comms.text:
@1 וּקְרָא לְמֹשֶׁה וּמַלֵיל יְיָ עִמֵיהּ מִמַשְׁכַּן זִמְנָא לְמֵימָר:
@2 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֱנַשׁ אֲרֵי יְקָרֵב מִנְכוֹן קוּרְבָּנָא קֳדָם יְיָ מִן בְּעִירָא מִן תּוֹרֵי וּמִן עָנָא תְּקָרְבוּן יָת קוּרְבַּנְכוֹן:
@3 אִם עֲלָתָא קוּרְבָּנֵיהּ מִן תּוֹרֵי דְכַר שְׁלִים יְקָרְבִנֵהּ לִתְרַע מַשְׁכַּן זִמְנָא יְקָרֵיב יָתֵיהּ לְרַעֲוָא לֵיהּ קֳדָם יְיָ:
@4 וְיִסְמוֹךְ יְדֵיהּ עַל רֵישׁ עֲלָתָא וְיִתְרְעֵי לֵיהּ לְכַפָּרָא עֲלוֹהִי:
@5 וְיִכּוֹס יָת בַּר תּוֹרֵי קֳדָם יְיָ וִיקָרְבוּן בְּנֵי אַהֲרֹן כָּהֲנַיָא יָת דְמָא וְיִזְרְקוּן יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר דִי בִתְרַע מַשְׁכַּן זִמְנָא:
@6 וְיַשְׁלַח יָת עֲלָתָא וִיפַלֵג יָתַהּ לְאֶבְרָהָא:
@7 וְיִתְּנוּן בְּנֵי אַהֲרֹן כַּהֲנָא אֶשָׁתָא עַל מַדְבְּחָא וִיסַדְרוּן אָעַיָא עַל אֶשָׁתָא:
@8 וִיסַדְרוּן בְּנֵי אַהֲרֹן כָּהֲנַיָא יָת אֶבְרַיָא יָת רֵישָׁא וְיָת תַּרְבָּא עַל אָעַיָא דִי עַל אֶשָׁתָא דִי עַל מַדְבְּחָא:
@9 וְגַוֵיהּ וּכְרָעוֹהִי יְחַלֵל בְּמַיָא וְיַסֵק כַּהֲנָא יָת כּוֹלָא לְמַדְבְּחָא עֲלָתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@10 וְאִם מִן עָנָא קוּרְבָּנֵיהּ מִן אִמְרַיָא אוֹ מִן בְּנֵי עִזַיָא לַעֲלָתָא דְכַר שְׁלִים יְקָרְבִינֵיהּ:
@11 וְיִכּוֹס יָתֵיהּ עַל צִדָא דְמַדְבְּחָא צִפּוּנָא קֳדָם יְיָ וְיִזְרְקוּן בְּנֵי אַהֲרֹן כָּהֲנַיָא יָת דְמֵיהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@12 וִיפַלֵג יָתֵיהּ לְאֶבְרוֹהִי וְיָת רֵישֵׁיהּ וְיָת תַּרְבֵּיהּ וְיַסְדַר כַּהֲנָא יָתְהוֹן עַל אָעַיָא דִי עַל אֶשָׁתָא דִי עַל מַדְבְּחָא:
@13 וְגַוָא וּכְרָעַיָא יְחַלֵל בְּמַיָא וִיקָרֵב כַּהֲנָא יָת כּוֹלָא וְיַסֵק לְמַדְבְּחָא עֲלָתָא הוּא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קָדָם יְיָ:
@14 וְאִם מִן עוֹפָא עֲלָתָא קוּרְבָּנֵיהּ קֳדָם יְיָ וִיקָרֵב מִן שַׁפְנִינַיָא אוֹ מִן בְּנֵי יוֹנָה יָת קוּרְבָּנֵיהּ:
@15 וִיקָרְבִינֵהּ כַּהֲנָא לְמַדְבְּחָא וְיִמְלוֹק יָת רֵישֵׁהּ וְיַסֵק לְמַדְבְּחָא וְיִתְמְצֵי דְמֵיהּ עַל כּוֹתֶל מַדְבְּחָא:
@16 וְיַעֲדֵי יָת זְפָקֵיהּ בְּאוּכְלֵיהּ וְיִרְמֵי יָתַהּ לִסְטַר מַדְבְּחָא קִידוּמָא לַאֲתַר דְמוֹשְׁדִין קִטְמָא:
@17 וִיפָרֵיק יָתֵיהּ בְּגַדְפוֹהִי לָא יַפְרֵישׁ וְיַסֵק יָתֵיהּ כַּהֲנָא לְמַדְבְּחָא עַל אָעַיָא דִי עַל אֶשָׁתָא עֲלָתָא הוּא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@18 וֶאֱנַשׁ אֲרֵי יְקָרֵב קוּרְבַּן מִנְחָתָא קֳדָם יְיָ סוּלְתָּא יְהֵי קוּרְבָּנֵיהּ וִירִיק עֲלָהּ מִשְׁחָא וְיִתֵּן עֲלָהּ לְבוֹנְתָּא:
@19 וְיַיְתִינָהּ לְוַת בְּנֵי אַהֲרֹן כַּהֲנַיָא וְיִקְמוֹץ מִתַּמָן מְלֵי קוּמְצְיהּ מִסִלְתָּהּ וּמִמִשְׁחָהּ עַל כָּל לְבוֹנְתָּהּ וְיַסֵק כַּהֲנָא יָת אַדְכַּרְתָּהּ לְמַדְבְּחָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@20 וּדְאִשְׁתָּאַר מִן מִנְחָתָא לְאַהֲרֹן וְלִבְנוֹהִי קוֹדֶשׁ קוּדְשִׁין מִקוּרְבָּנַיָא דַיְיָ:
@21 וַאֲרֵי תְקָרֵיב קוּרְבַּן מִנְחָתָא מַאֲפֵה תַנוּרָא סוּלְתָּא גְרִיצָן פַּטִירָן דְפִילָן בִּמְשָׁח וְאִסְפּוּגִין פַטִירִין דִמְשִׁיחִין בִּמְשָׁח:
@22 וְאִם מִנְחָתָא עַל מַסְרֵיתָא קוּרְבָּנָךְ סוּלְתָּא דְפִילָא בִמְשַׁח פַּטִיר תְּהֵי:
@23 בְּצַע יָתָהּ בִּיצוּעִין וּתְרִיק עֲלָהּ מִשְׁחָא מִנְחָתָא הִיא:
@24 וְאִם מִנְחָתָא דְרַדְתָּא קוּרְבָּנָךְ סוּלְתָּא בִּמְשַׁח תִּתְעֲבֵד:
@25 וְתַיְתֵי יַת מִנְחָתָא דִי יִתְעֲבֵיד מֵאִלֵין קֳדָם יְיָ וִיקַרְבִינָהּ לְוַת כַּהֲנָא וִיקַרְבִינָהּ לְמַדְבְּחָא:
@26 וְיַפְרֵישׁ כַּהֲנָא מִן מִנְחָתָא יָת אַדְכַּרְתָּהּ וְיַסֵק לְמַדְבְּחָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@27 וּדְאִשְׁתָּאַר מִן מִנְחָתָא לְאַהֲרֹן וְלִּבְנוֹהִי קוֹדֶשׁ קוּדְשִׁין מִקוּרְבָּנַיָא דַיְיָ:
@28 כָּל מִנְחָתָא דִי תְקַרְבוּן קֳדָם יְיָ לָא תִתְעֲבֵיד חֲמִיעַ אֲרֵי כָּל חֲמִיר וְכָל דְבַשׁ לָא תַסְקוּן מִנֵיהּ קוּרְבָּנָא קֳדָם יְיָ:
@29 קוּרְבַּן קַדְמַי תְּקָרְבוּן יַתְהוֹן קֳדָם יְיָ וּלְמַדְבְּחָא לָא יִתַּסְקוּן לְאִתְקַבָּלָא בְּרַעֲוָא:
@30 וְכָל קוּרְבַּן מִנְחָתָךְ בְּמִלְחָא תִּמְלַח וְלָא תְבַטֵל מְלַח קְיַם אֱלָהָךְ מֵעַל מִנְחָתָךְ עַל כָּל קוּרְבָּנָךְ תְּקָרֵב מִלְחָא:
@31 וְאִם תְּקָרֵב מִנְחַת בִּכּוּרִין קֳדָם יְיָ אָבִיב קְלֵי בְנוּר פֵּירוּכִין רַכִּיכָן תְּקָרֵיב יַת מִנְחַת בִּכּוּרָךְ:
@32 וְתִתֵּן עֲלַהּ מִשְׁחָא וּתְשַׁוֵי עֲלַהּ לְבוֹנְתָּא מִנְחָתָא הִיא:
@33 וְיַסֵק כַּהֲנָא יַת אַדְכַּרְתַּהּ מִפֵּרוּכַהּ וּמִמִשְׁחַהּ עַל כָּל לְבוֹנְתָּהּ קוּרְבָּנָא קֳדָם יְיָ:
@34 וְאִם נִכְסַת קוּדְשַׁיָא קוּרְבָּנֵיהּ אִם מִן תּוֹרֵי הוּא מְקָרֵב אִם דְכַר אִם נוּקְבָא שְׁלִים יְקָרְבִינֵיהּ קֳדָם יְיָ:
@35 וְיִסְמוֹךְ יְדֵיהּ עַל רֵישׁ קוּרְבָּנֵיהּ וְיִכְסִינֵיהּ בִּתְרַע מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן כַּהֲנַיָא יַת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@36 וִיקָרֵב מִנִכְסַת קוּדְשַׁיָא קוּרְבָּנָא קֳדָם יְיָ יַת תַּרְבָּא דְחָפֵי יַת גַוָא וְיַת כָּל תַּרְבָּא דִי עַל גַוָא:
@37 וְיַת תַּרְתֵּין כֻּלְיָן וְיַת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חַצְרָא דְעַל כַּבְדָא עַל כּוּלְיָתָא יַעֲדִינָהּ:
@38 וְיִסְקוּן יָתֵיהּ בְּנֵי אַהֲרֹן לְמַדְבְּחָא עַל עֲלָתָא דִי עַל אָעַיָא דִי עַל אֶשָׁתָא קוּרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@39 וְאִם מִן עָנָא קוּרְבָּנֵיהּ לְנִכְסַת קוּדְשַׁיָא קֳדָם יְיָ דְכַר אוֹ נוּקְבָא שְׁלִים יְקָרְבִינֵיהּ:
@40 אִם אִימַר הוּא מְקָרֵב יַת קוּרְבָּנֵיהּ וִיקָרֵיב יָתֵי קֳדָם יְיָ:
@41 וְיִסְמוֹךְ יַת יְדֵיהּ עַל רֵישׁ קוּרְבָּנֵיהּ וְיִכּוֹס יָתֵיהּ קֳדָם מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן יַת דְמֵיהּ עַל מַדְבְּחָא סְחוֹר םְחוֹר:
@42 וִיקָרֵב מִנִכְסַת קוּדְשַׁיָא קֻרְבָּנָא קֳדָם יְיָ תַּרְבֵּיהּ אֲלִיתָא שְׁלִמְתָּא לָקֳבֵל שֵׁזַרְתָּא יֶעְדִנַהּ וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא:
@43 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חַצְרָא דְעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@44 וְיַסְקִנֵהּ כַּהֲנָא לְמַדְבְּחָא לְחֵם קֻרְבָּנָא קֳדָם יְיָ:
@45 וְאִם מִן בְּנֵי עִזַיָא קֻרְבָּנֵהּ וִיקָרְבִנֵהּ קֳדָם יְיָ:
@46 וְיִסְמוֹךְ יָת יְדֵהּ עַל רֵישֵׁיהּ וְיִכּוֹס יָתֵהּ קֳדָם מַשְׁכַּן זִמְנָא וְיִזְרְקוּן בְּנֵי אַהֲרֹן יָת דְמֵהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@47 וִיקָרֵב מִנֵהּ קֻרְבָּנֵהּ קֻרְבָּן קֳדָם יְיָ יָת תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא:
@48 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חַצְרָא דִי עַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@49 וְיַםְקִנוּן כַּהֲנָא לְמַדְבְּחָא לְחֵם קֻרְבָּנָא לְאִתְקַבָּלָא בְּרַעֲוָא כָּל תַּרְבָּא קֳדָם יְיָ:
@50 קְיָם עָלָם לְדָרָתֵיכוֹן בְּכָל מוֹתְבָנֵיכוֹן כָּל תַּרְבָּא וְכָל דְמָא לָא תֵיכְלוּן:
@51 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@52 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר אֱנַשׁ אֲרֵי יֵחוֹב בְּשָׁלוּ מִכָּל פִּקוּדַיָא דַיְיָ דִי לָא כַשְׁרִין לְאִתְעֲבָדָא וְיַעְבֵּד מִן חָד מִ נְה וֹן:
@53 אִם כַּהֲנָא רַבָּא יֵיחוֹב לְחוֹבַת עַמָא וִיקָרֵב עַל חוֹבְתֵהּ דִי חָב תּוֹר בַּר תּוֹרֵי שְׁלִים קֳדָם יְיָ לְחַטָאתָא:
@54 וְיַיְתִי יָת תּוֹרָא לִתְרַע מַשְׁכַּן זִמְנָא לָקֳדָם יְיָ וְיִסְמוֹךְ יָת יְדֵיהּ עַל רֵישׁ תּוֹרָא וְיִכּוֹס יָת תּוֹרָא קֳדָם יְיָ:
@55 וְיִםַב כַּהֲנָא רַבָּא מִדְמָא דְתוֹרָא וְיָעֵל יָתֵהּ לְמַשְׁכַּן זִמְנָא:
@56 וְיִטְבּוֹל כַּהֲנָא יָת אֶצְבְּעֵהּ בִּדְמָא וְיַדִי מִן דְמָא שְׁבַע זִמְנִין קֳדָם יְיָ קֳדָם פָּרוּכְתָּא דְקוּדְשָׁא:
@57 וְיִתֵּן כַּהֲנָא מִן דְמָא עַל קַרְנַת מַדְבַּח קְטוֹרֶת בּוּסְמַיָא קֳדָם יְיָ דִי בְּמַשְׁכַּן זִמְנָא וְיָת כָּל דְמָא דְתוֹרָא יֵישׁוּד לִיסוֹדָא דְּמַדְבְּחָא דַעֲלָתָא דִי בִתְרַע מַשְׁכַּן זִ מְנָא:
@58 וְיָת כָּל תְּרַב תּוֹרָא דְחַטָאתָא יַפְרֵשׁ מִנֵהּ יָת תַּרְבָּא דְחָפֵי עַל גַוָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא:
@59 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חִצְרָא דְעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@60 כְּמָא דִי מִתַּפְרֵשׁ מִתּוֹר נִכְסַּת קוּדְשַׁיָא וְיַסֵקִנוּן כַּהֲנָא עַל מַדְבְּחָא דַעֲלָתָא:
@61 וְיָת מְשַׁךְ תּוֹרָא וְיָת כָּל בִּסְרֵהּ עַל רֵישֵׁיהּ וְעַל כְּרָעוֹהִי וְגַוֵהּ וְאוּכְלֵהּ:
@62 וְיַפֵּק יָת כָּל תּוֹרָא מִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְכֵי לַאֲתַר בֵּית מֵישַׁד קִטְמָא וְיוֹקִיד יָתֵהּ עַל אָעַיָא בְּאֶשָׁתָא עַל אֲתַר בֵּית מֵישַׁד קִטְמָא יִתּוֹקָד:
@63 וְאִם כָּל כְּנִשְׁתָּא דְיִשְׂרָאֵל יִשְׁתְּלוּן וִיהֵי מְכַסָא פִּתְגָמָא מֵעֵינֵי קְהָלָא וְיַעְבְדוּן חָד מִכָּל פִּקוּדַיָא דַיְיָ דִי לָא כָשְׁרִין לְאִתְעֲבָדָא וִיחוֹבוּן:
@64 וְתִתְיְדַע חוֹבְתָא דִי חָבוּ עֲלַהּ וִיקַרְבוּן קְהָלָא תּוֹר בַּר תּוֹרֵי לְחַטָּאתָא וְיַיְתוּן יָתֵהּ לָקֳדָם מַשְׁכַּן זִמְנָא:
@65 וְיִסְמְכוּן סָבֵי כְנִשְׁתָּא יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא קֳדָם יְיָ וְיִכּוֹס יָת תּוֹרָא קֳדָם יְיָ:
@66 וְיָעֵל כַּהֲנָא רַבָּא מִדְמָא דְתוֹרָא לְמַשְׁכַּן זִמְנָא:
@67 וְיִטְבּוֹל כַּהֲנָא אִצְבְּעֵהּ מִן דְמָא וְיַדִי שְׁבַע זִמְנִין קֳדָם יְיָ יָת קֳדָם פָּרֻכְתָּא:
@68 וּמִן דְמָא יִתֵּן עַל קַרְנַת מַדְבְּחָא דִי קֳדָם יְיָ דִי בְּמַשְׁכַּן זִמְנָא וְיָת כָּל דְמָא יֵשׁוֹד לִיסוֹדָא דְמַדְבְּחָא דַעֲלָתָא דִי בִתְרַע מַשְׁכַּן זִמְנָא:
@69 וְיָת כָּל תַּרְבֵּהּ יַפְרֵשׁ מִנֵהּ וְיַסֵק לְמַדְבְּחָא:
@70 וְיַעְבֵּד לְתוֹרָא כְּמָא דִי עֲבַד לְתוֹרָא דְחַטָאתָא כֵּן יַעְבֵּד לֵהּ וִיכַפֵּר עֲלֵיהוֹן כַּהֲנָא וְיִשְׁתְּבֵק לְהוֹן:
@71 וְיַפֵּק יָת תּוֹרָא לְמִבָּרָא לְמַשְׁרִיתָא וְאוֹקִיד יָתֵהּ כְּמָא דִי אוֹקִיד יָת תּוֹרָא קַדְמָאָה חַטַאת קְהָלָא הוּא:
@72 אִם רַבָּא יֵחוֹב וְיַעְבֵּד חַד מִכָּל פִּקוּדַיָא דַיְיָ אֱלָהֵיהּ דְלָא כַשְׁרִין לְאִתְעֲבָדָא בְּשָׁלוּ וְיֵחוֹב:
@73 אוֹ אִתְיְדַע לֵהּ חוֹבְתֵהּ דִי חַב בַּהּ וְיַיְתִי יָת קֻרְבָּנֵהּ צְפִיר בַּר עִזִין דְכַר שְׁלִים:
@74 וְיִסְמוֹךְ יְדֵהּ עַל רֵישָׁא דִצְפִירָא וְיִכּוֹס יָתֵהּ בַּאֲתַר דְיִכּוֹס יָת עֲלָתָא לָקֳדָם יְיָ חַטָאתָא הוּא:
@75 וְיִסַב כַּהֲנָא מִדְמָא דְחַטָּאתָא בְּאֶצְבְּעֵהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת דְמֵהּ יֵשׁוֹד לִיסוֹדָא לְמַדְבְּחָא דַעֲלָתָא:
@76 וְיָת כָּל תַּרְבֵּה יַסֵק לְמַדְבְּחָא כִּתְרַב נִכְסַת קוּדְשַׁיָּא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא מֵחוֹבְתֵהּ וְיִשְׁתְּבֵק לֵהּ:
@77 וְאִם אֱנַשׁ חַד יֵחוֹב בְּשָׁלוּ מֵעַמָא דְאַרְעָא בְּמֶעְבְּדַהּ חַד מִפִּקוּדַיָא דַיְיָ דְלָא כַשְׁרִין לְאִתְעְבָדָא וְיֵחוֹב:
@78 אוֹ אִתְיְדַע לֵהּ חוֹבְתֵהּ דִי חָב וְיַיְתִי קֻרְבָּנֵהּ צְפִירַת עִזִין שְׁלֶמְתָּא נְקוּבְתָא עַל חוֹבְתֵהּ דִי חָב:
@79 וְיִסְמוֹךְ יָת יְדֵהּ עַל רֵישׁ חַטָאתָא וְיִכּוֹס יָת חַטָאתָא בַּאֲתַר דַעֲלָתָא:
@80 וְיִסַב כַּהֲנָא מִדְמַהּ בְּאֶצְבְּעֵהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל דְמַהּ יֵשׁוֹד לִיסוֹדָא דְמַדְבְּחָא:
@81 וְיָת כָּל תַּרְבַּהּ יֶעְדֵי כְּמָא דִי מִתַּעְדָא תְרַב מֵעַל נִכְסַת קוּדְשַׁיָא וְיַסֵק כַּהֲנָא לְמַדְבְּחָא לְאִתְקַבָּלָא בְּרַעֲוָא קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי כַּהֲנָא וְיִשְׁתְּבֵק לֵהּ:
@82 וְאִם אִימַר יַיְתִי קֻרְבָּנֵהּ לְחַטָאתָא נֻקְבָא שְׁלֶמְתָּא יַיְתִנַהּ:
@83 וְיִסְמוֹךְ יַת יְדֵהּ עַל רֵישׁ חַטָאתָא וְיִכּוֹס יָתַהּ לְחַטָאתָא בְּאַתְרָא דִי יִכּוֹס יַת עֲלָתָא:
@84 וְיִסַב כַּהֲנָא מִדְמָא דְחַטָאתָא בְּאֶצְבְּעֵהּ וְיִתֵּן עַל קַרְנַת מַדְבְּחָא דַעֲלָתָא וְיָת כָּל דְמַהּ יֵשׁוֹד לִיסוֹדָא דְ מַ דְבְּחָא:
@85 וְיָת כָּל תַּרְבַּהּ יֶעְדֵי כְּמָא דִי מִתַּעְדָא תְרַב אִמְרָא מִנִכְסַת קוּדְשַׁיָא וְיַסֵק כַּהֲנָא יַתְהוֹן לְמַדְבְּחָא עַל קֻרְבָּנַיָא דַיְיָ וִיכַפֵּר עֲלוֹהִי כַהֲנָא עַל חוֹבְתֵהּ דִי חָב וְיִשְׁתְּבֵק לֵהּ:
@86 וֶאֵנַשׁ אֲרֵי יֵחוֹב וְיִשְׁמַע קַל מוֹמֵי וְהוּא סָהִיד אוֹ חֲזָא אוֹ יְדָע אִם לָא יְחַוִי וִיקַבֵּל חוֹבֵהּ:
@87 אוֹ אֱנַשׁ דִי יִקְרַב בְּכָל מִדַעַם מְסָאָב אוֹ בְּנִבְלַת חַיְתָא מְסָאָבָא אוֹ בְּנִבְלַת בְּעִירָא מְסָאָבָא אוֹ בְּנִבְלַת רִחֲשָׁא מְסָאָב וִיהֵי מְכַסָא מִנֵהּ וְהוּא מְסָאָב וְחָב:
@88 אוֹ אֲרֵי יִקְרַב בְּסוֹאֲבַת אֱנָשָׁא לְכָל סוֹבְתֵהּ דִי יִסְתָּאַב בַּהּ וִיהֵי מְכַסָא מִנֵהּ וְהוּא יְדַע וְחָב:
@89 אוֹ אֱנַשׁ אֲרֵי יְקַיֵם לְפָרָשָׁא בְסִפְוָן לְאַבְאָשָׁא אוֹ לְאוֹטָבָא לְכֹל דִי יְפָרֵשׁ אֱנָשָׁא בְּקִיוּם וִיהֵי מְכַסָא מִנֵהּ וְהוּא יָדַע וְחָב לַחֲדָא מֵאִלֵין:
@90 וִיהֵי אֲרֵי יֵחוֹב לַחֲדָא מֵאִלֵין וִיוַדִי דִי חָב עֲלַהּ:
@91 וְיַיְתִי יָת אַשְׁמֵהּ קֳדָם יְיָ עַל חוֹבְתֵהּ דִי חָב נְקוּבְתָא מִן עָנָא אִמְרָתָא אוֹ צְפִירַת עִזִין לְחַטָאתָא וִיכַפֵּר עֲלוֹהִי כַהֲנָא מֵחוֹבְתֵהּ:
@92 וְאִם לָא תִמְטֵי יְדֵהּ כְּמִסַת שֵׂיתָא וְיַיְתִי יָת חוֹבְתֵהּ דִי חָב תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה קֳדָם יְיָ חַד לְחַטָאתָא וְחַד לַעֲלָתָא:
@93 וְיַיְתִי יָתְהוֹן לְוָת כַּהֲנָא וִיקָרֵב יָת דִי לְחַטָאתָא קַדְמֵיתָא וְיִמְלוֹק יָת רֵישֵׁהּ מִלְקָבֵל קְדָלֵהּ וְלָא יַפְרֵשׁ:
@94 וְיַדִי מִדְמָא דְחַטָּאתָא עַל כֹּתֶל מַדְבְּחָא וּדְאִשְׁתָּאַר בִּדְמָא יִתִּמְצֵי לִיסוֹדָא דְמַדְבְּחָא חַטָאתָא הוּא:
@95 וְיָת תִּנְיָנָא יַעְבֵּד עֲלָתָא כִּדְחָזֵי וִיכַפֵּר עֲלוֹהִי כַהֲנָא מֵחוֹבְתֵהּ דִי חָב וְיִשְׁתְּבֵק לֵהּ:
@96 וְאִם לָא תַדְבֵּק יְדֵהּ לְתַרְתֵּין שַׁפְנִינִין אוֹ לִתְרֵין בְּנֵי יוֹנָה וְיַיְתִי יָת קֻרְבָּנֵהּ דִי חָב חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא לְחַטָּאתָא לָא יְשַׁוִי עֲלַהּ מִשְׁחָא וְלָא יִתֵּן עֲלַהּ לְבֻנְתָּא אֲרֵי חַטָאתָא הִיא:
@97 וְיַיְתִנַהּ לְוַת כַּהֲנָא וְיִקְמוֹץ כַּהֲנָא מִנַהּ מְלֵי קֻמְצֵהּ יָת אִדְכַּרְתַּהּ וְיַסֵק לְמַדְבְּחָא עַל קֻרְבָּנַיָא דַיְיָ חַטָאתָא הִיא:
@98 וִיכַפֵּר עֲלוֹהִי כַהֲנָא עַל חוֹבְתֵהּ דִי חָב מֵחֲדָא מֵאִלֵין וְיִשְׁתְּבֵק לֵהּ וּתְהֵי לְכַהֲנָא כְּמִנְחָתָא:
@99 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@100 אֱנַשׁ אֲרֵי יְשַׁקַר שְׁקַר וְיֵחוֹב בְּשָׁלוּ מִקוּדְשַׁיָא דַיְיָ וְיַיְתִי יָת אַשְׁמֵהּ קֳדָם יְיָ דְכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵהּ כְּסַף סִלְעִין בְּסִלְעֵי קוּדְשָׁא לַאֲשָׁמָא:
@101 וְיָת דִי חָב מִן קוּדְשָׁא יְשַׁלֵם וְיָת חֻמְשֵׁהּ יוֹסֵף עֲלוֹהִי וְיִתֵּן יָתֵהּ לְכַהֲנָא וְכַהֲנָא יְכַפֵּר עֲלוֹהִי בְּדִכְרָא דַאֲשָׁמָא וְיִשְׁתְּבֵק לֵהּ:
@102 וְאִם אֱנַשׁ אֲרֵי יֵחוֹב וְיַעְבֵּד חֲדָא מִכָּל פִּקוּדַיָא דַיְיָ דִי לָא כָשְׁרִין לְאִתְעֲבָדָא וְלָא יָדַע וְיֵחוֹב וִיקַבֵּל חוֹבֵהּ:
@103 וְיַיְתִי דְכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵהּ לַאֲשָׁמָא לְוָת כַּהֲנָא וִיכַפֵּר עֲלוֹהִי כַהֲנָא עַל שָׁלוּתֵהּ דְאִשְׁתְּלִי וְהוּא לָא יָדַע וְיִשְׁתְּבֵק לֵהּ:
@104 אֲשָׁמָא הוּא עַל חוֹבְתֵהּ דְהוּא חָב אֲשָׁמָא יְקָרֵב קֳדָם יְיָ:
@105 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@106 אֱנַשׁ אֲרֵי יֵחוֹב וִישַׁקַר שְׁקַר קֳדָם יְיָ וִיכַדֵב בְּחַבְרֵהּ בְּפִקְדוֹנָא אוֹ בְשֻׁתָּפוּת יְדָא אוֹ בִגְזֵלָא אוֹ אַנִיס יָת חַבְרֵהּ:
@107 אוֹ אַשְׁכַּח אֲבֶדְתָּא וִיכַדֵב בַּהּ וְאִשְׁתְּבַע עַל שִׁקְרָא עַל חֲדָא מִכֹּל דִי יַעְבֵּד אֱנָשָׁא לְמֵיחַב בְּהֵן:
@108 וִיהֵי אֲרֵי יֶחְטֵי וְיֵחוֹב וְיָתֵב יָת גְזֵלָא דִי גְזַל אוֹ יָת עֻשְׁקָא דִי עֲשַׁק אוֹ יָת פִּקְדוֹנָא דִי אִתְפָּקַד לְוָתֵהּ אוֹ יָת אֲבֶדְתָּא דִי אַשְׁכַּח:
@109 אוֹ מִכֹּל דִי יִשְׁתְּבַע עֲלוֹהִי לְשִׁקְרָא וִישַׁלֵם יָתֵהּ בְּרֵישֵׁיהּ וְחֻמְשֵׁהּ יוֹסֵף עֲלוֹהִי לְדִי הוּא דִילֵהּ יִתְּנִנֵהּ בְּיוֹמָא דְחוֹבְתֵהּ:
@110 וְיָת אַשָׁמֵיהּ יַיְתִי לָקֳדָם יְיָ דְכַר שְׁלִים מִן עָנָא בְּפֻרְסָנֵהּ לַאֲשָׁמָא לְוָת כַּהֲנָא:
@111 וִיכַפֵּר עֲלוֹהִי כַהֲנָא קֳדָם יְיָ וְיִשְׁתְּבֵק לֵהּ עַל חֲדָא מִכֹּל דִי יַעְבֵּד לְמֵיחַב בַהּ: פפפ:
@112 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@113 פַּקֵד יָת אַהֲרֹן וְיָת בְּנוֹהִי לְמֵימָר דָא אוֹרַיְתָא דַעֲלָתָא הִיא עֲלָתָא דְמִתּוֹקְדָא עַל מַדְבְּחָא כָל לֵילְיָא עַד צַפְרָא וְאֶשָׁתָא דְמַדְבְּחָא תְּהֵא יָקְדָא בֵהּ:
@114 וְיַלְבֵּשׁ כַּהֲנָא לְבוּשִׁין דְבוּץ וּמִכְנְסִין דְבוּץ יַלְבֵּשׁ עַל בִּסְרֵהּ וְיַפְרֵשׁ יָת קִטְמָא דִי תֵיכוּל אֶשָׁתָא יָת עֲלָתָא עַל מַדְבְּחָא וִישַׁוִנֵהּ בִּסְטַּר מַדְבְּחָא:
@115 וְיַשְׁלַח יָת לְבוּשׁוֹהִי וְיִלְבַּשׁ לְבוּשִׁין אָחֳרָנִין וְיַפֵּק יָת קִטְמָא לְמִבָּרָא לְמַשְׁרִיתָא לַאֲתַר דְכֵי:
@116 וְאֶשָׁתָא עַל מַדְבְּחָא תְהֵי יָקְדָא בֵהּ לָא תִטְּפֵי וְיַבְעַר עֲלַהּ כַּהֲנָא אָעַיָא בִּצְפַר בִּצְפָר וְיַסְדַר עֲלַהּ עֲלָתָא וְיַסֵק עֲלַהּ תַּרְבֵּי נִכְסַת קוּדְשַׁיָא:
@117 אֶשָׁתָא תְּדִירָא תְּהֵי יָקְדָא עַל מַדְבְּחָא לָא תִטְפֵי:
@118 וְדָא אוֹרַיְתָא דְמִנְחָתָא דִיקָרְבוּן יָתַהּ בְּנֵי אַהֲרֹן קֳדָם יְיָ לָקֳדָם מַדְבְּחָא:
@119 וְיַפְרֵשׁ מִנֵהּ בְּקֻמְצֵהּ מִסֻלְתָּא דְמִנְחָתָא וּמִמִשְׁחַהּ וְיָת כָּל לְבוּנְתָּא דִי עַל מִנְחָתָא וְיַסֵק לְמַדְבְּחָא לְאִתְקַבָּלָא בְרַעֲוָא אַדְכַּרְתָּא קֳדָם יְיָ:
@120 וּדְאִשְׁתָּאַר מִנַהּ יֵכְלוּן אַהֲרֹן וּבְנוֹהִי פַּטִיר תִּתְאַכֵל בַּאֲתַר קַדִּישׁ בְּדָרַת מַשְׁכַּן זִמְנָא יֵכְלֻנַהּ:
@121 לָא תִתְאֲפֵי חֲמִיעַ חָלָקְהוֹן יְהָבִית יָתַהּ מִקֻרְבָּנָי קֹדֶשׁ קוּדְשִׁין הִיא כְּחַטָאתָא וְכַאֲשָׁמָא:
@122 כָּל דְכוּרָא בִּבְנֵי אַהֲרֹן יֵכְלֻנַהּ קְיָם עָלָם לְדָרָתֵיכוֹן מִקֻרָבָּנַיָא דַיְיָ כֹּל דְיִקְרַב בְּהוֹן יִתְקַדָּשׁ:
@123 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@124 דֵין קֻרְבַּן אַהֲרֹן וּבְנוֹהִי דִי יְקָרְבוּן קֳדָם יְיָ בְּיוֹמָא דְרַבִּיאוּ יָתֵהּ חַד מִן עַסְרָא בִתְלַת סְאִין סֻלְתָּא מִנְחָתָא תְּדִירָא פַּלְגוּתַהּ בְּצַפְרָא וּפַלְגוּתַהּ בְּרַמְשָׁא:
@125 עַל מַסְרֵיתָא בִּמְשַׁח תִּתְעֲבֵד רְבִיכָא תַיְתִנַהּ תּוּפִינֵי מִנְחַת בִּצוּעִין תְּקָרֵב לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@126 וְכַהֲנָא דִמְרַבָּא תְחוֹתוֹהִי מִבְּנוֹהִי יַעְבֵּד יָתַהּ קְיָם עָלָם קֳדָם יְיָ גְמִיר תִּתַּסָק:
@127 וְכָל מִנְחָתָא דְכַהֲנָא גְמִיר תְּהֵי לָא תִתְאֲכֵל:
@128 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@129 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי לְמֵימָר דָא אוֹרַיְתָא דְחַטָאתָא בַּאֲתַר דִי תִתְנְכֵס עֲלָתָא תִּתְנְכֵס חַטָאתָא קֳדָם יְיָ קֹדֶשׁ קוּדְשִׁין הִיא:
@130 כַּהֲנָא דִמְכַפֵּר בִּדְמַהּ יֵיכְלִנַהּ בַּאֲתַר קַדִישׁ תִּתְאֲכֵל בְּדָרַת מַשְׁכַּן זִמְנָא:
@131 כֹּל דִי יִקְרַב בְּבִסְרַהּ יִתְקַדַשׁ וְדִי יַדִי מִדְמַהּ עַל לְבוּשׁ דִי יַדִי עֲלַהּ תִּתְחַוָר בַּאֲתַר קַדִישׁ:
@132 וּמָן דַחֲסַף דִי תִתְבַּשֵׁל בֵּהּ יִתָּבָר וְאִם בְּמָנָא דִנְחָשָׁא תִּתְבַּשֵׁל וְיִתְמְרֵק וְיִשְׁתַּטֵף בְּמַיָא:
@133 כָּל דְכוּרָא בְּכַהֲנַיָא יֵכוּל יָתַהּ קֹדֶשׁ קוּדְשִׁין הִיא:
@134 וְכָל חַטָאתָא דִי יִתָּעַלּ מִדְמַהּ לְמַשְׁכַּן זִמְנָא לְכַפָּרָא בְקוּדְשָׁא לָא תִתְאֲכֵל בְּנוּרָא תִּתּוֹקָד:
@135 וְדָא אוֹרַיְתָא דַאֲשָׁמָא קֹדֶשׁ קוּדְשִׁין הוּא:
@136 בְּאַתְרָא דִי יִכְּסוּן יָת עֲלָתָא יִכְּסוּן יָת אֲשָׁמָא וְיָת דְמֵהּ יִזְרַק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@137 וְיָת כָּל תַּרְבֵּהּ יַפְרֵשׁ מִנֵהּ יָת אֲלִיתָא וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא:
@138 וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן דִי עַל גִסְסַיָא וְיָת חִצְרָא דְעַל כַּבְדָא עַל כָּלְיֵתָא יֶעְדִנַהּ:
@139 וְיַסֵיק יָתְהוֹן כַּהֲנָא לְמַדְבְּחָא קוּרְבָּנָא קֳדָם יְיָ אֲשָׁמָא הוּא:
@140 כָּל דְכוּרָא בְּכַהֲנַיָא יֵיכְלִנֵהּ בַּאֲתַר קַדִישׁ יִתְאֲכָל קוֹדֶשׁ קוּדְשִׁין הוּא:
@141 כְּחַטָאתָא כַּאֲשָׁמָא אוֹרַיְתָא חֲדָא לְהוֹן כַּהֲנָא דִי יְכַפֵּר בֵּהּ דִילֵהּ יְהֵי:
@142 וְכַהֲנָא דִמְקָרֵב יַת עֲלַת גְבַר מְשַׁךְ עֲלָתָא דִי יְקָרֵב לְכַהֲנָא דִילֵהּ יְהֵי:
@143 וְכָל מִנְחָתָא דִי תִתְאֲפֵי בְּתַנוּרָא וְכָל דְתִתְעֲבֵד בְּרִדְתָּא וְעַל מַסְרֵיתָא לְכַהֲנָא דִמְקָרֵב יָתַהּ דִילֵהּ תְּהֵי:
@144 וְכָל מִנְחָתָא דְפִילָא בִמְשַׁח וּדְלָא פִילָא לְכָל בְּנֵי אַהֲרֹן תְּהֵי גְבַר כַּאָחוֹהִי:
@145 וְדָא אוֹרַיְתָא דְנִכְסַת קוּדְשַׁיָא דִי יְקָרֵב קֳדָם יְיָ:
@146 אִם עַל תּוֹדְתָא יְקָרְבִנֵהּ וִיקָרֵב עַל נִכְסַת תּוֹדְתָא גְרִיצָן פַּטִירָן דְפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִירִין דִּמְשִׁיחִין בִּמְשָׁח וְסוּלְתָּא רְבִיכָא גְרִיצָן דְפִילָן בִּמְשָׁח:
@147 עַל גְּרִיצָן דִלְחֵם חָמִיעַ יְקָרֵב קוּרְבָּנֵיהּ עַל נִכְסַת תּוֹדַת קוּדְשׁוֹהִי:
@148 וִיקָרֵב מִנֵהּ חַד מִכָּל קוּרְבַּן אַפְרָשׁוּתָא קֳדָם יְיָ לְכַהֲנָא דְיִזְרַק יָת דַם נִכְסַת קוּדְשַׁיָא דִילֵהּ יְהֵי:
@149 וּבְשַׂר נִכְסַת תּוֹדַת קוּדְשׁוֹהִי בְּיוֹם קֻרְבָּנֵהּ יִתְאֲכֵל לָא יַצְנַע מִנֵהּ עַד צַפְרָא:
@150 וְאִם נִדְרָא אוֹ נְדַבְתָּא נִכְסַת קֻרְבָּנֵהּ בְּיוֹמָא דִי יְקָרֵב יָת נִכְסְתֵיהּ יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר מִנֵהּ יִתְאֲכֵלּ:
@151 וּדְאִשְׁתָּאַר מִבְּסַר נִכְסָתָא בְּיוֹמָא תְּלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@152 וְאִם אִתְאֲכָלָא יִתְאֲכֵל מִבְּסַר נִכְסַת קוּדְשׁוֹהִי בְּיוֹמָא תְּלִיתָאָה לָא יְהֵי לְרַעֲוָא דִמְקָרֵב יָתֵהּ לָא יִתְחַשֵׁב לֵהּ מְרָחָק יְהֵי וֶאֱנַשׁ דְתֵכוּל מִנֵהּ חוֹבֵהּ יְקַבֵּל:
@153 וּבְסַר קוּדְשָׁא דִי יִקְרַב בְּכָל מְסָאָב לָא יִתְאֲכֵל בְּנוּרָא יִתּוֹקָד וּבְסַר קוּדְשָׁא כָּל דִי דְכֵי לְקוּדְשָׁא יֵיכוּל בְּסַר קוּדְשָׁא:
@154 וֶאֱנַשׁ דִי תֵכוּל בִּסְרָא מִנִכְסַת קוּדְשַׁיָא דִי קֳדָם יְיָ וְסוֹבְתֵהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַּהּ:
@155 וֶאֱנַשׁ אֲרֵי תִקְרַב בְּכָל מְסָאָב בְסוֹאֲבַת אֱנָשָׁא אוֹ בִּבְעִירָא מְסָאֲבָא אוֹ בְּכָל שִׁקְצָא מְסָאָב וְיֵיכוּל מִבְּסַר נִכְסַת קוּדְשַׁיָא דִי קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַּהּ:
@156 וּמַלֵיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@157 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר כָּל תְּרַב תּוֹר וְאִמַר וְעִזָא לָא תֵיכְלוּן:
@158 וּתְרַב נְבִילָא וּתְרַב תְּבִירָא יִתְעֲבֵד לְכָל עִבִדְתָּא וּמֵיכַל לָא תֵיכְלוּנֵהּ:
@159 אֲרֵי כָל דְיֵכוּל תַּרְבָּא מִן בְּעִירָא דִי יִקָרְבוּן מִנַהּ קוּרְבָּנָא קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֱנָשָׁא דִי תֵיכוּל מֵעַמַּהּ:
@160 וְכָל דְמָא לָא תֵיכְלוּן בְּכֹל מוֹתְבָנֵיכוֹן דְעוֹפָא וְדִבְעִירָא:
@161 כָּל אֱנָשָׁא דִי תֵיכוּל כָּל דְמָא וְיִשְׁתֵּיצֵי אֱנָשָׁא הַהוּא מֵעַמַהּ:
@162 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@163 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר דִמְקָרֵב יָת נִכְסַת קוּדְשׁוֹהִי קֳדָם יְיָ יַיְתִי יָת קֻרְבָּנֵהּ לָקֳדָם יְיָ מִנִכְסַת קוּדְשׁוֹהִי:
@164 יְדוֹהִי תַיְתוּן יָת קֻרְבָּנַיָא דַיְיָ יָת תַּרְבָּא עַל חַדְיָא יַיְתִנֵהּ יָת חֶדְיָא לַאֲרָמָא יָתֵהּ אֲרוּמָא קֳדָם יְיָ:
@165 וְיַסֵק כַּהֲנָא יָת תַּרְבָּא לְמַדְבְּחָא וִיהֵי חֶדְיָא לְאַהֲרֹן וְלִבְנוֹהִי:
@166 וְיָת שׁוֹקָא דְיַמִינָא תִּתְּנוּן אַפְרָשׁוּתָא לְכַהֲנָא מִנִכְסַת קוּדְשֵׁיכוֹן:
@167 דִמְקָרֵב יָת דָם נִכְסַת קוּדְשַׁיָא וְיָת תַּרְבָּא מִבְּנֵי אַהֲרֹן דִילֵהּ תְּהֵי שׁוֹקָא דְיַמִינָא לָחֳלָק:
@168 אֲרֵי יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא נְסֵבִית מִן בְּנֵי יִשְׂרָאֵל מִנִכְסַת קוּדְשֵׁיהוֹן וִיהָבִית יָתְהוֹן לְאַהֲרֹן כַּהֲנָא וְלִבְנוֹהִי לִקְיָם עָלָם מִן בְּנֵי יִשְׂרָאֵל:
@169 דָא רְבוּת אַהֲרֹן וּרְבוּת בְּנוֹהִי מִקוּרְבָּנַיָא דַיְיָ בְּיוֹמָא דְקָרֵב יָתְהוֹן לְשַׁמָשָׁא קֳדָם יְיָ:
@170 דִי פַקִיד יְיָ לְמִתַּן לְהוֹן בְּיוֹמָא דְרַבִּי יָתְהוֹן מִן בְּנֵי יִשְׂרָאֵל קְיָם עָלָם לְדָרֵיהוֹן:
@171 דָא אוֹרַיְתָא לַעֲלָתָא לְמִנְחָתָא וּלְחַטָּאתָא וְלַאֲשָׁמָא וּלְקוּרְבָּנַיָא וּלְנִכְסַת קוּדְשַׁיָא:
@172 דִי פַקִיד יְיָ יָת מֹשֶׁה בְּטוּרָא דְסִינָי בְּיוֹמָא דְפַקְדֵהּ יָת בְּנֵי יִשְׂרָאֵל לְקָרָבָא יָת קֻרְבָּנְהוֹן קֳדָם יְיָ בְּמַדְבְּרָא דְסִינָי:
@173 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@174 קָרֵב יָת אַהֲרֹן וְיָת בְּנוֹהִי עִמֵהּ וְיָת לְבוּשַׁיָא וְיָת מִשְׁחָא דִרְבוּתָא וְיָת תּוֹרָא דְחַטָאתָא וְיָת תְּרֵין דִכְרִין וְיָת סַלָא דְפַטִירַיָא:
@175 וְיָת כָּל כְּנִשְׁתָּא כְּנֵשׁ לִתְרַע מַשְׁכַּן זִמְנָא:
@176 וַעֲבַד מֹשֶׁה כְּמָא דִי פַקִיד יְיָ יָתֵהּ וְאִתְכְּנִשַׁת כְּנִשְׁתָּא לִתְרַע מַשְׁכַּן זִמְנָא:
@177 וַאֲמַר מֹשֶׁה לִכְנִשְׁתָּא דֵין פִּתְגָמָא דִי פַקִיד יְיָ לְמֶעְבָּד:
@178 וְקָרִיב מֹשֶׁה יָת אַהֲרֹן וְיָת בְּנוֹהִי וְאַסְחֵי יָתְהוֹן בְּמַיָא:
@179 וִיהַב עֲלוֹהִי יָת כִּתּוּנָא וְזָרֵז יָתֵהּ בְּהֶמְיָנָא וְאַלְבֵּשׁ יָתֵהּ יָת מְעִילָא וִיהַב עֲלוֹהִי יָת אֵפוֹדָא וְזָרֵז יָתֵהּ בְּהֶמְיַן אֵפוֹדָא וְאַתְקֵן לֵהּ בֵּהּ:
@180 וְשַׁוִי עֲלוֹהִי יָת חוּשְׁנָא וִיהַב בְּחוּשְׁנָא יָת אוּרַיָא וְיָת תֻּמַיָא:
@181 וְשַׁוִי יָת מִצְנַפְתָּא עַל רֵישֵׁיהּ וְשַׁוִי עַל מִצְנֶפְתָּא לָקֳבֵיל אַפּוֹהִי יָת צִיצָא דְדַהֲבָא כְּלִילָא דְקוּדְשָׁא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@182 וּנְסִיב מֹשֶׁה יָתּ מִשְׁחָא דִרְבוּתָא וְרַבִּי יָת מַשְׁכְּנָא וְיָת כָּל דִי בֵהּ וְקַדִישׁ יָתְהוֹן:
@183 וְאַדִי מִנֵהּ עַל מַדְבְּחָא שְׁבַע זִמְנִין וְרַבִּי יָת מַדְבְּחָא וְיָת כָּל מָנוֹהִי וְיָת כִּיוֹרָא וְיָת בְּסִיסֵהּ לְקַדָשׁוּתְהוֹן:
@184 וַאֲרֵיק מִמִשְׁחָא דִרְבוּתָא עַל רֵישָׁא דְאַהֲרֹן וְרַבִּי יָתֵהּ לְקַדָשׁוּתֵהּ:
@185 וְקָרִיב מֹשֶׁה יָת בְּנֵי אַהֲרֹן וְאַלְבֵּשִׁנוּן כִּתּוּנִין וְזָרֵז יָתְהוֹן הֶמְיָנִין וְאַתְקֵן לְהוֹן כּוֹבָעִין כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@186 וְקָרֵב יָת תּוֹרָא דְחַטָאתָא וּסְמַךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא דְחַטָאתָא:
@187 וּנְכֵס וּנְסִיב מֹשֶׁה יָת דְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר בְּאֶצְבְּעֵהּ וְדַכִּי יָת מַדְבְּחָא וְיָת דְמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא וְקַדְשֵׁהּ לְכַפָּרָא עֲלוֹהִי:
@188 וּנְסִיב יָת כָּל תַּרְבָּא דִי עַל גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְאַסֵק מֹשֶׁה לְמַדְבְּחָא:
@189 וְיָת תּוֹרָא וְיָת מַשְׁכֵהּ וְיָת בִּסְרֵהּ וְיָת אָכְלֵהּ אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@190 וְקָרִיב יָת דִכְרָא דַעֲלָתָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@191 וּנְכֵס וּזְרַק מֹשֶׁה יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@192 וְיָת דִכְרָא פַּלֵג לְאֶבְרוֹהִי וְאַסֵק מֹשֶׁה יָת רֵישָׁא וְיָת אֶבְרַיָא וְיָת תַּרְבָּא:
@193 וְיָת גַוָא וְיָת כְּרָעַיָא חַלִיל בְּמַיָא וְאַסֵק מֹשֶׁה יָת כָּל דִכְרָא לְמַדְבְּחָא עֲלָתָא הוּא לְאִתְקַבָּלָא בְרַעִוָא קוּרְבָּנָא הוּא קֳדָם יְיָ כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@194 וְקָרִיב יָת דִכְרָא תִנְיָנָא דְכַר קוּרְבָּנַיָא וּסְמָכוּ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@195 וּנְכֵס וּנְסִיב מֹשֶׁה מִן דְמָא וִיהַב עַל רוּם אוּדְנָא דְאַהֲרֹן דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא:
@196 וְקָרֵיב יָת בְּנֵי אַהֲרֹן וִיהַב מֹשֶׁה מִן דְמָא עַל רוּם אוּדְנֵהוֹן דְיַמִינָא וְעַל אִלְיוֹן אוּדְנֵהוֹן דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵיהוֹן דְיַמִינָא וּזְרַק מֹשֶׁה יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@197 וּנְסִיב יָת תַּרְבָּא וְיָת אֲלִיתָא וְיָת כָּל תַּרְבָּא דִי עַל גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבְּהֶן וְיָת שׁוֹקָא דְיַמִינָא:
@198 וּמִסַלָא דְפַטִירַיָא דִי קֳדָם יְיָ נְסִיב גְרִצְתָּא פַטִירָא חֲדָא וּגְרִיצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד וְשַׁוִי עַל תַּרְבַּיָא וְעַל שׁוֹקָא דְיַמִינָא:
@199 וִיהַב יָת כֹּלָא עַל יְדֵי אַהֲרֹן וְעַל יְדֵי בְנוֹהִי וַאֲרֵים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@200 וּנְסִיב מֹשֶׁה יָתְהוֹן מֵעַל יְדֵיהוֹן וְאַסֵק לְמַדְבְּחָא עַל עֲלָתָא קוּרְבָּנַיָא אִנוּן לְאִתְקַבָּלָא בְרַעֲוָא קוּרְבָּנָא הוּא קֳדָם יְיָ:
@201 וּנְסִיב מֹשֶׁה יָת חֶדְיָא וַאֲרִימֵהּ אֲרָמָא קֳדָם יְיָ מִדְכַר קוּרְבָּנַיָא לְמֹשֶׁה הֲוָה לָחֳלָק כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@202 וּנְסִיב מֹשֶׁה מִמִשְׁחָא דִרְבוּתָא וּמִן דְמָא דִי עַל מַדְבְּחָא וְאַדִי עַל אַהֲרֹן עַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵהּ וְקַדִישׁ יָת אַהֲרֹן יָת לְבוּשׁוֹהִי וְיָת בְּנוֹהִי וְיָת לְבוּשֵׁי בְנוֹהִי עִמֵהּ:
@203 וַאֲמַר מֹשֶׁה לְאַהֲרֹן וְלִבְנוֹהִי בַּשִׁילוּ יָת בִּסְרָא בִּתְרַע מַשְׁכַּן זִמְנָא וְתַמָן תֵּיכְלוּן יָתֵהּ וְיָת לַחְמָא דִי בְּסַל קוּרְבָּנַיָא כְּמָא דִי פַקֵדִית לְמֵימָר אַהֲרֹן וּבְנוֹהִי יֵיכְלוּנֵהּ:
@204 וּדְאִשְׁתָּאַר בְּבִשְׂרָא וּבְלַחְמָא בְּנוּרָא תּוֹקְדוּן:
@205 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְּקוּן שִׁבְעָא יוֹמִין עַד יוֹם מִשְׁלַם יוֹמֵי קוּרְבָּנֵיכוֹן אֲרֵי שִׁבְעָא יוֹמִין יְקָרֵב יָת קֻרְבָּנֵיכוֹן:
@206 כְּמָא דִי עֲבַד בְּיוֹמָא הָדֵין פָּקִיד יְיָ לְמֶעְבַּד לְכַפָּרָא עֲלֵיכוֹן:
@207 וּבִתְרַע מַשְׁכַּן זִמְנָא תֵּיתְבוּן יְמָם וְלֵילֵי שִׁבְעָא יוֹמִין וְתִטְרוּן יָת מַטְרַת מֵימְרָא דַיְיָ וְלָא תְמוּתוּן אֲרֵי כֵן אִתְפַּקָדִית:
@208 וַעֲבַד אַהֲרֹן וּבְנוֹהִי יָת כָּל פִּתְגָמַיָא דִי פַקִיד יְיָ בִּידָא דְמֹשֶׁה: פפפ:
@209 וַהֲוָה בְּיוֹמָא תְמִינָאָה קְרָא מֹשֶׁה לְאַהֲרֹן וְלִבְנוֹהִי וּלְסָבֵי יִשְׂרָאֵל:
@210 וַאֲמַר לְאַהֲרֹן סַב לָךְ עֵגֶל בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא שַׁלְמִין וְקָרֵב קֳדָם יְיָ:
@211 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵל לְמֵימָר סִבוּ צְפִיר בַּר עִזִין לְחַטָאתָא וְעֵגֶל וְאִמָר בְּנֵי שְׁנָא שַׁלְמִין לַעֲלָתָא:
@212 וְתוֹר וּדְכַר לְנִכְסַת קוּדְשַׁיָא לְדַבָּחָא קֳדָם יְיָ וּמִנְחָתָא דְפִילָא בִמְשָׁח אֲרֵי יוֹמָא דֵין יְקָרָא דַיְיָ מִתְגְלִי לְכוֹן:
@213 וּנְסִיבוּ יָת דִי פַקִיד מֹשֶׁה לָקֳדָם מַשְׁכַּן זִמְנָא וּקְרִיבוּ כָּל כְּנִישְׁתָּא וְקָמוּ קֳדָם יְיָ:
@214 וַאֲמַר מֹשֶׁה דֵין פִּתְגָמָא דִי פַקִיד יְיָ תַּעְבְּדוּן וְיִתְגְלִי לְכוֹן יְקָרָא דַיְיָ:
@215 וַאֲמַר מֹשֶׁה לְאַהֲרֹן קְרַב לְמַדְבְּחָא וְעִבֵד יָת חַטָאתָךְ וְיָת עֲלָתָךְ וְכַפֵּר עֲלָךְ וְעַל עַמָא וְעִבֵד יָת קֻרְבַּן עַמָא וְכַפֵּר עֲלֵיהוֹן כְּמָא דִי פַקִיד יְיָ:
@216 וּקְרַב אַהֲרֹן לְמַדְבְּחָא וּנְכֵס יָת עֶגְלָא דְחַטָאתָא דִי לֵהּ:
@217 וְקָרִיבוּ בְּנֵי אַהֲרֹן יָת דְמָא לֵהּ וּטְבַל אֶצְבְּעֵהּ בִּדְמָא וִיהַב עַל קַרְנַת מַדְבְּחָא וְיָת דְמָא אֲרִיק לִיסוֹדָא דְמַדְבְּחָא:
@218 וְיָת תַּרְבָּא וְיָת כָּלְיֵתָא וְיָת חִצְרָא מִן כַּבְדָא מִן חַטָאתָא אַסֵק לְמַדְבְּחָא כְּמָא דִי פַקִיד יְיָ יָת מֹשֶׁה:
@219 וְיָת בִּשְׂרָא וְיָת מַשְׁכָא אוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא:
@220 וּנְכֵס יָת עֲלָתָא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן לֵּהּ יָת דְמָא וּזְרָקֵהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@221 וְיָת עֲלָתָא אַמְטִיאוּ לֵהּ לְאֵבָרָהָא וְיָת רֵישָׁא וְאַסֵק עַל מַדְבְּחָא:
@222 וְחַלִיל יָת גַוָא וְיָת כְּרָעַיָא וְאַסֵק עַל עֲלָתָא לְמַדְבְּחָא:
@223 וְקָרֵב יָת קֻרְבַּן עַמָא וּנְסִב יָת צְפִירָא דְחַטָאתָא דִי לְעַמָא וְנָכְסֵהּ וְכַפֵּר בִּדְמֵהּ כְּקַדְמָאָה:
@224 וְקָרֵב יָת עֲלָתָא וְעָבְדַהּ כִּדְחָזֵי:
@225 וְקָרִיב יָת מִנְחָתָא וּמְלָא יְדֵהּ מִנַהּ וְאַסֵק עַל מַדְבְּחָא בַּר מֵעֲלַת צַפְרָא:
@226 וּנְכֵס יָת תּוֹרָא וְיָת דִכְרָא נִכְסַת קוּדְשַׁיָא דִי לְעַמָא וְאַמְטִיאוּ בְּנֵי אַהֲרֹן יָת דְמָא לֵהּ וּזְרָקֵהּ עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@227 וְיָת תַּרְבַּיָא מִן תּוֹרָא וּמִן דִכְרָא אֲלִיתָא וְחָפֵי גַוָא וְכָלְיֵתָא וַחֲצַר כַּבְדָא:
@228 וְשַׁוִיאוּ יָת תַּרְבַּיָא עַל חֶדְוָתָא וְאַסֵק תַּרְבַּיָא לְמַדְבְּחָא:
@229 וְיָת חֶדְוָתָא וְיָת שׁוֹקָא דְיַמִינָא אֲרֵים אַהֲרֹן אֲרָמָא קֳדָם יְיָ כְּמָא דִי פַקִיד מֹשֶׁה:
@230 וַאֲרֵם אַהֲרֹן יָת יְדוֹהִי עַל עַמָא וּבָרֵכִנוּן וּנְחַת מִלְמֶעְבַּד חַטָאתָא וַעֲלָתָא וְנִכְסַת קוּדְשַׁיָא:
@231 וְעַל מֹשֶׁה וְאַהֲרֹן לְמַשְׁכַּן זִמְנָא וּנְפָקוּ וּבָרִיכוּ יָת עַמָא וְאִתְגְלִי יְקָרָא דַיְיָ לְכָל עַמָא:
@232 וּנְפָקַת אֶשָׁתָא מִן קֳדָם יְיָ וַאֲכָלַת עַל מַדְבְּחָא יָת עֲלָתָא וְיָת תַּרְבַּיָא וַחֲזָא כָּל עַמָא וְשַׁבָּחוּ וּנְפָלוּ עַל אַפֵּיהוֹן:
@233 וּנְסִיבוּ בְנֵי אַהֲרֹן נָדָב וַאֲבִיהוּא גְבַר מַחְתִּיתֵהּ וִיהָבוּ בְהוֹן אֶשָׁתָא וְשַׁוִיאוּ עֲלַהּ קְטוֹרֶת וְקָרִיבוּ קֳדָם יְיָ אֶשָׁתָא נוּכְרֵיתָא דִי לָא פַקִיד יָתְהוֹן:
@234 וּנְפָקַת אֶשָׁתָא מִן קֳדָם יְיָ וַאֲכָלַת יָתְהוֹן וּמִיתוּ קֳדָם יְיָ:
@235 וַאֲמַר מֹשֶׁה לְאַהֲרֹן הוּא דִי מַלִיל יְיָ לְמֵימַר בְּקָרִיבַי אִתְקַדַשׁ וְעַל אַפֵּי כָל עַמָא אִתְיַקָר וּשְׁתִיק אַהֲרֹן:
@236 וּקְרָא מֹשֶׁה לְמִישָׁאֵל וּלְאֶלְצָפָן בְּנֵי עֻזִיאֵל אַח אֲבוּהִי דְאַהֲרֹן וַאֲמַר לְהוֹן קְרִיבוּ טוּלוּ יָת אֲחֵיכוֹן מִן קֳדָם אַפֵּי קוּדְשָׁא לְמִבָּרָא לְּמַשְׁרִיתָא:
@237 וּקְרִיבוּ וּנְטָלֻּנוּן בְּכִתֻּנֵיהוֹן לְמִבָּרָא לְמַשְׁרִיתָא כְּמָא דִי מַלִיל מֹשֶׁה:
@238 וַאֲמַר מֹשֶׁה לְאַהֲרֹן וּלְאֶלְעָזָר וּלְאִיתָמָר בְּנוֹהִי רֵישֵׁיכוֹן לָא תְרַבּוּן פֵּרוּעַ וּלְבוּשֵׁיכוֹן לָא תְבַזְעוּן וְלָא תְמוּתוּן וְעַל כָּל כְּנִשְׁתָּא יְהֵא רוּגְזָא וַאֲחֵיכוֹן כָּל בֵּית יִשְׂרָאֵל יִבְכּוּן יָת יְקִדְתָּא דִי אוֹקִיד יְיָ:
@239 וּמִתְּרַע מַשְׁכַּן זִמְנָא לָא תִפְקוּן דִלְמָא תְמוּתוּן אֲרֵי מְשַׁח רְבוּתָא דַיְיָ עֲלֵיכוֹן וַעֲבָדוּ כְּפִתְגָמָא דְמֹשֶׁה:
@240 וּמַלִיל יְיָ עִם אַהֲרֹן לְמֵימָר:
@241 חֲמַר וּמְרַוֵי לָא תִשְׁתֵּי אַתְּ וּבְנָיךְ עִמָךְ בְּמֵעַלְכוֹן לְמַשְׁכַּן זִמְנָא וְלָא תְמוּתוּן קְיַם עָלָם לְדָרֵיכוֹן:
@242 וּלְאַפְרָשָׁא בֵּין קוּדְשָׁא וּבֵין חֻלָא וּבֵין מְסָאֲבָא וּבֵין דַכְיָא:
@243 וּלְאַלָפָא יָת בְּנֵי יִשְׂרָאֵל יָת כָּל קְיָמַיָא דִי מַלִיל יְיָ לְהוֹן בִּידָא דְמֹשֶׁה:
@244 וּמַלִיל מֹשֶׁה עִם אַהֲרֹן וְעִם אֶלְעָזָר וְעִם אִיתָמָר בְּנוֹהִי דְאִשְׁתָּאֲרוּ סִבוּ יָת מִנְחָתָא דְאִשְׁתָּאָרָת מִקֻרְבָּנַיָא דַיְיָ וְאִכְלוּהָ פַטִיר בִּסְטַר מַדְבְּחָא אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא:
@245 וְתֵיכְלוּן יָתַהּ בַּאֲתַר קַדִישׁ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ הִיא מִקֻרְבָּנַיָא דַיְיָ אֲרֵי כֵן אִתְפַּקָדִית:
@246 וְיָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא תֵּיכְלוּן בַּאֲתַר דְכֵי אַתְּ וּבְנָיךְ וּבְנָתָיךְ עִמָךְ אֲרֵי חֳלָקָךְ וָחֳלַק בְּנָיךְ אִתְיְהִיבוּ מִנִכְסַת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל:
@247 שׁוֹקָא דְאַפְרָשׁוּתָא וְחֶדְיָא דַאֲרָמוּתָא עַל קֻרְבָּנֵי תַרְבַּיָא יַיְתוּן לַאֲרָמָא אֲרָמָא קֳדָם יְיָ וִיהֵי לָךְ וְלִבְנָיךְ עִמָךְ לִקְיַם עָלָם כְּמָא דִי פַקִיד יְיָ:
@248 וְיָת צְפִירָא דְחַטָאתָא מִתְבַּע תָּבְעֵי מֹשֶׁה וְהָא אִתּוֹקָד וּרְגֵז עַל אֶלְעָזָר וְעַל אִיתָמָר בְּנֵי אַהֲרֹן דְאִשְׁתָּאֲרוּ לְמֵימָר:
@249 מָדֵין לָא אֲכַלְתּוּן יָת חַטָאתָא בַּאֲתַר קַדִישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הִיא וְיָתַהּ יְהַב לְכוֹן לְסַלָחָא עַל חוֹבֵי כְנִשְׁתָּא לְכַפָּרָא עֲלֵיהוֹן קֳדָם יְיָ:
@250 הָא לָא אִתָּעַל יָת דְמַהּ לְבֵית קֻדְשָׁא גַוָאָה מֵיכַל תֵּכְלוּן יָתַהּ בְּקֻדְשָׁא כְּמָא דִי פַקֵדִית:
@251 וּמַלִיל אַהֲרֹן עִם מֹשֶׁה הָא יוֹמָא דֵין קְרִיבוּ יָת חַטָּאתְהוֹן וְיָת עֲלָתְהוֹן קֳדָם יְיָ וַעֲרָעָא יָתִי עָקָן כְּאִלֵין וְאִלוּפוֹן אֲכָלִית חַטָאתָא יוֹמָא דֵין הֲתַקֵן קֳדָם יְיָ:
@252 וּשְׁמַע מֹשֶׁה וּשְׁפַר בְּעֵינוֹהִי:
@253 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימַר לְהוֹן:
@254 מַלִילוּ עִם בְּנֵי יִשְׂרָאֵל לְמֵימַר דָא חַיְתָא דִי תֵיכְלוּן מִכָּל בְּעִירָא דִי עַל אַרְעָא:
@255 כֹּל דִי סְדִיקָן פַּרְסָתָא וּמַטִלְפָן טִלְפִין פַּרְסָתָא מַסְקָּא פִשְׁרָא בִּבְעִירָא יָתַהּ תֵּיכְלוּן:
@256 בְּרָם יָת דֵין לָא תֵיכְלוּן מִמַסְקֵי פִשְׁרָא וּמִמַסְדִיקֵי פַּרְסָתָא יָת גַמְלָא אֲרֵי מַסִיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:
@257 וְיָת טַפְזָא אֲרֵי מַסִיק פִּשְׁרָא הוּא וּפַרְסָתָא לָא סְדִיקָא מְסָאָב הוּא לְכוֹן:
@258 וְיָת אַרְנְבָא אֲרֵי מַסְקָא פִשְׁרָא הִיא וּפַרְסָתָא לָא סְדִיקָא מְסָאָבָא הִיא לְכוֹן:
@259 וְיָת חֲזִירָא אֲרֵי סְדִיק פַּרְסָתָא הוּא וּמַטִּלְפָן טִּלְפִין פַרְסָתֵהּ וְהוּא פִּשְׁרָא לָא פָשָׁר מְסָאָב הוּא לְכוֹן:
@260 מִבִּסְרְהוֹן לָא תֵיכְלוּן וּבִנְבִלְתְּהוֹן לָא תִקְרְבוּן מְסָאֲבִין אִנוּן לְכוֹן:
@261 יָת דֵין תֵּיכְלוּן מִכֹּל דִי בְמַיָא כֹּל דִי לֵהּ צִיצִין וְקַלְפִין בְּמַיָא בְּיַמְמַיָא וּבְנַחֲלַיָא יַתְהוֹן תֵּיכְלוּן:
@262 וְכֹל דִי לֵית לֵהּ צִיצִין וְקַלְפִין בְּיַמְמַיָא וּבְנַחֲלַיָא מִכֹּל רִחֲשָׁא דְמַיָא וּמִכֹּל נַפְשָׁא חַיְתָא דִי בְמַיָא שִׁקְצָא אִנוּן לְכוֹן:
@263 וְשִׁקְצָא יְהוֹן לְכוֹן מִבִּסְרְהוֹן לָא תֵיכְלוּן וְיָת נְבִלְתְּהוֹן תְּשַׁקְצוּן:
@264 כֹּל דִי לֵית לֵהּ צִיצִין וְקַלְפִין בְּמַיָא שִׁקְצָא הוּא לְכוֹן:
@265 וְיָת אִלֵין תְּשַׁקְצוּן מִן עוֹפָא לָא יִתְאָכְלוּן שִׁקְצָא אִנוּן נִשְׁרָא וְעֲר וְעַזְיָא:
@266 וְדַיְתָא וְטָרָפִיתָא לִזְנַהּ:
@267 יָת כָּל עוּרְבָא לִזְנֵהּ:
@268 וְיָת בַּת נַעֲמִיתָא וְצִיצָא וְצִפַּר שַׁחְפָא וְנָצָא לִזְנוֹהִי:
@269 וְקַרְיָא וְשָׁלֵינוּנָא וְקִפּוֹפָא:
@270 וּבַוְתָא וְקָתָא וִירַקְרֵקָא:
@271 וְחַוָרִיתָא וְאִבּוּ לִזְנַהּ וְנַגַר טוּרָא וַעֲטַלֵפָא:
@272 כֹּל רִחֲשָׁא דְעוֹפָא דִמְהַלֵךְ עַל אַרְבַּע שִׁקְצָא הוּא לְכוֹן:
@273 בְּרַם יָת דֵין תֵּיכְלוּן מִכֹּל רִחֲשָׁא דְעוֹפָא דִמְהַלֵךְ עַל אַרְבַּע דִי לֵהּ קַרְצוּלִין מֵעִלַוֵי רַגְלוֹהִי לְקַפָּצָא בְהוֹן עַל אַרְעָא:
@274 יָת אִלֵין מִנְהוֹן תֵּיכְלוּן יָת גוֹבָא לִזְנֵהּ וְיָת רָשׁוּנָא לִזְנוֹהִי וְיָת חַרְגוֹלָא לִזְנוֹהִי וְיָת חַגָבָא לִזְנוֹהִי:
@275 וְכֹל רִחֲשָׁא דְעוֹפָא דִי לֵהּ אַרְבַּע רַגְלִין שִׁקְצָא הוּא לְכוֹן:
@276 וּלְאִלֵין תִּסְתָּאָבוּן כָּל דְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב עַד רַמשָׁא:
@277 וְכָל דְיִטוֹל:מִנְבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:
@278 לְכָל בְּעִירָא דִי הִיא סְדִיקָא פַרְסָתָא וְטִלְפִין לֵיתָהָא מַטִלְפָא וּפִשְׁרָא לֵיתָהָא מַסְקָא מְסָאֲבִין אִנוּן לְכוֹן כָּל דְיִקְרַב בְּהוֹן יְהֵי מְסָאָב:
@279 וְכֹל דִמְהַלֵךְ עַל יְדוֹהִי בְּכָל חַיְתָא דִמְהַלְכָא עַל אַרְבַּע מְסַאֲבִין אִנוּן לְכוֹן כָּל דְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵא מְסָאָב עַד רַמְשָׁא:
@280 וּדְיִטוֹל יָת נְבִלְתְּהוֹן יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא מְסַאֲבִין אִנוּן לְכוֹן:
@281 וְדֵין לְכוֹן מְסַאָבָא דְּרִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא חֻלְדָא וְעַכְבָּרָא וְצָבָא לִזְנוֹהִי:
@282 וְיָלָא וְכוֹחָא וְחֻלְטֵיתָא וְחֻמְטָא וְאָשׁוּתָא:
@283 אִלֵין דִמְסַאֲבִין לְכוֹן בְּכָל רִחֲשָׁא כֹּל דְיִקְרַב בְּהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב עַד רַמְשָׁא:
@284 וְכָל דִי יִפֵּל עֲלוֹהִי מִנְהוֹן בְּמוֹתְהוֹן יְהֵי מְסָאָב מִכָּל מָאן דְעָא אוֹ לְבוּשׁ אוֹ מְשַׁךְ אוֹ שָׂק כָּל מָאן דִי תִתְעֲבֵד עִבִידָא בְּהוֹן בְּמַיָא יִתָּעַל וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@285 וְכָל מָאן דַחֲסַף דִי יִפֵּל מִנְהוֹן לְגַוֵהּ כֹּל דִי בְגַוֵהּ יִסְתָּאַב וְיָתֵהּ תְּתַבְּרוּן:
@286 מִכָּל מֵיכְלָא דְמִתְאֲכֵל דִי יַעֲלוּן עֲלוֹהִי מַיָא יְהֵי מְסָאָב וְכָל מַשְׁקֵה דִי יִשְׁתֵּתֵי בְּכָל מָאן יְהֵי מְסָאָב:
@287 וְכֹל דִי יִפֹּל מִנְבִלְתְּהוֹן עֲלוֹהִי יְהֵי מְסָאָב תַּנוּר וְכִירַיִם יִתָּרְעוּן מְסַאֲבִין אִנוּן וּמְסַאֲבִין יְהוֹן לְכוֹן:
@288 בְּרַם מַעְיָן וְגוֹב בֵּית כְּנִישׁוּת מַיָא יְהֵי דְכֵי וּדְיִקְרַב בִּנְבִלְתְּהוֹן יְהֵי מְסָאָב:
@289 וַאֲרֵי יִפֵּל מִנְבִלְתְּהוֹן עַל כָּל בַּר זְרַע זֵרוּעַ דִי יִזְדְרָע דְכֵי הוּא:
@290 וַאֲרֵי יִתְיַהֲבוּן מַיָא עַל בַּר זַרְעָא וְיִפֵּל מִנְבִלְתְּהוֹן עֲלוֹהִי מְסָאָב הוּא לְכוֹן:
@291 וַאֲרֵי יְמוּת מִן בְּעִירָא דִי הִיא לְכוֹן לְמֵיכָל דְיִקְרַב בִּנְבִלְתַּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@292 וּדְיֵכוּל מִנְבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטוֹל יָת נְבִלְתַּהּ יְצַבַּע לְבוּשׁוֹהִי וִיהֵי מְסָאָב עַד רַמְשָׁא:
@293 וְכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא שִׁקְצָא הוּא לָא יִתְאָכֵל:
@294 כֹּל דִמְהַלֵךְ עַל מְעוֹהִי וְכֹל דִמְהַלֵךְ עַל אַרְבַּע עַד כָּל סְגִיאוּת רַגְלָאִין לְכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא לָא תֵיכְלֻנוּן אֲרֵי שִׁקְצָא אִנוּן:
@295 לָא תְשַׁקְצוּ יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְרָחֵשׁ וְלָא תִסְתַּאֲבוּן בְּהוֹן וְתִסְתַּאֲבוּן פּוֹן בְּהוֹן:
@296 אֲרֵי אֲנָא יְיָ אֶלָהָכוֹן וְתִתְקַדְשׁוּן וּתְהוֹן קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא וְלָא תְסַאֲבוּן יָת נַפְשָׁתֵיכוֹן בְּכָל רִחֲשָׁא דְרָחֵשׁ עַל אַרְעָא:
@297 אֲרֵי אֲנָא יְיָ דְאַסֵק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ וּתְהוֹן קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא:
@298 דָא אוֹרַיְתָא דִבְעִירָא וּדְעוֹפָא וּדְכָל נַפְשָׁתָא חַיְתָא דִרְחֵשָׁא בְּמַיָא וּלְכָל נַפְשָׁא דִרְחֵשָׁא עַל אַרְעָא:
@299 לְאַפְרָשָׁא בֵּין מְסָאָבָא וּבֵין דַכְיָא וּבֵין חַיְתָא דְמִתְאַכְלָא וּבֵין חַיְתָא דִי לָא מִתְאַכְלָא: פפפ:
@300 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@301 מַלֵל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר אִתְּתָא אֲרֵי תְעַדִי וּתְלִיד דְכָר וּתְהֵי מְסָאָבָא שִׁבְעַת יוֹמִין כְּיוֹמֵי רִחוּק סוֹבְתַהּ תְּהֵי מְסָאָבָא:
@302 וּבְיוֹמָא תְּמִינָאָה יִגְזַר בִּסְרָא דְעָרְלְתֵהּ:
@303 וּתְלָתִין וּתְלָתָא יוֹמִין תֵּיתֵב בְּדַם דְכוּ בְּכָל קוּדְשָׁא לָא תִקְרַב וּלְמִקְדְשָׁא לָא תֵעוֹל עַד מִשְׁלַם יוֹמֵי דָכוּתַהּ:
@304 וְאִם נְקוּבְתָא תְלִיד וּתְהֵי מְסָאָבָא אַרְבְּעָה עֲסַר כְּרִחוּקַהּ וְשִׁתִּין וְשִׁתָּא יוֹמִין תֵּיתֵב עַל דַם דְכוּ:
@305 וּבְמִשְׁלַם יוֹמֵי דָכוּתַהּ לִבְרָא אוֹ לִבְרַתָּא תַּיְתִי אִמָר בַּר שַׁתֵּהּ לַעֲלָתָא וּבַר יוֹנָה אוֹ שַׁפְנִינָא לְחַטָאתָא לִתְרַע מַשְׁכַּן זִמְנָא לְוַת כַּהֲנָא:
@306 וִיקָרְבִנֵהּ קֳדָם יְיָ וִיכַפֵּר עֲלַהּ וְתִדְכֵּי מִסוֹאֲבַת דְמָהָא דָא אוֹרַיְתָא דְיַלֶדְתָּא לְדוּכְרָא אוֹ לִנְקֻבְתָא:
@307 וְאִם לָא תַשְׁכַּח יְדַהּ כְּמִסַת אִמְרָא וְתִסַב תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה חַד לַעֲלָתָא וְחַד לְחַטָאתָא וִיכַפֵּר עֲלַהּ כַּהֲנָא וְתִדְכֵּי:
@308 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@309 אֱנַשׁ אֲרֵי יְהֵי בִמְשַׁךְ בִּסְרֵהּ עַמְקָא אוֹ עַדְיָא אוֹ בַהֲרָא וִיהֵי בִמְשַׁךְ בִּסְרֵהּ לְמַכְתַּשׁ סְגִירוּ וְיִתֵּתֵי לְוַת אַהֲרֹן כַּהֲנָא אוֹ לְוַת חַד מִבְּנוֹהִי כַּהֲנַיָא:
@310 וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא בִמְשַׁךְ בִּסְרָא וְשֵׂעָר בְּמַכְתָּשָׁא אִתְהַפִיךְ לְמֶחֱוָר וּמֶחֱזֵי מַכְתָּשָׁא עַמִיק בִּמְשַׁךְ בִּסְרֵהּ מַכְתַּשׁ סְגִירוּתָא הוּא וְיֶחֱזִנֵהּ כַּהֲנָא וִיסָאֵב יָתֵהּ:
@311 וְאִם בַּהֲרָא חַוְרָא הִיא בִּמְשַׁךְ בִּסְרֵהּ וְעַמִיק לֵית מֶחֱזָהָא מִן מַשְׁכָא וּשְׂעָרָא לָא אִתְהֲפִיךְ לְמֶחֱוָר וְיַסְגַר כַּהֲנָא יָת מַכְתָּשָׁא שִׁבְעָא יוֹמִין:
@312 וְיֶחֱזִנֵהּ כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה וְהָא מַכְתָּשָׁא קָם כַּד הֲוָה לָא אוֹסֵף מַכְתָּשָׁא בְּמַשְׁכָּא וְיַסְגְרִנֵהּ כַּהֲנָא שִׁבְעָא יוֹמִין תִּנְיָנוּת:
@313 וְיֶחֱזֵי כַהֲנָא יָתֵהּ בְּיוֹמָא שְׁבִיעָאָה תִּנְיָנוּת וְהָא עַמְיָא מַכְתָּשָׁא וְלָא אוֹסֵף מַכְתָּשָׁא בְּמַשְׁכָּא וִידַכִּנֵהּ כַּהֲנָא עֲדִיתָא הִיא וִיצַבַּע לְבוּשׁוֹהִי וְיִדְכֵּי:
@314 וְאִם אוֹסָפָא תוֹסֵף עֲדִיתָא בְּמַשְׁכָּא בָּתַר דְאִתְּחֲזִי לְכַהֲנָא לְדַכּוּתֵהּ וְיִתַּחֲזִי תִנְיָנוּת לְכַהֲנָא:
@315 וְיֶחֱזֵי כַהֲנָא וְהָא אוֹסֵפַת עֲדִיתָא בְּמַשְׁכָּא וִיסָאֵבִנֵהּ כַּהֲנָא סגִירוּתָא הִיא:
@316 מַכְתַּשׁ סְגִירוּ אֲרֵי תְהֵי בֶּאֱנָשָׁא ויִתֵּתֵי לְוָת כַּהֲנָא:
@317 וְיֶחֱזֵי כֲהֲנָא וְהָא עַמְקָא חַוְרָא בְּמַשְׁכָּא וְהִיא הֲפָכַת שֵׂעָר לְחִוָר וְרֹשֶׁם בִּסְרָא חַיְתָא בְּעַמִקְתָּא:
@318 סְגִירוּת עַתִּיקָא הִיא בִּמְשַׁךְ בִּסְרֵהּ וִיסָאֵבִנֵהּ כַּהֲנָא לָא יַסְגְרִנֵהּ אֲרֵי:מסָאָב הוּא:
@319 וְאִם מִסְגָא תִסְגֵי סְגִירוּתָא בְּמַשְׁכָּא וְתַחְפֵי סְגִירוּתָא יָת כָּל מְשַׁךְ מַכְתָּשָׁא מֵרֵישֵׁהּ וְעַד רַגְלוֹהִי לְכָל חֵיזוּ עֵינֵי כַהֲנָא:
@320 וְיֶחֱזֵי כַהֲנָא וְהָא חֲפַת סְגִירוּתָא יָת כָּל בִּסְרֵהּ וִידַכִּי יָת מַכְתָּשָׁא כֻּלֵהּ אִתְהֲפִיךְ לְמֶחֱוַר דְכֵי הוּא:
@321 וּבְיוֹמָא דְאִתַּחֲזִי בֵהּ בִּסְרָא חַיָא יְהֵי מְסָאָב:
@322 וְיֶחֱזֵי כַהֲנָא יָת בִּסְרָא חַיָא וִיסָאֵבִנֵהּ בִּסְרָא חַיָא מְסָאָב הוּא סְגִירוּת הוּא:
@323 אוֹ אֲרֵי יְתוּב בִּסְרָא חַיָא וְיִתְהֲפִיךְ לְמֶחֱוָר וְיִתֵּתֵי לְוַת כַּהֲנָא:
@324 וְיֶחֱזִנֵהּ כַּהֲנָא וְהָא אִתְהֲפִיךְ מַכְתָּשָׁא לְמֶחֱוָר וִידַכֵּי כַהֲנָא יָת מַכְתָּשָׁא דְכֵי הוּא:
@325 וּבִסְרָא אֲרֵי יְהֵי בֵהּ בְּמַשְּׁכֵּהּ שִׁחֲנָא וְיִתַּסֵי:
@326 וִיהֵי בַאֲתַר שִׁחֲנָא עַמְקָא חַוְרָא אוֹ בַהֲרָא חַוְרָא סַמְקָא וְיִתַּחֲזִי לְכַהֲנָא:
@327 וְיֶחֱזֵי כַהֲנָא וְהָא מֶחֱזָהָא מַכִּיךְ מִן מַשְׁכָּא וּשְׂעָרַהּ אִתְהַפִיךְ לְמֶחֱוָר וִיסָאֵבִינֵהּ כַּהֲנָא מַכְתַּשׁ סְגִירוּתָא הִיא בְּשִׁחַנָא סְגִיאַת:
@328 וְאִם יֶחֱזִנַהּ כַּהֲנָא וְהָא לֵית בַּהּ שֵׂעָר חִוָר וּמַכִּיכָא לֵיתָהָא מִן מַשְׁכָּא וְהִיא עָמַיָא וְיַסְגְרִנֵהּ כַּהֲנָא שִׁבְעָא יוֹמִין:
@329 וְאִם אוֹסָפָא תוֹסֵף בְּמַשְׁכָּא וִיסָאֵב כַּהֲנָא יָתֵהּ מַכְתָּשָׁא הִיא:
@330 וְאִם בְּאַתְרָהָא קָמַת בֶּהַרְתָּא לָא אוֹסֵפַת רֹשֶׁם שִׁחֲנָא הִיא וִידַכִּנֵהּ כַּהֲנָא:
@331 אוֹ בִסְרָא אֲרֵי יְהֵי בְמַשְׁכֵּהּ כְּוָאָה דְנוּר וּתְהֵי רֹשֶׁם כְּוָאָה בַּהֲרָא חַוְרָא סֲמקָא אוֹ חַוְרָא:
@332 וְיֶחֱזֵי יָתַהּ כַּהֲנָא וְהָא אִתְהֲפִיךְ שֵׂעָר חִוָר בְּבַהֶרְתָּא וּמֶחֱזָהָא עַמִיק מִן מַשְׁכָּא סְגִירוּתָא הִיא בִּכְוָּאָה סְגִיאָה וִיסָאֵב יָתֵהּ כַּהֲנָא מַכְתַּשׁ סְגִירוּתָא הִיא:
@333 וְאִם יֶחֱזִנַהּ כַּהֲנָא וְהָא לֵית בְּבַהֶרְתָּא שֵׂעָר חִוָר וּמַכִּיכָא לֵיתָהָא מִן מַשְׁכָּא וְהִיא עָמְיָא וְיַסְגְרִנֵהּ כַּהֲנָא שִׁבְעָא יוֹמִין:
@334 וְיֶחֱזִנֵהּ כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה אִם אוֹסָפָא תוֹסֵף בְּמַשְׁכָּא וִיסָאֵב כַּהֲנָא יָתֵהּ מַכְתַּשׁ סְגִירוּתָא הִיא:
@335 וְאִם בְּאַתְרָהָא קָמַת בַּהֶרְתָּא לָא אוֹסֵפַת בְּמַשְׁכָּא וְהִיא עָמְיָא עוֹמֶק כְּוָאָה הִיא וִידַכִּנֵהּ כַּהֲנָא אֲרֵי רֹשֶׁם כְּוָאָה הִיא:
@336 וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵא בֵהּ מַכְתָּשָׁא בְּרֵישׁ אוֹ בִּדְקָן:
@337 וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא וְהָא מֶחֱזוֹהִי עַמִיק מִן מַשְׁכָּא וּבֵהּ שֵׂעָר סֻמָק דַעְדָק וִיסָאֵב יָתֵהּ כַּהֲנָא נִתְקָא הוּא סְגִירוּת רֵישָׁא אוֹ דִקְנָא הוּא:
@338 וַאֲרֵי יֶחֱזֵי כַהֲנָא יָת מַכְתַּשׁ נִתְקָא וְהָא לֵית מֶחֱזוֹהִי עַמִיק מִן מַשְּׁכָּא וְשֵׂעָר אֻכָם לֵית בֵּיהּ וְיַסְגַר כַּהֲנָא יָת מַכְתַּשׁ נִתְקָא שִׁבְעַת יוֹמִין:
@339 וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא בְּיוֹמָא שְׁבִיעָאָה וְהָא לָא אוֹסֵף נִתְקָא וְלָא הֲוָה בֵהּ שֵׂעָר סֻמָק וּמֶחֱזֵי נִתְקָא לֵית עַמִיק מִן מַשְׁכָּא:
@340 וִיגַלַח סָחֳרָנֵי נִתְקָא וּדְעִם נִתְקָא לָא יְגַלַח וְיַסְגַר כַּהֲנָא יָת נִתְקָא שִׁבְעָא יוֹמִין תִּנְיָנוּת:
@341 וְיֶחֱזֵי כַהֲנָא יָת נִתְקָא בְּיוֹמָא שְׁבִיעָאָה וְהָא לָא אוֹסֵף נִתְקָא בְּמַשְׁכָּא וּמֶחֱזוֹהִי לֵיתוֹהִי עַמִיק מִן מַשְׁכָּא וִידַכֵּי יָתֵהּ כַּהֲנָא וִיצַבַּע לְבוּשׁוֹהִי וְיִדְכֵּי:
@342 וְאִם אוֹסָפָא יוֹסֵף נִתְקָא בְּמַשְׁכָּא בָּתַר דָכוּתֵהּ:
@343 וְיֶחֱזִנֵהּ כַּהֲנָא וְהָא אוֹסֵף נִתְקָא בְּמַשְׁכָּא לָא יְבַקֵר כַּהֲנָא לְשֵׂעָר סֻמָק מְסָאָב הוּא:
@344 וְאִם כַּד הֲוָה קָם נִתְקָא וְשֵׂעָר אֻכָּם צְמַח בֵּהּ אִתַּסִי נִתְקָא דְכֵי הוּא וִידַכִּנֵהּ כַּהֲנָא:
@345 וגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בִמְשַׁךְ בִּסְרְהוֹן בַּהֲרָן בַּהֲרָן חַוְרָן:
@346 וְיֶחֱזֵי כַהֲנָא וְהָא בִמְשַׁךְ בִּסְרְהוֹן בַּהֲרָן עָמְיָן חַוְרָן בָּהֲקָא הוּא סָגֵי בְמַשְׁכָּא דְכֵי הוּא:
@347 וּגְבַר אֲרֵי יַתַּר שְׂעַר רֵישֵׁהּ קְרַח הוּא דְכֵי הוּא:
@348 וְאִם מִלָקֳבֵל אַפּוֹהִי יַתַּר שְׂעַר רֵישֵׁהּ גְלוֹשׁ הוּא דְכֵי הוּא:
@349 וַאֲרֵי יְהֵי בְקָרָחוּתֵהּ אוֹ בִגְלוֹשׁוּתֵהּ מַכְתַּשׁ חִוָר סַמוֹק סְגִירוּת סָגְיָא הִיא בְּקָרָחוּתֵהּ אוֹ בִגְלוֹשּׁוּתֵהּ:
@350 וְיֶחֱזֵי יָתֵהּ כַּהֲנָא וְהָא עַמִיק מַכְתָּשָׁא חַוְרָא סַמְקָא בְּקָרָחוּתֵהּ אוֹ בִגְלוֹשׁוּתֵהּ כְּמֶחֱזֵי סְגִירוּתָא מְשַׁךְ בִּסְרָא:
@351 גְבַר סְגִיר הוּא מְסָאָב הוּא סָאֳבָא יְסָאֵבִנֵהּ כַּהֲנָא בְּרֵישֵּׁהּ מַכְתָּשֵׁהּ:
@352 וּסְגִירָא דִי בֵהּ מַכְתָּשָׁא לְבוּשׁוֹהִי יְהוֹן מְבַזְעִין וְרֵישֵׁהּ יְהֵי פְרִיעַ וְעַל שָׂפָם כַּאֲבֵלָא יִתְעַטָף וְלָא תִסְתַּאֲבוּן וְלָא תִסְתַּאֲבוּן יִקְרֵי:
@353 כָּל יוֹמֵי דִי מַכְתָּשָּׁא בֵהּ יְהֵי מְסָאָב מְסָאָב הוּא בִּלְחוֹדוֹהִי יֵיתֵב מִבָּרָא לְמַשְׁרִיתָא מוֹתְבֵהּ:
@354 וּלְבוּשָׁא אֲרֵי יְהֵי בֵהּ מַכְתַּשׁ סְגִירוּ בִּלְבֻשׁ עֲמַר אוֹ בִּלְבוּשׁ כִּתָּן:
@355 אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא לְכִתָּנָא וּלְעַמְרָא אוֹ בְמַשְׁכָּא אוֹ בְּכָל עֲבִידַת מְשָׁךְ:
@356 וִיהֵי מַכְתָּשָׁא יָרוֹק אוֹ סַמוֹק בִּלְבוּשָׁא אוֹ בְמַשְׁכָּא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְכָל מַאן דִמְשַׁךְ מַכְתַּשׁ סְגִירוּתָא הוּא וְיִתַּחֲזֵי לְכַהֲנָא:
@357 וְיֶחֱזֵי כַהֲנָא יָת מַכְתָּשָׁא וְיַסְגַר יָת מַכְתָּשָׁא שִׁבְעַת יוֹמִין:
@358 וְיֶחֱזֵי יָת מַכְתָּשָׁא בְּיוֹמָא שְׁבִיעָאָה אֲרֵי אוֹסֵף מַכְתָּשָּׁא בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְמַשְׁכָּא לְכֹל דִי יִתְעֲבֵד מַשְׁכָּא לְעִבִידָא סְגִירוּת מְחַסְרָא מַכְתָּשָׁא מְסָאָב הוּא:
@359 וְיוֹקִיד יָת לְבוּשָׁא אוֹ יָת שִׁתְיָא אוֹ יָת עַרְבָא בְעַמְרָא אוֹ בְכִתָּנָא אוֹ יָת כָּל מָאן דִמְשַׁךְ דִי יְהֵי בֵהּ מַכְתָּשָׁא אֲרֵי סְגִירוּת מְחַסְרָא הִיא בְּנוּרָא תִּתּוֹקָד:
@360 וְאִם יֶחֱזֵי כַהֲנָא וְהָא לָא אוֹסֵף מַכְתָּשָׁא בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְּכָל מָאן דִמְשָׁךְ:
@361 וִיפַקֵד כַּהֲנָא וִיחַוְרוּן יָת דִי בֵהּ מַכְתָּשָׁא וְיַסְגְרִנֵהּ שִׁבְעַת יוֹמִין תִּנְיָנוּת:
@362 וְיֶחֱזֵי כַהֲנָא בָּתַר דְחַוָרוּ יָת מַכְתָּשָׁא וְהָא לָא שְׁנָא מַכְתָּשָׁא מִן כַּד הֲוָה וּמַכְתָּשָׁא לָא אוֹסֵף מְסָאָב הוּא בְּנוּרָא תּוֹקְדִנֵהּ תַּבְרָא הִיא בִּשְׁחִיקוּתֵהּ אוֹ בחַדָתוּתֵהּ:
@363 וְאִם חֲזָא:כַהֲנָא וְהָא עָמְיָא מַכְתָּשָׁא בָּתַר דְחַוָרוּ יָתֵהּ וּבְזַע יָתֵהּ מִן לְבוּשָׁא אוֹ מִן מַשְׁכָּא אוֹ מִן שִׁתְיָא אוֹ מִן עַרְבָא:
@364 וְאִם תִּתְחֲזֵי עוֹד בִּלְבוּשָׁא אוֹ בְשִׁתְיָא אוֹ בְעַרְבָא אוֹ בְכָל מָאן דִמְשַׁךְ סָגְיָא הִיא בְּנוּרָא תוֹקְדִנֵהּ יָת דִי בֵהּ מַכְתָּשָׁא:
@365 וּלְבוּשָׁא אוֹ שַׁתְיָא אוֹ עַרְבָא אוֹ כָל מָאן דִמְשָׁךְ דִי יִתְחַוַר וְיֶעְדֵי מִנְהוֹן מַכְתָּשָׁא וְיִצְטַּבַּע תִּנְיָנוּת וְיִדְכֵּי:
@366 דָא אוֹרַיְתָא דְמַכְתַּשׁ סְגִירוּ בִּלְבוּשׁ עֲמַר אוֹ כִתָּנָא אוֹ שִׁתְיָא אוֹ עַרְבָא אוֹ כָּל מָאן דִמְשָׁךְ לְדַכָּיוּתֵהּ אוֹ לְסַאֲבוּתֵהּ: פפפ:
@367 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@368 דָא תְהֵי אוֹרַיְתָא דִסְגִירָא בְּיוֹמָא דְדָכוּתֵהּ וְיִתֵּתֵי לְוָת כַּהֲנָא:
@369 וְיִפּוֹק כַּהֲנָא לְמִבָּרָא לְמַשְׁרִיתָא וְיֶחֱזֵי כַהֲנָא וְהָא אִתַּסִי מַכְתַּשׁ סְגִירוּתָא מִן סְגִירָא:
@370 וִיפַקֵד כַּהֲנָא וְיִסַב לְמִדַכֵּי תַּרְתֵּין צִפֳּרִין חַיִין דָכְיָן וְאָעָא דְאַרְזָא וּצְבַע זְהוֹרִי וְאֵזוֹבָא:
@371 וִיפַקֵד כַּהֲנָא וְיִכּוֹס יָת צִפְּרָא חֲדָא לְמָאן דַחֲסַף עַל מֵי מַבּוּעַ:
@372 יָת צִפְּרָא חַיְתָא יִסַב יָתַהּ וְיָת אָעָא דְאַרְזָא וְיָת צְבַע זְהוֹרִי וְיָת אֵזוֹבָא וְיִטְבּוֹל יָתְהוֹן וְיָת צִפְּרָא חַיְתָא בִּדְמָא דְצִפְּרָא דִנְכִיסָא עַל מֵי מַבּוּעַ:
@373 וְיַדִי עַל דְמִדַכֵּי מִן סְגִירוּתָא שְׁבַע זִמְנִין וִידַכִּנֵהּ וִישַׁלַח יָת צִפְּרָא חַיְתָא עַל אַפֵּי חַקְלָא:
@374 וִיצַבַּע דְמִדַכֵּי יָת לְבוּשׁוֹהִי וִיגַלַח יָת כָּל שַׂעֲרֵהּ וְיַסְחֵי בְמַיָא וְיִדְכֵּי וּבָתַר כֵּן יֵעוֹל לְמַשְׁרִיתָא וִיתֵב מִבָּרָא לְמַשְׁכְּנֵהּ שִׁבְעַת יוֹמִין:
@375 וִיהֵי בְיוֹמָא שְׁבִיעָאָה יְגַלַח יָת כָּל שַׂעֲרֵהּ יָת רֵישֵׁהּ וְיָת דִקְנֵהּ וְיָת גְבִינֵי עֵינוֹהִי וְיָת כָּל שַׂעֲרֵהּ יְגַלָח וִיצַבַּע יָת לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וְיִדְכֵּי:
@376 וּבְיוֹמָא תְמִינָאָה יִסַב תְּרֵין אִמְרִין שַׁלְמִין וְאִמַרְתָּא חֲדָא בַּת שַׁתָּא שְׁלֶמְתָּא וּתְלָתָא עֶסְרוֹנִין סֻלְתָּא מִנְחָתָא דְפִילָא בִמְשַׁח וְלֻגָא חַד דְמִשְׁחָא:
@377 וִיקִים כַּהֲנָא דִמְדַכֵּי יָת גַבְרָא דְמִדַכֵּי וְיָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@378 וְיִסַב כַּהֲנָא יָת אִמְרָא חֲדָא וִיקָרֵב יָתֵיהּ לַאֲשָּׁמָא וְיָת לֻגָא דְמִשְׁחָא וִירִים יָתְהוֹן אֲרָמָא קֳדָם יְיָ:
@379 וְיִכּוֹס יָת אִמְרָא בַּאֲתַר דִי יִכּוֹס יָת חַטָאתָא וְיָת עֲלָתָא בַּאֲתַר קַדִישׁ אֲרֵי כְּחַטָאתָא אֲשָׁמָא הוּא לְכַהֲנָא קֹדֶשׁ קוּדְשִׁין הוּא:
@380 וְיִסַב כַּהֲנָא מִדְמָא דַאֲשָׁמָא וְיִתֵּן כַּהֲנָא עַל רוּם אוּדְנָא דְמִדַכֵּי דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא:
@381 וְיִסַב כַּהֲנָא מִלֻגָא דְמִשְׁחָא וִירִיק עַל יְדָא דְכַהֲנָא דִשְׁמָאלָא:
@382 וְיִטְבּוֹל כַּהֲנָא יָת אֶצְבְּעֵהּ דְיַמִינָא מִן מִשְׁחָא דִי עַל יְדֵהּ דִּשְׂמָאלָא וְיַדִי מִן מִשְׁחָא בְּאֶצְבְּעֵהּ שְׁבַע זִמְנִין קֳדָם יְיָ:
@383 וּמִשְׁאָר מִשְׁחָא דִי עַל יְדֵהּ יִתֵּן כַּהֲנָא עַל רוּם אוּדְנָא דְמִדַכֵּי דְיַּמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא עַל דְמָא דַאֲשָׁמָא:
@384 וּדְאִשְׁתָּאַר בְּמִשְׁחָא דִי עַל יְדָא דְכַהֲנָא יִתֵּן עַל רֵישָׁא דְמִדַכֵּי וִיכַפֵּר עֲלוֹהִי כַּהֲנָא קֳדָם יְיָ:
@385 וְיַעְבֵּד כַּהֲנָא יָת חַטָאתָא וִיכַפֵּר עַל דְמִדַּכֵּי מִסּוֹבְתֵהּ וּבָתַר כֵּן יִכּוֹס יָת עֲלָתָא:
@386 וְיַסֵק כַּהֲנָא יָת עֲלָתָא וְיָת מִנְחָתָא לְמַדְבְּחָא וִיכַפֵּר עֲלוֹהִי כַּהֲנָא וְיִדְכֵּי:
@387 וְאִם מִסְכֵּן הוּא וְלֵית יְדֵהּ מַדְבְּקָא וְיִסַּב אִמַר חַד אֲשָׁמָא לַאֲרָמָא לְכַפָּרָא עֲלוֹהִי וְעִסְרוֹנָא סֻלְתָּא חַד דְפִיל בִּמְשַּׁח לְמִנְחָא וְלֻגָא דְמִשְׁחָא:
@388 וְתַרְתֵּין שַּׁ:פנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה דִי תַדְבֵּק יְדֵהּ וִיהֵי חַד חַטָאתָא וְחַד עֲלָתָא:
@389 וְיַיְתִי יָתְהוֹן בְּיוֹמָא תְמִינָאָה לְדַכָּיוּתֵהּ לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא קֳדָם יְיָ:
@390 וְיִסַב כַּהֲנָא יָת אִמְרָא דַאֲשָׁמָא וְיָת לֻגָא דְמִשְׁחָא וִירִים יָתְהוֹן כַּהֲנָא אֲרָמָא קֳדָם יְיָ:
@391 וְיִכּוֹס יָת אִמְרָא דַאֲשָׁמָא וְיִסַב כַּהֲנָא מִדְמָא דַאֲשָׁמָא וְיִתֵּן עַל רוּם אוּדְנָא דְמִדַכֵּי דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא:
@392 וּמִן מִשְׁחָא יְרִיק כַּהֲנָא עַל יְדָא דְכַהֲנָא דִשְׂמָאלָא:
@393 וְיַדִי כַהֲנָא בְּאֶצְבְּעֵהּ דְיַמִינָא מִן מִשְׁחָא דִי עַל יְדֵהּ דִשְׂמָאלָא שְׁבַע זִמְנִין קֳדָם יְיָ:
@394 וְיִתֵּן כַּהֲנָא מִן מִשְׁחָא דִי עַל יְדֵהּ עַל רוּם אוּדְנָא דְמִדַכֵּי דְיַמִינָא וְעַל אִלְיוֹן יְדֵהּ דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵהּ דְיַמִינָא עַל אֲתַר דְמָא דַאֲשָׁמָא:
@395 וּדְיִשְׁתָּאַר מִן מִשְׁחָא דִי עַל יְדָא דְכַהֲנָא יִתֵּן עַל רֵישָׁא דְמִדַכֵּי לְכַפָּרָא עֲלוֹהִי קֳדָם יְיָ:
@396 וְיַעְבֵּד יָת חַד מִן שַׁפְנִינַיָא אוֹ מִן בְּנֵי יוֹנָה מִדִי תַדְבֵּק יְדֵהּ:
@397 יָת דִי תַדְבֵּק יְדֵהּ יָת חַד חַטָאתָא וְיָת חַד עֲלָתָא עַל מִנְחָתָא וִיכַפֵר כַּהֲנָא עַל דְמִדַכֵּי קֳדָם יְיָ:
@398 דָא אוֹרַיְתָא דִי בֵהּ מַכְתַּשׁ סְגִירוּ דִי לָא תַדְבֵּק יְדֵהּ בְּדָכוּתֵהּ:
@399 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@400 אֲרֵי תֵעֲלוּן לְאַרְעָא דִכְנַעַן דִי אֲנָא יָהֵב לְכוֹן לְאַחֲסָנָא וְאֶתֵּן מַכְתַּשׁ סְגִירוּ בְּבֵית אַרְעָא אַחֲסַנְתְּכוֹן:
@401 וְיֵיתֵי דִי דִילֵהּ בֵּיתָא וִיחַוִי לְכַהֲנָא לְמֵימָר כְּמַכְתָּשָׁא אִתְחֲזִי לִי בְּבֵיתָא:
@402 וִיפַקֵד כַּהֲנָא וִיפַנוּן יָת בֵּיתָא עַד לָא יֵעוֹל כַּהֲנָא לְמֶחֱזֵי יָת מַכְתָּשָׁא וְלָא יִסְתָּאַב כָּל דִי בְּבֵיתָא וּבָתַר כֵּן יֵיעוֹל כַּהֲנָא לְמֶחֱזֵי יָת בֵּיתָא:
@403 וְיֶחֱזֵי יָת מַכְתָּשָׁא וְהָא מַכְתָּשָׁא בְּכָתְלֵי בֵיתָא פַּחֲתִין יַרְקָן אוֹ סַמְקָן וּמֶחֱזֵיהוֹן מַכִּיךְ מִן כָּתְלָא:
@404 וְיִפּוֹק כַּהֲנָא מִן בֵּיתָא לִתְרַע בֵּיתָא וְיַסְגַר יָת בֵּיתָא שִׁבְעָא יוֹמִין:
@405 וִיתוּב כַּהֲנָא בְּיוֹמָא שְׁבִיעָאָה וְיֶחֱזֵי וְהָא אוֹסֵף מַכְתָּשָׁא בּכָתלֵי בֵיתָא:
@406 וִיפַקֵד כֲּהֲנָא וִישַׁלְפוּן יָת אַבְנַיָא דִי בְהוֹן מַכְתָּשָׁא וְיִרְמוּן יָתְהוֹן לְמִבָּרָא לְקַרְתָּא לַאַתַר מְסָאָב:
@407 וְיָת בֵּיתָא יְקַלְפוּן מִגָיו סְחוֹר סְחוֹר וְיִרְמוּן יָת עַפְרָא דִי קַלִיפוּ לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:
@408 וְיִסְבוּן אַבְנַיָא אָחֳרָנִין וְיַיְתוּן בַּאֲתַר אַבְנַיָא וַעֲפַר אָחֳרָן יִסַב וִישׁוּעַ יָת בֵּיתָא:
@409 וְאִם יְתוּב מַכְתָּשָׁא וְיִסְגֵי בְּבֵיתָא בָּתַר דְשַׁלִיפוּ יָת אַבְנַיָא וּבָתַר דְקַלִיפוּ יָת בֵּיתָא וּבָתַּר דְאִתְּשָׁע:
@410 וְיֵיעוֹל כַּהֲנָא וְיֶחֱזֵי וְהָא אוֹסֵף מַכְתָּשָׁא בְּבֵיתָא סְגִירוּת מְחַסְרָא הִיא בְּבֵיתָא מְסָאָב הוּא:
@411 וִיתָרַע יָת בֵּיתָא יָת אַבְנוֹהִי וְיָת אָעוֹהִי וְיָת כָּל עֲפַר בֵּיתָא וְיַפֵּק לְמִבָּרָא לְקַרְתָּא לַאֲתַר מְסָאָב:
@412 וּדְיֵיעוֹל לְבֵיתָא כָּל יוֹמִין דְיַסְגַר יָתֵהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@413 וּדְיִשְׁכּוּב בְּבֵיתָא יְצַבַּע יָת לְבוּשׁוֹהִי וּדְיֵיכוּל בְּבֵיתָא יְצַבַּע יָת לְבוּשׁוֹהִי:
@414 וְאִם מֵעַל יֵיעוֹל כַּהֲנָא וְיֶחֱזֵי וְהָא לָא אוֹסֵף מַכְתָּשָׁא בְּבֵיתָא בָּתַר דְאִתְּשַׁע יָת בֵּיתָא וידַכֵּי כַהֲנָא יָת בֵּיתָא אֲרֵי אִתַּסִי מַכְתָּשָׁא:
@415 וְיִסַב לְדַכָּאָה יָת בֵּיתָא תַּרְתֵּין צִפֲּרִין וְאָעָא דְאַרְזָא וּצְבַע זְהוֹרִי וְאֵזוֹבָא:
@416 וְיִכּוֹס יָת צִפֲּרָא חֲדָא לְמַאן דַחֲסַף עַל מֵי מַבּוּעַ:
@417 וְיִסַב יָת אָעָא דְאַרְזָא וְיָת אֵזוֹבָא וְיָת צְבַע זְהוֹרִי וְיָת צִפֲּרָא חַיְתָא וְיִטְבּוֹל יָתְהוֹן בִּדְמָא דְצִפֲּרָא דִנְכִיסָא וּבְמֵי מַבּוּעַ וְיַדִי לְבֵיתָא שְׁבַע זִמְנִין:
@418 וִידַכֵּי יָת בֵּיתָא בִּדְמָא דְצִפֲּרָא וּבְמֵי מַבּוּעַ וּבְצִפֲּרָא חַיְתָא וּבְאָעָא דְאַרְזָא וּבְאֵזוֹבָא וּבִצְבַע זְהוֹרִי:
@419 וִישַׁלַח יָת צִפֲּרָא חַיְתָא לְמִבָּרָא לְקַרְתָּא לְאַפֵּי חַקְלָא וִיכַפֵּר עַל בֵּיתָא וְיִדְכֵּי:
@420 דָא אוֹרַיְתָא לְכָל מַכְתַּשׁ סְגִירוּתָא וּלְנִתְקָא:
@421 וְלִסְגִירוּת לְבוּשָׁא וּלְבֵיתָא:
@422 וּלְעַמְקָא וּלְעַדְיָא וּלְבַהֲרָא:
@423 לְאַלָפָא בְּיוֹמָא מְסָאָבָא וּבְיוֹמָא דַכְיָא דָא אוֹרַיְתָא דִסְגִירוּתָא:
@424 וּמַלִיל יְיָ עִם מֹשֶׁה וְעִם אַהֲרֹן לְמֵימָר:
@425 מַלִילוּ עִם בְּנֵי יִשְׂרָאֵל וְתֵימְרוּן לְהוֹן גְבַר גְבַר אֲרֵי יְהֵי דָאִיב מִבִּשְׂרֵהּ דוֹבֵהּ מְסָאָב הוּא:
@426 וְדָא תְּהֵי סוֹבְתֵהּ בְּדוֹבֵהּ רָר בִּשְׂרֵהּ יָת דוֹבֵהּ אוֹ חָתִים בִּשְׂרֵהּ מִדוֹבֵהּ סוֹבְתֵהּ הִיא:
@427 כָּל מִשְׁכְּבָא דִי יִשְׁכּוּב עֲלוֹהִי דוֹבָנָא יְהֵי מְסָאָב וְכָל מָנָא דְיֵיתֵב עֲלוֹהִי יהֵי מְסָאָב:
@428 וּגְבַר דִי:יִקְרַב בְּמִשְׁכְּבֵהּ יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@429 וּדְיֵיתֵב עַל מָנָא דְיֵיתֵב עֲלוֹהִי דוֹבָנָא יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@430 וּדְיִקְרַב בִּבְסַר דוֹבָנָא יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@431 וַאֲרֵי יֵרוֹק דוֹבָנָא בְּדַכְיָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָּׁא:
@432 וְכָל מֶרְכְּבָא דִי יִרְכּוּב עֲלוֹהִי דוֹבָנָא יְהֵי מְסָאָב:
@433 וְכָל דְיִקְרַב בְּכֹל דִי יְהֵי תְחוֹתוֹהִי יְהֵי מְסָאָב עַד רַמְשָׁא וּדְיִטוֹל יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@434 וְכֹל דִי יִקְרַב בֵּהּ דוֹבָנָא וִידוֹהִי לָא שְׁטַף בְּמַיָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@435 וּמָאן דַחֲסַף דִי יִקְרַב בֵּהּ דוֹבָנָא יִתָּבָר וְכָל מָאן דְאָע יִשְׁתַּטַּף בְּמַיָא:
@436 וַאֲרֵי יִדְכֵּי דוֹבָנָא מִדוֹבֵהּ וְיִמְנֵי לֵהּ שִׁבְעַת יוֹמִין לְדָכוּתֵהּ וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בִשְׂרֵהּ בְּמֵי מַבּוּעַ וְיִדְכֵּי:
@437 וּבְיוֹמָא תְמִינָאָה יִסַב לֵהּ תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה וְיֵיתֵי לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא וְיִתְּנִנוּן לְכַהֲנָא:
@438 וְיַעְבֵּד יָתְהוֹן כַּהֲנָא חָד חַטָאתָא וְחָד עֲלָתָא וִיכַפֵּר עֲלוֹהִי כַהֲנָא קֳדָם יְיָ מִדוֹבֵהּ:
@439 וּגְבַר אֲרֵי תִפוֹק מִנֵהּ שִׁכְבַת זַרְעָא וְיַסְחֵי בְמַיָא יָת כָּל בִּשְׂרֵהּ וִיהֵי מְסָאָב עַד רַמְשָׁא:
@440 וְכָל לְבוּשׁ וְכָל מְשַׁךְ דִי יְהֵי עֲלוֹהִי שִׁכְבַת זַרְעָא וְיִצְטַבַּע בְּמַיָא וִיהֵי מְסָאָב עַד רַ:משָׁא:
@441 וְאִתְּתָא דִי יִשְׁכּוּב גְבַר יָתָהּ שִׁכְבַת זַרְעָא וְיַסְחוּן בְּמַיָא וְיִסְאֲבוּן עַד רַמְשָׁא:
@442 וְאִתְּתָא אֲרֵי תְהֵי דָיְבָא דָם יְהֵי דוֹבָהּ בְּבִשְׂרָהּ שִׁבְעָא יוֹמִין תְּהֵי בְרִחוּקָהּ וְכָל דְיִקְרַב בָּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@443 וְכֹל דִי תִשְׁכּוּב עֲלוֹהִי בְּרִחוּקָהּ יְהֵי מְסָאָב וְכֹל דִי תֵיתֵב עֲלוֹהִי יְהֵי מְסָאָב:
@444 וְכָל דְיִקְרַב בְּמִשְׁכְּבָהּ יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@445 וְכָל דְיִקְרַב בְּכָל מָנָא דִי תֵיתֵב עֲלוֹהִי יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@446 וְאִם עַל מִשְׁכְּבָא הוּא אוֹ עַל מָנָא דִי הִיא יָתְבָא עֲלוֹהִי בְּמִקְרְבֵהּ בֵּהּ יְהֵי מְסָאָב עַד רַמְשָׁא:
@447 וְאִם מִשְׁכַּב יִשְׁכּוּב גְבַר יָתָהּ וּתְהֵי רִחוּקָהּ עֲלוֹהִי וִיהֵי מְסָאָב שִׁבְעַת יוֹמִין וְכָל מִשְׁכָּב דִי יִשְׁכּוּב עֲלוֹהִי יְהֵי מְסָאָב:
@448 וְאִתְּתָא אֲרֵי יְדוּב דוֹב דְמָהּ יוֹמִין סַגִיאִין בְּלָא עִדַן רִחוּקָהּ אוֹ אֲרֵי תְדוּב עַל רִחוּקָהּ כָּל יוֹמֵי דוֹב סוֹבְתָהּ כְּיוֹמֵי רִחוּקָהּ תְּהֵי מְסָאֳבָא הִיא:
@449 כָּל מִשְׁכְּבָא דִי תִשְׁכּוּב עֲלוֹהִי כָּל יוֹמֵי דוֹבָהּ כְּמִשְׁכַּב רִחוּקָהּ יְהֵי לָהּ וְכָל מָנָא דִי תֵתֵב עֲלוֹהִי מְסָאָב יְהֵי כְּסוֹאֲבַת רִחוּקָהּ:
@450 וְכָל דְיִקְרַב בְּהוֹן יְהֵי מְסָאָב וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא:
@451 וְאִם דְכִיאַת מִדוֹבָהּ וְתִמְנֵי לָהּ שִׁבְעַת יוֹמִין וּבָתַר כֵּן תִדְכֵּי:
@452 וּבְיוֹמָא תְמִינָאָה תִּסַב לָהּ תַּרְתֵּין שַׁפְנִינִין אוֹ תְרֵין בְּנֵי יוֹנָה וְתַיְתִי יָתְהוֹן לְוָת כַּהֲנָא לִתְרַע מַשְׁכַּן זִמְנָא:
@453 וְיַעְבֵּד כַּהֲנָא יָת חָד חַטָאתָא וְיָת חָד עֲלָתָא וִיכַפֵּר עֲלָהּ כַּהֲנָא קֳדָם יְיָ מִדוֹב סוֹבְתָהּ:
@454 וְתַפְרְשׁוּן יָת בְּנֵי יִשְׂרָאֵל מִסוֹאֲבַתְהוֹן וְלָא יְמוּתוּן בְּסוֹאֲבַתְהוֹן בְּסָאָבְהוֹן יָת מַשְׁכְּנִי דִי בֵינֵיהוֹן:
@455 דָא אוֹרַיְתָא דְדוֹבָנָא וְדִי תִפּוֹק מִנֵהּ שִּׁכְבַת זַרְעָא לְאִסְתָּאָבָא בָהּ:
@456 וְלִדְסוֹבְתָה בְּרִחוּקָהּ וְלִדְדָאִיב יָת דוֹבֵהּ לִדְכַר וּלְנֻקְבָא וְלִגְבַר דִי יִשְׁכּוּב עִם מְסָאָבָא: פפפ:
@457 וּמַלֵיל יְיָ עִם מֹשֶׁה בָּתַר דְמִיתוּ תְּרֵין בְּנֵי אַהֲרֹן בְּקָרוֹבֵיהוֹן אֶשָׁתָא נוּכְרֵיתָא קֳדָם יְיָ וּמִיתוּ:
@458 וַאֲמַר יְיָ לְמֹשֶׁה מַלֵל עִם אַהֲרֹן אָחוּךְ וְלָא יְהֵי עָלֵל בְּכָל עִדָן לְקוּדְשָׁא מִגָיו לְפָרֻכְתָּא לָקֳדָם כַּפֻּרְתָּא דִי עַל אֲרוֹנָא וְלָא יְמוּת אֲרֵי בַּעֲנָנָא אֲנָא מִתְגְלִי עַל בֵּית כַּפֻּרְתָּא:
@459 בְּדָא יְהֵי עָלֵל אַהֲרֹן לְקוּדְשָׁא בְּתוֹר בַּר תּוֹרֵי לְחַטָּאתָא וּדְכַר לַעֲלָתָא:
@460 כִּתּוּנָא דְבוּצָא קוּדְשָׁא יִלְבָּשׁ וּמִכְנְסִין דְבוּץ יְהוֹן עַל בִּסְרֵהּ וּבְהֶמְיָנָא דְבוּץ יֵסַר וּבְמִצְנֶפְתָּא דְבוּצָא יָחֵת בְּרֵישֵׁהּ לְבוּשֵׁי קוּדְשָׁא אִנוּן וְיַסְחֵי בְמַיָא יָת בִּ:סרֵהּ וְיַלְבְּשִׁנוּן:
@461 וּמִן כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל יִסַב תְּרֵין צְפִירֵי עִזִין לְחַטָאתָא וּדְכַר חַד לַעֲלָתָא:
@462 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָּאתָא דִי לֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ:
@463 וְיִסַב יָת תְּרֵין צְפִירִין וִיקִים יָתְהוֹן קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@464 וְיִתֵּן אַהֲרֹן עַל תְּרֵין צְפִירִין עַדְבִין עַדְבָא חַד לִשְׁמָא דַיְיָ וְעַדְבָא חַד לַעֲזָאזֵל:
@465 וִיקָרֵב אַהֲרֹן יָת צְפִירָא דִי סְלִיק עֲלוֹהִי עַדְבָא לִשְׁמָא דַיְיָ וְיַעְבְּדִנֵהּ חַטָאתָא:
@466 וּצְפִירָא דִי סְלִיק עֲלוֹהִי עַדְבָא לַעֲזָאזֵל יִתָּקַם כַּד חַי קֳדָם יְיָ לְכַפָּרָא עֲלוֹהִי לְשַׁלַח יָתֵהּ לַעֲזָאזֵל לְמַדְבְּרָא:
@467 וִיקָרֵב אַהֲרֹן יָת תּוֹרָא דְחַטָאתָא דִי לֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ וְיִכּוֹס יָת תּוֹרָא דְחַטָאתָא דִי לֵהּ:
@468 וְיִסַב מְלֵי מַחְתִּיתָא גוּמְרִין דְאֶשָׁא מֵעִלַוֵי מַדְבְּחָא מִן קֳדָם יְיָ וּמְלֵי חָפְנוֹהִי קְטוֹרֶת בּוּסְמִין דַקִיקִין וְיָעֵל מִגָיו לְפָרֻכְתָּא:
@469 וְיִתֵּן יָת קְטוֹרֶת בּוּסְמַיָא עַל אֶשָׁתָא לָקֳדָם יְיָ וְחָפֵי עֲנָנָא קְטָרְתָּא יָת כַּפֻּרְתָּא דִי עַל סַהֲדוּתָא וְלָא יְמוּת:
@470 וְיִסַב מִדְמָא דְתוֹרָא וְיַדֵי בְאֶצְבְּעֵהּ עַל אַפֵּי כַּפּוּרְתָּא קִדוּמָא וְלָקֳדָם כַּפֻּרְתָּא יַדִי שְׁבַע זִמְנִין מִן דְמָא בְּאֶצְבְּעֵהּ:
@471 וְיִכּוֹס יָת צְפִירָא דְחַטָאתָא דִי לְעַמָא וְיָעֵל יָת דְמֵהּ לְמִגָיו לְפָרֻכְתָּא וְיַעְבֵּד לִדְמֵהּ כְּמָא דִי עֲבַּד לִדְמָא דְתוֹרָא וְיַדִי יָתֵהּ עַל כַּפֻּרְתָּא וְלָקֳדָם כַּפֻּרְתָּא:
@472 וִיכַפֵּר עַל קוּדְשָׁא מִסוֹאֲבַת בְּנֵי יִשְׂרָאֵל וּמִמֶרְדֵיהוֹן לְכָל חֲטָאֵיהוֹן וְכֵן יַעְבֵּד לְמַשְׁכַּן זִמְנָא דְשָׁרֵי עִמְהוֹן בְּגוֹ סוֹאֲבָתְהוֹן:
@473 וְכָל אֱנַשׁ לָא יְהֵי בְּמַשְׁכַּן זִמְנָא בְּמֵעֲלֵהּ לְכַפָּרָא בְקוּדְשָׁא עַד מִפְּקֵהּ וִיכַפֵּר עֲלוֹהִי וְעַל אֱנַשׁ בֵּיתֵהּ וְעַל כָּל קְהָלָא דְיִשְׂרָאֵל:
@474 וְיִפּוֹק לְמַדְבְּחָא דִי קֳדָם יְיָ וִיכַפֵּר עֲלוֹהִי וְיִסַב מִדְמָא דְתוֹרָא וּמִדְמָא דִצְפִירָא וְיִתֵּן עַל קַרְנַת מַדְבְּחָא סְחוֹר סְחוֹר:
@475 וְיַדֵי עֲלוֹהִי מִן דְמָא בְּאֶצְבְּעֵהּ שְׁבַע זִמְנִין וִידַכִּנֵהּ וִיקַדְשִׁנֵהּ מִסוֹאֲבַת בְּנֵי יִשְׂרָאֵל:
@476 וִישֵׁיצֵי מִלְכַפָּרָא עַל קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא וִיקָרֵב יָת צְפִירָא חַיָא:
@477 וְיִסְמוֹךְ אַהֲרֹן יָת תַּרְתֵּין יְדוֹהִי עַל רֵישׁ צְפִירָא חַיָא וִיוַדֵי עֲלוֹהִי יָת כָּל עֲוָיַת בְּנֵי יִשְׂרָאֵל וְיָת כָל מֶרְדֵיהוֹן לְכָל חֲטָּאֵיהוֹן וְיִתֵּן יָתְהוֹן עַל רֵישׁ צְפִירָא וִישַׁלַח בְּיַד גְבַר דִזְמִין לִמְהַךְ לְמַדְבְּרָא:
@478 וְיִטוֹל צְפִירָא עֲלוֹהִי יָת כָּל חוֹבֵיהוֹן לְאַרְעָא דְלָא יָתְבָא וִישַׁלַח יַת צְפִירָא בְּמַדְבְּרָא:
@479 וְיֵיעוֹל אַהֲרֹן לְמַשְׁכַּן זִמְנָא וְיַשְׁלַח יָת לְבוּשֵׁי בוּצָא דִי לְבַשׁ בְּמֵעֲלֵהּ לְקוּדְשָׁא וְיַצְנִעוּן תַּמָן:
@480 וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא בַּאֲתַר קַדִישׁ וְיִלְבַּשׁ יָת לְבוּשׁוֹהִי וְיִפּוֹק וְיַעְבֵּד יָת עֲלָתֵהּ וְיָת עֲלַת עַמָא וִיכַפַּר עֲלוֹהִי וְעַל עַמָּא:
@481 וְיָת תַּרְבָּא דְחַטָאתָא יַסֵק לְמַדְבְּחָא:
@482 וּדְמוֹבִיל יָת צְפִירָא לַעֲזָאזֵל יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וּבָתַר כֵּן יֵיעוֹל לְמַשְׁרִיתָא:
@483 וְיָת תּוֹרָא דְחַטָאתָא וְיָת צְפִירָא דְחַטָאתָא דִי אִתָּעַל מִדִמְהוֹן לְכַפָּרָא בְקוּדְשָׁא יִתַּפְּקוּן לְמִבָּרָא לְמַשְּׁרִיתָא וְיוֹקְדוּן בְּנוּרָא יָת מַשְׁכֵּיהוֹן וְיָת בִּסְרְהוֹן וְיָת אָכְלֵיהוֹן:
@484 וּדְמוֹקִיד יָתְהוֹן יְצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי יָת בִּסְרֵהּ בְּמַיָא וּבָתַר כֵּן יֵיעוֹל למַשְׁרִיתָא:
@485 וּתְהֵי:לְכוֹן לִקְיַם עָלָם בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא תְּעַנוּן יָת נַפְשָׁתֵיכוֹן וְכָל עִבִידָא לָא תַעְבְּדוּן יַצִיבָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@486 אֲרֵי בְיוֹמָא הָדֵין יְכַפֵּר עֲלֵיכוֹן לְדַכָּאָה יָתְכוֹן מִכָּל חוֹבֵיכוֹן קֳדָם יְיָ תִּדְכּוּן:
@487 שְׁבַת שְׁבָתָא הִיא לְכוֹן וּתְעַנוּן יָת נַפְשָּׁתֵיכוֹן קְיַם עֲלָם:
@488 וִיכַפֵּר כַּהֲנָא דִי רַבִּי יָתֵהּ וְדִי יְקָרֵב יָת קֻרְבָּנֵהּ לְשַׁמָשָׁא תְּחוֹת אֲבוּהִי וְיִלְבַּשׁ יָת לְבוּשֵׁי בוּצָא:לבוּשֵׁי קוּדְשָׁא:
@489 וִיכַפֵּר עַל מִקְדַשׁ קוּדְשָׁא וְעַל מַשְׁכַּן זִמְנָא וְעַל מַדְבְּחָא יְכַפַּר וְעַל כַּהֲנַיָא וְעַל כָּל עַמָא דִקְהָלָא יְכַפַּר:
@490 וּתְהֵי דָא לְכוֹן לִקְיַם עָלָם לְכַפָּרָא עַל בְּנֵי יִשְׂרָאֵל מִכָּל חוֹבֵיהוֹן חֲדָא בְּשַׁתָּא וַעֲבַד כְּמָא דִי פַּקִיד יְיָ יָת מֹשֶׁה:
@491 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@492 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן דֵין פִּתְגָמָא דִי פַקִיד יְיָ לְמֵימָר:
@493 גְבַר גְבַר מִבֵּית יִשְׂרָאֵל דִי יִכּוֹס תּוֹר אוֹ אִמַר אוֹ עִזָא בְּמַשְׁרִיתָא אוֹ דִי יִכּוֹס מִבָּרָא לְמַשְׁרִיתָא:
@494 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתֵהּ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ קֳדָם מַשְׁכְּנָא דַיְיָ דְמָא יִתְחַשַׁב לְגַבְרָא הַהוּא דְמָא אֲשַׁד וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מִגוֹ עַמֵהּ:
@495 בְּדִיל דִי יַיְתוּן בְּנֵי יִשְׂרָאֵל יָת דִבְחֵיהוֹן דִי אִנוּן דָבְחִין עַל אַפֵּי חַקְלָא וְיַיְתוּנוּן לָקֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא לְוָת כַּהֲנָא וְיִכְסוּן נִכְסַת קוּדְשִׁין קֳדָם יְיָ יָתְהוֹן:
@496 וְיִזְרוֹק כַּהֲנָא יָת דְמָא עַל מַדְבְּחָא דַיְיָ בִּתְרַע מַשְׁכַּן זִמְנָא וְיַסֵק תַּרְבָּא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ:
@497 וְלָא יִדְבְּחוּן עוֹד יָת דִבְחֵיהוֹן לַשֵׁדִין דִי אִנוּן טָעָן בַּתְרֵיהוֹן קְיַם עָלָם תְּהֵי דָא לְהוֹן לְדָרֵיהוֹן:
@498 וּלְהוֹן תֵּימַר גְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יַסֵק עֲלָתָא אוֹ נִכְסַת קוּדְשַׁיָא:
@499 וְלִתְרַע מַשְׁכַּן זִמְנָא לָא אַיְתִנֵהּ לְמֶעְבַּד יָתֵהּ קֳדָם יְיָ וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵהּ:
@500 וּגְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יֵיכוּל כָּל דְמָא וְאֶתֵּן רוּגְזִי בַּאֲנָשָׁא דְיֵיכוּל יָת דְמָא וֶאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ:
@501 אֲרֵי נְפַשׁ בִּסְרָא בִּדְמָא הִיא וַאֲנָא יְהָבִתֵּהּ לְכוֹן עַל מַדְבְּחָא לְכַפָּרָא עַל נַפְשָׁתֵיכוֹן אֲרֵי דְמָא הוּא עַל נַפְשָׁא מְכַפֵּר:
@502 עַל כֵּן אֲמָרִית לִבְנֵי יִשְׂרָאֵל כָּל אֱנַשׁ מִנְכוֹן לָא יֵיכוּל דְמָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן לָא יֵיכוּל דְמָא:
@503 וּגְבַר גְבַר מִן בְּנֵי יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן דִי יְצוּד צֵידָא חַיְתָא אוֹ עוֹפָא דִי מִתְאֲכֵל וְיֵשׁוֹד יָת דְמֵהּ וִיכַסִנֵהּ בְּעַפְרָא:
@504 אֲרֵי נְפַשׁ כָּל בִּסְרָא דְמֵהּ בְּנַפְשֵׁהּ הוּא וַאֲמָרִית לִבְנֵי יִשְׂרָאֵל דַם כָּל בִּסְרָא לָא תֵיכְלוּן אֲרֵי נְפַשׁ כָּל בִּסְרָא דְמֵהּ הִיא כָּל דְיֵיכְלִנֵהּ יִשְׁתֵּיצֵי:
@505 וְכָל אֱנַשׁ דִי יֵיכוּל נְבִילָא וּתְבִירָא בְּיַצִיבָא וּבְגִיוֹרָא וִיצַבַּע לְבוּשׁוֹהִי וְיַסְחֵי בְמַיָא וִיהֵי מְסָאָב עַד רַמְשָׁא וְיִדְכֵּי:
@506 וְאִם לָא יְצַבַּע וּבִסְרֵהּ לָא יַסְחֵי וִיקַבֵּל חוֹבֵהּ:
@507 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@508 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@509 כְּעוֹבָדֵי עַמָא דְאַרְעָא דְמִצְרַיִם דִי יְתֶבְתּוּן בַּהּ לָא תַעְבְּדוּן וּכְעוֹבָדֵי עַמָא דְאַרְעָא דִכְנַעַן דִי אֲנָא מָעֵל יָתְכוֹן תַּמָן לָא תַעְבְּדוּן וּבְנִימוֹסֵיהוֹן לָא תְהָכוּן:
@510 יָת דִינַי תַּעְבְּדוּן וְיָת קְיָמַי תִּטְרוּן לְהַלָכָא בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@511 וְתִטְרוּן יָת קְיָמַי וְיָת דִינַי דִי יַעְבֵּד יָתְהוֹן אֲנָשָׁא וְיֵחֵי בְהוֹן לְחַיֵי עָלְמָא אֲנָא יְיָ:
@512 גְבַר גְבַר לְכָל קָרִיב בִּסְרֵהּ לָא תִקְרְבוּן לְגַלָאָה עֶרְיָא אֲנָא יְיָ:
@513 עֶרְיַת אֲבוּךְ וְעֶרְיַת אִמָךְ לָא תְגַלֵי אִמָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@514 עֶרְיַת אִתַּת אָבוּךְ לָא תְגַלֵי עֶרְיַת אָבוּךְ הִיא:
@515 עֶרְיַת אֲחָתָךְ בַּת אֲבוּךְ אוֹ בַת אִמָךְ דִילִידָא מִן אֲבוּךְ מִן אִתַּת אָחֳרִי אוֹ מִן אִמָךְ לִגְבַר אָחֳרָן לָא תְגַלֵי עֶרְיַתְהֶן:
@516 עֶרְיַת בַּת בְּרָךְ אוֹ בַת בְּרַתָּךְ לָא תְגַלֵי עֶרְיַתְהֶן אֲרֵי עֶרְיְתָךְ אִנוּן:
@517 עֶרְיַת בַּת אִתַּת אֲבוּךְ דִילִידָא מִן אֲבוּךְ אֲחָתָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@518 עֶרְיַת אֲחַת אֲבוּךְ לָא תְגַלֵי קָרִיבַת אֲבוּךְ הִיא:
@519 עֶרְיַת אֲחַת אִמָךְ לָא תְגַלֵי אֲרֵי קָרִיבַת אִמָךְ הִיא:
@520 עֶרְיַת אַח אֲבוּךְ לָא תְגַלֵי לְאִתְּתֵהּ לָא תִקְרַב אִתַּת אַח אֲבוּךְ הִיא:
@521 עֶרְיַת כַּלָתָךְ לָא תְגַלֵי אִתַּת בְּרָךְ הִיא לָא תְגַלֵי עֶרְיָתָהּ:
@522 עֶרְיַת אִתַּת אֲחוּךְ לָא תְגַלֵי עֶרְיַת אֲחוּךְ הִיא:
@523 עֶרְיַת אִתְּתָא וּבְרַתָּהּ לָא תְגַלֵי יָת בַּת בְּרָהּ וְיָת בַּת בְּרַתָּהּ לָא תִםַב לְגַלָאָה עֶרְיָתָהּ קָרִיבָן אִנוּן עֵצַת חִטְאִין הִיא:
@524 וְאִתְּתָא עִם אֲחָתָהּ לָא תִסָב לְעָקָאָה לְגַלָאָה עֶרְיְתָהּ עֲלָהּ בְּחַיָיהָא:
@525 וּלְאִתְּתָא בְּרִחוּק סוֹבְתַהּ לָא תִקְרַב לְגַלָאָה עֶרְיְתָהּ:
@526 וּבְאִתַּת חַבְרָךְ לָא תִתֵּן שְׁכֻבְתָּךְ לְזַרְעָא לְאִסְתָּאָבָא בָהּ:
@527 וּמִבְּנָיִךְ לָא תִתֵּן לְאַעְבָּרָא לְמוֹלֶךְ וְלָא תַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@528 וְעִם דְכוּרָא לָא תִשְׁכּוּב מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא הִיא:
@529 וּבְכָל בְּעִירָא לָא תִתֵּן שְׁכֻבְתָּךְ לְאִסְתָּאָבָא בָהּ וְאִתְּתָא לָא תְקוּם קֳדָם בְּעִירָא לְמִשְׁלַט בָּהּ תִּבְלָא הוּא:
@530 לָא תִסְתַּאֲבוּן בְּכָל אִלֵין אֲרֵי בְּכָל אִלֵין אִסְתַּאָבוּ עַמְמַיָא דִי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן:
@531 וְאִסְתָּאָבַת אַרְעָא וְאַסְעָרִית חוֹבָהּ עֲלָהּ וְרוֹקֵינַת אַרְעָא יָת יָתְבָהָא:
@532 וְתִטְרוּן אַתּוּן יָת קְיָמַי וְיָת דִינַי וְלָא תַעְבְּדוּן מִכֹּל תּוֹעֶבְתָּא הָאִלֵין יַצִיבָא וְגִיוֹרָא דְיִתְגַיְרוּן בֵּינֵיכוֹן:
@533 אֲרֵי יָת כָּל תּוֹעֶבְתָּא הָאִלֵין עֲבָדוּ אֱנָשֵׁי אַרְעָא דִי קֳדָמֵיכוֹן וְאִסְתָּאָבַת אַרְעָא:
@534 וְלָא תְרוֹקֵן אַרְעָא יָתְכוֹן בְּסָאֳבֵיכוֹן יָתָהּ כְּמָא דְרוֹקֵינַת יָת עַמְמַיָא דִי קֳדָמֵיכוֹן:
@535 אֲרֵי כָּל דִי יַעְבֵּד מִכֹּל תּוֹעֶבְתָּא הָאִלֵין וְיִשְׁתֵּיצוּן נַפְשָׁתָא דְיַעְבְּדוּן מִגוֹ עַמְהוֹן:
@536 וְתִטְרוּן יָת מַטְרַת מֵימְרִי בְּדִיל דְלָא לְמֶעְבַּד מִנִימוֹסֵי תוֹעֶבְתָּא דְאִתְעֲבָדָא קֳדָמֵיכוֹן וְלָא תִסְתַּאֲבוּן בְּהוֹן אֲנָא יְיָ אֱלָהָכוֹן: פפפ:
@537 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@538 מַלֵל עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן קַדִישִׁין תְּהוֹן אֲרֵי קַדִישׁ אֲנָא יְיָ אֱלָהָכוֹן:
@539 גְבַר מִן אִמֵהּ וּמִן אֲבוּהִי תְּהוֹן דָחֲלִין וְיָת יוֹמֵי שַׁבַּיָא דִילִי תִּטְרוּן אֲנָא יְיָ אֱלָהָכוֹן:
@540 לָא תִתְפְּנוּן בָּתַר טַעֲוָן וְדַחֲלָן דְמַתְּכָא לָא תַעְבְּדוּן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@541 וַאֲרֵי תִכְסוּן נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְסֻנֵהּ:
@542 בְּיוֹמָא דְיִתְנְכֵס יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר עַד יוֹמָא תְלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@543 וְאִם אִתְאֲכָלָא יִתְאֲכֵל בְּיוֹמָא תְלִיתָאָה מְרָחַק הוּא לָא יְהֵי לְרַעַוָא:
@544 וּדְיֵיכְלִנֵהּ חוֹבֵהּ יְקַבֵּל אֲרֵי יָת קוּדְשָׁא דַיְיָ אַחֵל וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵהּ:
@545 וּבְמֶחְצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ לְמֶחְצָד וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵט:
@546 וְכַרְמָךְ לָא תְעַלֵל וְנִתְרָא דְכַרְמָךְ לָא תְלַקֵט לְעַנְיֵי וּלְגִיוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@547 לָא תִּגְנְבוּן וְלָא תְכַדְבוּן וְלָא תְשַׁקְרוּן אֱנַשׁ בְּחַבְרֵהּ:
@548 וְלָא תִשָׁבְעוּן בִּשְׁמִי לְשִׁקְרָא וְתַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@549 לָא תַעֲשׁוֹק יָת חַבְרָךְ וְלָא תְאַנֵס לָא תְבִית אַגְרָא דַאֲגִירָא לְוָתָךְ עַד צַפְרָא:
@550 לָא תְלוּטּ דְלָא שָׁמַע וְקֳדָם דְלָא חָזֵי לָא תְשִׂים תַּקְלָא וְתִדְחַל מֵאֱלָהָךְ אֲנָא יְיָ:
@551 לָא תַעְבְּדוּן שְׁקַר בְּדִינָא לָא תִסַב אַפֵּי מַסְכֵּנָא וְלָא תֶהְדַר אַפֵּי רַבָּא בְּקוּשְׁטָא תְּדִינֵהּ לְחַבְרָךְ:
@552 לָא תֵיכוּל קוּרְצִין בְּעַמָךְ לָא תְקוּם עַל דְמָא דְחַבְרָךְ אֲנָא יְיָ:
@553 לָא תִשְׂנֵי יָת אֲחוּךְ בְּלִבָּךְ אוֹכָחָא תוֹכַח יָת חַבְרָךְ וְלָא תְקַבֵּל עַל דִי לֵהּ חוֹבָא:
@554 לָא תִקוֹם וְלָא תִטַר דְבָבוּ לִבְנֵי עַמָךְ וּתְרַחֵם לְחַבְרָךְ כְּוָתָךְ אֲנָא יְיָ:
@555 יָת קְיָמַי תִּטְרוּן בְּעִירָךְ לָא תַרְכֵּב עֵרוּבִין חַקְלָךְ לָא תִזְרַע עֵרוּבִין וּלְבוּשׁ עֵרוּבִין שַׁעַטְנֵזָא לָא יִסַק עֲלָךְ:
@556 וּגְבַר אֲרֵי יִשְׁכּוּב עִם אִתְּתָא שִׁכְבַת זַרְעָא וְהִיא אַמְתָא אֲחִידָא לִגְבַר וְאִתְפְּרָקָא לָא אִתְפְּרִיקַת בְּכַסְפָּא אוֹ חֵרוּתָא לָא אִתְיְהִיבַת לַהּ בִּשְׁטָר בִּקֻּרְתָּא תְהֵי לָא יוּמְתוּן אֲרֵי לָא אִתְחָרָרַת:
@557 וְיַיְתִי יָת אַשְׁמֵהּ קֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא דְכַר לַאֲשָׁמָא:
@558 וִיכַפֵּר עֲלוֹהִי כַּהֲנָא בְּדִכְרָא דַאֲשָׁמָא קֳדָם יְיָ עַל חוֹבְתֵהּ דִי חָב וְיִשְׁתְּבֵק לֵהּ מְחוֹבְתֵהּ דִי חַב:
@559 וַאֲרֵי תֵעֲלוּן לְאַרְעָא וְתִצְבוּן כָּל אִלָן דְמֵיכַל וּתְרַחֲקוּן רָחָקָא יַת אִבֵּהּ תְּלַת שְׁנִין יְהֵי לְכוֹן מְרָחָק לַאֲבָדָא לָא יִתְאֲכֵל:
@560 וּבְשַׁתָּא רְבִיעֵתָא יְהֵי כָּל אִבֵּהּ קֹדֶשׁ תּוּשְׁבְּחָן קֳדָם יְיָ:
@561 וּבְשַׁתָּא חֲמִישֵׁתָא תֵּיכְלוּן יָת אִבֵּהּ לְאוֹסָפָא לְכוֹן עֲלַלְתֵּהּ אֲנָא יְיָ אֱלָהָכוֹן:
@562 לָא תֵיכְלוּן עַל דְמָא לָא תְנַחֲשׁוּן וְלָא תְעוֹנוּן:
@563 לָא תַקְפוּן פָּאתָא דְרֵישְׁכוֹן וְלָא תְחַבֵּל יָת פָּאתָא דְדִקְנָךְ:
@564 וְחִבּוּל עַל מִית לָא תִתְּנוּן בְּבִסְרְכוֹן וְרוּשְׁמִין חֲרִיתִין לָא תִתְּנוּן בְכוֹן אֲנָא יְיָ:
@565 לָא תַחֵל יָת בְּרַתָּךְ לְאַטְעֲיוּתַהּ וְלָא תִטְעֵי אַרְעָא וְתִתְמְלֵי אַרְעָא עֵצַת חִטְאִין:
@566 יָת יוֹמֵי שַׁבַּיָא דִילִי תִּטְרוּן וּלְבֵית מַקְדְשִׁי תְּהוֹן דָחֲלִין אֲנָא יְיָ:
@567 לָא תִתְפְּנוּן בָּתַר בִּדִין וּדְכוּרוּ לָא תִתְבְּעוּן לְאִסְתָּאָבָא בְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@568 מִן קֳדָם דְסַבַּר בְּאוֹרַיְתָא תְּקוּם וּתְהַדַר אַפֵּי סָבָא וְתִדְחַל מֵאֳלָהָךְ אֲנָא יְיָ:
@569 וַאֲרֵי יִתְגַיַר עִמָךְ גִיוֹרָא בְּאַרְעֲכוֹן לָא תוֹנוּן יָתֵהּ:
@570 כְּיַצִיבָא מִנְכוֹן יְהֵי לְכוֹן גִיוֹרָא דְיִתְגַיַר בֵּינֵיכוֹן וּתְרַחֵם לֵהּ כְּוָתָךְ אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:
@571 לָא תַעְבְּדוּן שְׁקַר בְּדִין בִּמְשַׁחְתָּא בְּמַתְקְלָא וּבִמְכִלְתָּא:
@572 מֹאזְנָוָן דִקְשׁוֹט מַתְקְלָן דִקְשׁוֹט מְכִילָן דִקְשׁוֹט וְהִינִין דִקְשׁוֹט יְהוֹן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן דִי אֲפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@573 וְתִטְרוּן יָת כָּל קְיָמַי וְיָת כָּל דִינַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@574 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@575 וְלִבְנֵי יִשְׂרָאֵל תֵּימַר גְבַר גְבַר מִבְּנֵי יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בְּיִשְׂרָאֵל דִי יִתֵּן מִזַרְעֵהּ לְמוֹלֶךְ אִתְקְטָלָא יִתְקְטֵל עַמָא בֵית יִשְׂרָאֵל יִרְגְמֻנֵהּ בְּאַבְנָא:
@576 וַאֲנָא אֶתֵּן יָת רוּגְזִי בְגַבְרָא הַּהוּא וְאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ אֲרֵי מִזַרְעֵהּ יְהַב לְמוֹלֶךְ בְּדִיל לְסָאָבָא יָת מַקְדְשִׁי וּלְאַחַלָא יָת שְׁמָא דְקוּדְשִׁי:
@577 וְאִם מִכְבַּשׁ יִכְבְּשׁוּן עַמָא בֵית יִשְׂרָאֵל יָת עֵינֵיהוֹן מִן גַבְרָא הַהוּא בִּדְיָהֵב מִזַרְעֵהּ לְמוֹלֶךְ בְּדִיל דְלָא לְקַטָלָא יָתֵהּ:
@578 וֶאֱשַׁוֵי אֲנָא יָת רוּגְזִי בְגַבְרָא הַהוּא וּבִסְעָדוֹהִי וֶאֱשֵׁיצֵי יָתֵהּ וְיָת כָּל דְטָעָן בַּתְרוֹהִי לְמִטְעֵי בָּתַר מוֹלֶךְ מִגוֹ עַמְהוֹן:
@579 וֶאֱנַשׁ דִי יִתְפְּנֵי בָּתַר בִּדִין וּדְכוּרוּ לְמִטְעֵי בַתְרֵיהוֹן וְאֶתֵּן יָת רוּגְזִי בַּאֲנָשָׁא הַהִיא וֶאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ:
@580 וְתִתְקַדְשׁוּן וּתְהוֹן קַדִישִׁין אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@581 וְתִטְּרוּן יָת קְיָמַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא:ייָ מַקְדִשְׁכוֹן:
@582 אֲרֵי גְבַר גְבַר דִי יְלוּט יָת אֲבוּהִי וְיָת אִמֵהּ אִתְקְטָּלָא יִתְקְטֵל אֲבוּהִי וְאִמֵהּ לַטּ קְטָלָא חַיָב:
@583 וּגְבַר דִי יְגוּף יָת אִתַּת גְבַר דִי יְגוּף יָת אִתַּת חַבְרֵהּ אִתְקְטָלָא יִתְקְטֵל גַיָפָא וְגַיַפְתָּא:
@584 וּגְבַר דִי יִשְׁכּוּב עִם אִתַּת אֲבוּהִי עֶרְיְתָא דַאֲבוּהִי גַלִי אִתְקַטָלָא יִתְקַטְלוּן תַּרְוֵיהוֹן קְטָלָא חַיָבִין:
@585 וּגְבַר דִי יִשְׁכּוּב יָת כַּלָתֵהּ אִתְקְטָלָא יִתְקַטְלוּן תַּרְוֵיהוֹן תִּבְלָא עֲבָדוּ קְטָלָא חַיָבִין:
@586 וּגְבַר דִי יִשְׁכּוּב יָת דְכוּרָא מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא עֲבָדוּ תַּרְוֵיהוֹן אִתְקְטָלָא יִתְקַטְלוּן קְטָלָא חַיָבִין:
@587 וּגְבַר דִי יִסַב יָת אִתְּתָא וְיָת אִמַהּ עֵצַת חִטְאִין הִיא בְּנוּרָא יוֹקְדוּן יָתֵהּ וְיָתְהֶן וְלָא תְהֵי עֵצַת חִטְאִין בֵּינֵיכוֹן:
@588 וּגְבַר דִי יִתֵּן שְׁכָבְתֵּהּ בִּבְעִירָא אִתְקְטָלָא יִתְקְטֵל וְיָת בְּעִירָא תִּקְטְלוּן:
@589 וְאִתְּתָא דִי תִקְרַב לְכָל בְּעִירָא לְמִשְׁלַט בַּהּ וְתִקְטוֹל יָת אִתְּתָא וְיָת בְּעִירָא אִתְקְטָלָא יִתְקַטְלוּן קְטָלָא חַיָבִין:
@590 וּגְבַר דִי יִסַב יָת אֲחָתֵהּ בַּת אֲבוּהִי אוֹ בַת אִמֵהּ וְיֶחֱזֵי יָת עֶרְיְתַהּ וְהִיא תֶחֱזֵי יָת עֶרְיְתֵהּ קְלָנָא הוּא וְיִשְׁתֵּיצוּן לְעֵינֵי בְּנֵי עַמְהוֹן עֶרְיַת אֲחָתֵהּ גַלִי חוֹבֵהּ יְקַבֵּל:
@591 וּגְבַר דִי יִשְׁכּוּב יָת אִתְּתָא סוֹאֲבָתָא וִיגַלֵי יָת עֶרְיְתַהּ יָת קְלָנַהּ גַלִי וְהִיא תְגַלֵי יָת סוֹאֲבַת דְמָהָא וְיִשְׁתֵּיצוּן תַּרְוֵיהוֹן מִגוֹ עַמְהוֹן:
@592 וְעֶרְיַת אֲחַת אִמָךְ וַאֲחַת אָבוּךְ לָא תְגַלֵי אֲרֵי יָת קָרִיבֵהּ גַלִי חוֹבְהֶן יְקַבְּלוּן:
@593 וּגְבַר דִי יִשְׁכּוּב יָת אִתַּת אַח אֲבוּהִי עֶרְיַת אַח אֲבוּהִי גַלִי חוֹבְהֶן יְקַבְּלּוּן בְּלָּא וְלָד יְמוּתוּן:
@594 וּגְבַר דִי יִסַב יָת אִתַּת אֲחוּהִי מְרָחָקָא הִיא עֶרְיְתָא דַאֲחוּהִי גַלִי בְּלָא וְלָד יְהוֹן:
@595 וְתִטְרוּן יָת כָּל קְיָמַי וְיָת כָּל דִינַי וְתַעְבְּדוּן יָתְהוֹן וְלָא תְרוֹקֵן יָתְכוֹן אַרְעָא דִי אֲנָא מָעֵיל יָתְכוֹן תַּמָן לְמִתַּב בַּהּ:
@596 וְלָא תְהָכוּן בְּנִימוֹסֵי עַמְמַיָא דִי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן אֲרֵי יָת כָּל אִלֵין עֲבָדוּ וְרָחִיק מֵימְרִי יָתְהוֹן:
@597 וַאֲמָרִית לְכוֹן אַתּוּן תִּירְתוּן יָת אַרְעֲהוֹן וַאֲנָא אֶתְּנִנַהּ לְכוֹן לְמֵירַת יָתַהּ אַרְעָא עַבְדָא חַלָב וּדְבָשׁ אֲנָא יְיָ אֱלָהָכוֹן דִי אַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָא:
@598 וְתַפְרְשׁוּן בֵּין בְּעִירָא דַכְיָא לִמְסָאָבָא וּבֵין עוֹפָא מְסָאָבָא לִדְכֵי וְלָא תְשַׁקְצוּן יָת נַפְשָׁתֵיכוֹן בִּבְעִירָא וּבְעוֹפָא וּבְכֹל דִי תַרְחֵשׁ אַרְעָא דִי אַפְרֵשִׁית לְכוֹן לְסָאָבָא:
@599 וּתְהוֹן קֳדָמַי קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא יְיָ וְאַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָא לְמֶהֱוֵי פָלְחִין קֳדָמַי:
@600 וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בְהוֹן בִּדִין אוֹ דְכוּרוּ אִתְקְטָלָא יִתְקַטְלוּן בְּאַבְנָא יִרְגְמוּן יָתְהוֹן קְטָלָא חַיָבִין: פפפ:
@601 וַאֲמַר יְיָ לְמֹשֶׁה אֱמַר לְכַהֲנַיָא בְּנֵי אַהֲרֹן וְתֵימַר לְהוֹן עַל מִית לָא יִסְתָּאַב בְּעַמֵהּ:
@602 אֱלָהֵן לְקָרִיבֵהּ דְקָרִיב לֵהּ לְאִמֵהּ וְלַאֲבוּהִי וְלִבְרֵהּ וְלִבְרַתֵּהּ וְלַאֲחוּהִי:
@603 וְלַאֲחָתֵהּ בְּתֻלְתָּא דְקָרִיבָא לֵהּ דִי לָא הֲוַת לִגְבַר לַהּ יִסְתָּאָב:
@604 לָא יִסְתָּאַב רַבָּא בְעַמֵהּ לְאַחֲלוּתֵהּ:
@605 לָא יִמְרְטוּן מְרַט בְּרֵישְׁהוֹן וּפָאתָא דְדִקְנְהוֹן לָא יְגַלְחוּן וּבְבִשְׂרְהוֹן לָא יְחַבְּלוּן חִבּוּל:
@606 קַדִישִׁין יְהוֹן קֳדָם אֱלָהֲהוֹן וְלָא יְחַלוּן שְׁמָא דֶאֱלָהֲהוֹן אֲרֵי יָת קֻרְבָּנַיָא דַיְיָ קֻרְבַּן אֱלָהֲהוֹן אִנוּן מַקְרִיבִין וִיהוֹן קַדִישִׁין:
@607 אִתְּתָא מַטְעֲיָא וּמְחַלְלָא לָא יִסְבוּן וְאִתְּתָא דִמְתָרְכָא מִבַּעְלַהּ לָא יִסְבוּן אֲרֵי קַדִישׁ הוּא קֳדָם אֱלָהֵהּ:
@608 וּתְקַדְשִׁנֵהּ אֲרֵי יָת קֻרְבַּן אֱלָהָךְ הוּא מְקָרֵב קַדִישׁ יְהֵא לָךְ אֲרֵי קַדִישׁ אֲנָא יְיָ מְקַדִשְׁכוֹן:
@609 וּבַת גְבַר כָּהֵן אֲרֵי תִתְחַל לְמִטְעֵי מִקְדֻשַׁת אֲבוּהָ הִיא מִתַּחֲלָא בְּנוּרָא תִּתּוֹקָד:
@610 וְכַהֲנָא דְאִתְרַבָּא מֵאֲחוֹהִי דְיִתָּרִיק עַל רֵישֵׁהּ מִשְׁחָא דִרְבוּתָא וְדִי קָרִיב יָת קֻרְבָּנֵהּ לְמִלְבָּשׁ יָת לְבוּשַׁיָא יָת רֵישֵׁהּ לָא יְרַבֵּי פֵרוּעַ וּלְבוּשׁוֹהִי לָא יִבְזַע:
@611 וְעַל כָּל נַפְשַׁת מֵתָא לָא יֵיעוֹל לַאֲבוּהִי וּלְאִמֵהּ לָא יִסְתָּאָב:
@612 וּמִן מַקְדְשָׁא לָא יִפּוֹק וְלָא יַחֵל יָת מַקְדְשָׁא דֶאֱלָהֵהּ אֲרֵי כְּלִיל מְשַׁח רְבוּתָא דֶאֱלָהֵהּ עֲלוֹהִי אֲנָא יְיָ:
@613 וְהוּא אִתְּתָא בִבְתֻלְתָּהָא יִסָב:
@614 אַרְמְלָא וּמְתָרְכָא וְחַלִילָא מַטְעֲיָא יָת אִלֵין לָא יִסָב אֱלָהֵין בְּתֻלְתָּא מֵעַמֵהּ יִסַב אִתְּתָא:
@615 וְלָא יַחֵל זַרְעֵהּ בְּעַמֵהּ אֲרֵי אֲנָא יְיָ מְקַדְשֵׁהּ:
@616 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@617 מַלֵל עִם אַהֲרֹן לְמֵימָר גְבַר מִבְּנָיִךְ לְדָרֵיהוֹן דִי יְהֵּי בֵהּ מוּמָא לָא יִקְרַב לְקָרָבָא קֻרְבָּנָא קֳדָם אֱלָהֵהּ:
@618 אֲרֵי כָל גְבַר דִּי בֵהּ מוּמָא לָא יִקְרַב גְבַר עַוִיר אוֹ חֲגִיר אוֹ חָרִים אוֹ שָׂרִיע:
@619 אוֹ גְבַר דִי יְהֵי בֵהּ תְּבַר רַגְלָא אוֹ תְּבַר יְדָא:
@620 אוֹ גְבִין אוֹ דֻקָא אוֹ חִלִיז בְּעֵינֵהּ אוֹ גַרְבָן אוֹ חֲזָזָן אוֹ מְרִיס פַּחֲדִין:
@621 כָּל גְבַר דִי בֵהּ מוּמָא מִזַרְעָא דְאַהֲרֹן כַּהֲנָא לָא יִקְרַב לְקָרָבָא יָת קֻרְבָּנַיָא דַיְיָ מוּמָא בֵהּ יָת קֻרְבַּן אֱלָהֵהּ לָא יִקְרַב לְקָרָבָא:
@622 קֻרְבַּן אֱלָהֵהּ מִקֹדֶשׁ קוּדְשַׁיָא וּמִן קוּדְשַׁיָא יֵיכוּל:
@623 בְּרַם לְפָרֻכְתָּא לָא יֵיעוֹל וּלְמַדְבְּחָא לָא יִקְרַב אֲרֵי מוּמָא בֵהּ וְלָא יַחֵל יָת מַקְדְשַׁי אֲרֵי אֲנָא יְיָ מְקַדִשְׁהוֹן:
@624 וּמַלִיל מֹשֶׁה עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל:
@625 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@626 מַלֵיל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְיִפָּרְשׁוּן מִקוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל וְלָא יְחַלוּן יָת שְׁמָא דְקוּדְשִׁי דִי אִנוּן מְקַדְשִׁין קֳדָמַי אֲנָא יְיָ:
@627 אֱמַר לְהוֹן לְדָרֵיכוֹן כָּל גְבַר דִי יִקְרַב מִכָּל בְּנֵיכוֹן לְקוּדְשַׁיָא דִי יְקַדְשׁוּן בְּנֵי יִשְׂרָאֵל קֳדָם יְיָ וְסֹאבְתֵיהּ עֲלוֹהִי וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהִיא מִן קֳדָמַי אֲנָא יְיָ:
@628 גְבַר גְבַר מִזַרְעָא דְאַהֲרֹן וְהוּא סְגִיר אוֹ דָאִיב בְּקוּדְשַׁיָא לָא יֵיכוּל עַד דִי יִדְכֵּי וּדְיִקְרַב בְּכָל טְמֵא נַפְשָׁא אוֹ גְבַר דִי תִפּוֹק מִנֵהּ שִׁכְבַת זַרְעָא:
@629 אוֹ גְבַר דִי יִקְרַב בְּכָל רִחֲשָׁא דִי יִסְתָּאַב לֵהּ אוֹ בַאֲנָשָׁא דִי יִסְתָּאַב לֵהּ:לכָל סֹאבְתֵיהּ:
@630 אֱנַשׁ דִי יִקְרַב בֵּהּ וִיהֵי מְסָאָב עַד רַמְשָׁא וְלָא יֵיכוּל מִן קוּדְשַׁיָא אֱלָהֵן אַסְחֵי בִשׂרֵהּ בְּמַיָא:
@631 וּבְמֵעַל:שִׁמְשָׁא וְיִדְכֵּי וּבָתַר כֵּן יֵיכוּל מִן קוּדְשַׁיָא אֲרֵי לַחְמֵהּ הוּא:
@632 נְבִילָא וּתְבִירָא לָא יֵיכוּל לְאִסְתָּאָבָא בָהּ אֲנָא יְיָ:
@633 וְיִטְרוּן יָת מַטְּרַת מֵימְרִי וְלָא יְקַבְּלוּן עֲלוֹהִי חוֹבָא וִימוּתוּן בֵּהּ אֲרֵי יְחַלֻנֵהּ אֲנָא יְיָ מְקַדִשְׁהוֹן:
@634 וְכָל חִלוֹנַי לָא יֵיכוּל קוּדְשָׁא תּוֹתָבָא דְכַהֲנָא וַאֲגִירָא לָא יֵיכוּל קוּדְשָׁא:
@635 וְכָהֵן אֲרֵי יִקְנֵי נְפַשׁ קִנְיַן כַּסְפֵּהּ הוּא יֵיכוּל בֵּהּ וִילִיד בֵּיתֵהּ אִנוּן יֵיכְלוּן בְּלַחְמֵהּ:
@636 וּבַת כָּהֵן אֲרֵי תְהִי לִגְבַר חִלוֹנָי הִיא בְּאַפְרָשׁוּת קוּדְשַׁיָא לָא תֵיכוּל:
@637 וּבַת כָּהֵן אֲרֵי תְהֵי אַרְמְלָא וּמְתָרְכָא וּבַר לֵית לַהּ וּתְתוּב לְבֵית אֲבוּהָא כְּרַבְיוּתָהָא מִלַחְמָא דַאֲבוּהָא תֵּיכוּל וְכָל חִלוֹנַי לָא יֵיכוּל בֵּהּ:
@638 וּגְבַר אֲרֵי יֵיכוּל קוּדְשָׁא בְּשָׁלוּ וְיוֹסֵף חוּמְשֵׁהּ עֲלוֹהִי וְיִתֵּן לְכַהֲנָא יָת קוּדְשָׁא:
@639 וְלָא יְחַלוּן יָת קוּדְשַׁיָא דִבְנֵי יִשְׂרָאֵל יָת דִי יַפְרְשׁוּן קֳדָם יְיָ:
@640 וִיקַבְּלוּן עֲלֵיהוֹן עֲוָיָן וְחוֹבִין בְּמֵיכָלְהוֹן בְּסוֹאֲבָא יָת קוּדְשֵׁיהוֹן אֲרֵי אֲנָא יְיָ מְקַדִשְׁהוֹן:
@641 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@642 מַלֵל עִם אַהֲרֹן וְעִם בְּנוֹהִי וְעִם כָּל בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר גְבַר מִבֵּית יִשְׂרָאֵל וּמִן גִיוֹרָא בְּיִשְׂרָאֵל דִי יְקָרֵב קֻרְבָּנֵהּ לְכָל נִדְרֵיהוֹן וּלְכָל נִדְבָתְהוֹן דִי יְקָרְבוּן קֳדָם יְיָ לַעֲלָתָא:
@643 לְרַעֲוָא לְכוֹן שְׁלִים דְכוּרָא בְּתוֹרֵי בְּאִמְרַיָא וּבְעִזַיָא:
@644 כֹּל דִי בֵהּ מוּמָא לָא תְקָרְבוּן אֲרֵי לָא לְרַעֲוָא יְהֵי לְכוֹן:
@645 וּגְבַר אֲרֵי יְקָרֵב נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ לְפָרָשָׁא נִדְרָא אוֹ לִנְדַבְתָּא בְּתוֹרֵי אוֹ בְעָנָא שְׁלִים יְהֵי לְרַעֲוָא כָּל מוּמָא לָא יְהֵי בֵהּ:
@646 עַוִיר אוֹ תְבִיר אוֹ פְסִיק אוֹ יַבְּלָן אוֹ גַרְבָן אוֹ חֲזָזָן לָא תְקָרְבוּן אִלֵין קֳדָם יְיָ וְקֻרְבָּנָא לָא תִתְּנוּן מִנְהוֹן עַל מַדְבְּחָא קֳדָם יְיָ:
@647 וְתוֹר וְאִמַר יַתִּיר וְחַסִיר נְדַבְתָּא תַּעְבֵּד יָתֵהּ וּלְנִדְרָא לָא יְהֵי לְרַעֲוָא:
@648 וְדִי מְרִיס וְדִי רְסִיס וְדִי שְׁלִיף וְדִי גְזִיר לָא תְקָרְבוּן קֳדָם יְיָ וּבְאַרְעֲכוֹן לָא תַעְבְּדוּן:
@649 וּמִן בַּר עַמְמִין לָא תְקַרְבוּן יָת קֻרְבַּן אֱלָהֲכוֹן מִכָּל אִלֵין אֲרֵי חִבּוּלְהוֹן בְּהוֹן מוּמָא בְהוֹן לָא לְרַעֲוָא יְהוֹן לְכוֹן:
@650 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@651 תּוֹר אוֹ אִמָר אוֹ עִזָא אֲרֵי יִתְיְלִיד וִיהֵי שִׁבְעָא יוֹמִין בָּתַר אִמֵהּ וּמִיוֹמָא תְמִינָאָה וּלְהַלָא יִתִּרְעִי לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ:
@652 וְתוֹרְתָּא אוֹ שֵׂיתָא לֵהּ וְלִבְרֵהּ לָא תִכְּסוּן בְּיוֹמָא חָד:
@653 וַאֲרֵי תִּכְּסוּן נִכְסַת תּוֹדְתָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְּסֻנֵהּ:
@654 בְּיוֹמָא הַהוּא יִתְאֲכֵל לָא תַשְׁאֲרוּן מִנֵהּ עַד צַפְרָא אֲנָא יְיָ:
@655 וְתִטְרוּן פִּקוּדַי וְתַעֲבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@656 וְלָא תְחַלְלוּן יָת שְׁמָא דְקוּדְשַׁי וְאִתְקַדַשׁ בְּגוֹ בְּנֵי יִשְׂרָאֵל אֲנָא יְיָ מְקַדִשְּׁכוֹן:
@657 דְאַפִּיק יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם לְמֶהֱוֵי לְכוֹן לֵאלָהָא אֲנָא יְיָ:
@658 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@659 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן מוֹעֲדַיָא דַיְיָ דִי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִישׁ אִלֵין אִנוּן מוֹעֲדָי:
@660 שִׁתָּא יוֹמִין תִּתְעֲבֵד עִבִידָא וּבְיוֹמָא שְׁבִיעָאָה שְׁבַת שְׁבָתָא מְעָרַע קַדִישׁ כָּל עִבִידָא לָא תַעֲבְּדוּן שַׁבְּתָא הִיא קֳדָם יְיָ בְּכֹל מוֹתְבָנֵיכוֹן:
@661 אִלֵין מוֹעֲדַיָא דַיְיָ מְעָרְעֵי קַדִישׁ דִי תְעָרְעוּן יָתְהוֹן בְּזִמְנֵיהוֹן:
@662 בְּיַרְחָא קַדְמָאָה בְּאַרְבְּעַת עַשְׂרָא לְיַרְחָא בֵּין שִׁמְשַׁיָא פִּסְחָא קֳדָם יְיָ:
@663 וּבְחַמְשַׁת עַשְׂרָא יוֹמָא לְיַרְחָא הָדֵין חַגָא דְפַטִירַיָא קֳדָם יְיָ שִׁבְעָא יוֹמִין פַּטִיר תֵּיכְלוּן:
@664 בְּיוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחַן לָא תַעֲבְּדוּן:
@665 וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא שְׁבִיעָאָה מְעָרַע קַדִישׁ כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן:
@666 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@667 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לְאַרְעָא דִי אֲנָא יָהֵב לְכוֹן וְתַחְצְדוּן יָת חֲצָדַהּ וְתַיְתוּן יָת עוּמְרָא רֵישׁ חֲצָדְכוֹן לְוָת כַּהֲנָא:
@668 וִירִים יָת עוּמְרָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן מִבָּתַר יוֹמָא טָבָא יְרִימִנֵהּ כַּהֲנָא:
@669 וְתַעֲבְּדוּן בְּיוֹמָא דַאֲרָמוּתְכוֹן יָת עוּמְרָא אִמַר שְׁלִים בַּר שַׁתֵּהּ לַעֲלָתָא קֳדָם יְיָ:
@670 וּמִנְחָתֵהּ תְּרֵין עֶשְׂרוֹנִין סֻלְתָּא דְפִילָא בִמְשַׁח קֻרְבָּנָא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא וְנִסְכֵּהּ חַמְרָא רַבְעוּת הִינָא:
@671 וּלְחֵם וּקְלִי וּפֵרוּכָן לָא תֵיכְלוּן עַד כְּרַן יוֹמָא הָדֵין עַד אַיְתוֹאֵיכוֹן יָת קֻרְבָּן אֱלָהָכוֹן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@672 וְתִמְנוּן לְכוֹן מִבָּתַר יוֹמָא טָּבָא מִיוֹם אַיְתוֹאֵיכוֹן יָת עוּמְרָא דַאֲרָמוּתָא שִׁבְעָא שָׁבוּעִין שַּׁלְמִין יְהֶוְיָן (נ''א תְּהֶוְיָן):
@673 עַד מִבָּתַר שְׁבוּעֲתָא שְׁבִיעֵתָא תִּמְנוּן חַמְשִׁין יוֹמִין וּתְקַרְבוּן מִנְחָתָא חֲדַתָּא קֳדָם יְיָ:
@674 מִמוֹתְבָנֵיכוֹן תַּיְתוּן לְחֵם אֲרָמוּתָא תַּרְתֵּין (גְרִיצַן) תְּרֵין עֶשְׂרוֹנִין סֻלְתָּא יְהֶוְיָן חֲמִיעַ יִתְאַפְיָן בִּכּוּרִין קֳדָם יְיָ:
@675 וּתְקָרְבוּן עַל לַחְמָא שִׁבְעָא אִמְרִין שַׁלְמִין בְּנֵי שְׁנָא וְתוֹר בַּר תּוֹרֵי חַד וְדִכְרִין תְּרֵין יְהוֹן עֲלָתָא קֳדָם יְיָ וּמִנְחָתְהוֹן וְנִסְכֵּיהוֹן קֻרְבַּן דְמִתְקַבֵּל בְּרַעֲוָא קֳדָם יְיָ:
@676 וְתַעְבְּדוּן צְפִיר בַּר עִזֵי חַד לְחַטָאתָא וּתְרֵין אִמְרִין בְּנֵי שְׁנָא לְנִכְסַת קוּדְשַׁיָא:
@677 וִירִים כַּהֲנָא יָתְהוֹן עַל לְחֵם בִּכּוּרַיָא אֲרָמוּתָא קֳדָם יְיָ עַל תְּרֵין אִמְרִין קוּדְשָׁא יְהוֹן קֳדָם יְיָ לְכַהֲנָא:
@678 וּתְעָרְעוּן בִּכְרַן יוֹמָא הָדֵין מְעָרַע קַדִישׁ יְהֵי לְכוֹן כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן קְיַם עָלָם בְּכָל מוֹתְבָנֵיכוֹן לְדָרֵיכוֹן:
@679 וּבְמֶחֱצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ בְּמֶחֱצָדָךְ וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵט לְעַנְיֵי וּלְגִיוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהֲכוֹן:
@680 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@681 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּיַרְחָא שְׁבִיעָאָה בְּחַד לְיַרְחָא יְהֵי לְכוֹן נְיָחָא דוּכְרָן יַבָּבָא מְעָרַע קַדִישׁ:
@682 כָּל עִבִידַת פָלְחָנָא לָא תַעֲבְּדוּן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@683 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@684 בְּרַם בְּעַשְׂרָא לְיַרְחָא שְׁבִיעָאָה הָדֵין יוֹמָא דְכִפּוּרַיָא הוּא מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ:
@685 וְכָל עִבִידָא לָא תַעֲבְּדוּן בִּכְרַן יוֹמָא הָדֵין אֲרֵי יוֹמָא דְכִפּוּרַיָא הוּא לְכַפָּרָא עֲלֵיכוֹן קֳדָם יְיָ אֱלָהֲכוֹן:
@686 אֲרֵי כָל אֲנָשָׁא דִי לָא מִתְעַנֵי בִּכְרַן יוֹמָא הָדֵין וְיִשְׁתֵּיצֵי מֵעַמָהָא:
@687 וְכָל אֱנַשׁ דִי תַעְבֵּד כָּל עִבִידָא בִּכְרַן יוֹמָא הָדֵין וְאוֹבֵד יָת אֲנָשָׁא הַהִיא מִגוֹ עַמָהּ:
@688 כָּל עִבִידָא לָא תַעֲבְּדוּן קְיַם עָלָם לְדָרֵיכוֹן בְּכֹל מוֹתְבָנֵיכוֹן:
@689 שְׁבַת שְׁבָתָא הוּא לְכוֹן וּתְעַנוּן יָת נַפְשָׁתֵיכוֹן בְּתִשְׁעָה לְיַרְחָא בְּרַמְשָׁא מֵרַמְשָׁא עַד רַמְשָׁא תְּנוּחוּן נְיַחֲכוֹן:
@690 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@691 מַלֵיל עִם בְּנֵי יִשְׂרָאֵל לְמֵימָר בְּחַמְשָׁא עַשְׂרָא יוֹמָא לְיַרְחָא שְׁבִיעָאָה הָדֵין חַגָא דִמְטַלַיָא שִׁבְעַת יוֹמִין קֳדָם יְיָ:
@692 בְּיּוֹמָא קַדְמָאָה מְעָרַע קַדִישׁ כָּל עִבִידַת פָּלְחָן לָא תַעֲבְּדוּן:
@693 שִׁבְעָא יוֹמִין תְּקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ בְּיוֹמָא תְמִינָאָה מְעָרַע קַדִישׁ יְהֵי לְכוֹן וּתְקָרְבוּן קֻרְבָּנָא קֳדָם יְיָ כְּנֵשׁ תְּהוֹן כָּל עִבִידַת פָּלְחַן לָא תַעֲבְּדוּן:
@694 אִלֵין מוֹעֲדַיָא דַיְיָ דִי תְעָרְעוּן יָתְהוֹן מְעָרְעֵי קַדִישׁ לְקָרָבָא קֻרְבָּנָא קֳדָם יְיָ עֲלָתָא וּמִנְחָתָא נִכְסַת קוּדְשִׁין וְנִסוּכִין פִּתְגַם יוֹם בְּיוֹמֵהּ:
@695 בַּר שַׁבַּיָא דַיְיָ וּבַר מַתְּנָתֵיכוֹן וּבַר כָּל נִדְרֵיכוֹן וּבַר כָּל נִדְבָתֵיכוֹן דִי תִתְּנוּן קֳדָם יְיָ:
@696 בְּרַם בְּחַמְשָׁא עֲשַׂר יוֹמָא לְיַרְחָא שְׁבִיעָאָה בְּמִכְנְשֵׁיכוֹן יָת עֲלַלַת אַרְעָא תְּחַגוּן יָת חַגָא קֳדָם יְיָ שִׁבְעָא יוֹמִין בְּיוֹמָא קַדְמָאָה נְיָחָא וּבְיוֹמָא תְמִינָאָה נְיָחָא:
@697 וְתִסְבוּן לְכוֹן בְּיוֹמָא קַדְמָאָה פֵּרֵי אִילָנָא אֶתְרוֹגִין וְלֻלָבִין וַהֲדַסִין וְעַרְבִין דִנְחָל וְתֶחֱדוּן קֳדָם יְיָ אֱלָהֲכוֹן שַׁבְעַת יוֹמִין:
@698 וּתְחַגוּן יָתֵהּ חַגָא קֳדָם יְיָ שַׁבְעַת יוֹמִין בְּשַׁתָּא קְיַם עָלָם לְדָרֵיכוֹן בְּיַרְחָא שְׁבִיעָאָה תְּחַגוּן יָתֵהּ:
@699 בִּמְטַלַיָא תֵיתְבוּן שַׁבְעַת יוֹמִין כָּל יַצִיבָא בְּיִשְׂרָאֵל יֵתְבוּן בִּמְטַלַיָא:
@700 בְּדִיל דְיִדְעוּן דָרֵיכוֹן אֲרֵי בִמְטַלָיוּת עֲנָנֵי אוֹתֵבִית יָת בְּנֵי יִשְׂרָאֵל בְּאַפָּקוּתִי יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם אֲנָא יְיָ אֱלָהֲכוֹן:
@701 וּמַלִיל מֹשֶׁה יָת סְדַר מוֹעֲדַיָא דַיְיָ וְאַלֵפִנוּן לִבְנֵי יִשְׂרָאֵל:
@702 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@703 פַּקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ מְשַׁח זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָא תְּדִירָא:
@704 מִבָּרָא לְפָרֻכְתָּא דְסַהֲדוּתָא בְּמַשְׁכַּן זִמְנָא יַסְדַר יָתֵהּ אַהֲרֹן מֵרַמְשָׁא עַד צַפְרָא קֳדָם יְיָ תְּדִירָא קְיָם עָלָם לְדָרֵיכוֹן:
@705 עַל מְנַרְתָּא דָכִיתָא יַסְדַר יָת בּוֹצִינַיָא קֳדָם יְיָ תְּדִירָא:
@706 וְתִסַב סֻלְתָּא וְתֵיפֵי יָתַהּ תַּרְתָּא עַשְׂרֵי גְרִיצָן תְּרֵין עֶשְׂרוֹנִין תְּהֵי גְרִצְתָּא חֲדָא:
@707 וּתְשַׁוִי יָתְהוֹן תַּרְתֵּי סִדְרִין שִׁית סִדְרָא עַל פָּתוֹרָא דַכְיָא קֳדָם יְיָ:
@708 וְתִתֵּן עַל סִדְרָא לְבֹנְתָּא דָכִיתָא וּתְהֵי לִלְחֵם לְאִדְכַּרְתָּא קֻ:רבָּנָא:קָדָם יְיָ:
@709 בְּיוֹמָא דְשַׁבְּתָא בְּיוֹמָא דְשַׁבְּתָא יַסְדְרִנֵהּ קֳדָם יְיָ תְּדִירָא מִן קֳדָם בְּנֵי יִשְׂרָאֵל קְיַם עָלָם:
@710 וּתְהֵי לְאַהֲרֹן וְלִבְנוֹהִי וְיֵכְלֻנֵהּ בַּאֲתַר קַדִישׁ אֲרֵי קֹדֶשׁ קוּדְשִׁין הוּא לֵהּ מִקֻרְבָּנַיָא דַיְיָ קְיַם עָלָם:
@711 וּנְפַק בַּר אִתְּתָא בַת יִשְׂרָאֵל וְהוּא בַּר גְבַר מִצְרָאָה בְּגוֹ בְּנֵי יִשְׂרָאֵל וּנְצוֹ בְּמַשְׁרִיתָא בַּר אִתְּתָא בַת יִשְׂרָאֵל וְגַבְרָא בַּר יִשְׂרָאֵל:
@712 וּפָרֵשׁ בַּר אִתְּתָא בַת יִשְׂרָאֵל יָת שְׁמָא וְאַרְגֵז וְאַיְתִיאוּ יָתֵהּ לְוָת מֹשֶׁה וְשׁוּם אִמֵהּ שְׁלֹמִית בַּת דִבְרִי לְשִׁבְטָא דְדָן:
@713 וְאַסְרוֹהִי בְּבֵית מַטְרָא עַד דְיִתְפָּרַשׁ לְהוֹן עַל גְזֵרַת מֵימְרָא דַיְיָ:
@714 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@715 אַפֵּק יָת דְאַרְגֵז לְמִבָּרָא לְמַשְּׁרִיתָא וְיִסְמְכוּן כָּל דִי שְׁמָעוּ יָת יְדֵיהוֹן עַל רֵישֵׁהּ וְיִרְגְמוּן יָתֵהּ כָּל כְּנִשְּׁתָּא:
@716 וְעִם בְּנֵי יִשְׂרָאֵל תְּמַלֵל לְמֵימָר גְבַר גְבַר דִי יַרְגֵז קֳדָם אֱלָהֵהּ וִיקַבֵּל חוֹבֵהּ:
@717 וְדִי פָרֵשׁ שְׁמָא דַיְיָ אִתְקְטָּלָא יִתְקְטֵל מִרְגַם יִרְגְמוּן בֵּהּ כָּל כְּנִשְׁתָּא כְּגִיוֹרָא כְּיַצִיבָא בְּפָרָשׁוּתֵהּ שְׁמָא יִתְקְטֵל:
@718 וּגְבַר אֲרֵי יִקְטוֹל כָּל נַפְשָׁא דַאֲנָשָׁא אִתְקְטָלָא יִתְקְטֵל:
@719 וּדְיִקְטוֹל נְפַשׁ בְּעִירָא יְשַׁלְמִנַהּ נַפְשָׁא חֳלַף נַפְשָׁא:
@720 וּגְבַר אֲרֵי יִתֵּן מוּמָא בְּחַבְרֵהּ כְּמָא דִי עֲבַד כֵּן יִתְעֲבֵד לֵיהּ:
@721 תַּבְרָא חֳלַף תַּבְרָא עֵינָא חֳלַף עֵינָא שִׁנָא חֳלַף שִׁנָא כְּמָא דִי יִתֵּן מוּמָא בַּאֲנָשָׁא כֵּן יִתְיְהֵב בֵּהּ:
@722 וּדְיִקְטוֹל בְּעִירָא יְשַׁלְמִנַהּ וּדְיִקְטוֹל אֲנָשָׁא יִתְקְטֵל:
@723 דִינָא חֲדָא יְהֵי לְכוֹן כְּגִיוֹרָא כְּיַצִיבָא יְהֵי אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@724 וּמַלִיל מֹשֶׁה עִם בְּנֵי יִשְׂרָאֵל וְאַפִּיקוּ יָת דְאַרְגֵז לְמִבָּרָא לְמַשְׁרִיתָא וּרְגָמוּ יָתֵהּ אַבְנָא וּבְנֵי יִשְׂרָאֵל עֲבָדוּ כְּמָא דִי פַּקֵיד יְיָ יָת מֹשֶׁה: פפפ:
@725 וּמַלִיל יְיָ עִם מֹשֶׁה בְּטּוּרָא דְסִינַי לְמֵימָר:
@726 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעַלוּן לְאַרְעָא דִי אֲנָא יָהֵב לְכוֹן וְתַשְּׁמֵט אַרְעָא שְׁמִטְתָא קֳדָם יְיָ:
@727 שִׁית שְׁנִין תִּזְרַע חַקְלָךְ וְשִׁית שְׁנִין תִכְסַח כַּרְמָךְ וְתִכְנוֹשׁ יָת עֲלַלְתָּהּ:
@728 וּבְשַׁתָּא שְׁבִיעֲתָא נְיַח שְׁמִטְתָא יְהֵי לְאַרְעָא דְתַשְׁמֵט קֳדָם יְיָ חַקְלָךְ לָא תִזְרַע וְכַרְמָךְ לָא תִכְסָח:
@729 יָת כַּתֵּי דַחֲצָדָךְ לָא תֶחֱצַד וְיָת עִנְבֵי שִׁבְקָךְ לָא תִקְטוֹף שְׁנַת שְׁמִטְתָא יְהֵי לְאַרְעָא:
@730 וּתְהֵי שְׁמִטַת אַרְעָא לְכוֹן לְמֵיכַל לָךְ וּלְעַבְדָךְ וּלְאַמְתָךְ וְלַאֲגִירָךְ וּלְתוֹתָבָךְ דְדָיְרִין עִמָךְ:
@731 וְלִבְעִירָךְ וּלְחַיְתָא דִי בְאַרְעָךְ תְּהֵי כָל עֲלַלְתַּהּ לְמֵיכָל:
@732 וְתִמְנֵי לָךְ שְׁבַע שְׁמִיטִין דִשְׁנִין שְׁבַע שְׁנִין שְׁבַע זִמְנִין וִיהוֹן לָךְ יוֹמֵי שְּׁבַע שְׁמִטִין דִשְׁנִין אַרְבְּעִין וְתֵשַׁע שְׁנִין:
@733 וְתַעֲבַר שׁוֹפָר יַבָּבָא בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא בְּיוֹמָא דְכִפּוּרַיָא תַּעַבְרוּן שׁוֹפָרָא בְּכָל אַרְעֲכוֹן:
@734 וּתְקַדְשׁוּן יָת שְׁנַת חַמְשִׁין שְׁנִין וְתַקְרוּן חֵרוּתָא בְּאַרְעָא לְכָל יָתְבָהָא יוֹבֵלָא הִיא תְּהֵי לְכוֹן וּתְתוּבוּן גְבַר לְאַחֲסַנְתֵּהּ וּגְבַר לְזַרְעִיתֵהּ תְּתוּבוּן:
@735 יוֹבֵלָא הִיא שְׁנַת חַמְשִׁין שְׁנִין תְּהֵי לְכוֹן לָא תִזְרְעוּן וְלָא תַחְצְדוּן יַת כַּתָּהָא וְלָא תִקְטְפוּן יַת שִׁבְקָהָא:
@736 אֲרֵי יוֹבֵלָא הִיא קוּדְשָׁא תְּהֵי לְכוֹן מִן חַקְלָא תֵּיכְלוּן יָת עֲלַלְתָּהּ:
@737 בְּשַׁתָּא דְיוֹבֵלָא הָדָא תְּתוּבוּן גְבַר לְאַחֲסַנְתֵּהּ:
@738 וַאֲרֵי תְזַבֵּן זְבִינִין לְחַבְרָךְ אוֹ תִזְבֵּן מִידָא דְחַבְרָךְ לָא תוֹנוּן גְבַר יָת אֲחוֹהִי:
@739 בְּמִנְיַן שְׁנַיָא בָּתַר יוֹבֵלָא תִּזְבֵּן מִן חַבְרָךְ בְּמִנְיַן שְׁנֵי עֲלַלְתָּא יְזַבֶּן לָךְ:
@740 לְפוּם סְגִיאוּת שְׁנַיָא תַּסְגֵי זְבִינוֹהִי וּלְפוּם זְעֵרוּת שְׁנַיָא תַּזְעֵר זְבִינוֹהִי אֲרֵי מִנְיַן עֲלַלְתָּא הוּא מְזַבֵּן לָךְ:
@741 וְלָא תוֹנוּן גְבַר יָת חַבְרֵהּ וְתִדְחַל מֵאֱלָהָךְ אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@742 וְתַעְבְּדוּן יָת קְיָמַי וְיָת דִינַי תִּטְּרוּן וְתַעֲבְּדוּן יָתְהוֹן וְתֵיתְבוּן עַל אַרְעָא לְרָחֲצָן:
@743 וְתִתֵּן אַרְעָא אִבַּהּ וְתֵיכְלוּן לְמִשְׂבָּע וְתֵיתְבוּן לְרָחֲצָן עֲלַהּ:
@744 וַאֲרֵי תֵימְרוּן מָא נֵיכוּל בְּשַׁתָּא שְׁבִיעֵתָא הָא לָא נִזְרָע וְלָא נִכְנוֹשׁ יָת עֲלַלְתָּנָא:
@745 וֶאֱפַקֵד יָת בִּרְכְּתִי לְכוֹן בְּשַׁתָּא שְׁתִיתֵתָא וְתַעְבֵּד יָת עֲלַלְתָּא לִתְלַת שְׁנִין:
@746 וְתִזְרְעוּן יָת שַׁתָּא תְמִינֵתָא וְתֵיכְלוּן מִן עֲלַלְתָּא עַתִּיקָא עַד שַׁתָּא תְשִׁיעֵתָא עַד מֵעַל עֲלַלְתַּהּ תֵּיכְלוּן עַתִּיקָא:
@747 וְאַרְעָא לָא תִזְדַבַּן לַחֲלוּטִין אֲרֵי דִילִי אַרְעָא אֲרֵי דַיָרִין וְתוֹתָבִין אַתּוּן קֳדָמַי:
@748 וּבְכֹל אַרְעָא אַחֲסַנְתְּכוֹן פֻּרְקָנָא תִּתְּנוּן לְאַרְעָא:
@749 אֲרֵי יִתְמַסְכַּן אָחוּךְ וִיזַבֵּן מֵאַחֲסַנְתֵּהּ וְיֵיתֵי פָרִיקֵהּ דְקָרִיב לֵהּ וְיִפְרוֹק יָת זְבִינֵי אֲחוּהִי:
@750 וּגְבַר אֲרֵי לָא יְהֵי לֵהּ פָּרִיק וְתַדְבֵּק יְדֵהּ וְיַשְׁכַּח כְּמִסַת פֻּרְקָנֵהּ:
@751 וִיחַשֵׁב יָת שְׁנֵי זְבִינוֹהִי וְיָתֵב יָת מוֹתָרָא לִגְבַר דִי זַבֶּן לֵהּ וִיתוּב לְאַחֲסַנְתֵּהּ:
@752 וְאִם לָא תַשְׁכַּח יְדֵהּ כְּמִסַת אֲתֵב לֵהּ וִיהֵי זְבִינוֹהִי בִּידָא דִזְבַן יָתֵהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִפּוֹק בְּיוֹבֵלָא וִיתוּב לְאַחֲסַנְתֵּהּ:
@753 וּגְבַר אֲרֵי יְזַבֵּן בֵּית מוֹתַב קַרְתָּא מַקְפָא שׁוּר וּתְהֵי פוּרְקָנֵהּ עַד מִשְׁלַם שַׁתָּא דִזְבִינוֹהִי עִדָן בְּעִדָן תְּהֵי פוּרְקָנֵהּ:
@754 וְאִם לָא יִתְפָּרַק עַד מִשְׁלַם לֵהּ שַׁתָּא שְׁלֶמְתָּא וִיקוּם בֵּיתָא דִי בְקַרְתָּא דִי לֵהּ שׁוּרָא לַחֲלוּטִין לְדִי זְבַן יָתֵהּ לְדָרוֹהִי לָא יִפּוֹק בְּיוֹבֵלָא:
@755 וּבָתֵּי פַצְחַיָא דִי לֵית לְהוֹן שׁוּר מַקַף סְחוֹר סְחוֹר עַל חֲקַל אַרְעָא יִתְחַשָׁב פֻּרְקָנָא תְּהֵי לֵהּ וּבְיוֹבֵלָא יִפּוֹק:
@756 וְקִרְוֵי לֵיוָאֵי בָּתֵּי קִרְוֵי אַחֲסַנְתְּהוֹן פּוּרְקַן עָלָם תְּהֵי לְלֵיוָאֵי:
@757 וְדִי יִפְרוֹק מִן לֵיוָאֵי וְיִפּוֹק זְבִין בֵּיתָא וְקַרְתָּא אַחֲסַנְתֵּהּ בְּיוֹבֵלָא אֲרֵי בָתֵּי קִרְוֵי לֵיוָאֵי הִיא אַחְסַנְתְּהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@758 וַחֲקַל רְוַח קִרְוֵיהוֹן לָא יִזְדַבָּן אֲרֵי אַחֲסָנַת עָלָם הוּא לְהוֹן:
@759 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ וּתְמוּט יְדֵהּ עִמָךְ וְתַתְקַף בֵּהּ דַיַר וְתוֹתָב וִיחֵי עִמָךְ:
@760 לָא תִסַב מִנֵהּ חִבּוּלְיָא וְרִבִּיתָא וְתִדְחַל מֵאֱלָהָךְ וִיחֵי אָחוּךְ עִמָךְ:
@761 יָת כַּסְפָּךְ לָא תִתֵּן לֵהּ בְּחִבּוּלְיָא וּבְרִבִּיתָא לָא תִתֵּן מֵיכְלָךְ:
@762 אֲנָא יְיָ אֱלָהֲכוֹן דִי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם לְמִתַּן לְכוֹן יָת אַרְעָא דִכְנַעַן לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ:
@763 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ עִמָךְ וְיִזְדַבַּן לָךְ לָא תִפְלַח בֵּהּ פָּלְחַן עַבְדִין:
@764 כַּאֲגִירָא כְתוֹתָבָא יְהֵי עִמָךְ עַד שַׁתָּא דְיוֹבֵלָא יִפְלַח עִמָךְ:
@765 וְיִפּוֹק מֵעִמָךְ הוּא וּבְנוֹהִי עִמֵהּ וִיתוּב לְזַרְעִיתֵהּ וּלְאַחֲסָנַת אֲבָהָתוֹהִי יְתוּב:
@766 אֲרֵי עַבְדַי אִנוּן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם לָא יִזְדַבְּנוּן זְבוּן עַבְדִין:
@767 לָא תִפְלָח בֵּהּ בְּקַשְׁיוּ וְתִדְחַל מֵאֱלָהָךְ:
@768 וְעַבְדָךְ וְאַמְתָךְ דִי יְהוֹן לָךְ מִן עַמְמַיָא דִי בְסַחֲרָנֵיכוֹן מִנְהוֹן תִּקְנוּן עַבְדִין וְאַמְהָן:
@769 וְאַף מִבְּנֵי תוֹתָבַיָא עָרְלַיָא דְדָיְרִין עִמְכוֹן מִנְהוֹן תִּקְנוּן וּמִזַרְעִיתְהוֹן דְעִמְכוֹן דִי אִתְיְלִידוּ בְּאַרְעֲכוֹן וִיהוֹן לְכוֹן לְאַחֲסָנָא:
@770 וְתַחֲסוּן יָתְהוֹן לִבְנֵיכוֹן בַּתְרֵיכוֹן לִירוּתַת אַחֲסָנָא לְעָלָם בְּהוֹן תִּפְלְחוּן וּבְאֲחֵיכוֹן בְּנֵי יִשְׂרָאֵל גְבַר בַּאֲחוּהִי לָא תִפְלַח בֵּהּ בְּקַשְׁיוּ:
@771 וַאֲרֵי תַדְבֵּק יַד עָרֵל וְתוֹתָב עִמָךְ וְיִתְמַסְכַּן אָחוּךְ עִמֵהּ וְיִזְדַבַּן לְעָרֵל תּוֹתָב עִמָךְ אוֹ לְאַרְמַי זַרְעִית גִיוֹרָא:
@772 בָּתַר דְיִזְדַבַּן פֻּרְקָנָא תְּהֵי לֵהּ חַד מֵאֲחוֹהִי יִפְרְקִנֵהּ:
@773 אוֹ אַח אֲבוּהִּי אוֹ בַר אַח אֲבוּהִי יִפְרְקִנֵהּ אוֹ מִקָרִיב בִּשְׂרֵהּ מִזַרְעִיתֵהּ יִפְרְקִנֵהּ אוֹ דְתַדְבֵּק יְדֵהּ וְיִתְפָּרָק:
@774 וִיחַשֵׁב עִם זָבְנֵהּ מִשַׁתָּא דְאִזְדַבַּן לֵהּ עַד שַׁתָּא דְיוֹבֵלָא וִיהֵי כְּסַף זְבִינוֹהִי בְּמִנְיַן שְׁנַיָא כְּיוֹמֵי אֲגִירָא יְהֵי עִמֵהּ:
@775 אִם עוֹד סְגִיוּת בִּשְׁנַיָא לְפוּמְהֵן יָתֵב פֻּרְקָנֵהּ מִכְּסַף זְבִינוֹהִי:
@776 וְאִם זְעֵר יִשְׁתָּאַר בִּשְׁנַיָא עַד שַׁתָּא דְיוֹבֵלָא וִיחַשֶׁב לֵהּ כְּפוּם שְׁנוֹהִי יָתֵב יָת פּוּרְקָנֵהּ:
@777 כַּאֲגִיר שְׁנָא בִּשְׁנָא יְהֵי עִמֵהּ לָא יִפְלַח בֵּהּ בְּקַשְׁיוּ לְעֵינָיךְ:
@778 וְאִם לָא יִתְפָּרַק בְּאִלֵין וְיִפּוֹק בְּשַׁתָּא דְיוֹבֵלָא הוּא וּבְנוֹהִי עִמֵהּ:
@779 אֲרֵי דִילִי בְנֵי יִשְׂרָאֵל עַבְדִין עַבְדַי אִנוּן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהֲכוֹן:
@780 לָא תַעְבְּדוּן לְכוֹן טַעֲוָן וְצֶלֶם וְקָמָא לָא תְקִימוּן לְכוֹן וְאֶבֶן סָגְדָא לָא תִתְּנוּן בְּאַרְעֲכוֹן לְמִסְגֻד עֲלַהּ אֲרֵי אֲנָא יְיָ אֱלָהֲכוֹן:
@781 יָת יוֹמֵי שַׁבַּיָא דִילִי תִטְרוּן וּלְבֵית מַקְדְשִׁי תְּהוֹן דָחֲלִין אֲנָא יְיָ: פפפ:
@782 אִם בִּקְיָמַי תְּהָכוּן וְיָת פִּקוֹדַי תִּטְרוּן וְתַעֲבְּדוּן יָתְהוֹן:
@783 וְאֶתֵּן מַטְּרְכוֹן בְּעִדָנְהוֹן וְתִתֵּן אַרְעָא עֲלַלְתָּהּ וְאִילַן חַקְלָא יִתֵּן אִבֵּהּ:
@784 וִיעָרַע לְכוֹן דְיָשָׁא יָת קְטָפָא וּקְטָפָא יְעָרַע לְאַפּוֹקֵי בַר זַרְעָא וְתֵיכְלוּן לַחְמְכוֹן לְמִשְׂבַּע וְתֵיתְבוּן לְרָחְצָן בְּאַרְעַכוֹן:
@785 וְאֶתֵּן שְׁלָמָא בְּאַרְעָא וְתִשְׁרוּן וְלֵית דְמָנִיד וֶאֱבַטֵל חַיְתָא בִשְׁתָּא מִן אַרְעָא וּדְקַטְלִין בְּחַרְבָּא לָא יְעִדוּן בְּאַרְעֲכוֹן:
@786 וְתִרְדְפוּן יָת בַּעֲלֵי דְבָבֵיכוֹן וְיִפְּלוּן קֳדָמֵיכוֹן לְחַרְבָּא:
@787 וְיִרְדְפוּן מִנְכוֹן חַמְשָׁא מְאָה וּמְאָה מִנְכוֹן לְרִבּוֹתָא יֵיעִירְקוּן וְיִפְּלוּן בַּעֲלֵי דְבָבֵיכוֹן קֳדָמֵיכוֹן לְחַרְבָּא:
@788 וְאֶתְפְּנֵי בְּמֵימְרִי לְאוֹטָבָא לְכוֹן וְאַפֵּשׁ יָתְכוֹן וְאַסְגֵי יָתְכוֹן וַאֲקֵם יָת קְיָמִי עִמְכוֹן:
@789 וְתֵיכְלוּן עַתִּיקָא דְעַתִּיק וְעַתִּיקָא מִן קֳדָם חֲדַתָּא תְּפַנוּן:
@790 וְאֶתֵּן מַשְׁכְּנִי בֵּינֵיכוֹן וְלָא יְרַחֵק מֵימְרִי יָתְכוֹן:
@791 וְאַשְׁרֵי שְׁכִינְתִּי בֵּינֵיכוֹן וְאֶהֱוֵי לְכוֹן לֶאֱלָהּ וְאַתּוּן תְּהוֹן קֳדָמַי לְעָם:
@792 אֲנָא יְיָ אֱלָהֲכוֹן דִי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרַיִם מִלְמֶהֱוֵי לְהוֹן עַבְדִין וְתַבָּרִית נִיר עַמְמַיָא מִנְכוֹן וְדַבָּרִית יָתְכוֹן לְחֵרוּתָא:
@793 וְאִם לָא תְקַבְּלוּן לְמֵימְרִי וְלָא תַעְבְּדוּן יָת כָּל פִּקוּדַיָא הָאִלֵין:
@794 וְאִם בִּקְיָמַי תְּקוֹצוּן וְאִם יָת דִינַי תְּרַחֵק נַפְשְׁכוֹן בְּדִיל דְלָא לְמֶעְבַּד יָת כָּל פִּקוֹדַי לְאַשְׁנָיוּתְכוֹן יָת קְיָמִי:
@795 אַף אֲנָא אֶעְבֶּד דָא לְכוֹן וְאַסְעַר עֲלֵיכוֹן בַּהֶלְתָּא יָת שַׁחֶפְתָּא וְיָת קַדַחְתָּא מְחַשְׁכָן עַיְנִין וּמַפְּחַן נְפָשׁ וְתִזְרְעוּן לְרֵקָנוּן זַרְעֲכוֹן וְיֵיכְלֻנֵהּ בַּעֲלֵי דְבָבֵיכוֹן:
@796 וְאֶתֵּן רוּגְזִי בְּכוֹן וְתִתַּבְּרוּן קֳדָם בַּעֲלֵי דְבָבֵיכוֹן וְיִרְדוּן בְּכוֹן סַנְאֵכוֹן וְתֵעִירְקוּן וְלֵית דְרָדִיף יָתְכוֹן:
@797 וְאִם עַד אִלֵין לָא תְקַבְּלוּן לְמֵימְרִי וְאוֹסֵף לְמִרְדֵי יָתְכוֹן שְׁבַע עַל חוֹבֵיכוֹן:
@798 וְאֶתְבַּר יָת יְקַר תָּקְפְּכוֹן וְאֶתֵּן יָת שְׁמַיָא דִי עִלָוֵיכוֹן תַּקִיפִין כְּפַרְזְלָא מִלַאֲחָתָא מִטְרָא וְאַרְעָא דִתְחוֹתֵיכוֹן חֲסִינָא כִּנְחָשָׁא מִלְמֶעְבַּד פֵּירִין:
@799 וִיסוּפוּן לְרֵיקָנוּ חֵילֵיכוֹן וְלָא תִתֵּן אַרְעֲכוֹן יָת עֲלַלְתָּהּ וְאִילַן אַרְעָא לָא יִתֵּן אִבֵּהּ:
@800 וְאִם תְּהָכוּן קֳדָמַי בְּקַשְׁיוּ וְלָא תֵיבוּן לְקַבָּלָא לְמֵימְרִי וְאוֹסֵף לֶאֱתָאָה עֲלֵיכוֹן מָחָא שְׁבַע כְּחוֹבֵיכוֹן:
@801 וֶאֶגָרֵי בְכוֹן יָת חֵוַת בָּרָא וּתְתַכֵּל יָתְכוֹן וּתְשֵׁיצֵי יָת בְּעִירְכוֹן וְתַזְעֵר יָתְכוֹן וִיצַדְיָן אוֹרְחָתְכוֹן:
@802 וְאִם בְּאִלֵין לָא תִתְרְדוּן לְמֵימְרִי וּתְהָכוּן קֳדָמַי בְּקַשְׁיוּ:
@803 וְאֵהַךְ אַף אֲנָא עִמְכוֹן בְּקַשְׁיוּ וְאַלְקֵי יָתְכוֹן אַף אֲנָא שְׁבַע עַל חוֹבֵיכוֹן:
@804 וְאַיְתִי עֲלֵיכוֹן דְקָטְלִין בְּחַרְבָּא וְיִתְפָּרְעוּן מִנְכוֹן פּוּרְעֲנוּתָא עַל דַעֲבַרְתּוּן עַל פִתְגָמֵי אוֹרַיְתָא וְתִתְכַּנְשׁוּן לְקִרְוֵיכוֹן וֶאֱגָרֵי מוֹתָנָא בֵּינֵיכוֹן וְתִתְמַסְרוּן בִּידָא דְסָנְאָה:
@805 בִּדְאִתְּבַר לְכוֹן סָעִיד מֵיכְלָא וְיָפְיָן עֲסַר נְשִׁין לַחְמְכוֹן בְּתַנוּרָא חַד וִיתִיבוּן לַחְמְכוֹן בְּמַתְקְלָא וְתוֹכְלוּן וְלָא תִשְׂבְּעוּ ן:
@806 וְאִם בְּדָא לָא תְקַבְּלוּן לְמֵימְרִי וּתְהָכוּן קֳדָמַי בְּקַשְׁיוּ:
@807 וְאֵהַךְ עִמְכוֹן בִּתְקוֹף רְגַז וְאִרְדֵי יָתְכוֹן אַף אֲנָא שְׁבַע עַל חוֹבֵיכוֹן:
@808 וְתֵיכְלוּן בְּשַׂר בְּנֵיכוֹן וּבְשַׂר בְּנָתֵיכוֹן תֵּיכְלוּן:
@809 וֶאֱשֵׁיצֵי יָת בָּמָתֵיכוֹן וֶאֱקַצֵץ יָת חֲנִיסְנְסֵיכוֹן וְאֶתֵּן יָת פִּגְרֵיכוֹן עַל פִּגוּר טַעֲוָתְכוֹן וִירַחֵק מֵימְרִי יָתְכוֹן:
@810 וְאֶתֵּן יָת קִרְוֵיכוֹן צָדָא וְאֶצְדֵי יָת מַקְדְשֵׁיכוֹן וְלָא אֲקַבֵּל בְּרַעֲוָא קֻרְבַּן כְּנִשָׁתְכוֹן:
@811 וְאֶצְדֵי אֲנָא יָת אַרְעָא וִיצָרְיוּן עֲלַהּ בַּעֲלֵי דְבָבֵיכוֹן דְיָתְבוּן בַּהּ:
@812 וְיָתְכוֹן אֲבַדַר בֵּינֵי עַמְמַיָא וֶאֱגָרֵי בַתְרֵיכוֹן דְקַטְלִין בְּחַרְבָּא וּתְהֵי אַרְעֲכוֹן צָדְיָא וְקִרְוֵיכוֹן יְהוֹן חָרְבָּא:
@813 בְּכֵן תַּרְעֵי אַרְעָא יָת שְׁמִטָהָא כֹּל יוֹמִין דִי צְדִיאַת וְאַתּוּן בְּאַרַע בַּעֲלֵי דְבָבֵיכוֹן בְּכֵן תַּשְׁמֵט אַרְעָא וְתִרְעֵי יָת שְׁמִטָּהָא:
@814 כָּל יוֹמִין דִי צְדִיאַת תַּשְׁמֵט יָת דִי לָא שְׁמֵטַת בִּשְׁמִטֵיכוֹן כַּד הֲוֵיתוּן יָתְבִין עֲלַהּ:
@815 וּדְיִשְׁתַּאֲרוּן בְּכוֹן וְאָעֵל תַּבְרָא בְּלִבְּהוֹן בְּאַרְעֲתָא דְסַנְאֵיהוֹן וְיִרְדוֹף יָתְהוֹן קַל טַרְפָּא דְשַׁקִיף וְיֵעַרְקֻן כְּמֵעִירוֹק מִן קֳדָם דְקַטְלִין בְּחַרְבָּא וְיִפְּלוּן וְלֵית דְרָדִיף:
@816 וְיִתַּקְלוּן גְבַר בְּאָחוּהִי כְּמִקֳדָם דְקָטְלִין בְּחַרְבָּא וְרָדִיף לָיִת וְלָא תְהֵי לְכוֹן תְּקוּמָה קֳדָם בַּעֲלֵי דְבָבֵיכוֹן:
@817 וְתֵבְדוּן בֵּינֵי עַמְמַיָא וּתְגַמַר יָתְכוֹן אֲרַע בַּעֲלֵי דְבָבֵיכוֹן:
@818 וּדְיִשְׁתַּאֲרוּן בְּכוֹן יִתִּמְסוּן בְּחוֹבֵיהוֹן בְּאַרְעֲתָא בַּעֲלֵי דְבָבֵיכוֹן וְאַף בְּחוֹבֵי אֲבָהַתְהוֹן בִּישַׁיָא דַאֲחִידִין בִּידֵיהוֹן יִתִּמְסוּן:
@819 וִיוַדוּן יָת חוֹבֵיהוֹן וְיָת חוֹבֵי אֲבָהַתְהוֹן בְּשִׁקְרְהוֹן דְשַׁקָרוּ קֳדָמַי וְאַף דִי הַלִיכוּ קֳדָמַי בְּקַשְׁיוּ:
@820 אַף אֲנָא אֱהַךְ עִמְהוֹן בְּקַשְׁיוּ וְאָעֵיל יָתְהוֹן בְּאַרַע בַּעֲלֵי דְבָבֵיהוֹן אוֹ בְּכֵן יִתָּבַר לִבְּהוֹן טַפְשָׁא וּבְכֵן יִרְעוּן יָת חוֹבֵיהוֹן:
@821 וְדָכִירְנָא יָת קְיָמִי דְעִם יַעֲקוֹב וְאַף יָת קְיָמִי דְעִם יִצְחָק וְאַף יָת קְיָמִי דְעִם אַבְרָהָם אֲנָא דָכִיר וְאַרְעָא אֲנָא דָכִיר:
@822 וְאַרְעָא תִתְרְטֵשׁ מִנְהוֹן וְתַרְעֵי יָת שְׁמִיטָהָא בְּדִצְדִיאַת מִנְהוֹן וְאִנוּן יִרְעוּן יָת חוֹבֵיהוֹן לְוָטִין חֳלַף בִּרְכָן אַיְתִי עֲלֵיהוֹן בְּדִיל דִבְדִינַי קָצוּ וְיָת קְיָמַי רְחֵקַת נַפְשְׁהוֹן:
@823 וְאַף בְּרַם דָא בְּמֶהֱוֵיהוֹן בְּאַרַע בַּעֲלֵי דְבָבֵיהוֹן לָא אַרְטֵשִׁנוּן וְלָא אַרְחֵקִנוּן לְשֵׁיצָיוּתְהוֹן לְאַשְׁנָאָה קְיָמִי עִמְהוֹן אֲרֵי אֲנָא יְיָ אֱלָהֲהוֹן:
@824 וְדָכִירְנָא לְהוֹן קְיַם קַדְמָאֵי דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְעֵינֵי עַמְמַיָא לְמֶהֱוֵי לְהוֹן לֵאלָהָא אֲנָא יְיָ:
@825 אִלֵין קְיָמַיָא וְדִינַיָא וְאוֹרָיָתָא דִי יְהַב יְיָ בֵּין מֵימְרֵהּ וּבֵין בְּנֵי יִשְׂרָאֵל בְּטוּרָא דְסִינַי בִּידָא דְמֹשֶׁה:
@826 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@827 מַלֵל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן גְבַר אֲרֵי יַפְרֵשׁ נְדַר בְּפֻרְסַן נַפְשָׁתָא קֳדָם יְיָ:
@828 וִיהֵי פֻרְסָנֵהּ דְכוּרָא מִבַּר עֶסְרִין שְׁנִין וְעַד בַּר שִׁתִּין שְׁנִין וִיהֵי פֻרְסָנֵהּ חַמְשִׁין סִלְעִין דִכְסַף בְּסִלְעֵי קוּדְשָׁא:
@829 וְאִם נְקוּבְתָא הִיא וִיהֵי פֻרְסָנֵהּ תְּלָתִין סִלְעִין:
@830 וְאִם מִבַּר חֲמֵשׁ שְׁנִין וְעַד בַּר עֶסְרִין שְׁנִין וִיהֵי פֻרְסָנֵהּ דְכוּרָא עֶסְרִין סִלְעִין וְלִנְקוּבְתָא עֲסַר סִלְעִין:
@831 וְאִם מִבַּר יַרְחָא וְעַד בַּר חֲמֵשׁ שְׁנִין וִיהֵי פֻרְסָנֵהּ דְכוּרָא חֲמֵשׁ סִלְעִין דִכְסָף וְלִנְקוּבְתָא פֻרְסָנֵהּ תְּלַת סִלְעִין דִכְסָף:
@832 וְאִם מִבַּר שִׁתִּין שְׁנִין וּלְעֵלָא אִם דְכוּרָא וִיהֵי פֻרְסָנֵהּ חֲמֵשׁ עֶסְרֵי סִלְעִין וְלִנְקוּבְתָא עֲסַר סִלְעִין:
@833 וְאִם מִסְכֵּן הוּא מִפֻּרְסָנֵהּ וִיקִימִנֵהּ קֳדָם כַּהֲנָא וְיִפְרוֹס יָתֵהּ כַּהֲנָא עַל מֵימַר דִי תַדְבֵּק יְדָא דְנוֹדֵרָא יִפְרְסִנֵהּ כַּהֲנָא:
@834 וְאִם בְּעִירָא דִי יְקָרְבוּן מִנַהּ קֻרְבָּנָא קֳדָם יְיָ כָּל דִי יִתֵּן מִנֵהּ קֳדָם יְיָ יְהֵי קוּדְשָׁא:
@835 לָא יְחַלְפִנֵהּ וְלָא יְעִבַּר יָתֵהּ טַּב בְּבִישׁ אוֹ בִישׁ בְּטָב וְאִם חַלָפָא יְחַלֵף בְּעִירָא בִּבְעִירָא וִיהֵי הוּא וְחִלוּפֵי יְהֵי קַדִישׁ:
@836 וְאִם כָּל בְּעִירָא מְסָאָבָא דִי לָא יְקָרְבוּן מִנַהּ קֻרְבָּנָא קֳדָם יְיָ וִיקִים יָת בְּעִירָא קֳדָם כַּהֲנָא:
@837 וְיִפְרוֹס כַּהֲנָא יָתַהּ בֵּין טַב וּבֵין בִּישׁ כְּפֻרְסָנָא דְכַהֲנָא כֵּן יְהֵי:
@838 וְאִם מִפְרַק יִפְרְקֻנֵהּ וְיוֹסֵף חֻמְשֵׁה עַל פֻּרְסָנֵהּ:
@839 וּגְבַר אֲרֵי יַקְדֵשׁ יָת בֵּיתֵהּ קוּדְשָׁא קֳדָם יְיָ וְיִפְרְסִנֵהּ כַּהֲנָא בֵּין טַב וּבֵין בִּישׁ כְּמָא דִי יִפְרוֹס יָתֵהּ כַּהֲנָא כֵּן יְקוּם:
@840 וְאִם דְאַקְדֵשׁ יִפְרוֹק יָת בֵּיתֵהּ וְיוֹסֵף חוֹמֶשׁ כְּסַף פֻּרְסָנֵהּ עֲלוֹהִי וִיהֵי לֵהּ:
@841 וְאִם מֵחֲקַל אַחֲסַנְתֵּהּ יַקְדִישׁ גְבַר קֳדָם יְיָ וִיהֵי פֻרְסָנֵהּ לְפוּם זַרְעֵהּ בַּר זְרַע כּוֹר שְׂעוֹרִין בְּחַמְשִׁין סִלְעִין דִכְסָף:
@842 אִם מִשַּׁתָּא דְיוֹבֵלָא יַקְדֵשׁ חַקְלֵהּ כְּפֻרְסָנֵהּ יְקוּם:
@843 וְאִם בָּתַר יוֹבֵלָא יַקְדֵשׁ חַקְלֵהּ וִיחַשֵׁב לֵהּ כַּהֲנָא יָת כַּסְפָּא עַל מֵימַר שְׁנַיָא דְאִשְׁתָּאָרָן עַד שַׁתָּא דְיוֹבֵלָא וְיִתִּמְנַע מִפֻּרְסָנֵהּ:
@844 וְאִם מִפְרַק יִפְרוֹק יָת חַקְלָא דְאַקְדֵשׁ יָתֵהּ וְיוֹסֵף חוֹמֶשׁ כְּסַף פֻּרְסָנֵהּ עֲלוֹהִי וִיקוּם לֵהּ:
@845 וְאִם לָא יִפְרוֹק יָת חַקְלָא וְאִם זַבִּין יָת חַקְלָא לִגְבַר אָחֳרָן לָּא יִתְפָּרַק עוֹד:
@846 וִיהֵי חַקְלָא בְּמִפְּקֵהּ בְּיוֹבֵלָא קוּדְשָׁא קֳדָם יְיָ כַּחֲקַל חֶרְמָא לְכַהֲנָא תְּהֵי אַחֲסַנְתֵּהּ:
@847 וְאִם יָת חֲקַל זְבִינוֹהִי דִי לָא מֵחֲקַל אַחֲסַנְתֵּהּ יַקְדֵשׁ קֳדָם יְיָ:
@848 וִיחַשֶׁב לֵהּ כַּהֲנָא יָת מִנְיַן פֻּרְסָנֵהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִתֵּן יָת פֻרְסָנֵהּ בְּיוֹמָא הַהוּא קוּדְשָׁא קֳדָם יְיָ:
@849 בְּשַׁתָּא דְיוֹבֵלָא יְתוּב חַקְלָא לִדְזַבְנֵהּ מִנֵהּ לִדְדִילֵהּ אַחֲסָנַת אַרְעָא:
@850 וְכָל פֻּרְסָנֵּה יְהֵי בְּסִלְעֵי קוּדְשָׁא עֶסְרִין מָעִין יְהֵי סִלְעָא:
@851 בְּרַם בּוּכְרָא דִי יִתְבַּכַּר קֳדָם יְיָ בִּבְעִירָא לָא יַקְדֵשׁ גְבַר יָתֵהּ אִם תּוֹר אִם אִמַר דַיְיָ הוּא:
@852 וְאִם בִּבְעִירָא מְסָאָבָא וְיִפְרוֹק בְּפֻרְסָנֵהּ וְיוֹסֵף חֻמְשֵׁהּ עֲלוֹהִי וְאִם לָא יִתְפָּרַק וְיִזְדַבַּן בְּפֻרְסָנֵהּ:
@853 בְּרַם כָּל חֶרְמָא דִי יַחְרֵם גְבַר קֳדָם יְיָ מִכָּל דִי לֵהּ מֵאֲנָשָׁא וּבְעִירָא וּמֵחֲקַל אַחֲסַנְתֵּהּ לָא יִזְדַבַּן וְלָא יִתְפָּרָק כָּל חֶרְמָא קֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ:
@854 כָּל חֶרְמָא דִי יִתַּחְרַם מִן אֱנָשָׁא לָא יִתְפָּרָק אִתְקְטָלָא יִתְקְטֵל:
@855 וְכָל מַעְשְׂרָא דְאַרְעָא מִזַרְעָא דְאַרְעָא מִפֵּירֵי אִילָנָא דַיְיָ הוּא קוּדְשָׁא קֳדָם יְיָ:
@856 וְאִם מִפְרַק יִפְרוֹק גְבַר מִמַעַשְׂרֵהּ חֻמְשֵׁהּ יוֹסֵף עֲלוֹהִי:
@857 וְכָל מַעֲשַׂר תּוֹרִין וְעָן כֹּל דְיֵעִבַּר תְּחוֹת חֻטְרָא עֲשִׂירָאָה יְהֵי קַדִישׁ קֳדָם יְיָ:
@858 לָא יְבַקַר בֵּין טַב לְבִישׁ וְלָא יְחַלְפִנֵהּ וְאִם חַלָפָא יְחַלְפִנֵהּ וִיהֵי הוּא וְחִלוּפֵהּ יְהֵי קוּדְשָׁא לָא יִתְפָּרָק:
@859 אִלֵין פִּקוֹדַיָא דִי פַקִיד יְיָ יָת מֹשֶׁה לְוָת בְּנֵי יִשְׂרָאֵל בְּטוּרָא דְסִינָי: חזק:

@1 **ויקרא אל משה.** לכל דברות ולכל אמירות ולכל צוויים קדמה קריאה, לשון חבה, לשון שמלאכי השרת משתמשים בו, שנאמר (ישעיה ו ג) וקרא זה אל זה, אבל לנביאי אמות העולם נגלה עליהן בלשון עראי וטמאה, שנאמר (במדבר כג ד) ויקר אלהים אל בלעם: **ויקרא אל משה.** הקול הולך ומגיע לאזניו, וכל ישראל לא שומעין. יכול אף להפסקות היתה קריאה, תלמוד לומר וידבר, לדבור היתה קריאה, ולא להפסקות. ומה היו הפסקות משמשות, לתן רוח למשה להתבונן בין פרשה לפרשה ובין ענין לענין, קל וחומר להדיוט הלומד מן ההדיוט: **אליו.** למעט את אהרן. ר' יהודה בן בתירא אומר שלשה עשר דברות נאמרו בתורה למשה ולאהרן, וכנגדן נאמרו שלשה עשר מיעוטין, ללמדך שלא לאהרן נאמרו אלא למשה שיאמר לאהרן. ואלו הן שלשה עשר מיעוטין לדבר אתו, מדבר אליו, וידבר אליו, ונועדתי לך, כלן בתורת כהנים. יכול שמעו את קול הקריאה, תלמוד לומר קול לו, קול אליו (במדבר ז פט) , משה שמע, וכל ישראל לא שמעו: **מאהל מועד.** מלמד שהיה הקול נפסק ולא היה יוצא חוץ לאהל. יכול מפני שהקול נמוך, תלמוד לומר את הקול (שם) , מהו הקול, הוא הקול המפורש בתהלים (כט ד. ה) קול ה' בכח קול ה' בהדר, קול ה' שובר ארזים, אם כן למה נאמר מאהל מועד, מלמד שהיה הקול נפסק. כיוצא בו (יחזקאל י ה) וקול כנפי הכרובים נשמע עד החצר החיצונה, יכול (מפני) שהקול נמוך, תלמוד לומר (שם) כקול אל שדי בדברו, אם כן למה נאמר עד החצר החיצונה, שכיון שמגיע שם היה נפסק: **מאהל מועד לאמר.** יכול מכל הבית, תלמוד לומר מעל הכפורת. יכול מעל הכפורת כלה, תלמוד לומר מבין שני הכרובים: **לאמר.** צא ואמר להם דברי כבושים, בשבילכם הוא נדבר עמי, שכן מצינו שכל שלשים ושמונה שנה שהיו ישראל במדבר כמנדים, מן המרגלים ואלך, לא נתיחד הדבור עם משה, שנאמר (דב' ב טז) ויהי כאשר תמו כל אנשי המלחמה למות וידבר ה' אלי לאמר, אלי היה הדבור. דבר אחר צא ואמור להם דברי והשיבני אם יקבלום, כמו שנאמר (שמות יט ח) וישב משה את דברי העם וגו' :
@2 **אדם כי יקריב מכם.** כשיקריב, בקרבנות נדבה דבר הענין: **אדם.** למה נאמר, מה אדם הראשון לא הקריב מן הגזל, שהכל היה שלו, אף אתם לא תקריבו מן הגזל: **הבהמה.** יכול אף חיה בכלל, תלמוד לומר בקר וצאן: **מן הבהמה.** ולא כלה, להוציא את הרובע ואת הנרבע: **מן הבקר.** להוציא את הנעבד: **מן הצאן.** להוציא את המקצה: **ומן הצאן.** להוציא את הנוגח שהמית. כשהוא אומר למטה מן הענין (פסוק ג) מן הבקר, שאין תלמוד לומר, להוציא את הטרפה: **תקריבו.** מלמד ששנים מתנדבים עולה בשותפות: **קרבנכם.** מלמד שהיא באה נדבת צבור, היא עולת קיץ המזבח הבאה מן המותרות:
@3 **זכר.** ולא נקבה. כשהוא אומר זכר למטה, שאין תלמוד לומר, זכר ולא טומטום ואנדרוגינוס: **תמים.** בלא מום: **אל פתח אהל מועד.** מטפל בהבאתו עד העזרה. מהו אומר יקריב יקריב, אפלו נתערבה עולת ראובן בעולת שמעון, יקריב כל אחת לשם מי שהוא. וכן עולה בחלין, ימכרו החלין לצרכי עולות, והרי הן כלן עולות ותקרב כל אחת לשם מי שהוא. יכול אפלו נתערבה בפסולין או בשאינו מינו, תלמוד לומר יקריבנו: **יקריב אתו.** מלמד שכופין אותו. יכול בעל כרחו, תלמוד לומר לרצונו, הא כיצד כופין אותו עד שיאמר רוצה אני: **לפני ה' וסמך.** אין סמיכה בבמה:
@4 **על ראש העולה.** להביא עולת חובה לסמיכה ולהביא עולת הצאן: **העלה.** פרט לעולת העוף: **ונרצה לו.** על מה הוא מרצה לו, אם תאמר על כריתות ומיתות בית דין או מיתה בידי שמים או מלקות, הרי ענשן אמור, הא אינו מרצה אלא על עשה ועל לאו שנתק לעשה:
@5 **ושחט' והקריבו' הכהנים.** מקבלה ואלך מצות כהנה, למד על השחיטה שכשרה בזר: **לפני ה'.** בעזרה: **והקריבו.** זו קבלה שהיא הראשונה ומשמעה לשון הולכה, למדנו ששתיהן בבני אהרן: **בני אהרן.** יכול חללים, תלמוד לומר הכהנים: **את הדם וזרקו את הדם.** מה תלמוד לומר דם דם שתי פעמים, להביא את שנתערב במינו או בשאינו מינו. יכול אף בפסולים או בחטאות הפנימיות או בחטאות החיצוניות, שאלו למעלה והיא למטה, תלמוד לומר במקום אחר את דמו: **וזרקו.** עומד למטה וזורק מן הכלי לכתל המזבח למטה מחוט הסיקרא כנגד הזויות, לכך נאמר סביב, שיהא הדם נתן בארבע רוחות המזבח. או יכול יקיפנו כחוט, תלמוד לומר וזרקו, ואי אפשר להקיף בזריקה. אי וזרקו יכול בזריקה אחת, תלמוד לומר סביב, הא כיצד נותן שתי מתנות שהן ארבע: **אשר פתח אהל מועד.** ולא בזמן שהוא מפורק:
@6 **והפשיט את העלה.** מה תלמוד לומר העלה, לרבות את כל העולות להפשט ונתוח: **אתה לנתחיה.** ולא נתחיה לנתחים:
@7 **ונתנו אש.** אף על פי שהאש יורדת מן השמים, מצוה להביא מן ההדיוט: **בני אהרן הכהן.** כשהוא בכהונו, הא אם עבד בבגדי כהן הדיוט, עבודתו פסולה:
@8 **בני אהרן הכהנים.** כשהם בכהונם, הא כהן הדיוט שעבד בשמונה בגדים, עבודתו פסולה: **את הנתחים את הראש.** לפי שאין הראש בכלל הפשט, שכבר התז בשחיטה, לפיכך הצרך למנותו לעצמו: **ואת הפדר.** למה נאמר, ללמדך שמעלהו עם הראש ומכסה בו את בית השחיטה, וזהו דרך כבוד של מעלה: **אשר על המזבח.** שלא יהיו הגזירין יוצאין חוץ למערכה:
@9 **עלה.** לשם עולה יקטירנו: **אשה.** כשישחטנו יהא שוחטו לשם האש. וכל אשה לשון אש פויאד''א בלע''ז : **ניחוח.** נחת רוח לפני, שאמרתי ונעשה רצוני:
@10 **ואם מן הצאן.** וי''ו מוסיף על ענין ראשון. ולמה הפסיק, לתן רוח למשה להתבונן בין פרשה לפרשה: **מן הצאן מן הכבשים או מן העזים.** הרי אלו שלשה מיעוטין פרט לזקן, לחולה ולמזוהם:
@11 **על ירך המזבח.** על צד המזבח: **צפנה לפני ה'.** ואין צפון בבמה:
@14 **מן העוף.** ולא כל העוף, לפי שנאמר (ויקרא כב יט) תמים זכר בבקר בכשבים ובעזים, תמות וזכרות בבהמה, ואין תמות וזכרות בעופות, יכול אף מחסר אבר, תלמוד לומר מן העוף: **התרים.** גדולים ולא קטנים: **בני היונה.** קטנים ולא גדולים: **מן התרים או מן בני היונה.** פרט לתחלת הצהוב, שבזה ושבזה שהוא פסול, שגדול הוא אצל בני יונה וקטן אצל תורים:
@15 **והקריבו.** אפלו פרידה אחת יביא: **הכהן ומלק.** אין מליקה בכלי אלא בעצמו של כהן. קוצץ בצפרנו ממול העורף וחותך מפרקתו עד שמגיע לסימנין וקוצצן: **ונמצה דמו.** לשון מיץ אפים (משלי ל לג) , כי אפס המץ (ישעיה טז ד) , כובש בית השחיטה על קיר המזבח והדם מתמצה ויורד: **ומלק' והקטיר' ונמצה.** אפשר לומר כן, מאחר שהוא מקטיר הוא מוצה, אלא מה הקטרה הראש בעצמו והגוף בעצמו, אף מליקה כן. ופשוטו של מקרא מסורס הוא ומלק והקטיר, וקודם הקטרה, ונמצה דמו כבר:
@16 **מראתו.** מקום הרעי וזה הזפק: **בנצתה.** עם בני מעיה. ונוצה לשון דבר המאוס, כמו כי נצו גם נעו (איכה ד טו) וזה שתרגם אנקלוס באוכליה. וזהו מדרשו של אבא יוסי בן חנן, שאמר נוטל את הקרקבן עמה. ורבותינו זכרונם לברכה אמרו קודר סביב הזפק בסכין כעין ארבה ונוטלו עם הנוצה שעל העור. בעולת בהמה, שאינה אוכלת אלא באבוס בעליה, נאמר (פסוק יג) והקרב והכרעים ירחץ במים והקטיר, ובעוף, שנזון מן הגזל, נאמר והשליך, את המעים, שאכל מן הגזל: **אצל המזבח קדמה.** במזרחו של כבש: **אל מקום הדשן.** מקום שנותנין שם תרומת הדשן בכל בקר ודשון מזבח הפנימי והמנורה. וכלם נבלעים שם במקומן:
@17 **ושסע.** אין שסוע אלא ביד, וכן הוא אומר בשמשון (שופטים יד ו) וישסעהו כשסע הגדי: **בכנפיו.** עם כנפיו, אינו צריך למרוט כנפי נוצתו: **בכנפיו.** נוצה ממש. והלא אין לך הדיוט שמריח ריח רע של כנפים נשרפים ואין נפשו קצה עליו, ולמה אמר הכתוב והקטיר, כדי שיהא המזבח שבע ומהדר בקרבנו של עני: **לא יבדיל.** אינו מפרקו לגמרי לשתי חתכות, אלא קורעו מגבו. נאמר בעוף ריח ניחוח, ונאמר בבהמה ריח ניחוח, לומר לך אחד המרבה ואחד הממעיט, ובלבד שיכון את לבו לשמים:
@18 **ונפש כי תקריב.** לא נאמר נפש בכל קרבנות נדבה אלא במנחה, מי דרכו להתנדב מנחה, עני, אמר הקדוש ברוך הוא מעלה אני עליו כאלו הקריב נפשו: **סלת יהיה קרבנו.** האומר הרי עלי מנחה סתם, מביא מנחת סלת, שהיא הראשונה שבמנחות ונקמצת כשהיא סלת, כמו שמפורש בענין. לפי שנאמרו כאן חמשה מיני מנחות, וכלן באות אפויות קודם קמיצה חוץ מזו, לכך קרויה מנחת סלת: **סלת.** אין סלת אלא מן החטין, שנאמר (שמות כט ב) סלת חטים, ואין מנחה פחותה מעשרון, שנאמר (ויק' יד כא) ועשרון סלת למנחה, עשרון לכל מנחה: **ויצק עליה שמן.** על כלה: **ונתן עליה לבנה.** על מקצתה, מניח קמץ לבונה עליה לצד אחד. ומה ראית לומר כן, שאין רבוי אחר רבוי בתורה אלא למעט. דבר אחר שמן על כלה, מפני שהוא נבלל עמה ונקמץ עמה, כמו שנאמר (פסוק ב) מסלתה ומשמנה, ולבונה על מקצתה, שאינה נבללת עמה ולא נקמצת עמה, שנאמר (פסוק ב) על כל לבנתה, שלאחר שקמץ מלקט את הלבונה כלה מעליה ומקטירה: **ויצק' ונתן' והביאה.** מלמד שיציקה ובלילה כשרים בזר:
@19 **הכהנים וקמץ.** מקמיצה ואלך מצות כהנה: **וקמץ משם.** ממקום שרגלי הזר עומדות, ללמדך שהקמיצה כשרה בכל מקום בעזרה, אף באחת עשרה אמה של מקום דריסת רגלי ישראל: **מלא קמצו.** יכול מבורץ, מבצבץ ויוצא לכל צד, תלמוד לומר במקום אחר (ויק' ו ח) והרים ממנו בקמצו, אין לך כשר אלא מה שבתוך הקומץ. אי בקמצו יכול חסר, תלמוד לומר מלא. הא כיצד, חופה שלש אצבעותיו על פס ידו, וזהו קומץ במשמע לשון העברית: **על כל לבנתה.** לבד כל הלבונה יהא הקומץ מלא: **לבנתה והקטיר.** אף הלבונה בהקטרה: **מלא קמצו מסלתה ומשמנה.** הא אם קמץ ועלה בידו גרגיר מלח או קורט לבונה פסולה: **אזכרתה.** הקומץ העולה לגבוה הוא זכרון המנחה, שבו נזכר בעליה לטובה ולנחת רוח:
@20 **לאהרן ולבניו.** כהן גדול נוטל חלק בראש שלא במחלוקת, וההדיוט במחלוקת: **קדש קדשים.** היא להם: **מאשי ה'.** אין להם חלק בה אלא לאחר מתנות האשים:
@21 **וכי תקרב** וגו' **.** שאמר הרי עלי מנחת מאפה תנור, ולמד הכתוב שיביא או חלות או רקיקין, החלות בלולות, והרקיקין משוחין. ונחלקו רבותינו במשיחתן יש אומרים, מושחן וחוזר ומושחן עד שיכלה כל השמן שבלוג, שכל המנחות טעונות לוג שמן. ויש אומרים מושחן כמין כי יונית ושאר השמן נאכל בפני עצמו לכהנים. מה תלמוד לומר בשמן בשמן שתי פעמים, להכשיר שמן שני ושלישי היוצא מן הזיתים, ואין צריך שמן ראשון אלא למנורה, שנאמר בו (שמות כז כ) זך. ושנינו במנחות (עו א) כל המנחות האפויות לפני קמיצתן ונקמצות על ידי פתיתה, כלן באות עשר עשר חלות, והאמור בה רקיקין, באה עשרה רקיקין:
@22 **ואם מנחה על המחבת.** שאמר הרי עלי מנחת מחבת. וכלי הוא שהיה במקדש, שאופין בו מנחה על האור בשמן, והכלי אינו עמוק אלא צף, ומעשה המנחה שבתוכו קשין, שמתוך שהיא צפה, האור שורף את השמן. וכלן טעונות שלש מתנות שמן, יציקה, ובלילה, ומתן שמן בכלי קודם עשיתן: **סלת בלולה בשמן.** מלמד שבוללן בעודן סלת:
@23 **פתות אתה פתים.** לרבות כל המנחות, הנאפות קודם קמיצה, לפתיתה: **ויצקת עליה שמן מנחה הוא.** לרבות כל המנחות ליציקה. יכול אף מנחת מאפה תנור כן, תלמוד לומר עליה, אוציא את החלות ולא אוציא את הרקיקין, תלמוד לומר היא:
@24 **מרחשת.** כלי הוא שהיה במקדש עמוק, ומתוך שהיא עמוקה שמנה צבור ואין האור שורפו, לפיכך מעשה מנחה העשויין לתוכה רוחשין. כל דבר רך על ידי משקה נראה כרוחש ומנענע:
@25 **אשר יעשה מאלה.** מאחד מן המינים הללו: **והקריבה.** בעליה אל הכהן: **והגישה.** הכהן: **אל המזבח.** מגישה לקרן דרומית מערבית של מזבח:
@26 **את אזכרתה.** היא הקומץ:
@28 **וכל דבש.** כל מתיקת פרי קרויה דבש:
@29 **קרבן ראשית תקריבו.** מה יש לך להביא מן השאור ומן הדבש קרבן ראשית שתי הלחם של עצרת הבאים מן השאור, שנאמר (ויק' כג יז) חמץ תאפינה, ובכורים מן הדבש, כמו בכורי תאנים ותמרים:
@30 **מלח ברית.** שהברית כרותה למלח מששת ימי בראשית, שהבטחו המים התחתונים לקרב במזבח במלח, ונסוך המים בחג: **על כל קרבנך.** על עולת בהמה ועוף ואימורי כל הקדשים כלן:
@31 **ואם תקריב.** הרי אם משמש בלשון כי, שהרי אין זה רשות, שהרי במנחת העומר הכתוב מדבר, שהיא חובה, וכן (במדבר לו ד) ואם יהיה היובל וגו' : **מנחת בכורים.** במנחת העומר הכתוב מדבר, שהיא באה אביב בשעת בשול התבואה, ומן השעורים היא באה. נאמר כאן אביב, ונאמר להלן (שמות ט לא) כי השעורה אביב: **קלוי באש.** שמיבשין אותה על האור באבוב של קלאים, שאלולי כן אינה נטחנת בריחים, לפי שהיא לחה: **גרש כרמל.** גרוסה בעודה לחה: **גרש.** לשון שבירה וטחינה, גורסה בריחים של גרוסות, כמו (איכה ג טז) ויגרס בחצץ, וכן גרסה נפשי (תהלים קיט כ) : **כרמל.** בעוד הכר מלא, שהתבואה לחה ומלאה בקשין שלה, ועל כן נקראים המלילות כרמל, וכן (מלכים ב' ד מב) וכרמל בצקלונו:
@34 **שלמים.** שמטילים שלום בעולם. דבר אחר שלמים שיש בהם שלום למזבח ולכהנים ולבעלים:
@36 **ואת כל החלב** וגו' **.** להביא חלב שעל הקבה, דברי רבי ישמעאל. רבי עקיבא אומר להביא חלב שעל הדקין:
@37 **הכסלים.** פלנק''ש בלע''ז . שהחלב שעל הכליות, כשהבהמה חיה, הוא בגובה הכסלים והם מלמטה, וזהו החלב שתחת המתנים, שקורין בלע''ז לונביל''ש , לובן הנראה למעלה בגובה הכסלים, ובתחתיתו הבשר חופהו: **היתרת.** הוא דופן המסך, שקורין איברי''ש ובלשון ארמי חצרא דכבדא: **על הכבד.** שיטול מן הכבד עמה מעט. ובמקום אחר הוא אומר (ויק' ט י) ואת היותרת מן הכבד: **על הכבד על הכליות.** לבד מן הכבד ולבד מן הכליות יסירנה לזו:
@38 **על העלה.** מלבד העולה. למדנו שתקדים עולת תמיד לכל קרבן על המערכה:
@40 **אם כשב.** לפי שיש באימורי הכשב מה שאין באימורי העז, שהכשב אליתו קרבה, לכך נחלקו לשתי פרשיות:
@41 **וזרקו.** שתי מתנות שהן ארבע, ועל ידי הכלי הוא זורק, ואינו נותן באצבע אלא חטאת:
@42 **חלבו.** המבחר שבו. ומהו זה, האליה תמימה: **לעמת העצה.** למעלה מן הכליות היועצות:
@44 **לחם אשה לה'.** לחמו של אש לשם גבוה: **לחם.** לשון מאכל, וכן (ירמיהו יא יט) נשחיתה עץ בלחמו, (דניאל ה א) עבד לחם רב, (קהלת י יט) לשחוק עשים לחם:
@50 **חקת עולם.** יפה מפורש בתורת כהנים כל הפסוק הזה:
@52 **מכל מצות ה'.** פרשו רבותינו אין חטאת באה אלא על דבר שזדונו לאו וכרת (ושגגתו חטאת) : **מאחת מהנה.** ממקצת אחת מהן, כגון הכותב בשבת שם משמעון, נח מנחור, דן מדניאל:
@53 **אם הכהן המשיח יחטא לאשמת העם.** מדרשו אינו חיב אלא בהעלם דבר עם שגגת מעשה, כמו שנאמר לאשמת העם ונעלם דבר מעיני הקהל ועשו (פסוק יג) . ופשוטו לפי אגדה, כשכהן גדול חוטא, אשמת העם הוא זה, שהן תלויין בו לכפר עליהם ולהתפלל בעדם, ונעשה מקלקל: **פר.** יכול זקן, תלמוד לומר בן, אי בן יכול קטן, תלמוד לומר פר, הא כיצד, זה פר בן שלש:
@55 **אל אהל מועד.** למשכן, ובבית עולמים להיכל:
@56 **את פני פרכת הקדש.** כנגד מקום קדשתה, מכון כנגד בין הבדים, ולא היו נוגעים דמים בפרכת, ואם נגעו נגעו:
@57 **ואת כל דם.** שירי הדם:
@58 **ואת כל חלב פר.** חלבו היה לו לומר, מה תלמוד לומר פר, לרבות פר של יום הכפורים לכליות ולחלבים וליותרת: **החטאת.** להביא שעירי עבודה זרה לכליות ולחלבים ויותרת: **ירים ממנו.** מן המחבר, שלא ינתחנו קודם הסרת חלבו, [ ת''כ ] :
@60 **כאשר יורם.** מאותן אימורין המפורשין בשור זבח השלמים. וכי מה פרש בזבח השלמים שלא פרש כאן, אלא להקישו לשלמים מה שלמים לשמן, אף זה לשמו. ומה שלמים שלום לעולם, אף זה שלום לעולם. ובשחיטת קדשים מצריכו ללמוד המנו, שאין למדין למד מן הלמד בקדשים, בפרק איזהו מקומן [ זבחים מט ] : **על הכבד על הכליות'** יא **על ראשו ועל כרעיו.** כלן לשון תוספת הן, כמו מלבד:
@62 **אל מקום טהור.** לפי שיש מחוץ לעיר מקום מוכן לטמאה להשליך אבנים מנגעות ולבית הקברות, הצרך לומר מחוץ למחנה, זה שהוא חוץ לעיר, שיהא המקום טהור: **מחוץ למחנה.** חוץ לשלש מחנות, ובבית עולמים חוץ לעיר, כמו שפרשוהו רבותינו במסכת יומא (סח א) ובסנהדרין (מב ב) : **אל שפך הדשן.** מקום ששופכין בו הדשן המסלק מן המזבח, כמו שנאמר (ויקרא ו ד) והוציא את הדשן אל מחוץ למחנה: **על שפך הדשן ישרף.** שאין תלמוד לומר אלא ללמד, שאפלו אין שם דשן:
@63 **עדת ישראל.** אלו סנהדרין: **ונעלם דבר.** טעו להורות באחת מכל כריתות שבתורה שהוא מתר: **הקהל ועשו.** שעשו צבור על פיהם:
@67 **את פני הפרכת.** ולמעלה הוא אומר את פני פרוכת הקדש, משל למלך שסרחה עליו מדינה, אם מיעוטה סרחה, פמליא שלו מתקימת, ואם כלה סרחה, אין פמליא שלו מתקימת. אף כאן כשחטא כהן משיח עדין שם קדשת המקום על המקדש, משחטאו כלם, חס ושלום, נסתלקה הקדשה:
@68 **יסוד מזבח העלה אשר פתח אהל מועד.** זה יסוד מערבי, שהוא כנגד הפתח:
@69 **ואת כל חלבו ירים.** אף על פי שלא פרש כאן יותרת ושתי כליות, למדין הם מועשה לפר כאשר עשה וגו' . ומפני מה לא נתפרשו בו, תנא דבי ר' ישמעאל (זבחים מא ב) משל למלך שזעם על אוהבו ומעט בסרחונו מפני חבתו:
@70 **ועשה לפר.** זה כאשר עשה לפר החטאת, כמו שמפורש בפר כהן משיח, להביא יותרת ושתי כליות שפרש שם מה שלא פרש כאן. ולכפול במצות העבודות, ללמד שאם חסר אחת מכל המתנות פסול, לפי שמצינו בנתנין על המזבח החיצון שנתנן במתנה אחת כפר, הצרך לומר כאן שמתנה אחת מהן מעכבת:
@72 **אשר נשיא יחטא.** לשון אשרי, אשרי הדור שהנשיא שלו נותן לב להביא כפרה על שגגתו, קל וחומר שמתחרט על זדונותיו:
@73 **או הודע.** כמו אם הודע. הרבה או יש שמשמשין בלשון אם, ואם במקום או, וכן או נודע כי שור נגח הוא (שמות כא לו) : **הודע אליו.** כשחטא היה סבור שהוא התר, ולאחר מכאן נודע לו שאסור היה:
@74 **במקום אשר ישחט את העלה.** בצפון, שהוא מפורש בעולה: **חטאת הוא.** לשמו כשר, שלא לשמו פסול:
@75 **ואת דמו.** שירי הדם:
@76 **כחלב זבח השלמים.** כאותן אימורין המפורשים בעז האמור אצל שלמים:
@81 **כאשר הוסר חלב מעל זבח השלמים.** כאימורי עז האמורים בשלמים:
@83 **ושחט אתה לחטאת.** שתהא שחיטתה לשם חטאת:
@85 **כאשר יוסר חלב הכשב.** שנתרבו אימוריו באליה, אף חטאת, כשהיא באה כשבה, טעונה אליה עם האימורין: **על אשי ה'.** על מדורות האש העשויות לשם. פואיי לי ''ש ב לע ''ז [מדורות] :
@86 **ושמעה קול אלה.** בדבר שהוא עד בו, שהשביעוהו שבועה שאם יודע לו בעדות, שיעיד לו:
@87 **או נפש אשר תגע** וגו' **.** ולאחר הטמאה הזו יאכל קדשים, או יכנס למקדש, שהוא דבר שזדונו כרת. במסכת שבועות (יד ב) נדרש כן: **ונעלם ממנו.** הטמאה: **ואשם.** באכילת קדש או בביאת מקדש:
@88 **בטמאת אדם.** זו טמאת מת: **לכל טמאתו.** לרבות טמאת מגע זבין וזבות: **אשר יטמא.** לרבות הנוגע בבועל נדה: **בה.** לרבות בולע נבלת עוף טהור: **ונעלם.** ולא ידע, (נ''א: **והוא ידע** ) ששכח הטמאה: ואשם. באכילת קדש או בביאת מקדש:
@89 **בשפתים.** ולא בלב: **להרע.** לעצמו: **או להיטיב.** לעצמו, כגון אוכל ולא אוכל אישן ולא אישן: **לכל אשר יבטא.** לרבות לשעבר: **ונעלם ממנו.** ועבר על שבועתו, כל אלה בקרבן עולה ויורד, כמפורש כאן, אבל שבועה שיש בה כפירת ממון אינה בקרבן זה אלא באשם:
@93 **והקריב את אשר לחטאת ראשונה.** חטאת קודמת לעולה. למה הדבר דומה, לפרקליט שנכנס לרצות, רצה פרקליט נכנס דורון אחריו: **ולא יבדיל.** אינו מולק אלא סימן אחד. ערף, הוא גובה הראש המשפע לצד הצואר. מול ערף. מול הרואה את העורף, והוא אורך כל אחורי הצואר:
@94 **והזה מדם החטאת.** בעולה לא הטעין אלא מצוי, ובחטאת הזאה ומצוי. אוחז בעורף ומתיז, והדם נתז והולך למזבח: **חטאת הוא.** לשמה כשרה, שלא לשמה פסולה:
@95 **כמשפט.** כדת האמור בעולת העוף שלנדבה בראש הפרשה:
@96 **כי חטאת הוא.** ואין בדין שיהא קרבנו מהדר:
@97 **חטאת הוא.** נקמצה ונקטרה לשמה כשרה, שלא לשמה פסולה:
@98 **על חטאתו אשר חטא.** כאן שנה הכתוב, שהרי בעשירות ובדלות נאמר (פסוק י) מחטאתו, וכאן בדלי דלות נאמר על חטאתו, דקדקו רבותינו (כריתות כז ב) מכאן, שאם חטא כשהוא עשיר והפריש מעות לכשבה או שעירה והעני, יביא ממקצתן שתי תורים. הפריש מעות לשתי תורים והעני יביא ממקצתן עשירית האיפה [לכך נאמר מחטאתו] . הפריש מעות לעשירית האיפה והעשיר, יוסיף עליהן ויביא קרבן עשיר, לכך נאמר כאן על חטאתו: **מאחת מאלה.** מאחת משלש כפרות האמורות בענין, או בעשירות או בדלות או בדלי דלות. ומה תלמוד לומר, שיכול החמורין שבהם יהיו בכשבה או שעירה, והקלין יהיו בעוף, והקלין שבקלין יהיו בעשירית האיפה, תלמוד לומר מאחת מאלה, להשוות קלין לחמורין לכשבה ושעירה אם השיגה ידו, ואת החמורין לקלין לעשירית האיפה בדלי דלות: **והיתה לכהן כמנחה.** ללמד על מנחת חוטא שהיו שיריה נאכלין, זהו לפי פשוטו. ורבותינו דרשו והיתה לכהן כמנחה, ואם חוטא זה כהן הוא, תהא לו כשאר מנחת נדבת כהן, שהיא בכליל תהיה לא תאכל (ויקרא ו טז) :
@100 **כי תמעל מעל.** אין מעילה בכל מקום אלא שנוי, וכן הוא אומר (דה''א ה כה) וימעלו באלהי אבותיהם ויזנו אחרי אלהי עמי הארץ, וכן הוא אומר בסוטה (במדבר ה יב) ומעלה בו מעל: **וחטאה בשגגה מקדשי ה'.** שנהנה מן ההקדש. והיכן הזהר, נאמר כאן חטא ונאמר להלן חטא בתרומה (ויקרא כב ט) ולא ישאו עליו חטא, מה להלן הזהיר, אף כאן הזהיר. אי מה להלן לא הזהיר אלא על האוכל, אף כאן לא הזהיר אלא על האוכל, תלמוד לומר תמעול מעל, רבה: **מקדשי ה'.** המיוחדים לשם, יצאו קדשים קלים: **איל.** לשון קשה, כמו (יחזקאל יז יג) ואת אילי הארץ לקח, אף כאן קשה, בן שתי שנים: **בערכך כסף שקלים.** שיהא שוה שתי סלעים:
@101 **ואת אשר חטא מן הקדש ישלם.** קרן וחומש להקדש:
@102 **ולא ידע ואשם:. והביא.** הענין הזה מדבר במי שבא ספק כרת לידו ולא ידע אם עבר עליו אם לאו, כגון חלב ושומן לפניו, וכסבור ששתיהן התר, ואכל את האחת. אמרו לו אחת של חלב היתה, ולא ידע אם זו של חלב אכל, הרי זה מביא אשם תלוי ומגין עליו כל זמן שלא נודע לו שודאי חטא, ואם נודע לו לאחר זמן יביא חטאת: **ולא ידע ואשם ונשא עונו.** ר' יוסי הגלילי אומר הרי הכתוב ענש את מי שלא ידע, על אחת כמה וכמה שיעניש את שידע. רבי יוסי אומר אם נפשך לידע מתן שכרן של צדיקים, צא ולמד מאדם הראשון, שלא נצטוה אלא על מצות לא תעשה ועבר עליה, ראה כמה מיתות נקנסו עליו ולדורותיו. וכי איזו מדה מרבה, של טובה או של פרענות, הוי אומר מדה טובה. אם מדת פרענות המעוטה ראה כמה מיתות נקנסו לו ולדורותיו, מדה טובה המרבה, היושב לו מן הפגולין והנותרות והמתענה ביום הכפורים, על אחת כמה וכמה שיזכה לו ולדורותיו ולדורות דורותיו עד סוף כל הדורות. רבי עקיבא אומר הרי הוא אומר (דברים יז ו) על פי שנים עדים או שלשה עדים וגו' , אם מתקימת העדות בשנים, למה פרט לך הכתוב שלשה, אלא להביא שלישי להחמיר עליו ולעשות דינו כיוצא באלו לענין ענש והזמה. אם כך ענש הכתוב לנטפל לעוברי עברה כעוברי עברה, על אחת כמה וכמה שישלם שכר טוב לנטפל לעושי מצוה כעושי מצוה. רבי אלעזר בן עזריה אומר כי תקצר קצירך בשדך ושכחת עמר בשדה (דברים כד יט) , הרי הוא אומר (דברים כד יט) למען יברכך וגו' , קבע הכתוב ברכה למי שבאת על ידו מצוה בלא ידע, אמור מעתה היתה סלע צרורה בכנפיו ונפלה המנו ומצאה העני ונתפרנס בה, הרי הקדוש ברוך הוא קובע לו ברכה:
@103 **בערכך לאשם.** בערך האמור למעלה (פסוק טו) : **אשר שגג והוא לא ידע.** הא אם ידע לאחר זמן, לא נתכפר לו באשם זה עד שיביא חטאת. הא למה זה דומה לעגלה ערופה שנתערפה ואחר כך נמצא ההורג, הרי זה יהרג:
@104 **אשם הוא אשם אשם.** הראשון כלו קמץ שהוא שם דבר, והאחרון חציו קמץ וחציו פתח שהוא לשון פעל. ואם תאמר מקרא שלא לצורך הוא, כבר נדרש הוא בתורת כהנים. **אשם אשם.** להביא אשם שפחה חרופה שיהא איל (בן שתי שנים) שוה שתי סלעים. יכול שאני מרבה אשם נזיר ואשם מצורע, תלמוד לומר הוא:
@106 **נפש כי תחטא.** אמר ר' עקיבא מה תלמוד לומר ומעלה מעל בה', לפי שכל המלוה והלוה והנושא והנותן אינו עושה אלא בעדים ובשטר, לפיכך בזמן שהוא מכחש מכחש בעדים ובשטר, אבל המפקיד אצל חברו אינו רוצה שתדע בו נשמה אלא שלישי שביניהם, לפיכך כשהוא מכחש, מכחש בשלישי שביניהם: **בתשומת יד.** ששם בידו ממון להתעסק או במלוה: **או בגזל.** שגזל מידו כלום: **או עשק.** הוא שכר שכיר:
@107 **וכחש בה.** שכפר על אחת מכל אלה אשר יעשה האדם לחטוא ולהשבע על שקר לכפירת ממון:
@108 **כי יחטא ואשם.** כשיכיר בעצמו לשוב בתשובה, ולדעת ולהתודות כי חטא ואשם:
@109 **בראשו.** הוא הקרן ראש הממון: **וחמשתיו.** רבתה תורה חמשיות הרבה לקרן אחת, שאם כפר בחומש ונשבע והודה, חוזר ומביא חומש על אותו חומש. וכן מוסיף והולך עד שיתמעט הקרן שנשבע לו פחות משוה פרוטה: **לאשר הוא לו.** למי שהממון שלו:
@113 **צו את אהרן.** אין צו אלא לשון זרוז מיד ולדורות. אמר ר' שמעון ביותר צריך הכתוב לזרז במקום שיש בו חסרון כיס: **זאת תורת העלה** וגו' **.** הרי הענין הזה בא ללמד על הקטר חלבים ואיברים שיהא כשר כל הלילה, וללמד על הפסולין איזה אם עלה ירד, ואיזה אם עלה לא ירד, שכל תורה לרבות הוא בא, לומר תורה אחת לכל העולים, ואפלו פסולין, שאם עלו לא ירדו: **הוא העלה.** למעט את הרובע ואת הנרבע וכיוצא בהן, שלא היה פסולן בקדש, שנפסלו קודם שבאו לעזרה:
@114 **מדו בד.** היא הכתנת. ומה תלמוד לומר מדו, שתהא כמדתו: **על בשרו.** שלא יהא דבר חוצץ בנתים: **והרים את הדשן.** היה חותה מלא מחתה מן המאכלות הפנימיות ונותנן במזרחו של כבש: **הדשן אשר תאכל האש את העלה.** ועשאתה דשן, מאותו דשן ירים תרומה ושמו אצל המזבח: **על המזבח.** מצא אברים שעדין לא נתעכלו, מחזירן על המזבח, לאחר שחתה גחלים אלך ואלך ונטל מן הפנימיות, שנאמר את העלה על המזבח:
@115 **ופשט את בגדיו.** אין זו חובה אלא דרך ארץ, שלא ילכלך בהוצאת הדשן בגדים שהוא משמש בהן תמיד. בגדים שבשל בהן קדרה לרבו אל ימזג בהן כוס לרבו, לכך ולבש בגדים אחרים פחותין מהן: **והוציא את הדשן.** הצבור בתפוח, כשהוא רבה ואין מקום למערכה, מוציאו משם. ואין זה חובה בכל יום, אבל התרומה חובה בכל יום ה **והאש על המזבח תוקד בו.** רבה כאן יקידות הרבה על מוקדה, ואש המזבח תוקד בו, והאש על המזבח תוקד בו, אש תמיד תוקד על המזבח, כלן נדרשו במסכת יומא (מג ב) שנחלקו רבותינו במנין המערכות שהיו שם: **וערך עליה העלה.** עולת תמיד היא תקדים: **חלבי השלמים.** אם יביאו שם שלמים. ורבותינו למדו מכאן עליה, על עולת הבקר השלם כל הקרבנות כלם. מכאן שלא יהא דבר מאוחר לתמיד של בין הערבים:
@117 **אש תמיד.** אש שנאמר בה תמיד, היא שמדליקין בה את הנרות, שנאמר בה (שמות כז כ) להעלות נר תמיד, אף היא מעל המזבח החיצון תוקד: **לא תכבה.** המכבה אש על המזבח עובר בשני לאוין:
@118 **וזאת תורת המנחה.** תורה אחת לכלן להטעינן שמן ולבונה האמורין בענין. שיכול אין לי טעונות שמן ולבונה אלא מנחת ישראל שהיא נקמצת, מנחת כהנים שהיא כליל מנין, תלמוד לומר תורת: **הקרב אתה.** היא הגשה בקרן מערבית דרומית: **לפני ה'.** הוא מערב שהוא לצד אהל מועד: **אל פני המזבח.** הוא הדרום, שהוא פניו של מזבח, שהכבש נתון לאותו הרוח:
@119 **והרים ממנו.** מהמחבר, שיהא עשרון שלם בבת אחת בשעת קמיצה: **בקמצו.** שלא יעשה מדה לקומץ: **מסלת המנחה ומשמנה.** מכאן שקומץ ממקום שנתרבה שמנה: **המנחה.** שלא תהא מעורבת באחרת: **ואת כל הלבנה אשר על המנחה והקטיר.** שמלקט את לבונתה לאחר קמיצה ומקטירו. ולפי שלא פרש כן אלא באחת מן המנחות בויקרא (ב, א. ג) , הצרך לשנות פרשה זו, לכלול כל המנחות כמשפטן:
@120 **במקום קדש.** ואיזהו, בחצר אהל מועד:
@121 **לא תאפה חמץ חלקם.** אף השירים אסורים בחמץ: **כחטאת וכאשם.** מנחת חוטא הרי היא כחטאת, לפיכך קמצה שלא לשמה פסולה. מנחת נדבה הרי היא כאשם, לפיכך קמצה שלא לשמה כשרה:
@122 **כל זכר.** אפלו בעל מום. למה נאמר, אם לאכילה הרי כבר אמור לחם אלהיו מקדשי הקדשים וגו' , אלא לרבות בעלי מומין למחלוקת: **כל אשר יגע** וגו' **.** קדשים קלים או חלין שיגעו בה ויבלעו ממנה: **יקדש.** להיות כמוה, שאם פסולה יפסלו, ואם כשרה יאכלו כחמר המנחה:
@124 **זה קרבן אהרן ובניו.** אף ההדיוטות מקריבין עשירית האיפה ביום שהן מתחנכין לעבודה, אבל כהן גדול בכל יום, שנאמר מנחה תמיד וגו' והכהן המשיח תחתיו מבניו וגו' חק עולם וגו' (פסוק טו) יד **מרבכת.** חלוטה ברותחין כל צרכה: **תפיני.** אפויה אפיות הרבה, שאחר חליטתה אופה בתנור וחוזר ומטגנה במחבת: **מנחת פתים.** מלמד שטעונה פתיתה:
@126 **המשיח תחתיו מבניו.** המשיח מבניו תחתיו: **כליל תקטר.** אין נקמצת להיות שיריה נאכלין אלא כלה כליל, וכן כל מנחת כהן של נדבה כליל תהיה טז **כליל.** כלה שוה לגבוה:
@130 **המחטא אתה.** העובד עבודותיה שהיא נעשית חטאת על ידו: **המחטא אתה יאכלנה.** הראוי לעבודה, יצא טמא בשעת זריקת דמים שאינו חולק בבשר, ואי אפשר לומר שאוסר שאר כהנים באכילתה חוץ מן הזורק דמה, שהרי נאמר למטה (פסוק כב) כל זכר בכהנים יאכל אתה:
@131 **כל אשר יגע בבשרה.** כל דבר אוכל אשר יגע ויבלע ממנה: **יקדש.** להיות כמוה, אם פסולה תפסל, ואם היא כשרה תאכל כחמר שבה: **ואשר יזה מדמה על הבגד.** ואם הזה מדמה על הבגד, אותו מקום דם הבגד אשר יזה עליה, תכבס בתוך העזרה: **אשר יזה.** יהא נזה, כמו (איוב טו כט) ולא יטה לארץ מנלם, יהא נטוי:
@132 **ישבר.** לפי שהבליעה שנבלעת בו נעשה נותר, והוא הדין לכל הקדשים: **ומרק.** לשון תמרוקי הנשים (אסתר ב יב) אישקורימינ''ט בלע''ז [נקוי] : **ומרק ושטף.** לפלוט את בליעתו, אבל כלי חרס למדך הכתוב כאן שאינו יוצא מידי דפיו לעולם:
@133 **כל זכר בכהנים יאכל אתה.** הא למדת שהמחטא אותה האמור למעלה לא להוציא שאר הכהנים, אלא להוציא את שאינו ראוי לחטוי:
@134 **וכל חטאת** וגו' **.** שאם הכניס מדם חטאת החיצונה לפנים פסולה: **וכל.** לרבות שאר קדשים:
@135 **קדש קדשים הוא.** הוא קרב ואין תמורתו קרבה:
@136 **ישחטו.** רבה לנו שחיטות הרבה, לפי שמצינו אשם בצבור, נאמר ישחטו רבים. ותלאו בעולה להביא עולת צבור לצפון:
@137 **ואת כל חלבו** וגו' **.** עד כאן לא נתפרשו אמורין באשם, לכך הצרך לפרשם כאן, אבל חטאת כבר נתפרשו בה בפרשת ויקרא (פרק ב) : **את האליה.** לפי שאשם אינו בא אלא איל או כבש, ואיל וכבש נתרבו באליה:
@139 **אשם הוא.** עד שינתק שמו ממנו. למד על אשם שמתו בעליו או שנתכפרו בעליו, אף על פי שעומד להיות דמיו עולה לקיץ המזבח, אם שחטו סתם, אינו כשר לעולה קודם שנתק לרעיה. ואינו בא ללמד על האשם שיהא פסול שלא לשמו, כמו שדרשו הוא, הכתוב בחטאת, לפי שאשם לא נאמר בו אשם הוא, אלא לאחר הקטרת אמורין, והוא עצמו שלא הקטרו אמוריו כשר:
@140 **קדש קדשים הוא.** בתורת כהנים הוא נדרש:
@141 **תורה אחת להם.** בדבר זה: **הכהן אשר יכפר בו.** הראוי לכפרה חולק בו, פרט לטבול יום ומחסר כפורים ואונן:
@142 **עור העלה אשר הקריב לכהן לו יהיה.** פרט לטבול יום ומחסר כפורים ואונן שאינן חולקים בעורות:
@143 **לכהן המקריב אתה** וגו' **.** יכול לו לבדו, תלמוד לומר לכל בני אהרן תהיה. יכול לכלן, תלמוד לומר לכהן המקריב, הא כיצד לבית אב של אותו יום שמקריבין אותה:
@144 **בלולה בשמן.** זו מנחת נדבה: **וחרבה.** זו מנחת חוטא ומנחת קנאות שאין בהן שמן:
@146 **אם על תודה יקריבנו.** אם על דבר הודאה על נס שנעשה לו, כגון יורדי הים והולכי מדברות וחבושי בית האסורים וחולה שנתרפא שהם צריכין להודות שכתוב בהן (תהלים קז כא. כב) יודו לה' חסדו ונפלאותיו לבני אדם ויזבחו זבחי תודה. אם על אחת מאלה נדר שלמים הללו, שלמי תודה הן, וטעונות לחם האמור בענין, ואינן נאכלין אלא ליום ולילה, כמו שמפורש כאן: **והקריב על זבח התודה.** ארבעה מיני לחם חלות, ורקיקין, ורבוכה, שלשה מיני מצה, וכתיב (פסוק יג) על חלת לחם חמץ וגו' , וכל מין ומין עשר חלות, כך מפורש במנחות (עז א) . ושעורן חמש סאין ירושלמיות שהן שש מדבריות, עשרים עשרון: **מרבכת.** לחם חלוט ברותחין כל צרכו יג **יקריב קרבנו על זבח.** מגיד שאין הלחם קדוש קדשת הגוף להפסל ביוצא וטבול יום ומלצאת לחלין בפדיון, עד שישחט הזבח:
@148 **אחד מכל קרבן.** לחם אחד מכל מין ומין יטול תרומה לכהן העובד עבודתה, והשאר נאכל לבעלים ובשרה לבעלים, חוץ מחזה ושוק שבה, כמו שמפורש למטה (פסוקים כט. לב) תנופת חזה ושוק בשלמים. והתודה קרויה שלמים:
@149 **ובשר זבח תודת שלמיו.** יש כאן רבויין הרבה, לרבות חטאת ואשם ואיל נזיר וחגיגת ארבעה עשר, שיהיו נאכלין ליום ולילה: **ביום קרבנו יאכל.** וכזמן בשרה זמן לחמה: **לא יניח ממנו עד בקר.** אבל אוכל הוא כל הלילה, אם כן למה אמרו עד חצות, כדי להרחיק אדם מן העברה:
@150 **ואם נדר או נדבה.** שלא הביאה על הודאה של נס, אינה טעונה לחם ונאכלת לשני ימים, כמו שמפורש בענין: **וממחרת והנותר ממנו.** בראשון יאכל. וי''ו זו יתרה היא, ויש כמוה הרבה במקרא, כגון (בראשית לו כד) ואלה בני צבעון ואיה וענה, (דניאל ח יג) תת וקדש וצבא מרמס:
@152 **ואם האכל יאכל** וגו' **.** במחשב בשחיטה לאכלו בשלישי הכתוב מדבר. יכול אם אכל ממנו בשלישי יפסל למפרע, תלמוד לומר המקריב אותו לא יחשב, בשעת הקרבה הוא נפסל, ואינו נפסל בשלישי. וכן פרושו בשעת הקרבתו לא תעלה זאת במחשבה, ואם חשב פגול יהיה: **והנפש האכלת ממנו.** אפלו בתוך הזמן עונה תשא:
@153 **והבשר.** של קדש שלמים אשר יגע בכל טמא לא יאכל: **והבשר.** לרבות אבר שיצא מקצתו, שהפנימי מתר: **כל טהור יאכל בשר.** מה תלמוד לומר, לפי שנאמר (דברים יב כז) ודם זבחיך ישפך וגו' והבשר תאכל, יכול לא יאכלו שלמים אלא הבעלים, לכך נאמר כל טהור יאכל בשר: **והבשר כל טהור יאכל בשר.** כלומר כל מה שאסרתי לך בחטאת ואשם, שאם יצאו חוץ לקלעם אסורין, כמו שכתוב (ו ט) בחצר אהל מועד יאכלוה, בבשר זה אני אומר לך כל טהור יאכל בשר אפלו בכל העיר:
@154 **וטמאתו עליו.** בטמאת הגוף הכתוב מדבר, אבל טהור שאכל את הטמא, אינו ענוש כרת, אלא באזהרה והבשר אשר יגע בכל טמא וגו' (פסוק יט) . ואזהרת טמא שאכל את הטהור אינה מפורשת בתורה, אלא חכמים למדוה בגזרה שוה. שלש כריתות אמורות באוכלי קדשים בטמאת הגוף, ודרשוה רבותינו בשבועות (ז א) אחת לכלל ואחת לפרט ואחת ללמד על קרבן עולה ויורד, שלא נאמר אלא על טמאת מקדש וקדשיו:
@158 **יעשה לכל מלאכה.** בא ולמד על החלב שאינו מטמא טמאת נבלות: **ואכל לא תאכלהו.** אמרה תורה יבוא אסור נבלה וטרפה ויחול על אסור חלב, שאם אכלו, יתחיב אף על לאו של נבלה, ולא תאמר אין אסור חל על אסור:
@160 **בכל מושבתיכם.** לפי שהיא חובת הגוף ואינה חובת קרקע, נוהגת בכל מושבות, ובמסכת קדושין בפרק א' (לז א) מפרש למה הצרך לומר: **לעוף ולבהמה.** פרט לדם דגים וחגבים:
@164 **ידיו תביאינה** וגו' **.** שתהא יד הבעלים מלמעלה והחלב והחזות נתונין בה, ויד כהן מלמטה ומניפן: **את אשי ה'.** ומה הן האשים, **את החלב על החזה יביאנו.** כשמביאו מבית המטבחים נותן החלב על החזה, וכשנותנו ליד הכהן המניף נמצא החזה למעלה והחלב למטה, וזהו האמור במקום אחר (ויק' י טו) שוק התרומה וחזה התנופה על אשי החלבים יביאו להניף וגו' , ולאחר התנופה נותנו לכהן המקטיר, ונמצא החזה למטה, וזהו שנאמר (ויק' ט כ) וישימו את החלבים על החזות ויקטר החלבים המזבחה. למדנו ששלשה כהנים זקוקין לה, כך מפורש במנחות (סב א) : **את החלב על החזה יביאנו.** ואת החזה למה מביא, להניף אותו הוא מביאו, ולא שיהא הוא מן האשים. לפי שנאמר את אשי ה' את החלב על החזה, יכול שיהא אף החזה לאשים, לכך נאמר את החזה להניף וגו' :
@165 **והקטיר הכהן את החלב.** ואחר כך והיה החזה לאהרן, למדנו שאין הבשר נאכל בעוד שהאמורים למטה מן המזבח:
@166 **שוק.** מן הפרק של ארכבה הנמכרת עם הראש עד הפרק האמצעי, שהוא סובך של רגל:
@167 **המקריב את דם השלמים** וגו' **.** מי שהוא ראוי לזריקתו ולהקטיר חלבו, יצא טמא בשעת זריקת דמים או בשעת הקטר חלבים, שאינו חולק בבשר לד **התנופה' התרומה.** מוליך ומביא, מעלה ומוריד לז **ולמלואים.** ליום חנוך הכהנה:
@174 **קח את אהרן.** פרשה זו נאמרה שבעת ימים קודם הקמת המשכן, שאין מקדם ומאחר בתורה: **קח את אהרן.** קחנו בדברים ומשכהו: **ואת פר החטאת** וגו' **.** אלו האמורים בענין צואת המלואים בואתה תצוה, ועכשיו ביום ראשון למלואים חזר וזרזו בשעת מעשה:
@175 **הקהל אל פתח אהל מועד.** זה אחד מן המקומות שהחזיק מועט את המרבה:
@177 **זה הדבר.** דברים שתראו שאני עושה לפניכם צוני הקדוש ברוך הוא לעשות, ואל תאמרו לכבודי ולכבוד אחי אני עושה. כל הענין הזה פרשתי בואתה תצוה:
@180 **את האורים.** כתב של שם המפורש:
@181 **וישם על המצנפת.** פתילי תכלת הקבועים בציץ נתן על המצנפת, נמצא הציץ תלוי במצנפת:
@183 **ויז ממנו על המזבח.** לא ידעתי היכן נצטוה בהזאות הללו:
@184 **ויצק' וימשח.** בתחלה יוצק על ראשו, ואחר כך נותן בין ריסי עיניו ומושך באצבעו מזה לזה:
@185 **ויחבש.** לשון קשירה:
@187 **ויחטא את המזבח.** חטאו וטהרו מזרות להכנס לקדשה: **ויקדשהו.** בעבודה זו: **לכפר עליו.** מעתה כל הכפרות:
@188 **ואת יתרת הכבד.** על הכבד (שמות כט יג) לבד הכבד, שהיה נוטל מעט מן הכבד עמה:
@194 **איל המלאים.** איל השלמים, שמלואים לשון שלמים, שממלאים ומשלימים את הכהנים בכהנתם:
@198 **וחלת לחם שמן.** היא רבוכה, שהיה מרבה בה שמן כנגד החלות והרקיקין, כך מפורש במנחות (עח א) :
@200 **ויקטר המזבחה.** משה שמש כל שבעת ימי המלואים בחלוק לבן: **על העלה.** אחר העלה. ולא מצינו שוק של שלמים קרב בכל מקום חוץ מזה:
@206 **צוה ה' לעשת.** כל שבעת הימים. ורבותינו זכרונם לברכה דרשו לעשות. זה מעשה פרה. לכפר. זה מעשה יום הכפורים, וללמד שכהן גדול טעון פרישה קודם יום הכפורים שבעת ימים, וכן הכהן השורף את הפרה:
@207 **ולא תמותו.** הא אם לא תעשו כן, הרי אתם חיבים מיתה:
@208 **ויעש אהרן ובניו.** להגיד שבחן שלא הטו ימין ושמאל:
@209 **ויהי ביום השמיני.** שמיני למלואים, הוא ראש חדש ניסן, שהוקם המשכן בו ביום ונטל עשר עטרות השנויות בסדר עולם (פרק ז) : **ולזקני ישראל.** להשמיעם שעל פי הדבור אהרן נכנס ומשמש בכהנה גדולה, ולא יאמרו מאליו נכנס:
@210 **קח לך עגל.** להודיע שמכפר לו הקדוש ברוך הוא על ידי עגל זה על מעשה העגל שעשה:
@212 **כי היום ה' נראה אליכם.** להשרות שכינתו במעשה ידיכם לכך קרבנות הללו באין חובה ליום זה:
@215 **קרב אל המזבח.** שהיה אהרן בוש וירא לגשת. אמר לו משה למה אתה בוש, לכך נבחרת: **את חטאתך.** עגל בן בקר: **ואת עלתך.** איל: **קרבן העם.** שעיר עזים ועגל וכבש. כל מקום שנאמר עגל, בן שנה הוא, ומכאן אתה למד:
@219 **ואת הבשר ואת העור** וגו' **.** לא מצינו חטאת חיצונה נשרפת אלא זו ושל מלאים, וכלן על פי הדבור:
@220 **וימצאו.** לשון הושטה והזמנה:
@223 **ויחטאהו.** עשהו כמשפט חטאת: **כראשון.** כעגל שלו:
@224 **ויעשה כמשפט.** המפורש בעולת נדבה בויקרא (פרק א) :
@225 **וימלא כפו.** היא קמיצה: **מלבד עלת הבקר.** כל אלה עשה אחר עולת התמיד:
@227 **והמכסה.** חלב המכסה את הקרב:
@228 **וישימו את החלבים על החזות.** לאחר התנופה נתנן כהן המניף לכהן אחר להקטירם, נמצאו העליונים למטה:
@230 **ויברכם.** ברכת כהנים יברכך, יאר, ישא: **וירד.** מעל המזבח:
@231 **ויבא משה ואהרן** וגו' **.** למה נכנסו, מצאתי בפרשת מלאים בבריתא הנוספת על תורת כהנים שלנו למה נכנס משה עם אהרן, ללמדו על מעשה הקטרת. או לא נכנס אלא לדבר אחר, הריני דן ירידה וביאה טעונות ברכה, מה ירידה מעין עבודה, אף ביאה מעין עבודה, הא למדת למה נכנס משה עם אהרן, ללמדו על מעשה הקטרת. דבר אחר כיון שראה אהרן שקרבו כל הקרבנות ונעשו כל המעשים ולא ירדה שכינה לישראל, היה מצטער ואמר יודע אני שכעס הקדוש ברוך הוא עלי ובשבילי לא ירדה שכינה לישראל. אמר לו למשה, משה אחי כך עשית לי, שנכנסתי ונתבישתי. מיד נכנס משה עמו ובקשו רחמים וירדה שכינה לישראל: **ויצאו ויברכו את העם.** אמרו ויהי נועם ה' אלהינו עלינו (תהלים צ יז) , יהי רצון שתשרה שכינה במעשה ידיכם. לפי שכל שבעת ימי המלואים, שהעמידו משה למשכן ושמש בו ופרקו בכל יום, לא שרתה בו שכינה, והיו ישראל נכלמים ואומרים למשה, משה רבנו, כל הטורח שטרחנו, שתשרה שכינה בינינו ונדע שנתכפר לנו עון העגל. לכך אמר להם זה הדבר אשר צוה ה' תעשו וירא אליכם כבוד ה' (פסוק ו) , אהרן אחי כדאי וחשוב ממני שעל ידי קרבנותיו ועבודתו תשרה שכינה בכם ותדעו שהמקום בחר בו:
@232 **וירנו.** כתרגומו:
@234 **ותצא אש.** רבי אלעזר אומר לא מתו בני אהרן אלא על ידי שהורו הלכה בפני משה רבן. רבי ישמעאל אומר שתויי יין נכנסו למקדש, תדע שאחר מיתתן הזהיר הנותרים שלא יכנסו שתויי יין למקדש. משל למלך, שהיה לו בן בית וכו' , כדאיתא בויקרא רבה:
@235 **הוא אשר דבר** וגו' **.** היכן דבר ונועדתי שמה לבני ישראל ונקדש בכבודי (שמות כט מג) . אל תקרי בכבודי אלא במכבדי. אמר לו משה לאהרן, אהרן אחי יודע הייתי שיתקדש הבית במידעיו של מקום והייתי סבור או בי או בך, עכשיו רואה אני שהם גדולים ממני וממך: **וידם אהרן.** קבל שכר על שתיקתו. ומה שכר קבל, שנתיחד עמו הדבור, שנאמרה לו לבדו פרשת שתויי יין: **בקרבי.** בבחירי: **ועל פני כל העם אכבד.** כשהקדוש ברוך הוא עושה דין בצדיקים מתירא ומתעלה ומתקלס, אם כן באלו, כל שכן ברשעים, וכן הוא אומר (תהלים סח לו) נורא אלהים ממקדשיך, אל תקרא ממקדשיך אלא ממקדשיך:
@236 **דד אהרן.** עזיאל אחי עמרם היה, שנאמר (שמות ו יח) ובני קהת וגו' : **שאו את אחיכם** וגו' **.** כאדם האומר לחברו העבר את המת מלפני הכלה, שלא לערבב את השמחה:
@237 **בכתנתם.** של מתים. מלמד שלא נשרפו בגדיהם אלא נשמתם, כמין שני חוטין של אש נכנסו לתוך חטמיהם:
@238 **אל תפרעו.** אל תגדלו שער. מכאן שאבל אסור בתספורת, אבל אתם אל תערבבו שמחתו של מקום: **ולא תמתו.** הא אם תעשו כן תמותו: **ואחיכם כל בית ישראל.** מכאן שצרתן של תלמידי חכמים מטלת על הכל להתאבל בה:
@241 **יין ושכר.** יין דרך שכרותו: **בבאכם אל אהל מועד.** אין לי אלא בבואם להיכל, בגשתם למזבח מנין, נאמר כאן ביאת אהל מועד, ונאמר בקדוש ידים ורגלים ביאת אהל מועד, מה להלן עשה גישת מזבח כביאת אהל מועד, אף כאן עשה גישת מזבח כביאת אהל מועד:
@242 **ולהבדיל.** כדי שתבדילו בין עבודה קדושה למחללת, הא למדת שאם עבד, עבודתו פסולה:
@243 **ולהורת.** למד שאסור שכור בהוראה. יכול יהא חיב מיתה, תלמוד לומר אתה ובניך אתך ולא תמותו (פסוק ט) , כהנים בעבודתם במיתה, ואין חכמים בהוראתם במיתה:
@244 **הנותרים.** מן המיתה. מלמד שאף עליהם נקנסה מיתה על עון העגל, הוא שנאמר (דברים ט כ) ובאהרן התאנף ה' מאד להשמידו, ואין השמדה אלא כלוי בנים, שנאמר (עמוס ב ט) ואשמיד פריו ממעל, ותפלתו של משה בטלה מחצה, שנאמר (דברים ט כ) ואתפלל גם בעד אהרן בעת ההיא: **קחו את המנחה.** אף על פי שאתם אוננין וקדשים אסורים לאונן: **את המנחה.** זו מנחת שמיני ומנחת נחשון: **ואכלוה מצות.** מה תלמוד לומר, לפי שהיא מנחת צבור ומנחת שעה ואין כיוצא בה לדורות, הצרך לפרש בה דין שאר מנחות:
@245 **וחק בניך.** אין לבנות חק בקדשים: **כי כן צויתי.** באנינות יאכלוה:
@246 **ואת חזה התנופה.** של שלמי צבור: **תאכלו במקום טהור.** וכי את הראשונים אכלו במקום טמא, אלא הראשונים שהם קדשי קדשים הזקקה אכילתם במקום קדוש, אבל אלו אין צריכים תוך הקלעים, אבל צריכים הם להאכל תוך מחנה ישראל, שהוא טהור מלכנס שם מצורעים. מכאן שקדשים קלים נאכלין בכל העיר: **אתה ובניך ובנתיך.** אתה ובניך בחלק, אבל בנותיך לא בחלק, אלא אם תתנו להן מתנות, רשאות הן לאכול בחזה ושוק. או אינו אלא אף הבנות בחלק, תלמוד לומר כי חקך וחק בניך נתנו, חק לבנים ואין חק לבנות:
@247 **שוק התרומה וחזה התנופה.** לשון אשר הונף ואשר הורם. תנופה מוליך ומביא, תרומה מעלה ומוריד. ולמה חלקן הכתוב, תרומה בשוק ותנופה בחזה, לא ידענו, ששניהם בהרמה והנפה: **על אשי החלבים.** מכאן שהחלבים למטה בשעת תנופה, וישוב המקראות שלא יכחישו זה את זה, כבר פרשתי שלשתן בצו את אהרן (ז ל) :
@248 **שעיר החטאת.** שעיר מוספי ראש חדש. ושלשה שעירי חטאות קרבו בו ביום שעיר עזים, ושעיר נחשון ושעיר ראש חדש, ומכלן לא נשרף אלא זה. ונחלקו בדבר חכמי ישראל יש אומרים, מפני הטמאה שנגעה בו נשרף. ויש אומרים, מפני אנינות נשרף, לפי שהוא קדשי דורות, אבל בקדשי שעה סמכו על משה שאמר להם במנחה (פסוק יב) ואכלוה מצות: **דרש דרש.** שתי דרישות הללו מפני מה נשרף זה, ומפני מה נאכלו אלו, כך הוא בתורת כהנים: **על אלעזר ועל איתמר.** בשביל כבודו של אהרן הפך פניו כנגד הבנים וכעס: **לאמר.** אמר להם, השיבוני על דברי:
@249 **מדוע לא אכלתם את החטאת במקום הקדש.** וכי חוץ לקדש אכלוה, והלא שרפוה, ומה הוא אומר במקום הקדש, אלא אמר להם שמא חוץ לקלעים יצאה ונפסלה: **כי קדש קדשים הוא.** ונפסלת ביוצא, והם אמרו לו לאו. אמר להם הואיל ובמקום הקדש היתה, מדוע לא אכלתם אותה: **ואתה נתן לכם לשאת** וגו' **.** שהכהנים אוכלים ובעלים מתכפרים: **לשאת את עון העדה.** מכאן למדנו ששעיר ראש חדש היה, שהוא מכפר על עון טמאת מקדש וקדשיו, שחטאת שמיני וחטאת נחשון לא לכפרה באו:
@250 **הן לא הובא** וגו' **.** שאלו הובא היה לכם לשרפה, כמו שנאמר (ויקרא ו כג) וכל חטאת אשר יובא מדמה וגו' : **אכל תאכלו אתה.** היה לכם לאכלה אף על פי שאתם אוננים: **כאשר צויתי.** לכם במנחה:
@251 **וידבר אהרן.** אין לשון דבור אלא לשון עז, שנאמר (במדבר כא ה) וידבר העם וגו' . אפשר משה קצף על אלעזר ועל איתמר, ואהרן מדבר, הא ידעת שלא היתה אלא מדרך כבוד. אמרו אינו בדין שיהא אבינו יושב ואנו מדברים לפניו, ואינו בדין שיהא תלמיד משיב את רבו. יכול מפני שלא היה באלעזר להשיב, תלמוד לומר (במדבר לא כא) ויאמר אלעזר הכהן אל אנשי הצבא וגו' , הרי כשרצה, דבר לפני משה ולפני הנשיאים, זו מצאתי בספרי של פנים שני: **הן היום הקריבו.** מהו אומר, אלא אמר להם משה שמא זרקתם דמה אוננים, שהאונן שעבד חלל. אמר לו אהרן וכי הם הקריבו, שהם הדיוטות, אני הקרבתי, שאני כהן גדול ומקריב אונן: **ותקראנה אתי כאלה.** אפלו לא היו המתים בני אלא שאר קרובים שאני חיב להיות אונן עליהם כאלו, כגון כל האמורים בפרשת כהנים שהכהן מטמא להם: **ואכלתי חטאת.** ואם אכלתי הייטב וגו' : **היום.** אבל אנינות לילה מתר, שאין אונן אלא יום קבורה: **הייטב בעיני ה'.** אם שמעת בקדשי שעה אין לך להקל בקדשי דורות:
@252 **וייטב בעיניו.** הודה ולא בוש לומר לא שמעתי:
@253 **אל משה ואל אהרן.** למשה אמר שיאמר לאהרן: **לאמר אליהם.** אמר שיאמר לאלעזר ולאיתמר, או אינו אלא לאמר לישראל, כשהוא אומר דברו אל בני ישראל, הרי דבור אמור לישראל, הא מה אני מקים לאמר אליהם, לבניו לאלעזר ולאיתמר:
@254 **דברו אל בני ישראל.** את כלם השוה להיות שלוחים בדבר זה, לפי שהשוו בדמימה וקבלו עליהם גזרת המקום באהבה: **זאת החיה.** לשון חיים, לפי שישראל דבוקים במקום וראויין להיות חיים, לפיכך הבדילם מן הטמאה וגזר עליהם מצות, ולאמות העולם לא אסר כלום. משל לרופא שנכנס לבקר את החולה וכו' , כדאיתא במדרש רבי תנחומא: **זאת החיה.** מלמד שהיה משה אוחז בחיה ומראה אותה לישראל, זאת תאכלו וזאת לא תאכלו: **את זה תאכלו** וגו' **.** אף בשרצי המים אחז מכל מין ומין והראה להם. וכן בעוף ואת אלה תשקצו מן העוף. וכן בשרצים וזה לכם הטמא: **זאת החיה מכל הבהמה.** מלמד שהבהמה בכלל חיה:
@255 **מפרסת.** כתרגומו סדיקא: **פרסה.** פלאנט''ה בלע''ז [כף רגל] : **ושסעת שסע.** שמבדלת מלמעלה ומלמטה בשתי צפרנין, כתרגומו ומטלפא טלפין, שיש שפרסותיו סדוקות מלמעלה ואינן שסועות ומבדלות לגמרי, שמלמטה מחברות: **מעלת גרה.** מעלה ומקיאה האוכל ממעיה ומחזרת אותו לתוך פיה לכתשו ולטחנו הדק: **גרה.** כך שמו. ויתכן להיות מגזרת מים הנגרים (שמואל ב יד יד) , שהוא נגרר אחר הפה. ותרגומו פשרא שעל ידי הגרה האוכל נפשר ונמוח: **בבהמה.** תיבה זו יתרה היא לדרשה, להתיר את השליל הנמצא במעי אמו: **אתה תאכלו.** ולא בהמה טמאה. והלא באזהרה היא, אלא לעבור עליה בעשה ולא תעשה:
@260 **מבשרם לא תאכלו.** אין לי אלא אלו, שאר בהמה טמאה שאין לה שום סימן טהרה מנין, אמרת קל וחמר ומה אלו שיש בהן קצת סימני טהרה אסורות וכו' : **מבשרם.** על בשרם באזהרה, ולא על עצמות וגידין וקרנים וטלפים: **ובנבלתם לא תגעו.** יכול יהו ישראל מזהרים על מגע נבלה, תלמוד לומר אמור אל הכהנים וגו' (ויקרא כא א) , כהנים מזהרין ואין ישראל מזהרין. קל וחמר מעתה ומה טמאת מת חמורה, לא הזהיר בה אלא כהנים, טמאת נבלה קלה לא כל שכן. ומה תלמוד לומר לא תגעו, ברגל. זהו שאמרו חיב אדם לטהר עצמו ברגל:
@261 **סנפיר.** אלו ששט בהם: **קשקשת.** אלו קלפים הקבועים בו, כמו שנאמר (שמואל א יז ה) ושריון קשקשים הוא לבוש:
@262 **שרץ.** בכל מקום משמעו דבר נמוך שרוחש ונע ונד על הארץ:
@263 **ושקץ יהיו.** לאסר את עירוביהן, אם יש בו בנותן טעם: **מבשרם.** אינו מזהר על הסנפירים ועל העצמות: **ואת נבלתם תשקצו.** לרבות יבחושין שסננן. יבחושין מושקירונ''ש בלע''ז :
@264 **כל אשר אין לו** וגו' **.** מה תלמוד לומר, שיכול אין לי שיהא מתר אלא המעלה סימנין שלו ליבשה, השירן במים מנין, תלמוד לומר כל אשר אין לו סנפיר וקשקשת במים, הא אם היו לו במים אף על פי שהשירן בעליתו מתר:
@265 **לא יאכלו.** לחיב את המאכילן לקטנים. שכך משמעו לא יהיו נאכלים על ידך. או אינו אלא לאסרו בהנאה, תלמוד לומר (דברים יד יב) לא תאכלו, באכילה אסורין בהנאה מתרין. כל עוף שנאמר בו למינה, למינו, למינהו, יש באותו המין שאין דומין זה לזה, לא במראיהם ולא בשמותם, וכלן מין אחד:
@268 **הנץ.** אישפרויי''ר :
@269 **השלך.** פרשו רבותינו זה השולה דגים מן הים. וזהו שתרגם אנקלוס ושלינונא: **כוס וינשוף.** הם צואיטי''ש הצועקים בלילה ויש להם לסתות כאדם. ועוד אחר דומה לו שקורין יב''ן [לילית] :
@270 **התנשמת.** היא קלב''א שורי''ץ [עטלף] ודומה לעכבר ופורחת בלילה. ותנשמת האמורה בשרצים היא דומה לה, ואין לה עינים וקורין לה טלפ''א [חפרפרת] :
@271 **החסידה.** זו דיה לבנה ציגוני''ה . ולמה נקרא שמה חסידה, שעושה חסידות עם חברותיה במזונות: **האנפה.** היא דיה רגזנית. ונראה לי שזו היא שקורין לה היירו''ן : **הדוכיפת.** תרנגול הבר וכרבלתו כפולה ובלע''ז הירופ''א , ולמה נקרא שמו דוכיפת, שהודו כפות, וזו היא כרבלתו. תרגום אנקלוס ונגר טורא נקרא על שם מעשיו, כמו שפרשו רבותינו במסכת גטין בפרק מי שאחזו (דף סח ב) :
@272 **שרץ העוף.** הם הדקים הנמוכים הרוחשין על הארץ, כגון זבובים וצרעין ויתושין וחגבים:
@273 **על ארבע.** על ארבע רגלים: **ממעל לרגליו.** סמוך לצוארו יש לו כמין שתי רגלים לבד ארבע רגליו, וכשרוצה לעוף ולקפוץ מן הארץ מתחזק באותן שתי כרעים ופורח, ויש הרבה מהם במקומנו בינותינו, כאותן שקורין לנגושט''א , אבל אין אנו בקיאין בהן, שארבעה סימני טהרה נאמרו בהם ארבע רגלים, וארבע כנפים, וקרסלין אלו כרעים הכתובים כאן, וכנפיו חופין את רבו. וכל סימנים הללו מצויין באותן שבינותינו, אבל יש שראשן ארוך ויש שאין להם זנב וצריך שיהא שמו חגב, ובזה אין אנו יודעים להבדיל ביניהם:
@275 **וכל שרץ העוף** וגו' **.** בא ללמד שאם יש לו חמש טהור:
@276 **ולאלה.** העתידין להאמר למטה בענין: **תטמאו.** כלומר בנגיעתם יש טמאה:
@277 **וכל הנשא מנבלתם.** כל מקום שנאמרה טמאת משא, חמורה מטמאת מגע, שהיא טעונה כבוס בגדים:
@278 **מפרסת פרסה ושסע איננה שסעת.** כגון גמל שפרסתו סדוקה למעלה, אבל למטה היא מחברת. כאן למדך שנבלת בהמה טמאה מטמאה, ובענין שבסוף הפרשה פרש על בהמה טהורה:
@279 **על כפיו.** כגון כלב ודב וחתול: **טמאים הם לכם.** למגע:
@281 **וזה לכם הטמא.** כל טמאות הללו אינן לאסור אכילה אלא לטמאה ממש, להיות טמא במגען ונאסר לאכול תרומה וקדשים ולכנס במקדש: **החלד.** מושטיל''ה [נמיה] : **והצב.** פרוי''ט [קרפדה] שדומה לצפרדע:
@282 **והאנקה.** היריצו''ן [קפוד] : **והלטאה.** לישרד ''ה: **והחמט.** לימצ''ה [חלזון] : **והתנשמת.** טלפ''א [חפרפרת] :
@284 **במים יובא.** ואף לאחר טבילתו טמא הוא לתרומה עד הערב, ואחר כך וטהר בהערב השמש:
@285 **אל תוכו.** אין כלי חרס מטמא אלא מאוירו: **כל אשר בתוכו יטמא.** הכלי חוזר ומטמא מה שבאוירו: **ואתו תשברו.** למד שאין לו טהרה במקוה:
@286 **מכל האכל אשר יאכל.** מוסב על מקרא העליון, כל אשר בתוכו יטמא, מכל האכל אשר יאכל אשר יבא עליו מים והוא בתוך כלי חרס הטמא, יטמא. וכן כל משקה אשר ישתה בכל כלי, והוא בתוך כלי חרס הטמא, יטמא. למדנו מכאן דברים הרבה. למדנו שאין אוכל מכשר ומתקן לקבל טמאה עד שיבאו עליו מים פעם אחת, ומשבאו עליו מים פעם אחת מקבל טמאה לעולם ואפלו נגוב. והיין והשמן וכל הנקרא משקה מכשיר זרעים לטמאה כמים. שכך יש לדרוש המקרא, אשר יבא עליו מים או כל משקה אשר ישתה בכל כלי יטמא האוכל. ועוד למדו רבותינו מכאן, שאין ולד הטמאה מטמא כלים, שכך שנינו יכול יהיו כל הכלים מטמאין מאויר כלי חרס, תלמוד לומר כל אשר בתוכו יטמא מכל האוכל, אוכל מטמא מאויר כלי חרס, ואין כל הכלים מטמאין מאויר כלי חרס, לפי שהשרץ אב הטמאה והכלי, שנטמא ממנו, ולד הטמאה, לפיכך אינו חוזר ומטמא כלים שבתוכו. ולמדנו עוד, שהשרץ שנפל לאויר תנור והפת בתוכו, ולא נגע השרץ בפת, התנור ראשון והפת שניה. ולא נאמר רואין את התנור כאלו מלא טמאה ותהא הפת תחלה, שאם אתה אומר כן לא נתמעטו כל הכלים מלהטמא מאויר כלי חרס, שהרי טמאה עצמה נגעה בהן מגבן. ולמדנו עוד על ביאת מים, שאינה מכשרת זרעים אלא אם כן נפלו עליהן משנתלשו, שאם אתה אומר מקבלין הכשר במחבר, אין לך שלא באו עליו מים, ומהו אומר אשר יבוא עליו מים, משנתלשו. ולמדנו עוד שאין אוכל מטמא אחרים אלא אם כן יש בו כביצה, שנאמר אשר יאכל, אוכל הנאכל בבת אחת, ושערו חכמים אין בית הבליעה מחזיק יותר מביצת תרנגולת:
@287 **תנור וכירים.** כלים המטלטלין הם, והם של חרס ויש להן תוך, ושופת את הקדרה על נקב החלל ושניהם פיהם למעלה: **יתץ.** שאין לכלי חרס טהרה בטבילה: **וטמאים יהיו לכם.** שלא תאמר מצוה אני לנתצם, תלמוד לומר וטמאים יהיו לכם, אם רצה לקימן בטמאתן רשאי:
@288 **אך מעין ובור מקוה מים.** המחברים לקרקע, אין מקבלין טמאה. ועוד יש לך ללמוד יהיה טהור הטובל בהם מטמאתו: **ונגע בנבלתם יטמא.** אפלו הוא בתוך מעין ובור ונוגע בנבלתם יטמא, שלא תאמר קל וחומר אם מטהר את הטמאים מטמאתם, קל וחמר שיציל את הטהור מלטמא, לכך נאמר ונוגע בנבלתם יטמא:
@289 **זרע זרוע.** זריעה של מיני זרעונין. זרוע שם דבר הוא, כמו ויתנו לנו מן הזרועים: (דניאל א יב) **טהור הוא.** למדך הכתוב שלא הכשר ונתקן לקרות אוכל לקבל טמאה, עד שיבואו עליו מים:
@290 **וכי יתן מים על זרע.** לאחר שנתלש, שאם תאמר יש הכשר במחבר, אין לך זרע שלא הכשר: **מים על זרע.** בין מים בין שאר משקין, בין נפלו הם על הזרע, בין הזרע נפל לתוכן, הכל נדרש בתורת כהנים: **ונפל מנבלתם עליו.** אף משנגב מן המים, שלא הקפידה תורה אלא להיות עליו שם אוכל, ומשירד עליו הכשר קבלת טמאה פעם אחת, שוב אינו נעקר המנו:
@291 **בנבלתה.** ולא בעצמות וגידים ולא בקרנים וטלפים ולא בעור:
@292 **והנשא את נבלתה.** חמורה טמאת משא מטמאת מגע, שהנושא מטמא בגדים, והנוגע אין בגדיו טמאין, שלא נאמר בו יכבס בגדיו: **והאכל מנבלתה.** יכול תטמאנו אכילתו, כשהוא אומר בנבלת עוף טהור (ויקרא כב ח) נבלה וטרפה לא יאכל לטמאה בה, אותה מטמאה בגדים באכילתה, ואין נבלת בהמה מטמאה בגדים באכילתה בלא משא, כגון אם תחבה לו חברו בבית הבליעה, אם כן מה תלמוד לומר האכל, לתן שעור לנושא ולנוגע כדי אכילה והוא כזית: **וטמא עד הערב.** אף על פי שטבל צריך הערב שמש:
@293 **השרץ על הארץ.** להוציא את היתושין שבכליסין ושבפולין ואת הזיזין שבעדשים, שהרי לא שרצו על הארץ אלא בתוך האוכל, אבל משיצאו לאויר ושרצו הרי נאסרו: **לא יאכל.** לחיב על המאכיל כאוכל. ואין קרוי שרץ אלא דבר נמוך קצר רגלים, שאינו נראה אלא כרוחש ונד:
@294 **הולך על גחון.** זה נחש, ולשון גחון שחיה, שהולך שח ונופל על מעיו: **כל הולך.** להביא השלשולין ואת הדומה לדומה: **הולך על ארבע.** זה עקרב: **כל.** להביא את החפושית אישקרבו''ט בלע''ז ואת הדומה לדומה: **מרבה רגלים.** זה נדל, שרץ שיש לו רגלים מראשו ועד זנבו לכאן ולכאן, וקורין ציינפיי''ש :
@295 **אל תשקצו.** באכילתן, שהרי כתיב נפשותיכם, ואין שקוץ נפש במגע, וכן ולא תטמאו באכילתן: **ונטמתם בם.** אם אתם מטמאין בהם בארץ אף אני מטמא אתכם בעולם הבא ובישיבת מעלה:
@296 **כי אני ה' אלהיכם.** כשם שאני קדוש שאני ה' אלהיכם, כך והתקדשתם קדשו עצמכם למטה: **והייתם קדשים.** לפי שאני אקדש אתכם למעלה ובעולם הבא: **ולא תטמאו** וגו' **.** לעבור עליהם בלאוין הרבה. וכל לאו מלקות, וזהו שאמרו בתלמוד [ מכות טז ] אכל פוטיתא לוקה ארבע, נמלה לוקה חמש, צרעה לוקה שש:
@297 **כי אני ה' המעלה אתכם.** על מנת שתקבלו מצותי העלתי אתכם. דבר אחר כי אני ה' המעלה אתכם, בכלן כתיב והוצאתי, וכאן כתיב המעלה, תנא דבי רבי ישמעאל אלמלי לא העלתי את ישראל ממצרים אלא בשביל שאין מטמאין בשרצים כשאר אמות, דים, ומעליותא היא גבייהו, זהו לשון מעלה:
@299 **להבדיל.** לא בלבד השונה, אלא שתהא יודע ומכיר ובקי בהן: **בין הטמא ובין הטהר.** צריך לומר בין חמור לפרה והלא כבר מפורשים הם, אלא בין טמאה לך לטהורה לך, בין נשחט חציו של קנה לנשחט רבו: **ובין החיה הנאכלת.** צריך לומר בין צבי לערוד, והלא כבר מפורשים הם, אלא בין שנלדו בה סימני טרפה כשרה, לנלדו בה סימני טרפה פסולה:
@301 **אשה כי תזריע.** אמר ר' שמלאי כשם שיצירתו של אדם אחר כל בהמה חיה ועוף במעשה בראשית, כך תורתו נתפרשה אחר תורת בהמה חיה ועוף: **כי תזריע.** לרבות שאפלו ילדתו מחוי, שנמחה ונעשה כעין זרע, אמו טמאה לידה: **כימי נדת דותה תטמא.** כסדר כל טמאה האמורה בנדה מטמאה בטמאת לידה, ואפלו נפתח הקבר בלא דם: **דותה.** לשון דבר הזב מגופה. לשון אחר לשון מדוה וחולי, שאין אשה רואה דם שלא תחלה (י''ג: תחלה) ראשה ואבריה כבדין עליה:
@303 **תשב.** אין תשב אלא לשון עכבה, כמו (דברים א מו) ותשבו בקדש, וישב באלני ממרא (בראשית יג יח) : **בדמי טהרה.** אף על פי שרואה דם טהורה. בדמי טהרה לא מפיק ה''א, והוא שם דבר, כמו טוהר: **ימי טהרה.** מפיק ה''א, ימי טוהר שלה: **בכל קדש** וגו' **.** לרבות את התרומה, לפי שזו טבולת יום ארוך, שטבלה לסוף שבעה ואין שמשה מעריב לטהרה עד שקיעת החמה של יום ארבעים, של מחר תביא את כפרת טהרתה: **לא תגע.** אזהרה לאוכל, כמו ששנויה ביבמות (עה א) :
@306 **והקריבו.** למדך שאין מעכבה לאכול בקדשים אלא אחד מהם. ואי זה הוא, זה חטאת, שנאמר וכפר עליה הכהן וטהרה, מי שהוא בא לכפר, בו הטהרה תלויה: **וטהרה.** מכלל שעד כאן קרויה טמאה:
@307 **אחד לעלה ואחד לחטאת.** לא הקדימה הכתוב אלא למקראה, אבל הקרבת חטאת קודם לעולה, כך שנינו בזבחים בפרק כל התדיר (זבחים צ א) :
@309 **שאת או ספחת** וגו' **.** שמות נגעים הם ולבנות זו מזו: **בהרת.** חברבורות טיי''א בלע''ז [כתם] וכן (איוב לז כא) בהיר הוא בשחקים: **אל אהרן** וגו' **.** גזרת הכתוב היא שאין טמאת נגעים וטהרתן אלא על פי כהן:
@310 **ושער בנגע הפך לבן.** מתחלה שחור והפך ללבן בתוך הנגע, ומעוט שער שנים: **עמק מעור בשרו.** כל מראה לבן עמק הוא, כמראה חמה עמוקה מן הצל: **וטמא אתו.** יאמר לו טמא אתה, ששער לבן סימן טמאה הוא גזרת הכתוב:
@311 **ועמק אין מראה.** לא ידעתי פרושו: **והסגיר.** יסגירנו בבית אחד ולא יראה עד סוף השבוע, ויוכיחו סימנים עליו:
@312 **בעיניו.** במראהו ובשיעורו הראשון: **והסגירו שנית.** הא אם פשה בשבוע ראשון טמא מחלט:
@313 **כהה.** הכהה מראיתו, הא אם עמד במראיתו או פשה טמא: **מספחת.** שם נגע טהור: **וכבס בגדיו וטהר.** הואיל ונזקק להסגר נקרא טמא וצריך טבילה:
@315 **וטמאו הכהן.** ומשטמאו הרי הוא מחלט וזקוק לצפרים ולתגלחת ולקרבן האמור בפרשת זאת תהיה: **צרעת הוא.** המספחת הזאת: **צרעת.** לשון נקבה: **נגע.** לשון זכר:
@317 **ומחית.** שינמינ''ט בלע''ז [רפוי] , שנהפך מקצת הלובן שבתוך השאת למראה בשר, אף הוא סימן טמאה, שער לבן בלא מחיה, ומחיה בלא שער לבן, ואף על פי שלא נאמרה מחיה אלא בשאת, אף בכל המראות ותולדותיהן הוא סימן טמאה:
@318 **צרעת נושנת הוא.** מכה ישנה היא תחת המחיה, וחבורה זו נראית בריאה מלמעלה ותחתיה מלאה לחה, שלא תאמר הואיל ועלתה מחיה אטהרנה:
@319 **מראשו.** של אדם ועד רגליו: **לכל מראה עיני הכהן.** פרט לכהן שחשך מאורו:
@321 **וביום הראות בו בשר חי.** אם צמחה בו מחיה הרי כבר פרש שהמחיה סימן טמאה, אלא הרי שהיה הנגע באחד מעשרים וארבעה ראשי אברים שאין מטמאין משום מחיה, לפי שאין נראה הנגע כלו כאחד ששופע אלך ואלך, וחזר ראש האבר ונתגלה שפועו על ידי שמן, כגון שהבריא ונעשה רחב ונראית בו המחיה, למדנו הכתוב שתטמא: **וביום.** מה תלמוד לומר, ללמד יש יום שאתה רואה בו ויש יום שאין אתה רואה בו, מכאן אמרו חתן נותנין לו כל שבעת ימי המשתה לו ולכסותו ולביתו, וכן ברגל נותנין לו כל ימי הרגל:
@322 **צרעת הוא.** הבשר ההוא. בשר לשון זכר:
@325 **שחין.** לשון חמום, שנתחמם הבשר בלקוי הבא לו מחמת מכה, שלא מחמת האור: **ונרפא.** השחין העלה ארוכה ובמקומו העלה נגע אחר:
@326 **או בהרת לבנה אדמדמת.** שאין הנגע לבן חלק אלא פתוך ומעורב בשתי מראות לובן ואודם:
@327 **מראה שפל.** ואין ממשה שפל, אלא מתוך לבנוניתו הוא נראה שפל ועמוק, כמראה חמה עמוקה מן הצל:
@329 **נגע הוא.** השאת הזאת או הבהרת:
@330 **תחתיה.** במקומה: **צרבת השחין.** כתרגומו רושם שיחנא, אינו אלא רושם החמום הנכר בבשר. כל צרבת לשון רגיעת עור הנרגע מחמת חמום, כמו (יחזקאל כא ג) ונצרבו בה כל פנים, רייטרי''ר בלע''ז : **צרבת.** ריטריימינ''ט בלע''ז :
@331 **מחית המכוה.** שיינימנ''ט בלע''ז [רפוי] כשחיתה המכוה נהפכה לבהרת פתוכה או לבנה חלקה. וסימני מכוה וסימני שחין שוים הם, ולמה חלקן הכתוב, לומר שאין מצטרפין זה עם זה, נלד חצי גריס בשחין וחצי גריס במכוה לא ידנו כגריס:
@336 **בראש או בזקן.** בא הכתוב לחלק בין נגע שבמקום שער לנגע שבמקום בשר, שזה סימנו בשער לבן וזה סימנו בשער צהוב:
@337 **ובו שער צהב.** שנהפך שער שחור שבו לצהוב: **נתק הוא.** כך שמו של נגע, שבמקום שער:
@338 **ושער שחר אין בו.** הא אם היה בו שער שחור, טהור. ואין צריך להסגר ששער שחור סימן טהרה הוא בנתקים, כמו שנאמר (פסוק לז) ושער שחר צמח בו וגו' :
@339 **והנה לא פשה** וגו' **.** הא אם פשה או היה בו שער צהוב טמא:
@340 **והתגלח.** סביבות הנתק: **ואת הנתק לא יגלח.** מניח שתי שערות סמוך לו סביב, כדי שיהא נכר אם פשה, שאם יפשה ועבר השערות ויצא למקום הגלוח, טמא:
@342 **אחרי טהרתו.** אין לי אלא פושה לאחר הפטור, מנין אף בסוף שבוע ראשון ובסוף שבוע שני, תלמוד לומר פשה יפשה:
@344 **ושער שחר.** מנין אף הירוק והאדום שאינו צהוב, תלמוד לומר ושער. ולמה צהוב דומה, לתבנית הזהב. צהוב, כמו זהוב אורבל''א בלע''ז [זהוב] : **טהור הוא וטהרו הכהן.** הא טמא שטהרו הכהן, לא טהור:
@345 **בהרת.** חברבורות:
@346 **כהות לבנת.** שאין לובן שלהן עז אלא כהה: **בהק.** כמין לובן הנראה בבשר אדם אדום, שקורין רו''ש [אדמוני] , בין חברבורות אדמימותו, קרוי בהק, כאיש עדשן שבין עדשה לעדשה מבהיק הבשר בלובן צח:
@347 **קרח הוא טהור הוא.** טהור מטמאת נתקין, שאינו נדון בסימני ראש וזקן, שהם מקום שער, אלא בסימני נגע עור בשר בשער לבן, מחיה ופשיון:
@348 **ואם מפאת פניו.** משפוע קדקד כלפי פניו קרוי גבחת, ואף הצדעין שמכאן ומכאן בכלל. ומשפוע קדקד כלפי אחוריו, קרוי קרחת:
@349 **נגע לבן אדמדם.** פתוך. מנין שאר המראות, תלמוד לומר נגע:
@350 **כמראה צרעת עור בשר.** כמראה הצרעת האמור בפרשת עור בשר (פסוק ב) אדם כי יהיה בעור בשרו. ומה אמור בו, שמטמא בארבע מראות ונדון בשני שבועות, ולא כמראה צרעת האמור בשחין ומכוה, שהוא נדון בשבוע אחד, ולא כמראה נתקין של מקום שער שאין מטמאין בארבע מראות שאת ותולדתה, בהרת ותולדתה:
@351 **בראשו נגעו.** אין לי אלא נתקין, מנין לרבות שאר המנגעים, תלמוד לומר טמא יטמאנו, לרבות את כלן. על כלן הוא אומר בגדיו יהיו פרומים וגו' :
@352 **פרמים.** קרועים: **פרוע.** מגדל שער: **ועל שפם יעטה.** כאבל: **שפם.** שער השפתים גירנו''ן בלע''ז [שפם] : **וטמא טמא יקרא.** משמיע שהוא טמא ויפרשו ממנו:
@353 **בדד ישב.** שלא יהיו שאר טמאים יושבים עמו. ואמרו רבותינו מה נשתנה משאר טמאים לישב בדד, הואיל והוא הבדיל בלשון הרע בין איש לאשתו ובין איש לרעהו, אף הוא יבדל: **מחוץ למחנה.** חוץ לשלש מחנות:
@355 **לפשתים ולצמר.** של פשתים או של צמר: **או בעור.** זה עור שלא נעשה בו מלאכה: **או בכל מלאכת עור.** זה עור שנעשה בו מלאכה:
@356 **ירקרק.** ירוק שבירקין: **אדמדם.** אדם שבאדמים:
@358 **צרעת ממארת.** לשון סלון ממאיר (יחזקאל כח כד) . פוינינ''ט בלע''ז [דוקר] . ומדרשו תן בו מארה שלא תהנה המנו:
@359 **בצמר או בפשתים.** של צמר או של פשתים, זהו פשוטו. ומדרשו יכול יביא גזי צמר ואניצי פשתן וישרפם עמו, תלמוד לומר היא באש תשרף, אינה צריכה דבר אחר עמה. אם כן מה תלמוד לומר בצמר או בפשתים, להוציא את האימריות שבו, שהן ממין אחר. אימריות לשון שפה, כמו אימרא:
@361 **את אשר בו הנגע.** יכול מקום הנגע בלבד, תלמוד לומר את אשר בו הנגע. יכול כל הבגד כלו טעון כבוס, תלמוד לומר הנגע. הא כיצד, יכבס מן הבגד עמו:
@362 **אחרי הכבס.** לשון העשות: **לא הפך הנגע את עינו.** לא הכהה ממראיתו: **והנגע לא פשה.** שמענו שאם לא הפך ולא פשה טמא, ואין צריך לומר לא הפך ופשה. הפך ולא פשה איני יודע מה יעשה לו, תלמוד לומר והסגיר את הנגע, מכל מקום, דברי רבי יהודה. וחכמים אומרים וכו', כדאיתא בתורת כהנים. ורמזתיה כאן לישב המקרא על אפניו: **פחתת היא.** לשון גמא, כמו (שמואל ב' יז ט) באחת הפחתים, כלומר שפלה היא, נגע שמראיו שוקעין: **בקרחתו או בגבחתו.** כתרגומו בשחיקותיה או בחדתותיה: **קרחתו.** שחקים ישנים. ומפני המדרש שהצרך לגזרה שוה מנין לפריחה בבגדים שהיא טהורה, נאמרה קרחת וגבחת באדם, ונאמרה קרחת וגבחת בבגדים, מה להלן פרח בכלו טהור, אף כאן פרח בכלו טהור, לכך אחז הכתוב לשון קרחת וגבחת. ולענין פרושו ותרגומו זהו משמעו קרחת לשון ישנים, וגבחת לשון חדשים, כאלו נכתב באחריתו או בקדמותו, שהקרחת לשון אחוריים והגבחת לשון פנים, כמו שכתוב (פסוק מא) ואם מפאת פניו וגו' , והקרחת כל ששופע ויורד מן הקדקד ולאחריו, כך מפורש בתורת כהנים:
@363 **וקרע אתו.** יקרע מקום הנגע מן הבגד וישרפנו:
@364 **פרחת הוא.** דבר החוזר וצומח: **באש תשרפנו.** את כל הבגד:
@365 **וסר מהם הנגע.** אם כשכבסוהו בתחלה על פי כהן, סר ממנו הנגע לגמרי: **וכבס שנית.** לשון טבילה. תרגום של כבוסין שבפרשה זו לשון לבון ויתחור, חוץ מזה שאינו ללבון אלא לטבול, לכך תרגומו ויצטבע, וכן כל כבוסי בגדים שהן לטבילה מתרגמין ויצטבע:
@368 **זאת תהיה תורת המצרע ביום טהרתו.** מלמד שאין מטהרין אותו בלילה:
@369 **אל מחוץ למחנה.** חוץ לשלש מחנות שנשתלח שם בימי חלוטו:
@370 **חיות.** פרט לטרפות: **טהרות.** פרט לעוף טמא. לפי שהנגעים באין על לשון הרע, שהוא מעשה פטפוטי דברים, לפיכך הזקקו לטהרתו צפרים, שמפטפטין תמיד בצפצוף קול: **ועץ ארז.** לפי שהנגעים באין על גסות הרוח: **ושני תולעת ואזב.** מה תקנתו ויתרפא, ישפיל עצמו מגאותו, כתולעת וכאזוב: **עץ ארז.** מקל של ארז: **ושני תולעת.** לשון של צמר צבוע זהורית:
@371 **על מים חיים.** נותן אותם תחלה בכלי, כדי שיהא דם צפור נכר בהם. וכמה הם, רביעית:
@372 **את הצפר החיה יקח אתה.** מלמד שאינו אוגדה עמהם, אלא מפרישה לעצמה, אבל העץ והאזוב כרוכים יחד בלשון הזהורית, כענין שנאמר ואת עץ הארז ואת שני התולעת ואת האזוב, קיחה אחת לשלשתן. יכול כשם שאינה בכלל אגדה כן לא תהא בכלל טבילה, תלמוד לומר וטבל אותם ואת הצפור החיה, החזיר את הצפור לכלל טבילה:
@374 **וישב מחוץ לאהלו.** מלמד שאסור בתשמיש המטה:
@375 **את כל שערו** וגו' **.** כלל ופרט וכלל. להביא כל מקום כנוס שער ונראה:
@376 **וכבשה אחת.** לחטאת: **ושלשה עשרנים.** לנסכי שלשה כבשים הללו, שחטאתו ואשמו של מצורע טעונין נסכים: **ולג אחד שמן.** להזות עליו שבע ולתן ממנו על תנוך אזנו ומתן בהונות:
@377 **לפני ה'.** בשער נקנור, ולא בעזרה עצמה, לפי שהוא מחסר כפורים:
@378 **והקריב אתו לאשם.** יקריבנו לתוך העזרה לשם אשם: **והניף.** שהוא טעון תנופה חי: **והניף אתם.** את האשם ואת הלוג:
@379 **במקום אשר ישחט** וגו' **.** על ירך המזבח בצפון. ומה תלמוד לומר, והלא כבר נאמר בתורת אשם בפרשת צו את אהרן שהאשם טעון שחיטה בצפון, לפי שיצא זה מכלל אשמות לדון בהעמדה, יכול תהא שחיטתו במקום העמדתו, לכך נאמר ושחט במקום אשר ישחט וגו' : **כי כחטאת.** כי ככל החטאות: **האשם.** הזה: **הוא לכהן.** בכל עבודות התלויות בכהן השוה אשם זה לחטאת, שלא תאמר הואיל ויצא דמו מכלל שאר אשמות לנתן על תנוך ובהונות, לא יהא טעון מתן דמים ואימורים לגבי מזבח, לכך נאמר כי כחטאת האשם הוא לכהן. יכול יהא דמו נתן למעלה כחטאת, תלמוד לומר וכו' , בתורת כהנים:
@380 **תנוך.** גדר אמצעי שבאוזן. ולשון תנוך לא נודע לי. והפותרים קורים לו טנדרו''ס : **בהן.** גדל:
@382 **לפני ה'.** כנגד בית קדשי הקדשים:
@386 **ואת המנחה.** מנחת נסכים של בהמה:
@387 **ועשרון סלת אחד.** לכבש זה שהוא אחד יביא עשרון אחד לנסכיו: **ולוג שמן.** לתת ממנו על הבהונות ושמן של נסכי המנחה לא הזקק הכתוב לפרש:
@389 **ביום השמיני לטהרתו.** שמיני לצפרים ולהזאת עץ ארז ואזוב ושני תולעת:
@394 **על מקום דם האשם.** אפלו נתקנח הדם, למד שאין הדם גורם אלא המקום גורם:
@400 **ונתתי נגע צרעת.** בשורה היא להם שהנגעים באים עליהם, לפי שהטמינו אמוריים מטמוניות של זהב בקירות בתיהם כל ארבעים שנה שהיו ישראל במדבר, ועל ידי הנגע נותץ הבית ומוצאן:
@401 **כנגע נראה לי בבית.** אפלו תלמיד חכם שיודע שהוא נגע ודאי לא יפסוק דבר ברור לומר נגע נראה לי, אלא כנגע נראה לי:
@402 **בטרם יבא הכהן** וגו' **.** שכל זמן שאין כהן נזקק לו, אין שם תורת טמאה: **ולא יטמא כל אשר בבית.** שאם לא יפנהו ויבא הכהן ויראה הנגע, נזקק להסגר, וכל מה שבתוכו יטמא. ועל מה חסה תורה, אם על כלי שטף, יטבילם ויטהרו, ואם על אוכלין ומשקין, יאכלם בימי טמאתו, הא לא חסה התורה אלא על כלי חרס, שאין להם טהרה במקוה:
@403 **שקערורת.** שוקעות במראיהן:
@406 **וחלצו את האבנים.** כתרגומו וישלפון, יטלום משם, כמו (דברים כה ט) וחלצה נעלו, לשון הסרה: **אל מקום טמא.** מקום שאין טהרות משתמשות שם, למדך הכתוב שהאבנים הללו מטמאות מקומן בעודן בו:
@407 **יקצע.** רודוניי''ר בלע''ז . ובלשון משנה יש הרבה: **מבית.** מבפנים: **סביב.** סביבות הנגע, בתורת כהנים נדרש כן, שיקלוף הטיח שסביב אבני הנגע: **הקצו.** לשון קצה, אשר קצעו בקצות הנגע סביב:
@409 **הקצות.** לשון העשות וכן הטוח, אבל חלץ את האבנים מוסב הלשון אל האדם שחלצן והוא משקל לשון כבד, כמו כפר, דבר: **ואם ישוב הנגע** וגו' **.** יכול חזר בו ביום יהא טמא, תלמוד לומר ושב הכהן ואם ישוב, מה שיבה האמורה להלן לסוף שבוע, אף שיבה האמורה כאן בסוף שבוע:
@410 **ובא הכהן וראה והנה פשה.** יכול לא יהא החוזר טמא אלא אם כן פשה, נאמר צרעת ממארת בבתים ונאמר צרעת ממארת בבגדים, מה להלן טמא את החוזר אף על פי שאינו פושה, אף כאן טמא את החוזר אף על פי שאינו פושה, אם כן מה תלמוד לומר והנה פשה, אין כאן מקומו של מקרא זה, אלא ונתץ את הבית היה לו לכתוב אחר ואם ישוב הנגע וראה והנה פשה, הא לא בא ללמד אלא על נגע העומד בעיניו בשבוע ראשון ובא בסוף שבוע שני ומצאו שפשה, שלא פרש בו הכתוב למעלה כלום בעומד בעיניו בשבוע ראשון, ולמדך כאן בפשיון זה שאינו מדבר אלא בעומד בראשון ופשה בשני ומה יעשה לו, יכול יתצנו, כמו שסמך לו ונתץ את הבית, תלמוד לומר ושב הכהן ובא הכהן, נלמד ביאה משיבה, מה שיבה חולץ וקוצה וטח ונותן לו שבוע, אף ביאה חולץ וקוצה וטח ונותן לו שבוע. ואם חוזר, נותץ. לא חזר, טהור. ומנין שאם עמד בזה ובזה חולץ וקוצה וטח ונותן לו שבוע, תלמוד לומר ובא ואם בא יבא, במה הכתוב מדבר, אם בפושה בראשון הרי כבר אמר, אם בפושה בשני הרי כבר אמור, הא אינו אומר [ובא] , ואם בא יבא, אלא את שבא בסוף שבוע ראשון ובא בסוף שבוע שני וראה והנה לא פשה. זה העומד מה יעשה לו, יכול יפטר וילך, כמו שכתוב כאן וטהר את הבית, תלמוד לומר כי נרפא הנגע, לא טהרתי אלא את הרפאוי, מה יעשה לו, ביאה אמורה למעלה וביאה אמורה למטה, מה בעליונה חולץ וקוצה וטח ונותן לו שבוע, דגמר לה זהו שיבה זהו ביאה, אף בתחתונה כן וכו' , כדאיתא בתורת כהנים. גמרו של דבר אין נתיצה אלא בנגע החוזר אחר חליצה וקצוע וטיחה ואין החוזר צריך פשיון. וסדר המקראות כך הוא ואם ישוב, ונתץ, והבא אל הבית, והאוכל בבית, ובא הכהן וראה והנה פשה. ודבר הכתוב בעומד בראשון שנותן לו שבוע שני להסגרו, ובסוף שבוע שני להסגרו בא וראהו שפשה, ומה יעשה לו, חולץ וקוצה וטח ונותן לו שבוע. חזר, נותץ. לא חזר, טעון צפרים, שאין בנגעים יותר משלשה שבועות:
@412 **כל ימי הסגיר אתו.** ולא ימים שקלף את נגעו, יכול שאני מוציא המחלט שקלף את נגעו, תלמוד לומר כל ימי: **יטמא עד הערב.** מלמד שאין מטמא בגדים, יכול אפלו שהה בכדי אכילת פרס, תלמוד לומר והאוכל בבית יכבס את בגדיו. אין לי אלא אכל, שכב מנין, תלמוד לומר והשוכב. אין לי אלא אוכל ושוכב, לא אוכל ולא שוכב מנין, תלמוד לומר יכבס יכבס, רבה. אם כן למה נאמר אוכל ושוכב, לתן שיעור לשוכב כדי אכילת פרס:
@414 **ואם בא יבא.** לסוף שבוע שני: **וראה והנה לא פשה.** מקרא זה בא ללמד בעומד בעיניו בראשון ובשני מה יעשה לו, יכול יטהרנו כמשמעו של מקרא וטהר הכהן את הבית, תלמוד לומר כי נרפא הנגע, לא טהרתי אלא את הרפאוי, ואין רפוי אלא הבית שהקצה והוטח ולא חזר הנגע, אבל זה טעון חליצה וקצוי וטיחה ושבוע שלישי. וכן המקרא נדרש ואם בא יבא בשני, וראה והנה לא פשה יטיחנו, ואין טיחה בלא חלוץ וקצוי. ואחרי הטוח את הבית וטהר הכהן את הבית אם לא חזר לסוף השבוע, כי נרפא הנגע, ואם חזר כבר פרש על החוזר שטעון נתיצה:
@423 **להורת ביום הטמא.** איזה יום מטהרו ואיזה יום מטמאו:
@425 **כי יהיה זב.** יכול זב מכל מקום יהא טמא, תלמוד לומר מבשרו ולא כל בשרו. אחר שחלק הכתוב בין בשר לבשר זכיתי לדון, טמא בזב וטמא בזבה, מה זבה ממקום שהיא מטמאה טמאה קלה, נדה, מטמאה טמאה חמורה, זיבה, אף הזב ממקום שמטמא טמאה קלה, קרי, מטמא טמאה חמורה, זיבה: **זובו טמא.** למד על הטפה שהיא מטמאה. זוב דומה למי בצק של שעורין ודחוי, ודומה ללובן ביצה המוזרת. שכבת זרע קשור כלובן ביצה שאינה מוזרת:
@426 **רר.** לשון ריר שזב את בשרו: **את זובו.** כמו ריר שיוצא צלול: **או החתים.** שיוצא עב וסותם את פי האמה ונסתם בשרו מטפת זובו, זהו פשוטו. ומדרשו מנה הכתוב הראשון ראיות שתים וקראו טמא, שנאמר זב מבשרו זובו טמא הוא, ומנה הכתוב השני ראיות שלש וקראו טמא, שנאמר טמאתו בזובו רר בשרו את זובו או החתים בשרו מזובו טמאתו היא. הא כיצד, שתים לטמאה, והשלישית מזקיקתו לקרבן:
@427 **כל המשכב.** הראוי למשכב, יכול אפלו מיוחד למלאכה אחרת, תלמוד לומר אשר ישכב, אשר שכב לא נאמר, אלא אשר ישכב, המיוחד תמיד לכך, יצא זה שאומרים לו עמוד ונעשה מלאכתנו: **אשר ישב.** ישב לא נאמר אלא אשר ישב עליו הזב, במיוחד תמיד לכך:
@428 **ואיש אשר יגע במשכבו.** למד על המשכב שחמור מן המגע, שזה נעשה אב הטמאה לטמא אדם לטמא בגדים, והמגע שאינו משכב אינו אלא ולד הטמאה, ואינו מטמא אלא אוכלין ומשקין:
@429 **והישב על הכלי.** אפלו לא נגע, אפלו עשרה כלים זה על זה, כלן מטמאין משום מושב וכן במשכב:
@431 **וכי ירק הזב בטהור.** ונגע בו או נשאו, שהרוק מטמא במשא:
@432 **וכל המרכב.** אף על פי שלא ישב עליו, כגון התפוס של סרגא שקורין ארצו''ן [שלד האכף] טמא משום מרכב. והאכף, שקורין אלוו''ש טמא טמאת מושב:
@433 **וכל הנגע בכל אשר יהיה תחתיו.** של זב. בא ולמד על המרכב, שיהא הנוגע בו טמא ואין טעון כבוס בגדים, והוא חמר במשכב מבמרכב: **והנושא אותם.** את כל האמור בענין הזב, זובו ורקו ושכבת זרעו ומימי רגליו והמשכב והמרכב והמושב, שיהא משאן מטמא אדם לטמא בגדים:
@434 **וידיו לא שטף במים.** בעוד שלא טבל מטמאתו, ואפלו פסק מזובו וספר שבעה ומחסר טבילה, מטמא בכל טמאותיו. וזה שהוציא הכתוב טבילת גופו של זב בלשון שטיפת ידים, ללמדך שאין בית הסתרים טעון ביאת מים, אלא אבר הגלוי, כמו הידים:
@435 **וכלי חרש אשר יגע בו הזב.** יכול אפלו נגע בו מאחוריו וכו' , כדאיתא בתורת כהנים, עד איזהו מגעו שהוא בכלו הוי אומר זה הסיטו:
@436 **וכי יטהר.** כשיפסוק: **שבעת ימים לטהרתו.** שבעת ימים טהורים מטמאת זיבה, שלא יראה זוב, וכלן רצופין:
@441 **ורחצו במים.** גזרת מלך היא שתטמא האשה בביאה. ואין הטעם משום נוגע בשכבת זרע, שהרי מגע בית הסתרים הוא:
@442 **כי תהיה זבה.** יכול מאחד מכל איבריה, תלמוד לומר (ויקרא כ יח) והיא גלתה את מקור דמיה, אין דם מטמא אלא הבא מן המקור: **דם יהיה זבה בבשרה.** אין זובה קרוי זוב לטמא אלא אם כן הוא אדום: **בנדתה.** כמו (איוב יח יח) ומתבל ינדהו, שהיא מנדה ממגע כל אדם: **תהיה בנדתה.** אפלו לא ראתה אלא ראיה ראשונה:
@446 **ואם על המשכב הוא.** השוכב או היושב על משכבה או על מושבה, אפלו לא נגע בה, אף הוא בדת טמאה האמורה במקרא העליון שטעון כבוס בגדים: **על הכלי.** לרבות את המרכב: **בנגעו בו יטמא.** אינו מדבר אלא על המרכב שנתרבה מעל הכלי: **בנגעו בו יטמא.** ואינו טעון כבוס בגדים שהמרכב אין מגעו מטמא אדם לטמא בגדים:
@447 **ותהי נדתה עליו.** יכול יעלה לרגלה, שאם בא עליה בחמישי לנדתה לא יטמא אלא שלשה ימים כמותה, תלמוד לומר וטמא שבעת ימים. ומה תלמוד לומר ותהי נדתה עליו, מה היא מטמאה אדם וכלי חרס, אף הוא מטמא אדם וכלי חרס:
@448 **ימים רבים.** שלשה ימים: **בלא עת נדתה.** אחר שיצאו שבעת ימי נדתה: **או כי תזוב.** את שלשת הימים הללו: **על נדתה.** מפלג מנדתה יום אחד, זו היא זבה ומשפטה חרוץ בפרשה זו, ולא כדת הנדה, שזו טעונה ספירת שבעה נקיים וקרבן, והנדה אינה טעונה ספירת שבעה נקיים, אלא שבעת ימים תהיה בנדתה בין רואה בין שאינה רואה. ודרשו רבותינו בפרשה זו, אחד עשר יום יש בין סוף נדה לתחלת נדה, שכל שלשה רצופין שתראה באחד עשר יום הללו, תהא זבה:
@454 **והזרתם.** אין נזירה אלא פרישה, וכן (ישעיה א ד) נזורו אחור, וכן (בראשית מט כו) נזיר אחיו: **ולא ימתו בטמאתם.** הרי הכרת של מטמא מקדש קרוי מיתה:
@455 **זאת תורת הזב.** בעל ראיה אחת, ומהו תורתו, **ואשר תצא ממנו שכבת זרע.** הרי הוא כבעל קרי טמא טמאת ערב:
@456 **והזב את זובו.** בעל שתי ראיות ובעל שלש ראיות, שתורתן מפורשת למעלה:
@457 **וידבר ה' אל משה אחרי מות שני בני אהרן** וגו' **.** מה תלמוד לומר, היה רבי אלעזר בן עזריה מושלו משל לחולה שנכנס אצלו רופא. אמר לו אל תאכל צונן ואל תשכב בטחב. בא אחר ואמר לו אל תאכל צונן ואל תשכב בטחב שלא תמות כדרך שמת פלוני. זה זרזו יותר מן הראשון, לכך נאמר אחרי מות שני בני אהרן:
@458 **ויאמר ה' אל משה דבר אל אהרן אחיך ואל יבא.** שלא ימות כדרך שמתו בניו: **ולא ימות.** שאם בא הוא מת: **כי בענן אראה.** כי תמיד אני נראה שם עם עמוד ענני. ולפי שגלוי שכינתי שם, יזהר שלא ירגיל לבא, זהו פשוטו. ומדרשו לא יבא כי אם בענן הקטרת ביום הכפורים:
@459 **בזאת.** גימטריא שלו ארבע מאות ועשר, רמז לבית ראשון: **בזאת יבא אהרן** וגו' **.** ואף זו לא בכל עת, כי אם ביום הכפורים, כמו שמפורש בסוף הפרשה (פסוק כט) בחדש השביעי בעשור לחדש:
@460 **כתנת בד** וגו' **.** מגיד שאינו משמש לפנים בשמונה בגדים שהוא משמש בהם בחוץ, שיש בהם זהב, לפי שאין קטגור נעשה סנגור, אלא בארבעה, ככהן הדיוט, וכלן של בוץ: **קדש ילבש.** שהיו משל קדש: **יצנף.** כתרגומו יחית ברישיה, יניח בראשו, כמו (בראשית לט טז) ותנח בגדו ואחתתיה: **ורחץ במים.** אותו היום טעון טבילה בכל חליפותיו. וחמש פעמים היה מחליף מעבודת פנים לעבודת חוץ ומחוץ לפנים, ומשנה מבגדי זהב לבגדי לבן ומבגדי לבן לבגדי זהב, ובכל חליפה טעון טבילה ושני קדושי ידים ורגלים מן הכיור:
@462 **את פר החטאת אשר לו.** האמור למעלה. ולמדך כאן שמשלו הוא בא, ולא משל צבור: **וכפר בעדו ובעד ביתו.** מתודה עליו עונותיו ועונות ביתו:
@464 **ונתן אהרן על שני השעירים גרלות.** מעמיד אחד לימין ואחד לשמאל, ונותן שתי ידיו בקלפי ונוטל גורל בימין וחברו בשמאל, ונותן עליהם, את שכתוב בו לשם הוא לשם, ואת שכתוב בו לעזאזל משתלח לעזאזל: **עזאזל.** הוא הר עז וקשה, צוק גבוה, שנאמר (פסוק כב) ארץ גזרה, חתוכה:
@465 **ועשהו חטאת.** כשמניח הגורל עליו קורא לו שם ואומר לה' חטאת:
@466 **יעמד חי.** כמו יעמד חי על ידי אחרים, ותרגומו יתקם כד חי. מה תלמוד לומר חי, לפי שנאמר לשלח אתו לעזאזל, ואיני יודע שלוחו אם למיתה אם לחיים, לכך נאמר יעמד חי, עמידתו חי עד שישתלח, מכאן ששלוחו למיתה: **לכפר עליו.** שיתודה עליו, כדכתיב (פסוק כא) והתודה עליו וגו' :
@467 **וכפר בעדו** וגו' **.** ודוי שני עליו ועל אחיו הכהנים, שהם כלם קרויים ביתו, שנאמר (תהלים קלה יט) בית אהרן ברכו את ה' וגו' , מכאן שהכהנים מתכפרים בו, וכל כפרתן אינה אלא על טמאת מקדש וקדשיו, כמו שנאמר (פסוק טז) וכפר על הקדש מטמאות וגו' :
@468 **מעל המזבח.** החיצון: **מלפני ה'.** מצד שלפני הפתח והוא צד מערבי: **דקה.** מה תלמוד לומר דקה, והלא כל הקטורת דקה היא, שנאמר (שמות ל לו) ושחקת ממנה הדק, אלא שתהא דקה מן הדקה, שמערב יום הכפורים היה מחזירה למכתשת:
@469 **על האש.** שבתוך המחתה: **ולא ימות.** הא אם לא עשאה כתקנה, חיב מיתה:
@470 **והזה באצבעו.** הזאה אחת במשמע: **ולפני הכפרת יזה שבע.** הרי אחת למעלה ושבע למטה:
@471 **אשר לעם.** מה שהפר מכפר על הכהנים מכפר השעיר על ישראל, והוא השעיר שעלה עליו הגורל לשם: **כאשר עשה לדם הפר.** אחת למעלה ושבע למטה:
@472 **מטמאת בני ישראל.** על הנכנסין למקדש בטמאה ולא נודע להם בסוף, שנאמר לכל חטאתם, וחטאת היא שוגג: **ומפשעיהם.** אף הנכנסין מזיד בטמאה: **וכן יעשה לאהל מועד.** כשם שהזה משניהם בפנים אחת למעלה ושבע למטה, כך מזה על הפרוכת מבחוץ משניהם אחת למעלה ושבע למטה: **השכן אתם בתוך טמאתם.** אף על פי שהם טמאים שכינה ביניהם:
@474 **אל המזבח אשר לפני ה'.** זה מזבח הזהב שהוא לפני ה' בהיכל. ומה תלמוד לומר ויצא, לפי שהזה ההזאות על הפרוכת ועמד מן המזבח ולפנים והזה, ובמתנות המזבח הזקיקו לצאת מן המזבח ולחוץ, ויתחיל מקרן מזרחית צפונית: **וכפר עליו.** ומה היא כפרתו, ולקח מדם הפר ומדם השעיר, מעורבין זה לתוך זה:
@475 **והזה עליו מן הדם.** אחר שנתן מתנות באצבעו על קרנותיו, מזה שבע הזאות על גגו: **וטהרו.** ממה שעבר: **וקדשו.** לעתיד לבא:
@477 **איש עתי.** המוכן לכך מיום אתמול:
@479 **ובא אהרן אל אהל מועד.** אמרו רבותינו, שאין זה מקומו של מקרא זה, ונתנו טעם לדבריהם במסכת יומא (דף לב א) ואמרו כל הפרשה כלה אמורה על הסדר, חוץ מביאה זו, שהיא אחר עשית עולתו ועולת העם והקטרת אימורי פר ושעיר שנעשים בחוץ בבגדי זהב, וטובל ומקדש ופושטן ולובש בגדי לבן: **ובא אל אהל מועד.** להוציא את הכף ואת המחתה שהקטיר בה הקטרת לפני ולפנים: **ופשט את בגדי הבד.** אחר שהוציאם ולובש בגדי זהב לתמיד של בין הערבים. וזהו סדר העבודות תמיד של שחר בבגדי זהב, ועבודת פר ושעיר הפנימיים וקטרת של מחתה בבגדי לבן, ואילו ואיל העם ומקצת המוספין בבגדי זהב, והוצאת כף ומחתה בבגדי לבן, ושירי המוספין ותמיד של בין הערבים וקטורת ההיכל שעל מזבח הפנימי בבגדי זהב. וסדר המקראות לפי סדר העבודות כך הוא ושלח את השעיר במדבר, ורחץ את בשרו במים וגו' ויצא ועשה את עולתו וגו' ואת חלב החטאת וגו' . וכל הפרשה עד ואחרי כן יבא אל המחנה, ואחר כך ובא אהרן: **והניחם שם.** מלמד שטעונין גניזה, ולא ישתמש באותן ארבעה בגדים ליום כפורים אחר:
@480 **ורחץ את בשרו** וגו' **.** למעלה למדנו מורחץ את בשרו ולבשם (פסוק ד) , שכשהוא משנה מבגדי זהב לבגדי לבן טעון טבילה, שבאותה טבילה פשט בגדי זהב שעבד בהן עבודת תמיד של שחר ולבש בגדי לבן לעבודת היום, וכאן למדנו שכשהוא משנה מבגדי לבן לבגדי זהב טעון טבילה: **במקום קדוש.** המקדש בקדשת עזרה והיא היתה בגג בית הפרוה, וכן ארבע טבילות הבאות חובה ליום, אבל הראשונה היתה בחול: **ולבש את בגדיו.** שמונה בגדים שהוא עובד בהן כל ימות השנה: **ויצא.** מן ההיכל אל החצר שמזבח העולה שם: **ועשה את עלתו.** איל לעולה האמור למעלה (פסוק ג) בזאת יבא אהרן וגו' : **ואת עלת העם.** ואיל אחד לעולה האמור למעלה (פסוק ה) ומאת עדת בני ישראל וגו' :
@481 **ואת חלב החטאת.** אימורי פר ושעיר: **יקטיר המזבחה.** על מזבח החיצון, דאלו בפנימי כתיב (שמות ל ט) לא תעלו עליו קטרת זרה ועולה ומנחה:
@483 **אשר הובא את דמם.** להיכל ולפני ולפנים:
@488 **וכפר הכהן אשר ימשח** וגו' **.** כפרה זו של יום הכפורים אינה כשרה אלא בכהן גדול, לפי שנאמרה כל הפרשה באהרן, הצרך לומר בכהן גדול הבא אחריו שיהא כמוהו: **ואשר ימלא את ידו.** אין לי אלא המשוח בשמן המשחה, מרבה בגדים מנין, תלמוד לומר ואשר ימלא את ידו וגו' , והם כל הכהנים הגדולים שעמדו מיאשיהו ואילך, שבימיו נגנזה צלוחית של שמן המשחה: **לכהן תחת אביו.** ללמד שאם בנו ממלא את מקומו הוא קודם לכל אדם:
@490 **ויעש כאשר צוה ה'** וגו' **.** כשהגיע יום הכפורים עשה כסדר הזה, ולהגיד שבחו של אהרן שלא היה לובשן לגדלתו, אלא כמקיים גזרת המלך:
@493 **אשר ישחט שור או כשב.** במקדשין הכתוב מדבר, שנאמר להקריב קרבן: **במחנה.** חוץ לעזרה:
@494 **דם יחשב.** כשופך דם האדם שמתחייב בנפשו: **דם שפך.** לרבות את הזורק דמים בחוץ:
@495 **אשר הם זבחים.** אשר הם רגילים לזבוח:
@497 **לשעירם.** לשדים, כמו (ישעיה יג כא) ושעירים ירקדו שם:
@498 **אשר יעלה עלה.** לחיב על המקטיר איברים בחוץ כשוחט בחוץ, שאם שחט אחד והעלה חברו שניהם חיבין:
@499 **ונכרת.** זרעו נכרת וימיו נכרתין:
@500 **כל דם.** לפי שנאמר בנפש יכפר, יכול לא יהא חיב אלא על דם המקדשים, תלמוד לומר כל דם: **ונתתי פני.** פנאי שלי, פונה אני מכל עסקי ועוסק בו:
@501 **כי נפש הבשר.** של כל בריה בדם היא תלויה, ולפיכך נתתיו על המזבח לכפר על נפש האדם. תבוא נפש ותכפר על הנפש:
@502 **כל נפש מכם.** להזהיר גדולים על הקטנים:
@503 **אשר יצוד.** אין לי אלא ציד, אוזין ותרנגולין מנין, תלמוד לומר ציד מכל מקום. אם כן למה נאמר אשר יצוד, שלא יאכל בשר אלא בהזמנה הזאת: **אשר יאכל.** פרט לטמאים:
@504 **דמו בנפשו הוא.** דמו הוא לו במקום הנפש, שהנפש תלויה בו: **כי נפש כל בשר דמו הוא.** הנפש היא הדם. דם ובשר לשון זכר' נפש לשון נקבה:
@505 **אשר תאכל נבלה וטרפה.** בנבלת עוף טהור דבר הכתוב' שאין לה טמאה אלא בשעה שנבלעת בבית הבליעה' ולמדך כאן שמטמאה באכילתה' ואינה מטמאה במגע. וטרפה האמורה כאן לא נכתבה אלא לדרוש. וכן שנינו יכול תהא נבלת עוף טמא מטמאה בבית הבליעה' תלמוד לומר טרפה' מי שיש במינו טרפה' יצא עוף טמא שאין במינו טרפה:
@506 **ונשא עונו.** אם יאכל קדש או יכנס למקדש חיב על טמאה זו ככל שאר טמאות: **ובשרו לא ירחץ ונשא עונו.** על רחיצת גופו ענוש כרת ועל כבוס בגדים במלקות:
@508 **אני ה' אלהיכם.** אני הוא שאמרתי בסיני (שמות כ ב) אנכי ה' אלהיך, וקבלתם עליכם מלכותי, מעתה קבלו גזרותי. רבי אומר גלוי וידוע לפניו שסופן לנתק בעריות בימי עזרא, לפיכך בא עליהם בגזרה אני ה' אלהיכם, דעו מי גוזר עליכם, דין להפרע ונאמן לשלם שכר:
@509 **כמעשה ארץ מצרים.** מגיד שמעשיהם של מצריים ושל כנעניים מקלקלים מכל האמות, ואותו מקום שישבו בו ישראל מקלקל מן הכל: **אשר אני מביא אתכם שמה.** מגיד שאותן עממין שכבשו ישראל מקלקלים יותר מכלם: **ובחקתיהם לא תלכו.** מה הניח הכתוב שלא אמר, אלא אלו נמוסות שלהן, דברים החקוקין להם, כגון טרטיאות ואצטדיאות. רבי מאיר אומר אלו דרכי האמורי שמנו חכמים:
@510 **את משפטי תעשו.** אלו דברים האמורים בתורה במשפט, שאלו לא נאמרו, היו כדאי לאמרן: **ואת חקתי תשמרו.** דברים שהם גזרת המלך, שיצר הרע משיב עליהם, למה לנו לשמרן, ואמות העולם משיבין עליהם, כגון אכילת חזיר ולבישת שעטנז וטהרת מי חטאת, לכך נאמר אני ה' גזרתי עליכם, אי אתם רשאים להפטר: **ללכת בהם.** אל תפטר מתוכם, שלא תאמר למדתי חכמת ישראל אלך ואלמד חכמת האמות:
@511 **ושמרתם את חקתי** וגו' **.** לרבות שאר דקדוקי הפרשה, שלא פרט הכתוב בהם. דבר אחר לתן שמירה ועשייה לחקים ושמירה ועשייה למשפטים, לפי שלא נתן אלא עשייה למשפטים ושמירה לחקים: **וחי בהם.** לעולם הבא, שאם תאמר בעולם הזה, והלא סופו הוא מת: **אני ה'.** נאמן לשלם שכר:
@512 **לא תקרבו.** להזהיר הנקבה כזכר, לכך נאמר לשון רבים: **אני ה'.** נאמן לשלם שכר:
@513 **ערות אביך.** זו אשת אביך, או אינו אלא כמשמעו, נאמר כאן ערות אביך, ונאמר להלן (ויקרא כ יא) ערות אביו גלה, מה להלן אשת אביו, אף כאן אשת אביו: **וערות אמך.** להביא אמו שאינה אשת אביו:
@514 **ערות אשת אביך.** לרבות לאחר מיתה:
@515 **בת אביך.** אף בת אנוסה במשמע: **מולדת בית או מולדת חוץ.** בין שאומרים לו לאביך קים את אמה ובין שאומרים לו לאביך הוצא את אמה, כגון ממזרת או נתינה:
@516 **ערות בת בנך.** בבתו מאנוסתו הכתוב מדבר, ובתו ובת בתו מאשתו אנו למדין מערות אשה ובתה לא תגלה, בין שהיא ממנו ובין שהיא מאיש אחר: **ערות בת בנך.** קל וחמר לבתך, אלא לפי שאין מזהירין מן הדין למדוה מגזרה שוה במסכת יבמות (ג א) :
@517 **ערות בת אשת אביך.** למד שאינו חיב על אחותו משפחה ונכרית לכך נאמר בת אשת אביך בראויה לקדושין:
@520 **ערות אחי אביך לא תגלה.** ומה היא ערותו, אל אשתו לא תקרב:
@521 **אשת בנך היא.** לא אמרתי אלא בשיש לבנך אישות בה, פרט לאנוסה ושפחה ונכרית:
@523 **ערות אשה ובתה.** לא אסר הכתוב אלא על ידי נשואי הראשונה, לכך נאמר לא תקח, לשון קיחה, וכן לענין הענש אשר יקח את אשה ואת אמה (ויקרא כ יד) , לשון קיחה, אבל אנס אשה מתר לשא בתה: **שארה הנה.** קרובות (הן) זו לזו: **זמה.** עצה כתרגומו עצת חטאין, שיצרך יועצך לחטוא:
@524 **אל אחתה.** שתיהן כאחת: **לצרר.** לשון צרה לעשות את זו צרה לזו: **בחייה.** למדך שאם גרשה לא ישא את אחותה כל זמן שהיא בחיים:
@527 **למלך.** עבודה זרה היא ששמה מולך, וזו היא עבודתה, שמוסר בנו לכומרים ועושין שתי מדורות גדולות ומעבירין את הבן ברגליו בין שתי מדורות האש: **לא תתן.** זו היא מסירתו לכומרים: **להעביר למלך.** זו (היא) העברת האש:
@529 **תבל הוא.** לשון קדש וערוה ונאוף, וכן ואפי על תבליתם (ישעיה י כה) . דבר אחר תבל הוא לשון בלילה וערבוב, זרע אדם וזרע בהמה:
@534 **ולא תקיא הארץ אתכם.** משל לבן מלך שהאכילוהו דבר מאוס, שאין עומד במעיו אלא מקיאו, כך ארץ ישראל אינה מקימת עוברי עברה. ותרגומו ולא תרוקין, לשון רקון, מריקה עצמה מהם:
@535 **הנפשות העשת.** הזכר והנקבה במשמע:
@536 **ושמרתם את משמרתי.** להזהיר בית דין על כך: **ולא תטמאו בהם אני ה' אלהיכם.** הא אם תטמאו, אני אלהיכם, ואתם נפסלים מאחרי, ומה הנאה יש לי בכם, ואתם מתחיבים כליה, לכך נאמר אני ה' אלהיכם:
@538 **דבר אל כל עדת בני ישראל.** מלמד שנאמרה פרשה זו בהקהל, מפני שרוב גופי תורה תלויין בה: **קדשים תהיו.** הוו פרושים מן העריות ומן העברה, שכל מקום שאתה מוצא גדר ערוה אתה מוצא קדשה, אשה זונה וחללה וגו' אני ה' מקדשכם, (ויקרא כא ז. ח) ולא יחלל זרעו אני ה' מקדשו (ויקרא כא טו) קדשים יהיו אשה זונה וחללה וגו' (ויקרא כא ו. ז) :
@539 **איש אמו ואביו תיראו.** כל אחד מכם תיראו אביו ואמו, זהו פשוטו. ומדרשו אין לי אלא איש, אשה מנין, כשהוא אומר תיראו, הרי כאן שנים אם כן למה נאמר איש, שהאיש ספק בידו לעשות, אבל אשה רשות אחרים עליה: **אמו ואביו תיראו.** כאן הקדים אם לאב, לפי שגלוי לפניו שהבן ירא את אביו יותר מאמו, ובכבוד הקדים אב לאם, לפי שגלוי לפניו שהבן מכבד את אמו יותר מאביו, מפני שמשדלתו בדברים: **ואת שבתתי תשמרו.** סמך שמירת שבת למורא אב, לומר אף על פי שהזהרתיך על מורא אב, אם יאמר לך חלל את השבת אל תשמע לו, וכן בשאר כל המצות: **אני ה' אלהיכם.** אתה ואביך חיבים בכבודי, לפיכך לא תשמע לו לבטל את דברי. איזהו מורא, לא ישב במקומו ולא ידבר במקומו ולא יסתור את דבריו. ואיזהו כבוד, מאכיל ומשקה, מלביש ומנעיל, מכניס ומוציא:
@540 **אל תפנו אל האלילם.** לעבדם. אלילים לשון אל, כלא הוא חשוב: **ואלהי מסכה.** תחלתן אלילים הם, ואם אתה פונה אחריהם, סופך לעשותן אלהות: **לא תעשו לכם.** לא תעשו לאחרים ולא אחרים לכם. ואם תאמר לא תעשו לעצמכם אבל אחרים עושין לכם, הרי כבר נאמר (שמות כ ג) לא יהיה לך, לא שלך ולא של אחרים:
@541 **וכי תזבחו** וגו' **.** לא נאמרה פרשה זו אלא ללמד שלא תהא זביחתן אלא על מנת להאכל בתוך הזמן הזה, שאם לקבוע להם זמן אכילה, הרי כבר נאמר (ויקרא ז טז) ואם נדר או נדבה זבח קרבנו וגו' : **לרצנכם תזבחהו.** תחלת זביחתו תהא על מנת נחת רוח שיהא לכם לרצון, שאם תחשבו עליו מחשבת פסול לא ירצה עליכם לפני: **לרצנכם.** אפיימנ''ט [פיוס] . זהו לפי פשוטו. ורבותינו למדו (חולין יג א) , מכאן למתעסק בקדשים שפסול, שצריך שיתכון לשחוט:
@542 **ביום זבחכם יאכל.** כשתזבחוהו, תשחטוהו על מנת לאכלו בזמן שקבעתי לכם כבר:
@543 **ואם האכל יאכל** וגו' **.** אם אינו ענין לחוץ לזמנו, שהרי כבר נאמר (ויקרא ז יח) ואם האכל יאכל מבשר זבח שלמיו וגו' , תנהו ענין לחוץ למקומו. יכול יהיו חייבין כרת על אכילתו, תלמוד לומר (שם) והנפש האכלת ממנו עונה תשא, ממנו ולא מחברו, יצא הנשחט במחשבת חוץ למקומו: **פגול.** מתועב, כמו (ישעיה סה ד) ומרק פגולים כליהם:
@544 **ואכליו עונו ישא.** בנותר גמור הכתוב מדבר ואינו ענוש כרת על הנשחט חוץ למקומו שכבר מיעטו הכתוב. וזהו בנותר גמור מדבר. ובמסכת כריתות (ה א) למדוהו מגזרה שוה:
@545 **לא תכלה פאת שדך.** שיניח פאה בסוף שדהו: **ולקט קצירך.** שבלים הנושרים בשעת קצירה אחת או שתים, אבל שלש אינן לקט:
@546 **לא תעולל.** לא תטל עוללות שבה והן נכרות. איזהו עוללות כל שאין לה לא כתף ולא נטף: **ופרט כרמך.** גרגרי ענבים הנושרים בשעת בצירה: **אני ה' אלהיכם.** דין להפרע ואיני גובה מכם אלא נפשות, שנאמר (משלי כב. כג) אל תגזל דל וגו' כי ה' יריב ריבם וגו' :
@547 **לא תגנבו.** אזהרה לגונב ממון, אבל לא תגנוב (שמות כ יג) שבעשרת הדברות, אזהרה לגונב נפשות, דבר הלמד מענינו, דבר שחיבין עליו מיתת בית דין: **ולא תכחשו.** לפי שנאמר (ויקרא ה כב) וכחש בה, משלם קרן וחומש. למדנו עונש, אזהרה מנין, תלמוד לומר ולא תכחשו: **ולא תשקרו.** לפי שנאמר (שם) ונשבע על שקר, ישלם קרן וחומש. למדנו עונש, אזהרה מנין, תלמוד לומר ולא תשקרו: **לא תגנבו ולא תכחשו ולא תשקרו ולא תשבעו.** אם גנבת, סופך לכחש, סופך לשקר, סופך להשבע לשקר:
@548 **ולא תשבעו בשמי.** למה נאמר, לפי שנאמר (שמות כ ז) לא תשא את שם ה' אלהיך לשוא, יכול לא יהא חיב אלא על שם המיוחד, מנין לרבות כל הכנויין, תלמוד לומר ולא תשבעו בשמי לשקר, כל שם שיש לי:
@549 **לא תעשק.** זה הכובש שכר שכיר: **לא תלין.** לשון נקבה מוסב על הפעלה: **עד בקר.** בשכיר יום הכתוב מדבר, שיציאתו מששקעה החמה, לפיכך זמן גבוי שכרו כל הלילה. ובמקום אחר הוא אומר (דברים כד טו) ולא תבוא עליו השמש, מדבר בשכיר לילה, שהשלמת פעלתו משיעלה עמוד השחר, לפיכך זמן גבוי שכרו כל היום, לפי שנתנה תורה זמן לבעל הבית עונה לבקש מעות:
@550 **לא תקלל חרש.** אין לי אלא חרש, מנין לרבות כל אדם, תלמוד לומר (שמות כב כז) בעמך לא תאר, אם כן למה נאמר חרש, מה חרש מיוחד שהוא בחיים אף כל שהוא בחיים, יצא המת שאינו בחיים: **ולפני עור לא תתן מכשל.** לפני הסומא בדבר לא תתן עצה שאינה הוגנת לו, אל תאמר מכור שדך וקח לך חמור, ואתה עוקף עליו ונוטלה המנו: **ויראת מאלהיך.** לפי שהדבר הזה אינו מסור לבריות לידע אם דעתו של זה לטובה או לרעה, ויכול להשמט ולומר לטובה נתכונתי, לפיכך נאמר בו ויראת מאלהיך המכיר מחשבותיך. וכן כל דבר המסור ללבו של אדם העושהו ואין שאר הבריות מכירות בו, נאמר בו ויראת מאלהיך:
@551 **לא תעשו עול במשפט.** מלמד שהדין המקלקל את הדין קרוי עול, שנאוי ומשקץ, חרם ותועבה. שהעול קרוי תועבה, שנאמר (דברים כה טז) כי תועבת ה' וגו' כל עשה עול, והתועבה קרויה שקץ וחרם, שנאמר (שם ז כו) ולא תביא תועבה אל ביתך והיית חרם כמוהו שקץ תשקצנו וגו' : **לא תשא פני דל.** שלא תאמר עני הוא זה והעשיר חיב לפרנסו, אזכנו בדין, ונמצא מתפרנס בנקיות: **ולא תהדר פני גדול.** שלא תאמר עשיר הוא זה בן גדולים הוא זה, היאך אבישנו ואראה בבשתו, עונש יש בדבר, לכך נאמר ולא תהדר פני גדול: **בצדק תשפט עמיתך.** כמשמעו. דבר אחר הוי דן את חברך לכף זכות:
@552 **לא תלך רכיל.** אני אומר על שם שכל משלחי מדנים ומספרי לשון הרע הולכים בבתי רעיהם לרגל מה יראו רע או מה ישמעו רע לספר בשוק, נקראים הולכי רכיל, הולכי רגילה אשפיימנ''ט בלע''ז [רגול] . וראיה לדברי, שלא מצינו רכילות שאין כתוב בלשון הליכה לא תלך רכיל, הולכי רכיל נחשת וברזל (ירמיה ו כח) , ושאר לשון הרע אין כתוב בו הליכה מלשני בסתר רעהו (תהלים קא ה) , לשון רמיה (שם קכ ב) , לשון מדברת גדולות (שם יב ד) , לכך אני אומר שלשון רכיל לשון הולך ומרגל, שהכ''ף נחלפת בגימ''ל, שכל האותיות שמוצאיהם ממקום אחד מתחלפות זו בזו, בי''ת בפ''א ובוי''ו, גימ''ל בכ''ף וקו''ף, נו''ן בלמ''ד, ורי''ש וז''ן בצד''י וכן (ש''ב יט כח) וירגל בעבדך, רגל במרמה לומר עלי רעה, וכן (תהלים טו ג) לא רגל על לשונו, וכן רוכל הסוחר ומרגל אחר כל סחורה, וכל המוכר בשמים להתקשט בהם הנשים, על שם שמחזר תמיד בעירות נקרא רוכל, לשון רוגל. ותרגומו לא תיכול קרצין, כמו (דניאל ג ח) ואכלו קרציהון די יהודיא, אכל ביה קרצא בי מלכא (ברכות נח א) . נראה בעיני שהיה משפטם לאכול בבית המקבל דבריהם שום הלעטה, והוא גמר חזוק, שדבריו מקימים ויעמידם על האמת, ואותה הלעטה נקראת אכילת קרצין, לשון קורץ בעיניו (משלי ו יג) , שכן דרך כל הולכי רכיל לקרוץ בעיניהם ולרמוז דברי רכילותן, שלא יבינו שאר השומעים: **לא תעמד על דם רעך.** לראות במיתתו ואתה יכול להצילו, כגון טובע בנהר, וחיה או לסטים באים עליו: **אני ה'.** נאמן לשלם שכר, ונאמן להפרע:
@553 **ולא תשא עליו חטא.** לא תלבין את פניו ברבים:
@554 **לא תקם.** אמר לו השאילני מגלך. אמר לו לאו. למחר אמר לו השאילני קרדמך. אמר לו איני משאילך כדרך שלא השאלתני, זו היא נקימה. ואיזו היא נטירה, אמר לו השאילני קרדמך. אמר לו לאו. למחר אמר לו השאילני מגלך. אמר לו הא לך ואיני כמותך, שלא השאלתני. זו היא נטירה, שנוטר האיבה בלבו אף על פי שאינו נוקם: **ואהבת לרעך כמוך.** אמר רבי עקיבא זה כלל גדול בתורה:
@555 **את חקתי תשמרו.** ואלו הן בהמתך לא תרביע כלאים וגו' , חקים אלו גזרות מלך שאין טעם לדבר: ובגד כלאים. למה נאמר, לפי שנאמר לא תלבש שעטנז צמר ופשתים יחדו (דבר' כב יא) , יכול לא ילבש גיזי צמר ואניצי פשתן, תלמוד לומר בגד. מנין לרבות הלבדים, תלמוד לומר שעטנז, דבר שהוא שוע טווי ונוז. ואומר אני נוז לשון דבר הנמלל ושזור זה עם זה לחברו, מישטי''ר בלע''ז [לערבב] , כמו (מועד קטן יב ב) חזיין לנאזי דאית בהון, שאנו מפרשין לשון כמוש פלישטר''א . ולשון שעטנז פרש מנחם, מחברת צמר ופשתים:
@556 **נחרפת לאיש.** מיועדת ומיוחדת לאיש, ואיני ידע לו דמיון במקרא. ובשפחה כנענית שחציה שפחה וחציה בת חורין המאורסת לעבד עברי שמתר בשפחה, הכתוב מדבר: **והפדה לא נפדתה.** פדויה ואינה פדויה וסתם פדיון בכסף: **או חפשה.** בשטר: **בקרת תהיה.** היא לוקה ולא הוא, יש על בית דין לבקר את הדבר שלא לחיבה (י''ג: לחיבו) מיתה: **כי לא חפשה.** ואין קדושיה קדושין גמורין. ורבותינו למדו מכאן שמי שהוא במלקות יהא בקריאה, שהדינים המלקין קורין על הלוקה (דברים כח נח, נט) אם לא תשמר לעשות וגו' והפלא ה' את מכותך וגו' : **כי לא חפשה.** לפיכך אין חיב עליה מיתה, שאין קדושיה קדושין, הא אם חפשה, קדושיה קדושין וחיב מיתה:
@558 **ונסלח לו מחטאתו אשר חטא.** לרבות את המזיד כשוגג:
@559 **וערלתם ערלתו.** ואטמתם אטימתו, יהא אטום ונסתם מליהנות ממנו: **שלש שנים יהיה לכם ערלים.** מאימתי מונה לו, משעת נטיעתו. יכול אם הצניעו, לאחר שלש שנים יהא מתר, תלמוד לומר יהיה, בהויתו יהא:
@560 **יהיה כל פריו קדש.** כמעשר שני שכתוב בו (ויקרא כז ל) וכל מעשר הארץ וגו' קדש לה'. מה מעשר שני אינו נאכל חוץ לחומת ירושלים אלא בפדיון, אף זה כן. ודבר זה הלולים לה' הוא, שנושאו שם לשבח ולהלל לשמים:
@561 **להוסיף לכם תבואתו.** המצוה הזאת שתשמרו תהיה להוסיף לכם תבואתו, שבשכרה אני מברך לכם פרות הנטיעות. היה רבי עקיבא אומר דברה תורה כנגד יצר הרע, שלא יאמר אדם הרי ארבע שנים אני מצטער בו חנם, לפיכך נאמר להוסיף לכם תבואתו: **אני ה'.** אני ה' המבטיח על כך ונאמן לשמור הבטחתי:
@562 **לא תאכלו על הדם.** להרבה פנים נדרש בסנהדרין (סג א) אזהרה שלא יאכל מבשר קדשים לפני זריקת דמים, ואזהרה לאוכל מבהמת חלין טרם שתצא נפשה, ועוד הרבה: **לא תנחשו.** כגון אלו המנחשין בחלדה ובעופות, פתו נפלה מפיו, צבי הפסיקו בדרך: **ולא תעוננו.** לשון עונות ושעות, שאומר יום פלוני יפה להתחיל מלאכה, שעה פלונית קשה לצאת:
@563 **לא תקפו פאת ראשכם.** זה המשוה צדעיו לאחורי אזנו ולפדחתו, ונמצא הקף ראשו עגל סביב, שעל אחורי אזניו עקרי שערו למעלה מצדעיו הרבה: **פאת זקנך.** סוף הזקן וגבוליו. והן חמש שתים בכל לחי ולחי למעלה אצל הראש שהוא רחב ויש בו שתי פאות, ואחת למטה בסנטרו מקום חבור שני הלחיים יחד:
@564 **ושרט לנפש.** כן דרכן של אמוריים להיות משרטין בשרם כשמת להם מת: **וכתבת קעקע.** כתב המחקה ושקוע שאינו נמחק לעולם שמקעקעו במחט והוא משחיר לעולם: **קעקע.** לשון (במד' כה ד) והוקע אותם, (שמואל ב כא ו) והוקענום. תוחבין עץ בארץ ותולין אותם עליהם ונמצאו מחקין ותחובין בקרקע, פורפויינ''ט בלע''ז [נעוץ] :
@565 **אל תחלל את בתך להזנותה.** במוסר בתו פנויה לביאה שלא לשם קדושין: **ולא תזנה הארץ.** אם אתה עושה כן הארץ מזנה את פירותיה לעשותן במקום אחר ולא בארצכם. וכן הוא אומר (ירמיה ג ג) וימנעו רבבים וגו' :
@566 **ומקדשי תיראו.** לא יכנס בהר הבית לא במקלו ולא במנעלו ובאפונדתו ובאבק שעל רגליו. ואף על פי שאני מזהירכם על המקדש, את שבתותי תשמרו אין בנין בית המקדש דוחה שבת:
@567 **אל תפנו אל האבת.** אזהרה לבעל אוב וידעוני. בעל אוב זה פיתום המדבר משחיו. וידעוני מכניס עצם חיה ששמה ידוע לתוך פיו והעצם מדבר: **אל תבקשו.** להיות עסוקים בם, שאם תעסקו בם אתם מטמאין לפני ואני מתעב אתכם: **אני ה' אלהיכם.** דעו את מי אתם מחליפין במי:
@568 **מפני שיבה תקום.** יכול זקן אשמאי, תלמוד לומר זקן, אין זקן אלא שקנה חכמה: **והדרת פני זקן.** איזהו הדור, לא ישב במקומו ולא ידבר במקומו ולא יסתור את דבריו. יכול יעצים עיניו כמי שלא ראהו, לכך נאמר ויראת מאלהיך, שהרי דבר זה מסור ללבו של עושהו, שאין מכיר בו אלא הוא, וכל דבר המסור ללב נאמר בו ויראת מאלהיך:
@569 **לא תונו.** אונאת דברים. לא תאמר לו אמש היית עובד עבודה זרה ועכשיו אתה בא ללמוד תורה שנתנה מפי הגבורה:
@570 **כי גרים הייתם.** מום שבך אל תאמר לחברך: **אני ה' אלהיכם.** אלהיך ואלהיו אני:
@571 **לא תעשו עול במשפט.** אם לדין, הרי כבר נאמר לא תעשו עול במשפט (פסוק טו) , ומהו משפט השנוי כאן, הוא המדה והמשקל והמשורה. מלמד שהמודד נקרא דין, שאם שקר במדה הרי הוא כמקלקל את הדין וקרוי עול, שנאוי, ומשקץ, חרם ותועבה. וגורם לחמשה דברים האמורים בדין מטמא את הארץ, ומחלל את השם, ומסלק את השכינה, ומפיל את ישראל בחרב, ומגלה אותם מארצם: **במדה.** זו מדת הארץ: **במשקל.** כמשמעו: **ובמשורה.** היא מדת הלח והיבש:
@572 **אבני צדק.** הם המשקולות ששוקלין כנגדן: **איפת.** היא מדת היבש: **הין.** זו היא מדת הלח: **אשר הוצאתי אתכם.** על מנת כן. דבר אחר אני הבחנתי במצרים בין טפה של בכור לטפה שאינה של בכור, ואני הנאמן להפרע ממי שטומן משקלותיו במלח להונות את הבריות שאין מכירים בהם:
@575 **ואל בני ישראל תאמר.** ענשין על האזהרות: **מות יומת.** בבית דין, ואם אין כח לבית דין עם הארץ מסיעין אותן: **עם הארץ.** עם שבגינו נבראת הארץ. דבר אחר עם שעתידין לירש את הארץ על ידי מצות הללו:
@576 **אתן את פני.** פנאי שלי, פונה אני מכל עסקי ועוסק בו: **באיש.** ולא בצבור, שאין כל הצבור נכרתין: **כי מזרעו נתן למלך.** לפי שנאמר מעביר בנו ובתו באש (דברים יח י) , בן בנו ובן בתו מנין, תלמוד לומר כי מזרעו נתן למלך. זרע פסול מנין, תלמוד לומר בתתו מזרעו למלך: **למען טמא את מקדשי.** את כנסת ישראל, שהיא מקדשת לי, כלשון (ויקרא כא כג) ולא יחלל את מקדשי:
@577 **ואם העלם יעלימו.** אם העלימו בדבר אחד, סוף שיעלימו בדברים הרבה. אם העלימו סנהדרי קטנה, סוף שיעלימו סנהדרי גדולה:
@578 **ובמשפחתו.** אמר ר' שמעון וכי משפחה מה חטאה, אלא ללמדך שאין לך משפחה שיש בה מוכס שאין כלם מוכסין, שכלם מחפין עליו: **והכרתי אתו.** למה נאמר, לפי שנאמר ובמשפחתו, יכול יהיו כל המשפחה בהכרת, תלמוד לומר אותו. אותו בהכרת ולא כל המשפחה בהכרת, אלא ביסורין: **לזנות אחרי המלך.** לרבות שאר עבודה זרה שעבדה בכך, ואפלו אין זו עבודתה:
@580 **והתקדשתם.** זו פרישות עבודה זרה:
@582 **אביו ואמו קלל.** לרבות לאחר מיתה: **דמיו בו.** זו סקילה, וכן כל מקום שנאמר דמיהם בם. ולמדנו מאוב וידעוני שנאמר בהם באבן ירגמו אותם דמיהם בם (פסוק כז) . ופשוטו של מקרא, כמו דמו בראשו (יהושע ב יט) , אין נענש על מיתתו אלא הוא, שהוא גרם לעצמו שיהרג:
@583 **ואיש.** פרט לקטן: **אשר ינאף את אשת איש.** פרט לאשת קטן, למדנו שאין לקטן קדושין. ועל איזו אשת איש חיבתי לך: **אשר ינאף את אשת רעהו.** פרט לאשת גוי, למדנו שאין קדושין לגוי: **מות יומת הנאף והנאפת.** כל מיתה האמורה בתורה סתם אינה אלא חנק:
@585 **תבל עשו.** גנאי. לשון אחר מבלבלין זרע האב בזרע הבן:
@586 **משכבי אשה.** מכניס כמכחול בשפופרת:
@587 **ישרפו אתו ואתהן.** אי אתה יכול לומר אשתו הראשונה ישרפו, שהרי נשאה בהתר ולא נאסרה עליו, אלא אשה ואמה הכתובין כאן, שתיהן לאסור, שנשא את חמותו ואמה. ויש מרבותינו שאומרים, אין כאן אלא חמותו. ומהו אתהן, את אחת מהן, ולשון יוני הוא הן אחת:
@588 **ואת הבהמה תהרגו.** אם אדם חטא בהמה מה חטאה, אלא מפני שבאה לאדם תקלה על ידה, לפיכך אמר הכתוב תסקל. קל וחמר לאדם שיודע להבחין בין טוב לרע וגורם רעה לחברו לעבור עברה. כיוצא בדבר אתה אומר (דברים יב ב) אבד תאבדון את כל המקומות, הרי דברים קל וחמר, מה אילנות שאינן רואין ואינן שומעין על שבאת תקלה על ידם אמרה תורה השחת, שרוף וכלה, המטה את חברו מדרך חיים לדרכי מיתה על אחת כמה וכמה:
@590 **חסד הוא.** לשון ארמי חרפה (בראשית לד יד) חסודא. ומדרשו אם תאמר קין נשא אחותו, חסד עשה המקום לבנות עולמו ממנו, שנאמר (תהלים פט ג) עולם חסד יבנה:
@591 **הערה.** גלה. וכן כל לשון ערוה גלוי הוא, והוי''ו יורדת בתבה לשם דבר, כמו זעוה, מגזרת (אסתר ה ט) ולא קם ולא זע, וכן אחוה מגזרת אח. והעראה זו נחלקו בה רבותינו, יש אומרים זו נשיקת שמש, ויש אומרים זו הכנסת עטרה:
@592 **וערות אחות אמך** וגו' **.** שנה הכתוב באזהרתן, לומר שהזהר עליהן בין על אחות אביו ואמו מן האב בין על אחיותיהן מן האם, אבל ערות אשת אחי אביו לא הזהר אלא על אשת אחי אביו מן האב:
@593 **אשר ישכב את דדתו.** המקרא הזה בא ללמד על כרת האמור למעלה, שהוא בענש הליכת ערירי: **ערירים.** כתרגומו בלא ולד, ודומה לו (בראשית טו ב) ואנכי הולך ערירי. יש לו בנים קוברן, אין לו בנים מת בלא בנים, לכך שנה בשני מקראות אלו ערירים ימותו ערירים יהיו. ערירים ימותו, אם יהיו לו בשעת עברה, לא יהיו לו כשימות לפי שקוברן בחייו. ערירים יהיו, שאם אין לו בשעת עברה, יהיה כל ימיו כמו שהוא עכשו:
@594 **נדה הוא.** השכיבה הזאת מנדה היא ומאוסה. ורבותינו דרשו לאסור העראה בה כנדה, שהעראה מפורשת בה (פסוק יח) את מקורה הערה (לעיל יח) :
@596 **ואקץ.** לשון מיאוס, כמו (בראשית כז מו) קצתי בחיי, כאדם שהוא קץ במזונו:
@598 **והבדלתם בין הבהמה הטהרה לטמאה.** אין צריך לומר בין פרה לחמור, שהרי מבדלין ונכרין הם, אלא בין טהורה לך לטמאה לך, בין שנשחט רבו של סימן לנשחט חציו. וכמה בין רבו לחציו, מלא שערה: **אשר הבדלתי לכם לטמא.** לאסור:
@599 **ואבדל אתכם מן העמים להיות לי.** אם אתם מבדלים מהם הרי אתם שלי, ואם לאו הרי אתם של נבוכדנצר וחבריו. רבי אלעזר בן עזריה אומר מנין שלא יאמר אדם נפשי קצה בבשר חזיר, אי אפשי ללבוש כלאים, אבל יאמר אפשי, ומה אעשה ואבי שבשמים גזר עלי, תלמוד לומר ואבדיל אתכם מן העמים להיות לי, שתהא הבדלתכם מהם לשמי, פורש מן העברה ומקבל עליו עול מלכות שמים:
@600 **כי יהיה בהם אוב** וגו' **.** כאן נאמר בהם מיתה ולמעלה כרת. עדים והתראה בסקילה, מזיד בלא התראה בהכרת ושגגתם חטאת, וכן בכל חיבי מיתות שנאמר בהם כרת:
@601 **אמר אל הכהנים.** אמר ואמרת, להזהיר גדולים על הקטנים: **בני אהרן.** יכול חללים, תלמוד לומר הכהנים: **בני אהרן.** אף בעלי מומין במשמע: **בני אהרן.** ולא בנות אהרן: **לא יטמא בעמיו.** בעוד שהמת בתוך עמיו, יצא מת מצוה:
@602 **כי אם לשארו.** אין שארו אלא אשתו:
@603 **הקרובה.** לרבות את הארוסה: **אשר לא היתה לאיש.** למשכב: **לה יטמא.** מצוה:
@604 **לא יטמא בעל בעמיו להחלו.** לא יטמא לאשתו פסולה שהוא מחלל בה בעודה עמו. וכן פשוטו של מקרא לא יטמא בעל בשארו בעוד שהוא בתוך עמיו, שיש לה קוברין, שאינה מת מצוה, ובאיזה שאר אמרתי, באותו שהוא להחלו, להתחלל הוא מכהנתו:
@605 **לא יקרחו קרחה.** על מת. והלא אף ישראל הזהרו על כך, אלא לפי שנאמר בישראל (דברים יד א) בין עיניכם, יכול לא יהא חיב על כל הראש, תלמוד לומר בראשם, וילמדו ישראל מהכהנים בגזרה שוה, נאמר כאן קרחה ונאמר להלן בישראל קרחה, מה כאן כל הראש אף להלן כל הראש במשמע, כל מקום שיקרח בראש. ומה להלן על מת, אף כאן על מת: **ופאת זקנם לא יגלחו.** לפי שנאמר בישראל (ויקרא יט כז) ולא תשחית, יכול לקטו במלקט וברהיטני יהא חיב, לכך נאמר לא יגלחו, שאינו חיב אלא על דבר הקרוי גלוח ויש בו השחתה, וזהו תער: **ובבשרם לא ישרטו שרטת.** לפי שנאמר בישראל (ויקרא שם כח) ושרט לנפש לא תתנו, יכול שרט חמש שריטות לא יהא חיב אלא אחת, תלמוד לומר לא ישרטו שרטת, לחייב על כל שריטה ושריטה. שתיבה זו יתרה היא לדרוש, שהיה לו לכתוב לא ישרטו ואני יודע שהיא שרטת:
@606 **קדשים יהיו.** על כרחם יקדישום בית דין בכך:
@607 **זנה.** שנבעלה בעילת ישראל האסור לה, כגון חיבי כרתות או נתין או ממזר: **חללה.** שנלדה מן הפסולים שבכהנה, כגון בת אלמנה מכהן גדול או בת גרושה וחלוצה מכהן הדיוט, וכן שנתחללה מן הכהנה על ידי ביאת אחד מן הפסולים לכהנה:
@608 **וקדשתו.** על כרחו, שאם לא רצה לגרש, הלקהו ויסרהו עד שיגרש: **קדש יהיה לך.** נהוג בו קדשה לפתוח ראשון בכל דבר ולברך ראשון בסעודה:
@609 **כי תחל לזנות.** כשתתחלל על ידי זנות, שהיתה בה זיקת בעל וזנתה או מן האירוסין או מן הנשואין. ורבותינו נחלקו בדבר, והכל מודים שלא דבר הכתוב בפנויה: **את אביה היא מחללת.** חללה ובזתה את כבודו, שאומרים עליו ארור שזו ילד, ארור שזו גדל:
@610 **לא יפרע.** לא יגדל פרע על אבל. ואיזהו גדול פרע, יותר משלשים יום:
@611 **ועל כל נפשת מת** וגו' **.** באהל המת: **נפשת מת.** להביא רביעית דם מן המת שמטמא באהל: **לאביו ולאמו לא יטמא.** לא בא אלא להתיר לו מת מצוה:
@612 **ומן המקדש לא יצא.** אינו הולך אחר המטה. ועוד מכאן למדו רבותינו שכהן גדול מקריב אונן, וכן משמעו, אף אם מתו אביו ואמו אינו צריך לצאת מן המקדש אלא עובד עבודה: **ולא יחלל את מקדש.** שאינו מחלל בכך את העבודה שהתיר לו הכתוב, הא כהן הדיוט שעבד אונן חלל:
@614 **וחללה.** שנלדה מפסולי כהנה:
@615 **ולא יחלל זרעו.** הא אם נשא אחת מן הפסולות, זרעו המנה חלל מדין קדשת כהנה:
@617 **לחם אלהיו.** מאכל אלהיו, כל סעודה קרויה לחם, כמו (דניאל ה א) עבד לחם רב:
@618 **כי כל איש אשר בו מום לא יקרב.** אינו דין שיקרב, כמו (מלאכי א ח) הקריבהו נא לפחתך: **חרם.** שחטמו שקוע בין שתי העינים, שכוחל שתי עיניו כאחת: **או שרוע.** שאחד מאיבריו גדול מחברו, עינו אחת גדולה ועינו אחת קטנה, או שוקו אחת ארכה מחברתה:
@620 **או גבן.** שורצילו''ש בלע''ז [בעל גבות ארוכות] שגביני עיניו שערן ארוך ושוכב: **או דק.** שיש לו בעיניו דוק שקורין טיל''א [קרום] , כמו (ישעיה מ כב) הנוטה כדוק: **או תבלל.** דבר המבלבל את העין, כגון חוט לבן הנמשך מן הלבן ופוסק בסירא, שהוא עוגל המקיף את השחור, שקוראים פרוניל''א [אישון] , והחוט הזה פוסק את העוגל ונכנס בשחור. ותרגום תבלל חליז, לשון חלזון, שהוא דומה לתולעת אותו החוט. וכן כנוהו חכמי ישראל במומי הבכור חלזון נחש עינב (בכורות לח א) : **גרב וילפת.** מיני שחין הם: גרב, זו החרס. שחין היבש מבפנים ומבחוץ: ילפת, היא חזזית המצרית. ולמה נקראת ילפת שמלפפת והולכת עד יום המיתה, והוא לח מבחוץ ויבש מבפנים. ובמקום אחר קורא לגרב שחין, הלח מבחוץ ויבש מבפנים, שנאמר (דברים כח כז) ובגרב ובחרס, כשסמוך גרב אצל חרס קורא לילפת גרב, וכשהוא סמוך אצל ילפת קורא לחרס גרב, כך מפורש בבכורות (מא א) : **מרוח אשך.** לפי התרגום מריס פחדין, שפחדיו מרססים, שביצים שלו כתותין. פחדין כמו (איוב מ יז) גידי פחדו ישורגו:
@621 **כל איש אשר בו מום.** לרבות שאר מומין: **מום בו.** בעוד מומו בו פסול, הא אם עבר מומו כשר: **לחם אלהיו.** כל מאכל קרוי לחם:
@622 **מקדשי הקדשים.** אלו קדשי הקדשים: **ומן הקדשים יאכל.** אלו קדשים קלים. ואם נאמרו קדשי הקדשים למה נאמרו קדשים קלים, אם לא נאמרו הייתי אומר בקדשי הקדשים יאכל בעל מום, שמצינו שהתרו לזר, שאכל משה בשר המלואים, אבל בחזה ושוק של קדשים קלים לא יאכל, שלא מצינו זר חולק בהן, לכך נאמרו קדשים קלים. כך מפורש בזבחים (קא:) :
@623 **אך אל הפרכת.** להזות שבע הזאות שעל הפרכת: **ואל המזבח.** החיצון. ושניהם הצרכו להכתב, ומפורש בתורת כהנים: **ולא יחלל את מקדשי.** שאם עבד, עבודתו מחללת להפסל:
@624 **וידבר משה.** המצוה הזאת: **אל אהרן ואל בניו ואל כל בני ישראל.** להזהיר בית דין על הכהנים:
@626 **וינזרו.** אין נזירה אלא פרישה, וכן הוא אומר (יחזקאל יד ז) וינזר מאחרי, (ישעיה א ד) נזורו אחור, יפרשו מן הקדשים בימי טמאתן. דבר אחר: וינזרו מקדשי בני ישראל אשר הם מקדישים לי ולא יחללו את שם קדשי. סרס המקרא ודרשהו, אשר הם מקדשים לי ולא יחללו את שם קדשי: **אשר הם מקדשים לי.** לרבות קדשי כהנים עצמן:
@627 **כל איש אשר יקרב.** אין קריבה זו אלא אכילה, וכן מצינו שנאמרה אזהרת אכילת קדשים בטמאה בלשון נגיעה בכל קדש לא תגע (ויקרא יב ד) , אזהרה לאוכל. ולמדוה רבותינו מגזרה שוה. ואי אפשר לומר שחיב על הנגיעה, שהרי נאמר כרת על האכילה בצו את אהרן (ויקרא ז כ. כא) שתי כריתות זו אצל זו, ואם על הנגיעה חיב לא הצרך לחיבו על האכילה, וכן נדרש בתורת כהנים וכי יש נוגע חיב, אם כן מה תלמוד לומר יקרב, משיכשר לקרב, שאין חיבין עליו משום טמאה, אלא אם כן קרבו מתיריו. ואם תאמר שלש כריתות בטמאת כהנים למה, כבר נדרשו במסכת שבועות אחת לכלל ואחת לפרט וכו' (שבועות ז א) : **וטמאתו עליו.** וטמאת האדם עליו, יכול בבשר הכתוב מדבר, וטמאתו של בשר עליו, ובטהור שאכל את הטמא הכתוב מדבר, הרי כבר נאמר (ויק' ז יט) והבשר אשר יגע בכל טמא לא יאכל, אלא על כרחך ממשמעו אתה למד, במי שטמאתו פורחת ממנו הכתוב מדבר, וזהו האדם שיש לו טהרה בטבילה: **ונכרתה** וגו' **.** יכול מצד זה לצד זה, יכרת ממקומו ויתישב במקום אחר, תלמוד לומר אני ה', בכל מקום אני:
@628 **מזרע אהרן.** אין לי אלא זרעו, גופו מנין, תלמוד לומר והוא צרוע, שיכול הואיל ומקריב אונן יקריב צרוע וזב, תלמוד לומר והוא: **עד אשר יטהר.** ביאת השמש, או אינו אלא טבילה, נאמר כאן וטהר, ונאמר למטה וטהר (פסוק ז) ובא השמש וטהר, מה להלן ביאת שמש, אף כאן ביאת שמש: **בכל טמא נפש.** במי שנטמא במת:
@629 **בכל שרץ אשר יטמא לו.** בשעור הראוי לטמא, בכעדשה: **או באדם.** במת: **אשר יטמא לו.** כשיעורו לטמא, וזהו כזית: **לכל טמאתו.** לרבות נוגע בזב וזבה, נדה ויולדת ובמצורע:
@630 **נפש אשר תגע בו.** באחד מן הטמאים הללו:
@631 **ואחר יאכל מן הקדשים.** נדרש ביבמות בתרומה, שמתר לאכלה בהערב השמש: **מן הקדשים.** ולא כל הקדשים:
@632 **נבלה וטרפה לא יאכל לטמאה בה.** לענין הטמאה הזהיר כאן, שאם אכל נבלת עוף טהור, שאין לה טמאת מגע ומשא אלא טמאת אכילה בבית הבליעה, אסור לאכול בקדשים. וצריך לומר וטרפה, מי שיש במינו טרפה, יצא נבלת עוף טמא שאין במינו טרפה:
@633 **ושמרו את משמרתי.** מלאכול תרומה בטמאת הגוף: **ומתו בו.** למדנו שהיא מיתה בידי שמים:
@634 **לא יאכל קדש.** בתרומה הכתוב מדבר, שכל הענין דבר בה: **תושב כהן ושכיר.** תושבו של כהן ושכירו, לפיכך תושב זה נקוד פתח, לפי שהוא דבוק. ואיזהו תושב, זה נרצע שהוא קנוי לו עד היובל, ואיזהו שכיר, זה קנוי קנין שנים, שיוצא בשש, בא הכתוב ולמדך כאן שאין גופו קנוי לאדוניו לאכול בתרומתו:
@635 **וכהן כי יקנה נפש.** עבד כנעני שקנוי לגופו: **ויליד ביתו.** אלו בני השפחות. ואשת כהן אוכלת בתרומה מן המקרא הזה, שאף היא קנין כספו. ועוד למד ממקרא אחר (במדבר יח יא) כל טהור בביתך וגו' בספרי:
@636 **לאיש זר.** ללוי ולישראל:
@637 **אלמנה וגרושה.** מן האיש הזר: **וזרע אין לה.** ממנו: **ושבה.** הא אם יש לה זרע ממנו אסורה בתרומה כל זמן שהזרע קים: **וכל זר לא יאכל בו.** לא בא אלא להוציא את האונן שמתר בתרומה. זרות אמרתי לך, ולא אנינות:
@638 **כי יאכל קדש.** תרומה: **ונתן לכהן את הקדש.** דבר הראוי להיות קדש, שאינו פורע לו מעות אלא פירות של חלין, והן נעשין תרומה:
@639 **ולא יחללו** וגו' **.** להאכילם לזרים:
@640 **והשיאו אותם.** את עצמם יטענו עון באכלם את קדשיהם, שהבדלו לשם תרומה וקדשו ונאסרו עליהם. ואנקלוס שתרגם במיכלהון בסואבא, שלא לצורך תרגמו כן: **והשיאו אותם.** זה אחד משלשה אתים שהיה רבי ישמעאל דורש בתורה שמדברים באדם עצמו, וכן (במ' ו יג) ביום מלאת ימי נזרו יביא אתו, הוא יביא את עצמו. וכן (דברים לד ו) ויקבור אתו בגיא, הוא קבר את עצמו, כך נדרש בספרי:
@642 **נדריהם.** הרי עלי: **נדבתם.** הרי זו:
@643 **לרצנכם.** הביאו דבר הראוי לרצות אתכם לפני, שיהא לכם לרצון אפיימני''ט בלע''ז . ואיזהו הראוי לרצון, **תמים זכר בבקר בכשבים ובעזים.** אבל בעולת העוף אין צריך תמות וזכרות, ואינו נפסל במום אלא בחסרון אבר:
@645 **לפלא נדר.** להפריש בדבורו:
@646 **עורת.** שם דבר של מום עורון בלשון נקבה, שלא יהא בו מום של עורת: **או שבור.** לא יהיה: **חרוץ.** ריס של עין שנסדק או שנפגם, וכן שפתו שנסדקה או נפגמה: **יבלת.** ורוא''ה בלע''ז : **גרב.** מין חזזית וכן ילפת. ולשון ילפת, כמו (שופטים טז כט) וילפת שמשון, שאחוזה בו עד יום מיתה, שאין לה רפואה: **לא תקריבו.** שלש פעמים, להזהיר על הקדשן ועל שחיטתן ועל זריקת דמן: **ואשה לא תתנו.** אזהרת הקטרתן:
@647 **שרוע.** אבר גדול מחברו: **וקלוט.** פרסותיו קלוטות: **נדבה תעשה אתו.** לבדק הבית: **ולנדר.** למזבח: **לא ירצה.** איזהו הקדש בא לרצות, הוי אומר זה הקדש המזבח:
@648 **ומעוך וכתות ונתוק וכרות.** בביצים או בגיד: **מעוך.** ביציו מעוכין ביד: **כתות.** כתושים יותר ממעוך: **נתוק.** תלושין ביד עד שנפסקו חוטים שתלויים בהן, אבל נתונים הם בתוך הכיס, והכיס לא נתלש: **וכרות.** כרותין בכלי ועודן בכיס: **ומעוך.** תרגומו ודמריס, זה לשונו בארמית, לשון כתישה: **וכתות.** תרגומו ודרסיס, כמו (עמוס ו יא) הבית הגדול רסיסים, בקיעות דקות, וכן (שבת פ ב) קנה המרסס: **ובארצכם לא תעשו.** דבר זה, לסרס שום בהמה וחיה ואפלו טמאה, לכך נאמר בארצכם, לרבות כל אשר בארצכם, שאי אפשר לומר לא נצטוו על הסרוס אלא בארץ, שהרי סרוס חובת הגוף הוא, וכל חובת הגוף נוהגת בין בארץ בין בחוצה לארץ:
@649 **ומיד בן נכר.** נכרי שהביא קרבן ביד כהן להקריבו לשמים לא תקריבו לו בעל מום. ואף על פי שלא נאסרו בעלי מומין לקרבן בני נח אלא אם כן מחסרי אבר, זאת נוהגת בבמה שבשדות, אבל על המזבח שבמשכן לא תקריבוה, אבל תמימה תקבלו מהם, לכך נאמר למעלה איש איש (לעיל פסוק יח) , לרבות את הנכרים שנודרים נדרים ונדבות כישראל: **משחתם.** חבולהון: **לא ירצו לכם.** לכפר עליכם:
@651 **כי יולד.** פרט ליוצא דופן:
@652 **אתו ואת בנו.** נוהג בנקבה, שאסור לשחוט האם והבן או הבת, ואינו נוהג בזכרים, ומתר לשחוט האב והבן או האב והבת: **אתו ואת בנו.** אף בנו ואותו במשמע:
@653 **לרצנכם תזבחו.** תחלת זביחתכם הזהרו שתהא לרצון לכם. ומהו הרצון, ביום ההוא יאכל. לא בא להזהיר אלא שתהא שחיטה על מנת כן, אל תשחטוהו על מנת לאכלו למחר, שאם תחשבו בו מחשבת פסול לא יהא לכם לרצון. דבר אחר לרצונכם, לדעתכם, מכאן למתעסק שפסול בשחיטת קדשים. ואף על פי שפרט בנאכלים לשני ימים, חזר ופרט בנאכלין ליום אחד שתהא זביחתן על מנת לאכלן בזמנן:
@654 **ביום ההוא יאכל.** לא בא להזהיר אלא שתהא שחיטה על מנת כן, שאם לקבוע לו זמן אכילה, כבר כתוב (ויקרא ז טו) ובשר זבח תודת שלמיו וגו' : **אני ה'.** דע מי גזר על הדבר ואל יקל בעיניך:
@655 **ושמרתם.** זו המשנה: **ועשיתם.** זה המעשה:
@656 **ולא תחללו.** לעבור על דברי מזידין. ממשמע שנאמר ולא תחללו, מה תלמוד לומר ונקדשתי, מסור עצמך וקדש שמי. יכול ביחיד, תלמוד לומר בתוך בני ישראל, וכשהוא מוסר עצמו, ימסור עצמו על מנת למות, שכל המוסר עצמו על מנת הנס, אין עושין לו נס, שכן מצינו בחנניה מישאל ועזריה שלא מסרו עצמן על מנת הנס, שנאמר (דניאל ג יח) והן לא, ידיע להוא לך מלכא די לאלהך לא איתנא פלחין וגו' , מציל ולא מציל, ידיע להוא לך וגו' :
@657 **המוציא אתכם.** על מנת כן: **אני ה'.** נאמן לשלם שכר:
@659 **דבר אל בני ישראל** וגו' **מועדי ה'.** עשה מועדות שיהיו ישראל מלמדין בהם, שמעברים את השנה על גליות שנעקרו ממקומם לעלות לרגל ועדין לא הגיעו לירושלים:
@660 **ששת ימים.** מה ענין שבת אצל מועדות, ללמדך שכל המחלל את המועדות מעלין עליו כאלו חלל את השבתות. וכל המקים את המועדות, מעלין עליו כאלו קים את השבתות:
@661 **אלה מועדי ה'.** למעלה מדבר בעבור שנה, וכאן מדבר בקדוש החדש:
@662 **בין הערבים.** משש שעות ולמעלה: **פסח לה'.** הקרבת קרבן ששמו פסח:
@665 **והקרבתם אשה** וגו' **.** הם המוספין האמורים בפרשת פנחס ולמה נאמרו כאן, לומר לך שאין המוספין מעכבין זה את זה: **והקרבתם אשה לה'.** מכל מקום, אם אין פרים הבא אילים, ואם אין פרים ואילים, הבא כבשים: **שבעת ימים.** כל מקום שנאמר שבעת שם דבר הוא, שבוע של ימים, שטיינ''א בלע''ז [קבוצה של שבעה ימים רצופים] , וכן כל לשון שמונת, ששת, חמשת, שלשת: **מלאכת עבדה.** אפלו מלאכות החשובות לכם עבודה וצורך, שיש חסרון כיס בבטלה שלהן, כגון דבר האבד. כך הבנתי מתורת כהנים, דקתני יכול אף חלו של מועד יהא אסור במלאכת עבודה וכו' :
@667 **ראשית קצירכם.** שתהא ראשונה לקציר: **עמר.** עשירית האיפה, כך היתה שמה, כמו (שמות טז יח) וימדו בעמר:
@668 **והניף.** כל תנופה מוליך ומביא, מעלה ומוריד. מוליך ומביא לעצור רוחות רעות, מעלה ומוריד לעצור טללים רעים: **לרצנכם.** אם תקריבו כמשפט זה, יהיו לרצון לכם: **ממחרת השבת.** ממחרת יום טוב הראשון של פסח, שאם אתה אומר שבת בראשית, אי אתה יודע איזהו:
@669 **ועשיתם:. כבש.** חובה לעמר הוא בא:
@670 **ומנחתו.** מנחת נסכיו: **שני עשרנים.** כפולה היתה: **ונסכה יין רביעית ההין.** אף על פי שמנחתו כפולה, אין נסכיו כפולים:
@671 **וקלי.** קמח עשוי מכרמל רך שמיבשין אותו בתנור: **וכרמל.** הן קליות שקורין גרניד''ש [שבלים] : **בכל משבתיכם.** נחלקו בו חכמי ישראל, יש שלמדו מכאן שהחדש נוהג בחוצה לארץ, ויש אומרים לא בא אלא ללמד שלא נצטוו על החדש אלא לאחר ירשה וישיבה, משכבשו וחלקו:
@672 **ממחרת השבת.** ממחרת יום טוב: **תמימת תהיינה.** מלמד שמתחיל ומונה מבערב, שאם לא כן אינן תמימות:
@673 **השבת השביעת.** כתרגומו שבועתא שביעתא: **עד ממחרת השבת השביעת תספרו.** ולא עד בכלל, והן ארבעים ותשעה יום: **חמשים יום והקרבתם מנחה חדשה לה'.** ביום החמשים תקריבוה. ואומר אני זהו מדרשו, אבל פשוטו עד ממחרת השבת השביעית, שהוא יום חמשים, תספרו. ומקרא מסורס הוא: **מנחה חדשה.** היא המנחה הראשונה שהובאה מן החדש. ואם תאמר, הרי קרבה מנחת העומר, אינה כשאר כל המנחות, שהיא באה מן השעורים:
@674 **ממושבתיכם.** ולא מחוצה לארץ: **לחם תנופה.** לחם תרומה המורם לשם גבוה, וזו היא המנחה החדשה האמורה למעלה: **בכורים.** ראשונה לכל המנחות, אף למנחת קנאות הבאה מן השעורים, לא תקרב מן החדש קודם לשתי הלחם:
@675 **על הלחם.** בגלל הלחם, חובה ללחם: **ומנחתם ונסכיהם.** כמשפט מנחה ונסכים המפורשים בכל בהמה בפרשת נסכים (במדבר טו ד. י) שלשה עשרונים לפר ושני עשרונים לאיל ועשרון לכבש, זו היא המנחה. והנסכים חצי ההין לפר ושלישית ההין לאיל ורביעית ההין לכבש:
@676 **ועשיתם שעיר עזים.** יכול שבעת הכבשים והשעיר האמורים כאן הם שבעת הכבשים והשעיר האמורים בחומש הפקודים, כשאתה מגיע אצל פרים ואילים אינן הם, אמור מעתה אלו לעצמן ואלו לעצמן, אלו קרבו בגלל הלחם ואלו למוספין:
@677 **והניף הכהן אתם תנופה.** מלמד שטעונין תנופה מחיים, יכול כלם, תלמוד לומר על שני כבשים: **קדש יהיו.** לפי ששלמי יחיד קדשים קלים, הזקק לומר בשלמי צבור שהם קדשי קדשים:
@679 **ובקצרכם.** חזר ושנה לעבור עליהם בשני לאוין. אמר רבי אבדימי ברבי יוסף מה ראה הכתוב לתנה באמצע הרגלים, פסח ועצרת מכאן וראש השנה ויום הכפורים והחג מכאן, ללמדך שכל הנותן לקט שכחה ופאה לעני כראוי, מעלין עליו כאלו בנה בית המקדש והקריב קרבנותיו בתוכו: **תעזב.** הנח לפניהם והם ילקטו, ואין לך לסיע לאחד מהם: **אני ה' אלהיכם.** נאמן לשלם שכר:
@681 **זכרון תרועה.** זכרון פסוקי זכרונות ופסוקי שופרות, לזכור לכם עקידת יצחק שקרב תחתיו איל:
@682 **והקרבתם אשה.** המוספים האמורים בחומש הפקודים:
@684 **אך.** כל אכין ורקין שבתורה מיעוטין, מכפר הוא לשבים ואינו מכפר על שאינם שבים:
@687 **והאבדתי.** לפי שהוא אומר כרת בכל מקום ואיני יודע מה הוא, כשהוא אומר והאבדתי, למד על הכרת שאינו אלא אבדן:
@688 **כל מלאכה** וגו' **.** לעבור עליו בלאוין הרבה, או להזהיר על מלאכת לילה כמלאכת יום:
@692 **מקרא קדש.** קדשהו בכסות נקיה ובתפלה, ובשאר ימים טובים במאכל ובמשתה ובכסות נקיה ובתפלה:
@693 **עצרת הוא.** עצרתי אתכם אצלי כמלך שזמן את בניו לסעודה לכך וכך ימים, כיון שהגיע זמנן להפטר אמר בני בבקשה מכם, עכבו עמי עוד יום אחד, קשה עלי פרידתכם: **כל מלאכת עבדה.** אפלו מלאכה שהיא עבודה לכם, שאם לא תעשוה יש חסרון כיס בדבר: **לא תעשו.** יכול אף חלו של מועד יהא אסור במלאכת עבודה, תלמוד לומר היא:
@694 **עלה ומנחה.** מנחת נסכים הקרבה עם העולה: **דבר יום ביומו.** חק הקצוב בחומש הפקודים: **דבר יום ביומו.** הא אם עבר יומו בטל קרבנו:
@696 **אך בחמשה עשר יום:. תחגו.** קרבן שלמים לחגיגה. יכול תדחה את השבת, תלמוד לומר אך, הואיל ויש לה תשלומין כל שבעה: **באספכם את תבואת הארץ.** שיהא חדש שביעי זה בא בזמן אסיפה, מכאן שנצטוו לעבר את השנים, שאם אין העבור, פעמים שהוא בא באמצע הקיץ או החורף: **תחגו.** שלמי חגיגה: **שבעת ימים.** אם לא הביא בזה יביא בזה. יכול יהא מביאן כל שבעה, תלמוד לומר וחגתם אתו, יום אחד במשמע, ולא יותר. ולמה נאמר שבעה, לתשלומין:
@697 **פרי עץ הדר.** עץ שטעם עצו ופריו שוה: **הדר.** הדר באילנו משנה לשנה, וזהו אתרוג: **כפת תמרים.** חסר וי''ו, למד שאינה אלא אחת: **וענף עץ עבת.** שענפיו קלועים כעבותות וכחבלים, וזהו הדס העשוי כמין קליעה:
@699 **האזרח.** זה אזרח: **בישראל.** לרבות את הגרים:
@700 **כי בסכות הושבתי.** ענני כבוד:
@703 **צו את בני ישראל.** זו פרשת מצות הנרות. ופרשת ואתה תצוה לא נאמרה אלא על סדר מלאכת המשכן לפרש צורך המנורה. וכן משמע, ואתה סופך לצוות את בני ישראל על כך: **שמן זית זך.** שלשה שמנים יוצאים מן הזית, הראשון קרוי זך, והן מפורשים במנחות (פט א) ובתורת כהנים: **תמיד.** מלילה ללילה, כמו עולת תמיד שאינה אלא מיום ליום:
@704 **לפרכת העדת.** שלפני הארון, שהוא קרוי עדות. ורבותינו דרשו על נר מערבי, שהוא עדות לכל באי עולם שהשכינה שורה בישראל, שנותן בה שמן כמדת חברותיה וממנה היה מתחיל ובה היה מסים: **יערך אתו אהרן מערב עד בקר.** יערוך אותו עריכה הראויה למדת כל הלילה, ושערו חכמים חצי לוג לכל נר ונר, והן כדאי אף ללילי תקופת טבת, ומדה זו הקבעה להם:
@705 **המנרה הטהרה.** שהיא זהב טהור. דבר אחר על טהרה של מנורה, שמטהרה ומדשנה תחלה מן האפר:
@707 **שש המערכת.** שש חלות המערכה האחת: **השלחן הטהר.** של זהב טהור. דבר אחר על טהרו של שלחן, שלא יהיו הסניפין מגביהין את הלחם מעל גבי השלחן:
@708 **ונתת על המערכת.** על כל אחת משתי המערכות היו שני בזכי לבונה, מלא קומץ לכל אחת: **והיתה.** הלבונה הזאת: **ללחם לאזכרה.** שאין מן הלחם לגבוה כלום, אלא הלבונה נקטרת כשמסלקין אותו בכל שבת ושבת. והיא לזכרון ללחם, שעל ידה הוא נזכר למעלה, כקומץ שהוא אזכרה למנחה:
@710 **והיתה.** המנחה הזאת, שכל דבר הבא מן התבואה בכלל מנחה הוא: **ואכלהו.** מוסב על הלחם, שהוא לשון זכר:
@711 **ויצא בן אשה ישראלית.** מהיכן יצא, רבי לוי אומר מעולמו יצא. רבי ברכיה אומר מפרשה שלמעלה יצא. לגלג ואמר ביום השבת יערכנו, דרך המלך לאכול פת חמה בכל יום, או שמא פת צוננת של תשעה ימים, בתמיהה. ומתניתא אמרה מבית דינו של משה יצא מחיב. בא לטע אהלו בתוך מחנה דן, אמרו לו מה טיבך לכאן, אמר להם מבני דן אני. אמרו לו (במדבר ב) איש על דגלו באתת לבית אבותם כתיב. נכנס לבית דינו של משה ויצא מחיב, עמד וגדף: **בן איש מצרי.** הוא המצרי שהרגו משה: **בתוך בני ישראל.** מלמד שנתגיר: **וינצו במחנה.** על עסקי המחנה: **ואיש הישראלי.** זה שכנגדו, שמחה בו מטע אהלו:
@712 **ויקב.** כתרגומו ופרש, שנקב שם המיוחד וגדף, והוא שם המפורש ששמע מסיני: **ושם אמו שלמית בת דברי.** שבחן של ישראל שפרסמה הכתוב לזו, לומר, שהיא לבדה היתה זונה: **שלמית.** דהות פטפטה שלם עלך, שלם עלך, שלם עליכון, מפטפטת בדברים שואלת בשלום הכל: **בת דברי.** דברנית היתה מדברת עם כל אדם, לפיכך קלקלה: **למטה דן.** מגיד שהרשע גורם גנאי לו גנאי לאביו גנאי לשבטו, כיוצא בו (שמות לא ו) אהליאב בן אחיסמך למטה דן, שבח לו שבח לאביו שבח לשבטו:
@713 **ויניחהו.** לבדו, ולא הניחו מקושש עמו, ששניהם היו בפרק אחד. ויודעים היו שהמקושש במיתה, שנאמר (שמות לא יד) מחלליה מות יומת אבל לא פרש להם באיזו מיתה, לכך נאמר (במדבר טו לד) כי לא פרש מה יעשה לו. אבל במקלל הוא אומר לפרוש להם, שלא היו יודעים אם חיב מיתה אם לאו:
@715 **השמעים.** אלו העדים: **כל.** להביא את הדינים: **את ידיהם.** אומרים לו דמך בראשך ואין אנו נענשים במיתתך שאתה גרמת לך: **כל העדה.** במעמד כל העדה. מכאן ששלוחו שלאדם כמותו:
@716 **ונשא חטאו.** בכרת, כשאין התראה:
@717 **ונקב שם.** אינו חיב עד שיפרש את השם, ולא המקלל בכנוי: **ונקב.** לשון קללה, כמו (במדבר כג ח) מה אקב:
@718 **ואיש כי יכה.** לפי שנאמר (שמות כא יב) מכה איש ומת, אין לי אלא שהרג את האיש, אשה וקטן מנין, תלמוד לומר כל נפש אדם:
@721 **כן ינתן בו.** פרשו רבותינו, שאינו נתינת מום ממש אלא תשלומי ממון, שמין אותו כעבד, לכך כתוב בו לשון נתינה, דבר הנתון מיד ליד:
@722 **ומכה בהמה ישלמנה.** למעלה דבר בהורג בהמה, וכאן דבר בעושה בה חבורה: **ומכה אדם יומת.** אפלו לא הרגו אלא עשה בו חבורה, שלא נאמר כאן נפש ובמכה אביו ואמו דבר הכתוב, ובא להקישו למכה בהמה מה מכה בהמה מחיים, אף מכה אביו ואמו מחיים, פרט למכה לאחר מיתה, לפי שמצינו שהמקללו לאחר מיתה חיב, הצרך לומר במכה שפטור. ומה בבהמה בחבלה, שאם אין חבלה אין תשלומין, אף מכה אביו ואמו אינו חיב עד שיעשה בהם חבורה:
@723 **אני ה' אלהיכם.** אלהי כלכם, כשם שאני מיחד שמי עליכם כך אני מיחד שמי על הגרים:
@724 **ובני ישראל עשו.** כל המצוה האמורה בסקילה במקום אחר דחיה, רגימה ותליה:
@725 **בהר סיני.** מה ענין שמטה אצל הר סיני, והלא כל המצות נאמרו מסיני, אלא מה שמטה נאמרו כללותיה ופרטותיה ודקדוקיה מסיני, אף כלן נאמרו כללותיהן ודקדוקיהן מסיני, כך שנויה בתורת כהנים. ונראה לי שכך פרושה לפי שלא מצינו שמטת קרקעות שנשנית בערבות מואב במשנה תורה, למדנו שכללותיה ופרטותיה כלן נאמרו מסיני, ובא הכתוב ולמד כאן על כל דבור שנדבר למשה שמסיני היו כלם כללותיהן ודקדוקיהן, וחזרו ונשנו בערבות מואב:
@726 **שבת לה'.** לשם ה', כשם שנאמר בשבת בראשית:
@728 **יהיה לארץ.** לשדות ולכרמים: **לא תזמר.** שקוצצין זמורותיה. ותרגומו לא תכסח, ודומה לו (ישעיה לג יב) קוצים כסוחים, (תהלים פ יז) שרפה באש כסוחה:
@729 **את ספיח קצירך.** אפלו לא זרעתה והיא צמחה מן הזרע שנפל בה בעת הקציר, הוא קרוי ספיח: **לא תקצור.** להיות מחזיק בו כשאר קציר, אלא הפקר יהיה לכל: **נזירך.** שהנזרת והפרשת בני אדם מהם ולא הפקרתם: **לא תבצר.** אותם אינך בוצר, אלא מן המפקר:
@730 **והיתה שבת הארץ** וגו' **.** אף על פי שאסרתים עליך, לא באכילה ולא בהנאה אסרתים, אלא שלא תנהוג בהם כבעל הבית, אלא הכל יהיו שוים בה, אתה ושכירך ותושבך: **שבת הארץ לכם לאכלה.** מן השבות אתה אוכל, ואי אתה אוכל מן השמור: **לך ולעבדך ולאמתך.** לפי שנאמר (שמות כג יא) ואכלו אביוני עמך, יכול יהיו אסורים באכילה לעשירים, תלמוד לומר לך ולעבדך ולאמתך, הרי בעלים ועבדים ושפחות אמורים כאן: **ולשכירך ולתושבך.** אף הגוים:
@731 **ולבהמתך ולחיה.** אם חיה אוכלת בהמה לא כל שכן, שמזונותיה עליך, מה תלמוד לומר ולבהמתך, מקיש בהמה לחיה, כל זמן שחיה אוכלת מן השדה האכל לבהמתך מן הבית, כלה לחיה מן השדה כלה לבהמתך מן הבית:
@732 **שבתת שנים.** שמטות שנים. יכול יעשה שבע שנים רצופות שמטה ויעשה יובל אחריהם, תלמוד לומר שבע שנים שבע פעמים, הוי אומר כל שמטה ושמטה בזמנה: **והיו לך ימי שבע** וגו' **.** מגיד לך שאף על פי שלא עשית שמטות עשה יובל לסוף ארבעים ותשע שנה. ופשוטו של מקרא יעלה לך חשבון שנות השמטות למספר ארבעים ותשע:
@733 **והעברת.** לשון (שמות לו ו) ויעבירו קול במחנה, לשון הכרזה: **ביום הכפורים.** ממשמע שנאמר ביום הכפורים איני יודע שהוא בעשור לחדש, אם כן למה נאמר בעשור לחדש, אלא לומר לך תקיעת עשור לחדש דוחה שבת בכל ארצכם, ואין תקיעת ראש השנה דוחה שבת בכל ארצכם, אלא בבית דין בלבד:
@734 **וקדשתם.** בכניסתה מקדשין אותה בבית דין ואומרים מקדשת השנה: **וקראתם דרור.** לעבדים, בין נרצע, בין שלא כלו לו שש שנים משנמכר. אמר ר' יהודה מהו לשון דרור, כמדייר בי דירא ומסחר בכל מדינה וכו' , שדר בכל מקום שהוא רוצה ואינו ברשות אחרים: **יובל הוא.** שנה זאת מבדלת משאר שנים בנקיבת שם לה לבדה. ומה שמה, יובל שמה, על שם תקיעת שופר: **ושבתם איש אל אחזתו.** שהשדות חוזרות לבעליהן: **ואיש אל משפחתו תשבו.** לרבות את הנרצע:
@735 **יובל הוא שנת החמשים שנה.** מה תלמוד לומר, לפי שנאמר וקדשתם וגו' , כדאיתא בראש השנה (ח ב) ובתורת כהנים: **את נזריה.** את הענבים המשמרים. אבל בוצר אתה מן המפקרים, כשם שנאמר בשביעית כך נאמר ביובל, נמצאו שתי שנים קדושות סמוכות זו לזו, שנת ארבעים ותשע שמטה ושנת החמשים יובל:
@736 **קדש תהיה לכם.** תופסת דמיה כהקדש. יכול תצא היא לחלין, תלמוד לומר תהיה, בהויתה תהא: **מן השדה תאכלו.** על ידי השדה אתה אוכל מן הבית, שאם כלה לחיה מן השדה אתה צריך לבער מן הבית, כשם שנאמר בשביעית כך נאמר ביובל:
@737 **תשבו איש אל אחזתו.** והרי כבר נאמר (פסוק י) ושבתם איש אל אחזתו, אלא לרבות המוכר שדהו ועמד בנו וגאלה שחוזרת לאביו ביובל:
@738 **וכי תמכרו** וגו' **.** לפי פשוטו כמשמעו. ועוד יש דרשה מנין כשאתה מוכר, מכור לישראל חברך, תלמוד לומר וכי תמכרו ממכר לעמיתך מכור, ומנין שאם באת לקנות קנה מישראל חברך, תלמוד לומר או קנה מיד עמיתך: **אל תונו.** זו אונאת ממון:
@739 **במספר שנים אחר היובל תקנה.** זהו פשוטו לישב מקרא על אפניו על האונאה בא להזהיר, כשתמכור או תקנה קרקע דע כמה שנים יש עד היובל. ולפי השנים ותבואות השדה שהיא ראויה לעשות ימכור המוכר ויקנה הקונה, שהרי סופו להחזירה לו בשנת היובל. ואם יש שנים מועטות וזה מוכרה בדמים יקרים הרי נתאנה לוקח, ואם יש שנים מרבות ואכל ממנה תבואות הרבה ולקחה בדמים מועטים הרי נתאנה מוכר, לפיכך צריך לקנותה לפי הזמן. וזהו שנאמר במספר שני תבואות ימכר לך, לפי מנין שני התבואות שתהא עומדת ביד הלוקח תמכור לו. ורבותינו דרשו מכאן, שהמוכר שדהו אינו רשאי לגאול פחות משתי שנים, שתעמוד שתי שנים ביד הלוקח מיום ליום, ואפלו יש שלש תבואות באותן שתי שנים, כגון שמכרה לו בקמותיה. ו''שני'' אינו יוצא מפשוטו, כלומר מספר שנים של תבואות, ולא של שדפון, ומעוט שנים שנים:
@740 **תרבה מקנתו.** תמכרנה ביקר: **תמעיט מקנתו.** תמעיט בדמיה:
@741 **ולא תונו איש את עמיתו.** כאן הזהיר על אונאת דברים, שלא יקניט איש את חברו לא ישיאנו עצה שאינה הוגנת לו לפי דרכו והנאתו של יועץ. ואם תאמר, מי יודע אם נתכונתי לרעה, לכך נאמר ויראת מאלהיך, היודע מחשבות הוא יודע. כל דבר המסור ללב, שאין מכיר אלא מי שהמחשבה בלבו, נאמר בו ויראת מאלהיך:
@742 **וישבתם על הארץ לבטח.** שבעון שמטה ישראל גולים, שנאמר (ויקרא כו לד) אז תרצה הארץ את שבתתיה והרצת את שבתתיה, ושבעים שנה שלגלות בבל, כנגד שבעים שמטות שבטלו, היו:
@743 **ונתנה הארץ** וגו' **וישבתם לבטח עליה.** שלא תדאגו משנת בצורת: **ואכלתם לשבע.** אף בתוך המעים תהא בו ברכה:
@744 **ולא נאסף.** אל הבית: **את תבואתנו.** כגון יין ופרות האילן וספיחין הבאים מאליהם:
@745 **לשלש השנים.** למקצת הששית מניסן ועד ראש השנה, ולשביעית ולשמינית, שיזרעו בשמינית במרחשון ויקצרו בניסן:
@746 **עד השנה התשיעת.** עד חג הסכות של תשיעית, שהיא עת בא תבואתה של שמינית לתוך הבית, שכל ימות הקיץ היו בשדה בגרנות, ובתשרי הוא עת האסיף לבית. ופעמים שהיתה צריכה לעשות לארבע שנים, בששית שלפני השמטה השביעית, שהן בטלין מעבודת קרקע שתי שנים רצופות השביעית והיובל, ומקרא זה נאמר בשאר השמטות כלן:
@747 **והארץ לא תמכר.** לתן לאו על חזרת שדות לבעלים ביובל, שלא יהא הלוקח כובשה: **לצמתת.** לפסיקה, למכירה פסוקה עולמית: **כי לי הארץ.** אל תרע עינך בה שאינה שלך:
@748 **ובכל ארץ אחזתכם.** לרבות בתים ועבד עברי, ודבר זה מפורש בקדושין בפרק ראשון (דף כא א) . ולפי פשוטו סמוך לפרשה שלאחריו, שהמוכר אחזתו רשאי לגאלה לאחר שתי שנים או הוא או קרובו, ואין הלוקח יכול לעכב:
@749 **כי ימוך אחיך ומכר.** מלמד שאין אדם רשאי למכור שדהו אלא מחמת דחק עוני: **מאחזתו.** ולא כלה, למד דרך ארץ שישיר שדה לעצמו: **וגאל את ממכר אחיו.** ואין הלוקח יכול לעכב:
@750 **ואיש כי לא יהיה לו גאל.** וכי יש לך אדם בישראל שאין לו גואלים, אלא גואל שיוכל לגאול ממכרו:
@751 **וחשב את שני ממכרו.** כמה שנים היו עד היובל, כך וכך. ובכמה מכרתיה לך בכך וכך. עתיד היית להחזירה ביובל, נמצאת קונה מספר התבואות כפי חשבון של כל שנה. אכלת אותה שלש שנים או ארבע הוצא את דמיהן מן החשבון וטול את השאר, וזהו והשיב את העדף. בדמי המקח על האכילה שאכלה, ויתנם ללוקח: **לאיש אשר מכר לו.** המוכר הזה שבא לגאלה:
@752 **די השיב לו.** מכאן שאינו גואל לחצאין: **עד שנת היובל.** שלא יכנס לתוך אותה שנה כלום, שהיובל משמט בתחלתו:
@753 **בית מושב עיר חומה.** בית בתוך עיר המקפת חומה מימות יהושע בן נון: **והיתה גאלתו.** לפי שנאמר בשדה שיכול לגאלה משתי שנים ואלך כל זמן שירצה ובתוך שתי שנים הראשונים אינו יכול לגאלה, הצרך לפרש בזה שהוא חלוף, שאם רצה לגאול בשנה ראשונה גואלה, ולאחר מכאן אינו גואלה: **והיתה גאלתו.** של בית: **ימים.** ימי שנה שלמה קרויים ימים, וכן (בראשית כד נה) תשב הנערה אתנו ימים:
@754 **וקם הבית** וגו' **לצמיתת.** יצא מכחו של מוכר ועומד בכחו של קונה: **אשר לא חמה.** לו קרינן, אמרו רבותינו זכרונם לברכה אף על פי שאין לו עכשיו, הואיל והיתה לו קודם לכן. ועיר נקבה היא והצרך לכתוב לה, אלא מתוך שצריך לכתוב לא בפנים, תקנו לו במסרת, זה נופל על זה: **לא יצא ביבל.** אמר רב ספרא אם פגע בו יובל בתוך שנתו לא יצא:
@755 **ובתי החצרים.** כתרגומו פצחין, עירות פתוחות מאין חומה. ויש הרבה בספר יהושע (יהושע יג כח) הערים וחצריהם, (בראשית כה טז) בחצריהם ובטירותם: **על שדה הארץ יחשב.** הרי הן כשדות הנגאלים עד היובל ויוצאין ביובל לבעלים אם לא נגאלו: **גאלה תהיה לו.** מיד אם ירצה. ובזה יפה כחו מכח שדות, שהשדות אין נגאלות עד שתי שנים: **וביבל יצא.** בחנם:
@756 **וערי הלוים.** ארבעים ושמנה עיר שנתנו להם: **גאלת עולם.** גואל מיד אפלו לפני שתי שנים, אם מכרו שדה משדותיהם הנתונות להם באלפים אמה סביבות הערים, או אם מכרו בית בעיר חומה, גואלין לעולם, ואינו חלוט לסוף שנה:
@757 **ואשר יגאל מן הלוים.** ואם יקנה בית או עיר מהם: **ויצא ביבל.** אותו ממכר של בית או של עיר וישוב ללוי שמכרו, ולא יהיה חלוט כשאר בתי ערי חומה של ישראל. וגאלה זו לשון מכירה. דבר אחר לפי שנאמר (פסוק לב) , גאלת עולם תהיה ללוים, יכול לא דבר הכתוב אלא בלוקח ישראל שקנה בית בערי הלוים, אבל לוי שקנה מלוי יהיה חלוט, תלמוד לומר ואשר יגאל מן הלוים, אף [לוי] הגואל מיד לוי גואל גאלת עולם: **ויצא ממכר בית.** הרי זו מצוה אחרת, ואם לא גאלה יוצאה ביובל, ואינו נחלט לסוף שנה כבית של ישראל: **כי בתי ערי הלוים הוא אחזתם.** לא היה להם נחלת שדות וכרמים אלא ערים לשבת ומגרשיהם, לפיכך הם להם במקום שדות, ויש להם גאלה כשדות, כדי שלא תפקע נחלתם מהם:
@758 **ושדה מגרש עריהם לא ימכר.** מכר גזבר, שאם הקדיש בן לוי את שדהו ולא גאלה ומכרה גזבר, אינה יוצאה לכהנים ביובל, כמו שנאמר בישראל (ויק' כז) ואם מכר את השדה לאיש אחר לא יגאל עוד, אבל בן לוי גואל לעולם:
@759 **והחזקת בו.** אל תניחהו שירד ויפול ויהיה קשה להקימו, אלא חזקהו משעת מוטת היד. למה זה דומה, למשאוי שעל החמור, עודהו על החמור אחד תופס בו ומעמידו, נפל לארץ, חמשה אין מעמידין אותו: **גר ותושב.** אף אם הוא גר או תושב, ואיזהו תושב, כל שקבל עליו שלא לעבוד עבודה זרה, ואוכל נבלות:
@760 **נשך ותרבית.** חד שוינהו רבנן, ולעבור עליו בשני לאוין: **ויראת מאלהיך.** לפי שדעתו של אדם נמשכת אחר הרבית וקשה לפרוש המנו ומורה לעצמו התר בשביל מעותיו שהיו בטלות אצלו, הצרך לומר ויראת מאלהיך. או התולה מעותיו בנכרי, כדי להלוותם לישראל ברבית, הרי זה דבר המסור ללבו של אדם ומחשבתו, לכך הצרך לומר ויראת מאלהיך:
@762 **אשר הוצאתי** וגו' **.** והבחנתי בין בכור לשאינו בכור, אף אני יודע ונפרע מן המלוה מעות לישראל ברבית ואומר של נכרי הם. דבר אחר אשר הוצאתי אתכם מארץ מצרים על מנת שתקבלו עליכם מצותי אפלו הן כבדות עליכם: **לתת לכם את ארץ כנען.** בשכר שתקבלו מצותי: **להיות לכם לאלהים.** שכל הדר בארץ ישראל אני לו לאלהים, וכל היוצא ממנה כעובד עבודה זרה:
@763 **עבדת עבד.** עבודה של גנאי, שיהא נכר בה כעבד, שלא יוליך כליו אחריו לבית המרחץ ולא ינעול לו מנעליו:
@764 **כשכיר כתושב.** עבודת קרקע ומלאכת אמנות כשאר שכירים התנהג בו: **עד שנת היבל.** אם פגע בו יובל לפני שש שנים, היובל מוציאו:
@765 **הוא ובניו עמו.** אמר רבי שמעון אם הוא נמכר בניו מי מכרן, אלא מכאן שרבו חיב במזונות בניו: **ואל אחזת אבתיו.** אל כבוד אבותיו, ואין לזלזלו בכך: **אחזת.** חזקת:
@766 **כי עבדי הם.** שטרי קודם: **לא ימכרו ממכרת עבד.** בהכרזה כאן יש עבד למכור, ולא יעמידנו על אבן הלקח:
@767 **לא תרדה בו בפרך.** מלאכה שלא לצורך, כדי לענותו. אל תאמר לו החם לי את הכוס הזה, והוא אינו צריך, עדור תחת הגפן עד שאבא. שמא תאמר אין מכיר בדבר אם לצורך אם לאו, ואומר אני לו שהוא לצורך, הרי הדבר הזה מסור ללב, לכך נאמר ויראת:
@768 **ועבדך ואמתך אשר יהיו לך.** אם תאמר אם כן במה אשתמש. בעבדי איני מושל, באמות איני נוחל, שהרי הזהרתני (דברים כ טז) לא תחיה כל נשמה, אלא מי ישמשני: **מאת הגוים.** הם יהיו לך לעבדים: **אשר סביבתיכם.** ולא שבתוך גבול ארצכם, שהרי בהם אמרתי לא תחיה כל נשמה:
@769 **וגם מבני התושבים.** שבאו מסביבותיכם לשא נשים בארצכם וילדו להם, הבן הולך אחר האב, ואינו בכלל לא תחיה, אלא אתה מתר לקנותו כעבד: **מהם תקנו.** אותם תקנו:
@770 **והתנחלתם אתם לבניכם.** החזיקו בהם לנחלה לצורך בניכם אחריכם. ולא יתכן לפרש הנחילום לבניכם, שאם כן היה לו לכתוב והנחלתם אותם לבניכם. והתנחלתם, כמו והתחזקתם: **איש באחיו.** להביא נשיא בעמיו ומלך במשרתיו שלא לרדות בפרך:
@771 **יד גר ותושב.** גר והוא תושב, כתרגומו ערל תותב, וסופו מוכיח ונמכר לגר תושב: **וכי תשיג יד גר ותושב עמך.** מי גרם לו שיעשיר, דבוקו עמך: **ומך אחיך עמו.** מי גרם לו שימוך, דבוקו עמו, על ידי שלמד ממעשיו: **משפחת גר.** זהו הגוי. כשהוא אומר לעקר זה הנמכר לעבודה זרה עצמה להיות לה שמש, ולא לאלהות, אלא לחטוב עצים ולשאוב מים:
@772 **גאלה תהיה לו.** מיד, אל תניחהו שיטמע: **עד שנת היובל.** שהרי כל עצמו לא קנאו אלא לעבדו עד היובל, שהרי ביובל יצא, כמו שנאמר למטה (פסוק נד) ויצא בשנת היובל. ובגוי שתחת ידך הכתוב מדבר ואף על פי כן לא תבא עליו בעקיפין, מפני חלול השם, אלא כשבא לגאל ידקדק בחשבון לפי המגיע בכל שנה ושנה ינכה לו הגוי מן דמיו, אם היו עשרים שנה משנמכר עד היובל וקנאו בעשרים מנה, נמצא שקנה הגוי עבודת שנה במנה, ואם שהה זה אצלו חמש שנים ובא לגאל, ינכה לו חמשה מנים ויתן לו העבד חמש עשרה מנים, וזהו: **והיה כסף ממכרו במספר שנים' כימי שכיר יהיה עמו.** חשבון המגיע לכל שנה ושנה יחשב כאלו נשכר עמו כל שנה במנה וינכה לו:
@775 **אם עוד רבות בשנים.** עד היובל: **לפיהן.** הכל כמו שפרשתי:
@777 **לא ירדנו בפרך לעיניך.** כלומר ואתה רואה:
@778 **ואם לא יגאל באלה.** באלה הוא נגאל, ואינו נגאל בשש: **הוא ובניו עמו.** הנכרי חיב במזונות בניו כישראל:
@779 **כי לי בני ישראל עבדים.** שטרי קודם: **אני ה' אלהיכם.** כל המשעבדן מלמטה כאלו משעבדן מלמעלה:
@780 **לא תעשו לכם אלילם.** כנגד זה הנמכר לגוי, שלא יאמר הואיל ורבי מגלה עריות אף אני כמותו, הואיל ורבי עובד עבודה זרה אף אני כמותו, הואיל ורבי מחלל שבת אף אני כמותו, לכך נאמרו מקראות הללו. ואף הפרשיות הללו נאמרו על הסדר, בתחלה הזהיר על השביעית, ואם חמד ממון ונחשד על השביעית סופו למכור מטלטליו, לכך סמך לה וכי תמכרו ממכר (ויק' כה יד) , מה כתיב ביה או קנה מיד עמיתך (שם) , דבר הנקנה מיד ליד. לא חזר בו, סוף מוכר אחזתו. לא חזר בו, סוף מוכר את ביתו. לא חזר בו, סוף לוה ברבית. כל אלו האחרונות קשות מן הראשונות. לא חזר בו, סוף מוכר את עצמו. לא חזר בו, לא דיו לישראל אלא אפלו לגוי: **ואבן משכית.** לשון כסוי, כמו (שמות לג כב) ושכתי כפי, שמכסין הקרקע ברצפת אבנים: **להשתחות עליה.** אפלו לשמים, לפי שהשתחואה בפשוט ידים ורגלים היא, ואסרה תורה לעשות כן חוץ מן המקדש:
@781 **אני ה'.** נאמן לשלם שכר:
@782 **אם בחקתי תלכו.** יכול זה קיום המצות, כשהוא אומר ואת מצותי תשמרו, הרי קיום המצות אמור, הא מה אני מקים אם בחקתי תלכו, שתהיו עמלים בתורה: **ואת מצותי תשמרו.** הוו עמלים בתורה על מנת לשמור ולקים, כמו שנאמר (דברים ה א) ולמדתם אתם ושמרתם לעשותם:
@783 **בעתם.** בשעה שאין דרך בני אדם לצאת, כגון בלילי שבתות ובלילי רביעיות: **ועץ השדה.** הן אילני סרק, ועתידין לעשות פרות:
@784 **והשיג לכם דיש את בציר.** שיהא הדיש מרבה ואתם עסוקים בו עד הבציר, ובבציר תעסקו עד שעת הזרע: **ואכלתם לחמכם לשבע.** אוכל קמעא והוא מתברך במעיו:
@785 **ונתתי שלום.** שמא תאמרו הרי מאכל והרי משתה, אם אין שלום אין כלום, תלמוד לומר אחר כל זאת ונתתי שלום בארץ, מכאן שהשלום שקול כנגד הכל. וכן הוא אומר עושה שלום ובורא את הכל: **וחרב לא תעבר בארצכם.** אין צריך לומר שלא יבאו למלחמה, אלא אפלו לעבור דרך ארצכם ממדינה למדינה:
@786 **לפניכם לחרב.** איש בחרב רעהו:
@787 **ורדפו מכם.** מן החלשים שבכם, ולא מן הגבורים שבכם: **חמשה מאה ומאה מכם רבבה.** וכי כך הוא החשבון, והלא לא היה צריך לומר אלא מאה מכם שני אלפים ירדפו, אלא אינו דומה מועטין העושין את התורה למרבין העושין את התורה: **ונפלו איביכם** וגו' **.** שיהיו נופלין לפניכם שלא כדרך הארץ:
@788 **ופניתי אליכם.** אפנה מכל עסקי לשלם שכרכם, משל למה הדבר דומה, למלך ששכר פועלים וכו' , כדאיתא בתורת כהנים: **והפריתי אתכם.** בפריה ורביה: **והרביתי אתכם.** בקומה זקופה: **והקימתי את בריתי אתכם.** ברית חדשה, לא כברית הראשונה שהפרתם אותה, אלא ברית חדשה שלא תופר, שנאמר (ירמיה לא ל) וכרתי את בית ישראל ואת בית יהודה ברית חדשה לא כברית הראשונה:
@789 **ואכלתם ישן נושן.** הפרות יהיו משתמרין וטובים להתיישן, שיהא ישן הנושן של שלש שנים יפה לאכול משל אשתקד: **וישן מפני חדש תוציאו.** שיהיו הגרנות מלאות חדש והאוצרות מלאות ישן, וצריכים אתם לפנות האוצרות למקום אחר לתת החדש לתוכן:
@790 **ונתתי משכני.** זה בית המקדש: **ולא תגעל נפשי.** אין רוחי קצה בכם. כל געילה לשון פליטת דבר הבלוע בדבר אחר, כמו (שמואל ב' א כא) כי שם נגעל מגן גבורים, לא קבל המשיחה שמושחין מגן של עור בחלב מבשל, כדי להחליק מעליו מכת חץ או חנית, שלא יקוב העור:
@791 **והתהלכתי בתוככם.** אטייל עמכם בגן עדן כאחד מכם, ולא תהיו מזדעזעים ממני. יכול לא תיראו ממני, תלמוד לומר והייתי לכם לאלהים:
@792 **אני ה' אלהיכם.** כדאי אני שתאמינו בי שאני יכול לעשות כל אלה, שהרי הוצאתי אתכם מארץ מצרים ועשיתי לכם נסים גדולים: **מטת.** כמין יתד [התחובה] בשני ראשי העול המעכבים המוסרה שלא תצא מראש השור ויתיר הקשר, כמו (ירמיה כז ב) עשה לך מוסרות ומוטות קוניונגל''א בלע''ז [רצועת העול] : **קוממיות.** בקומה זקופה:
@793 **ואם לא תשמעו לי.** להיות עמלים בתורה, לדעת מדרש חכמים. יכול לקיום המצות, כשהוא אומר ולא תעשו וגו' , הרי קיום מצות אמור, הא מה אני מקים ואם לא תשמעו לי, להיות עמלים בתורה. ומה תלמוד לומר לי, אין לי אלא זה המכיר את רבונו ומתכון למרוד בו, וכן בנמרוד (בראשית י ט) גבור ציד לפני ה', שמכירו ומתכון למרוד בו, וכן באנשי סדום (שם יג יג) רעים וחטאים לה' מאד, מכירים את רבונם ומתכונים למרוד בו: **ולא תעשו.** משלא תלמדו לא תעשו הרי שתי עברות:
@794 **ואם בחקתי תמאסו.** מואס באחרים העושים: **משפטי תגעל נפשכם.** שונא החכמים: **לבלתי עשות.** מונע את אחרים מעשות: **את כל מצותי.** כופר [במצוות] שלא צויתים, לכך נאמר את כל מצותי, ולא נאמר את כל המצות: **להפרכם את בריתי.** כופר בעיקר הרי שבע עברות, הראשונה גוררת השניה, וכן עד השביעית ואלו הן: לא למד, ולא עשה, מאס באחרים העושים, שונא את החכמים, מונע את האחרים, כופר במצות, כופר בעיקר:
@795 **והפקדתי עליכם.** וצויתי עליכם: **שחפת.** חולי שמשחף את הבשר, אנפולי''ש בלע''ז [בועות] , דומה לנפוח שהוקלה נפיחתו ומראית פניו זעופה: **קדחת.** חולי שמקדיח את הגוף ומחממו ומבעירו, כמו (דברים לב כב) כי אש קדחה באפי: **מכלות עינים ומדיבת נפש.** העינים צופות וכלות לראות שיקל וירפא, וסוף שלא ירפא, וידאבו הנפשות של משפחתו במותו. כל תאוה שאינה באה ותוחלת ממשכה קרויה כליון עינים: **וזרעתם לריק.** תזרעו ולא תצמח, ואם תצמח ואכלוהו אויביכם:
@796 **ונתתי פני.** פנאי שלי, פונה אני מכל עסקי להרע לכם: **ורדו בכם שנאיכם.** כמשמעו ישלטו בכם: אגדת תורת כהנים מפרשה זו, **אף אני אעשה זאת.** איני מדבר אלא באף, וכן והלכתי אף אני עמכם בקרי (פסוק כד) : **והפקדתי עליכם.** שיהיו המכות פוקדות אתכם מזו לזו, עד שהראשונה פקודה אצלכם אביא אחרת ואסמכנה לה: **בהלה.** מכה המבהלת את הבריות, ואיזו, זו מכת מותן: **את השחפת.** יש לך אדם שהוא חולה ומטל במטה אבל בשרו שמור עליו, תלמוד לומר שחפת, שהוא נשחף. או עתים שהוא נשחף אבל נוח ואינו מקדיח, תלמוד לומר ואת הקדחת, מלמד שהוא מקדיח. או עתים שהוא מקדיח אבל סבור הוא בעצמו שיחיה, תלמוד לומר מכלות עינים. או הוא אינו סבור בעצמו שיחיה אבל אחרים סבורים שיחיה, תלמוד לומר ומדיבות נפש: **וזרעתם לריק זרעכם.** זורעה ואינה מצמחת, ומעתה מה אויביכם באים ואוכלים, ומה תלמוד לומר ואכלוהו אויביכם, הא כיצד, זורעה שנה ראשונה ואינה מצמחת, שנה שניה מצמחת ואויבים באים ומוצאים תבואה לימי המצור, ושבפנים מתים ברעב, שלא לקטו תבואה אשתקד. דבר אחר וזרעתם לריק זרעכם, כנגד הבנים והבנות הכתוב מדבר, שאתה עמל בהם ומגדלן, והחטא בא ומכלה אותם, שנאמר (איכה ב כב) אשר טפחתי ורביתי אויבי כלם: **ונתתי פני בכם.** כמו שנאמר בטובה ופניתי אליכם, כך נאמר ברעה ונתתי פני. משלו משל, למלך שאמר לעבדו פונה אני מכל עסקי ועוסק אני עמכם [לרעה] : **ונגפתם לפני איביכם.** שיהא המות הורג אתכם מבפנים ובעלי דבביכון מקיפין אתכם מבחוץ: **ורדו בכם שנאיכם.** שאיני מעמיד שונאים אלא מכם ובכם, שבשעה שאמות העולם עומדים על ישראל אינם מבקשים אלא מה שבגלוי, שנאמר (שופטים ו ג. ד) והיה אם זרע ישראל ועלה מדין ועמלק ובני קדם וגו' ויחנו עליהם וישחיתו את יבול הארץ, אבל בשעה שאעמיד עליכם מכם ובכם, הם מחפשים אחר המטמוניות שלכם, וכן הוא אומר (מיכה ג ג) ואשר אכלו שאר עמי ועורם מעליהם הפשיטו וגו' : **ונסתם.** מפני אימה: **ואין רדף אתכם.** מבלי כח:
@797 **ואם עד אלה.** ואם בעוד אלה המכות עמכם לא תשמעו: **ויספתי.** עוד יסורין אחרים: **שבע על חטאתיכם.** שבע פרעניות על שבע העברות האמורות למעלה:
@798 **ושברתי את גאון עזכם.** זה בית המקדש, וכן הוא אומר (יחזקאל כד כא) הנני מחלל את מקדשי גאון עזכם: **ונתתי את שמיכם כברזל ואת ארצכם כנחשה.** זו קשה משל משה, ששם הוא אומר (דברים כח כג) והיו שמיך אשר על ראשך נחשת וגו' , שיהיו השמים מזיעין כדרך שהנחשת מזיעה והארץ אינה מזיעה כדרך שאין הברזל מזיע והיא משמרת פירותיה, אבל כאן השמים לא יהיו מזיעין כדרך שאין הברזל מזיע ויהא חורב בעולם והארץ תהא מזיעה כדרך שהנחשת מזיעה והיא מאבדת פירותיה:
@799 **ותם לריק כחכם.** הרי אדם שלא עמל שלא חרש שלא זרע שלא נכש שלא כסח שלא עדר ובשעת הקציר בא שדפון ומלקה אותו, אין בכך כלום, אבל אדם שעמל וחרש וזרע ונכש וכסח ועדר ובא שדפון ומלקה אתו, הרי שניו של זה קהות: **ולא תתן ארצכם את יבולה.** אף מה שאתה מוביל לה בשעת הזרע: **ועץ הארץ.** אפלו מן הארץ יהא לקוי, שלא יחניט פירותיו בשעת החנטה: **לא יתן.** משמש למעלה ולמטה אעץ ואפרי: **לא יתן פריו.** כשהוא מפרה משיר פירותיו, הרי שתי קללות, ויש כאן שבע פרעניות:
@800 **ואם תלכו עמי קרי.** רבותינו אמרו עראי, במקרה, שאינו אלא לפרקים, כן תלכו עראי במצות. ומנחם פרש לשון מניעה, וכן (משלי כה יז) הקר רגלך, וכן יקר רוח (משלי יז כז) , וקרוב לשון זה לתרגומו של אנקלוס לשון קושי, שמקשים לבם להמנע מהתקרב אלי: **שבע כחטאתיכם.** שבע פרעניות אחרים במספר שבע כחטאתיכם:
@801 **והשלחתי.** לשון גרוי: **ושכלה אתכם.** אין לי אלא חיה משכלת שדרכה בכך, בהמה שאין דרכה בכך מנין, תלמוד לומר (דברים לב כד) ושן בהמות אשלח בם, הרי שתים. ומנין שתהא ממיתה בנשיכתה, תלמוד לומר (שם) עם חמת זחלי עפר. מה אלו נושכין וממיתין, אף אלו נושכין וממיתין. כבר היו שנים בארץ ישראל חמור נושך וממית, ערוד נושך וממית: **ושכלה אתכם.** אלו הקטנים: **והכריתה את בהמתכם.** מבחוץ: **והמעיטה אתכם.** מבפנים: **ונשמו דרכיכם.** שבילים גדולים ושבילים קטנים, הרי שבע פרעניות, שן בהמה, ושן חיה, חמת זחלי עפר, ושכלה, והכריתה, והמעיטה, ונשמו:
@802 **לא תוסרו לי.** לשוב אלי:
@804 **נקם ברית.** ויש נקם שאינו בברית כדרך שאר נקמות, וזהו סמוי עיניו של צדקיהו. דבר אחר נקם ברית נקמת בריתי אשר עברתם. כל הבאת חרב שבמקרא היא מלחמת חילות אויבים: **ונאספתם.** מן החוץ אל תוך הערים מפני המצור: **ושלחתי דבר בתוככם.** ועל ידי הדבר ונתתם ביד האויבים הצרים עליכם, לפי שאין מלינים את המת בירושלים, וכשהם מוציאים את המת לקברו, נתנים ביד אויב:
@805 **מטה לחם.** לשון משען, כמו (ירמיה מח יז) מטה עז: **בשברי לכם מטה לחם.** אשבור לכם כל מסעד אוכל, והם חצי רעב: **ואפו עשר נשים לחמכם בתנור אחד.** מחוסר עצים: **והשיבו לחמכם במשקל.** שתהא התבואה נרקבת ונעשית פת נפולה ומשתברת בתנור, והן יושבות ושוקלות את השברים לחלקם ביניהם: **ואכלתם ולא תשבעו.** זו מארה בתוך המעים. הרי שבע פרעניות חרב, מצור, דבר, שבר מטה לחם, חוסר עצים, פת נפולה, מארה במעים. ונתתם (פסוק כה) אינה מן המנין, שהיא החרב:
@809 **במתיכם.** מגדלים ובירניות: **חמניכם.** מין עבודה זרה שמעמידין על הגגות. ועל שם שמעמידין בחמה קרויין חמנים: **ונתתי את פגריכם.** תפוחי רעב היו, ומוציאים יראתם מחיקם ומנשקים אותם, וכרסו נבקעת ונופל עליה: **וגעלה נפשי אתכם.** זה סלוק שכינה:
@810 **ונתתי את עריכם חרבה.** יכול מאדם, כשהוא אומר והשמותי אני את הארץ (פסוק לב) הרי אדם אמור, הא מה אני מקים חרבה מעובר ושב: **והשמותי את מקדשיכם.** יכול מן הקרבנות, כשהוא אומר ולא אריח הרי קרבנות אמורים, הא מה אני מקים והשמותי את מקדשיכם, מן הגדודיות, שירות של ישראל שהיו מתקדשות ונועדות לבא שם. הרי שבע פרעניות אכילת בשר בנים ובנות, והשמדת במות, הרי שתים. כריתת חמנים אין כאן פרענות אלא על ידי השמדת הבירניות יפלו החמנים שבראשי הגגות ויכרתו. ונתתי את פגריכם וגו' הרי שלש. סלוק שכינה ארבע. חרבן ערים, שממון מקדש מן הגדודיות, ולא אריח קרבנות, הרי שבע:
@811 **והשמתי אני את הארץ.** זו מדה טובה לישראל שלא ימצאו האויבים נחת רוח בארצם, שתהא שוממה מיושביה:
@812 **ואתכם אזרה בגוים.** זו מדה קשה, שבשעה שבני מדינה גולים למקום אחד רואים זה את זה ומתנחמין, וישראל נזרו כבמזרה, כאדם הזורה שעורים בנפה ואין אחת מהן דבוקה בחברתה: **והריקתי.** כששולף החרב מתרוקן הנדן. ומדרשו חרב הנשמטת אחריכם אינה חוזרת מהר, כאדם שמריק את המים ואין סופן לחזור: **והיתה ארצכם שממה.** שלא תמהרו לשוב לתוכה ומתוך כך עריכם יהיו חרבה, נראות לכם חרבות שבשעה שאדם גולה מביתו ומכרמו ומעירו וסופו לחזור כאלו אין כרמו וביתו חרבים, כך שנויה בתורת כהנים:
@813 **אז תרצה.** תפייס את כעס המקום שכעס על שמטותיה: **והרצת.** למלך את שבתותיה:
@814 **כל ימי השמה.** לשון העשות ומ''ם דגש במקום כפל שממה: **את אשר לא שבתה.** שבעים שנה של גלות בבל הן היו כנגד שבעים שנות השמטה ויובל שהיו בשנים שהכעיסו ישראל בארצם לפני המקום ארבע מאות ושלשים שנה. שלש מאות ותשעים היו שני עונם משנכנסו לארץ עד שגלו עשרת השבטים, ובני יהודה הכעיסו לפניו ארבעים שנה משגלו עשרת השבטים עד חרבות ירושלים, הוא שנאמר ביחזקאל (יחזקאל ד ד. ו) ואתה שכב על צדך השמאלי וגו' וכלית את אלה ושכבת על צדך הימני שנית ונשאת את עון בית יהודה ארבעים יום. ונבואה זו נאמרה ליחזקאל בשנה החמישית לגלות המלך יהויכין. ועוד עשו שש שנים עד גלות צדקיהו, הרי ארבעים ושש. ואם תאמר, שנות מנשה חמשים וחמש היו, מנשה עשה תשובה שלשים ושלש שנה וכל שנות רשעו עשרים ושתים שנה, דכתיב ויעש אשרה כאשר עשה אחאב (מלכים ב' כא ג) ואחאב מלך עשרים ושתים שנה, כמו שאמרו באגדת חלק (סנהדרין קג א) ושל אמון שתים, ואחת עשרה ליהויקים, וכנגדן לצדקיהו. צא וחשוב לארבע מאות ושלשים ושש שנה שמטין ויובלות שבהם, והם שש עשרה למאה, ארבע עשרה שמיטין ושני יובלות, הרי לארבע מאות שנה ששים וארבע. לשלשים ושש שנה חמש שמטות, הרי שבעים חסר אחת, ועוד שנה יתרה שנכנסה בשמטה המשלמת לשבעים. ועליהם נגזר שבעים שנה שלמים. וכן הוא אומר בדברי הימים (דה''ב לו כא) עד רצתה הארץ את שבתותיה למלאת שבעים שנה:
@815 **והבאתי מרך.** פחד ורך לבב. מ''ם של מרך יסוד נופל הוא, כמו מ''ם של מועד ושל מוקש: **ונסו מנסת חרב.** כאלו רודפים הורגים אותם: **עלה נדף.** שהרוח דוחפו ומכהו על עלה אחר ומקשקש ומוציא קול, וכן תרגומו קל טרפא דשקיף, לשון חבטה, שדופות קדים (בראשית מא ו) שקיפן קדום, לשון משקוף, מקום חבטת הדלת, וכן תרגומו של חבורה (שמות כא כה) משקופי:
@816 **וכשלו איש באחיו.** כשירוצו לנוס, יכשלו זה בזה, כי יבהלו לרוץ: **כמפני חרב.** כאלו בורחים מלפני הורגים, שיהא בלבבם פחד וכל שעה סבורים שאדם רודפם. ומדרשו וכשלו איש באחיו, זה נכשל בעונו של זה, שכל ישראל ערבין זה לזה:
@817 **ואבדתם בגוים.** כשתהיו פזורים תהיו אבודים זה מזה: **ואכלה אתכם.** אלו המתים בגולה:
@818 **בעונת אבתם אתם.** כשאוחזים מעשה אבותיהם בידיהם: **ימקו.** לשון המסה, כמו ימסו, וכמו (זכריה יד יב) תמקנה בחוריהן, (תהלי' לח ו) נמקו חבורתי:
@820 **והבאתי אתם.** אני בעצמי אביאם, זו מדה טובה לישראל, שלא יהיו אומרים, הואיל וגלינו בין האמות נעשה כמעשיהם, אני איני מניחם, אלא מעמיד אני את נביאי ומחזירן לתחת כנפי, שנאמר (יחזקאל כ לב. לג) והעולה על רוחכם היו לא תהיה וגו' חי אני וגו' אם לא ביד חזקה וגו' : **או אז יכנע.** כמו (שמות כא לו) או נודע כי שור נגח הוא, אם אז יכנע. לשון אחר אולי שמא אז יכנע לבבם וגו' : **ואז ירצו את עונם.** יכפרו על עונם ביסוריהם:
@821 **וזכרתי את בריתי יעקוב.** בחמשה מקומות נכתב מלא, ואליהו חסר בחמשה מקומות, יעקב נטל אות משמו של אליהו ערבון שיבא ויבשר גאלת בניו: **וזכרתי את בריתי יעקוב.** למה נמנו אבות אחורנית, לומר כדאי הוא יעקב הקטן לכך, ואם אינו כדאי הרי יצחק עמו, ואם אינו כדאי, הרי אברהם עמו, שהוא כדאי. ולמה לא נאמרה זכירה ביצחק, אלא אפרו של יצחק נראה לפני צבור ומנח על המזבח:
@822 **יען וביען.** גמול ובגמול אשר במשפטי מאסו:
@823 **ואף גם זאת.** ואף אפלו אני עושה עמהם זאת הפרענות אשר אמרתי בהיותם בארץ אויביהם, לא אמאסם לכלותם ולהפר בריתי אשר אתם:
@824 **ברית ראשנים.** של שבטים:
@825 **והתורת.** אחת בכתב ואחת בעל פה, מגיד שכלם נתנו למשה בסיני:
@827 **כי יפלא.** יפריש בפיו: **בערכך נפשת.** לתן ערך נפשו לומר ערך דבר שנפשו תלויה בו עלי:
@828 **והיה ערכך** וגו' **.** אין ערך זה לשון דמים, אלא בין שהוא יקר בין שהוא זול, כפי שניו הוא הערך הקצוב עליו בפרשה זו: **ערכך.** כמו ערך. וכפל הכפי''ן לא ידעתי מאיזה לשון הוא:
@830 **ואם מבן חמש שנים.** לא שיהא הנודר קטן, שאין בדברי קטן כלום, אלא גדול שאמר ערך קטן זה, שהוא בן חמש שנים, עלי:
@832 **ואם מבן ששים שנה** וגו' **.** כשמגיע לימי הזקנה האשה קרובה להחשב כאיש, לפיכך האיש פוחת בהזדקנו יותר משליש בערכו, והאשה אינה פוחתת אלא שליש בערכה, דאמרי אנשי, סבא בביתא, פחא בביתא. סבתא בביתא, סימא בביתא וסימנא טבא בביתא:
@833 **ואם מך הוא.** שאין ידו משגת לתן הערך הזה: **והעמידו.** לנערך לפני הכהן ויעריכנו לפי השגת ידו של מעריך: **על פי אשר תשיג.** לפי מה שיש לו יסדרנו וישאיר לו כדי חייו מטה כר וכסת וכלי אמנות, אם היה חמר, משאיר לו חמורו:
@834 **כל אשר יתן ממנו.** אמר רגלה של זו עולה, דבריו קימין, ותמכר לצרכי עולה ודמיה חלין, חוץ מדמי אותו האבר:
@835 **טוב ברע.** תם בבעל מום: **או רע בטוב.** וכל שכן טוב בטוב ורע ברע:
@836 **ואם כל בהמה טמאה.** בבעלת מום הכתוב מדבר, שהיא טמאה להקרבה, ולמדך הכתוב שאין קדשים תמימים יוצאין לחלין בפדיון אלא אם כן הממו:
@837 **כערכך הכהן כן יהיה.** לשאר כל אדם הבא לקנותה מיד הקדש:
@838 **ואם גאל יגאלנה.** בבעלים החמיר הכתוב להוסיף חמש, וכן במקדיש בית וכן במקדיש את השדה וכן בפדיון מעשר שני הבעלים מוסיפין חמש, ולא שאר כל אדם:
@841 **והיה ערכך לפי זרעו.** ולא כפי שויה. אחת שדה טובה ואחת שדה רעה, פדיון הקדשן שוה, בית כור שעורים בחמשים שקלים, כך גזרת הכתוב. והוא שבא לגאלה בתחלת היובל, ואם בא לגאלה באמצעו, נותן לפי החשבון סלע ופונדיון לשנה, לפי שאינה הקדש אלא למנין שני היובל, שאם נגאלה הרי טוב, ואם לאו הגזבר מוכרה בדמים הללו לאחר ועומדת ביד הלוקח עד היובל כשאר כל השדות המכורות, וכשהיא יוצאה מידו חוזרת לכהנים של אותו משמר שהיובל פוגע בו ומתחלקת ביניהם, זהו המשפט האמור במקדיש שדה. ועכשיו אפרשנו על סדר המקראות:
@842 **אם משנת היבל יקדיש** וגו' **.** אם משעברה שנת היובל מיד הקדישה ובא לגאלה מיד: **כערכך יקום.** כערך הזה האמור יהיה, חמשים כסף יתן:
@843 **ואם אחר היבל יקדיש.** וכן אם הקדישה משנת היובל ונשתהה ביד גזבר ובא זה לגאלה אחר היובל: **וחשב לו הכהן את הכסף על פי השנים הנותרת.** כפי חשבון. כיצד, הרי קצב דמיה של ארבעים ותשע שנים חמשים שקל, הרי שקל לכל שנה, ושקל יתר בין כלן, והשקל ארבעים ושמנה פונדיונין, הרי סלע ופונדיון לשנה אלא שחסר פונדיון אחד לכלן, ואמרו רבותינו שאותו פונדיון קלבון לפרוטרוט, והבא לגאול יתן סלע ופונדיון לכל שנה לשנים הנותרות עד שנת היובל: **ונגרע מערכך.** מנין השנים שמשנת היובל עד שנת הפדיון:
@844 **ואם גאל יגאל.** המקדיש אתו, יוסיף חמש על הקצבה הזאת:
@845 **ואם לא יגאל את השדה.** המקדיש: **ואם מכר.** הגזבר: **את השדה לאיש אחר לא יגאל עוד.** לשוב ליד המקדיש:
@846 **והיה השדה בצאתו ביבל.** מיד הלוקחו מן הגזבר, כדרך שאר שדות היוצאות מיד לוקחיהם ביובל: **קדש לה'.** לא שישוב להקדש בדק הבית ליד הגזבר אלא כשדה החרם הנתון לכהנים, שנאמר (במדבר יח יד) כל חרם בישראל לך יהיה, אף זו תתחלק ביובל לכהנים של אותו משמר, שיום הכפורים של יובל פוגע בו:
@847 **ואם את שדה מקנתו** וגו' **.** חלוק יש בין שדה מקנה לשדה אחזה, ששדה מקנה לא תתחלק לכהנים ביובל, לפי שאינו יכול להקדישה אלא עד היובל, שהרי ביובל היתה עתידה לצאת מידו ולשוב לבעלים, לפיכך אם בא לגאלה, יגאל בדמים הללו הקצובים לשדה אחזה. ואם לא יגאל וימכרנה גזבר לאחר, או אם לא יגאל הוא, בשנת היובל ישוב השדה לאשר קנהו מאתו, אותו שהקדישה. ופן תאמר לאשר קנהו הלוקח הזה האחרון מאתו, וזהו הגזבר, לכך הצרך לומר לאשר לו אחזת הארץ (פסוק כד) , מירשת אבות, וזהו בעלים הראשונים שמכרוה למקדיש:
@850 **וכל ערכך יהיה בשקל הקדש.** כל ערכך שכתוב בו שקלים יהיה בשקל הקדש: **עשרים גרה.** עשרים מעות. כך היו מתחלה ולאחר מכאן הוסיפו שתות. ואמרו רבותינו שש מעה כסף דינר, עשרים וארבע מעות לסלע:
@851 **לא יקדיש איש אתו.** לשם קרבן אחר, לפי שאינו שלו:
@852 **ואם בבהמה הטמאה** וגו' **.** אין המקרא הזה מוסב על הבכור, שאין לומר בבכור בהמה טמאה ופדה בערכך. וחמור אין זה, שהרי אין פדיון פטר חמור אלא טלה, והוא מתנה לכהן ואינו להקדש, אלא הכתוב מוסב על ההקדש. שהכתוב של מעלה (פסוק יא) דבר בפדיון בהמה טהורה שהוממה, וכאן דבר במקדיש בהמה טמאה לבדק הבית: **ופדה בערכך.** כפי מה שיעריכנה הכהן: **ואם לא יגאל.** על ידי בעלים: **ונמכר בערכך.** לאחרים:
@853 **אך כל חרם** וגו' **.** נחלקו רבותינו בדבר יש אומרים סתם חרמים להקדש, ומה אני מקים (במדבר יח יד) כל חרם בישראל לך יהיה, בחרמי כהנים שפרש ואמר הרי זה חרם לכהן, ויש שאמרו סתם חרמים לכהנים: **לא ימכר ולא יגאל.** אלא ינתן לכהן. לדברי האומר סתם חרמים לכהנים, מפרש מקרא זה בסתם חרמים. והאומר סתם חרמים לבדק הבית, מפרש מקרא זה בחרמי כהנים, שהכל מודים שחרמי כהנים אין להם פדיון עד שיבואו ליד כהן, וחרמי גבוה נפדים: **כל חרם קדש קדשים הוא.** האומר סתם חרמים לבדק הבית מביא ראיה מכאן, והאומר סתם חרמים לכהנים מפרש כל חרם קדש קדשים הוא לה', ללמד שחרמי כהנים חלים על קדשי קדשים ועל קדשים קלים, ונותן לכהן, כמו ששנינו במסכת ערכין (כח ב) אם נדר נותן דמיהם, ואם נדבה נותן את טובתה: **מאדם.** כגון שהחרים עבדיו ושפחותיו הכנענים:
@854 **כל חרם אשר יחרם** וגו' **.** היוצא להרג ואמר אחד ערכו עלי, לא אמר כלום: **מות יומת.** הרי הולך למות, לפיכך לא יפדה אין לו לא דמים ולא ערך:
@855 **וכל מעשר הארץ.** במעשר שני הכתוב מדבר: **מזרע הארץ.** דגן: **מפרי העץ.** תירוש ויצהר: **לה' הוא.** קנאו השם ומשלחנו צוה לך לעלות ולאכלו בירושלים, כמו שנאמר (דברים יד כג) ואכלת לפני ה' אלהיך מעשר דגנך תירושך וגו' :
@856 **ממעשרו.** ולא ממעשר חברו, הפודה מעשר של חברו אין מוסיף חומש. ומה היא גאלתו, כדי להתירו באכילה בכל מקום. והמעות יעלה ויאכל בירושלים, כמו שנאמר (דברים יד כד) ונתת בכסף וגו' :
@857 **תחת השבט.** כשבא לעשרן מוציאן בפתח זה אחר זה, והעשירי מכה בשבט צבוע בסיקרא להיות נכר שהוא מעשר, כן עושה [לגדיים] לטלאים ולעגלים של כל שנה ושנה: **יהיה קדש.** לקרב למזבח דמו ואמוריו, והבשר נאכל לבעלים, שהרי לא נמנה עם שאר מתנות כהנה, ולא מצינו שיהא נתן לכהנים:
@858 **לא יבקר** וגו' **.** לפי שנאמר (שם יב יא) וכל מבחר נדריכם, יכול יהא בורר ומוציא את היפה, תלמוד לומר לא יבקר בין טוב לרע, בין תם בין בעל מום חלה עליו קדשה, ולא שיקרב בעל מום, אלא יאכל בתורת מעשר ואסור לגזז ולעבד:

@1 **ויקרא וגו'**. טעם הקריאה, ולא הספיק הדיבור לבד, אמרו בתורת כהנים כי בג' מקומות קדמה הקריאה לדבור, בסנה, וסיני, ואוהל מועד, ולא מצינו ללמוד אוהל מועד לא מסנה ולא מסיני, מסנה שיש בו רבותא שהיה תחלה לכל הדברות סיני יש בו רבותא שהוא לכל ישראל, ואין ללמוד מהם של אהל מועד, גם אין ללמוד אהל מועד מצד השוה שבסנה וסיני, כי י''ל מה לצד השוה שהיו באש מה שאין כן אהל מועד:
@1 **הנה** מה שאמרו שנאמרה קריאה בסיני כתב הרא''ם שהוא פסוק ויקרא אל משה ביום השביעי וגו' (שמות כד טז) או ויקרא ה' למשה אל ראש ההר (שמות יט כ) אבל לא מדכתיב ויקרא אליו ה' מן ההר (שמות יט ג) כמו שפירש רבינו הלל, כי קרא זה לא עם אש נאמר וברייתא קתני מה לצד השוה שהיה באש וכו' ע''כ. ובמחילה מכבודו לא דק בזה כי האמת הוא שהלימוד הוא לדבור הוא מפסוק ויקרא אליו ה' מן ההר, כי ויקרא אל משה ביום הזה אין אותה קריאה מיותרת ואצטריכא לגופא שקרא לו לעלות לשבת בהר ארבעים יום כאמור שם ויקרא אל משה וגו' ויבא משה וגו' ויהי משה בהר ארבעים יום, וקריאה זו במקום דבור היא. והקריאה שאנו דנים בה קריאה שהיא לדבור, ומזכיר קריאה ודבור, גם ויקרא ה' למשה אל ראש ההר שקריאה זו צורך עליה היתה כי משה היה למטה וקרא לו לעלות אל ראש ההר ושם דיבר אליו, ואם לא אמר ויקרא והיה מדבר עמו היה מדבר עמו והוא למטה מן ההר, ואנו רואים שלא דבר אליו עד אחר עלות, ואיך יהיה פה ולשון לומר שלא היה לו לומר אלא וידבר, אבל פסוק ויקרא אליו ה' מן ההר רואים אנו כי תכלית הקריאה לא היה אלא לומר אליו כה תאמר וגו', ודברים אלו אמרם אליו שם והוא למטה מבלי עלות, א''כ מה טיבה של קריאה זו אינה אלא קדימה לדבור. ומה שנסתייע הרב בפסוק ויקרא אל משה ביום השביעי ממה שאמר הכתוב אחר אומרו ויקרא וידבר וגו' ויקחו לי וגו', לא האירו למול פני הרב בב' כתובים ובהם ב' עניינים שהפסיקו בין הקריאה לדבור האחד ומראה כבוד ה' וגו' והב' ויבא משה וכו' ויהי שם בהר ארבעים יום וגו', ואחר זה אמר הכתוב וידבר ה' בסנה להעירך להצדיק מה שכתבנו, ומי יאמר שדבור זה לא היה אחר שבתו בהר עשרים יום או שלשים יום. ומה שדחה דעת רבינו הלל שאמר פסוק ויקרא אליו ה' מן ההר בטענת שלא היה עדיין אש ואמרו שם בתורת כהנים מה לצד השוה של סנה וסיני שהיו באש וכו', להיותו סובר הרב שהאש היה בשעת הקריאה מקשה, ולא היא, שכונת התנא הוא שבאותה נבואה היה בה דבר זה לתוספת, ומידי דהוה שהיתה בה מעלה זו שהיתה באש מה שלא היה באהל מועד היה בו גם כן הקריאה למעלה, ולפי זה לו יהיה שלא היה עדיין אש מה בכך הרי באותה הנבואה היה אש ונשתנית נבואה זו ונבואת סנה מנבואת אוהל מועד שלא היה בו אש, ובזה אין קושיא דרב קשיא, ותמה אני איך לא האירו למול עניו מה שהקשינו:
@1 **ועוד** לו יהיה כפי דבריו איך מצי למימר תנא מה להצד השוה שבהן שהיו באש, והלא ויקרא אליו ה' מן ההר ליאמר וגו' לא היה באש, ולגמור מאותה קריאה וקריאת סנה מצד השוה שבהם שאינם אלא דבור מפה קדוש למשה והקדים קריאה לדבור, ולהעמיק בקושיא זו יראה דמתברא טנרי:
@1 **ועוד** למה הוצרך לומר ג' קראי בסיני שקדמה קריאה, ולו יהיה שלא נחשוב פסוק ויקרא אליו ה' מן ההר, ב' מיהא ישנם שקדמה קריאה לדיבור לסברת הרב, והלא כל טרחת התנא הוא על יתור ויקרא האמורה באהל מועד שלא היה צריך לאומרה ויגדל הקושיא בזכרונה ב' פעמים בסיני, אלא ודאי שדברי הרב כאן שלא בדקדוק, ולדברינו אינו מקום לקושיא אחת מכל אלו והקודמים ומעתה נמצינו אומרים עיקר לימוד שקדמה קריאה לדבור בסיני הוא פסוק ויקרא אליו ה' מן ההר וגו' כה תאמר ועיקר:
@1 **ומה** שאמרו בברייתא לא אם אמרת בסיני שהוא לכל ישראל וגו' לכאורה הוא דבר תמוה שהרי אין לך מצוה שאינה לכל ישראל. ובעל קרבן אהרן פירש לכל ישראל ולצד זה היה צורך שיהיה הקול בהדרגה מועטת מהרגיל לדבר עם משה ולזה אמר ויקרא אל משה להודיע שדיבר אליו בקול הרגיל ולא נתמעט מהדרגתו בשביל ישראל, ולדרכו צ''ל כאלו אמר התנא לצד שהיה לכל ישראל. כי לא המעלה היא היותו לכל ישראל, ואין דברים אלו מתקבלים בשכלי. והנכון בעיני הוא שהמעלה היא שמצינו ששינה ה' דברותיו שם שלא אמרם למשה לבד והוא ידבר אל בני ישראל אלא מפי עליון היו לכל ישראל, וכשם שנשתנית נבואת סיני לפרט זה נשתנית ג''כ למעלה זו של קריאה משאר דברות הנאמרים למשה לבד ולא השמיעם ה' לכל ישראל ג''כ נאמר שלא היתה בהם מעלה זו שקדמה קריאה לדבור:
@1 **עוד** סיים באותה ברייתא יכול לא היתה קריאה אלא לדבור זה מנין לכל הדברות שבתורה תלמוד לומר מאוהל מועד יכול לא הית' קריא' אלא לדברות בלבד מניחן לרבות האמירות והצווים תלמוד לומר דבר וידבר לרבות אף לאמירות וציווים וכו' ע''כ. פירוש הדברים כי מקריאת אהל מועד וסנה וסיני אין ללמוד לשום דבור זולתם, והטעם לצד שהיה התחלת דבור במקום ההוא אבל את אשר ידבר עוד שם במקום ההוא לא יקדים בו הקריאה תלמוד לומר מאוהל מועד קרא יתירה לומר כל אשר ידבר מאוהל מועד תקדים לו הקריאה והגם שלא ריבה הכתוב אלא באהל מועד הרי זה בנין אב לכל, כי אין בו דבר חידוש מסיני ולא מסנה לומר שלצד אותו חידוש היתה הקריאה. וחזר לומר אין לי אלא דברות שכן דייק הכתוב וידבר מנין לנביאות המתחילות ויאמר או לשון ציווי. ואולי כי הדיבור יגיד תגבורת המדבר מה שאין כן האמירות והצוויים מנין שיקדים להם הקריאה תלמוד לומר דבר וידבר. וראיתי גירסא להראב''ד תלמוד לומר דבר וידבר לאמר. ולגירסא זו דרש יתור תיבת לאמר האמורה בוידבר שלא היה צ''ל אחר שאמר דבר, הא למדת שבא לרבות האמירות, והצווים בגדר אמירות הם:
@1 **וראיתי** לבעל קרבן אהרן שהשיג על הגירסה למה אמר תלמוד לומר דבר שלא היה לו לומר אלא תלמוד לומר לאמר עד כאן. ואין זו קושיא, לצד שכח הדרשה היא מכפל דבר שזולתה תיבת לאמר אינה מיותרת ואצטריכא לעצמה, לכן כגירסת הראב''ד עיקר:
@1 **והנה** מה שדן התנא להכריח כי צ''ל ויקרא על דבור ראשון שבאוהל מועד משום שאינו נלמד לא מסנה ולא מסיני, אין זה אלא הבחנת האמת מצד עצמו, כי זולת זה ג''כ הגם שהיה נלמד דבור ראשון הנאמר באוהל מועד מסנה וסיני אין יתור לתיבת ויקרא, כי הוצרך לשאר דברות הנרמזים ביתור מאוהל מועד והנלמדים מיתור לאמר, שזולת זכרון הקריאה כאן לא היינו יודעים דברים המתרבים:
@1 **אלא** שיש לתת לב בברייתא למה לא הקשה ייתור ויקרא האמורה בסנה וסיני וילמדו מויקרא האמורה באוהל מועד, ואין צריך לומר אם יאמר אוהל מועד וסיני או אוהל מועד וסנה ויבא הג' מצד השוה שביניהם. ועוד קשה לדברי התנא שדורש אומרו מאוהל מועד קרא יתירא לדרשא להביא כל הדברות שגאמרו באוהל מועד שקדמה בהם הקריאה ולא פעם ראשונה בלבד, א''כ מי גרע דיבור ראשון שנאמר בסיני שלא תקדים בו הקריאה שהוצרך לומר בו ויקרא, וכמו כן בסנה לא היה צ''ל ויקרא לפי מה שלמד שם מיתור דבר לאמר לרבות כל האמירות:
@1 **וראיתי** להרא''ם שנתן דעתו ליישב הדקדוקים, וכל מה שכתב הרב בזה אין דעתי הולמתו, ראשונה מה שכתב כי לא מצי למילף סיני וסנה מאוהל מועד לצד שהיתה קריאה לטעם שהיה משה ירא לבא לזה קרא לו ליכנם, קשה לכשנאמר כי תנא דתורת כהנים חושש לדרשה זו, ועד עתה דלמא לא קדמה קריאה לדבור באוהל מועד, וקריאה זו אינה אלא כדי שיכנם ולא יעמוד בחוץ לצד שהיה ירא, ודוקא בסיני וסנה לצד צד השוה שבהם שאינו באוהל מועד הוא שקדמה הקריאה לדבור:
@1 **ומה** שיישב שאחר האמת דעת התנא הוא דלמדינן סנה מסיני ואוהל סועד, וכמו שגילה דעתו שדרש (שמות ג ד) ויאמר משה משה שאין תלמוד לומר ויאמר אלא ללמד על כל הקריאות שהיו משה משה, ואם לא היה סובר שאין צורך ללמד בה שקדמה הקריאה לצד דיליף מסיני ואוהל מועד הרי אצטריכא לגופא להשמיענו שקדמה לה הקדיאה ע''כ. בושני מדברים אלו כי מה שאנו לומדים שהקריאה קדמה להדיבור אינו על דבור שהיה בקריאה עצמה אלא על הדבור הנאמר בסמוך לה, כי הדבור שבקריאה עצמה לא מצינו אותו ולא היה בשום אחת מג' קריאות זולת בסנה פירש הכתוב אופן הקריאה שהיתה משה משה, ולא על דבור זה אנו אומרים שקדמה קריאה לדבור אלא על הדבור הנאמר לו אחר הקריאה, והנה לפניך המקומות שאנו אומרים בהם שקדמה הקריאה בהם בסיני לא נאמר אלא ויקרא ולא אמר הדבור שהיה בקריאה עצמה ואנו אומרים בו שקדמה הקריאה לדבור ובהכרח שהוא דבור הנאמר בסמוך לקריאה וכמו כן באוהל מועד אנו אומרים שקדמה הקריאה לדבור הגם שלא נאמר ויאמר משה, וא''כ כמו כן תהיה קריאת הסנה הגם שלא היה אומר הכתוב ויאמר אלא ויקרא משה משה וגו' ויאמר של נעליך וגו' אמרי' שקדמה קריאה לדבור, ואייתר ליה ויאמר לדרוש מה שדרש התנא. ותמהני עליו שהוא פירש שקריאה שקדמה לדבור בסיני הוא פסוק ויקרא ביום השביעי והדבור שאחריו הוא ויקחו לי תרומה שיש הרבה ריחוק מקום בין הקריאה לדבור, ובקריאת סנה העלים עיניו מראות הדבורים הנאמרים בסמוך. ואם הרב חשב שהקריאה לחוד ואמירת משה משה לחוד, זה שגגה הוא, והדברים ברורים לעין כל בן דעת, ותמהני איך יצאו מפי קדוש דברים אלו, ויש עוד להקשות אלא שאין צורך לדחות דברים כאלה:
@1 **ומה** שיישב למה לא ילמוד סיני וסנה מכל הדבורים והאמירות שנתרבו בפסוק זה שקדמה בהם הקריאה, ואמר שאין כוונת התנא אלא לאותם דברים ואמירות שנאמרו באוהל מועד בלבד ואין ללמוד ממנו לשאר דבדות שנאמרו בשאר מקומות, לפי מה שהעלה שסתרנוהו בסמוך, כי סנה אין בו קדימת קריאה, ואוהל מועד לצד ששכן עליו הענן ולא יכול לבוא, ודחק עצמו לפרש גם בדברי רש''י שאמר סתם לכל הדברות ואמירות וכו' קדמה קריאה וכו' שאינו אלא אותם שנאמרו באהל מועד ע''כ. דבריו ז''ל אין שכלי הולמם, כי ממה שריבה הכתוב כל הדברות והאמירות שהיו באוהל מועד שקדמה בהם הקריאה עין רואה ולב שומע כי לא לצד ששכן הענן ולא יכול לבא היתה הקריאה אלא להקדים הקריאה לדבור מודיע הכתוב שאם מחמת היראה קריאה אחת תספיק לכל, ואם להודיע שבכל דבור שהיה ה' מדבר היה משה ירא ליכנס והיה צריך לקרא לו, אין דברים אלו כדאים ליאמר, כי בהכרח לומר שלא היה הדבר כן בתמידות, שהרי הכהנים נכנסים ומשמשים ומשה לא ירא ולא יפחד ליכנם עמהם, ומן הסתם שידבר ה' עמו בתמידות, אם לא שתאמר שבכל עת שהיה רוצה ה' לדבר עמו היה הענן שכן והיו יוצאים הכהנים חוץ לאהל מועד, וזה הבל גמור:
@1 **ועוד** תמצא שהעלה רא''ם בד''ה מאוהל מועד כי תנא דתורת כהנים סובר כאותה ברייתא דקתני (ריש ת''כ) כתוב אחד אומר (שמות מ לה) ולא יכול משה לבא וכתוב אחד אומר (במדבר ז פט) ובבא משה בא הכתוב השלישי והכריע ביניהם (שמות מ לה) כי שכן עליו הענן, אמור מעתה כל זמן שהיה הענן על המשכן לא יכול, נסתלק וכו' ובבוא וגו' ע''כ. הנה פשט דרשה זו היא שמעולם לא נכנס משה אלא אחר שנסתלק הענן, ואף על פי כן ריבה הכתוב לכל הדברות שנאמרו לו באוהל מועד שקדמה להם הקריאה, ואם תאמר שלא דרש תנא כן אלא אחר שנאמר קריאה בסיני אבל זולת זה היה מחזר אחר דרשת ר' תנחומא (ריש פ' זו) שדרש שהקריאה היתה לצד שהיה מתיירא לבא, הרי לך דרשת ר' תנחומא ז''ל, היה ירא משה ליכנס דכתיב ולא יכול משה אמר הקב''ה אינו דין ודרך כבוד שמשה שנצטער במשכן יהיה עומד בחוץ ואני בפנים אלא הריני קורא אותו שיכנס לכך נאמר ויקרא, לסברא זו לא היה הדיבור אלא בפעם ראשונה אבל משם ואילך הרשות נתונה לו מאת המלך ליכנס ואין פחד ואף על פי כן אמר הכתוב שהיה מקדים קריאה לדבור ומעתה למה לא למדינן כל הדברות ואין צריך לומר סיני וסנה מאוהל מועד:
@1 **והנכון** לומר הוא כי אם לא אמר הכתוב קדימת קריאה לדבור בסיני וסנה הגם שהיה אומר באהל מועד היינו אומרים כי מאהל מועד מיעט סיני וסנה שלא קדמה הקריאה בו, שהסברא נותנת ללמוד מאוהל מועד כשם שקדמה בו קריאה לדבור כמו כן בסנה וסיני תלמוד לומר מאוהל מועד, ויש טעם למיעוט, כי אולי לצד שקבע ה' שכינתו עם ישראל הוסיף מעלה זו בתחלת שכינתו שקרא לו קודם הדבור, ורבוי לאמר היינו דורשים דרש אחרת. ותדע שאין לך פרשה שאין בה יתור לאמר ואנו דורשים באופן אחר ותהיה זאת כאחת מהנה. ואחר שאמר הכתוב קריאה בסנה וסיני נתחייבנו לומר כי מאוהל מועד בא לרבות שאר דיבורים, ואחר שמצינו שריבה הכתוב הדבורים דרשינן ג''כ לאמר למה שלפנינו שהם האמירות ששקול אני בהם אם יהיו בכלל הדברות, כי יותר יש לנו לדרוש יתור התיבה למה שאנו צריכין לה במקומה מלבקש דרשות, ואחר שהודיענו הכתוב כל הדברות והאמירות שנאמרו באוהל מועד שקדמה להם הקריאה הוא הדין לכל הדברות והאמירות שנאמרו בתורה, והטעם כי בג' מקומות מצינו שהקדים הכתוב קריאה לאמירה סיני וסנה ואהל מועד, ואין אני יודע אם לא היה דבר זה אלא בפעם ראשונה או בכל פעם ופעם כשביאר הכתוב באחד מהם שהוא באוהל מועד שהיה בו בכל דבור ואמירה הרי נתגלה הסתום שה''ה בכל הדבורים שהיו בכל המקומות. או נאמר עז''ה שאחר שביאר הכתוב דבורים ואמירות שהיו באוהל מועד אנו חוזרים ולומדים מסיני וסנה ואוהל מועד לכל הדבורים על זה הדרך, מה סיני וכו' קדמה קריאה אף כל וכו', מה לסיני וסנה שהיה תחלת דבור במקום ההוא תאמר בשאר דבורים שלא היו תחלת דבור במקום ההוא, אוהל מועד יוכיח שקדמה הקריאה לכל דבור ודבור שהיה שם, ולכשנאמר מה לאוהל מועד שכן היה מקום ששכן בו ה' בקביעות ונעשה אלהים שכן בתוכנו, סיני וסנה יוכיחו וכו' שקדמה הקריאה בפעם ראשונה וכו' וחזר הדין וכו' הצד השוה שבהם שהיה דיבור מפי קדוש למשה אף אני אביא כל דיבור מפי קדוש למשה שקדמה בו הקריאה בכל מקום שדבר עמו:
@1 **ויקרא אל משה**. צריך לדעת למה לא הזכיר שם הקורא, והגם שהזכירו אחר כך, מן הראוי להזכירו בתחלה וממילא מובן כי הוא המדבר כשיאמר ויקרא ה' וגו' וידבר. ואולי שיכוין הכתוב להודיע תעצומותיו יתברך שיקרא בקול גדול ולא ישמענו זולת את אשר יחפוץ, והוא אומרו **ויקרא אל משה** שהגם שקרא לא נשמע הדבור אלא אל משה ולא למי שלפניו, ולפי זה אם היה אומר הכתוב ויקרא ה' אל משה תבין שה' קרא בקול גדול אבל הגעת הקול למשה היה בקול נמוך שישער משה בדעתו שאפשר שאותם שרחוקים קצת ואינם בסמוך לו לא ישמעו ואין כאן חידוש פלא ה', לזה אמר **ויקרא אל משה** פירוש כי גם לגבי משה היתה קריאה בקול גדול ששמע קול גדול, והן הן נוראותיו יתברך שלא שמע זולתו. עוד נראה טעם שלא הזכיר שמו יתברך בקריאה, שיותר בחר למעלת השם להזכירו בדבור של מצוה מעל הקריאה שאין בה אלא הזמנה בעלמא או דרך כבוד לפי המדרש. עוד יש לתת טעם כפי המדרש (ויק''ר א' ח') שאמרו שהיו אהרן ובניו והזקנים אומרים אין אנו יודעים איזה מהם חביב לפני המקום אלא למי שיקרא ה' וכו' ויקרא אל משה וגו'. הנה לפי זה אין מקום להזכיר שמו בקריאה, כי מאמר ויקרא הוא ענין ההבחנה שהיו מצפים לה גדולי ישראל למי יקרא ה', לזה אין לומר אלא ויקרא אל משה והבן. ולדרך זה יתיישב מה שיש לדקדק עוד, למה הוצרך לומר **אל משה** ולא הספיק באומרו **אליו** שחוזר אל משה שהוזכר בסמוך (סוף פקודי), ודומה לזה תמצא שאמר הכתוב תחלת פרשת וירא אליו ולא הזכיר למי נגלה וסמך על זכרון אברהם שבפרשת הקודמת כמו כן היה לו לומר כאן, ובמה שכתבנו לא קשה:
@1 **וידבר ה' אליו מאהל מועד**. טעם שהוצרך לומר אליו, שלא תאמר שלא מנע ה' קולו משמוע לזולת משה אלא בערך ישראל, אבל כשידבר באהל מועד לא ימנע שמיעת הדבור מהמזדמנים שם שהם משרתיו כהני ה', לזה אמר אליו מאוהל מועד שאפילו בגשת משה לאוהל מועד ולא יהיו שם אלא כהני ה' לא היה נשמע הדבור אלא למשה:
@1 **מאהל מועד וגו'**. קשה כי מן הראוי להקדים הודעת המקום שממנו הדיבור ואח''כ יזכיר למי ידבר, וכאן איחר שאמר אל משה אח''כ אמר מאוהל מועד. והנה לפי מה שדרשו בתורת כהנים שכתבתי למעלה כי אומרו מאוהל מועד להודיע על כל הדברות שנאמרו אח''כ מאוהל מועד שקדמה להם הקריאה, יש טעם באיחור זכרון זה לומר כי למרחוק מגדת והבן:
@1 **ובתורת** כהנים דרשו עוד, מאהל מועד מלמד שהיה הקול נפסק ולא היה יוצא מאוהל מועד ע''כ. וקשה והלא כבר דרשו ממנה ענין הקריאה. עוד קשה אם היה נפסק הקול ולא יצא חוץ למה הוצרך הכתוב למעט ישראל משמיעת הדבור. וראיתי להרא''ם שכתב שכח דרשתו היא ממה שלא אמר ויקרא אל משה מאוהל מועד, ואמר אליו מאהל מועד דרשו שירצה לומר שמאהל מועד היה אליו באין הפסק הא למדת שלא יצא. וקושיא ב' תירץ הראב''ד שמה שהוצרך הכתוב למעטם הוא מן הדברות שהיו קודם הקמת המשכן:
@1 **ואין** דעתי מתישבת בב' התירוצים. ממה שכתב רא''ם שדורש מאיחור זכרון מאוהל מועד, הלא אין השינוי עושה רושם לאשר יכוין אליו, כי הגם שנשמע שמאהל מועד יצא לאוזן משה אף על פי כן לא יתחייב מזה לומר שלא יצא הקול, שאולי שמשה היה עומד סמוך לאוהל מועד ולעולם יצא חוץ. ועוד לדבריו היה לו להקדים תחלת הקול ואחר כך תכליתו על זה הדרך מאוהל מועד אליו, וממה שהקדים אליו ה''ז שולל שלא נתכוין בסמיכות זה לומר כן, כי איך יקדים שיעור סוף הדיבור קודם ראשיתו. ויותר נראה לומר שדורש מאומרו מאהל מועד לאמר ולא אמר וידבר ה' מאהל מועד אליו לאמר, שיש להקדים מקום המדבר וזכרון הנדבר אליו, וישנם לכל הדרשות שקדמו, ישנה ליתור מאהל מועד לדרוש שאר דברות שקדמה הקריאה, גם ישנה מופלגת ממה שלא אמר ויקרא מאהל מועד, גם ישנה לדרשת לאמר לרבות שאר אמירות וציווים שקדמה בהם הקריאה, שמע מינה שנתכוין לומר על זה הדרך מאהל מועד לאמר פירוש ממנו הוא תחלת דיבור הרמוז באומרו וידבר ובו כלתה האמירה באומרו לאמר, הא למדת שלא יצתה חוץ. או נאמר שהאי תנא אינו דורש יתור אוהל מועד לרבות שאר הדברות ודורש בין שאר הדברות בין האמירות כולן מייתור תיבת לאמר וכיון שהיא מיותרת אם אינו ענין למדבר תנהו ענין לשומע שלא ישמע אלא מהעומדים באוהל מועד ולא מהעומדים חוץ. ואולי שאמר מאוהל לומר למעט אותם שבאוהל מועד שהם אהרן ובניו, והגם שמעטו מתיבת אליו, עדיין יש לטעות שאומרו אליו למעט הזקנים, אבל אהרן ובניו יש מקום לומר שלא נמעטו, לזה אמר מאוהל מועד:
@1 **ומה** שתירץ הראב''ד לקושיא ב' שהמיעוט בא לדברות שקדמו, דברים תמוהים הם, שהרי המיעוט הוא בקריאתו מאוהל מועד, וגם לסברת הך תנא דממעטים מפסוק (שמות כה כב) ודברתי אתך וגו' (במדבד ז פט) וקול אליו הכל באוהל מועד היה. ויותר נכון לומר שלא דרשו שהיה הקול נפסק באוהל מועד אלא במה שדבר אליו באוהל מועד שכן כתוב וידבר אליו מאוהל מועד, אבל בקריאה מודה שיצא הקול חוץ לקרות למשה שהיה עומד בחוץ:
@1 **ומה** שכתב הרא''ם שתנא זה סובר שהיה משה בפנים והיה בזמן שנסתלק הענן, וכאידך דרשה דרמי כתיב ולא יכול משה וגו' וכתיב ובבא משה, בא הכתוב הג' והכריע ביניהם כי שכן הענן וגו', מעתה כל זמן שהיה ענן וכו' עד כאן. ואני אומר כי בעל דרשה זו לא יכחיש שזמן שנאמר ויקרא אל משה היה בזמן ששכן הענן, ורומית הכתובים היא על זה הדרך כתיב ובבא משה משמע שהרשות בידו בכל עת, וכתיב ולא יכול וגו' פירש כי אם על ידי קריאה, וכן תמצא שאמר הכתוב בסוף משפטים ויקרא אל משה ויבא משה בתוך הענן, וכמו כן במה שלפנינו, והדברים פשוטים אצלי כי אין מי שיסבור לומר שנתעכב משה חוץ לאוהל מועד עד אחר שנסתלק הענן וקרא לו. ותמצא דקתני רישא של אותה ברייתא וז''ל אוציא את כולן ולא אוציא מלאכי השרת שאין משה יכול ליכנס לתוכן עד שיקרא לו תלמוד לומר קול לו וגו' מאוהל מועד מלמד שהיה הקול נפסק וכו' ע''כ. הרי שהתנא עצמו סובר שלא היה נכנס אלא אחר קריאה, הא למדת חוץ לאוהל מועד היה. ואם תאמר אם כן מנין לתנא לדרוש שקדמה הקריאה לדיבור הלא קריאה זו לצורך היתה כדי שיכנם מפני שהיה ירא, נראה כי אם לא היה צורך בקריאה להקדימה לדיבור כאמור היה יכול ה' להסיר פחד מלבו ויכנס בלא קריאה אלא מטעם שהקדים הקריאה לדיבור הוא שקרא כנזכר, ומשה היה ירא לבא לאוהל מועד להזמין עצמו שיהיה מוכן כשיקרא ונשאר עומד בחוץ עד שקרא לו ה' כמנהגו ואז נכנס, וקול הקריאה יצא לחוץ, וקול הדיבור עמד במקומו באוהל מועד ולא היה יוצא לישמע אפילו הברתו חוץ לאוהל:
@1 **ובדרך** רמז ירמוז שיאמר משה לישראל שם באוהל מועד כל אשר יצווהו ה', לזה סמך **מאוהל מועד לאמר** פירוש משם יאמר הוא לישראל ויש בזה טוב טעם כדי שיהיה אימת הדיבור על שומעיו לפני המלך המצוה ב''ה, גם שיצדיקו אותו ביותר כשיאמר הדברים לפניו יתברך שלא הותיר ולא הוסיף על דבריו. עוד ירמוז על זה הדרך **אליו מאוהל מועד** פירוש שלא השיג לדבר ה' אליו אלא לצד שמחל ה' על עון העגל ושכן באוהל מועד לאות ולמופת, אבל אם לא היתה המחילה לישראל הרמוזה באוהל מועד לא היה ה' מדבר אליו, ואמר לו שיאמר דבר זה לישראל, והוא אומרו **לאמר**. ותמצא שאמרו שם בתורת כהנים לאמר אמור להם דברי כבושים בשבילכם מדבר עמי וכו' עד כאן, והוא מכוין לפירושנו, אלא שדרשתם כולה מתיבת לאמר ולא מדקדוק הכתוב שאמרנו. ואולי שגם רז''ל זו היא כוונתם. עוד אמרו רז''ל (ת''כ כאן) יכול היה מדבר עמו לצורך עצמו תלמוד לומר לאמר בשביל ישראל היה מדבר עמו ולא בשביל עצמו ע''כ. כוונת דבריו כי תיבת לאמר מיעוט הוא למעט שלא היה דיבורו למשה זולת בשביל ישראל פירוש לדבר להם, מכאן אתה למד שלא דיבר ה' עם משה אלא דברי תורה שמסר לישראל, והוא מאמר התנא (אבות א) משה קבל תורה מסיני ומסרה ליהושע, הא למדת שכל מה שקבל מסר, ומכאן אתה למד שלא הודיעו ה' סוד שלא למדו את ישראל, והושוו ישראל למשה בידיעה אלא שהוא למד מפי הגבורה וישראל מפי איש:
@2 **דבר וגו' ואמרת**. כפל לומר **דבר ואמרת**, גם שינה לדבר בב' לשונות ולא אמר אמור ואמרת. לצד שצוה ה' ב' מיני קרבן, א' הבא לרצון נידר ונידב, וא' לכפרת חטא כי יחטא אדם, כנגד זה אמר **דבר** כי גזרת מלך היא עליו חובת חטאת הרשומה בכל פרט ופרט וכנגד הבא לרצון אמר **ואמרת אליהם** אין זה אלא לצד רוממות וכבוד ואין חובה בדבר. עוד ירמוז גם על פרט חטאת השגיונות שיש בהם דיבור לבחינת החיוב, ואמירה שהוא לצד שיתרצה ה' לקבל בהמה תחת נפש החוטאת, שמן הראוי היא תמות וה' פדה נפש אדם בשה כשבים ושה עזים ולמרבה פר בן בקר. ואומרו **בני ישראל** וגו' בתורת כהנים אמרו אל בני ישראל למעט גוים מהסמיכה האמורה בסמוך. בני ולא בנות. ואמרת אליהם לסמיכה האמורה בסוף שהיא סמיכת שלמים, וקשה אחר שדרשו בסמוך יתור לאמר, דבר אל בני ישראל צריכה לגופה. ואין לומר כי ממילא מובן מתיבת לאמר כמו שפירש בעל קרבן אהרן, במחילה מכבודו שהרי אם לא אמר דבר אל בני ישראל לא הייתי דורש מה שדרשתי בלאמר ומה מקום לדרוש דבר וגו'. ואולי כיון שאין ידוע איזה מהם שהיא לגופה ואיזה מהם שבאה לדרשא דרשי' לתרווייהו. או אפשר שאינו דורש התנא דבר, אלה בני ישראל שהיה לו לומר דבר אליהם ומובן הדבר שעל ישראל הוא אומר, ומאומרו בני ממעט נשים שהיה לו לומר דבר אל בית ישראל, ומאומרו ישראל מיעט הגוים, וראשון עיקר, כי תמצא כי שם בתורת כהנים דורש בני ישראל לומר מה בני ישראל מקבלי ברית, ובה מכריח דרשתו שדורש בפסוק אדם כי יקריב מכם, הרי כי דורש דרשות הרבה כל שיהיו נשמעים כא', הכי נמי דורש יתור לאמר כיון שנוכל לומר כי זה הוא המיותר, וחוזר ודורש דבר אל וגו' כיון שנוכל לומר זה הוא המיותר:
@2 **אדם כי יקריב וגו'**. צריך לדעת למה הוצרך לומר תיבת **אדם**. ורז''ל אמרו (ת''כ הכא) לרבות גרים, והקשה הרב בעל קרבן אהרן למה הוצרך לרבות גרים כיון דקיימא לן (מנחות עג:) מקבלין מגוים וכו', והעלה שסלקא דעתך למעט אותם כיון שנכנסו בגדר ישראל, ומצינו שמיעט הכתוב בישראל דכתיב מכם ולא כולכם לזה הוצרך לרבות ע''כ. ודבריו ז''ל שלא בדקדוק כל עיקר, כי אם לא היה רבוי זה שרבוי גרים לא הייתי דורש מרבוי איש איש לרבות הגוים אלא לרבות הגרים, לזה קדם תנא והודיע כי גרים נתרבו מייתיר אדם, א''כ איש איש בא לרבות הגוים, ובזה תלך בדרך ישר במשמעות כל אותה ברייתא מבלי צורך דוחקת. ואין להקשות דלמא אדם בא למעט הגוים (ב''מ קיד.) כאומרו אתם קרוים אדם ולא אומות העולם קרוים אדם ואיש איש לרבות הגרים, כי מאומרו דבר אל בני ישראל הרי אין הכתוב בדבר אלא בישראל ומנין יעלה על הדעת לקבל מהגוים שיוצרך למעטם, אלא ודאי לא בא אלא לרבות, ואין לנו לרבות אלא גדר אחד מאותם שאינם בני ישראל והם הגרים, ולכשיבא רבוי אחר אז נבין שירבה הגוים, רבוי של הגרים לכולא עלמא מקבלין כל מין קרבן, אבל רבוי הגוים נחלקו (מנחות עג:) רבי יוסי הגלילי ורבי עקיבא אם דוקא עולות וכו':
@2 **ובמדרש** תנחומא אמרו למה אמר אדם ולא אמר איש, ירצה לומר כי יחטא האדם כאדם הראשון שהתחיל לחטוא יביא קרבן עד כאן. הנה ממשמעות דברי המדרש משמע כי אדם הראשון שוגג היה שהרי אין מביאין קרבן אלא על חטא שוגג, וזה מכוון למה שפירשתי בפרשת בראשית בפסוק (ג יב) היא נתנה לי וגו'. וכוונת המדרש היא כי בא ה' להתנהג עם בני ישראל מה שלא נהג כן עם אדם הראשון, כי אדם הראשון חטא ונקנסה עליו מיתה ולא הועיל לו הבאת קרבן, ולהם יועיל. ואומרו שהתחיל לחטוא, נתן הטעם למה לא נהג ה' כמו כן עם אדם הראשון, כי אדם התחיל לחטוא ולא קדם לו בחינת הרע להכריחו לחטוא, מה שאין כן הבאים אחריו כבר קדם להם בחינת החטא בנפשם, וזה לך אות הברית אשר ערל בשרו וצוה ה' למול מה שלא היה כן לאדם הראשון ולדרך זה השכלתי לישב חקירה אחת אשר שפט לאדם על עון ראשון משפט מות ולא חש למדתו ב''ה דכתיב (איוב נא) פעמים שלש עם גבר, ואדרבא משפט צבור יש לו להעביר לו גם עון ג' דכתיב (עמוס ב) על ג' פשעי ישראל וגו'. כי יש טעם נכון בדבר, כי ביום ברוא ה' האדם החליטו בבחינת הטוב באין פסולת שהיא בחינת הרע המטה את האדם מדרך הטוב ובחטאו נמשך בחינת הרע ונעשה סיג לכל נפש איש ישראל בנפשו רוחו ונשמתו, גם בגופו ערל לב וערל בשר, ולזה אם יחטא איש ישראל יעבור לו ה' פעמים שלש וגו' לצד חלק הרע הדבוק בו רע משננער מבטן אמו והוא יתגבר עליו להחטיאו במזיד, גם יחטיאנו בהסח הדעת ולזה יועיל לו קרבן על שגיונו, מה שאין כן אדם הראשון הגם שלא חטא אלא בשוגג משפט צדק, הוא לו שלא יעבור לו ה' אפילו חטא א'. גם שיהיה שוגג לא יועיל לו קרבן על שגיונו:
@2 **כי יקריב מכם**. צריך לדעת למה הוצרך לומר **מכם**. עוד למה איחר לומר מכם אחר זכרון המפעל ממנו, כי מן הראוי להקדים זכרון הפועל אשר בו ידבר ואחר כך הנפעל ממנו. ורז''ל (חולין ה' ע''א) אמרו שבא למעט מומר שבישראל, ודרשו מן הבהמה להביא מומר, הא כיצד מיעוט מומר לכל התורה כולה או לעבודה זרה ששקולה ככל התורה, וריבה מומר שאינו לכל התורה. ולדבריהם ז''ל נראה לישב גם מה שאיחר לומר מכם, שאם היה אומר אדם מכם היה נשמע שממעט במקום שמרבה, או מרבה במקום שממעט, ולא כן הוא כוונת הכתוב שהרבוי הוא בגרים, והמיעוט הוא בישראל לבד, לזה הבדיל ביניהם בתיבת כי יקריב. ונראה עוד לפרש על פי מה שאמרו בחולין (שם ע''ב) שהביאו ברייתא זו שדרשו מכם להוציא המומר, והביא אחריה ברייתא שדרשו מעם הארץ פרט למומר ר''ש אומר השב מידיעתו, ואמרו שם מומר לאכול חלב והביא קרבן על הדם איכא בינייהו, וקאמר שם חדא בחטאת וחדא בעולה ע''כ, ואמרו ז''ל בתורת כהנים כי יקריב אינו אלא רשות, והוא מה שדקדק לומר כי יקריב קודם אומרו מכם לומר שמה שממעט הוא בדבר הנידר ונידב וכדברי הגמרא שמסיק חדא בעולה, דלא תימא כיון שדורון הוא יקובל קא משמע לן, וחדא בחטאת, ומיעוט הצריך בחטאת הנה הוא רשום בכתב אמת באומרו (לקמן ד' כ''ז) מעם הארץ, ומשונה מיעוט זה ממיעוט האמור בעולה, כי מיעוט האמור בעולה אינו אלא למומר לכל התורה כולה, אבל המיעוט האמור בחטאת ימעט אפילו מומר לעבירה אחת אם תהיה אותה שמביא קרבן על שגיונה, וכן משמע גם כן מדברי הרמב''ם בפרק ג' מהלכות מעשה הקרבנות יעיין שם:
@2 **ובדרך** רמז יכוין על זה הדרך, לצד שראו שהקריב ה' את משה אליו ויקרא לו מתוך כולם ועשה יקר וגדולה למשה, לזה אמר **אדם כי יקריב** כל כך הקרבה לשכינה אין זה אלא **מכם** פירוש מצד ישראל כי באמצעותם היא ההגשה, וכמו שכתבנו למעלה שלא היה מדבר ה' עמו אלא בשביל ישראל, וצא ולמד ל''ח שנה שהיו ישראל נזופים נתרחק מעליו הכבוד ולא דבר אתו אלהים. עוד ירמוז לצוות את אנשי חיל להשתדל לקרב לבבות עם בני ישראל לעבודת ה', ולזה יקרא קרבן לה', כי על ידי חטא האדם יפרד הדבקות של ישראל עם אביהם שבשמים דכתיב (דברים ד ר) ואתם הדבקים בה' ויהיו נבדלים ומרוחקים מהשכינה, והאדון ברוך הוא יקפיד כביכול על הדבר ויתאוה לקרב אותם אליו, וצוה להוכיח לכל הרחוק ולקרב לבו, גם העניש למעלים עין מהדבר, וזה לך האות אשר צוה ה' להתחיל ממקודשיו והגדיל שכר המזכה כמאמר התנא (אבות פ''ה) כל המזכה את הרבים אין חטא בא על ידו כי ישמרנו ה' משגיונות, והם הדברים הנאמרים כאן.
@2 **אדם** דקדק לומר אדם לשון חשיבות כאמור בזוהר (תזריע מח) כי יקריב ואת מי יקריב פירש הכתוב ואמר **מכם** מן הפחותים שישנם בכם אשר פשעו בה' ויאמרו לאל סור ממנו ונתרחקו מדביקותו יתברך את זה יקריב, ולזה יקרא קרבן לה' כי יקריב נצר מטעיו קודש לשרשו, ואדם כזה אין צריך להביא לא נדר ולא נדבה גם אין מציאות להביא לו חטאת ולא אשם, על דרך אומרם ז''ל (אבות פ''ה) כל המזכה את הרבים אין חטא בא על ידו ואם אין שוגג אין קרבן, ואחר שגמר אומר מעשה קרבן הנכבד והמעולה אמר **מן הבהמה וגו' תקריבו את קרבנכם** דבר זה ישנו בכל אדם כי לא כל ישיגו בחינת רבים השיב מעון:
@3 **אם** עולה קרבנו. קשה למה שינה מב' פרשיות הסדורות אחרי זאת ואם מן הצאן וגו' לעולה, ואם מן העוף עולה, גם כאן היה לו לומר אם מן הבקר עולה וגו', ויתבאר על פי הסברא שאמרו בתורת כהנים במה שאמר הכתוב למעלה מזה את קרבנכם מלמד שהיא באה נדבת צבור עד כאן, לזה אמר סמוך לאומרו קרבנכם **אם עולה** פירוש דוקא עולה היא שאני מתיר שבאה נדבת צבור ולא שלמים כדתניא (ת''כ ג') שלמים אין באין נדבת צבור. עוד אם היה אומר הכתוב אם מן הבקר עולה היה נשמע שלא התיר להביא עולה אלא מן הבקר ולא מן הצאן, לזה אמר **אם עולה** לומר כי מה שמרבה באומרו קרבנכם הוא פרט העולה בין אם יהיה מן הבקר בין אם יהיה מן הצאן, ואין לטעות בעולת העוף, שהרי ביאר הכתוב ואמר קרבנו יתירה כמו שדרשו שם למעט צבור מעולת העוף ובתורת כהנים אמרו וזה לשונם עולה מה תלמוד לומר שיכול לא יהיו כל הפסולים אלו נוהגים אלא בעולת נדבה עולת חובה מניין וכו' תלמוד לומר אם עולה עד כאן. נראה שהקושה להם שהיה לו לומר אם קרבנו עולה, ודרשו שאם היה אומר אם קרבנו עולה אז יהיה נשמע שמדייק הכתוב בעולת נדבה שבה משתעי קרא דכתיב כי יקריב רשות, ואמר אם עולה פירוש כל עולה שבעולם בין של חובה בין של נדבה. והראב''ד ז''ל פירש שתיבת עולה מיותרת שהיה לו לסמוך על זכרונה לבסוף, והוא דוחק:
@3 **קרבנו** בתורת כהנים דרשו שבאה לרבות שלמים שישנם בכל הפסולין הרשומים ואין לומר שלמעטם בא הכתוב ולומר קרבנו האמור שהוא עולה ולא שלמים, כי זה אינו צריך למעט כי מהיכא תיתי לאסור, ולא דרשו קרבנו בכנוי שהוא יותר פשוט בכתוב, כי הרי הוציאו דין זה מקרבנו האמורה בעולת צאן:
@9 **את הכל**. אמרו ז''ל (ת''כ כאן) לרבות הקרנים והטלפים. וקשה למה לא הקריב אברהם את השה לעולה בקרניו וגו' והניח קרניו לשופרות כמאמרם ז''ל (פדר''א לא). ואולי שהקריב הכל ופקע מעל המזבח, כדתנן (זבחים פ''ו) וכולן שפקעו מעל המזבח לא יחזיר. או אפשר שנתלש מעליו קודם זריקה, ולא נתרבו הקרנים וכו' להקרבה אלא בעודן מחוברים אבל נתלשו אפילו עלו לראש המזבח ירדו דכתיב (דברים יב כז) ועשית עולתך הבשר וגו', ומותר בהנאה, וכדרבי זירא שאמר בפרשת המזבח מקדש (שם) נתלש קודם זריקה שרי למעבד מנייהו אפילו קתא דסכיני. או אפשר שעדיין לא נתנה תורה, והגם שאמרו ז''ל (יומא כח) קיים אברהם אבינו אפילו עירובי תבשילין, כבר כתבתי בפרשיות אבות שזה היה לרצון כל שאין הכרח בדבר לאיזו סבות זכות, כמו שתאמר נישואי תמר ליהודה נישואי שתי אחיות ליעקב, וכמו כן קרני איל עמדו לנם בהודעת נביאים, ולזה לא קיימו מצות העתידות להקטיר קרניו:
@10 **ואם מן הצאן**. אמרו בתורת כהנים הרי זה מוסיף על ענין ראשון עד כאן. הכונה בזה ליתן כל האמור במין הבקר ולא הוזכר בצאן כגון סמיכה ודיניה ושאר הלמודים. גם לדרוש אם נכפל דבר מהמוזכר כבר בבן הבקר, ולזה תמצא שדרשו כל הפרטים שנכפלו, גם ליתן את האמור בפרשה זו בשלפניה, כגון שחיטת צפון וכו' ושאר הדרשות הנלמדים מעולת צאן. ובתורת כהנים מסיים בה ולמה הפסיק, כדי ליתן ריוח למשה. הקשה הרא''ם דמכאן משמע שלא הוקשה ליה למה הפסיק אלא לצד דכתיב ואם שמוסיף, ושם בתורת כהנים (פסוק א') בברייתא שדנה שהיתה קריאה קודמת לדבור קתני יכול אף להפסקות וכו' ומה היו ההפסקות משמשות וכו' ע''כ. משמע אפילו בלא וא''ו היו ההפסקות משמשות וכו' ע''כ, ותירץ וכו' ואין דבריו נראים. והנכון בעיני הוא כי כח וטעם המתרץ שם הוא מכאן שזולת ייתור וא''ו האמור כאן הייתי אומר טעם ההפסקות לא ליתן ריוח למשה להתבונן אלא כדי שישכיל משה שלא ילמד דין מזה לזה, וממה שמצינו שרשם ה' כאן ואמר ואם מן הצאן בתוספת וא''ו הא למדת שדין כולן שוה וליתן האמור של זה בזה אם כן למה היו ההפסקות בהכרח לומר שהוא ליתן ריוח למשה, ומכאן לכל מקום שיהיו ההפסקות הרי שלך לפניך הטעם, והוא מאמר התנא בדרך כלל ומה היו ההפסקות משמשות:
@13 **והקריב וגו' את הכל והקטיר וגו'**. הנה כבר אמר זה בפרשת עולת בן בקר ואין לומר שנתכוין לרבות מה שאין בבן בקר והוא הצמר שבראשי כבשים והשער שבזקן התישים, שכל אלו לא היו נשמעים מאומרו את הכל בעולת בן בקר, שהרי מצינו שדרשו בתורת כהנים צמר ושער התישים מפסוק האמור בעולת בקר ומשמע להם כי מאמר את הכל הגם שלא נכתוב אלא בבקר ישנו גם בצאן בכל השייך בהם, ועוד כאן לא אמר הכל אלא בהקרבה ולא סמוך להקטרה ודרשו רז''ל (ת''כ כאן) באומרם והקריב את הכל וגו' זו עליית כבש שצריך כהן, שדין זה לא נשמע בעולת בקר, אם כן הקטרת המזבח בעולת צאן למה אצטריך:
@13 **ונראה** לפרש על פי מה שאמרו בתורת כהנים וזה לשונם והקטיר אף על פי שיוצא, אף על פי שפסול, אף על פי שפגול ונותר וכו' כשהן בראש המזבח עד כאן:
@13 **וקשה** מנין מצא תנא לדרוש היתר הפסולין לגבי המזבח. והרב בעל קרבן אהרן פירש מדלא כתב והקטירם משמע שיקטיר מכל מקום ע''כ, לדבריו ז''ל יתחייב לדרוש כמו כן באומרו והקריב את הכל ממה שלא אמר והקריבם שיקריב מכל מקום אפילו פסולין, ומדהא ליתא הא נמי ליתא. והנכון הוא שהתנא דורש לה מייתור והקטיר והקטיר ב' פעמים והוא קושייתנו עצמה שלא היה לו לומר אלא באחד מב' מקומות או בעולת בקר או בעולת צאן, אלא ודאי לדרשה בא לרבות הקטרת פסולין ונותר וכו' אחר שעלו המזבחה:
@13 **עולה הוא**. אמר הוא, דרשו בתורת כהנים שבא לעכב שחיטה בצפון בדיעבד שאם לא שחט בצפון פסולה. ולזה לא כתבה התורה הרבוי אלא בפרשה שנזכרה בה צפונה לומר כי על פרט זה בא המיעוט, ולא כתבו בפרשת בן בקר שהוזכר שם הסמיכה, כי אדרבה עליה בא רבוי תיבת עולה (פסוק ט') שאינה מעכבת סמיכה האמורה שם והגם שהכתוב אמר חלק מהרבוים ומהמעוטים מאחד וחלק מהרבוים והמעוטים בא' ואנו אומרים כאילו אמר כל הרבוים והמעוטים בכל א' מהם, שאני פרט זה כיון שהזכיר ב' מצות שהם סמיכה וצפון ומיעט וריבה ואין ידוע לאיזו מהם מיעט ולאיזו מהם ריבה, דרשינן הסמוך למיעוט והסמוך לריבוי, ומה מצינו מה סמך לרבוי סמיכה מה סמך למיעוט צפון. והגם כי גם שם נאמר רבוי, בא לניתוח שאינו מעכב כהפשט שנתמעט בריבוי שהוזכר בעולת בקר. ויש עוד להרחיב צדדים שישנם בענין והמשכיל יבין מעצמו. ובברייתא (בת''כ כאן) נתן טעם שדרשו הרבוי על הסמיכה שאינה מעכבת ומיעוט הוא על הצפון שמעכב כי הסמיכה אינה בכל העולות שעולת צבור אינה טעונה סמיכה וכו'. ואולי כי לרווחא דמלתא אמרו כן, כי הגם שהיה הדבר שקול יוכרע מטעם שכתבנו, והגם שהב' פרשיות ענין אחד הם, אף על פי כן להכריע ספק כזה יספיק. ותמצא בדרשת עולה הוא האמורה בעוף דרשו רז''ל בתורת כהנים כמו כן עולה לרבות אפילו לא מיצה דם הראש, הוא למעט אם לא מיצה דם הגוף עד כאן, והקשה בגמ' (זבחים סו:) מאי תלמודא, ומשני משום דרוב דמים בגוף שכיחי עד כאן, הרי דבסברא מטה הספק ודיוקינו מהכתוב עדיף:
@14 **ואם מן העוף**. גם זה מוסיף על ענין ראשון, ליתן כל האמור למעלה בו זולת פרטים ששלל הכתוב בפירוש בו. הא' שאין עוף בא אלא עולה ממה שדייק העוף עולה שינה מסדר שבעולת בקר וצאן, או לצד הייתור, ועוד מיעט קרבנו שאין בא עוף עולה מצבור, גם בדין מליקה שמעכב בכהן מה שאין מעכבת השחיטה בעולת בקר וצאן, גם פרטים שהוכפלו בעולת בקר ועולת צאן ללא צורך בא הדבר למעט העוף, אבל שאר דברים שמיעט הכתוב באחד משניהם ולמד זה מזה כגון נרבע, מוקצה, ונעבד, טריפה, חולה, זקן, גזול כולם פסולים בעוף כבהמה, וכן הוא מבואר בדבריהם וברמב''ם בפרק ג' מהלכות איסורי מזבח ולזה אמר ואם מן העוף:
@14 **קרבנו לה'**. טעם אומרו **קרבנו לה'**, מה שלא אמר כן בעולת בקר וצאן, לפי שמצינו שהכשיר הכתוב בעוף בעלי מומין כאומרם ז''ל (תו''כ קידושין כד) אין זכרות ותמות בעוף וכמו שכתבנו בסמוך, אם כן תבא הסברא לומר כי פחות הוא קרבן זה כי מום בו ואין זה בגדר קרבן לה' לזה אמר **קרבנו לה'** כי אין בו שום הדרגה פחותה לצד בחינה זו ואין רושם במומו כל עיקר. עוד ירצה על דרך אומרו (ישעי' נז) ואת דכא ושפל רוח ואמרו ז''ל (סוטה ה) אני את דכא ולמאן דאמר אתי דכא, ומהטעם עצמו לא הזכיר שמו יתברך סמוך להזכרת קרבן אלא בקרבן עוף, כי מי דרכו להביא עוף הוא העני ומביאו בשברון לב לצד מה שהוא העני ולצד מיעוט הקרבן וקרא עליו ואת דכא, מה שאין כן המקריב בקר וצאן שנפשו שמחה עליו בהקרבת דבר הראוי להתכבד. וכיוצא בזה דרשו בזבחים (מנחות קצ:) במה שאמר הכתוב במנחה ונפש יעו''ש:
@17 **אשה ריח ניחוח**. רז''ל אמרו (מנחות קי) נאמר בעולת בהמה אשה ריח וגו' ונאמר בעולת העוף אשה וגו' לומר לך אחד המרבה ואחד הממעיט וכו' עד כאן. הנה נתכוונו רז''ל לתרץ מה שקשה כי יאמר הכתוב אשה ריח ניחוח בעוף שהוא שוה איסר ומכל שכן בעולת הבהמה, לזה דקדקו בלשונם ואמרו לומר לך אחד המרבה וכו', פירוש שבא הכתוב להודיענו שאין הפרש בין המועט למרובה, שלא תאמר שאין זה אלא לצד שה' מצד רחמיו מתרצה בקרבן העני הגם שאינו חשוב כקרבן העשיר, ועל כל פנים אין המוחש נכחש כי זה מביא פר וזה מביא עוף, לזה נתחכם הכתוב ואמר ריח ניחוח בבהמה ולא הספיק לו במה שאמר בעוף ללמוד ממנו להעירך ולהראותך כי לא פחות הוא מקרבן בהמה ללמוד ממנו וצריך הוא להודיעך גם בקרבן בהמה אשה ריח ניחוח, והוא מה שדקדק התנא באומרו נאמר ונאמר וכו' פירוש ולא הספיק לו לומר הדבר במדרגה הקטנה נתכוין לומר לך בזה אחד המרבה ואחד הממעיט פירוש בהשואה הם, ולזה לא אמר התנא לומר הממעיט כמרבה שאז בטלה לה הכוונה שפי' בדבריו, כי כשנגיע לומר זה כזה יתחייב לומר כי הנלמד קטן מהמלמד כמשפט הרב ותלמידו, ומדקדוק לשון אומרו אחד ואחד הרי זה מראה באצבע השכל כי אין הדרגה לאחד מחברו, ובזה הוא שהשיג תירוץ למה לא אמר ריח ניחוח בעוף, כי בא ללמדנו דבר זה שאין מעלה לעשיר בשורו ולא כלום, ומטעם זה גם כן הוצרך לומר אשה ריח ניחוח בצאן ולא הספיק בבקר ועוף שהם ב' קצוות, כי בענין זה אין דבר נלמד מחברו לצד המובא:
@18 **ונפש וגו'**. בתורת כהנים דרשו יתור ונפש שיש בו מיעוט וריבוי, מיעוט נפש לשון יחיד למעט צבור שלא יביאו מנחת נדבה, ריבוי ביתרון הוא''ו לרבות יחיד שאינו מביא מנחה על טומאת מקדש וקדשיו שהוא כהן משיח, שמביא מנחת נדבה. וטעם הכתוב שכתב כאן רבוי ומיעוט בתיבה אחת. אולי כי לצד שלא הוכרח למעט הצבור אלא לצד שריבה כהן משיח לזה רמז שניהם יחד הגם שהם ב' דברים הפכיים, כי לולי רבוי כהן משיח אין צורך למעט צבור כי מנין יעלה על דעתנו שיביאו שיוצרך למעט, ואחר שבא רבוי כהן משיח יצא לנו דין חדש שישנו במלמד לצבור כאומרם שם בתורת כהנים לזה הוצרך למעט:
@21 **וכי תקריב**. אמר **וכי** בתוספת וא''ו לסמוך דין זה לענין ראשון, לומר לך שגם בפרטי המנחה נתרבה כהן משיח, ונתמעטו צבור גם לתנאי פרטי ההקרבה שנרשמו בקומץ מנחת סולת, גם להביא לבונה הגם שלא הוזכרה בה:
@27 **והנותרת וגו'**. צריך לדעת למה כפל פסוק זה ב' פעמים, ואולי שיתבאר על דרך אומרם ז''ל (מנחות נח.) בכל המנחות שמותר לאכול שירי מנחות בדבש אבל אם החמיץ שיריה לוקה ודרשו (שם נה) ממה שאמר הכתוב לא תאפה חמץ חלקם פירוש גם חלקם ע''כ. ועדיין אני אומר דוקא על האפיה הוא לוקה אבל אם החמיצה ולא אפאה לא, לזה אמר הכתוב והנותרת וגו' כל המנחה אשר תקריבו לא תעשה חמץ פירוש אפילו שיריה. והגם שרז''ל (שם) דרשו מפסוק לא תאפה חמץ וסמיך ליה חלקם, מאותה דרשה אין לחייב על שיריה אלא על האפיה ולא על שאר מעשה, ובפסוק זה לבד לא יספיק לחייב על שיריה על כל פרט ופרט, והגם שדרשו שם בתורת כהנים אפיה בכלל היתה ולמה יצתה לומר לך מה אפיה מעשה יחידי וחייב עליו אף אני אביא כל מעשה יחידי, עדיין אני אומר דוקא קומצה ולא שיריה קא משמע לן והנותרת וגו'. עוד יתבאר על דרך אומרו בתורת כהנים והנותרת אף על פי שלא הומלחה, אף על פי שלא הוגשה, אף על פי שלא הקטיר כל לבונתה, מן המנחה פרט לשחסרה וכו'. ושלא הקטיר מלבונתה כלום. וכתב הראב''ד כי וא''ו וה''א ריבויא הוא לרבות הנזכר ע''כ. ואין דעתי משגת רבוי זה שיעורו, שאין משמעות לתיבה בהסיר וא''ו וה''א. ובעל קרבן אהרן פירש כי וא''ו לבד הוא דאייתר וגם על זה יש לגמגם. ועוד מנין לתנא לומר ג' רבויים מליחה והגשה וכל הלבונה, בשלמא מה שמעט ג' מהמנחה יש לדרוש כל דמיון שבמנחה לעכב מה שאין כן ריבוי אחד אין לנו להרבות הרבה פרטים:
@27 **אכן** נראה כי לצד שאמר הכתוב ג' מצות אלה המלחה והגשה והקטרת כל לבונתה מפוזרים בג' מקומות, הקטרת כל לבונתה כתבה בפרשת מנחת סולת, הגשה במנחת מרחשת, המלחה אחר תשלום זכרון כל דיני מנחות, ומצינו שאמר הכתוב והנותרת מן המנחה אחר זכרון מנחת סולת הגם שלא הוזכר בה הגשה הא למדת שאין הגשה מעכבת בה שהרי הגם שלא הוזכר בה הגשה אמר והנותרת וגו' לאהרן ובניו, והגם שאנו אומרים מדרשות סמיכות וא''ו האמורה בתחלת כל הפסקה והפסקה שיכוין הכתוב ליתן את האמור של זה בזה ואם כן גם ההגשה שנאמרה במנחת מרחשת צריכה להיות גם במנחת סולת וגו', ממה שכתב והנותרת באמצע המנחות גילה כי הלימוד אינו אלא לכתחלה אבל אינו מעכב ליפסול בשבילה, אבל כל הלבונה מעכב. ועוד מצינו שחזר הכתוב ואמר והנותרת וגו' אחר דין מנחת מרחשת ופסוק זה כל רואה יגיד שהוא עצמו נותר שהדברים ככתבן נאמרו למעלה, הא ודאי לא בא אלא לומר שבפרטי דינים הרשומים שם יספיק להיות הנותרת לאהרן וגו' ושם לא הוזכר הקטרת לבונה כל עיקר אלא הקומץ דכתיב והרים הכהן וגו' אזכרתה פירוש הקומץ ולא הוזכר לבונה הא למדת שעל זה בא הכתוב ללמד שהגם שלא הקטיר כל לבונה כרשום בפרשת מנחת סולת הנותרת לאהרן, והוא מאמר התנא והנותרת אף על פי שלא הוגשה אף על פי שלא הקטיר כל לבונתה, וקתני גם כן אף על פי שלא הומלחה כי ראינו שצוה אחר אומרו והנותרת לאהרן הא למדת שישנו השיריים בהיתר הגם שלא הומלחה:
@31 **ואם תקריב וגו'**. פירוש אם יהיה זמן הקרבת מנחת בכורים וגו', תקריב פירוש חובה כי חיוב מצוה זו בכל זמן, ובמקום זכרון תנאי הזמן אמר ואם:
@34 **אם זכר**. שלא לעשות הדרגה לזכר בשלמים לזה אמר אם והבן:
@45 **ואם עז וגו'**. בתורת כהנים אמרו הפסיק הענין שלא תהא העז טעונה אליה ע''כ. וצריך לדעת במה הפסיק הענין. ובעל קרבן אהרן פירש ממה שהיה צריך לומר ואם עז ואמר אם עז. ודבריו שוגג הם כי ואם עז כתיב. והריב''א (תום' פסחים צו) פירש מדלא כלל אותו בהדי כבש כו' ולא שנה בו כלום וכו', והדברים פשוטים אצלי שכוונת התנא הוא לצד כי מצינו שאמר הכתוב בפרשת עולה ואם מן הצאן וגו' מן הכבשים ומן העזים, וכאן בפרשת שלמים הפסיק הענין ואמר מן הצאן בתחלה ואחר כך חזר לפרט דין העז בפני עצמה, לומר שיש בו דין חדש, ומה שלא אמר אם עז הא למדת שהוא סמוך על ענין ראשון בכל פרטי דינים הרשומים באומרו זבח שלמים זכר ונקבה וגו' כי רבים הם כולם ישנם בשלמי עז ולא נפסקה פרשת עז אלא לאליה, והטעם לפי שחזר הכתוב לפרט כל פרטי החלבים והשמיט האליה הרי זה מגיד שאליה הפסיק בין עז ובין כבש. ודע שלא הוצרך למעט האליה אלא בעז, אבל בבקר הגם שאמר ואם כבש וערבניהו קרא לא הוצרך למעט אליה, והטעם כי על כל פנים אליה דבקר אינו דומה לאליה דצאן ולא מקריא אליה, ולזה הגם שמערב הכתוב ב' דינים יחדיו ואם מן הצאן ליתן האמור של זה בזה היינו בדבר שישנו במציאות אבל אליה לצד שאין אליה של בקר קרוי אליה מנין לנו לרבותה דאצטריך קרא למעט, ולזה הגם שלא מיעטה הכתוב אמרו בתורת כהנים שאין בה דין אליה, ודוקא בעז לצד שרשם ואמר ואם מן הצאן ועז צאן מקרי וסלקא דעתך אמינא שעל שניהם אמר הכתוב האליה לזה הוצרך הכתוב לחלק ולומר אם כשב אם עז וגו':
@50 **חקת עולם וגו'**. מכאן פטיש להכות על קדקוד הטועה לומר שלא נאסר חלב אלא של קדשים, והרי כתיב חוקת עולם לדורותיכם בכל מושבותיכם, ואיך יעמד חי פסוק זה אם לא נאסר אלא חלב של קדשים, וכן פירש בתורת כהנים חוקת עולם לבית עולמים, לדורותיכם שינהוג לדודות, בכל מושבותיכם בארץ ובחוץ לארץ ע''כ. והנה אחר שאמר חוקת עולם מה מקום לומר **לדורותיכם בכל מושבותיכם**, אלא ודאי שהכוונה הוא על זה הדרך חוקת עולם נמשכת עם שלמעלה שהוא ע''ע הקדשים, ואמר תהיה אזהרה עוד לדרותיכם בכל מושבותיכם כל חלב וגו', והוא אומרו שינהוג לדורות איסור החלב בכל מושבותיכם אפילו בחוץ לארץ, שיעלה על דעתך לומר שלא אסר אלא בזמן שישנו קרב על גבי המזבח ולא בשאר זמנים, או אפילו בזמן שאינו קרב, אם הוא במקום שהוא קרב אבל במקום שאינו קרב לא תלמוד לומר לדורותיכם בכל מושבותיכם. ואם יטעה הטועה שאינו אסור אלא חלב הקרב, אחר שאמר חוקת עולם במה יש לטעות שהוצרך לומר לדורותיכם בכל מ ושב ותיכם:
@52 **דבר אל בני ישראל וגו'**. בתורת כהנים דרשו בני ישראל מביאים חטאת ולא גוים מביאים חטאת על ז' מצות בני נח וקשה מנין יעלה על דעת לומר שיביאו שהוצרך למעטם, ואם מנדרים ונדבות מה לנדרים ונדבות שאינם לכפרה תאמר בחטאת, וכדרך שאמרו בחולין (ה:) בצריכות מיעוטא דמומר דמיעטיה קרא בעולה ובחטאת דאצטריך למעט מומר בעולה ולא גמרינן ליה ממיעוט חטאת משום דלכפרה הוא מה שאין כן עולה ע''כ, ומינה בהיכא דנתרבו בעולה שהיא נדבות ונדרים שאין ללמוד חטאת שהיא לכפרה. ונראה לומר שהכוונה היא לשמור שלא תרבה גוים מייתור נפש שאמר הכתוב, לזה אמר **בני ישראל** למעט גוים וריבוי **נפש** לרבות גרים. וקשה לא היה לו לכתוב לא בני ישראל ולא נפש ואני יודע שהגוים לא מטעם שכתבנו וגרים מביאין דמנין יעלה על דעת למעטם. זו אינו קושיא כי הלא מצינו שהוצרך הכתוב לרבותם בתחלת הפ' דכתיב (פסוק ב') אדם ודרשו שם בתורת כהנים להביא גרים וא''כ סלקא דעתך אמינא שלא ריבה אותם אלא לעולה ולא לחטאת קא משמע לן, ואם כן אם לא היה מיעוט שמעט ביתור בני ישראל היה צד לומר כי גרים לא איצטריך משום דכיון דנתרבו בתחלת הפרשה נתרבו לכל פרטים הרשומים בכל הפרשה ולא בא רבוי שריבה ביתור נפש אלא לרבות הגוים שמביאין חטאת לזה אמר בני ישראל למעט גוים הא למדת שאומרו נפש אינה אלא לרבות גרים, ולא הספיק רבוי שבתחלת הפרשה לצד מדרגת חטאת עדיפא מעולה, גם לצד שהפסיק בענין ואין למידין לזה אצטריך. ועוד נראה לומר כי לא מיתור בני ישראל דורש אלא ממשמעות בני ישראל יגיד כי לא גוים, ולצד שבמשמעות בני ישראל יתמעטו גם הגרים לזה אמר נפש לרבות הגרים, ומעתה הגם כי בני ישראל צריכה לגופה בכל התורה כולה להודיע למי באה מצוה זו ממילא מתמעטים הגוים:
@52 **נפש**. אמרו רז''ל (תו''כ) לרבות גרים, ואם לכלול נשים היה לו לומר אדם כי יחטא כי אדם כולל זכר ונקבה דכתיב (בראשית ה ב) ויקרא שמם אדם. ובדרך רמז יכוין כי לצד שנפש של אדם רשע היא נחסרת לצד מעשה הרע באמצעות העון במזיד ולזה יקרא הרשע בחייו מת דכתיב (יחזקאל יח) במות המת כי אין לו נפש, והוא ג''כ אומרו (משלי כג) אם בעל נפש אתה, והודיעו הכתוב כי תחסר הנפש גם בחטא השוגג, האמת שלא תחסר כולה אלא מקצתה ולצד מחסור כזה הוא אשר אמר ה' כי יביא קרבן ובזה תתקרב הנפש לשורשה ויאיר אורה כבתחלה אבל במזיד שתחסר כולה לא יועיל תקנת הקרבן כי אין נפש במציאות לקרבה עד אשר ישוב ויעבור עליו יוה''כ ויחיה ע''ד אומרו (יחזקאל יח) השיבו וחיו:
@53 **אם הכהן וגו'**. התחיל בכהן ולא בצבור, ומה גם שאמר **לאשמת העם** שדימה שגגתו לשגגת העם ומן הראוי להקדים ברישא. ואולי שבא לו' שצריך להקדים קרבנו של משוח לשל ציבור ואין צריך לומר לשל מלך, והטעם כמו שאמרו במסכת הוריות (יג) כהן מכפר וצבור מתכפרין. ומצאתי לרז''ל (תו''כ פסוק יג) שאמרו פר כהן משיח ופר העדה פר כהן משיח קודם, ודרשוה מאומרו ואם כל עדת ישראל וגו' הא למדת שיש להקדימו. עוד דרשו מאומרו כאשר שרף וגו' מכאן שצריך להקדים פר משיח לפר העדה. וצריך לדעת למה לא הספיק לרז''ל ללמוד הקדימה ממה שהקדימו הכתוב שהוצרכו לחפש אחר דרשות אחרים. ואולי שאם לא היתה אלא הקדימה בסדר לבד הייתי אומר שלא סדרו הכתוב קודם קרבן צבור אלא לצד שאם היה מסדרו אחר קרבן צבור היה נשמע אומרו אם הכהן המשיח יחטא לאשמת העם פירוש האמורה בסמוך שהורו בית דין והוא הורה עמהם, וזה אינו כי אם הורה עם הצבור מתכפר לו עם הצבור וכדאיתא במשנה שם (הוריות ו) לזה קדם וסדר משפטו לבד. ועדיין אני אומר שלא יקדים קרבנו לשל צבור לזה דרשו מאומרו ואם וגו', ועדיין קשה למה הוצרכו ב' דרשות, לזה דרשת ואם, ודרשת כאשר שרף. ונראה כי אחד לרשות ואחד לחובה. ומה שראיתי לבעל קרבן אהרן שנתן טעם שהייתי או' למקצת ולא לכולה, אין טעם בטעמו. עוד נראה לו' אחד לאם קדם והביא ועדיין לא הביאו פר העדה והביאו אחר כך והרי שניהם עומדים, וחד לאם באו כאחת פר משיח ופר העדה אף על פי כן תקדים של משיח:
@53 **לאשמת העם**. יתבאר על דרך אז''ל (אבות פ''ה מי''ח) המזכה את הרבים אין חטא בא על ידו, ובראות כי כהן המשיח חטא זה יגיד שלא זכו הזוכים על ידו כדי שלא יבא חטא על ידו בשבילם והוא אומרו **לאשמת העם**. ובתורת כהנים דרשו כי לאשמת העם יכון הכתוב להראות מין החטא אשר יתחייב עליו קרבן שהוא העלם דבר עם שגגת מעשה כאמור לאשמת העם (פסוק יג) ונעלם דבר וגו'. ואם הכהן המשיח שגג בשגגת מעשה לבד הדבר תלוי אם יתחייב להביא קרבן הדיוט או לא, ודרשו ז''ל (הוריות יא) בפסוק מעם הארץ להוציא כהן משיח כי פטור לגמרי. ואם הכהן המשיח אינו חכם מופלא הרי זה פטור (שם ז) מכל מין קרבן בין בהעלם דבר ושגגת מעשה בין בשגגת מעשה לבד, וצריך לתת טעם לדבר זה. ואולי כי העושה בהעלם דבר והוא חכם מופלא שגגה זו עושה רושם גדול בנשמתו ומרחיק נפשו משורשה ולא יועיל זכותם של ישראל שהוא מכפר בעדן למנוע ממנו הפגם, מה שאין כן כל ששגג במעשה לבד או בהעלם דבר ואינו חכם מופלא חטא זה לא יפעיל פגם בבחינת נפש כהן משיח לרחקה משרשה כדי שיצטרך לקרבן לקרבה כי באמצעות זכות הרבים הן אל כביר לא ימאם, גם לא יספיק זה לסימן כי העם אשמים ממה שבא ליד המשיח שוגג זה מהטעם עצמו שכתבנו:
@57 **לפני ה'**. בתורת כהנים מה תלמוד לומר אמר רבי נחמיה לפי שמצינו בפר הבא ביום הכפורים שהוא עומד לפנים מן המזבח ומזה על הפרכת יכול אף זה כן ת''ל המזבח לפני ה' ולא כהן לפני ה' ע''כ. משמע שאם לא מצינו בפר הבא ביום הכפורים לא היה צריך להשמיענו לפני ה'. וקשה ומנין אני יודע מקום עמידתו, ומחמת שאין אני יודע מהכתוב שיש לו מקום ידוע נבוא לומר רצה עומד לפנים מן המזבח עומד רצה עומד חוץ למזבח עומד תלמוד לומר לפני ה' לומר כי צריך לעמוד חוץ למזבח ולמה הוצרך לומר (לפי שמצינו) לפני ה'. עוד קשה מנין מקום לדרוש שיזה על הפרוכת והוא חוץ למזבח, דלמא לגופא בא שיזה על המזבח והוא חוץ למזבח, וכדרך אומרו בפר יום כיפור (לקמן טז יח) ויצא אל המזבח, ולעולם הזאת הפרוכת תהיה והוא לפנים. ואלו לא היה לנו אלא דקדוק זה היה מקום ליישב. אלא שראיתי עוד בפרשת אחרי מות (שם) תניא ויצא אל המזבח מה ת''ל אמר רבי נחמיה לפי שמצינו בפר הבא על המצות שהוא עומד חוץ למזבח ומזה על הפרוכת יכול אף זה כן תלמוד לומר ויצא, והיכן היה לפני ה' ע''כ. קשה מה היא כח קושית מה תלמוד לומר, והלא אצטריך לומר שיצא ממקומו ולא יזה על המזבח והוא בפנים. עוד אומרו לפי שנאמר משמע דוקא לצד שנאמר אבל זולת שנאמר לא יודיענו הכתוב מקום עמידתו כשיזה על הפרוכת. ועוד לפי דבריו לא היה לו לומר לא ויצא שממנו נתחייב לומר לפני ה' בפר המצות כמו שמדקדק בדבריו מה תלמוד לומר לפני ה' לפי שמצינו וכו' ולא לפני ה' שממנה נתחייב לומר ויצא בפרשת פר יום כיפור כאומרו מה תלמוד לומר ויצא לפי שמצינו וכו'. ועוד קשה אומרו לפי שמצינו בפר הבא על המצות שעומד חוץ למזבח ומזה על הפרוכת, היכן מצינו שאמר הכתוב כן, ואם מאומרו לפני ה', דלמא על הזאת המזבח הוא אומר כפשט הכתוב ולא על הזאת הפרוכת. ועוד נראה אנחנו אם לא היה אומר לא ויצא ולא לפני ה' איה מקום כבוד עמידתו, ואם כן איך יכול תנא לומר מה תלמוד לומר בשניהם:
@57 **אכן** דרשת התנא היא כסדר זה כי אם לא אמר הכתוב לא ויצא ולא יתור לפני ה' פשוט הוא שנשפוט בו שיכול להזות בין על הפרכת בין על המזבח בכל אופן שיהיה בין המזבח בפנים בין הוא בפנים, ואחר שבא הכתוב וזכר בפר העלם מצות מזבח בפנים, ופשט הכתוב הוא על הזאת מזבח, וזכר בפר יום כיפור גם כן מזבח בפנים כאמור ויצא אל המזבח, ובפרט זה הושוו פר יום כיפור עם פר המצות, גם השמיענו בפר יום כיפור שהזאת פרוכת תהיה והוא בפנים, כי מאומרו ויצא מכלל שהיה בפנים, והנה הדעת נותנת שהוא הדין בפר המצות תהיה הזאת הפרוכת והוא לפנים מהמזבח וילמוד מה שחסר בפר העלם מפר יום הכיפור ונמצאו פר יום כיפורים ופר המצות שוים שיזה על הפרוכת והוא לפנים ויצא ויזה על המזבח, אשר על כן בא התנא והוציא דבר זה מלב שומע בכח הדרשה, ואמר לפני ה' מה תלמוד לומר, פירוש אחר שאמר הכתוב בפר יום כיפורים ויצא הא למדת שהזאת המזבח תהיה ומזבח לפנים, אם כן למה הוצרך לומר כאן לפני ה', אם ללמד בא שלא יזה על המזבח והוא בחוץ, אינו צריך וילמד הכל מפר יום כיפורים, ותירץ רבי נחמיה כי הוצרך לומר לפני ה', פירוש ממה שאנו רואים שלא רצה הכתוב ללמוד פר מצות מפר יום כיפורים הרי זה מראה באצבע שאין דומה לו, ובמה אין דומה לו, לפי שמצינו בו פרט אחד שלא הוזכר בפר המצות והוא הזאת הפרוכת והוא בפנים, והוא אומרו לפי שמצינו בפר יום כיפורים שהוא עומד לפנים ומזה על הפרוכת, ואם הייתי דן פר מצות ממנו הייתי יכול לו' גם זה (כן) תלמוד לומר לפני ה' כו', ומעתה אומרו מזבח לפני ה' שולל כהן לפני ה' בכל ההזאות בין של מזבח בין של פרוכת, שעל מי סמך עליו הכתוב להבין איה מקום עמידתו בשעת הזאת פרוכת, אם ללמוד מפר יום כיפור נלמוד גם כן הכל, אלא ודאי שקנה לו מקומו מזבח לפני ה' ולא כהן לפני ה' בכל ההזאות האמורים בענין זה. ובפסוק ויצא האמור ביום הכיפורים דרש על זה הדרך, מה תלמוד לומר פירוש משמעות פשט הכתוב הוא שלא יזה על המזבח עד שיצא, ומשמיענו גם כן שקודם כשהזה על הפרוכת היה לפנים:
@57 **והנה** דרשה ראשונה נשמעת בכתוב שצריך לצאת להזות על המזבח, אבל הזאת פרוכת שצריך לעמוד בפנים אין הכרח בדבר ויכול להזות בין שהוא לפנים בין שהוא לחוץ, ולצד כי רשות יש לו לעמוד במקום שירצה להזות על הפרוכת הזהיר הכתוב שכשיגמור בפנים להזות על הפרוכת יצא להזות על המזבח, לזה בא התנא ואמר הדרשה שבשבילה בנה הקושיא, והוא לפי שמצינו בפר הבא על המצות שהוא עומד וכו', פירוש הגם שלא הוזכר שם אלא גבי הזאת המזבח ולא למדנו על הזאת הפרכת אלא ממה שלא למד מפר יום כיפור והוצרך לומר לפני ה', אף על פי כן לפי מה שאנו דנים עליו עתה הוא אם לא נאמר בפר יום כיפור ויצא אלא לפני ה' שבפר העלם ובמציאות זה כשאני בא לדון על מקום עמידתו בשעת הזאת הפרוכת הייתי אומר כי רצה עומד בפנים רצה עומד בחוץ שלא הקפיד הכתוב אלא על הזאת המזבח שצריך שיעמוד בחוץ אבל בשעת הזאתו על הפרוכת אין עכוב בדבר, נמצאת אומר כי יכול לעמוד בחוץ למזבח ומזה על הפרוכת, והוא אומרו לפי שמצינו וכו' שהוא עומד חוץ למזבח ומזה על הפרוכת יכול גם זה כן תלמוד לומר ויצא, פירוש לעכובא שצריך לעמוד בפנים בשעת הזאת הפרוכת, שאם אתה אומר רשות לא היה צריך לו לומר ולומד אני מפר העלם, הא למדת שמכח אומרו לפני ה' בפר העלם אתה מתחייב לומר כי אומרו ויצא בפר יום כיפור בא לומר שצריך לעמוד בפנים בשעת הזאה על הפרוכת, שאם רשות לא היה צריך לומר והיה למד מפר העלם ב' דברים, שצריך לעמוד בהזות על המזבח בחוץ, ובהזות על הפרוכת יעמוד במקום שירצה, הא למדת מאומרו ויצא ב' דברים, שצריך לעמוד בפנים כשיזה על הפרוכת, וצריך לעמוד בחוץ כשיזה על המזבח, ולפי זה נתיישבו צריך עיון שהניח הרא''ם בפרשת אחרי מות (טז יח) בדרשת ויצא ועיין שם דבריו:
@57 **אלא** שצריך לחקור זאת, לפי ברייתא זאת שהכריחה עמידת פנים בהזאת הפרוכת ממה שלא למד פר יום כיפור מפר העלם, אם כן כשנחזור להבין ברייתא דלפני ה' למה נאמר וכו' קשה והלא צריך לדעת לפני ה' שזולתה לא הייתי יודע כי כוונת אומרו ויצא הוא להצריך עמידה בפנים בהזאת הפרוכת כנזכר, ומעתה נחזור למה שהיה עולה על דעתינו לומר כי גם בפר העלם יעמוד בפנים בשעת הזאה על הפרוכת כסדר האמור בפר יום כיפור, מה תאמר, למה הוצרך לומר, אצטריך כדי לגלות על פר יום כיפור שחובה לעמוד בפנים בהזאת הפרכת כאמור, שזולת זה הייתי אומר רשות. ויש לומר כי סובר התנא שלא תבא לפני ה' לעשות ממנו פלפול זה לבד דהיינו להקשות ילמוד ממנו פר יום כיפור וממה שלא למד וכו' כנזכר, כי אין זה דרך הכתוב, שעל כל פנים תהיה צריכה ללמוד דבר לגופה, שאם לא היה כוונת ה' אלא לגלות על ויצא כנזכר היה לו לפרש הדבר במקומו בפר יום כיפור:
@57 **עוד** נראה לומר כי כיון שדרשה זו צודקת כשנקדים להקשות למה נאמר לפני ה' וילמד מויצא, למה תדחה דרשה זו מאידך, הלכך למדינן תרווייהו:
@63 **ואם כל עדת וגו'**. בתורת כהנים דרשו עדת זו סנהדרין, נאמר כאן עדה ונאמר להלן וכו', ישראל דרשו המיוחדת שבישראל, שהיא של ע''א, ישגו יכול יהיו המיוחדים חייבים על ואמרו עוד הורו בית דין ועשו יכול יהיו חייבין תלמוד לומר הקהל ועשו, ההוראה בבית דין והמעשה בקהל ע''כ. ובדרך רמז ירצה שאם ישגו העדה ויטעו מדרך הישר, גם סנהדרי ישראל תורתם תהיה נעלמת מהם, לצד שלא השגיחו על עדת ה' ליישר המעקשים, כי החטא יולד חטא אחר, וצא ולמד (כתובות ס:) מהוראת אביי בלא נטילת רשות מרבו ששגג באותה הוראה והרגיש כי דין גרמה, וכדאיתא בסנהדרין (ה:):
@72 **אשר נשיא יחטא**. פירוש אפילו בהוראת בית דין כל שאין חייבין בית דין ועשה הוא חייב שעיר, וכן כתב הרמב''ם (הלכות שגגות פט''ו ה''ח):
@72 **או הודע**. אומרו או, לצד שקדם ואמר ואשם, ואמרו ז''ל (תו''כ) מלמד שמביא אשם תלוי אם נסתפק, לזה אמר או הודע פירוש אם הודע אליו ודאי:
@77 **ואם נפש וגו'**. אמר **ואם** בוא''ו להוסיף על ענין ראשון מה שרשם מהדינים בפרשה זו שאין בהם נגדיות להאמור במה שלפניה:
@77 **מעם הארץ**. דרשו רז''ל (הוריות יא) למעט כהן משיח בשגגתו בלא העלם דבר שלא יביא אפילו שעירה. גם מ''ם של מעם אמרו למעט נשיא בהיכא שאכל חצי זית והוא הדיוט וחצי זית והוא מלך שאינו מביא כשבה. פירוש מתחלה דורש עם הארץ שהוא לאפוקי הגדול ומיוחד שבהם שהוא כהן המשיח ודרשא זו היתה נדרשת הגם שהיה אומר בעם הארץ, ומאומרו מעם חזר וחלק גם חלק מההדיוט, וכגון הדיוט שאכל חצי זית ונתמנה והשלימו שאינו מביא:
@77 **בעשותה**. לא היה צריך לומר, ודרשו ממנה בתורת כהנים מיעוט ורבוי מיעוט שאם עשה על פי הוראת בית דין פטור, דסלקא דעתך אמינא מה שקבע הכתוב פר הקהל אינו אלא על בית דין שהיו סבה בהוראתם לחטוא אבל העושים כדינם עומדים להביא כשבה או שעירה קא משמע לן דדוקא התולה בעצמו, רבוי שאם תלה בבית דין פירוש שהורו בבית דין ועשה על פיהם אם היה יודע שטעו אינו נפטר מצד הוראתם וחייב בשעירה או כשבה הגם שיביאו בית דין פר החטאת כמשפטו. הרבוי רמוז בתיבת בעשות, והמיעוט בדקדוק בעשותה, משמע בעשות אותה ולא אחרת, ובזה תבין ב' ברייתות בתורת כהנים על נכון:
@82 **ואם כבש וגו' עד ונסלח לו**. צריך לדעת למה הוצרך לחלקם לב' פרשיות, והיה לו לומר למעלה והביא קרבנו שעירת עזים וגו' או כשבה תמימה וגו' ולא היה צריך לכתוב כל הפרשה, ונראה כי חלקם הכתוב לטעם עצמו שאמרו רז''ל (תו''כ ג) בפרשת ואם עז שבא לרבות אליה בחטאת מן הכשבה, לזה דקדק לומר בכשבה כאשר יורם חלב הכשב, ובשעירה אמר ואת כל חלבה יסיר. וחדא בשלמי נדבה וחדא בחטאת חובה. גם רואני שיש חידוש בכל האמור, אומרו **וסמך** דרשו רז''ל (תו''כ הכא) שבא ללמד על חטאת נזיר וחטאת מצורע שטעונין סמיכה, ואומרו **ושחט אותה לחטאת** דרשו (זבחים ז) שצריך שתהיה שחיטה לשם חטאת, ופרט זה לא נרמז בפרשת שעירה ומכאן אתה למד לשניהם, ואומרו **במקום אשר** וגו' אמרו בזבחים (מח:) בפרק איזהו מקומן חטאת מנלן דבעיא צפון דכתיב ושחט החטאת במקום העולה, אשכחן למצוה לעכובא מנלן דכתיב במקום אשר ישחט את העולה וגו' ע''כ. הרי שהוצרכו ב' כתובים. ושם בש''ס העלה שלמדין לכל החטאות למצוה, ואומרו (תו''כ כאן) **מדם החטאת** דרשו שצריך לקבל דמה לשם חטאת, וכן בכל מה שכפל יש בו חידוש משפט, ולזה חלקינהו קרא ללמד חוקים ומשפטים וכו':
@86 **כי תחטא**. צריך לדעת לאיזה ענין אמר כי תחטא שלא היה לו לומר אלא כי תשמע קול וגו', ונראה כי להיות שלא הוצרך זה להשביעו לזה אלה לצד שלא רצה להעיד עדות שיש לו לזכותו, כי בתחלה ישאל ממנו עדותו בלא השבעה, ועל כפירתו קורא עליו הכתוב כי תחטא, כי חטא הוא זה לדבר שקרים, ואם שמעה קול וגו' תתחייב בקרבן. ובזה תתיישב וא''ו של ושמעה שיורה שזולת זה הוא החטא הרשום בו חטאה:
@86 **עוד** יתבאר על דרך מה שאמרו בפרק שבועת העדות (ל.) וחייבין על זדון השבועה ועל שגגתה עם זדון העדות, ואינן חייבין על שגגתה, ופירש''י ואין חייבין על שגגתה, אם שוגגין הם לגמרי כסבורין שאין יודעין לו עדות וכו'. וכתב הרמב''ם בפרק א' מהלכות שבועות כיצד שגגת שבועת העדות, כגון שנעלם ממנו שחייבין עליה קרבן וידע ששבועה זו אסורה וכו' ושהיא שקר ע''כ. הרי שהשגגה שחייב עליה הוא שיודע על כל פנים שהיא אסורה ושקר והוא אמרו **נפש כי תחטא** פירוש בין במזיד בין בשוגג תכיר שחוטאת, לשלול אם שגגה שחשבה שמותר או ששכחה העדות אינו חייב על שבועה זו. ובאגדת אנשי אמת (זהר ויקרא יג:) נדרש פסוק זה על הנפש בירידתה לעולם על נכון:
@86 **ושמעה קול אלה**. יתבאר על דרך מה שאמרו בריש פרק שבועת העדות (שם) וז''ל המשנה, שבועת העדות וכו' בפני בית דין ושלא בפני בית דין מפי עצמו, ומפי אחרים אין חייבין עד שיכפרו בהן בבית דין דברי רבי מאיר וחכמים אומרים בין מפי עצמו בין מפי אחרים אינם חייבין עד שיכפרו בהן בפני בית דין ע''כ. הנה לרבי מאיר כל שהיא בבית דין אין צריך שתהיה השבועה מפי עצמו אלא בשמיעת האוזן לבד מתחייב. והוא אומרו **ושמעה קול אלה** פירוש הגם שלא ענה אמן. ולחכמים לסברת הראב''ד והאחרונים כל ששמעה קול אלה בין בפני בית דין בין שלא בפני בית דין אפילו לא ענה אמן כל שהיתה הכפירה בבית דין אפילו שלא בשעת השבועה חייב. ולדרך זה ידוייק הכתוב שבכל הצדדין הוא תולה הדבר בשמיעת קול אלה ואין צריך ביטוי שפתים:
@86 **ורמב''ם** ז''ל הגם שפסק כחכמים שצריך שיהיה הכפירה בבית דין אע''פ כן חלק שאם היתה השבועה שלא בפני בית דין צריך שיענה אמן, כמבואר בדבריו בפרק ט' הלכה א', ובפרק י' הלכה י''ז, א''כ סובר שכל שלא בפני בית דין ל''מ מפי אחרים אלא מפי עצמו, או מפי אחרים וענה אמן שהוא כמוציא שבועה מפיו, וכמו מה שכתב בתחלת פרק ב' מהלכות שבועות, והשיגו הראב''ד פרק ט' הלכה י' כי אין הלכה כרבי מאיר, ועוד בין לרבי מאיר בין לחכמים מה צורך שיהיה הבית דין בשעת השבועה והלא אין מקפידין וכו' אלא על הכפיר' ע''כ. והכסף משנה כתב שלא ידע מנין לו לרמב''ם חילוק זה:
@86 **ולי** נראה כי לא נחלקו רבי מאיר ורבנן אלא בנשבע מפי עצמו חוץ לבית דין ולא היתה הכפירה בבית דין כל עיקר, דלרבי מאיר חייב משום דיליף משבועת הפקדון, ודן מיניה ומינה כשם ששם מפי עצמו חייב, ומינה אפילו שלא בפני בית דין חייב, גם שבועת העדות כמו כן, ורבנן סוברים דון מינה ואוקי באתרה כאמור שם, אבל בנשבע מפי אחרים שלא בפני בית דין והיתה הכפירה בבית דין אין מחלוקת להם בזה ומשמע דלכ''ע חייב:
@86 **אלא** דטעמו של הרמב''ם שהצריך בכל שבועה שהיתה שלא בפני בית דין להיות מפי עצמו, הוא ממה דתנן שם דף ל''א ע''ב וז''ל שבועת העדות כיצד אמר לב' בואו והעידוני שבועה שאין אנו יודעין לך עדות או שאמרו אין אנו יודעין משביע אני עליכם ואמרו אמן הרי אלו חייבין, השביע עליהם ה' פעמים חוץ לבית דין ובאו לבית דין והודו פטורים, כפרו חייבין על כל וכו' ע''כ. הרי דקתני בפרוש ואמר אמן, מני מתני', אי רבי מאיר ומיירי שלא היתה הכפירה בבית דין, אם כן הוו ליה מחלוקת ואח''כ סתם שבמשנה שקדמה כתב רבי מחלוקת רבי מאיר ורבנן ובמשנה זו שלאחריה כתב סתם כרבי מאיר, וממה שמצינו שרמב''ם הצריך הכפירה בבית דין אפילו נשבע מפי עצמו אם כן מפרש מתני' כרבנן, וקתני ואמר אמן, ובמאי, שלא בפני בית דין, שאם בפני בית דין לכל הסברות אין צריך שיאמר אמן, אם כן הרי לך שלדברי חכמים צריך שיאמר אמן שלא בפני בית דין. והתוספת כתבו שטעם שאמר ואמרו אמן היא לקצר, ואין הכי נמי אם אמרו אין אנו יודעים לך עדות, ואין כן דעת רמב''ם אלא כל שהשבועה חוץ לבית דין צריך שיאמר אמן דהיינו מפי עצמו, והטעם הוא כי לא אמר הכתוב ושמעה קול הגם שלא אמר הוא מפיו אלא בבית דין שבו מדבר הכתוב דכתיב אם לא יגיד אבל שלא בפני בית דין צריך שיוציא מפיו:
@86 **והגם** שאמרו שם דף ל''ב וז''ל מנלן שהכפירה בבית דין הוא דמחייבי אחוץ לא מחייבי, אמר אביי אמר קרא אם לא יגיד וגו' לא אמרתי אלא במקום שאם מגיד זה מתחייבין, אמר ליה ר' פפא אי הכי אימא שבועה גופא בבית דין אין שלא בבית דין לא, לא סלקא דעתך דתניא לאחת לחייב על כל אחת, ואי סלקא דעתך בבית דין מי מחייב על כל אחת והתנן השביע עליהן ה' פעמים בפני בית דין וכפרו אין חייבין אלא אחת וכו' אלא לאו שמע מינה שבועה חוץ לבית דין כפירה בבית דין, משמע כי השבועה שישנה בבית דין היא עצמה אשר תהיה חוץ לבית דין ומתחייב עליה, ואם כן אפילו השביעוהו אחרים לא שנא בפני בית דין לא שנא שלא בפני בית דין. לכשנעמוד על אמתתן של דברים משם דלבית דין ומתחייב עליה, ואם כן אפילו השביעוהו אחרים לא שנא בפני בית דין לא שנא שלא בפני בית דין. לכשנעמוד על אמתתן של דברים משם דגל עמוד דינו של רמב''ם ז''ל, כי ממה שמוכיח מדתניא לאחת לחייב על כל אחת. וקשה והלא לאחת כתובה בשבועת בטוי ואנו עוסקים בשבועת העדות ואינו דומה שבועה זו לזו. ובהכרח לומר כי אינו מוכיח אלא לשבועה מפי עצמו שלמדוה שישנה בשבועת העדות משבועת בטוי בגזירה שוה דתחטא תחטא כאמור שם, ולזה מוכיח שפיר לשבועת העדות בנשבע מפיו הנלמד ממנה, אבל השביעוהו אחרים שהיא שבועה המוזכרת בפרשת שבועת העדות דוקא בבית דין הוא שחייב עליה כי אין מוכיח כלום מלאחת, ואנו חוזרים למה שדייק ר' פפא בבית דין אין שלא בבית דין לא, ולא דחה אביי לדברי רב פפא אלא למה שדקדק בדבריו שבועה וכו' שלא בבית דין לא שמשמע שאין חיוב שבועת העדות אלא בפני בית דין לזה שלל זה מדעתו, ולעולם מפי אחרים דוקא בבית דין וכדעת רמב''ם:
@86 **נמצינו** אומרים לדרך זה כי אמרו **ושמעה קול אלה** הוא שהשביעוהו והגם שלא ענה אמן, ודוקא בבית דין כמו שדייק אם לא יגיד, ואם הוציא שבועה מפיו יתחייב גם כן על פרט השבועה שחלה עליו בדין זה מגזירה שוה דתחטא תחטא דשבועת בטוי ובתנאי שתהיה הכפירה בבית דין. ומה שמסיק בגמרא שמע מינה שבועה חוץ לבית דין, פירוש ישנה לשבועה חוץ לבית דין וכגון שבועה מפיו:
@86 **ומעתה** הרווחנו פשט הכתוב לדעת רמב''ם על נכון, שמדבר הכתוב במציאות אחד והוא שמשביעין אותו בבית דין ולא הגיד בבית דין, וב' דברים אלו לעיכוב, בין ההשבעה מפי אחרים צריכה להיות בבית דין וחוץ לבית דין לא הגם שהיתה הכפירה בבית דין בזמן אחר, וכן הכפירה גם כן צריכה להיות בבית דין, וזולת זה הגם שנשבע מפי עצמו שלמדוהו מתחטא תחטא משבועת בטוי אינו חייב, והיכא שהיתה הכפירה בבית דין והשבועה שלא בפני בית דין למדינן משבועת בטוי אם נשבע בפיו חייב, והמשכיל יבין שדינו של רמב''ם מאיר, והכתוב מסייעו והאומר ששבועה מפי אחרים תועיל שלא בפני בית דין עליו להביא ראיה כי לימוד לאחת אינה אלא לנשבע מפי עצמו או השביעהו אחרים ואמר אמן דהיינו מפי עצמו:
@92 **ואם לא תגיע ידו וגו'**. פירוש הגם שהגיעה ידו ליותר מב' תורים וב' בני יונה, כל עוד שלא השיג ידו די שה חסר איסור או חסר פונדיון הרי זה מביא קרבן עני. ובתורת כהנים דרשו ידו אין אומרים לו ללות ואין אומרים לו עסוק באומנותו וכו', הטעם משום דחביבה מצוה בשעתה, וכמאמרם ז''ל (תו''כ כאן) בפסוק ואם לא תשיג ידו די שה, יש לו שה ואין לו צרכיו מנין שיביא קרבן עני תלמוד לומר **די שה** פירוש היה לו לאדם זה שה אבל הוא לו לצרכיו של זה האדם כמו שתאמר היה לו או לכסותו או למחיתו הרי הוא כאלו אין לו, והוא שדקדק לומר די שה פי' בידו להביא שה, וזה הגם שיש לו השה אין בכחו להביאו כי הוא צריך לו. וראיתי לרבינו הלל שפירש צרכיו פירוש של שה שאין לו, שהדין הוא שהוא צריך להטפל בו להביאו לעזרה, וזה דוחק כי מה טורח בזה יותר מהבאת תורים ובני יונה, ואם על גודל הכבש, יוליך בידו מעות למקדש ושם יקנה, ואם לצד שהשה צריך סמיכה, והלא סמיכה אינה מעכבת, ולמה יבטל קרבנו בשביל הסמיכה ויביא קרבן עני, ואנו שנינו בסוף מסכת נגעים עשיר שהקריב קרבן עני לא יצא, והגם שבמסת נגעים (פי''ד מי''ב) שנו לה, הוא הדין לכל קרבן עולה ויורד, וכן מוכח בדברי רמב''ם פרק י' מהלכות שגגות, אבל הסמיכה אינה אלא שירי מצוה ואם לא סמך כיפר כאומרם בריש זבחים (ו:):
@92 **שוב** ראיתי שדרשו בתורת כהנים בפרשת יולדת אם לא תמצא ידה וגו' יש לה שה ואין לה צרכיו מנין שתביא קרבן עני תלמוד לומר די שה ע''כ. הנה דרשה זו צריכה לענין נסכים כי הנסכים מעכבין וקרבן יולדת עולה הוא שטעון נסכים, ומעתה ריבוי זה שריבה הכתוב בפרשה זו של חטאת מה הוא, אם לסמיכה, קשה למה אצטריך לומר די שה בעולה והלא קל וחומר הוא אם בחטאת שאין צרכיה מעכבין מכל שכן שיביא קרבן עני בשבילה עולה שצורכיה מעכבין מכל שכן שיביא קרבן עני אלא ודאי נראה כמו שכתבתי, וכן ראיתי שהסכים הרב בעל קרבן אהרן:
@95 **מחטאתו אשר חטא**. טעם שבקרבן עשיר אמר (פסוק ו) מחטאתו ובקרבן עני אמר מחטאתו אשר חטא. יתבאר על פי מה שפירש בתורת כהנים (לקמן פסוק יג) בקרבן דלי דלות, יכול החמורים שבהם יהיו בכשבה ושעירה הקלים יהיו בתורים ובני יונה, הקלים שבקלים יהיו בעשירית האיפה, תלמוד לומר מאחת מאלה להשוות הקלים לחמורים וכו' ע''כ. פירוש לפי שיש בפרשה זו ג' מיני חטאות טומאת מקדש וקדשיו שיש בה עונש כרת זו חמורה מכולן, ושבועת העדות שחייב על זדונה ושגגתה, זו קלה משלפניה וחמורה משלאחריה שהיא שבועת ביטוי שאינו חייב אלא על שגגתה, יכול החמורים וכו'. קשה איך יכול אדם לומר כן והכתוב אומר ואם לא תגיע וגו' משמע שבמציאות עצמו שחייב כשבה ושעירה הוא מדבר. וכן אם לא תשיג ידו וגו' שבדלי דלות. וראיתי להרא''ם שפירש ואם לא תגיע שלא נגעה ידו במעל שחייב בעבורו כשבה וכו' אלא למעל קל ממנו המוזכר בפרשה יביא ב' תורים וגו', ואם (לא) השיג ידו במעל שחייב להביא בעבורו ב' בני יונה וגו' ע''כ. ולדרך זה יתישב אומרו **מחטאתו אשר חטא**, לצד שחלוקה זו היא חלוקת הקלים שהיא שבועת העדות, כדי שלא תטעה שאין קרבן זה של עוף אלא לחטא זה הקל אבל לחמור ממנו שהוא טומאת מקדש וקדשיו אין עוף בא אפי' בעניות, תלמוד לומר מחטאתו אשר חטא, ב' חטאות נאמרו, א' לשבועות העדות, וא' לטומאת מקדש וקדשיו שלא תטעה בו כנזכר, וחזר הכתוב בפרשת דלי דלות וריבה אפילו לענין עשירית האיפה שישנה בכל הג'. אלא שנראה בעיני פירוש הרא''ם ז''ל דחוק ביותר, כי איך יקבל הרעת לפרש אומרו אם לא תשיג ידו שהכוונה היא לחטא יותר כמו זר נחשב הענין:
@95 **ואולי** נוכל לפרש כונת התנא על זה הדרך, שאם לא אמר הכתוב מאחת מאלה הייתי אומר החמורים שבהם שהוא טומאת מקדש וקדשיו קרבנם קבוע בכשבה, ומה שאמר הכתוב ואם לא תגיע ידו די שה והביא תורים ובני יונה לא לכל הוא אומר אלא לקרבן הקל שבכולן הוא שהקיל בכפרתו שהגם שבעושרו חייבו כשבה בעניו אם לא תגיע ידו לכשבה יביא תורים, והבא לומר שיועיל גם לחמור עליו להביא ראיה, וגם אומרו ואם לא תשיג ידו לב' תורים וגו' יביא עשירית האיפה הייתי אומר על הקל שבקלות הוא אומר שיועיל קרבן זה שהוא שבועת בטוי, ולא על שבועת העדות שהיא חמורה, ואין צריך לומר טומאת מקדש וקדשיו שלא יקיל בו ה' לכפר עליו בעשירית האיפה, והייתי דן לחזק זה ממה שמצינו שקבע ה' קרבן כשבה ושעירה לכל השגגות כאמור בפרשה שלפניה, למה יגרע כרת זה של טומאת מקדש וקדשיו, הא ודאי לא בא קרבן עולה ויורד אלא על הקלין. והוא על סדר זה העשיר יביא על כולן כשבה ושעירה הדל הקל בו הכתוב להביא תורים ובני יונה על שבועת העדות אבל על טומאת מקדש וקדשיו לא יצא מכלל החטאות שחייב בפי' שלפני' דכתיב נפש וגו' כי תחטא בשגגה, דלי דלית הקל בו הכתוב להביא עשירית האיפה על שבועת בטוי, אבל על שבועת העדות שהיא חמורה לא יביא עשירית האיפה, וזה הוא עיקר הטעות שהייתי טועה בענין, דתלמוד לומר מאחת מאלה הרי השוה הכתוב את כולן להביא אפילו על טומאת מקדש וקדשיו עשירית האיפה ומכל שכן תורים ובני יונה, והוא כוונת התנא שאמר יכול. אלא מה שאמר בחלוקת השואת קלים לחמורים, כדי נסבה, ואין עיקר הטעות שעליו בא הכתוב אלא חלוקות השואת חמורים לקלים:
@95 **עוד** נראה לפרש דברי התנא על זה הדרך לפי שסדר הכתוב ג' מיני חטאות, ורואני כי יש בהם ג' הדרגות, ובא לסדר החטאות הצריכין לכפרה, התחיל בחמור שבכולן ואמר יביא כשבה ואם לא תשיג ידו יביא קרבן השייך למה שלפניו שהוא שבועת העדות ב' תורים וגו' או ב' בני יונה שהוא בא על שבועת העדות בין בעשירות בין בעניות ועל טומאת מקדש וקדשיו בא בדלות ולא בעשירות, ואומרו ואם לא תשיג ידו פירוש על שבועות העדות הוא אומר שקבוע לו תורים ובני יונה אם לא תשיג ידו הרי זה מביא קרבן הקבוע לשבועת בטוי. נמצאת אומר על שבועת בטוי מביא עשירית האיפה קבועה ואפילו עשיר, על שבועת העדות בעשרו יביא תורים ובני יונה ובעניו יביא עשירית האיפה, על טומאת מקדש וקדשיו עשיר יביא כשבה או שעירה בעניו יביא תורים ובני יונה אבל לא עשירית האיפה, והוא מאמר התנא החמורים שבהם יהיו בכשבה פירוש הם הוא שיביאו כשבה ולא הקלים שהם שבועת העדות ושבועת בטוי ואפילו בעשרם. ולא חש התנא עליך שתטעה שיהיו בכשבה לבד ולא בתורים ובני יונה. שהרי תברך בצדך ואם לא תגיע ידו, אלא לומר שאין הקלים בכשבה, ואומרו הקלים בעוף פירוש הם יביאו ולא קל שבקלים שהם בעלי שבועת בטוי יביאו עוף אלא עשירית האיפה. ולא חש עליך לטעות שאין מביא על שבועת העדות עשירית בעוני, שהרי כתיב ואם לא תשיג וגו'. נמצאת אומר שאין כשבה אלא בחמור ולא בב' קלים, ואין עוף בקל שבקלים אלא בקל. ואומרו הקלים שבקלים יהיו בעשירית האיפה פירוש ולא החמור שהוא טומאת מקדש וקדשיו בעשירית האיפה. ולא חש עליך לטעות שבא לשלול שבועת העדות שהרי בהדיא כתיב ואם לא תשיג סמוך לו, גם אין לומר שבא לשלול שאין קל שבקלים בתורים ובני יונה ואין צריך לומר בכשבה, שהרי דבר זה הוא מה שפירש באומרו החמורים שבהם בכשבה לשלול הקלים ואין צריך לומר קלי קלים, ומעופות גם כן הוא מה שמיעט באומרו הקלים בעופות לשלול קלי קלים מעופות. נמצאת אומר שבועת בטוי אינה אלא בעשירית האיפה ולא בתורים ואין צריך לומר בכשבה, ושבועת העדות אינו אלא בתורים ובני יונה ובעוני בעשירית האיפה ולא בכשבה, וטומאת מקדש וקדשיו אינה כל עיקר בעשירית האיפה אלא בעושר כשבה ובעוני תורים ובני יונה, תלמוד לומר מאחת מאלה פירוש מהשלשה חטאות האמורות יביא עשירית האיפה על כל אחת מהשלשה והשוו גם קלים לחמורים מאומרו מאחת מאלה על זה הדרך על חטאתו אשר חטא מאחת פירוש מאחת שתהיה לא על הקלים לבד אלא על כולן. מאלה חזר והשוה אותם פעם ב' לומר כי אלה שוים הם להביא קרבן כשבה גם על הקלה שבקלות בעושרו. או סובר התנא כי מאומרו אחת מאלה השוה אותם לכל מה שבזה יש בזה. ואין לומר שסובר התנא כיון שהשוה הכתוב החמור לקל בעשירית האיפה מכל שכן הקל בכשבה. זה אינו כי אנו על החיוב אנו דנים לחייבו ומנין לנו לחייבו:
@95 **עוד** נראה לומר כי התנא דורש השואת קלים לחמורים שיביאו כשבה ממה שאמר הכתוב בתחילת הפרשה (פסוק ה) והיה כי יאשם לאחת מאלה וגו' והביא את אשמו וגו' כשבה, הרי שהשוה אותן קלין לחמורים, וכאן השוה חמורים לקלים, והגם שקבע הדרשה מפסוק א' סמך על פסוק אחר לבא להקשות, וקבע שני החלוקות במקום א', וכן דרך התנא:
@95 **ובזה** אין אנו צריכין לדוחקו של רא''ם שאמר כי פסוק ראשון בא להשוותם לוידוי האמור שם, שזה דוחק, כי כשהשוה אותם הכתוב ואמר והתודה והביא את אשמו מנין תמצא לחלק ולומר שלא השוה אלא לסמוך ממש, כי במה חלק הכתוב למאמר והביא את אשמו אדרבה וא''ו סמכיה:
@95 **ומעתה** נבוא לדייק אומרו מחטאתו אשר חטא על זה הדרך, שלא תאמר שאין קרבן זה של עוף בא אלא על הקל, שהוא שבועות העדות, אבל החמור שהוא טומאת מקדש וקדשיו לא, תלמוד לומר אשר חטא לרבות חטא חמור, וכשהזכיר פרשת דלי דלות ריבה גם כן עשירית האיפה בכולן, מאומרו מאחת מאלה, ואפילו בטומאת מקדש וקדשיו:
@95 **ואם** תאמר ישמיענו בקרבן דלי דלות שישנו בחמור ומכל שכן קרבן דלות, נראה לומר כי לצד שבדלי דלות אמר ואם לא תשיג ידו לשתי תורים ולא אמר כאומרו בפרשת דלות. ואם לא תגיע ידו די שה, ודרשו בתורת כהנים אפילו יש לו שה אם אין לו צרכיו, הרי זה מביא קרבן עני, ופירשנוהו למעלה:
@95 **והנה** דרשת התנא היה ממה שלא אמר כמו שאמר כאן ואם לא (תגיע) [תשיג] ידו לשתי תורים, וכן פירש בעל קרבן אהרן, ופשוט הוא, אם כן כאן שלא אמר הכתוב די שתי תורים, הדברים מוכיחים כי אם יש לו הרי זה חייב להביא, אפילו הוא צריך להם, ומעתה הוצרך הכתוב לרבות בעוף שיביא להחמור שהוא טומאת מקדש וקדשיו, הגם שהיה לו כבש, אם הוא צריך לו, והבן:
@95 **גם** מה שפירש רבינו הלל ואין לו צרכיו, של שה קאמר, יוצדקו דברינו, כי השמיענו שיפטר בזה גם לחמורות שהוא טומאת מקדש [וקדשיו] מה שלא היה נשמע זה מקרבן עשירית האיפה:
@106 **נפש כי תחטא ומעלה וגו'**. צריך לדעת למה אמר כי תחטא, ואין לנו לפרש כאן כי החטא הוא ההכחשה, שהרי הוא אומר וכחש בעמיתו. עוד אומרו מעל בה' מה שלא אמר בכל החטאות. עוד אומרו וכחש בעמיתו שלא היה צריך לומר בעמיתו. גם שיעור התיבה אינו מדוקדק:
@106 **ואולי** כי יודיע הכתוב שלשה ענפי רשע שיעשה בעל עבירה זו. הא' נטילת דבר שאינו שלו, הוא ענף הגזל. ב' ומעלה מעל בה', פירוש בה' כביכול עשה המעל פירוש לשון שינוי, כי הוא שפט על פי המעשים וזיכה לזה שיהיה לו ממון, וכשזה בא וגוזלו נמצא שגורם מעילה בה' ששינה עליו את הדין, שלא עמד בידו ממה שהגיעו כפי משפט ה', ונמצא ה' כביכול נחשד שלא עשה משפט צדק, ואולי שכפל לומר ומעלה מעל, ולא הספיק לומר ומעלה בה', נתכוין לכלול גם כן צד הגזלן, כי גם לצדו מעל בה' כביכול כי הוא דנו בחסרון הלקוח, והוא נוטל מה שלא נקצב עליו במשפטי ה'. ג' וכחש בעמיתו, פירוש שמרשיע את הצדיק כשתובע ממנו פקדונו וכו' והוא אומד לו לא היו דברים מעולם, ומשימו מכחש, והוא אומרו וכחש בעמיתו, פירוש משים הכיחוש בעמיתו, שהוא הנגזל ממנו, משימו רשע, שתובע דבר שאינו שלו ואומר לו למה תשקר עלי ויריב עמו. והנה ב' דברים אלו אינם אלא בפקדון או בתשומת יד או בגזל כשגוזל ממנו את שלו, או עושק שכר שכיר, אבל במצא אבדה אין בה כחש בעמיתו, לזה אמר הכתוב בפני עצמה, או מצא אבדה וכחש בה וגו':
@106 **עוד** ירמוז שלשה דברים רעים הגורמת הנפש המרשעת. הא' היא נחסרת מאורה וממעלתה, והוא אומרו נפש כי תחטא לשון חסרון בנפש עצמה. ב' ומעלה מעל בה' על דרך אמרו אנשי אמת כי אין לך נפש מישראל שאין שפע נשמתו יורד לה להתקיים שזולת זה אין לה חיות, זולת הנפש אשר עלתה צחנתה ובאשה בעון פלילי לזה יכרת ממנה השפע האלהי, כאומרו (בראשית יז יד) ונכרתה הנפש ההיא, ודרך השפע בא דרך ב' חוטין דקים, דרך ב' נקבי האף, והוא דרך מקום דביקות הנפש עם קונה, כאומרו (דברים ד ד) ואתם הדבקים בה' אלהיכם:
@106 **והנה** בחטא האדם מהחטאים כאלה הנפש ההיא שולטים בה ובשפעה החיצונים כידוע, ונהנים מהשפע האלהי הרשעים ההם, וזהו אומרו ומעלה מעל בה', כביכול באור הנמשך ממנו, והוא סוד הרמוז באומרו (משלי כח ד) גוזל אביו ואמו וגו' חבר הוא לאיש משחית, פירוש לצד שמתחבר לבחינת הרע הנקרא איש משחית, והבן:
@106 **הג'** כי גם לכללות הקהל הוא גורם הכחשה, פירוש לצד שכל ישראל כאחד רעת אחד תסובב רע לכל הנצר, והוא אומרו וכחש בעמיתו שנעשית עמיתו כחושה מצדו רחמנא ליצלן, והוא מה שרמוז בפסוק (שם) גוזל אביו ואמו ואמרו ז''ל (ברכות לה:) אמו זו כנסת ישראל כי באמצעות אנשי חיל מתרבה בכללות עם ה' השלום והטוב והחיים:
@106 **חסלת פרשת ויקרא**
@113 **צו את אהרן**. אמרו ז''ל בתורת כהנים (עי' קידושין כט.) אין צו אלא זירוז מיד ולדורות, אמר רבי שמעון ביותר צריך הכתוב לזרז כל מקום שיש בו חסרון כיס, עד כאן. הנה לתנא קמא יש כאן זירוז, לצד מה שגדלו פרטי דיני העולה בלילה, מה שאין משפט דומה לה בכל הקרבנות, לזה זרזו מיד פירוש לאותו זמן יתנהג, כמו שלמדו בתורת כהנים מפרשת נרות דכתיב (להלן כד ב) צו את בני ישראל ויקחו אליך וגו' וכתיב (במדבר ח ג) ויעש כן אהרן, לדורות, פירוש שיתנהגו משפטי העולה ככתבן לדורות, שאמרו ז''ל (פסיקתא פסוק את קרבני לחמי במדבר כח ב) וז''ל לפי שהיו ישראל אומרים לשעבר היו המסעות נוהגים והתמידין נוהגים, פסקו המסעות פסקו התמידין, עד כאן:
@113 **הרי** שיש מקום לטעות שלא תנהוג לדורות, וחסרון כיס שאומר רבי שמעון רבו בו הפירושים, יש אומרים לאו דוקא חסרון כים, אלא הוא הדין ריבוי הצער, ויש אומרים כי היה בטל ממלאכתו כל הלילה, והוא חסרון כיס, ויש אומרים חסרון כיס הוא לישראל, שאברי עולה נשרפין על המזבח ואינם נהנין מהם, ויש אומרים חסרון כים לכהן, שהוא ירצה להקריב קרבנות אחרים שיש לו זכות בהם, מה שאין כן העולה שכולה כליל ואין לו בה אלא העור, וכל הדברים רחוקים בעיני:
@113 **ואולי** נראה שהוא על התמדת עצים שאמרו ז''ל (יומא מה.) ג' מערכות של אש היו שם וכו', שלישית אין עליה כלום, אלא לקיים אש תמיד תוקד וגו' עד כאן, על פרט זה אמר חסרון כים פירוש ללא דבר, שאין בו אחד מהקרבנות, אלא שתהיה האש אוכלת עצים כל הלילה, וגם הם שוים ממון:
@113 **עוד** נראה כי חסרון כיס הוא, לצד שמצות עולת תמיד עשה בה הכתוב דבר גדול, דכתיב (להלן פסוק ה) ובער עליה הכהן וגו' וערך עליה העולה, ותנו רבנן בתורת כהנים מנין שלא יהיה דבר קודם לתמיד של שחר, תלמוד לומר עליה העולה עד כאן, ותניא בתוספתא דפסחים כל הקדשים שהקריבן קודם לתמיד של שחר וכו' פסולים וכו' עד כאן:
@113 **הא** למדת אם אין עולה כל הנעשה קודם לה פסול, ומזה ישתלשלו דברים רבים שיש בהם חסרון כים, הרי שהביא כבש בן שנתו, ואם היה מקריבו סמוך להבאתו היה כשר, ולצד שאומרים לו עמוד (עד) שיקריב תמיד של שחר הרי זה הפסידו בשהיית שעה אחת, כי מונין שעות לקדשים, כדאיתא בפרק ב' דזבחים (כה:) ובפרק על אלו מומין (בכורות לט:):
@113 **וכן** משכחת לה אם קמץ והקטיר קודם הרי זה פסול, גם משכחת לה שיהיה זמן שלא היה להם כבשים להקריב, בזמן שהיתה ירושלים במצור ואין מציאות לעבודת בית אלהינו להקריב קרבן מהקרבנות הבאים משאר בעלי חיים, והמנחות והקטורת, וצריכין ישראל לתת ממון רב בכבש לצד שאין מציאות להקריב עד שיקדים:
@113 **וכן** תמצא (ב''ק פב:) שהיו משלשלין להם קופה מלאה דינרי זהב בעד כבש אחד, ואין לך חסרון כים גדול מזה, ואולי שאם לא היה העיכוב הנזכר לא היו נותנים כל הפלגה בכבש אחד בכל יום ובפרט מנכסי גבוה:
@113 **לאמר**. אין ידוע למי יאמרו, ואם לדורות, הרי דבר זה נשמע מאומרו צו, כמו שכתבנו בסמוך, ואם לומר לישראל כדי שיכינו העולה ומכשיריה ועצי המערכה, הרי אמר וידבר ה' וגו' לאמר:
@113 **ואולי** כי ציוה עליו שיאמר לאהרן דרשות הרמוזות במכתב אלהים, והדקדוקים אשר יכוין להם הכתוב, כי הפסוק הוא כחזון הסתום, ומה שתמצא שדרשו רבותינו ז''ל אינו אלא לפי מה שקדם אליהם מההלכות שנאמרו למשה בסיני, ואותם ציוה ה' לאמר לאהרן:
@113 **או** ירצה לצד שהכשיר עולים על המזבח, הגם שנפסלו כאמור בדבריהם (בתורת כהנים) בפירוש הכתוב, לזה ציוה שיאמר להם שישתדלו לבל יעלו מן הפסולין, בראותם כי אינם יורדין יחשבו כי אין קפידה כל כך בעלייתם ולא יתנו עליהם לב לשומרם לבל יעלו, לזה ציוה לאמר להם, שישמרו שלא תעלה אלא תורת העולה, פירוש עולה כתורתה וכמשפטה בלא לינה בלא יציאה וכו':
@113 **זאת תורת העולה וגו'**. רבי יהודה דרש (תורת כהנים כאן) ג' מיעוטים, זאת, היא, וה''א של העולה שניה, למעט נשחטה בלילה, ושנשפך דמה, ושיצא דמה חוץ לקלעים, אלו אם עלו ירדו, אבל הלן, וזבח היוצא, והטמא וכו', אם עלו לא ירדו, וכל שאר הפסולין אם עלו לא ירדו, כי תיבת תורת ריבוי הוא:
@113 **וזה** שיעור הכתוב זאת תורת העולה היא העולה, פירוש כל שעלתה על מוקדה וכו', תורת עולה יש לה, ואין לך בה פסול אלא קודם שעלתה, אבל אם עלתה על מוקדה על המזבח, תורת עולה יש לה בכל גוונא, וכל הפסולין טהרם המזבח זולת ג' דברים שמיעט כנזכר, שלא היה לו לומר אלא תורת העולה עולה על מוקדה ואמר זאת, ואמר הא, ואמר היא, למעט כנזכר:
@113 **היא העולה**. כתב רש''י ז''ל מיעט הרובע כו', לא ידעתי למה בחר יותר לפרש הכתוב אליבא דרבי שמעון ולא אליבא דרבי יהודה, שכתב למעט הנשחט בלילה, ושנשפך דמה, ועוד לא דקדק יפה הרב בלשונו, שלא כתב המיעוטים בזאת אלא בהיא העולה, ורבי שמעון מזאת דריש:
@113 **ופשוט** אצלי כי ממיעוט זאת לבד דריש רבי שמעון ולא מהיא העולה, כי אין צריך לרבי שמעון מיעוטים רבים לפרטים שאמר בהם, אם יעלו ירדו, כמו שמיעט רבי יהודה ג' [פרטים] מג' מיעוטים, שאם באנו לומר כן צריכים אנו למיעוטים רבים מלספור, כי רבים הם הפרטים שהזכירם רבי שמעון שעליהם בא המיעוט, אלא ודאי כי ממיעוט אחד מיעט הכל, כל שאין פסולו בקודש אין הקודש מקבלו, וכיון שאין צריך אלא מיעוט אחד וקתני ליה בברייתא (זבחים פד.) תלמוד לומר זאת, מנין לרש''י לומר שדורש היא העולה:
@113 **ותמצא** שאמרו בהוריות (ב:) על מתניתא דקתני נפש אחת וכו', הרי אלו מיעוטין העושה מפי עצמו וכו', ומוקי הש''ס הברייתא כרבי יהודה, ופריך דלמא רבי שמעון היא, ומשני מאן שמעת ליה דדריש מיעוט כהאי רבי יהודה, דתניא זאת תורת העולה היא העולה הרי אלו מיעוטין, הרי כי רבי שמעון לא דריש מיעוט:
@113 **על מוקדה על המזבח**. יתבאר על דרך אומרם בפרק המזבח מקדש (זבחים פה:) כל אלו שאם עלו לא ירדו אם ירדו לא יעלו, אמר עולא לא שנו אלא שלא משלה בהם האור אבל משלה בהם האור יעלו, והגם דאיכא התם מאן דמתני אסיפא דעצמות והגידים והקרנים וכו', הרי מסיק בגמרא דלא נפקא פלוגתא אלא בסיפא, אבל ברישא דרישא האברים והאמורים הפסולים שנתרבו מהעולה שאם עלו לא ירדו ואם ירדו לא יעלו, לכולי עלמא אם שלט בהם האור יעלו הגם שירדו:
@113 **ולזה** אמר הכתוב, כנגד אותם שמשלה בהם האור על מוקדה, וכנגד אותן שעדיין לא משלה בהן האור אלא עלו למזבח אמר על המזבח, וחלקם הכתוב לצד שישתנו בדינם, על מוקדה תעלה הגם שירדה, אבל מה שהוסיף הכתוב לומר על המזבח, דוקא אם עלתה ולא ירדה:
@113 **ולזה** הקדים הכתוב לומר על מוקדה, קודם אומרו על המזבח, ומן הראוי יקדים עליית המזבח כי אינה מוקדה אלא אחר שקדם המזבח, אלא נתכוון לרשום הדרגה ראשונה שבה יחזור הפסול כשר ממש לענין אם ירדו יעלו, ואחר כך אמר הדרגה שנייה שאין בהם הסרת פסול, אלא כל עוד שהם על המזבח כנזכר:
@113 **ובתורת** כהנים נחלקו רבן גמליאל ורבי יהושע, רבן גמליאל סובר על המזבח, כל דבר שראוי למזבח אם עלו לא ירדו, ואפילו נסכים, ורבי יהושע סובר על מוקדה דוקא ולא נסכים וכו', ושבעים פנים לתורה (זוה''ק ח''א מז:):
@113 **ובדרך** רמז תרמוז כל הפרשה על גלות האחרון שאנו בו לנחמנו מעצבון נפשנו, כי כל איש ישראל מאנה הנחם נפשו בראות אורך הגלות, נראה למי דומה, למצרים ת', לבבל ע', לשניהם יחד ת''ע, והן היום אלף ותרע''ב מה אייחל עוד, ולא גלות לבד אלא ענוי מהאומות כי כל גוי וממלכה בבני ישראל יעבודו, ואשר זה יסובב חשוב לא טוב, כי שפת אמת לא הוכרעה בכוננת והאריכה לשון שקר, ובא הצופה ומביט עד סוף כל הדורות קורא הדורות מראש והודיע למשה לזרז לישראל ובראשם בני תורה שפתי כהן אשר תורה יבקשו מפיהו אהרן ובניו להודיע לדורות את הדבר הזה, **זאת תורת העולה**, אמר זאת למעט כל העליות שאין כמוה עולה, וחזר ופירש מי הוא זאת, ואמר **הוא העולה** כבר דכתיב (שה''ש ג) מי זאת עולה מן המדבר. על מוקדה על המזבח הם ב' פרטים שאנו בהם, הא' שאנו בני תורה מה שאין בכל האומות, והב' שאנו מיוסרים בגלות ויסורין ודלות, כנגד התורה אמר **על מוקדה** שנמשלה התורה לאש, וכן תמצא שאמרו ז''ל (תענית ד) האי צורבא מרבנן דרתח אורייתא וכו', וכנגד הגלות וענפיו אמר **על המזבח** כי היסורין מתיחם להם שם מזבח להיותם כפרה, וכן הוא בלשון חכמים (ברכות ה). והודיע הכתוב כי באמצעות ב' דברים תהיה עלייתנו מיועדת בהפלגות המעולות משונות לשבח שבחים אשר לא היה ולא יהיה. וביאר עד מתי יהיו ישראל בגדר ב' דברים אלו, **כל הלילה** שהוא זמן הגלות הנמשל ללילה שומר מה מלילה (ישעי' כא) וכן בפסוק ליני הלילה דרשו ז''ל על הגלות עד הבוקר שהוא זמן שיריק עלינו כבודו ואתא בוקר, והזמן הוא אחר עבור ת''ק לאלף הששי, לפי מה שקדם לנו מדבריהם ז''ל (ב''ר יט) כי יומו של הקב''ה אלף שנה, ומהשכל יהיו ת''ק ראשונה מדת לילה ות''ק שניה מדת יום, והודיע ה' כי עד הבוקר שכשיגמר ת''ק שנה בגלות עד הבוקר שיהיה העליה, ובוקר זה אין אני יודע אם בוקר של אלף הה' או בוקרו של אלף הו' כי באלף הד' גלה כבוד ישראל בעקב''ו, לזה גילה ה' סודו ביד עבדיו הנביאים כי הוא לבוקר ב', והוא אומרו (ישעי' לג) הי' זרועם לבקרים לב' בקרים לבוקר ב' אם לא לבוקר א'. ולזה אמר עד הבוקר הידוע שהוא ב' ולא בוקר הבא ראשון בגלות. ואולי כי לזה רמז הנביא באומרו (ישעי' כא) אמר שומר אתא בוקר וגם לילה פי' הגם שאתא בוקר ראשון לא הועיל ובא גם כן הלילה אחריו כי לא נושענו בו. ואולי כי אלו ישראל היו שלמים היו נגאלים בבוקר ראשון:
@113 **והוא** מה שרמוז בדבריהם שלא נגזר על ישראל גלות אלא יום אחד דכתיב (תהלים כ) יענך ה' ביום צרה פירוש יומו של הקב''ה, ולא נשארים אלא תרע''ב שהם עק''ב שנשארו מאלף הד' ות''ק של אלף הה' הרי תרע''ב ובבוקרו היו נגאלים, ולצד מעשיהם הרעים עכב ויעד בוקר ב', ולזה נתכוון באומרו (ישעי' לג) ה' חננו לך קוינו וגו' פירוש קוינו להיות הגאולה בבוקר א' שלא לעכב עד בוקר ב', אבל על כל פנים היה זרועם לבקרים כשיעברו שנים. ואומרו **ואש המזבח תוקד בו** יודיע הכתוב כי באור בוקר תעשן אף ה' ואש מפיו תאכל על אשר עינונו בני עולה ויסרונו ביסורי נקמה ובפרט בני המערב הפנימי אין לך כוס מר שלא הטעימו תמיד, והוא אומרו ואש המזבח שרמזנו בו בחינת היסורין מהאומות ולא ריחם לבם לאשר הכה ה' זה ימים והשפיל גאון יעקב, ולא נהג בם בחינת דיראון, לומר די ראות עליוני עליונים למטה מטה, אש מזבח זה תוקד בו בנעלם הנעלמים כי הוא המקנא ולובש קנאה ורמז גם כן באומרו ואש המזבח לבחינת עקדת יצחק, גם המזבח יגיד אל בחינת הדין כי יתעוררו הדינים ויתגברו, והוא סוד אומרו **תוקד בו** והבן.
@113 **ולבש הכהן מדו בד** ירצה למדת החסד והרחמים כי יתכנה בשם כהן, הכוונה שגם החסדים יסכימו לנקום נקם, ועיין מה שפירשתי בפרשת וארא וגו' בפסוק (ו' ב') ויאמר אליו אני ה', ואומרו מדו בד יתבאר על דרך אומרם ז''ל כי כל נפש שהורגים האומות מישראל על קידוש שמו ית' הקב''ה רושם מדמו צורת הנהרג ההוא במלבוש ואותו ילבוש יום נקם בלבו, והוא אומרו מדו אשר בו אותם שהם בד שהם ישראל אשר הם (בלק כג ט) עם לבדד ישכון ושורשה בד. גם ירמוז אל האחדות שהם נהרגים על אשר לא יחפצו לשתף שם שמים ודבר אחר ומיחדים שמו יתברך, ואומרו **ומכנסי בד** ירמוז למה שהרגו האומות מהאנשים הנגשים אל ה' המכניסים אמונת ה' ואחדותו בלב ישראל, והם הם יקירי אל עליון אשר אין דבר מפסיק בינו לבינם, והוא מה שדקדק לומר ומכנסי בד לשון הכנסה. בד הוא בחי' האחדות, לאלה אמר על בשרו פירוש אין דבר מפסיק בינם לבין ה', ואמר **בשרו** לשכך את האוזן על דרך אומרו (ירמי' יג) כאשר ידבק האזור אל מתני איש וגו', (במדבר יא א) באזני ה', עיני ה' (תהלים לד), ולצד מה שעשו להצדיקים הללו יחתם גזר דין לאומה רשעה, ואומרו **והרים את הדשן** כנגד מה שהריעו בבחינת היסורין והעינויים אשר צררו אותנו, ואם באת לראות הוא יותר מגלות מצרים, כי גלות מצרים היו משעבדים אותם ומאכילים אותם ומלבישים אותם, וצא ולמד ממה שאמרו ז''ל (מכילתא וילקוט) בפסוק זכרנו את וגו' את הקשואים וגו' חנם היו אוכלים הכל, והן גלות ישמעאלים אשרי מי שלא ראם משעבדים וממררים חיי ישראל, ולא די שלא יתנו שכר אלא עוד שואלים ממנו מדוד והבא, ועוד אדם נגזל במה שיש לו והם תובעים ממנו מה שאין לו, וכוס זה ישקוהו עד שימות, וכנגד זה אמר **והרים** אל מרים ראשי את הדשן אשר תאכל האש אש העמים, כי מצינו שצרת האומות תקרא אש, וצא ולמד מאש בין הכרובים (יחזקאל י) את העולה שהיא האומה הנקראת עולה:
@113 **ואומרו** על המזבח יתבאר על דרך מה שנחלקו רמב''ם (הל' תשובה פ''ו) וראב''ד בענין משפט העובדי כוכבים המענים אומתינו, כי הראב''ד סובר שישפטו על אשר הרעו יותר מהקצוב להיותם בעלי בחירה ורצון. ורמב''ם סובר כי ישפטו גם על העיקר, וכבר כתבתי בפרשת בין הבתרים (לד טו יד) כי האמת הוא שישפטו על הכל בטוב טעם. ומחדש אני דובר כי מהתוספת יוקח ראיה אל העיקר, שאם כונת המענים לקיים מצות ה' היה להם שלא להוסיף וממה שהוסיפו גילו דעתם כי לא למצוה יכוונו. והוא אומרו על המזבח פירוש ביתר על השיעור שהוא לכפרה שקצב ה' להם אותו שיעשו ביותר מהקצוב, **ושמו אצל המזבח** שהוא הקצוב לכפרה וידין ממנו כי לא למצות ה' הם מתכוונים, שהיתר יגלה על בחינת הנגזרה לכפרה אם לה מתכוונים או בשנאה להרע לבד ונמצאים מתחייבים על הכל. או ירצה כי הגם שעדיין לא שלמו ימי גלות יבוא ה' למנין הנותר מהצער הקצוב אשר הוסיפו בני עולה לענות ושמו אצל המזבח להשלים בו כפרה הצריכה אשר קצב ה' בגזרת הגלות:
@113 **עוד** ירצה כי יקריב מעשה הצרות לפני מדת הדין שמתיחסת למזבח כדי לנקום נקם מאויבינו. ואומרו **ופשט** וגו' להיות שבגדים הראשונים הם לעשות משפט בעושי רעתינו ועכשיו בא להטיב להוציאנו מהגלות ולהטיב אותנו, לזה ילבש בגדי בחינת ההטבה, כי לא יעכב קיבוץ גליות עד כלות עושי רשעה אלא תיכף ומיד יקבץ נפוצותינו ויוציא אותנו ממחנה האנשים הרשעים **אל מקום טהור** היא ארץ ישראל הטהורה כי ארץ העמים היא טמאה היא ועפרה ואפילו אוירה (שבת טו) ואין לך מקום שיקרא טהור זולת ארץ הקדושה. גם ירמוז באומרו **מקום טהור** מקומו של הקב''ה הנקרא טהור כביכול, ואומרו **והאש על המזבח** פירוש לא תדמה כי אין צרה לעושי רשעה אלא הרעה ההיא אשר יעשה ה' בהם שפטים בהוציא אותנו מביניהם, לא כן אלא והאש היא בחינת אש המשפט לא תכבה, **וביער עליה הכהן עצים** הם האומות שהם עצים יבשים על דרך אומרו (דברים כ יט) כי האדם עץ וכן אמרו ברבות (בפתיחתא איכה ר') וזה לשונם העצים אלו הגליות ע''כ. ואומרו **בבקר בבקר** ירצה לפי מה שהקדמנו כי זמן הגאולה היה ראוי להיות בבקר ראשון של שנת הת''ק לאלף החמישי ולסיבת העון נתעכב עד בוקר ב', ואמר הכתוב כי לא מפני זה יזכו האומות ולא יבא עליהם מה שהיה צריך לבא עליהם בבוקר ראשון, לו יהיה שישראל לא זכו ליגאל אף על פי כן לא ימלטו האומות מהצרה שהיתה עתידה לבא עליהם אז ויביא ה' עליהם מה שנתחייבו בבוקר ראשון ובוקר ב':
@113 **ואומרו** וערך עליה וגו' יתבאר על דרך אומרם ז''ל (ב''ק פ''ג) הכל לפי המבייש והמתבייש, כי אינו דומה נכבד המבייש נכבד לבזוי המבייש נכבד ואין צריך לומר עבד המבייש את רבו, והוא אומר וערך עליה העולה שהוא האומה הישראלית בכללותה. **והקטיר עליה** פירוש יעריך גם כן בחינת הצדיקים השלמים מובחרי ישראל שלמים שבהם המעלים ריח בשמים על דרך אומרו (תולדות כז כז) ראה ריח בני כריח שדה ותדע כי כל העובר עבירות ריחו נודף לרעה, והמעשה שהובא בדבריהם (קב הישר פ''ז) שהיה עובר אליהו וראה אדם רשע ומנע עצמו מהריח ריחו הרע יותר ממה שהרגיש בעוברו על סרחון נבילה, ובהפך יהיה לאיש צדיק שלם שיעלה ממנו בושם כריח הגן, לזה זכר זכרון עריבתם בלשון הקטרה, והמכוון כי ישפוט בפרטות את אשר הריעו לאנשי בושם:
@113 **עוד** ירצה כי כאשר יעריך ה' את העולה לנקום נקמתה מהמריעים לא יעריכנה בפני עצמה אלא יקטיר עליה המובחרים והשלמים שבאומה שיקראו בשם חלב השלמים שבזה תגדל מעלתה של האומה לנקום נקמה גדולה משונאיה. ואומרו **אש תמיד** וגו' פירוש הגם שיכה ה' בהם מכה רבה לא תכבה אש ותמיד תוקד על המזבח על דרך אומרו (יואל ד) ונקיתי דמם לא נקיתי, עד אבוד רוח הטומאה מן הארץ, והיה ה' למלך על כל הארץ (זכרי' יד):
@126 **והכהן וגו'**. תחתיו מבניו. בפרק התכלת (נא) דרשו שבא לכהן גדול שמת ועדיין לא מינו אחר תחתיו שבנו של מת יביאנה במקומו, והוא אומרו **תחתיו מבניו**. ודרשו מ''ם של מבניו לדרשא אחרת, דתניא שם בניו אלו כהנים הדיוטים, או אינו אלא כהנים גדולים, כשהוא אומר והכהן המשיח תחתיו מבניו הרי כהן גדול אמור מה אני מקיים בניו בהדיוטים, ומסיק שם בגמרא דמאומרו מבניו דורש כן. ובהוריות פרק ג' (יא) אמרו עוד כהן גדול בן כהן גדול טעון משיחה מנלן דכתיב והכהן המשיח תחתיו מבניו נימא קרא והכהן מתחתיו מבניו מאי המשיח וכו' ע''כ. וקשה והלא צריך לומר המשיח ללמד על בניו האמורים בתחלה שהם הדיוטות כמאמר התנא בפרק התכלת. ויש לומר שללמד על בניו האמורים בתחלה שהם הדיוטות שפיר נשמע הגם שלא היה אומר המשיח, כי ב' כתובים בכהן א' למה לי, אלא ודאי שבניו דרישא בהדיוטים בניו דסיפא בגדולים, ולא היה צריך לומר המשיח אלא לדרשא למשוח כהן גדול בן כהן גדול. ועדיין קשה בכתוב למה אמר **תחתיו מבניו** שהיה צריך לומר מבניו תחתיו. ואולי שיכוין להסמיך בניו ליעשה אותה לכוין דרשת פרק התכלת שאם מת כהן גדול ועדיין לא מינו אחר במקומו בנו יביא במקומו, וזה שיעור הכתוב והכהן המשיח תחתיו יעשה, ואם עדיין לא נתמנה, מבניו של מת יעשה אותה, ואם היה אומר הכתוב הכהן המשיח מבניו תחתיו אז תהיה הכוונה שאין חיוב על בנו להביא אלא אם יהיה תחתיו שכן משמע דוקא תחתיו פירוש שנתמנה או שהוא ראוי לעמוד תחתיו, ומאומרו מבניו יעשה משמע כל יורש יביא. ולר''ש שחולק וסובר שאם לא מינו אחר תחתיו באה משל ציבור אמר תחתיו מבניו, לסמוך מבניו ליעשה, לומר כי אין ראוי לשום אדם אחר ליכנס תחת הכהן זולת בנו. אחר שפירשתי זה מצאתי שכן דרשוה בתורת כהנים למבין משמעות הברייתות על נכון:
@139 **אשם הוא**. נחלקו רבנן ורבי אליעזר (ת''כ כאן), רבנן אמרו הוא למעט אם לא שחטו בצפון לעיכובא, ר' אליעזר אומר למעט אם שחטו שלא לשמו והנה לסברת ר' אליעזר ידוייק אשם הוא שחוזר הוא לאשם שצריך שיהיה לשם אשם. והגם שבזבחים (י) מצינו שהקשה ר' יהושע לר' אליעזר וחזר ר' אליעזר ולמד דין זה דשלא לשמו מפסוק (ז) כחטאת כאשם שהשוה אותם הכתוב, אם כן תיבת הוא למה צריכה, ואולי כי זולת הוא הייתי אומר שההקש בא לענין שצריך סמיכה כמו שדרשו חכמים (שם יא) לזה אמר הוא סמך לאשם לומר שצריך לשם אשם, ולצד שנקשה מה שהקשה שם אמר כחטאת כאשם. ולרבנן הוא למעט שחיטה שלא בצפון שהוזכרה בפרשה (פסוק ב) ובא לעכב, והגם שיש להקשות מעין קושיות שהקשה ר' יהושע לר' אליעזר גם לדברי חכמים, כיון שלא חדשו דין זר מהשכל בדרשתם אלא דבר שישנה בכל הקרבנות, וגם הוזכר בפירוש, אלא שמפסוק א' הייתי אומר שאינו מעכב, יכולין לדרוש הוא שבא לעכובא מה שאין כן ר' אליעזר שהוליד דין חדש שאין לו דמיון, לזה הוקשה כל הקשיות הרשומות שם:
@143 **וכל מנחה וגו'**. אמר הכתוב זכרון ה' מנחות למעט ה' דברים א' שלא יחלקו בני אהרן פירוש בית אב זבחים כנגד מנחות אלא כל אחד יטול חלקו במנחה. ב' שלא יחלקו עופות כנגד מנחות הגם שישנם בהשוואה בענין אחד שמצינו שהעוף בא בדלות והמנחה קמה תחתיהם בדלי דלות. ג' שלא יחלקו עופות כנגד זבחים הגם ששניהם מיני דמים. ד' שלא יחלקו מנחות כנגד מנחות הגם שהם מיני קמחים. ה' שלא יחלקו אפילו מחבת כנגד מחבת ומרחשת כנגד מרחשת הגם שמעשיהם שוים, והגם שהמעוטים הם מנחות, דרשום באם אינו ענין. אלא שראיתי לרמב''ם (הל' מעשה קרבנות פ''י טו) שכתב באופן אחר, כי ממה שחלק הכתוב בין מנחות האפויות ומנחת הסולת שהרי באפויות הוא אומר כל המנחה לכהן המקריב וגו' ובמנחת סולת הוא אומר וכל מנחה לכל בני אהרן וגו', לומר לך שאפילו מנחת סולת שהיה עולה על הדעת שיחלקוה מנחה כנגד מנחה לצד שאם יחלקוה ביניהם מגיע לזה מלא כפו וכו' שאינו דאוי לא ללוש ולא לאפות אף על פי כן לכל בני אהרן יחלקוה בפני עצמה, מכאן אמרו חכמים אין חולקין מנחה כנגד מנחה ע''כ. נמצאת אומר לדבריו שהלימוד הוא מאומרו לכל בני אהרן במנחת סולת מזה אנו לומדים לכל המנחות, ומן הברייתא אינו נשמע כן:
@143 **ועוד** דקדק הרב בלשונו שהלימוד הוא ממה שחלקם הכתוב, משמע שאם לא חלקם לא היינו שומעים זה, ודלא כהברייתא. ואולי כי סובר רמב''ם כי ממה שחלק הכתוב בין מנחות האפויות וכו' בזה גילה לנו הכתוב כוונתו שבא לומר שלא יחלקו ביניהם אחת כנגד אחת אפילו במנחת סולת, ומזה למדו לכל המנחות, כי במרחשת ומחבת לא הוזכר בה חילוק לכל אלא שלא יטלוה זולת בית אב של אותו יום, ומנין אתה אומר שלא יטלו מחבת כנגד מרחשת אם לא הוזכר בה סדר חלוקתה אם לכולם יחד אם לאחד מהם. ומה שלמדו כל הה' פרטים מה' מיעוטים אסמכתא היא, ולעולם עיקר לימודם הוא ממה שחלק הכתוב. ומעתה צריך לדעת למה פרט הכתוב כל המנחות כיון שלימודנו הוא ממה שחלק לא היה לו לומר אלא כל מנחה לכהן המקריב וגו' וכל מנחה חרבה לכל בני וגו'. ואולי שאחר שירד הכתוב לפרט מאפה וחרבה חש שיטעה אדם לחלק ביניהם לבין שאר מנחות, גם מצינו שדרשו ז''ל (תו''כ מנחות סג) וכל נעשה במרחשת ועל מחבת שעל שם כליין נקראו ונפקה מינה האומר הרי עלי מרחשת כלי שרת נדר, והוא דבר שנחלקו בו (שם) בית שמאי ובית הלל לזה אמר הכתוב **וכל נעשה במרחשת ועל מחבת** לגלות לך שעל שם כליין נקראו, ואומרו **אשר תאפה בתנור** דרש גם כן רבי יוסי ב''ר יהודה שבאה ללמוד על עצמו מהסמיכות של כל נעשה במרחשת ועל מחבת מה מרחשת ומחבת הם ב' גם מאפה תנור הם ב', ולא יביא מחצה חלות ומחצה רקיקין, וגם ללמד על מרחשת ומחבת בא לומר מה תנור כלי גם מחבת ומרחשת כלי כאמור שם בתורת כהנים. ונשאר אומר כל מנחה בלולה בשמן וחרבה למה הוצרך לומר ב':
@143 **ונראה** כי כוונת רבי יוסי ב''ר יהודה שלמד כל מנחת מאפה שהוא ב' מיני מנחות לא למדה אלא ממה שאמר הכתוב ב' פעמים כל אחרי כן והם ב' ב', ולזה דייק בלשונו תלמוד לומר וכל מנחה וכל נעשה וגו' וכל מנחה בלולה וגו' מה כל וכל האמורים למטה ב' מינים וכו', ולזה אם היה אומר הכתוב וכל מנחה בלולה לבד או כל מנחה חרבה לבד אין מקום ללמוד ויש לבעל הדין לחלוק ולומר כל מנחה חרבה תוכיח שאמר כל ואין בה אלא מין אחד אף כל מאפה תנור מין אחד לזה הוצרך לומר כל האמור בכתוב:
@154 **והנפש אשר וגו' וטומאתו וגו'**. פסוק זה ושלאחריו בטומאת הגוף פירשוהו בתורת כהנים ובזבחים דף מ''ג אמרו כל קרא שלא פירשו רבי יצחק בר אבדימי וכו' לא מפרשא הכי אמר רבי יצחק בר אבדימי הואיל ופתח הכתוב בלשון נקבה וסיים בלשון נקבה ולשון זכר באמצע בטומאת הגוף הכתוב מדבר ע''כ. ופירש''י הואיל וכו' פירוש פסוק נפש כי תגע שהוא פסוק ב' ושם בהכרח לומר שעל טומאת הגוף הוא אומר הגם ששינה באמצע גם בפסוק ראשון והנפש אל תתמה עליו שדיבר תחלה לשון נקבה והנפש ולבסוף ונכרתה ובאמצע וטומאתו שאין הכוונה על הבשר אלא על הגוף ע''כ. דבריו ז''ל הועילו שלא להכריח ממה ששינה באמצע לומר שנתכוון לומר שבטומאת בשר הוא אומר, אבל להכריח שעל טומאת הגוף הוא אומר הוא ממשמעות הכתוב, שנראה שכבר נגמרו הלכות טומאת בשר כמו שפירש''י שם בזבחים. ועוד בתורת כהנים למדו גזירה שוה טומאתו טומאתו האמורה בביאת מקדש (בפ' חוקת), אלא נתתי לבי למה שינה הכתוב בב' פסוקים אלו, בפסוק אחד שינה לכתוב וטומאתו וסמך ללמוד בגזירה שוה והיה לו לכתוב וטומאתה ולא היינו צריכין לגזירה שוה, גם בפסוק ב' למה לא אמר לשון ישר כל הכתוב בסדר אחד:
@154 **ונראה** כי טעם אומרו **וטומאתו עליו** בא להעיר ענין אחר, שהגם שעברו ז' ימי טומאה לטומאת מת או הערב שמש לטומאת שרץ כל עוד שלא טבל הרי הוא בטומאתו, ויש לך לדעת כי טומאה זו אינה בפנימיות הנפש אלא מסוה הטומאה המסכך על הגוף מבחוץ ולא בפנים, ולצד זה הוא שמועיל לו טבילה להסיר מסוכת הטומאה מה שלא יועיל לו במשך ימי הטומאה שהטומאה גם בפנים, וזה שיעור הכתוב **נפש אשר תאכל** וגו' **וטומאתו עליו** פירוש לא מבעיא וטומאתה עליה שהוא במשך ז' לטומאת מת ובמשך יום מגעו לטומאת שרץ, אלא אפילו טומאתו של גוף לבד היינו שעבר עליו שבעה ימי טומאה ואינו חסר אלא טבילה להעביר מעל גופו אפילו הכי **ונכרתה**. וטעם אומרו בפסוק ב' לשון זכר באמצע הגם שאין טעות בדבר לא היה לו לומר אלא סדר אחד בכל הכתוב. ונראה כי טעם אומרו **ונפש כי תגע** לשון נקבה ולא אמר איש כי יגע לשון זכר, שנתכוון לומר שצריך שיגע לדעתו ולא בהעלם, שאינו חייב כרת אלא בידיעת טומאה, וגם אומרו בפסוק אחד והנפש אשר תאכל שהיתה אכילת בשר בידיעה, כי הנפש יורה אל ההרגש ולמניעת ההעלמות, ולטעם זה תמצא שאמר בפרשת השגגות (לעיל ד וה') ונפש לומר טעם המחייב חטאת ואשם על השוגג הוא לצד היותה נפש שהיא בחינת ההערה והידיעה ושגגה, לזה תתחייב קרבן, ולעולם שם נפש יורה על בחינת שלילת ההתעלמות, ולזה אמר בב' כתובים נפש כי תגע הרי ידיעת הנגיעה, והנפש אשר תאכל הרי ידיעת המאכל, ומעתה אין מקום לקושיא למה אמר לשון זכר באמצע, שאין צורך לשנות סדר הרגיל לומר על העושה לשון זכר, וטעם אומרו ונכרתה הנפש ההיא, בא גם כן להשמיענו חידוש שגם נפש החוטאת תמות ולא גוף לבד:
@154 **וחוץ** מדרכם ז''ל נראה ליישב כפל הכתובים על דרך מה שאמרו בזבחים דף ק''ו במשנה, הטמא שאכל בין קודש טמא בין קודש טהור חייב ורבי יוסי הגלילי אומר טמא שאכל טמא פטור, ואמרו בגמרא (שם קח) כל היכי דנטמא הגוף ואחר כך נטמא הבשר דכולי עלמא לא פליגי דחייב, ולזה אמר ב' כתובים, האחד אשר תאכל בשר מזבח השלמים זה טמא האוכל בשר שלמים טהור, והב' אמר ואכל מבשר זבח וגו' זה כנגד טמא האוכל מבשר שלמים שנטמא. ואולי כי לזה דקדק הכתוב לומר בפסוק אחד **תאכל בשר מזבח השלמים**, פסוק הבשר הוא מזבח השלמים שהוא עדיין במדרגתו שלא נטמא, והב' אמר **מבשר זבח השלמים** פירוש ממין בשר שלמים הגם שעכשיו אינו בשר שלמים שבא בו יעוד האכילה, והוא אומרו מבשר ששם זבח שלמים עליו, כי לא קשר הבשר עם זכרון זבח השלמים לרמון כי אינו בגדר סתם זבח שלמים הטהור ודו''ק ולא יפנה לבבך לטעות אחר המ''ם באופן אחר:
@159 **מן הבהמה**. דרשו ז''ל בתורת כהנים לרבות כלאים מתיש ורחל או להפך, ומאומרו כל חלב ריבה כוי שהוא הבא מתיש וצביה, ועיין מה שכתבתי בחבורי פרי תואר על טור יורה דעה סימן טז:
@159 **כל אוכל חלב**. בתורת כהנים דרשו לרבות חלב בהמת חולין, שלא תטעה לומר אשר יקריב ממנה אשה לה' אמר הכתוב דוקא חלב קדשים תלמוד לומר כל חלב, ורבוי זה אם אינו ענין לאוכלין תנהו ענין לנאכלין. וקשה לי איך נטעה לומר דוקא חלב קדשים והלא אמר וחלב נבלה יעשה לכל מלאכה אימורי קדשים מי מותרים להדיוט, והלא אמרו בכיצד צולין דף פ''ב נשחטה ונמצאת טריפה הרי זה תצא לבית השרפה מדכתיב (לעיל ו כג) בקדש באש תשרף לימד על כל פסולים שבקדש בשרפה, ואם כן מאומרו וחלב נבלה וחלב טריפה יעשה לכל מלאכה אתה יודע כי לא של קדשים לבד אסר הכתוב, ולא היה צריך לומר כל אוכל, ויש לומר דעיקר לימוד התנא מכל אוכל חלב הוא על חיוב כרת, וזולת כל הגם שהייתי למד מפסוק יעשה לכל מלאכה ואכול לא תאכלוהו, הייתי אומר לאו דוקא, ולא כרת, ולא בא הכרת אלא על חלב קדשים. ואומרו שור כבש ועז דרשו בתורת כהנים שבא למעט בהמה טמאה וחיה ועוף. ובחולין דף קי''ו אמר ליה רב מרי לרב זביד אי אליה אקרי חלב תתסר באכילה אמר ליה עליך אמר קרא חלב שור וכשב ועז דבר השוה בשור וכשב ועז ע''כ. וקשה והלא אצטריכו שור וכשב ועז למעט בהמה טמאה ועוף וחיה שהיו באים בקל וחומר לאסור כאמור שם בתורת כהנים תלמוד לומר שור וכשב ועז. ואולי כי שלשה אלה ממועטים הם מאומרו אשר יקריב ממנה אשה לה' יצתה חיה, יצתה בהמה טמאה, יצא עוף שאין כולו נקרב. או שאחר שמיעט הכתוב בהמה טמאה וחיה הרי גילה הכ' שאין לדון קל וחומר מדם שהרי בהמה טמאה וחיה יוכיחו. וכן תמצא שכתב רש''י בחולין (קיז) בפירוש המשנה שאמרה אינו נוהג אלא בטהורים דכתיב אשר יקריב ממנה אשה לה', ועיין בפסוק שאחר זה:
@159 **מן הבהמה**. דרשו בתורת כהנים להביא חולין בעלי מומין, שלא תאמר חולין דומיא דקדשים תלמוד לומר מן הבהמה לרבות אפילו בעלי מומין. והגם שאסר הכתוב בפירוש חלב נבילה וטריפה הגם שאסורים למזבח, בשלמא טריפה נוכל לומר כדעת רמב''ם (איסורי מזבח פ''ב) שאין בה איסור למזבח מן התורה אלא משום (מלאכי א) הקריבהו נא לפחתך, והגם שבתורת כהנים (סימן א פ''ב) דרשו לאסור מן הכתוב אינו אלא אסמכתא וכמו שכתב שם הכסף משנה, אלא נבילה פיסול המזבח הוא כי ושחט כתיב בכל הקרבנות. ויש לומר שלענין כרת מחזר התנא וכמו שכתבתי למעלה:
@159 **אשר יקריב**. אמרו בתורת כהנים מה תלמוד לומר אשר יקריב, חלב שכמותו כשר ליקרב על גבי המזבח, יצא חלב דפנות שאין כשר ליקרב ע''כ. הנה לסברא זו שהוציא מיעוט בהמה טמאה וחיה ועוף מאומרו שור וכשב ועז לא היה צריך לומר אשר יקריב, והוצרך למעט חלב דפנות. וקשה לרב זביד שדרש שור וכשב ועז לאליה שמותרת, ואשר יקריב למעט בהמה טמאה וחיה ועוף מנין להתיר חלב דפנות, גם לתנא שדרש שור וכשב ועז למעט טמאה וחיה ועוף היתר האליה מנא ליה ויש לומר לרב זביד אומרו אשר יקריב ימעט בהמה חיה ועוף וכו' גם חלב דפנות, כי כל שאינו קרב לה' הרי הוא בכלל המיעוט, ותנא דתורת כהנים גם כן ימעט גם כן מאומרו שור וכשב ועז את האליה, שאם לא בא הכתוב אלא לבהמה טמאה וחיה ועוף לא היה לו לומר אלא שור ושה, וכשנתמעט דבר שישנו באיסור דם תו לא עבדינן קל וחומר, וכלום למה איצטריך למעט משום שהייתי דן קל וחומר מדם, במיעוט אחד שיתמעט בהמה טמאה או חיה או עוף נסתר קל וחומר, ולא איצטריך אלא ללמד על האליה שאינה שוה בכולן שמותרת אלא שעדיין אין הדעת מתישבת בזה, למה יחלוק רב זביד על תנא דתורת כהנים דממעט טמאה וחיה ועוף משור וכשב ועז והוא ימעטם מאשר יקריב ממנה לה'. ועוד הרי התנא גילה דעתו כי אומרו אשר יקריב וגו' לא יספיק לדרוש ממנו למעט בהמה טמאה וחיה ועוף וחלב הדפנות ממה שחלקם לב' מיעוטים. אשר על כן הנכון בעיני הוא כי גם לכולי עלמא מיעוט בהמה טמאה חיה ועוף אינו אלא מאומרו שור וכשב ועז, ודרשה זו היתה צודקת הגם שהיה אומר שור ושה, וממה שפרט כשב ועז למעט האליה, ואומר אשר יקריב בא למעט חלב הדפנות, ולא כמו שפירש''י שכתבתי למעלה:
@171 **זאת התורה לעולה**. לא נודע כוונת פסוק זה. ובתורת כהנים דרשו לומר לך מה מילואים נאמרו כללותיהן ודקדוקיהן מסיני אף כל נאמרו וכו'. וכבר כתבתי במקומות אחרים (ריש פ' משפטים) מה שיש להעיר בדבר זה. עוד דרשו ז''ל (תו''כ זבחים צז:) ללמד על הזבחים כולן שטעונין סכין כעולה, וללמד על שלמי ציבור שנאכלין לזכרי כהונה כמנחה וכו'. ובדרך רמז נראה על דרך אומרם במנחות (קי.) אמר ריש לקיש מאי דכתיב זאת התורה וגו' כל העוסק בתורת עולה כאילו הקריב כו' ע''כ, גם אנו נאמר בדרך זה:
@171 **וקודם** אקדים דברי רז''ל אנשי אמת שונים בש''ע נהורים אשר אמרו כי תכלית עסק התורה הוא לברר ניצוצי הקדושה אשר נפלו ואשר נאנסו מהקדושה ולהחזירם ביחוד שלם לכמות שהיו, והם שני בחינות, האחד ניצוצי הקדושה שירדו בעולם התהו לסיבה ידועה לו והמושג ליודעי דעת יספיק לטעם נכון, והשני הם נפשות העשוקות אשר עשק אדם בליעל מאדם הראשון בחטאו אשר שלל שלל רב, כידוע הפלגת הנשמות אשר הרבה לעשוק, ואין לך דבר שפוקד עליו להוציא בולעו מפיו זולת אמצעות עסק התורה יעשה כל דבר עיקר. יעלה ניצוצי הקדושה שנפלו קודם עולם התיקון, ויוציא מס''מ בולעו מפיו ומפוצצו וממחה כוחו עד אשר יקיא חיל בלע, והוא מאמרם ז''ל (קדושין ל:) אם פגע וכו' אם אבן הוא נימוח ואם ברזל מתפוצץ ובפסוק זה גילה הכתוב פלאי התורה ותעצומיה, ואמר **זאת התורה** תועלותיה אשר תסובב קריאתה, **לעולה** פירוש שבאמצעותה תתעלה השכינה שהיא בחינת כנסת ישראל, ב' **למנחה** תיבה זו סובלת כמה פירושים וכולן צודקין, לשון מנוחה ולשון נחת, ולשון הנחה, וזה הפירוש הוא סוד (חולין צא:) עלי יניח צדיק זה את ראשו, והוא סוד (ב''ר פ''י) באה שבת באה מנוחה כי יניח עליה צדיק יסוד עולם, והוא סוד (שה''ש ב') שמאלו תחת לראשי וימינו תחבקני והבן:
@171 **לחטאת** ולאשם הם שני בחינות הברורין, האחד חלקי הקדושה שירדו למטה ממדרגתם בתחילה בעולם התהו כנגדם אמר לחטאת, והשניה חלקי הנשמות שנעשקו מאדם בחטאו כנגדם אמר **לאשם**, כי התורה תועיל לשני בחינות אלו לבררם ממקום ירידתם. ולא בירור לבד אלא גם יכוננם במקום שנחסרו ממנו, והוא אומרו **ולמלואים** למלאותם במקומם, זה כנגד ניצוצות שירדו וכנגד חלקי נשמות שאנס ס''מ מאדם הראשון אמר **ולזבח השלמים**, על דרך אומרו (תהלים נ) זובח תודה יכבדנני ודרשו ז''ל (סנהדרין עג:) זה הזובח יצרו. והזביחה הוא שינצחהו ובבחינת הנצחון הוא בורר ממנו בחינת הטוב אשר אנס מאדם הראשון. והנה בחינה זו היא מעלה גדולה אשר יתעצם לזבוח יצרו כמעשה דוד שאמר (תהלים קט) ולבי חלל בקרבי ודבר זה עושה פעולה גדולה בבחינה שאנו משתדלים עליה, ואין מציאות להשגה זו זולת באמצעות התורה כאומרם (קדושין ל:) אם פגע בך מנוול זה משכהו לבית המדרש, וכן אמרו (שם) אמר הקב''ה בראתי לכם יצר הרע בראתי לו תבלין שהיא התורה:
@171 **עוד** ירמוז באומרו **ולזבח השלמים** כי תכלית הבירור יהיה באמצעות הזבח דכתיב (ישעי' לד) כי זבח לה' בבצרה, ואמרו ז''ל עתיד הקב''ה לשחוט את השטן, ופירוש שחיטה זו היא שיסיר ממנו בחינה המחייהו שהוא ניצוץ הקדושה ובזה השלמים נשלמו כל הבירורים, והודיע הכתוב כי גם הדבר הזה יושג באמצעות עסק התורה כי בזכות עסק התורה שעוסקים הצדיקים בעולם הזה יהיה הדבר, ולזה רמזו ז''ל (שם) בדבריהם כי השחיטה הלז תהיה על זה הדרך הקב''ה מצד אחד וכל הצדיקים תופסין הסכין מצד אחר לזבוח זבח ההוא כי בכחם היה המושג, הא למדת זאת התורה לכל הדברים הנפלאים, **לעולה למנחה** כנגד העלאת השכינה ויחודה עם הקב''ה, **לחטאת ולאשם** לברר ב' בחינות הברורים שהם עיקר העולם, **ולמלואים ולזבח השלמים** ליחד ניצוצות היורדות למלאותם במקומם, ולזבוח יצרו זביחה שאין אחריה קיום, גם יעמוד חי לפני ה' לשלוח יד במבקשי רעתו לזבוח זבח, והיה ה' למלך וגו' יהיה ה' אחד ושמו אחד, והוא אומרו השלמים פירוש שנשלמו כל בחינות הקדושה ונתיחדו יחד. ואומרו **אשר צוה ה'** וגו' חוזר לסיבה שהיא התורה שהזכיר בראש הפסוק, כאילו אמר זאת התורה אשר צוה ה' וגו' שצריכין ללמוד התורה על מנת כן לא לתכלית אחר זולתו, ואומרו **ביום צוותו** כי דבר זה נאמר להם במעמד הר סיני דכתיב במדבר סיני, ואמר **להקריב את קרבניהם** כאן רמן בתוספת ביאור מה שפירשתי שמקריבין כל חלקי הקדושה שהם מיוחסים לישראל שהם הם הדרגת הקדושה וכל חלקי הקדושה להם יתיחסו ובאמצעות התורה יקריבו את קרבניהם ויתיחדו כל בחינות הקדושה כנזכר למעלה:
@174 **קח** את אהרן וגו'. פרשה זו נאמרה קודם הקמת המשכן, וטעם שנאמרה כאן, לומר לך שקדמו כל משפטי הקרבנות ופרטיהן ודקדוקיהן קודם מילואיו, כי לעשות כולן נתכהנו הוא ובניו, ולא נתכהן עד שלמדו משה כל פרטי דיני כל הקרבנות וקיים וקבל עליו לעשות ככל הכתוב ואז אמר לו קח את אהרן שעל מנת כן נתכהן, ועוד שזולת זה משכחת שיביא אדם מישראל קרבן מיד בקרבתו לפני ה' ולא ידע מה לעשות:
@176 **ותקהל העדה וגו'**. אולי כי בראותם מעשה משה שלקח אהרן ובניו והבגדים וגו' נקהלו מעצמן. או ירצה להודיע שהחזיקם המקום לכל ישראל בפתח אהל מועד, כמו שדרשו ז''ל (ויק''ר פסוק שלפני זה) בפרשת הקהל וגו', וכאן יודיע הכתוב שכן היה:
@177 **ויאמר** וגו' זה הדבר וגו'. אמר כן להודיעם לבל יערערו על הדבר כקרח וכעדתו בחושבם כי מלבו ומרצונו היה עושה. ומעתה אין טענה לקרח כי שוגג היה שהרי הודיעו בשעת מעשה כי זה הדבר הוא מצות ה' ולא מלבו ומרצונו של משה. עוד ירצה על דרך אומרם ז''ל (שמו''ר פ''ב) כי משה מלך היה דכתיב (ברכה לג) ויהי בישורון מלך ותנן (כתובות יז.) מלך שמחל על כבודו אין כבודו מחול, והנה משה היה עושה מעשים שאסור לעשותם אפילו עבד עברי לאדונו לרחוץ אותם במים וכו' כל גופם וכל סדר המעשה, ואין לך זלזול גדול מזה, אשר על כן הקדים לומר **זה הדבר אשר צוה ה'** מפי ה' נאמר לי לעשותו, ודוקא זה ולא אחר כי המלך אסור לעשות כן הגם שיחפוץ למחול, כי דוקא זה הדבר לצד שהפה שאסר מלך שלא ימחול על כבודו הוא שהתיר וצוה לי לעשות. עוד ירצה על דרך מה שאמרו ז''ל בתורת כהנים בפסוק וירחץ אותם במים באותה שעה זכו בקידוש ידים ורגלים ובטבילת יום הכפורים ע''כ. והוא אומרו זה הדבר **אשר צוה ה' לעשות** לדורות, כי בזה יזכו בקידוש ידים ורגלים וטבילה ביום הכיפורים לדורות:
@182 **וימשח את המשכן וגו'**. הטעם שהפסיק בין לבישת אהרן למשיחתו במשיחת המשכן וכליו, לצד שמצינו שצוה ה' במשיחת המשכן וכליו קודם למשיחת אהרן כרשום בפרשת פקודי (מ' ט'), ומן הראוי היה להקדים משיחת המשכן גם ללבישת בגדי אהרן כרשום שם, וטעם שלא עשה כן לצד שדקדק מאמר ה' כאן בפרשה זו (פסוק ב') שאמר לו קח את אהרן וגו' ואת שמן המשחה וגו', ואם משיחת המשכן קודמת גם ללבישת בגדי אהרן היה לו לומר קח את שמן המשחה שהוא דבר שיעשה ממנו המצוה הראשונה שהיא משיחת המשכן ואין מקום לטעות מאומרו קח את שמן המשחה ראשונה שימשח אהרן קודם לבישת בגדיו, שהרי כבר אמר והלבשת את אהרן וגו' ומשחת אותו, אלא ודאי שכוונתו הוא להקדים לבישת הבגדים קודם למשיחת המשכן, ומה שהקדים משיחת משכן בפרשת פקודי ללבישת בגדי אהרן ולמשיחתו אינו אלא למשיחתו דוקא, אלא לצד שלא רצה הכתוב להפסיק בין מצות הבגדים למצות המשיחה של אהרן לזה אמר כל דיני אהרן יחד, ולעולם לא תקדים משיחת המשכן וכליו אלא למשיחת אהרן ולא לבגדים כמו שגילה כאן כנזכר:
@200 **על העולה**. שלא היה דבר מפסיק. ואולי שלא שהה עד שאכלה האש את העולה אלא ועדיין העולה קיימת:
@203 **כאשר צויתי**. פירוש על האכילה צוה כבר שיאכלוה ועתה הוא מצוה על המקום, הא למדת מצוה על האכילה, ומצוה על המקום ואם ירצה שלא לאכול הרי זה בטל המצוה, ואם ירצה לאכול חוץ מהמקום הרי זה בטל המצוה. ואומרו **לאמר** פירוש לא שצוה מעצמו אלא ממה שנאמר לו מפי השכינה:
@203 **חסלת פרשת צו**
@209 **ויהי ביום השמיני**. צריך לדעת מה טעם אמר ויהי ובמסכת מגילה (דף י) אמר רבי לוי דבר זה מסורת בידינו מאנשי כנסת הגדולה כל מקום שנאמר ויהי אינו אלא לשון צער, ומקשה והכתיב ויהי ביום השמיני ותניא אותו היום היתה שמחה לפני הקב''ה כיום בריאת שמים וארץ כתיב הכא ויהי וגו' וכתיב התם (בראשית א ה) ויהי ערב ויהי בקר וגו', ומתרץ הא מתו נדב ואביהוא, ומקשה עוד ויהי בשמונים שנה (מ''א ו) ויהי כאשר ראה יעקב (ויצא כט י) וגו' ויהי ערב ויהי בקר וגו', ומתרץ רב אשי כל ויהי איכא הכי ואיכא הכי ויהי בימי אינו אלא לשון צער ע''כ, החי יתן אל לבו למקשה מפסוק ויהי ביום השמיני והעלים עין ממה שלפניו ויהי ערב ויהי בוקר שממנו למד ויהי ביום השמיני, ולזה יכולני לומר שמקשה משניהם יחד ולהגדיל קושייתו הוסיף גם פסוק ויהי ביום השמיני לומר כי רבים ויהי שהם לשון שמחה, או אפשר שנתכוין לומר לו שאדרבא להפך כל מקום שנאמר ויהי אינו אלא לשון שמחה כדרך שלמד התנא מויהי ביום השמיני מויהי ערב אם כן כל ויהי לא יגרע עינה מזה. גם בזה לא יוכל לדחות כי דבריו הם במן הסתם ולא במקומות שגילה הכתוב בפירוש, כי הרי התנא למד מויהי ערב וגו'. אלא תגדל התמיה על המתרץ, כי מה מתרץ הרי מתו נדב ואביהוא, תירוץ זה מועיל לויהי ביום השמיני ולא לויהי ערב ויהי בוקר שממנו למד ויהי ביום השמיני, ואין לומר שהיה לו איזה ענין לומר שגם בו ביום היה איזה צער, שהרי מצינו כשחזר המקשה והקשה ממנו חזר לאחוריו והודה חצי הודאה. ועוד מעיקרא למה לא נתן לב רבי לוי מעצמו לכתובים שמוכיחים שיש ויהי שהוא שמחה, והיה לו לחלק מעצמו:
@209 **אכן** נראה כי כוונת ר' לוי גם כן לא היתה אלא כדברי רב אשי, ולזה לא אמר אלא אמר רב אשי שיהיה נשמע שסותר דברים הראשונים, שגם יוסבלו דברי רב אשי בדברי ר' לוי, שהרי מקראות ויהי רבים ונכבדים, אלא שהמקשה סבר כי לכל ויהי הוא אומר, ונתחכם להקשות מויהי ביום השמיני כי אין הפרש בין ויהי בימי לויהי ביום, ורצה לסתור הכלל אפילו במקום שיאמר ויהי בימי, והמתרץ תירץ כי שם מתו נדב ואביהוא, כי לא רצה לחלק בין ויהי בימי לויהי ביום, כי אין הפרש, ואין הוכחה מתשובה זו שסובר אפילו ויהי לבד הוא לשון צער, כי לא הוכרח לתרץ זה אלא לצד שהקשה מויהי ביום. ואחר כך חזר להקשות אפילו מויהי לבד, ונתחכם המקשה להקדים פסוק ויהי בשמונים שנה לגלות על ויהי ערב שמלבד שלא היה שם צער היה בו שמחה. והגם שמדברי הברייתא שהביא למעלה מוכח שהיה שמחה לפניו, אינו אלא דברי התנא, אבל אין הוכחה מהכתוב אלא שלא היה צער אבל שמחה מנין, לזה הקדים פסוק ויהי בשמונים שנה שזה ודאי שמחה יגיד בבנין בית המקדש (תענית כו) דכתיב (שה''ש ג') ביום שמחת לבו, וזה יגיד על ויהי כאשר ראה יעקב ויהי ערב וגו' שאינם אלא שמחה, ואמר רב אשי ויהי איכא ואיכא כו', וכן היתה דעת המתרץ ראשון אלא שקדם רב אשי ותירץ. ואולי גם מתרץ ראשון רב אשי הוא והזכיר שמו במסקנא, או ב' סתמי דתלמוד הם, וג' דרכים אלו הם שאנו הולכים בהם בשבילי התלמוד. נמצאת אומר כי אפילו לרב אשי ויהי ביום הוא כויהי בימי, והצער הוא שמתו נדב ואביהוא שאין כמותם בכל ישראל, וזולת זה לא היה אומר הכתוב ויהי, וגם אומרו (יתרו י''ט ט''ז) ויהי ביום השלישי, גם שם הרי פרחה נשמתם של כל ישראל כאומרם ז''ל (שבת פח:) וזולת זה לא היה אומר ויהי ביום:
@209 **ואולי** נראה עוד כי הצער שיגיד הכתוב הוא של משה המוזכר בכתוב כי ראה גדולתו וגדולת זרעו ביד אהרן ובניו, וצא ולמד צער הקנאה מדבר טוב מה עושה ממעשה בניו של שמעון הצדיק (מנחות קט:), וישתנה מה שלפנינו שהיתה לו ולזרעו אחריו, ולצד שהפציר בשליחות פרעה חרה אפו בו ביום ההוא ועזבו מהיות כהן לעולם, וכשהגיע יום הפקידה נצטער על אשר פרח ממנו עוז תפארת כהונת עולם, והגם כי עצם מאוד בצדקות ובענוה, הלא כל לב חי מרגיש ובפרט בדבר מצוה יקרת הערך ומופלאה כזאת. ואולי כי צער זה רמזו הכתוב בפסוק (ז' א') ויהי ביום כלות משה שהוא עצמו יום זה, ומיתת נדב ואביהוא רמז כאן בפסוק ויהי ביום השמיני:
@209 **ביום וגו** ' **קרא משה לאהרן וגו'**. דע כי העושה דבר כזה שיתן גדולה הנודעת לו לזולתו, לו יהיה אחיו, כאשר יתחייב לעשותה, לא ישלוט בנפשו עשותה בג' שלמיות, הא' שיעשנה במהירות, והב' בצירוף בחינת ההדרגות שישנה בדבר. הג' עשיית הדבר בפרסום לפני רבים, והודיע הכתוב כי שלשתם יחד שלט משה בנפשו ועשאם. כנגד המהירות אמר ביום השמיני, פירוש בהיות הבקר טהור לב לא עכב אלא תיכף קרא לאהרן לתת לו הכהונה ולא נתעצל. ב' עשה הדבר בצירוף בחינת ההדרגות שנתן הכהונה לאהרן ולבניו יחד, הגם כי בזה יגדל העצבון בלבו שיראה גדולה מושכת לאהרן ובניו ואשר יעצב אל לבו יעשה הדבר בהדרגות, בתחלה יקרא לאהרן ואחר כך לבניו, כי לא היה הכרח בקריאת הבנים אז עם אהרן. הג' במצב כל הזקנים דכתיב **ולזקני ישראל** לעשות הדבר בפומבי בפני רבים ונכבדים, וזה יורה על שלימות הרצון לעשות רצונו ית', וכפה הרגשותיו:
@210 **קח לך עגל**. ביומא דף ג' דקדקו אחר שאמר ואל בני ישראל וגו' קח לך למה לי מובן הוא שהעגל לו. ודרשו שבא לומר שיקח משלו ולא משל ציבור. עוד נראה לומר כי אומרו לך כי זה יהיה לו לאות עולם כי לא עשה הוא העגל בכוונה ח''ו ולא טעה אחריו אלא שבא על ידו בלא כוונה ובלא מחשבה רעה, ולצד זה יועיל לכפר בעגל, מה שאין כן ישראל לצד שמעשיהם בעגל הוא בחינת המזיד ולא יבא העגל לחטאת להם והוא אדרבה קטיגור. ותמצא (ויק''ר כא) שהקפיד ה' על אהרן לבל יכנס לבית ה' פנימה ביום הכיפורים בבגדי זהב לצד שעשה זהב העגל, ויש להעיר בזה למה צוה ה' שיביא עגל בן בקר לחטאת והלא החטאת באה לכפרה ואין לך סניגור בעולם כזה. ונראה כי האדון ב''ה שפט בצדק הדבר, לצד כי אהרן לא עשה שום פעולה בבחינת מעשה העגל כי לא ציירו ולא הכינו ואין צריך לומר שלא האמין בו ולא טעה אחריו חס ושלום כמאמרו למשה (תשא לב כד) ויצא העגל פירוש מעצמו יצא על ידי מעשה אשר עשו ב' מכשפי ערב רב יינום ויומברוס כמאמרם ז''ל (תנחומא תשא יט), ומעתה המעשה שעשה הוא בבחינת הזהב שאמר להם (שם) למי זהב התפרקו ולקח מידם ויצר אותו בחרט ומעשה זה עשהו בידיעה שלימה והגם שטעמו היה לצד יראה מישראל לבל יהרגוהו כחור, גם היה מאבד להן הזמן עד שיבא משה, אף על פי כן הרי עשה מעשה בלתי הגון, אשר על כן אמר ה' שיביא העגל לכפר על הדבר שיצא על ידו שלא בכוונה אבל הזהב שמעשה שעשה בו היה בכוונת המכוון אמר ה' לא יראה בו לפני ולפנים שלא יעשה קטיגור סניגור, מה שאין כן ישראל שחטאו בעגל אינם יכולין להביא עגל לכפרה לזה צוה ה' שיביאו שעיר עזים:
@210 **עוד** נראה לומר בהעיר איך אנו אומרים (ר''ה כו.) אין קטיגור נעשה סניגור בענין הזהב והלא אמרו (ערכין טז.) ארבעה בגדי זהב של כהן גדול מכפרים על ארבעה מיני עבירות וכו' אם כן קטיגור נעשה סניגור, ובהכרח ליישב כי ישתנה כפרת חוץ מכפרת פנים שכפרת פנים מלבנת החטאים כשלג, וזה לך האות לשון של זהורית (יומא סז.), ודבר זה הוא מופלא וצריך שלא ימצא בו רושם העון כלל, ואשר על כן הבגדים להיותם בחוץ מכפרים הגם היותם מין זהב מה שאין כן כפרת פנים, וגם לפי חילוק זה ישתנה חטא של אהרן בזהב מחטאם של ישראל בעגל, כי אהרן מכפר בחוץ בבגדי זהב וישראל אינם מתכפרים בעגל כי חטא אהרן בזהב שוגג גמור היה בלקיחתו ובנתינתו בחרט מה שאין כן ישראל, ולזה לא יתכפרו בעגל אפילו בחוץ והבן:
@211 **תדבר לאמר**. צריך לדעת מה טעם ידבר כאן אהרן לישראל ולא משה הרגיל ואולי כי לצד שאמר להם למי זהב התפרקו וגו' לזה יצו ה' אליו כי ידבר להם להביא כפרה שעיר עזים הפה שאסר הוא הפה שהתיר וכבר כתבנו בכמה מקומות דברי רז''ל כי החטא יפעיל הגנאי במקומו והתיקון צריך להיות מכוון כנגדו והוא אומרו **תדבר לאמר** פי' תדבר דיבור שיש בו מעלה וזכות כנגד דיבור שהיה בו השפלה אשר פרע בו את העם. עוד נראה כי לצד שעלה אהרן במעלה הנפלאה הלז מתוך כל ישראל בו בחר ה' לז''א אליו משה שידבר לישראל אמירות רכות והוא אומרו **לאמר** וכן תמצא שאמר **כי היום ה' נראה אליכם** פי' כל המושג וכל הרצון אינו אלא לצד ישראל כאומרו אליכם ולא לי וכדרך שמצינו שאמר משה לישראל הלא כ''ז שהיו ישראל נזופים לא דבר ה' עם משה כי כל המושג אינו אלא לצד מעלת ישראל:
@213 **ויקחו וגו' אשר צוה משה**. אמר **אשר צוה משה**, יכוין אל אהרן גם כן שלקח את אשר צוהו, ואינו יוצא ממשמעות מעשה ישראל שהגם שמפי אהרן נאמרו להם הדברים אהרן עצמו מפי משה אמרם, ואילו אמר הכתוב אשר צוה אהרן אין במשמע אלא לקיחת ישראל ולא לקיחת אהרן. עוד אולי שנתכוין באומרו **אשר צוה משה** כי לצד מצות משה לבד עשו הדבר הגם שלא היתה ההבטחה הרשומה במאמר:
@214 **זה הדבר וגו'**. צריך לדעת מה הוא **הדבר**. ורש''י פירש על הקרבת אהרן. ואין זה פשט מאמר הכתוב שאמר תעשו ונראה שיכוין לומר על המעשה שהזכיר הכתוב בסמוך דכתיב ויקרבו כל העדה ויעמדו **לפני ה'**, דקדק הכתוב לומר **לפני ה'** ולא אמר לפני אהל מועד גם לא היה צריך לומר שהרי אמר בסמוך ויקחו וגו' אל פני אהל מועד, אלא ירצה לומר שהכינו עצמם בערך השלימות והמושכל והערכת עמידתם שהיא לפני ה', ובחינה זו היא השגת תכלית השלימות, כמאמר דוד (תהלים טז) שויתי ה' לנגדי תמיד כי בזה לא ימוט מימינו שהיא התורה, כי אין ישיבת האדם ותנועותיו וכו' כישיבתו וכו' לפני מלך ומכל שכן לפני מלך מלכי המלכים, וכשהשכיל משה במעשה זה אמר להם זה הדבר אשר צוה ה' תעשו פירוש צוה ה' שתעשו אותו, שתהיו תמיד מעריכים בדעתיכם כי אתם עומדים לפני ה', וידא אליכם כבוד ה' עוד יכוין בכלל אומרו **לפני ה'** שלא היה מסך מבדיל בינם לבין ה' כדכתיב (ישעי' נט) עונותיכם היו מבדילים וגו', וזה יגיד שהיו שלימים עם ה' וכפי זה ידוייק על נכון אומרו זה על מעשה האמור בסמוך:
@214 **אחר** שכתבתי זה בא לידי מדרש חז''ל (במד''ר נשא פי''ב ח') וזה לשונם זה הדבר מה הוא זה הדבר על המילה כמה דתימא זה הדבר אשר מל יהושע עד כאן. ודברי המדרש סתומים וחתומים, וכי באותו יום מל אותם משה, או באותו יום צוה על המילה:
@214 **אכן** הכוונה היא על ערלת לבם שהוא דבר המבדיל בין ישראל ובין אביהם שבשמים, גם מרחיק אימתו מלבם, וצוה למול ערלת לבבם ובזה יראה להם כבוד ה', והם דברינו עצמם. שוב באה לידי מדרש אחר (כן הוא בתו''כ הכא) בילקוט וזה לשונם זה הדבר אמר להם משה לישראל אותו יצר הרע תעבידו מלבבכם ותהיו כלכם ביראה אחת ובעצה אחת לשרת לפני המקום וכו' ותהיה עבודתכם מיוחדת לפניו דכתיב ומלתם את ערלת לבבכם וגו' ואם עשיתם זה וירא אליכם כבוד ה' עד כאן, והם דברינו עצמם:
@215 **וכפר בעדך ובעד העם**. משמע כי כפרת אהרן נוגעת גם לעם. והטעם הוא לצד כי חטא אהרן ישראל היו לו סיבה לחטוא שאמרו לו (תשא לב א) קום עשה לנו וגו', וכל עוד שלא נתכפר אהרן ישנו החטא לעושהו ולמסבב עושהו, ואחר שנתכפר נתכפרו שניהם, לזה אמר לו וכפר בעדך ובעד העם:
@216 **ויקרב אהרן אל המזבח**. ירמוז לדבריהם ז''ל שאמרו (ירושלמי מכות פ''ב ה''ו) שאלו לנבואה חוטא מה עונשו אמרה הנפש החוטאת היא תמות, ולצד רחמי ה' אמר יביא קרבן, שעיקר מעשה הקרבן היא מחשבת המקריב כי הוא החייב בכל המעשה אשר יעשה בקרבן ההוא ליזבח ולהשרף על האישים והיתה לו מחשבה זו לכפרה, והוא אומרו **ויקרב אהרן אל המזבח** פירוש הוא עצמו הכין לשום אשם נפשו, וקרב למזבח פירוש לזביחה לאישים, ועשה השחיטה במקומו לעגל לצד רחמי ה' שנתרצה להביא חליפתו:
@216 **וראיתי** לתת לב בענין לפי מה שקדם לנו (תנחומא שפטים) כי נשבע ה' להעמיד העולם וברואיו במשפט, וכל האומר הקב''ה וותרן יוותרו בני מעיו (ירושלמי שקלים פ''ה ה''א), אם כן אם הנפש החוטאת משפטה היא תמות כמאמר הנביא (יחזקאל יח ד) איך יביא קרבן ויפטר, ונראה כי טעם נכון יש בדבר על פי המשפט, כי כשהאדם חוטא אין בחינתו בחינת ארם, על דרך אומרם ז''ל (סוטה נ. ג.) אין אדם עובר עבירה אלא אם כן נכנס בו רוח שטות, ונעשה בהמה וביום שחזר בתשובה רוח היא באנוש ועלה ממדריגת בהמה למדריגת אדם, האם ראוי הוא להמית אדם זה תחת בהמה, לזה יביא דוגמת החוטא שהוא בהמה וישתתף עמה בצער החושב כי ראוי הוא לעשות בו משפט זה, וכפי זה חלק רוח המרגיש הוא מציל את האדם בהערה זו, והוא מה שאמר הכתוב (תהלים לו) אדם ובהמה תושיע ה' כי חלק הבהמי שבאדם בהצטרפותו עם האדם שהיא בחינת ההשכל נושע בו פירוש לצדו כדי שלא יענש והוא אינו ראוי לעונש, ובזה אפילו בדין הקרבת הקרבן בעד החטא הוא על קו המשפט, כאומרו (שם) משפטיך תהום רבה אדם ובהמה תושיע ה':
@223 **ויקרב את קרבז העם**. זו הקרבת בחינת האורות הנטועות בישראל ממקור האור אשר נשתנו באמצעות החטא ולא יהיו בבחינת הנשתוון להתקרב, כי השינוי בנפש יחייב ההרחקה, כי יעשה שאינו מינו, ובאמצעות העבודה שעשה אהרן יגיד הכתוב כי הקריב קרבן העם פירוש שהקריב כל הרחקותם. והנה מהראוי היה שיכתוב פסוק זה בסוף מעשה הקרבן, וטעם שהתחיל בו, לומר שהפעולה נעשה במה שכוון במעשה קודם עשוהו, כי לא המעשה הוא העיקר אלא הכוונה הצריכה בו והוא אשר עשה אהרן בתחילת מעשיו והבן. וארמוז לך פרט אחד קטן שרמז הכתוב באו' **ויקרב את העולה ויעשה כמשפט**, כבר רמזתי לך כי זכרון העולה ירמוז על כנסת ישראל ובאמצעות הרחקת ישראל מהיושר הם מורידים העולה למטה ח''ו ובאמצעות התקרבותם לא מלבד שלא תשולח בפשעם אלא יוסיפו להעלות עליה אחר עליה עד שתעמוד בגדר המשפט כידוע למשכיל, והוא ויעשה כמשפט. שמעתי:
@230 **וישא אהרן וגו'**. בתורת כהנים פרשה כ''ט אמרו מקרא מסורס ראוי לומר וירד מעשות וגו' וישא אהרן וגו' שבירידתו נשא כפיו וכו'. וצריך לדעת למה ידבר הכתוב בדרך זה ולא בדרך הישר. ואולי כי בראותו אהרן שלא ירדה שכינה חשב אולי כי עדיין חסר כפרתו על מעשה העגל שבאמצעותו הביא קללה על שונאי ישראל, ולזה וישא וגו' ויברך וגו', ובזה ירד מעשות תשלומי החטאת וכו' ואולי כי גם ברכת ישראל לצד שהיא כפרת חטאו של אהרן תוכלל בכלל החטאת, כי גם לה יתיחם שם חטאת, ואומרו **וירד**, אולי כי הוא לשון ירידה כי הוכר לו פחיתותו, לצד שראה שגמר מעשות הכל ולא ירדה שכינה, ותמצא שאמרו ז''ל בתורת כהנים פרשה י''ט שצעק אהרן לפני משה שאמר לו ליקרב למזבח ובא לידי בושה וכו' ונכנס משה עמו ובקשו רחמים וירדה שכינה:
@231 **ויצאו ויברכו וגו'**. אולי כי כן נצטוו בנבואה. או ברכה זו במקום תפלה היתה כדי שתשרה שכינה. והגם שכבר בירכם אהרן, טובים השנים לצד הסכמת ב' מדרגות הרמוזים בב' בחינות האחים כהונה ולויה שהם חסד וגבורה:
@233 **ויקחו בני אהרן נדב ואביהוא וגו'**. ירצה להודיע מקום טעותם שהיא לב' סיבות, האחד להיותם כהנים שאליהם תאות העבודה וזהו שהתחיל לומר בני אהרן, ב' היותם גדולים במעשה ושקולים הם כמשה ואהרן כאוז''ל (תו''כ הכא אחרי נג) וכאומרם בספר הזהר הקדוש (אחרי נו) שהיו במדרגה גדולה מצד מעשיהם, וזה אומרו נדב ואביהוא, ובחינ' זו אינה באלעזר ואיתמר שהגם שהם בני אהרן אין להם מדרגה מצד עצמם כנדב ואביהוא, וכן תמצא שדרשו ז''ל (תו''כ להלן פסוק טז) במה שכתוב ויקצוף משה על אלעזר וגו' הנותרים וגו' יעויין שם דבריהם ובכח זה נכנסו, ודקדקו ליכנס שניהם יחד להגדיל זכותם, ולא רצו לקחת מאש המזבח, אמרו אולי אין ראוי לקחת ממנה אלא לקטורת החיוב, לזה הביאו מבחוץ:
@233 **וישימו עליה**. ולא אמר עליהן כאומרו ויתנו בהן וגו', וישימו עליהן, חוזר אל האש שהזכיר בסמוך, להיות שהקפדה היא על אש זרה לזה כינה בה המעשה:
@233 **זרה אשר לא צוה**. פירוש ומה היא זרותה, שלא צוה ה' אותה. ואולי שאם היו לוקחים אש מעל המזבח לא היה ה' מקפיד על הדבר כל כך. או אפשר שהיה מקפיד מאופן אחר. עוד ירצה על זה הדרך אש זרה אשר לא צוה אותם לעשות כן וזה היא זרותה:
@234 **וימותו לפני ה'**. אולי שירמוז טעם מיתתם, שהוא להפחיד לירא מן המשכן בראותם את אלו שקרבו לפניו מתו, עוד ירמוז כי מיתתם היה על מה שקדם מהם לה', על דרך מאמרם ז''ל (ויקרא רבא פי''ג) שמיתתם היה למה שקדם ויחזו את האלהים וגו', והם הם אצילי בני ישראל:
@235 **הוא אשר דבר ה' וגו'**. צריך לדעת כוונת אומרו **הוא** ב' אומרו לאמר משמע שצוה ה' לאמר אם כן למה לא אמר עד עתה, ושגיון זה דומה לשגיון אזהרת שבת שלא צוה בשעתו עד אחר כך אמר (בשלח טז כג) הוא אשר דבר ה', ושם מצינו לו טעמים מספיקים בענין כי לא נאמר לו לאמר כמו שדקדק לומר הוא אשר דבר ה' שבתון וגו' ולא אמר לאמר, מה שאין כן במה שלפנינו שאמר לאמר, ורז''ל מצינו להם שאמרו (תו''כ הכא) היה אהרן עומד ותוהא ואומר אוי לי כך עבירה בידי וביד בני שכך הגעתני, נכנס משה אצלו והיה מפייסו אמר לו אהרן אחי מסיני נאמר לי עתיד אני לקדש הבית באדם גדול והייתי אומר או בי או בך הבית מתקדש עכשיו נמצאו בניך גדולים ממני וממך וכו' עד כאן. דבר אחר ויאמר משה וגו' הוא אשר דבר וגו' דיבור זה נאמר למשה בסיני ולא ידעה עד שבא מעשה לידו וכיון כו' אמר לו משה לאהרן לא מתו בניך אלא בשביל קדושת שמו של מקום שנאמר (תצוה כח מג) ונועדתי שמה לבני ישראל ונקדש בכבודי, כיון ששמע אהרן שבניו ידועי המקום הן שתק ע''כ:
@235 **הנה** לדרך הראשון מפרש תיבת **הוא** על זה הדרך להיות שהיה מצטער על הסיבה שהוא סבב לבניו שמתו לזה אמר לו משה כי הוא זה טעם מיתתם לצד אשר דבר ה' וגו' ולא לצד עונו היה הדבר, ותיבת הוא כפי זה חוזרת אל הסובב. ולדרך ב' תיבת **הוא** חוזרת אל הדיבור הסתום שלא ידעו ועתה ידע כי הוא זה מכוון הדיבור הנאמר לו קודם ונקדש בכבודי, גם לא נאמר לו שם דבר ולא לאמר דוק ותשכח, ונשארו הדברים בלבב משה סתומים עד שעת מעשה והבינם ואמר הוא אשר דבר ה' אלי ומה דבר ונקדש בכבודי. ואומרו **לאמר** וגו' פירוש כוונת דברי ה' באומרו ונקדש בכבודי הוא לומר על זה הדרך באומרו ונקדש רצונו לומר בקרובי אקדש, ואומרו בכבודי הוא ועל פני כל העם אכבד, ולדרך זה נתישבו כל הדקדוקים. אלא לדרך ראשון עדיין קשה מה שהקשינו. ולעמוד על עומק דבריו יש להעיר אומרו או בי או בך שלא היה לו לומר אלא בי או בך או יאמר בך או בי כי לא יוצדק לומר או בתחילה:
@235 **ולזה** נראה לישב כי לצד שיש בענין ב' דברים. הא' הוא בחינת המעלה והב' בחינת המאורע שהוא המיתה, וכשבא לומר את אשר הבין מי הוא הקרוב אשר יקדש בו אם היה מתחיל לומר בי או בך היה נשמע בדבריו כי הוא הקרוב לפני ה' ביותר מעלה וכבוד ולזה הזכיר עצמו בפשיטות והזכיר אהרן בספק או, לזה אמר או בי שגם הוא בספק ואם היה אומר בך או בי יבא המיחוש כי רצה להלביש המאורע הרע באהרן כי הוא ימות בהשראת שכינה ואת עצמו עשה בספק, לזה נתחכם משה ואמר או בי הקדים עצמו לצד בחינת קבלת הפורענות ולא בהחלט כדי שלא יכנס בחשד כי מעריך עצמו בערך גדול מאהרן ואמר או דרך ספק כדרך הספק שעשה באהרן באומרו או בך. אלא שעדיין קשה כיון שלא נאמר מה' אלא א' מהם ולא נכנס לו הספק אלא איזה א' מהם אם כן למה מתו שנים, ועוד מנין לו לומר שהם גדולים ממשה ואהרן כיון שלא אמר ה' אלא א' מהם ומתו שניהם נכנסו במקום א' מהם, ואינו יכול לומר אלא טובים הב' מאחד מהם. אכן הכוונה הוא שכשאמר לו ה' ונקדש בכבודי ידע משה כי ימות מהצדיקים, אלא שסבר בשיעור משמעות הדברים באומרו ונקדש בכבודי הוא שיתקדש הבית באותו שהוא כבודי מכובדי שהוא הצדיק. ולפי זה אין כאן אלא צדיק א' כי כן משמע כבודי לשון יחיד ונפל לו הספק מי הוא זה היחיד אם הוא משה אם הוא אהרן, והוא אומרו או בי או בך וכמו שפירשנוה, ועכשיו כשראה כי מתו שנים חזר להבין כוונת אומרו ונקדש בכבודי שאין הכוונה שיתקדש ובמה בכבודי שהוא לשון יחיד, אלא הכוונה הוא על זה הדרך בקרובי אקדש והוא אומרו ונקדש, ואומרו ועל פני כל העם אכבד הוא כוונת אומרו בכבודי פירוש בשביל כבודי, וכפי פירוש זה לא אמר ה' לשון יחיד בצדיקים כי הצדיקים נרמזו באומרו ונקדש, ואומרו בכבודי הוא בשביל כבודי, והראיה שכך הוא כוונת אמירתו יתברך שהרי מתו שנים והוא אומרו הוא אשר דיבר תשובה לאהרן שלא יתעצב וכו' ופירש דברי ה' שהם לאמר פירוש כוונת אמירתו היא על זה הדרך בקרובי וגו' ועל פני וגו' לשלול פירוש אחר שיתחייב ממנו לומר שלא ימות אלא אחד:
@235 **או** אפשר שמשה הבין גם כן דרך זה שאמר כאן בקרובי וגו' ועל פני וגו', והוא מה שרמז בדבריו או בי וכו' כי אומרו או יגיד שקדמה חלוקה אחרת והוא שניהם יחד והוא דרך שצדק לבסוף, או בי לבד, או בך לבד, ואחר מעשה הוכרע ספק השקול שכוונתו לאמר בקרבי וגו' ועל פני וגו' ולזה מתו ב'. ובזה נתיישבו הדקדוקים שדקדקנו בכתוב. ונשאר ליישב מכל מקום מי אמר למשה להכריע כן דלמה לעולם הכתוב כפשוטו ונקדש הבית בצדיק א' הנרמז בתיבת כבודי ומה שמתו ב' כי זכות שניהם מתאים לשיעור א' מהם משה או אהרן הנה בהשכיל על טעם הדבר נדע שאין זו קושיא, כי טעם הדבר הוא לצד שחש ה' שכשראו ישראל את אלהיהם שכן שמו בתוכם ואין גדולתו ומוראו ניכר כסדר שהוא ניכר בעליונים שלא יהיה מוראו עליהם כמצטרך ולא יתנהגו כשיעור הכבוד המתחייבים בו, ויותר יש לחוש לגדולי ישראל שיחשבו בדעתם שהם קרובים אל ה' וירצו להיות נגשים ומתקרבים, אשר ע''כ עשה משפט בגדול שבכולן שאין גדר למעלה ממנו לחוש לו לומר שבערך בחינתו לא תמנע ממנו הקריבה לה', ונשאר כל העם שומרים כבודו יתברך כאומרו ועל פני כל העם וגו'. ומעתה לכשנאמר כי משה בפני עצמו גדול מנדב או אביהוא אהרן בפני עצמו גדול מכל א' מהם גם כן, אם כן הניח ה' הדרגה שאין עליה מורא, ולצד התחברותם, הלא לא יועיל זכותו והשגתו של א' לחבירו להכינו לאושר להתקרב לשכינה, ואין הגבלת כבוד לה' אלא לגדר של כל א' מהם ולא לגדר גדול מא' מהם. ולכשנכחיש בחילוק זה ותרצה לומר כי יצטרף זכות ב'. אם כן עדיין יחסר הגדלת כבודו יתברך בערך משה ואהרן יחד, או שלשה כנדב ואביהוא, או ה' שיצטרף זכותם ליותר מזכות נדב ואביהוא, אלא ודאי כי לא יצדיק הצירוף כאן. ועוד תמצא שאין נערך זכות הנפרד לזכות הנסמך בבחינת המרגליות ואבנים טובות, שב' קטנים הגם שיהיו גדולים בהצטרפותם יחד מאחת גדולה לא תכנם עמהם הגדולה בהשוואת הערך, והדברים פשוטים:
@238 **ראשיכם אל תפרעו וגו' ועל כל העדה וגו'**.
@238 פירוש אם יעשו כמותכם, שאתם דוקא הוא שישנם באזהרה, אבל על כל העדה יקצוף אם יעשו כן, אלא חייבין לקרוע עליהם. ואולי ששפט בהם משפט אב בית דין שחייבין לקרוע עליו כל ישראל (מועד קטן כב:). ומה גם למה שאמר שהם גדולים ממשה ואהרן חייבים כל ישראל לקרוע עליהם. ואומרו **ואחיכם** וגו' **יבכו**, למצוה, ואם לא בכו אין עליהם קצף כמשפט הקריעה. ודקדק לו **אשר שרף ה'**, יתבאר על דרך אז''ל (שבת קה:) שכל הבוכה ומתאבל על אדם כשר מוחלין לו כל עונותיו ולא יבכה עוד, והוא מה שרמז באומרו אשר שרף וגו' פירוש אם יבכו השרפה אין להם אלא מה שכבר שרף מקודם לשלול שלא תהיה שריפה אחרת עוד. עוד ירצה באומרו **ולא תמותו ועל כל** וגו' פירוש כי באמצעות מיתת הצדיקים מגיע קצף לכללות ישראל, כי חוזק ישראל וחיותם הם גדוליהם הצדיקים ובפרט כהני ה' המכפרים בעד העם:
@248 **דרש דרש משה וגו'**. אומר אני כי משה לא החליט בדעתו להתירו באכילה, והראיה ממה שלא אמר להם דינו כמו שאמר להם במנחה (פסוק יב) קחו את המנחה וגו', שאם היה בדעתו בפשיטות להתיר היה לו לומר קחו את החטאת, מה תאמר שאמר דין המנחה וחשב כי אין הפרש בינהם כל עיקר ולרוב פשיטות שהיה לו הדבר לא הוצרך לומר אם כן לא היה לו לדרוש כי מנין נכנס לו המיחוש לדרוש עליו מה היה בו, אלא ודאי שלא אמר אלא הפשוט אצלו שהיא המנחה שהיא קדשי שעה וממנה לשעיר נחשון ושעיר עזים שהיו קדשי שעה, אבל שעיר ראש חודש שהוא קדשי דורות עדיין היה הדבר עומד אצלו בספק והיה דורש בדעתו אם יתירנו כמו כן או לא, ודרש עליו מה היה בו, ולזה כפל לומר **דרוש דרש** אחת למשפטו ואחת לעצמו מה היה בו והנה וגו' ויקצוף על אשר עשו דבר מדעתם שאפילו הוא עדיין לא ידע את אשר יצוה להם עשות. והגם שאמר לבסוף תאכלו אותה כאשר צויתי, פירוש יותר היה לכם לדמותה למנחה אשר צויתי לאוכלה ולא לשורפה בלא טעם הפך מה שצויתי במנחה. ובתורת כהנים אמרו דרש דרש מפני מה נשרף, ומפני מה (לא) נאכלו אלו, ובישוב הכתוב הדברים רחוקים, כי אחר הדרישות הוא שנגלית השריפה, ואיך ידרוש קודם למה נשרף. ויש לישב:
@248 **הנותרים לאמר**. אומרו **לאמר**, יתבאר על דרך אומרם ז''ל (ויק''ר פי''ג) הנותרים אמר ר' פנחם ולואי שלא נשארתם ע''כ. והוא אומרו הנותרים לאמר פירוש הנותרים לאמר ענין אחר, והוא דברי ר' פנחם, ובתורת כהנים אמרו לאמר אמר להם השיבוני על דברי פירוש הרשם להשיבו שלא ימנעו לצד ראותו בקצף עליהם עוד ירצה על דרך אומרם ז''ל (ב''ר פע''ג) בפסוק צאן לבן הנותרות שהוא לשון פחיתות, והוא אומרו **הנותרים לאמר** כאילו אמר לאמר הנותרים פירוש קראם במאמרו נותרים לשון פחיתות:
@251 **וידבר אהרן אל משה**. רז''ל (תו''כ) אמרו אין דיבור אלא לשון עז, יורה על דברים קשים. צריך לדעת איך יוצדק ענין זה באהרן עם משה. ואולי כי לצד שאמר משה לבניו הנותרים שהוא דבור דומה לקללה והוא עדיין בחרדת לב על ב' בניו שכבר מתו בו ביום והשטן מקטרג. ומה גם כששמע עקימת שפתיו של משה בדמיון הקללה, לזה חרד לבו ודבר בקול גדול לפני משה כי נכמרו רחמיו אל בניו:
@251 **הן היום**. רז''ל דרשו (זבחים קא.) שרצונו לומר וכי ביום זה הקריבו אלעזר ואיתמר שאסורים להקריב באנינות שאתה אומר שמא הקרבתם אותו באנינות ולזה שרפתם, אני הוא שהקרבתי וכהן גדול מקריב אונן. ופשט הכתוב הוא על זה הדרך **הז היום הקריבו** פירוש נדב ואביהוא את חטאתם ואת עולתם לפני ה' וכו', שכוונתו כי הוא אונן כי בו ביום מתו, **ואכלתי חטאת היום** פירוש חטאת של יום שהוא שעיר ראש חודש, וכאן רמז לו שישתנה זה ממנחה שהוא קדשי שעה אבל חטאת היום הוא קדשי דורות הייטב בעיני ה' לאוכלו. והיה נראה להוכיח מכאן ספק א', אם מותר לתלמיד להורות לעצמו הוראה במקום רבו, שראיתי להרא''ש ז''ל (עירובין פ' הדר) שכתב לאסור זולת סר סכינא שאין קפידא כל כך. והנה ממה שראינו שהורה אהרן הלכה זו לעצמן ושרפו החטאת משמע שמותר. ואין לך רב מובהק כמשה לאהרן. ואולי יש לדחות, כי אין הוראה זו הוראה, כפי מה שאמרו ביומא (רש''י שם דף ה:) שדן אהרן קל וחומר ממעשר הקל אמרה תורה לא אכלתי באוני קודש חמור לא כל שכן ע''כ. וכיון שנאמר לו מפי משה דין מעשר כאלו אמר לו משה לשרוף ולא הורה הוא לעצמו כלום, כי בכלל מעשר חטאת בקל וחומר וכגון זה מותר לתלמיד להורות, וקל הוא מביעתא בכותחא. ועיין בדברי התוספת שם (עירובין סב:) פירוש הוראת ביעתא בכותחא:
@252 **וישמע משה וייטב וגו'**. יש לדעת איך נתעלמה ממנו הלכה פשוטה כזו לחלק בין קדשי דורות לקדשי שעה. ואם היה לו איזה צד לומר שאין לעשות חילוק זה, למה קבלו מאהרן ולא דן עליו לסותרו. והנה לפי מה שפירשתי למעלה כי גם משה היה צריך לעמוד על הדבר אם לאכלה אם לשרפה, ולא היה לו מוחלט הדבר לאכילה והקפדתו על אהרן ובניו היתה לצד שחשב ששרפוהו בלא טעם נכון, או לצד שמא אירע לה איזה מאורע כמאמר רז''ל (פסחים סב. זבחים קא) שאמר להם שמא אירע בו פסול בהקרבת דמו או נטמא או יצא חוץ למקומו, וכל אלה הדברים הם לצד מיעוט זריזותם, ועל זה היתה ההקפדה, מה שאין כן אחר שאמר לפניו אהרן הדין שדן בו ושרפו קבל משה הטעם וראה שלא שרף אלא אחר שדן דין צדק, ואין הכי נמי אם לא היה דן אהרן והיה דן משה כזה היה דן בדבר ושורפו, ולא יבצר ממנו כל דבר, ואומרו **וייטב בעיניו**, פירוש את אשר עשו בשריפתו, ולא הקפיד על אשר סמכו על עצמן ולא שאלוהו:
@252 **או** ירצה **וייטב בעיניו** אהרן כי טוב הוא ויורה יורה ידין ידין:
@252 **או** ירצה **וישמע משה** פירוש התורה מעידה שחילוק זה שמעו משה מפי הקב''ה, **וייטב בעיניו** הדבר אשר עשה אהרן. ואם תאמר אם שמע כן מפי הקב''ה מה מקום להקפדתו. אולי לצד שלא אמרו עדיין לאהרן חש שדן בו טעם אחר שאינו צודק ושרפו, או אפשר כי באותו שעה נאמרה לו נבואה זו, כי מצויה היתה נבואה למשה, כאומרו (במדבר ט ח) עמדו ואשמעה מה ידבר ה', וכמו כן כאן תיכף וישמע משה מפי ה' המשפט וייטב בעיניו אשר צדק אהרן במשפטו. ורז''ל אמרו במדרש (תו''כ כאן) וזה לשונם אמר רב יהודה חנניה בן יהודה היה דורש כל ימיו קשה ההקפדה שגרמה למשה לטעות, אחר מיתתו אני משיב לו על דבריו, וכי מי גרם לו שהקפיד אלא שטעה ע''כ. טעם אומרו כל ימיו, גם טעם חנניה שלא אמר כרב יהודה שהוא היותר מובן מפשטי הכתוב, גם טעמו של רב יהודה שלא חלק אלא אחר מותו יראה כי חנניה ורב יהודה כל אחד מתכוין לדבר טוב על משה, לצד שיש לפנינו ב' דרכים. הא' השכחה אשר אמר לו ה' והוא שלא מן המוסר לנאמן בית, ב' שנתכעס על בני אהרן ודבר להם קשות כנזכר, וגם לצד אהרן קצף בדרך נסתר. ובא חנניה ובחר לתלות כמשה שגיון הכעס ששגג בו והוא סיבה לטעות מלומר ח''ו ששכח דבר ה' שהוא דופי גדול. וכמו כן מצינו בספרי (מטות פסוק נז) שאמר ראב''ע בג' מקומות בא משה לכלל כעם ובא לכלל טעות וכו', כיוצא בדבר ויקצוף משה על אלעזר וגו' ע''כ. מכאן אתה למד שהדבר שעליו הקפיד לא (מצד) הטעות. ואם תאמר אם כן למה הקפיד אם לא טעה, בהכרח לומר שהקפיד על אשר דנו בדעתם וסמכו על הוראתם מבלי שאלת רבם, ועל זה נתעלמה הימנו הלכה ואמר אכל תאכלו, וסובר כי בהחלט הוא אומר כפי הדין שראוי לאכלה, לא כמו שפירשתי שאין דבריו בהחלט אלא שאומר צד הנגדי למעשיהם, ובא רב יהודה וחלק כי אין לתלות במשה ההקפדה בהחלט, כי יש בהקפדה צד לומר שהיא גרועה מהעלם דבר ואפשר לתלות שטעה ושגג בדין ולצד שגיונו הקפיד על המעשה שנעשה שלא כרצונו יתברך אבל זולת הטעות לא יקפיד על כבודו. והנה דעת זו לא היתה מוכרעת לרב יהודה אלא שקולה, שיש פנים להקל בבחינת ההקפדה, ויש פנים להקל בבחינת הטעות, ולזה לא חלק על חנניה אלא אחר מותו שעמד בדרשה זו ולא אמר פן האחר שישנו במשקולת ההשכל, משמע כי מוכרע אצלו הדבר כי הקפיד ובזה חלק עליו, ולזה דקדק לומר אחר מיתתו אני משיב. ובנוסח ספרא שלפנינו אמרו הריני כמשיב על דבריו, וממה שאמר כמשיב משמע ולא משיב, ויכוין ג''כ לדברינו. או אפשר לומר כי רב יהודה בחר בהחלט לומר טעמו של משה הוא לצד שטעה מלומר שהקפיד שהוא מעשה בלתי הגון, כי הטעות יכול אדם לטעות בהסח הדעת, מה שאין כן ההקפדה שהוא מעשה מזיד, ועוד אם נאמר שטעה הרי לא יצתה תקלה מטעות, ואם נאמר שהקפיד הרי יצתה תקלה מתחת ידו שהרי הקפיד ונתכעס, ולזה בחר רב יהודה לומר מי גרם לו שהקפיד אלא שטעה. וטעם אומרו אחר מותו, לומר שאפילו כל ימיו דרש ואפילו כבר מת הדורש לא נמנעתי מלחלוק לצד אמיתות הדבר אצל, או נתכוין לומר שלא חלק עמו בפנים ושתק אלא לאחר מותו שאפשר שאם היה בחיים חיותו היה משיב על הדבר להוכיח כמותו ורז''ל אמת יהגה חיכם:
@253 **אל משה ואל אהרן**. אמר **ואל אהרן**. אולי שנתכוון לעשות שניהם יחד שליחות מצוה זו אל ישראל, וכן גמר אומר **דברו אל בני ישראל**, וכן אמר בפרשת בא (יב א) אל משה ואל אהרן וגו' דברו וגו', כי לענין הקדמה שיקדים משה לומר לאהרן קודם ישראל כבר למדנו זה ממקום אחר:
@253 **לאמר אליהם**. רז''ל אמרו (בתו''כ) אליהם פירוש שיאמר לאלעזר ולאיתמר והכוונה בזה כדי להקדימם בלימוד קודם כדתניא (עירובין נ''ד) בסדר הלימוד. ואולי שנתכוון להצריכם להורות בני ישראל על דרך (מלאכי ב) כי שפתי כהן וגו', ואשר על כן סמך לזה דברו וגו'. עוד יתבאר אומרו **לאמר אליהם** לפי מה שפירשתי במקומות אחרים (יתרו כ א) כי טעם אמרו לאמר כי הדיבור היוצא מפי אל עליון היה נוצר ממנו מלאך והוא היה מדבר עם משה, ופירוש לאמר הוא הדיבור יאמר למשה, וכמו כן אמר כאן לאמר אליהם פירוש הדיבור יאמר למשה ולאהרן. ואין פירוש זה מכחיש דברי רז''ל שאמרו (תו''כ א) לא היה הדיבור אלא למשה ולא לאהרן, כי גם לדרכינו לא היה שומע דברי ה' אלא משה, אלא שהמלאך המתהוה מהדיבור היה מדבר לשון רבים, ומשה היה מגיע הדברים לאהרן:
@254 **אל בני ישראל לאמר**. אמר תיבת **לאמר** ירצה כי מצוה זו היא בחינת המעלה והכבוד להם, להשמר מדברים הטמאים, וכאומרם בזוהר (ויק''ר פי''ג) אמר רבי שמעון בר יוחאי בפסוק (חבקוק ג) עמד וימודד ארץ מדד ה' את כל האומות ולא מצא אומה שהיא ראויה כו', ופירוש תיבת לאמר כאן הוא על דרך (ישעי' ג') אמרו צדיק וגו'. עוד ירצה על זה הדרך לאמר זאת וגו' פירוש שיקחו בידם כל מין חיה ויאמרו להם זאת תאכלו וזאת לא תאכלו, ולא יספיק לומר להם בעל פה:
@254 **זאת החיה וגו'**. טעם שמכנה שם חיה בהמה, כבר כתבתי בכמה מקומות כי בחינת הרע לא יתייחס אליו בחינת החיים, והוא אומרו **זאת החיה** פירוש שיש בה בחינה הנקראת חיה, לשלול שאר בהמות שאין להם קדושה שהיא בחינת החיים:
@255 **כל מפרסת וגו' מעלת גרה**. יתבאר על דרך אומרם ז''ל (חולין נט.) כל בהמה שמפרסת פרסה היא מעלת גרה, חוץ מן החזיר, והוא אומרו **כל מפרסת** וגו' **מעלת גרה**, פירוש בידוע שהיא מעלת גרה, ומיעט אחר כך החזיר שיצא מהכלל. ואולי ממה שלא הוציא מן הכלל סמוך להודעת הכלל רמז שאפילו החזיר בכלל, על דרך אומרם ז''ל (רבינו בחיי בשם תנחומא) למה נקרא שמו חזיר שעתיד לחזור להיות מותר, ומעתה כלל כל מפרסת וגו' היא מעלת וגו' לא יצא מכללו דבר, ועל זמן מהזמנים אמר החזיר שהוא מפריס וכו' לא יגר:
@256 **ממעלי וגו' וממפריסי וגו'**. רז''ל אמרו (תו''כ בכורות ו) שבא לאסור אפילו מעלה ומפריס אם נמצאו במעי טמאה. ופשט הכתוב הוא על זה הדרך ממעלי הגרה זה הגמל, וממפריסי וגו' זה החזיר, או זה או זה קאמר, ולזה דייק לומר וממפריסי וגומר, ולא אמר ומפריסי, והבן:
@258 **ואת הארנבת**. טעם זכרון המין בלשון נקבה לצד שבחינת הטומאה לפעמים תהיה הנקבה למעלה מזכר ויהיה הזכר טפל לה, ותזכר הנקבה מהטעם עצמו שיזכר הזכר תמיד ולא הנקבה, שהוא הטעם כי היא העיקר, ותמצא שאמרו בזוהר (פנחם רלא:) בסוד יותרת הכבד כי הנוקבא נותנת יותרת לזכר, וכבר כתבנו שכל מין הנאסר היא בחינת הקליפה המושלל מהחיים והטוב:
@259 **והוא גרה לא יגר**. פירש תנאי הוא הדבר לזמן שהוא לא יגר אבל לעתיד לבא יעלה גרה ויחזור להיות מותר, ולא שישאר בלא גרה ויותר כי תורה לא תשונה:
@262 **שקץ הם לכם**. פירוש ולצד זה שקץ יהיו לכם וטעם אומרו **ושקץ** בתוספות וא''ו, יתבאר על דרך אומרם בחולין (ה.) אין הקב''ה מביא תקלה וכו' וכל שכן על ידי צדיקים עצמן, וכתבו התוספת (שם) כי דוקא בענין איסור אכילה גנאי הוא לצדיקים שיבא לתוך גופן דבר איסור פירוש ואפילו בשוגג, וזה הוא שרמז כאן באומרו **ושקץ יהיו לכם** פירוש לרבות אפילו בשוגג שלא תתכוונו לאוכלם אף על פי כן ישקצו את הנפש. עוד ירמוז כי הם ישקצוהו ויסבבוהו להרים תולעים במותו, והוא אומרו **שקץ יהיו לכם** פירוש לעצמכם יעשו אתכם שקץ:
@266 **ואת האיה למינה**. (האיה) האמורה כאן כולל הרבה מינין שכולם מין איה, ותמצא שאמרו רז''ל (חולין סג:) כי ק''ך מיני עופות היו ידועים להם שכולם מין איה, ואפשר שיהיו עוד כהנה, וכן במינו של עורב ימצאו כמה וכמה הגם שאינם דומין ושמם משונה כסינונית לבנה (תו''כ וגמ' שם סב.) שהיא מין עורב:
@273 **אשר לו כרעים**. כבר הארכתי בחיבורי על טור ויורה דעה (סי' פה) שהעיקר כפירש''י בזה שצריך שיהיו לו כרעים הארוכים סמוכים לצוארו. והטועים להתירה כי אין מין זה בנמצא, אף אני השיבותי אותו גם אין מצויים אלא מין א' מהד' שהם שמנה אשר רשם ה' בטהרה (חולין סה.), גם אינם מצויים לפנינו מינים הטמאים שאין להם הכרעים בדרך זה, והם הרבים, למה שקדם לנו (שם סג) כי לא ימנה הכתוב אלא המועטים, וכאן מנה הטהורים אם כן הטמאים הם המרובין, ומעתה אין ראיה ממה שאין מצוי מין זה לומר שאיננו בעולם שהרי יש מינים הרבה ודאי ואינם מצויים כל עיקר אצלנו, לכן כל ירא וחרד ירא ויפחד לבל יושיט ידו לשקץ זה, וימחה בשולחי יד. והנה מיום שנשמעו דברי במערב ופירשו מהם הרבים לא נגע ה' עוד במכה זו ולא נראו זה יותר מי''ב שנה, כי תורה ומעשים טובים כתריס בפני הפורענות:
@275 **אשר לו ד' רגלים**. בתורת כהנים דרשו שבא להתיר מי שיש לו ה'. ונראה שהוא הדין מי שיש לו ו' וז' ולאו דוקא ה', וצריך לדעת לאיזה ענין התיר בת ה' מן הדיוק ולא אמר בפירוש כל שרץ העוף שיש לו ה' רגלים או על זה הדרך מד' רגלים ומעלה תאכלו. ואולי שהוצרך להשמיע גם כן דין היתר ציר חגבים טמאים, שדרשו ז''ל (בתו''כ) מאומרו בפסוק זה שקץ הוא פרט לעירוביו שהוא ציר כמאמרם שם, ולזה בחר להשמיענו היתר בת ה' רגלים באופן זה:
@276 **ולאלה תטמאו**. בתורת כהנים פירשו אומרו **ולאלה** על העתידים ליאמר בענין למטה. וקשה לי למה אמר ולאלה בתוס' וא''ו כיון שאין לו שייכות דין זה עם מה שלמעלה ממנו ולא שלמעלה עמו. ואולי נתכוון ליתן העליון כתחתון, פירוש שכל מין בהמה וחיה בין טמאים שאינם לא מעלה גרה ולא מפריסי פרסה שלא נרשמו כאן בכתוב, ובין טהורים שמעלים גרה ומפריסים פרסה ושוסעת שסע שלא נרשמו גם כן בכתוב ורמזם באומרו לכל הבהמה, וכלל זה חוזר למה שרשם בפרשת סימני בהמה, ולזה אמר ולאלה בוא''ו. כדי שלא תטעה ליתן כל האמור למעלה, לזה פרט שאין דבריו אלא בבהמה וחיה. או ירצה להסמיך דין טומאה לדין אכילה האמור בפרשה שלפניה וגו' מה אכילה בכזית גם טומאה בכזית. ובתורת כהנים העמידו הכתוב שלא בא אלא לטומאת אבר מן החי של בהמה טמאה ובהמה טהורה, ודרשו טומאה בכזית מפסוק אחר דכתיב (פסוק מ) והאוכל מנבלתה יכבם בגדיו וטמא עד הערב, וזה לשונם לא בא אלא ליתן שיעור לנוגע ולנושא בכזית כמו האוכל. ואפשר לומר עוד שרמז בסמיכות זה לומר שאם ילדה כמין בהמה הסמוך לה דינו שוה. וראיתי לראב''ע ז''ל שכתב שלדעתו נראה שמלת אלה חוזרת על כל הנזכרים למעלה, ודחה דעת האומר אלה לכל הבהמה וכו'. ואני אומר שיותר היה לו שלא לומר דבר שאינו נשמע ולא יחלוק על מקבלי תורה, כי מי ישמע לדבריו כאן ואפילו ללומדם והם הפך קבלת תורת משה, ומה גם בפשט הכתוב שאפילו בי רב זוטר כן יבין בתחילת ההשכל, וממי נעדר את אשר ראו עיניו ויותר מהמה, ומה כחו לחלוק עמהן גם בלא הכרח ואפילו אם יהיה המנגדו כיוצא בו ומכל שכן גדולים ממנו וכל שכן וקל וחומר אשר קטנם עבה ממתניו, וצא ולמד מה שאמרו האמוראים על גדולים שקדמום (שבת קיב:) אם הראשונים וכו'. וללמד על הרב ז''ל זכות אולי שפירוש זה לא כתבו אלא לסיבה ידועה לו, ונהג מנהג ע' זקנים (מגילה ט.) ששינו בכמה מקומות, וגם לזה ה' יכפר בעדו:
@281 **וזה לכם הטמא**. טעם אומרו וזה, לפי מה שפירשו שם בתורת כהנים בפרשה שלפניה שבא לטומאת אבר מן החי אמר וזה להשוות למה שלפניו שגם הוא מדבר בדין טומאת אבר מן החי שהאבר הוא שמטמא ולא הבשר הפורש בין בשרצים בין בבהמה וחיה. עוד נראה כי וא''ו האמורה כאן בתחילה לא להסמיך באה אלא לרמוז תוספת טומאה בשרץ שהוא טומאת דמו שיהיה מטמא כבשרו, מה שאין כן בבהמה טמאה כמאמר רז''ל בתורת כהנים (כאן) וכאילו אמר ועוד תוספת טומאה בזה. ואומרו **לכם** דרשו ז''ל (תו''כ כאן) שבא למעט שלא יכשיר הזרעים, דדוקא לטומאה ולא להכשירה, והוא אומרו לכם הוא טמא ולא מכשיר. עוד ירצה **לכם** הוא שהם טמאים אבל לא לגוים, שאין הגוים מקבלים טומאה כבהמות. ויש לחקור זאת איך לא מנה הכתוב הנחש שהוא אב הטומאה לכל טומאת השרצים ודומיהם ואולי שטומאת הנחש הוא בנפשו ולא בגופו ובמותו ישאר הגוף ריקם מכל כעפר הארץ כי אין טומאה דבקה בגופו לצד שאין בו ולא כלום וכיוצא בזה תמצא שאמרו ז''ל (ב''מ קיד:) גוים אין מטמאים באהל, וישראל מטמאים באהל והוא מהטעם עצמו, וטומאת השרצים בגופם יותר מבנפשם, ולזה יטמאו במותם ולא בחייהם, הא למדת כי הנחש טומאתו יותר מטומאת השרצים:
@281 **למינהו**. פשט למינהו יגיד כי יש הרבה מיני צב וכל שיש בו מינים הרבה או אפילו מין אחד לבד יאמר הכתוב למינהו. אלא שבהעור והרוטב (חולין קכב:) תניא וזה לשונם הטמאים לרבות עורותיהן כבשרן, יכול אפילו כולן תלמוד לומר אלה, והא אלה אכולהו כתיב, אמר רב למינהו הפסיק ע''כ. וקשה מנין לרב לומר כי למינהו באה להפסקה ולא לגופה לומר שיש בו מינים. ונראה כי רב אינו מכחיש משמעות הכתוב וכוונתו היא כי לצד שיש לפנינו רבוי של הטמאים לרבות עורותיהן, ואמר הכתוב סמוך לרבוי זה מיעוט דכתיב אלה, ואם לא היתה תיבת למינהו באיזה דרך נחלק אותן שבא עליהם הרבוי ואותן שמיעט, ומאומרו למינהו הגם שבאה לגופה תועיל גם כן להפריד בין המתרבים בטומאת עורותיהן, כיון שהכתוב גילה שיש חלוקה ביניהם לענין טומאה הרי זה מראה כי למינהו בא גם כן לסמן החלוקה. ובזה נתישבה קושית התוספת שם בד''ה למינהו וכו' תימא כיון דהפסיק בענין אלה למה לי עד כאן ולדרכנו לא קשה. גם לדברי תנא דמתניתין שם דמטמא עורותיהן משום דאזיל בתר גישתא אין להקשות עליו למינהו למה לי, שעכ''פ איצטריך למינהו לגופה כנזכר:
@283 **הטמאים**. לתנא שאינו דורש טומאת עורותיהן מהטמאים למה איצטריך, אז''ל (בתו''כ) שבא לרבות ביצת השרץ שרקמה. גם דרשו (ת''כ מעילה יז) שיצטרפו לטומאה דם בדם דם בבשר בין במין אחד בין בב' מינים. וצריך לדעת תיבת **אלה** מה בא למעט לדרכו. ונראה לפרשה על דרך מה שכתב הרמב''ם בפרק ד' מהלכות אבות הטומאות דם השרץ כבשרו ומצטרף לכעדשה כל זמן שהוא מחובר לבשרו, לזה אמר אלה למעט אם פירש הדם מן השרץ לא יצטרף עם הבשר:
@292 **והאוכל מנבלתה וגו'**. בתורת כהנים אמרו שלא בא הכתוב אלא ליתן שיעור לנוגע ולנושא שהוא כדי אכילת כזית, ואין כוונת הכתוב כפשוטו שתטמאנו בבית הבליעה, שהרי מצינו שאמר בנבלת עוף הטהור (אמור כב ח) ולא יאכל לטמאה בה, בה אתה מטמא בבית הבליעה ואי אתה מטמא בנבלת בהמה בבית הבליעה. וצריך לדעת למה לא אמרה התורה הדבר בפירוש, ואולי כי נתכוון הכתוב להרבה דינים שישנם בדין אכילה מלבד שיעור כזית, גם אמרו (חולין עא.) בשר השרץ שנפסד והבאיש ונפסל מלאכול הכלב טהור ע''כ, ודבר זה נלמד מדין אכילה כמו שכתבו התוספת עלה כ''ג דממה שאמר הכתוב (מלכים ב) בחלק יזרעאל יאכלו הכלבים אלמא אכילת כלבים שמה אכילה וכו', ואם כן לצד שנתכוין הכתוב להשוות הטומאה לדין אכילה בין לשיעור בין לשאר דברים לזה אם היה בא ללמד כל פרטי הדינים צריך להוסיף דברים רבים, וכסף נבחר לשון צדיק:
@292 . (מג) **אל תשקצו וגו'**. צריך לדעת למה חזר עוד לצוות לזה ורז''ל (בתו''כ) אמרו לרבות את שפירשו לארץ וחזרו, ודרשה זו אמת אלא שאינה צריכה כיון שפירשו וכי בשביל שחזרו יהיו מותרים. ויש ליישב דבריהם ז''ל. ואולי שבא הכתוב להודיע כי האוכל מהשרצים תעשה נפשו עצמה שרץ, והוא אומרו **אל תשקצו את נפשותיכם** פירוש לא תעשו נפשותיכם שקץ ובמה בכל השרץ השורץ על הארץ כשתאכלו אותה. ולך נא ראה מה שכתבנו בפרשת בראשית ברמז פסוק (א כו) וירדו בדגת הים וגו'. ותמצא מאמרם ז''ל (פסחים מט:) שאמרו על עמי הארץ הם שרץ ובנותיהם שקץ וגו', וכל דבריהם ז''ל ברוח הקודש נאמרו והם דברינו עצמם. ואומרו **ולא תטמאו בהם** אולי שיכוין לומר שצריכין ישראל להזהר לבל יכנסו לפיהם אפילו בהיסח הדעת, כי ההפרש שבין השוגג למזיד במציאות זה כשוגג כמזיד, כי התיעוב יעשה מעשהו בנפש אדם אפילו בהיסח הדעת, אלא שישתנה הפגם במעשה מזיד תעשה נפשו שקץ ובשוגג תטמא נפשו ותטמטם, והוא אומרו **ולא תטמאו ונטמתם בם**. וצריך האדם ליזהר בתוספת זהירות וזריזות בכל דבר אשר יכנס בגדר ספק שיקוץ זה, ומה גם בזמנים אלו שנזהם האויר והארצות כולן יחד ואין לך גידולי קרקע שאין בהם מהשיקוץ שומר נפשו ישמור את הדבר:
@296 **כי אני ה' אלהיכם**. פירוש ומשונה אומה ישראלית לקדושה וטהרה שלא בחר ה' ליקרא אלוה אלא לישראל, לזה צריך להרחיק מן הטומאה:
@296 **והתקדשתם וגו'**. פירוש אם אתם מתקדשים אני אקדש אתכם לבל יכנס לגופכם דבר שיקוץ על דרך אומרם (חולין ה:) אין הקדוש ב''ה מביא וכו' וכל שכן צדיקים עצמן, והעמידו התוספות מאמר זה בדבר איסור הנכנם לגופו של אדם כי הקב''ה ישמרהו בזה:
@296 **עוד** ירצה **והתקדשתם** תעשו גדרים וסייגים לבל תטמאו ובזה אני מבטיחכם שתהיו קדושים. וחזר ופירש באיזה דבר יהיו קדושים, ואמר **כי קדוש אני** הנה מה שתולה טעם קריאתם קדושים שהוא לצדו הא למדת כי השרה שכינתו על הפרושים ולזה יקראו על שמו. ואומרו **ולא תטמאו** וגו' פירוש מלבד דברים שאתה מעלה על דעתך לשמור עצמך מהם עוד אני מבטיחך שלא יאונה לך כל מין הרע, והוא אומרו בכל השרץ הרומש וגו'. עוד ירמוז שבאמצעות שמירת מצוה זו לא ישלטו עכו''ם בעם בני ישראל עכו''ם יקראו שרצים ושקצים הרומשים על הארץ:
@297 **כי אני ה' המעלה וגו'**. נותן הוכחה לעיניהם כי ה' ישמור אותם מהכשל בעון ההוא, כי הוא העלה וברר נפשות ישראל שהיו נתונים בקליפת מצרים כמו שפירשנו במקומו, ואם יזונו מהתיעוב הנה הנם חוזרים לשקע נפשם בקליפה כבראשונה, ואשר על כן כשיתקדשו הוא יגמור בעדם לשומרם. עוד ירצה לומר כי אין הקב''ה כביכול יכול ליחד שמו ולהשרות שכינתו אלא על המושלל ממין הרע ההוא, ולזה לא יחד שמו עליהם עד שהוציאם מארץ מצרים, ואם לא ישמרו עצמם מהתיעוב הנה הנם חוזרים להיות כמות שהיו קודם עלותם מארץ מצרים, ויהיו מושללים מבחינה זו:
@298 **זאת תורת הבהמה והעוף**. כל הכתוב מיותר ובתורת כהנים אמרו (בחולין כז:
@298 מבואר כדבדי רבינו) כי בא לומר משפט שחיטת העוף במה שסדר העוף בין הבהמה ובין הדגים שהם נפש החיה לומר חציו בהמה וחציו דג, לזה צריך סימן אחד בעוף או רובו. ולפי זה מצאנו טעם נכון שהוצרך הכתוב למעט הדגים מן השחיטה דכתיב (במדבר יא כב) יאסף, כי מנין יעלה על הדעת שצריכה, שהוצרך למעט, אלא לצד שהוצרך לכתוב דגי הים לתת בינו ובין הבהמה העוף, חש לטעות כי כוונת הכתוב הוא שהשוה הכתוב העופות והדגים לבהמה שכולן צריכין שחיטה ב' סימנים, לזה אמר בדגים אסיפה ובזה תבין כוונת ה' בפסוק שלא בא אלא לעוף להצריכו סימן אחד כנזכר. ואם תאמר אם כן למה הוצרך להזכיר כאן נפש השורצת שהם החגבים. ויש לומר שחש הכתוב לטעות מפסוק שמיעט שחיטה בדגים דכתיב יאסף וגו' כי לא מיעט אלא דגים ולא חגבים, לזה סדרם אחר הדגים לומר שאינם צריכין שחיטה כמשפט הדגים:
@298 **חסלת פרשת שמיני**
@301 **דבר וגו' לאמר**. טעם אומרו לאמר פעם ב' ואולי כי להיות שמצוה זו עיקר אזהרתה היא על הנשים, לזה אמר לאמר לנשים שיזהרו בדבר. עוד יתבאר על פי מה שאמרו בספרא (תו''כ כאן) בני ישראל בענין זה ואין הגוים בענין זה עד כאן, לזה אמר לאמר לשון אמרות ורוממות כי ענין זה שהתנה להיות בישראל ולא בעכו''ם הוא לצד המעלה והכבוד אשר ה' האמיר עמו, מה שאין כן בעכו''ם כי נפשם וגופם טמא:
@301 **אשה כי תזריע וגו'**. צריך לדעת למה הוצרך לומר **כי תזריע וילדה** ולא הספיק לומר אשה כי תלד זכר. ורז''ל נחלקו (בתו''כ הכא) חכמים אומרים למעט יוצא דופן כי צריך להיות הלידה במקום הזריעה, ור' שמעון אומר לרבות ילדתו מחוי. ועוד יש לאלוה מילין בהעיר עוד, למה שינה הכתוב את לשונו שהתחיל לדבר לשון עתיד **תזריע** וגמר אומר **וילדה** ולא אמר ותלד, וכמו שאמר גם כן בסמוך ואם נקבה תלד. והגם שהרבה כתובים מדברים בסדר זה עבר במקום עתיד, אף על פי כן דבר יגידו בשנות לשון. עוד למה אמר **וילדה** שמשמע ודאי ולא אמר אם תלד זכר שהרי אין ודאית לזכר יותר מהנקבה. ולזה יש לומר שאומרו כי תזריע הרי כי משמשת אם, ונמשכת למטה עם וילדה, וזה דוחק. ורז''ל אמרו בהמפלת (נדה לא.) ובהרואה (ברכות ס.) אשה מזרעת תחלה יולדת זכר, ולזה אמר וילדה ודאי. והגם שדרש רבי צדוק דרשה זו מפסוק (ויגש מו טו) ואת דינה בתו תלה הכתוב זכרים בנקבות, ונקבות בזכרים, נראה כי משם אין ידוע טעם התליה, וכאן גילה הכתוב טעם התליה כי תזריע תחלה. ולא הוצרך לומר תחלה, שאם לא כן על כל פנים צריך שתזריע בין ללידת זכר בין ללידת נקבה, ולא הספיק פסוק זה והוצרך לפסוק ואת דינה בתו, ללמד על איש תחלה יולדת נקבה. ויש עוד לאלוה מילין. ויתבאר על דרך אומרו (תהלים קלט) אחור וקדם צרתני ודרשו ז''ל (ב''ר פ''א) אחור לכל המעשים וקדם למעשה בראשית דכתיב ורוח אלהים מרחפת וגו', הרי כי ב' יצירות באדם יצירת הרוח ויצירת הגוף. והנה בעת ההזרעה אמרו ז''ל (זוהר קדושים פ.) כי כפי הכוונה אשר יכוין המזריע ימשיך לזרע הנפש, אם יחשוב מחשבות רעות ומזוהמות ימשיך לטפה נפש טמאה ואם יחשוב בטהרה ימשיך נפש קדושה, וצא ולמד (ברכות י. ד.) מבניו של הצדיק המופלא חזקיה המלך עליו השלום אשר נשא בת נביא ולצד שחשבה האשה בעבדי מרודך בלאדן המשיכה נפש רעה לב' בניה (סנהדרין קד.). אם כן עיקר הלידה שהיא המשכת הנפש לעובר היא בשעת ההזרעה, וקודם לה מלפניה, כי אחר הוצאת הזרע כבר קדם כח החושב שממנו יתהוה הזרע, והוא מאמר הכתוב **כי תזריע וילדה** מודיע הכתוב כי עיקר הלידה היא בשעת ההזרעה שכאשר תזריע כבר ילדה והיה מה שהיה אם נפש טהורה אם לא ואין תקוה להפך מה שכבר הוא, ומעתה מה שיתעצם האדם בבחינת הלידה הוא בשעת ההזרעה כי אז היא עיקר הלידה לבחינת הנפש שהוא העיקרית באדם, והויות הדבר והמצאתו הגם שהוא נעלם תקרא לידה. ומתוכיות דברינו אלה תשכיל אומרו (לד יב ה) ואת הנפש אשר עשו בחרן שהם הנפשות שעשו בזיווגם, הגם שלא היתה שרה יולדת, כל זיקה וזיקה היו מולידים נפשות, והגם שלא נבנה הגוף להם לא מפני זה יכחד האמת, ואומרו **זכר**, רמז כי גם יש כח במוציאים בשעת ההזרעה להוליד זכר כפי הכוונה אשר יכוין להמשיך נפש מעלמא דדכורא:
@301 **עוד** ירמוז הכתוב לצד שעיקר הבנים היא האשה וחש הכתוב לה לצד שאינה חייבת לא תתרצה בהולדה לצד הצער שסובלת גם לה שמתגנת בלידה, אשר על כן לא תחפוץ להנשא, ואם תנשא יהיה כוונתה למלאות תאותה הבהמית כי שלה גדול (גיטין מט:), לזה בא הכתוב והבטיחה כי הגם שאינה מצווה אם תעשה כסדר האמור יהיה לה יתרון ומעלה כזכר, והוא אומרו **אשה כי תזריע** וגו' פירוש אשה שתעשה פעולה זו שתזריע כאן שלל מניעת הזיווג, **וילדה** פירוש תהיה כוונתה בהזרעתה לתכלית הלידה ולא לתאוה בהמית, ואם לא אמר אלא אשה כי תלד היתה הכוונה כל שתלד הוא אומר, ולא כן הוא, אלא מי שמכוונת בזווגה אל הלידה זאת האשה היא במדרגת זכר, והוא אומרו **זכר**, ואמר **וילדה** ולא תלד, לומר שלא תשיג הגדר ההוא אלא אחר שיצא הדבר לפועל. ואולי כי לזה נתכוון באומרו **לאמר** וסמך לה תיבת **אשה** פירוש לאמר לשון מעלה ורוממות למי אשה כי תזריע וילדה ומה מעלתה זכר בכל פרטי הבחינות אשר יגדל בהם הזכר על האשה. ואולי כי לזה נתכוין אומרו (משלי י) ובן כסיל תוגת אמו, כי לה נוגע החסרון מטעם הנזכר. עוד ירמוז הכתוב על כנסת ישראל אשר מצינו שנקראת אשה בדברי הנביאים דכתיב (ישעי' נד) כי בועליך עושיך, וכתיב (שם) ואשת נעורים, וכתיב (הושע ג) וארשתיך לי וגו', (ישעי נ) איזה ספר כריתות וגו', ועליה אומר הכתוב אשה כי תזריע פירוש הזרעת מצות ומעשים טובים, על דרך אומרו (הושע י) זרעו לכם לצדקה, **וילדה זכר** פירוש תהיה הולדתה זכר פירוש דע כי בחינת הזכר היא בחינה עליונה מבחינת הנקבה והתורה מיחסת בחינות העליונות בבחינת הזכר, והודיע הכתוב כי אם כנסת ישראל תזריע ודאי שתוליד הדרגות עליונות, והוא מאמרם רז''ל (סנהדרין צח שמו''ר פט''ו כאן) עוצם הפלגת הפלאות אשר יפליא ה' בביאת הגואל אם ישראל יזכו על ידי מעשיהם הכשרים, ויכוין להבדיל בין הגאולה המחוכה לגאולה שעברה של מצרים שהיו ישראל ערום ועריה, גם אמר הכתוב (דברים ד לד) גוי מקרב גוי ואותה גאולה תכליתה לא עמד כי נחרב הבית וגלו והיה מה שהיה ואין טובה זו בבחי' זכר, אבל הגאולה העתידה לצד שעל כל פנים תהיה באמצעות זכות ישראל, לו יהיה שלא יהיו ראויים אף על פי כן באמצעות אורך הגלות ועסק התורה דכתיב (דברים לא) לא תשכח מפי זרעו על כל פנים תהיה הגאולה בבחינת זכר, ועמדה לנצח. ואומרו **וטמאה** וגו', כאן רמז תיקון אשר יעשה ה' להשיג בחינת הזכר, כי ז' שנים יכונן חבלי משיח, כאומרם (סנהדרין צז.) ז''ל שבוע שבן דוד בא וכו' ליסרם ולזקקם, והוא אומרו וטמאה יחס היסור לבחינת הטומאה כי הוא הטמא הוא המיסר, ואמר ז' ימים פירוש שבע שנים, על דרך אומרו (כתובות נז:) תשב הנערה אתנו ימים או עשור ואמרו ז''ל ימים שנה, **וביום השמיני** וגו' פירוש שאחר עבור ז' שנים בהתחלת יום השמיני, ימול בשר ערלתו, כי אז יעביר ה' בחינת הערלה מהעולם, דכתיב ואת רוח הטומאה אעביר מן הארץ, וזה יהיה בשנה ח', וידוע הוא בחינת הערלה שהיא הקליפה:
@302 **וביום השמיני וגו'**. צריך לדעת למה הוצרך לצוות לזה והלא כבר אמרה התורה בפרשת לך לך כל פרטי דיני מילה. ואם להודיע שצריך למול ביום ולא בלילה, גם להודיע אפילו בשבת, כמו שדרשו ז''ל (תו''כ שבת קלב.) וביום אפילו בשבת, קשה למה לא רשם ה' פרטי דינים אלו שם בפרשת מילה שנכתבה בפרשת לך לך. ואולי כי לא קבע ה' פרט זה במצות אברהם, שלא יחשוב אדם כי לא הקל ה' שבת לגבי מילה אלא להאבות שלא קבלו התורה וחומרת שבת, אבל ישראל שנצטוו מה' (תשא לא יד) מחלליה מות יומת לא ידחה שבת, והגם שאמרו ז''ל (חולין ק) שהמצוה בסיני נאמרה אלא שנכתבה במקומה, אף על פי כן יש מקום לבעל דין לחלוק כי אין ללמוד להקל בשבת ולא הקל ה' בזה אלא להאבות שלא קבלו התורה, אשר על כן ציוה פרט זה לבנים שקבלו התורה:
@302 **עוד** נראה כי מן הסתם פשוט הוא כי מצות מילה שנאמרה בפרשת לך לך לאברהם אבינו עליו השלום הדברים הם כנתינתן מפי הגבורה לאברהם בלא תוספת דברים בהם אחר מתן תורה, ומעתה אין מקום שיצוה ה' לאברהם למול אפילו בשבת כי הוא מעצמו כן יעשה, הגם שמקיים כל התורה כולה אף על פי כן ידחה שבת מלפני מילה, כי מילה הוא מצוה שנצטוה בה ושבת היא מצוה שלא נצטוה בה כל עיקר ואם לא עשה כן הרי זה ח''ו לא טוב עשה, ואם כן אין מקום שיצווהו ה' למול אפילו בשבת, ואם הי' מצוה היו משתברים הקולמסים עליו למה הוצרך לצוות וכו', אשר על כן הוצרך הכתוב לצוות על הדבר את בני ישראל שישנם בשמירת שבת. כמו כן מה שדרשו שם בתורת כהנים ברבוי תיבת ימול בשר למול אפילו בהרת, מצוה זו לא נאמרה לאברהם מטעם הנזכר:
@302 **ונראה** לתת טעם לסמיכת וביום השמיני עם מה שלפניו, שבא לתת טעם לעכבת המילה עד יום השמיני ולא צוה למול ביומו כמו שמצינו במקנת כסף (שבת קלה) לזה כתב אחר אומרו וטמאה שבעה ימים **וביום השמיני** וגו' לומר כי לטעם זה הוא שעכב המילה והוא על דרך אומרם ז''ל (נדה לא:) כדי שלא יהיו כל העולם שמחים ואביו ואמו עצבים. ורז''ל אמרו (מד''ד תצא פ''ו) וזה לשונם למה התינוק נימול לח' שקנה ה' רחמים עליו עד שיהיה בו כח, וכשם שרחמיו על האדם כך רחמיו על הבהמה שנאמר (אמור כב' כז') ומיום השמיני והלאה ירצה עכ''ל. וצריך לדעת מי גילה סוד זה כי בח' ימים יהיה בו כח לא פחות ולא יותר. ונראה כי כח האמור בדבריהם הוא מה שאמר בזוהר (תזריע מד. אמור צא:) שהוא כדי שיעבור עליו שבת ותגיעהו נפש החיונית הנשפעת בעולם ביום השבת כידוע ואז יהיה בן קיימא, והוא שאמרו ז''ל כח החיוני, ותמצא שאמרו ז''ל (ב''ר פ''ו) שקודם שבא שבת היה העולם רופף ורועד כיון שבא שבת נתחזק ונח ע''כ. והוא מה שאמרו כדי שיהיה בו כח. עוד ירצה באומרו **וביום** בתוספת וא''ו להסמיך מילה למצות נדה שמלפניה, לומר כי זה תלוי בזה שאם ישמור מצות נדה יוסיף לזכות עשות מצות מילה:
@302 **עוד** יתבאר הכתוב על פי דבריהם ז''ל (תנחומא תזריע ה) וזה לשונם שאל טורנוסרופוס את ר' עקיבא איזה מעשים נאים של הקב''ה או של בשר ודם כו' למה אתם מלים כו' הביא לו שיבולים וגלוסקאות אמר לו אלו מעשה הקב''ה ואלו מעשה בשר ודם אין אלו נאים אמר לו הואיל והוא חפץ במילה למה אינו יוצא מהול אמר לו שלא נתן הקב''ה מצות לישראל אלא לצרף בהם דכתיב (תהלים יח) אמרת ה' צרופה וגו' ע''כ. הנה לא הספיק בתשובת תכונת השבולים כי צריכין תיקון אחר מעשה הקב''ה, לצד כי השבולים מה שחסר בהם מהתיקון הוא לצד אשר יאות לבני אדם הם ילכו ויתקנו הנאות להם, מה שאין כן המילה היא חפצי שמים אם כן יעשה ה' רצונו כרצונו, ולזה השיבו ר' עקיבא כי לצרף בהם ישראל נתכוין ה'. והנה תשובה זו סתומה וחתומה בערך מושכל, מושג לטורנוסרופוס, לפי שאין בבחינת נפשו גדר השגת שכליות פנימיות הידיעה האלהית קבל פשטן של דברים, אבל לנו בני אל חי יש לנו להשכיל בבוריין של דברים. גם בהשכיל בטבע הרגיל בעולם אשר יסד בורא הכל כי כל מוליד או מהוה דבר יהיה כתבנית המוליד למינהו, ואפילו בפרטי תכונת תואר פנים איקונין של זה דומה לאקונין של זה, ואיך אדם מהול יוליד בן ערל הלא חלק הערלה שבנולד אינו במוליד, ואין לומר שהטעם הוא לצד שתכונת המוליד מתחלתה היא בערלה, כי מה בכך כיון שנכרתה הערלה ואין רישומה ניכר, ועוד אם כן משה רבינו עליו השלום שנולד מהול (אבדר''נ פ''ב) למה ילד בן ערל דכתיב (שמות ד כה) ותקח צפורה צור ותכרות את ערלת בנה:
@302 **אכן** אשכילך בדבר האלהים, לפי מה שקדם לנו מדבריהם כי בחינת הערלה היא בחינת הרע, כי מעשה הערלה הוא יגיד על בחינת נעלמות, כי כל הגוף אינו אלא נרתק לנפש והנרתק יודיע את מה שבתוכו, ואמר ה' כי ישראל כשימולו הערלה הנה הם מושללים מבחינת הרעה שהערלה סימן לה, מה שאין כן אומות העולם שכל נפשם היא בחינת הרע שהיא הערלה, והוא מה שרמז באומרו (ירמיה ט) כי כל הגוים ערלים, ודבר ידוע כי בריאת אדם הראשון היתה בריאה תמה בבחינת הקדושה מושללת מכל רע, ולזה לא היתה בתכונתו בחינת הערלה, ובסיבת החטא משך בערלתו (סנהדרין לח:), ונולדה בו בחינת הערלה, וגם נמשך מזה שליטת הטומאה באשה והוא דם נידותה כי הוא זה סיבת היותו כמאמרם ז''ל (ערובין ק: כתובות י:) גם באמצעות חטא האדם נזרע זרע רע בכל ממשלתו ותוציא הארץ פריה בקליפות רבות, וזה לך האות כי אין אדם יכול ליהנות מהחטה עד עשות בה מלאכות רבות מלפניה ומלאחריה במספר עשרה הלא המה סדורים בפרק כלל גדול אמרו בשבת (דף עג:) עד האופה, כנגד עשרה קללות שנתקללה האדמה כאמור בדבריהם ז''ל בספר הזוהר הקדוש (פנחס רמג) ולזה כשיעביר ה' רוח הטומאה מן הארץ דכתיב (זכריה יג) ואת רוח וגו' מן הארץ לרמוז גם בחינת הארץ עצמה ואז תוציא הארץ גלוסקאות, פירוש אין צורך לאחד מעשרה מלאכות אלא הארץ מעצמה תוציא גלוסקאות לחם שאין צריך מכשירים, ולזה נתכוון ר' עקיבא בהוראת שיבולים וגלוסקאות כי היא הסיבה והוא הטעם ללידת הערל שבחינת הרע אשר דבקה בנפש אדם הראשון טומאתה מלאה ארץ ולזה הגם שהאדם בזמן שהוא מוליד הוא מהול אף על פי כן בחינת כוחות המהוות זרע אשר בו נוצר הולד מוציאותם הוא מתולדות הארץ כי יגדל האדם מגדוליה ומגדולי גדוליה ומהם יתכונן בו תכונת החושב והמעשה, ולצד שכל גדולין אלו מהארץ אשר צמחה יעידו למו שמלאים בחינת הרע בכמה הדרגות שבין הגלוסקאות לשבולים ואשר על כן הזרע שממנו יצירת הולד לא יצא מבחינת זו ולזה יצא הולד ערל בשר. ושאלת טורנוסרופס שניה אם ה' חפץ במילה למה אינו יוצא מהול, שאלתו הוא לצד שהוא חסר ידיעת רוחניות וחשב כי תכלית מעשה המילה הוא מה שנראה לעינים בגוף לא שיש דבר בפנימיות:
@302 **או** אפשר שהוגד לו וידע כי החיצוניות שבמוחש יגיד על אשר ישנו במושכל, וחשב כי ה' יסיר הכתמים והפגמים ויטהר הנפש עם הבשר. ולזה השיבו ר' עקיבא תשובה כללית, למה שהוא חושב בדעתו אם לא השיג לדעת אלא בחינת הגוף הודיע כי תכלית הדבר לצרף נפשם לא למה שנגלה לבד שאין הפרש בין היות האדם מהול או ערל. ואם כונתו לומר שגם בענין הרוחניות אם הקב''ה חפץ יסיר התיעוב אשר הערלה תגיד עליו, השיבו גם כן כי כל המצות שנתן ה' לישראל אינם אלא לצרף ולנקות את הסיגים אשר סבבו החטא קדמון, כי כל מצות לא תעשה להסיר תחלואי הנפש, וכל מצות עשה להאיר לבחינת הנפש, לצד שעל ידי חטא קדמון הוחשכו מאורי הנפש ועל ידי שמירת מצות לא תעשה יוסר הפגם ועדיין תחסר מאורי אורה ובעשות מצות עשה יאיר אורה כאומרו (משלי ו) נר מצוה, וענין זה אין ה' עושהו לצד כי האדם הוא הגורם הרע הוא חטא והוא ישא את עונו אשר הלביש את נפשו אז כשחטא אדם הראשון והיו כל הנפשות תלויות בו כולם טעמו טעם חטא ועליהם להריק תחלואיהם, ומה מקום לומר לה' הסר מעלי הבגדים הצואים שהלבשתי עצמי, ועיין מה שפרשתי בפרשת בראשית בפסוק (ד' ז') ואם לא תטיב וגו', ועוד אם באנו לומר כי ה' יסיר תיעוב המסובב מאדם לעצמו בסכלותו אם כן אין שכר ואין עונש. ומעתה טעם הערלה הוא לצד חטא קדמון שנדבק בנפש ותולדתו בעור הבשר, וצוה ה' לאיש ישראל לכרות מגופם בחינת הרע שבזה מתמרק בחינת הרע מהנפש וטהרה. ובזה יתבאר אומרו **וביום** פירוש לצד כי מצוה הקודמת וזאת הם ב' דברים שסיבתם אחת היא שהיא עון קדמון הוא סבב טומאת לידה וסבב ערלת הזכרים לזה צוה על שניהם כאחת על טומאת לידה ועל כריתת ערלה אשר על כן אמר **וביום השמיני** וגו'. ולצד שחטא האשה גדול מחטא האיש לזה האיש נפרדת הטומאה ממנו בהחלט מה שאין כן האשה טומאה קשורה עמה שחוזרת ונטמאת. ואולי כי טעם שצוה ה' ביום השמיני ולא קודם ולא אחר, שדן בו ה' דין אמו שצריכה מיום שפסקה למנות שבעה נקיים כמו כן עובר ירך אמו הוא ובצאתו מבטן אמו נטמא בפתיחת קבר, ולצד שהמילה היא גילוי שמו יתברך באדם וכמו שרמזתי בפרשת וירא אליו ה' לזה צוה ה' להמתין עד עבור עליו שבעה ימי נקיים וביום השמיני ימול וגו':
@302 **ימול בשר ערלתו**. יתבאר על פי מה שהקדמנו כי הערלה היא בחינת הקליפה, רמז הכתוב כאן כי צריך לעשות שלשה דברים במצות המילה, והם מילה, פריעה, מציצה, מילה הוא כריתת הערלה, והוא אומרו **ימול** פירוש יכרות. הפריעה הוא מה שפורע עור הדק לב' ואין צריך לכרות, והוא מה שרמז באומרו **בשר** פירוש יעשנה כבשר שאין בו חיות, ועור הפריעה אינו חוזר וחופה עוד העטרה. והמציצה הוא דם המזוהם של ב' בחינות אלו ערלה ופריעה, לצד היותם חלק אחד מגוף יש להם חלק בדם האדם והוא מעורב בכללות האדם וציוה ה' למצוץ דם זה לצד שהוא גם כן בחינת ערלה, והוא מה שרמז באומרו **ערלתו**, ואמרו בספר הזוהר הקדוש (השמטות ח''א רס''ב) כי ד' קליפות הם הסובבים לבחינת הקדושה בסוד גינת אגוז, ותמצא שבאגוז ד' קליפות, א' היא קליפה המרה המתיבשת ונופלת. ב' קליפה הקשה. ג' אותה המפרדת בין חלקי האוכל. ד' הדבוקה באוכל ונאכלת עם האוכל לצד שדבוקה בו, ובחינת קליפה זו אינה כל כך מאוסה אלא בהפרדה מהאוכל, ובמצות המילה מפרידים מהאדם ג' בחינות הקליפה, הערלה היא כנגד בחינה הרמוזה בקליפה החצונה של אגוז, פריעה כנגד קליפת אגוז המשתברת. מציצה היא כנגד קליפה שמפרדת בין חלקי האוכל וצריך לשולפה מבין האוכל, ועדיין נשארת בו בחינה הרמוזה בקליפה הדבוקה, והוא מה שאמרו ז''ל (זהר לב עח:) כי האדם עד תשלום י''ג שנה הוא בבחינת שני ערלה כי ה' הגביל לאילנות שלש שנים ערלים והאדם עץ השדה שלש עשרה ואור לי''ד יהיה כל פריו קודש הלולים:
@302 **עוד** יתבאר על פי מה שאמרו בספר התקונים (תיקון כד) כי שלשה מדריגות יש בבחינת מצוה זו של מילה, מדרגה המעולה שבכולן הוא מילת בניהם של צדיקים בני אל חי מילה זו הוא להם גילוי שמו יתברך חתום בבשר קודש והוא עטרת היסוד. שניה לה הם בני אנשים הבינונים מילה זו להם כקרבן לפני ה'. שלישית הוא מילת בני הממזרים האנשים הרשעים שנואי ה' מילה זו הוא להם כמי שנותן חלק לנחש עפר לחמו, ועיין תקונים דף י', והשלשה רמז הכתוב באומרו **ימול** וגו', כנגד מילת הצדיקים אהובי ה' אמר ימול פירוש יו''ד מול כי הוא מגלה בו רשימו קדישא אות י' הרשומה בשמו יתברך. וכנגד מילת הבינונים אמר **בשר** כאן רמז בחינת הקרבן אשר יקריב בשר קודש לה'. וכנגד מילת השנואים שבישראל אמר **ערלתו** כי הוא נותן לס''ם חלק הנוגע לו בילד שהוא בחינת הערלה. נמצאת אומר כי יצו ה' על המילה בין לבני הצדיקים בין לבני הבינונים בין לבני הרשעים, שלא יאמרו בית דין מה לי לממזר למולו וכלו מלא ערלה תלמוד לומר שאף על פי כן יסיר ערלתו ממנו להתיש כח הקליפה שבו שאם יזכה במעשיו יתעצם בכח מעשיו הטובים ויגבר צד הטוב ויתבטל חלק הרע, ועל זה אמרו ז''ל (הוריות יג.) ממזר תלמיד חכם קודם לכהן גדול עם הארץ:
@304 **ואם נקבה תלד**. טעם שהוצרך לומר **תלד** ולא סמך למה שזכר וילדה. אמרו בתורת כהנים וזה לשונם אין לי אלא נקבה מנין לרבות טומטום ואנדרוגינוס תלמוד לומר ואם נקבה תלד אין הדבר תלוי אלא בלידה ע''כ, ואין אני חולק על דבריהם ח''ו אלא כמוסיף, כי מאומרו ואם נקבה ולא אמר וכי תלד נקבה או ולנקבה וגו' נתכוון לומר אפילו אינה ודאי נקבה אלא ואם נקבה פירוש ספק, ואם כן נתרבו טומטום ואנדרוגינוס כי ספק הוא ולא היה צריך לומר תלד. ואולי כי אמר תלד לרבות אנדרוגינוס למאן דאמר (ביכורים פ''ד מ''ב) ברי' בפני עצמו שלא היה נשמע מתיבת ואם נקבה שהרי יש בו ודאי צד זכרות. ואולי כי תנא דתורת כהנים כן סובר שמרבה טומטום מתיבת ואם ואנדרוגינום מריבוי תלד, וסובר כמאן דאמר בריה בפני עצמה, ולזה אמר תלמוד לומר ואם נקבה תלד ולא הספיק לומר תלמוד לומר תלד. אלא שצריך ליישב הכתוב למאן דאמר אנדרוגינוס ספק למה הוצרך לומר תלד. ואולי שגם למאן דאמר ספק לא יספיק לימוד אחד לשניהם מטעם כי ספיקו של טומטום הוא ספק שאפשר שיתברר וימצא נקבה ולזה יש לחוש לו, מה שאין כן ספיקו של אנדרוגינוס שהוא עומד כמו כן לעולם, ולזה הוצרכו ב' רבויים. ולמה שאמרו בריש פרק בתרא דיומא (עד.) כי לא אתי קרא לספק משום דקמי שמיא גליא אם זכר אם נקבה. אם כן טומטום תתחייב לומר שאין טומאתו כנקבה אלא מדבריהם, ומעתה גם אנדרונגינוס אינו אלא מדבריהם ממה שהשוה אותם התנא יחד כשם שטומטום אינו אלא אסמכתא גם אנדרוגינוס אינו אלא מדבריהם ואסמכוה, ולחומרא נלכו בו ולא לקולא כמו שאמרו בפרק יש נוחלין (ב''ב קכז.) אהא דתנן המפלת טומטום ואנדרוגינום תשב לזכר ולנקבה ע''כ. פירוש ימי טוהר דזכר וימי טומאה דנקבה לחומרא שבשניהם יעויין שם דבריהם. וכפי זה אומרו ואם נקבה תלד שאנו מרבים הספיקות אינו אלא להסמוך לה שהוא וטמאה שבועיים אבל ימי טוהד אין לה אלא כימי זכר שאם ראתה מיום ארבעים ללידתה אין לה משפט דם טוהר:
@306 **והקריבו וגו' וכפר וגו'**. פירוש כנגד הקרבת כבש לעולה אמר והקריבו וכנגד בן יונה לחטאת אמר **וכפר עליה** זהו פשוטו. ובתורת כהנים דרשו שאין שנים מעכבין אלא אחד לזה אמר והקריבו. ואין אני יודע מי הוא מהשנים כשהוא אומר וכפר וגו' כפרה בחטאת ע''כ. ואולי שדקדקו ממה שלא אמר והקריבם ולא היה צריך לומר וכפר על החטאת. והגם שצריך לומר וכפר כסדר האמור בכל הקרבנות, הרי על כל פנים אינו מוסיף לא תיבה ולא אות אחת אם יאמר והקריבם וירשום הקרבת שניהם:
@309 **אדם כי יהיה בעור וגו'**. פירוש על דרך אומרם ז''ל (ב''מ קיד:) אתם קרויים אדם ואין או''ה קרוים אדם, שאין האומות מטמאין בנגעים, ומכאן הוכחה שאין גוים מטמאין בנגעים שאמרו במסכת נגעים בתחלת פרק י''א. ואומרו **כי יהיה בעור בשרו**, מודיע הכתוב שאין טומאת צרעת באיש הישראלי אלא בעור בשרו ולא בפנים, כי האומות בחינת נפשם עצמה היא בחינת הצרעת ומינם, ובנפש ישראל בפגעו בם לצד החטא אשר יחטא ירשום מראה צרעת בעור בשר, ודוקא בעורו ולא בבשרו ואין צריך לומר בפנימיותו, ורז''ל אמרו (ערכין ג.) כי טעם אומרו אדם לומר אפילו תינוק, גם כלל האשה שגם היא נקראת אדם דכתיב (בראשית ה ב) ויקרא את שמם אדם. עוד אמרו בתורת כהנים טעם אומרו בעור בשרו לרבות אפילו עור שאין בו צמחי שערות, פירוש שלא תאמר דוקא במקום שראוי לגדל צמחי שער אבל במקום שאין בו צמחי שער הגם שצמח בו שער והפך לבן אינו מטמא תלמוד לומר. ועל כל פנים צריך קדימת הבהרת לשער לבן, אבל אם קדם שער לבן לבהרת כגון זקן שהלבין שערו או גרמיני והוא מי שברייתו כך טהור. ואם קדמה בהרת לשער וכשגדל השער גדל לבן בבהרת יש להסתפק אם צריך שיקדים צמיחת השער לבהרת והבהרת תהפכנו ללבן, או כיון דסוף סוף לא היה שער לבן אלא אחר הבהרת הוי סימן טומאה. ונראה כי דבר זה אי אפשר לומר בו ודאי כשגדל השער גדל לבן, כי כיון שבאים לפנינו לבנים מי יאמר שלא נולדו שחורים והבהרת הפכתם ללבן כהרף עין, ואם כן זה נכלל גם כן במה ששנינו (נגעים פ''ד.) ספק אם כו', ועיין מה שאמרו התוספות בפרק ב' דנדה (י''ט ד''פ ר''ו) כי הבהרת חזקתה מהפכת השער ללבן, ולזה ספיקו טמא:
@309 **שאת או ספחת וגו'**. אמרו ז''ל (נגעים פ''א מ''א) כי פי' ספחת הוא מין הדומה לשאת כי שאת צמר נקי ודומה לו בהדרגה שניה לו כסיד ההיכל והנה הגם שלא נאמרה ספחת אלא גבי שאת, הוא הדין ספחתה של בהרת, וזה הוא שיעור הכתוב שאת או ספחתה או בהרת וספחתה. ויש לדעת למה הקדים הכתוב זכרון השאת קודם לבהרת אחר שהבהרת הוא לובן שאין למעלה ממנו כמאמרם ז''ל (שם) בהרת עזה כשלג שניה לה שהיא שאת כצמר נקי, אם כן היה לו להקדים מדרגה הגדולה ואחר כך מדרגות שלמטה ממנה. ונראה שאם היה אומר הכתוב בהרת או ספחת או שאת לצד שהבהרת עזה שלבנוניתה היא ביותר כשיאמר או ספחת לא נלמוד ממנה ספחת השאת, והייתי אומר שאין לנו אלא שלשה מיני נגעים והם בהרת שאת ספחת. גם אם היה אומר בהרת או שאת או ספחת לא הייתי יודע שיש מין נגע שלישי שהיא ספחת הבהרת כיון שבא זכרון הספחת באחרונה מה שאין כן לפי סדר האמור. ולמה שאמרו ז''ל (ערכין טו:) שהצרעת באה על לשון הרע ירמוז הכתוב בב' מראות נגעים על פי מה שכתב רמב''ם בפרק ז' מהלכות דעות וזה לשונו לשון הרע הוא המספר בגנות חברו אף על פי שאומר אמת אבל האומר שקר הוא נקרא מוציא שם רע על חברו עד כאן הנה האומר דברי גנאי על חברו הגם שאומר אמת נקרא בעל לשון הרע, והאומר שקר נקרא מוציא שם רע. וכנגד ב' אלו אמר שאת או בהרת, שאת כנגד מוציא שם רע, ואמר שאת ע''ד (שמות כג א) לא תשא שמע שוא, בהרת כנגד לשון הרע, ואמר לשון בהרת בהירות שיורה הצדקת הדברים הנאמרים כי כנים הם ואף על פי כן מאוסים הם ויסובבו הצרעת. ולצד שיש הדרגות בב' הבחינות, לזה עשה ה' ב''ה ספחת לשאת ולבהרת כבחינת הדבור אשר יסובב אותה:
@309 **והיה וגו' לנגע**. פירוש להיות שעיקר טומאת הנגע יגידו השערות ולא מראית השאת והבהרת מגדת צרעת זולת השער, לזה אמר והיה וגו' לנגע וגו' פירוש הבא אחר כך והוא כשיהפך שערו ללבן:
@310 **ומראה הנגע וגו'**. ענין זה יגיד סוד אומרו (תהלים לט) אך בצלם יתהלך איש, והוא מראה הבשר החי, וכשישלוט בחינת הרע באדם ירשום בבשר אדם הסתלקות זוהרת החיוני, ולזה יראה חסרון המראה ויהיה עמוק מהעור, ולזה דבר הכתוב בדרך זה עמוק מן העור, ולדברי רז''ל (תו''כ כאן שביעית ו) טעם אומרו עמוק לומר שאם היה כל בשרו כמראה הנגע טהור שאין ניכר עומק, והכתוב הקפיד על העומק:
@310 **וראהו הכהן וטמא אותו**. תלה הכתוב הטומאה בפה כהן, על דרך אומרם ז''ל (שבת קיט:) ב' מלאכים מלוים את האדם בליל שבת לביתו וכו' וגם מלאך טוב עונה בעל כרחו וכו', והנה לצד שהכהן הוא המכפר על ישראל מטומאתם ומתחלואיהם לזה יצו ה' שיסכים על טומאה זו שקנתה מקומה באיש ההוא, עד שובו לפני ה' ואז יבער ה' ממנו טומאתו:
@313 **והנה כהה**. פירוש רש''י הא אם עמד במראיתו, או פשה טמא. ורמב''ם בפרק א' מהלכות טומאת צרעת כתב זה שנאמר בתורה והנה כהה הנגע וגו' שאם כהה מד' מראות נגעים טהור, וכן אם לא כהה ולא פשה ולא נולד בו שער לבן וכו' טהור ע''כ. הנה לדברי רש''י הכיהוי הוא מהקודם, ולא ממראה הצרעת, שאז תתחייב לומר שאין כאן מראה צרעת, ואין הכתוב מדבר אלא במי שהיתה בו מין צרעת מג' מראות, כמו שתאמר בהרת ונעשית שניה לה או שאת ונעשית שניה לה וכדומה, אבל אם היתה קרום ביצה שוב אין לה הדרגה אחרת. או אפשר שגם בכל אחת מד' מראות יש במין עצמו כיהוי, כמו שתאמר הבהרת עצמה תוכל להיות בב' הדרגות א' קודם כיהוי וא' אחר כיהוי וכן כל א' מהד'. ותמצא שאמרו במסכת נגעים (פ''א מ''ד) ר' חנינה אומר מראות נגעים י''ו, רבי דוסא וכו' אומר ל''ו. עקביא בן מהללאל אומר ע''ב, ומן הסתם אין חולקין בטהרה וטומאה אלא במספר המינים, וכן פירש רמב''ם בפירוש המשנה, הא למדת שהרבה מינים הם, והנה ישתנה הדין בין ב' הדרכים, כיון שהכיהוי הוא המטהר, אם צריך כיהוי ממדרגה למדרגה, או אפילו במדרגה עצמה, ויש צדדים לכאן ולכאן, וראשון מוטה קצת, ולדרכו ז''ל פירוש כהה הנגע הוא אחר הכיהוי קוריהו הכתוב נגע שלא נעקר ממנו שם נגע הגם שכהה אלא שכהה מראה ראשון, ולדברי רמב''ם הכיהוי הוא ממראה הנגע שלא נשאר מראית הנגע, ופירוש כהה הנגע שאמר הכתוב של הקודם משמע שהוכהה מהיות נגע, ופשט הכתוב יע. ד כפירש''י, כי אם כהה הנגע ממראית ד' נגעים פשיטא שטהור שהרי אין כאן נגע, אבל אם נאמר כי פירוש כהה היא ממראית ראשון ועודנו במראית טמא כדברי רש''י יש חידוש לומר שאינו טהור אלא אם כהה. ויש ליישב לדעת רמב''ם שבא לומר שהגם שהוכהה מד' מראות נגעים ואין כאן רושם נגע אף על פי כן טעון כבוס בגדים, ויש לדעת לסברת רש''י למה לא התנה הכתוב באם חזר הנגע למראית הראשון כמו שהתנה באם פשה וגו', בשלמא לדעת רמב''ם בין לא פשה ופשה שאמר הכתוב בשלא כהה מדבר, אלא לרש''י נעלם דבר זה מה יהיה דינו:
@313 **ויש** לפנינו ב' דרכים, אחד הוא שניהם היו בתנאי הטהרה ויצא אחד מהם ולמד על עצמו שבחזרתו יטמא האיש לא ללמד על עצמו יצא אלא ללמד על הכל יצא שגם הכיהוי אם חזר הנגע למראית ראשון טמא הגם שלא פשה, ודרך ב' כי דווקא הפשיון אם חזר ופשה הוא שטמא כיון שפשיון זה לא היה לו כלל פירוש שלא פשה נגע זה ממה שנראה קודם הסגר עכשיו שישנו טמא, מה שאין כן חזרת הגוון למה שהיה קודם כיהוי יש לומר כיון שגוון זה היה בו בתחלה ולא הוחלט לטומאה גם עכשיו יראה כבתחלה. ולא תקשה הלא גם פשיון יש מציאות שיהיה קודם הסגר וטהור ואף על פי כן אמר הכתוב אם פשה אחר טהרה שהוא טמא ואין אנו אומרים יראה כבתחלה. לא קשה כי שאני פשיון שמחליט אחר הסגר ראשון תאמר בכיהוי שהגם שלא כהה בהסגר ראשון שאינו מוחלט דכתיב (פסוק ה) והנה הנגע עמד בעיניו ולא פשה וגו' והסגירו. ואולי שסובר רש''י שדרך ב' מוכרע הוא בסברא ולא הוצרך הכתוב לאומרו, וזה דוחק בדברי רש''י:
@313 **ולי** נראה לפרש הכתוב על זה הדרך **והנה כהה הנגע** פירוש שהוכהה ממראהו ראשון אלא שעדיין מראהו מראה נגע כדברי רש''י, אלא שכונת הכתוב הוא לומר שהגם שכהה אין לטהר אלא אם לא פשה, אבל אם פשה הגם שכהה אין לומר פנים חדשות באו לכאן ויראה בתחלה, אלא שקשה לי על מי סמך עליו הכתוב להכריע בו פירוש זה:
@313 **שוב** ראיתי דברי רז''ל בתורת כהנים וזה לשונם והנה כהה יכול למטה מד' מראות תלמוד לומר הנגע, אי הנגע יכול במראיו תלמוד לומר והנה כהה, הא כיצד כהה ממראיו לא למטה מד' מראות, והנה כהה שאם העז וכהה כאלו לא העז, הנגע שאם כהה והעז כאלו לא כהה עד כאן. והנה תנא דתורת כהנים מפרש כהה שלא נעקר ממנו מראית הנגע כדרכו של רש''י, אלא מאומרו כאלו לא העז וכאלו לא כהה יגיד כפירושנו שכוונת הכתוב הוא לומר שלא יראה בתחלה ואפילו כהה מתחלה והעז אחר כך כאלו מתחלה עז היה וטהור אם לא פשה. ומעתה מדברי ברייתא זו נסתרו דברי רש''י ורמב''ם, ועדיין גם לדרך המבורר נשאר קושיא על מי סמך עליו לפרש בדבריו כן, ודלמא תנאי היא אם כהה דוק' לטהר, ומצאתי בתורת כהנים באותה פרשה עצמה הלכה ט' וזה לשונם מספחת, אף על פי שלא נשתנו מראיה ע''כ, הרי שהגם שלא כהה השמיענו הכתוב שהוא טהור, אם כן נחזור לפרש טעם אומרו כהה לומר שלא יראה בתחלה אם כהה ואומרו הנגע שלא יראה בתחלה אם העז. וצריך עיון לדברי רש''י ורמב''ם ויש ליישב בדוחק גדול:
@313 **מספחת היא**. פירוש אינו צרעת, כדרך שאמר בוהק הוא, ואף על פי כן צוה ה' לכבס בגדיו שגם בחינה זו היא ענף מענפי הטומאה אלא שטומאתה קלה. ואולי שזה ירמוז לאבק לשון הרע, כרמוז בדבריהם ז''ל (ערכין טו:) שאפילו לומר נורא בבית פלוני הוא אבק לשון הרע:
@313 **עוד** ירצה באומרו **מספחת היא** לומר שהוא שם מין נגע שצריך שיכבם בגדיו בשבילו, והוא מה שסמך לאומרו מספחת היא **וכבס בגדיו**, גם בזה מצאנו נחת רוח במה שקדם לומר **וטהרו הכהן** שנראה שצריך שיאמר הכהן טהור אתה, וקשה בשלמא אומרו וטמאו הכהן ירצה לומר שאין טומאה יורדת עליו אלא עד שיאמר הכהן טמא, אבל טהרה הרי בחזקת טהור הוא האיש והנגע טהור הוא אם כן מה צורך לומר וטהרו הכהן שמשמע שאינו טהור עד שיאמר לו הכהן טהור, והגם שאמרו ז''ל (רש''י) לצד שנסגר, אין זה מספיק, ולדברינו ישנו לטעם הדבר, כי מין נגע זה שמזקיקו לכיבוס בגדים אינו נטהר ממנו אלא במאמר הכהן כשאומר לו טהור זו היא טהרתו ויכבם בגדיו על מה שקדם קודם שיאמר הכהן טהור והבן:
@315 **צרעת היא**. פירוש אפילו מה שכבר קרא עליו הכהן שם טהרה עתה למפרע נתגלה שהוא טמא, כי המספחת הטהורה אין דרכה לפשות כל עיקר והשמיענו הכתוב בהודעה זו לומר שאין צריך שיהיה הפשיון גדול כשיעור הנגע אלא כל שהוא, שהרי אנו דנים במספחת עצמה שהיא צרעת והבן:
@317 **והיא הפכה וגו' ומחית וגו'**. פשט הכתוב משמע שצריך ב' לטומאה מחיה ושער לבן ורז''ל אמרו בתורת כהנים וזה לשונם יכול עד שיהיה בה שער לבן ומחיה תלמוד לומר צרעת נושנת היא, היא טמאה ואינה צריכה דבר אחר, אם כן למה נאמר שער לבן ומחית, מלמד שלא תהיה טמאה עד שיהיה בה כדי לקבל שער לבן ומחיה ע''כ. הנה מה שדייקו לטמא במחיה לבד מאומרו נושנת היא קשה, תינח מחיה אינה צריכה דבד אחר לסעדה מה שאין כן שער לבן בשאת מנין שיספיק לבד. ואולי דאומרו היא חוזר לכל אחד מב' דברים על הפכיות שער ללבן ועל מחיה, לא כמו שכתב בעל קרבן אהרן שחוזר אל המחיה לבד. או אפשר שדיוק היא חוזר להפכיות שער לבן שבו יספיק בלא מחית. ומחית לבד נשמעת מאומרו בפסוק שבסוף הענין שאמר הבשר החי טמא הוא צרעת הוא משמע בלא תנאי אחר כל שיש בשר חי יגיד צרעת, וחוץ מדבריהם נראה לי כי טעם שלא אמר או מחית בשר, לומר שאפילו היו שניהם אם תכסה הצרעת את כל עור וגו' טהור, מה שלא נשמע אם היה אומר או, כי מנין לנו לטהר כשיהיו ב' סימני טומאה, ולא חש למטעי להצריך לטומאה שניהם מטעם הנזכר:
@326 **שאת לבנה או וגו'**. בתורת כהנים אמרו טעם אומרו לבנה, לומר שאינה אדמדמת, ובהרת לבנה אדמדמת, ומנין ליתן בשאת אדמדמת ובבהרת לבנה חלקה תלמוד לומר נגע צרעת פירוש בסוף הענין. ונראה שלא הוצרך התנא לריבוי של נגע צרעת אלא לפתוך של שאת, שלא תאמר כיון שלבנוניתה אינו עז אם יבא בו הפתוך יחשך הלבנונית תלמוד לומר, אבל לא לחלקה של בהרת, כי הגם שלא היה ריבוי של נגע צרעת לא הייתי מטהר בהרת חלק, שלא מצינו שיש טומאה בשאת יותר מבהרת. ופירוש הכתוב כן הוא שאת לבנה או בהרת לבנה הגם שהיא אדמדמת, כי גוון הבהרת יש בו שאת ולא יטהר לצד שגדל בו מראית הצרעת ולא הוצרך ריבוי של נגע צרעת אלא לפתוך השאת, והגם שאמר התנא ב' חלוקות, אגב אמרה. ודע כי לאו דוקא שאת אלא הוא הדין ספחתה של בהרת ושל שאת מטמאין בחלק ובפתוך. כן מוכח במסכת נגעים (פ''א מ''ב), וטעמו ממה שריבה נגע צרעת כל ד' מראות שוים הם בדין זה:
@336 **ואיש או אשה וגו'**. הוצרך לפרט כאן או אשה ולא אמר אדם ואשה בכלל, לצד שאין לאשה זקן יאמר האומר שלא דבר הכתוב אלא באיש שישנו בזקן, והגם שיאמר אדם ולא יאמר איש תאמר שבא לרבות הקטן או למעט גוים, ולעולם נגעי זקן באשה לא מטמאה תלמוד לומר או אשה לאם גדל שער בזקנה שהיא מטמא בנתקים:
@337 **שער צהוב**. בתורת כהנים צהוב, צהוב ולא ירוק וכו', אוציא את כל אלו ולא אוציא הלבן ודין הוא ומה צהוב שאינו סימן טומאה בנגעים סימן טומאה בנתקים שער לבן שהוא סימן טומאה וכו' תלמוד לומר צהוב ע''כ. וקשה דלמא לגופו אתא שיטמא בנתק הגם שאינו מטמא בשאר נגעים, ולעולם הלבן מטמא בקל וחומר הנזכר, ומה גם שלא עשה התנא קל וחומר ומה צהוב וכו' עד שלקח בידו שהצהוב מטמא בנתק, מעתה הגם שאמר הכתוב צהוב בנתק עשה קל וחומר ללבן אם כן במה סתרו באומרו תלמוד לומר:
@337 **ונראה** שדרשת התנא היא ממה שאמר הכתוב צהוב וטמא אותו ולא אמר וטמאו כמו שאמר בב' ובג' מקומות, ואמר אותו למעט הלבן על זה הדרך אותו פירוש הצהוב הוא מטמא וכאלו אמר התנא תלמוד לומר צהוב וטמא אותו, וכמו כן תמצא שדרש תנא בתורת כהנים כל אותו האמורים בפרשיות הקודמות ממה שלא אמר וטמאו, וטעם שלא בא תיבת אותו בדברי התנא, לצד שעדיין היה רוצה לדרוש תיבת דק שקדמה לה, ולא חש לטעות, כי אין דרך לפנות ימין ושמאל וסמך על המעיין, ותמצא שאחר כך דרש התנא מיעוט וטמא אותו נתק הוא ולא דרש בו אלא מיעוט הוא ולא מיעוט אותו, שהרי כבר דרשה כדרכנו:
@337 **ואם** תאמר אם כן נדון קל וחומר לטמא צהוב בשאר נגעים על זה הדרך, ומה לבן שאינו מטמא בנתק מטמא בשאר נגעים צהוב שמטמא בנתק מכל שכן שיטמא בשאר נגעים, ואולי כי ממה שהוצרך למעט לבן בנתק יגיד שחש שלא לדון בקל וחומר ומן הנמנע שנעשה קל וחומר עד שנצדיק לומר שאין הצהוב מטמא בשאר נגעים, ומעתה אין מקום לדון בהפך שהרי הכתוב העיד שאין צהוב מטמא בשאר נגעים ממה שהוצרך למעט לבן בנתק כנזכר והבן. ועיין בפרשת מצורע (י''ד ז') מה שפלפלנו מזה בברייתא דשבע פעמים האמור במצורע, ופירוש צהוב אמרו בתורת כהנים וזה לשונם צהוב וגו' ולמה הוא דומה לתבנית הזהב, ופירש רמב''ם (נגעים פ''ו מ''א) שהוא מראה המעורב מאדמימות וירקות ע''כ. וראיתי לראב''ע ז''ל שפירש וזה לשונו בלשון ישמעאל קרוב מעין הלובן עד כן נראה שיחשוב כי לזה נתכוון הכתוב ואנו מבני גלות ישמעאל ואותו גוון שקורין אותו בלשון ישמעאל כן הוא לבן דיהוי קצת, וכפי זה הוא בהיפך מפירוש התנאים, ובמחילה מכבודו אם באנו לחלוק על רז''ל ולפרש מלות התורה בלשון ישמעאל היינו עושים תורת שקר, וכי כעורה זו שפירשו רז''ל בלשון הזה''ב ובפירושים כאלו נתן הרב יד לחכמי הדורות לזלזל בכבודו, וכלן כמין פירוש זה ישתקעו הדברים ולא יאמרו:
@344 **טהור הוא וטהרו הכהן**. בתורת כהנים אמרו טהור, יכול יפטור וילך לו תלמוד לומר וטהרו, יכול אם אמר כהן על טמא טהור יהיה טהור תלמוד לומר טהור וטהרו, ועל דבר זה עלה הלל ע''ה (ידושלמי פסחים פ''ו ה''א) מבבל, משמע שלא היה יכול להכריחם מהפסוק עד שעלה לארץ ישראל וקבל שכן הוא ההלכה כמו שדרש הוא, וצריך לדעת במה היו החולקים עליו מיישבים הכתובים:
@344 **ונראה** כי טהור וטהרו צריכין לדון שלא יפטור וילך לו אלא עד שיאמר לו הכהן טהור אתה, שזולת טהור הייתי אומר כי לצד שאינו יודע יבא כהן ויודיענו כי הכהן הוא הבקי בהלכות אלו ותורה יבקשו מפיהו, ולעולם אם ידע הוא שהוא בוהק יפטור וילך תלמוד לומר טהור הוא וטהרו, ואין הכרח לדרשת הלל עד שעלה לארץ ישראל וידע שכן באה ההלכה, מעתה נחזור לקבוע ההלכה בכתוב על זה הדרך טהור הוא דוקא אם הוא כפי האמת טהור בזה הוא שיועילו דברי הכהן אבל אם אמר על טמא טהור לא יועיל, ולא תקשה דלמא נתכוון הכתוב באומרו טהור אפילו ידע הוא שהוא טהור, כי אין זו אלא דחיה ותצדק קודם בירור האמת שכך באה הלכה, אבל אחר שהדין שאנו קובעים ביתור הוא הלכה, יותר נבחר לומר לזה נתכוון מלדחות דחיות. וזה כלל נכון בפירוש התורה. וראיתי ליישב מאמרי רז''ל שאמרו (ויק''ר פכ''ב) שלא היה דבר שלא נמסר למשה בסיני, ואפילו מה שתלמיד ותיק עתיד לחדש, ואמרו במקום אחר (במד''ר פי''ט) כי רבי עקיבא היה דורש מה שלא ידע משה כאומרו הדברים עשיתים אעשה לא נאמר וכו' יעויין שם דבריהם, וכן כמה מאמרים שדומים לזה. ונראה כי ישוב המאמרים הוא. כי הן אמת שכל דבר תורה נאמר למשה ואין חכם יכול לדעת יותר ממה שידע משה, והגם שתצרף כל דורות ישראל מיום מתן תורה עד שתמלא הארץ דעה אין חידוש שלא ידעו משה, אבל ההפרש הוא כי משה נתן לו ה' תורה שבכתב ותורה שבעל פה, והנה האדון ב''ה בחכמתו יתברך רשם בתורה שבכתב כל תורה שבעל פה שאמר למשה, אבל לא הודיע למשה כל מה שנתן לו בעל פה היכן הוא רמוז בתורה שבכתב וזו היא עבודת בני ישראל עמלי תורה ללבש ההלכות שנאמרו למשה בסיני והסודות והדרשות כלן יתנו להם מקום בתורה שבכתב, ולזה תמצא באו התנאים וחברו תורת כהנים וספרי וכו' וכל דרושתם בכתובים אינם אלא על פי ההלכות והלבישם בתורת ה' תמימה שבכתב, ואחריהם ועד היום זו היא עבודת הקודש בני תורה לדייק המקראות וליישבם על פי המאמרים שהם תורה שבעל פה, וזו היא עבודת התורה הנקראת ארץ החיים, וענין זה לא נמסר למשה כולו לדעת כל תורה שבעל פה היכן היא כולה רמוזה בתורה שבכתב, ולזה אמרו ז''ל שדרש רבי עקיבא דרשות שלא ידעם משה, אין הכוונה שלא ידע משה עקרן של דברים הלא ממנו הכל אפילו מה שתלמיד ותיק עתיד לחדש, אלא שלא ידע סמיכתם ודיוקם היכן רמוזים בתורה, וזה לך האות מה שלפנינו שדרש הלל מהכתוב ההלכה שנאמרה למשה בעל פה ולא גילה ה' למשה עיקרה בכתוב ובא הלל ודרשה, ודברים אלו נכונים הם:
@351 **צרוע הוא טמא הוא**. נראה לפרש הפסוק כדרך שפירש הלל בפסוק טהור הוא שכתבנו בסמוך, וכאן הוא מוכרח ביותר כי אמר **צרוע הוא** לגופה ואף על פי כן צריך שיטמאהו הכהן, ואם לא טמאו הכהן אין לו טומאה, וכפל לומר **טמא הוא** למעט אם אמר על הטהור טמא כי דוקא זה שטמא הוא כפי האמת הוא שיטמאנו הכהן אבל אם היה טהור ואמר לו טמא אין זה טמא אלא טהור, וטעם שכפל **טמא יטמאנו**, דרשו בתורת כהנים לרבות כל הטומאות שצריכין מפי כהן:
@351 **צרוע הוא**. ולא אמר צרעת הוא. אולי כי לצד שה' זלזל בו כל כך שהפריח צרעת בקרחתו ובגבחתו זה יגיד כי טומאתו מרובה משאר נגעים הבאים בהצנע, כי ה' יחוש על כבוד הבריות, וזה מעשיו מוכיחות כי נמאם בעיני ה' ויסרו נגע כזה רחמנא ליצלן. ולזה גמר אומר **בראשו נגעו** לתת טעם לקריאתו כן איש צרוע וגו' כי בראשו נגע ו:
@353 **כל ימי**. פירוש כל זמן שנגעו בו שהוא עונו כמו כן ישאר בטומאת צרעתו והוא אומרו **יטמא** פירוש יעמוד בטומאתו ואומרו **טמא הוא** פירוש על דרך אומרו (ירמי' ב') תיסרך רעתך, שאין ה' ב''ה מטמאו אלא טמא הוא מעצמו לצד פעולתו ואין ה' עושה לו דבר, וכן הוא אומר (איכה ג') מה יתאונן אדם חי גבר על חטאיו ודרשו ז''ל (ילקוט תתר''מ) יעויין שם דבריהם. ועייין מה שכתבתי (בראשית ד ז) בפסוק הלא אם תטיב שאת:
@354 **והבגד וגו'**. אומרו וא''ו החיבור דרש רבי יוסי הגלילי (בתו''כ) וזה לשונו מחוץ למחנה מושבו והבגד למד על הבגדים שהם טעונים שלוח חוץ לשלשה מחנות, ואמרו עוד שם אין לי אלא צמר ופשתים המיוחדים מנין לרבות הכלאים תלמוד לומר והבגד וגו'. וקשה דלמא לא בא רבוי וא''ו והבגד אלא או להסמיכו לדין שלוח חוץ לשלשה מחנות או לרבות כלאים. ואולי כי דרשת רבי יוסי הגלילי היא מוא''ו, ודרשת ריבוי כלאים מה''א של והבגד ממה שלא אמר ובגד:
@354 **בבגד צמר או בבגד וגו'**. צריך לדעת למה אמר או ולא הספיק לומר בבגד צמר ובבגד פשתים ומה גם לדברי הרב בעל קרבן אהרן שפירש שטעם שהוצרך לרבות כלאים לצד שאמר הכתוב או שחלקם כל אחד לבדו תגדל הקושיא שלא היה צריך לכתוב לא או ולא ריבוי והבגד, ועוד תגדל הקושיא שאמרו שם בתורת כהנים יכול יהיו מטמאין בין צבועים בין שאינם צבועים תלמוד לומר בבגד צמר או בבגד פשתים מה פשתים כברייתו אף צמר כברייתו ע''כ, קשה הלא הכתוב אדרבה הכחיש זה ממה שאמר או חלקם לומר שאין ללמוד צמר מפשתים:
@354 **ונראה** כי צריך הכתוב לומר או שלא יטעה אדם לומר שלא יטמא בנגעים אלא בגד של שניהם על זה הדרך בגד צמר ובגד פשתים עמו תלמוד לומר או, אם כן תיבת או צריכה לעצמה ואינה מעכבת סמיכות צמר לפשתים, וזה הוא שיעור הכתוב בבגד צמר ולאו דוקא צמר אלא הוא הדין אם יהיה בגד פשתים שניהם שוים בדין, ולזה דרשו מה פשתים כברייתו, פירוש שאין דרך בני אדם לצבוע בגדי פשתים אף צמר וכו', ומה שהוצרך לרבות כלאים מוהבגד לא לצד הטעות שיבא מתיבת או כמו שחשב בעל קרבן אהרן אלא לצד שלא אמר הכתוב אלא צמר ופשתים כלאים מנין לנו לומר, ואם היינו אומרים שהוצרך לצד שאמר או כדברי בעל קרבן אהרן אם כן תיבת או תבא בה הסברא שפסקה בין הצמר ובין הפשתים לכל דבר שלצד זה הוצרך הכתוב לרבות ובזה הוצרך הכתוב כי או פסקה מעתה אין מקום לומר מה פשתים כברייתו והלא או אפסקיה והבן:
@357 **וראה הכהן וגו' והסגיר**. צריך לדעת מאי טעמא שינה הכתוב משפט צרעת הבגד ממשפט צרעת אדם שצרעת אדם ישנה בלא הסגר כשהיא צרעת וצרעת הבגד הגם שהיא צרעת כמו שאמר הכתוב נגע צרעת היא אף על פי כן לא צוה שיטמאנו הכהן אלא יסגירנו, ונמצא כפי זה מחשיב הכתוב בגדי אדם מאדם עצמו, ונראה כי הבגדים לצד שהחלטו הוא כליונו אם בפעם ראשונה יוחלט אם כן אין תרופה לבעל תשובה לשוב על חטא שצרעת זה בא בעבורו, וכבר קדם לנו כי לא יחפוץ ה' בהפסד וכליון ממון אדם, צא ולמד מה שדרשו ז''ל (תו''כ נגעים פי''ב מ''ה) בפסוק וצוה הכהן ופינו את הבית שהקב''ה חס אפילו על ממון הבזוי של הרשעים, אשר על כן אין לך נגע בבגדים שיוחלט בפעם אחד, מה שאין כן האדם שישנו בתשובה ותיקון גם אחר החלטו שהרי אינו נאבד בהחלטו אלא נבדל ובשובו יוסר ממנו הנגע וטהר לזה ישנה לצרעת חלוטה בפעם ראשונה, וישרים דרכי ה':
@357 **חסלת פרשת תזריע**
@368 **זאת תהיה תורת**. כל הכתוב מיותר, שלא היה לו לומר אלא כי יטהר המצורע והובא אל הכהן וגו'. ובתורת כהנים דרשו תיבת זאת למעט טהרת המצורע בבמה, שלא יהיה אלא בבית עולמים, ותיבת תהיה לרבות שיטהרו מצורעים בזמן הזה, וכמעשה רבי טרפון (ירושלמי פ''ב ה''ב. תו''כ פסוק ד) שהראה מקל שטהר בו מצורעים בזמן הזה, ותיבת תורת לומר שהגם שחלק בטומאת מצורע שיש מוחלט בראית כהן פעם ראשונה ויש בהסגר שבוע וכדומה אף על פי כן תורת מצורע אחת היא ותיבת ביום לומר שאין טהרת מצורע אלא ביום ולא בלילה, ואמרו יכול אף לקיחת צפרים וכו' תלמוד לומר זאת עד כאן. הנה תיבת זאת דרש ממנה למעט טהרת מצורע בבמה ודרש ממנה למעט לקיחת צפרים ביום, הטעם, לצד שקדמה לזכרון הטהרה וזכרון ביום מיעט בשניהם, שאם לא היתה כונת ה' למעט אלא באחת מהנה היה לו להסמיך המיעוט לאחד על זה הדרך תורת המצורע זאת תהיה ביום, ואז יהיה המיעוט על ביום ולא על תורת המצורע אם צריכה בבית עולמים. או יאמר על זה הדרך ביום טהרת המצורע זאת תהיה תורתו, ואז היה המיעוט על הקרבנות ולא על ביום, ואין בסדר זה תוספת אפילו אות אחת. ובדרש דרשו (ויק''ר פט''ז ב') מיתור הכתוב זאת תהיה תורתו של מוציא שם רע וצריך לדעת למה רמז הדבר במקום זה בזמן טהרה. ונראה כי לצד שבא הכתוב לומר הבאת צפרים לזה הקדים לתת טעם כי לצד שחטאו הוא בשביל לשון הרע לזה תהיה תורתו זאת להביא צפרים המצפצפים דוגמתו:
@368 **עוד** נראה לפרש על זה הדרך להיות שהצרעת כפי הטבע תכונתו תתהוה מעפשות וזיהום הגוף ותגבורת המרה אשר תתגבר באדם ועושה רושם בבשרו, ודבר זה יסובבנו העצבון וצרת הלב ושממון השכל, והרפואה הטבעית לזה היא הרחקות העצבון ועניינים המרחיבים לבו של אדם ומשמחים אותו, והנה בבוא נגע צרעת על האדם יכול אדם לומר כי חולי טבעי הוא אשר יקרה להאדם, ובאמור לו כי הוא זה בשביל לשון הרע לא יאמין ולא יצדיק הדברים, לזה נתחכם אל עליון וצוה שיסגר המצורע בדד ישב ובגדיו יהיו פרומים וראשו יהיה פרוע ועל שפם יעטה, ודברים אלו הם כפי הטבע נגדיים לרפואת סיבת הנגע ואדרבה יולידו הנגע מחדש, וכאשר יראה האדם שהגם שעשה דברים אלו שהם נגדיים אף על פי כן על ידי שהרהר תשובה והתודה חטאתו כי בעונו אשר פשט לשונו גילה הנגע את עינו וישוב מחטאתו ויטהר לשונו ויראה כי הפך הנגע את עינו בזה ידע ויוכיח הוכחה ברורה שלא בא לו הנגע אלא לצד שדבר לשון הרע, והוא אומרו **זאת תהיה תורת** מוציא שם רע, והכרת הדבר והוכחתו **ביום טהרתו**, שהגם שעשה דברים נגדיים לחוליו כנזכר אף על פי כן נטהר, בזה ידע כי תורת לשונו הרע הוא זה ולא מקרה הטבעי כחושבי מחשבות און וישמור פיו ולשונו, והוא מה שגמר אומר **נרפא נגע הצרעת מן הצרוע** פירוש מן הצרוע באה רפואתו ששב ורפא לו:
@368 **והובא וגו'**. הוצרך לומר **והובא** וגו', לצד שאמר ביום טהרתו חש שיחשוב אדם שהכתוב קראו טהור במה שהוסר נגעו ואין תנאי בדבר לזה אמר והובא וגו' פירוש חדא ועוד, טהרתו והובא אל וגו'. ורז''ל אמרו (תו''כ) שלא ישהה. וטעם אומרו **והובא** ולא אמר ובא. אולי שיחייבוהו בית דין או תוקפו כהן לבא, וכמו כן מה שאמר הכתוב נגע צרעת וגו' והובא אל הכהן יכוין לומר שיחייבוהו לבא אם נתעצל:
@370 **וצוה הכהן ולקח וגו'**. רז''ל בתורת כהנים אמרו צוי בכהן ולקיחה בכל אדם. ודרשו בפסוק שאחר זה וצוה הכהן ושחט ציווי בכהן ושחיטה בכל אדם דברי רבי יהודה בר רבי יוסי רבי אומר אף שחיטה בכהן ע''כ. קשה למה לא נחלקו רבי יהודה ורבי אלא בפסוק שני ולא בראשון. ואם לצד כי וצוה ולקח אין דבר להלביש בציווי לבד הלקיחה, גם וצוה ושחט אין ידוע מה יש בציווי לבד השחיטה, ואדרבה בציווי ולקח יש לנו לומר שיכוין לומר וצוה שיביאו לפניו הצפרים ויקחם הוא מיד המביאים וב' מצות צריכין להיות בכהן מה שאין כן וצוה ושחט אם נאמר שהכהן הוא שישחוט במה נלביש הציווי:
@370 **וראיתי** לבעל קרבן אהרן שכתב שהמצוה היא שיצו להביא לפניו הב' צפרים לבחור מהם אחת המיוחדת והמבוררת. וטעם שלא חלק רבי בפסוק ראשון הוא לצד שלא מצא במה ילביש המצוה ע''כ. ואין דבריו נראים כי מצוה זו של הברירה שצריך שתהיה ביד כהן אינה נשמעת מאומרו וצוה, ואדרבה יש לנו לומר שכוונת הכתוב הוא לומר שיצוה לברור האחת וירצה לומר הכתוב שמצות הבירור על ידי כהן והבירור על ידי הזולת והשחיטה בכהן, ועל כל פנים יכול הוא רבי לפרש בפסוק ראשון כדרך שפירש בפסוק ב'. והי' נראה לפרש שטעם שחלק רבי וסבר שהשחיטה גם כן בכהן לא לצד משמעות הכתוב אלא לצד מה שהוא הענין. כי צוה ה' שתהיה השחיטה אל כלי חרס על מים חיים, ושחיטה זו אינה בחינת שחיטה לבד שהרי יש עמה מעשה אחר שישחוט אל כלי וגו', וזה עיקר הכנת הטהרה, ולזה אמר שצריך על ידי כהן, מה שאין כן בפסוק ראשון שאין בלקיחת הצפרים מעשה טהרה, והתורה מסרה הדבר לחכמים להבחין בדברים:
@370 **עוד** נראה לומר כי על כל פנים פשט הכתוב כשאמר וצוה הכהן ולקח וגו' כוונתו באומרו ולקח הוא על הכהן, כי אין צריך הכתוב להזכיר הכהן על כל דבר ודבר, מה תאמר שיאמר וצוה ולקח הכהן, אז היינו אומרים בעיון נכון שאין הציווי בכהן לפי שאיחר זכרונו לבסוף, מה שאין כן אומרו וצוה הכהן שהזכיר הכהן בתחלה כל מה שיבא מהמעשה אחר כך יכוון למוזכר קודם. ומעתה כשאמר הכתוב הראשון וצוה הכהן ולקח פשט הכתוב הוא שהכהן יצוה והוא יקח, אלא ממה שאמר הכתוב אחר כך וצוה הכהן ושחט הרי זה מראה באצבע כי מה שאמר הכתוב ולקח אינו חוזר אל הכהן, שאם בכהן מדבר הכתוב עד עתה למה הוצרך לומר וצוה הכהן פעם ב' הלא בכהן מדבר עד עתה ולא היה לו לומר אלא וצוה ושחט ואני יודע שבכהן מדבר, אלא ודאי שאפסקיה אחר, ואיזה הוא, ולקח הקודם לה שמדבר בכל אדם, לזה לכולי עלמא בין רבי יהודה בין רבי סוברים בפסוק ראשון וצוה הכהן ולקח כל האדם, מה שאין כן פסוק ב' שאין לנו הכרח סובר רבי כי מקרא עומד כפשוטו וצוה הכהן ושחט גם כן הכהן הסמוך לו. ורבי יהודה סובר יגיד עליו ריעו אחר שנתגלה לנו מפסוק ראשון שאין חוזרת תיבת ולקח אל הכהן הסמוך כמו כן פסוק ב' יתפרש בקוטב ראשון:
@370 **אלא** שראיתי שדרשו שם בתורת כהנים בתחילת הפרשה וזה לשונם תורת המצורע בכהן וכו', אין לי אלא טהרתו וטומאתו בכהן מנין שחיטת צפרים והזאות וכו' ותגלחתו תלמוד לומר תורת המצורע בכהן, יכול אף לקיחת צפרים ושילוח ספרים וכיבום וכו' בכהן תלמוד לומר זאת ע''כ. הנה מפשט הברייתא משמע כי אין צורך שיהיה בכהן אלא שלשה פרטים הרשומים דוקא ואם כן אין צריך שיצוה הכהן לא על הלקיחה ולא על השחיטה ומב' הברייתות משמע להדיא דלכולי עלמא בין לרבי יהודה בין לרבי צריך שיצוה הכהן ב' דברים. ואולי כי לא הזכיר התנא ב' הציוויים בברייתא עם הג' דברים לצד שבדרשת תורת המצורע אינם נכללים אלא דברים שהם בגוף הטהרה, שהרי מיעט הרבה מעשים מאומרו זאת, וזולת אומרו וצוה הכהן היו הציוויים גם כן מתמעטים, לזה לא הזכיר אלא פרטים הנדרשים מאומרו תורת המצורע אבל הציוויים אין זה מקומן ויחד להם הכתוב הדבר במקומו ואמר וצוה הכהן וגו', וסמך התנא על מה שעתיד לפרש בפרשת וצוה הכהן ציווי בכהן:
@370 **אלא** שראיתי לרמב''ם (הל' טו''צ פי''א ה''ה) כתב שאין צריך בכהן אלא שחיטת צפרים והזאה ותגלחת ולא הזכיר כלל ענין ציווים שיהיה בכהן, ואדרבה כלל דבר שוה ואמר ושאר הדברים בין בכהן ובין בישראל, והגם שבתוספתא בפרק ח' דנגעים תניא כדברי רמב''ם שאין צריך שיהיה בכהן אלא ג' דברים ושאר הדברים בכל אדם ושם לא הזכיר ענין ציווי בכהן. מן הסתם לא נעמיד התוספתא דלא כמאן ונאמר גם כן שהתנא ביאר הדברים במקום אחר, וגם שמבואר הוא בתורה שהציווי הוא בכהן ולא הוצרך לאומרו מה שאין כן רמב''ם שצריך הוא לבאר הדבר, ואינו כל כך הדבר מבואר בתורה שנדחוק לומר שגם רמב''ם לא הוצרך לכותבו, שהרי רואים אנו שהתנאים הוצרכו לדרוש הדבר מהכתוב. ואין לומר דסובר רמב''ם שפשט התוספתא שאמרה ושאר הדברים בכל אדם משמע אפילו הציווים ודלא כרבי יהודה ורבי. אם נאמר כן תקשה עוד, כי דבר פשוט הוא כי אין לחוש לתוספתא כזו שאינה לא כרבי יהודה ולא כרבי שהובאו דבריהם בספרא דבי רב המזוקק. ואפשר לומר שסובר רמב''ם מכח ברייתא ראשונה דתורת כהנים שהזכיר דברים הצריכין כהן בדרשת פסוק תורת המצורע שכל אותם הדברים הם תורה לעיכובא, ודרשת וצוה הכהן היא על זה הדרך שהכהן הוא יצוה לעשות הדברים והוא דרך כבוד שיהיו הדברים נעשים על פיו ובמאמרו על דרך ועל פיך ישק כל עמי (מקץ מא מ), והוא אומרו הציווי בכהן לגזור על הדבר ואחרים יעשו, ומשמעות הדברים מגידים כן שאין זה לעיכוב אלא לכבוד לכהן. ועוד קל וחומר הדברים ומה שילוח הצפרים וכו' אמר הכתוב שאינו מעכב מכל שכן מצות לקיחה ומצות שחיטה. ורבי שאמר גם השחיטה בכהן לא מכח פסוק וצוה הכהן ושחט אלא מכח דרשת תורת המצורע שגם השחיטה היא דומה להזאה ותגלחת, והוא תנא ראשון שכלל השחיטה עם התגלחת והזאה:
@373 **והזה על המטהר מן הצרעת וגו'**. צריך לדעת למה הוצרך לומר **מן הצרעת** אחר שבו מדבר הכתוב. ואולי כי לצד שהזאה זו אינה מטהרת אותו בהחלט אלא כיום שפסקה זבה מדם זובה ועדיין צריך הוא לספירת ז' ימים כדין טומאת זב, ותמצא שכל ימי ספרו עדיין הוא אב הטומאה, לזה אמר **המטהר מן הצרעת** פירוש מגוף הצרעת ולא מן טומאת הצרעת, ולזה אמר לבסוף והיה ביום השביעי וגו' וכבם את בגדיו הא למדת שבימי ספרו היה מטמא בגדים והנה הוא אב הטומאה, ולזה הודיעך כי אינו נטהר אלא מגופו של צרעת ואחר שנטהר מהצרעת צריך לישב בטומאתו ז' ימים:
@373 **ובתורת** כהנים דרשו למה הוצרך לומר מן הצרעת כיון שבו מדבר הכתוב, ואמרו כי הוצרך לומר מן הצרעת למעט טמא מת שלא יטעון ז' פעמים, משום שהייתי דן קל וחומר ממצורע שאינו טעון ג' וז' ואף על פי כן טעון ז' פעמים, טמא מת שטעון ג' וז' אינו דין שיהיה טעון ז' פעמים, תלמוד לומר מן הצרעת ולא מטומאת מת. ודרשו עוד בסוף אותה ברייתא וטהרו מה שהוצרך לומר וטהרו כי בא למעט המצורע מטעינת ג' וז', שזולת זה הייתי דן קל וחומר מטמא מת שאינו טעון ז' ואף על כן טעון ג' וז', מצורע שטעון ז' אינו דין שיהיה טעון ג' וז', תלמוד לומר וטהרו פירוש בזה יספיק לטהרו ע''כ. וקשיא לי אחר שאמר הכתוב מן הצרעת ודרשנו למעט מן טומאת מת, הנה לא יוצדק למעט אלא לצד שהיה בא מן הדין, ודין זה אינו אלא כשנאמר שהמצורע אין בו ג' וז' שבזה יבא קל וחומר ומה מצורע וכו' כאמור בדברי הברייתא, אם כן מאומרו מן הצרעת החזיק הכתוב דעת זו וחתם עליה כי המצורע אין בו ג' וז', ומעתה למה הוצרך לומר וטהרו למעטו מג' וז' הרי כבר נתחייבה מהכתוב לומר שאין בו ג' וז' מאומרו מן הצרעת. או היה לו לומר וטהרו שאין צריך המצורע ג' וז' ולא היה צריך לומר מן הצרעת, ואני יודע כי טמא מת אין צריך ז' פעמים ממה שהוצרך לומר וטהרו לסתור הקל וחומר הבא מטמא מת להזאת ג' וז', ואין קל וחומר בא אלא אם תאמר שאין בא במלמד אלא אחד והבן:
@373 **ונראה** לפרש כי להיות שראינו שה' צוה בטומאת מת הזאת ג' וז' ולא הזכיר כמה הזאות והזכיר בטומאת צרעת ז' פעמים ולא הזכיר ג' וז', יש סברא לומר כי טהרת ריבוי ההזאות היא טהרה גדולה יותר מהזאת ג' וז' לצד היותם ז' פעמים מה שאין כן הזאות ג' וז' שאינם אלא ב' פעמים, וכפי זה הצריך הכתוב תיקון לטהרת מצורע יותר מתיקון טהרת טומאת מת, ויש סברא לומר טהרת מספר הימים היא יותר גדולה שלא יום אחד בלבד יספיק לטהר, ואם כן מה שמצינו שה' הצריך בטמא מת ג' וז' היא הדרגה גדולה מהזאת ז' פעמים, וב' סברות אלו יתחלקו בדעות חכמים, ויהיה חכם שיחשוב גדול הנאמר בטהרת המצורע יותר מהנאמר בטהרת טמא מת, ויהיה חכם שיחשוב להפך. והנה להחושב כי טהרת ג' וז' יותר יבוא לדון קל וחומר מהמצורע להצריך בטמא מת ז' פעמים. ולהחושב כי טהרת ז' פעמים חמורה ילמד למצורע ג' וז' מטמא מת מקל וחומר. ומעתה יתחייב הכתוב לומר ב' המיעוטים להסיר טעות כל סברא וסברא. ואם לא היה אומר אלא אחד כגון שיאמר מן הצרעת למעט טמא מת שאינו צריך ז' פעמים, תבא סברת הסובר לומר כי בזה הסיר הכתוב טעות שכנגדו והצדיק לומר כי הזאת ז' פעמים היא יותר גדולה וישנה במצורע ולא בטמא מת וחוזר אני ודן להביא לו ג' וז' מטמא מת, וכן אם היה אומר וטהרו וגו'. וכדי שלא ירחיק דעתך דרך זה לומר איך יבא הכתוב למעט סברא שאינה אמיתית, הלא תמצא שאמרו (ברכות מז) בכמה מקומות עליך אמר קרא פירוש הגם שאין דעתו כך, הרי שהתנא יבאר הכתוב שבא לסברא שאין דעתו מסכמת לה שיחוש הכתוב לסובר כן והבן:
@373 **וראיתי** להרב המופלא הר''י רוזאניש זצוק''ל בספר הנכבד משנה למלך (הל' חמץ ומצה פ''ו ה''א) שהביא ברייתא אחת דומה למה שלפנינו, דתניא בתורת כהנים פרק י''א וזה לשונם הזה חג המצות יום זה טעון מצה ואין חג הסוכות טעון מצה, שהיה בדין, ומה אם זה שאינו טעון סוכה טעון מצה זה שטעון סוכה אינו דין שיטעון מצה, תלמוד לומר הזה חג המצות טעון מצה וכו', ושם בפרק י''ד תניא וזה לשונם הזה חג הסוכות זה טעון סוכה ואין חג המצות טעון סוכה, שהיה בדין, ומה זה שאינו טעון מצה טעון סוכה חג המצות שהוא טעון מצה אינו דין שיטעון סוכה, תלמוד לומר הזה זה טעון סוכה ואין וכו'. והקשה הרב הקושיות עצמם שכתבנו בברייתות טהרת מצורע דרשו מעל ספר הרב מה שתרץ בזה. ודבריו ז''ל קצת דחוקים, ובפרט לכת הפוסקים (רמב''ם ועוד) שסוברים דספק דאורייתא שמותר מן התורה לא יעמדו דברי הרב עליו השלום למעיין בדבריו. ולדעתי יתבארו הברייתות בדרך עצמו שבארנו למעלה, והוא כי לצד שיש פרסום נס יציאת מצרים בסוכה בבחינה אחת יותר מפרסום נם שיש באכילת מצה, כי הרבה פעמים אדם אוכל פתו מצה מה שאין כן מעשה סוכה שיש פרסום גדול. ובפסח גם כן בחינה אחרת יש בו שהוא יותר פרסום הנס בעתו ובזמנו שהוא בט''ו בניסן, ויבא חכם שתהיה לו הסברא להגדיל פרסום נם סוכה שהוא גדול מפרסום אכילת מצה, וידון קל וחומר לסוכה שטעונה מצה, ויאמר ומה חג המצות שלא הצריך בו ה' כל כך פרסום על כל פנים חייבו במצה לצד שהוא דבר הצריך על כל פנים, סוכה שראינו שהוא פרסום גדול אינו דין שצריך מצה, תלמוד לומר הזה חג המצות, ותבא סברא אחרת שתדון בהפך ויאמר כי דידיה נצח ודחה סברא שכנגדו ממה שמיעט סוכה שאין בה מצה ועיקר הפרסום הוא המצה וידון לחייב סוכה בפסח בקל וחומר מסוכה שלא הצריך בה ה' מצה ואף על פי כן הצריך סוכה, תלמוד לומר [הזה] חג הסוכות ותדע שהתנא דורש המיעוטין לב' הסברות, בהעיר בקל וחומר ראשון שעשה התנא, איך הוציא מפיו קל וחומר ועדיין אינו יודע אם אינו טעון אלא אחד או שנים, ובמה שפירשתי יבוא על נכון. ומה שכתב הרב הגדול בעל משנה למלך שלא היינו יודעים באיזה מקום נאמר הקל וחומר ומספיקא היינו אומרים שחג המצות טעון סוכה וחג הסוכות טעון מצה ע''כ. אין דבריו ז''ל מוכרחים, כי כיון שאין אתה יכול לדון קל וחומר לצד שאינך יכול לומר ומה זה שאינו טעון אלא זה כי מי אמר לך שאינו טעון אלא זה ודלמא תדון הקל וחומר להפך ויהיה טעון ב', וכן לצד האחר אין אני יכול לעשות הקל וחומר מהטעם עצמו, ומעתה יעמוד כל אחד בשלו ולא תדון קל וחומר, אם לא שתאמר שיש פן לומר קל וחומר מצד אחד ויש פן לומר הקל וחומר מצד אחר וחש הכתוב לב' הצדדין, והוא הדרך שפירשתי:
@374 **וכבס המטהר וגו'**. צריך לדעת כיבוס זה למה כיון שעודנו מטמא בגדים בימי ספרו, וגם למה שפירשתי (פסוק ז') כי טומאה זו שמכבס בגדיו עלי' היא הפסקת הצרעת כמו שדייקתי מאומרו מן הצרעת, אף על פי כן לא יכבס בגדיו ועודנו מטמא אותם. ובתורת כהנים מצאתי שאמרו וזה לשונם וכבס מה בא ללמד אם ללמד שמטמא בגדים במגע קל וחומר מבימי ספרו וכו', אלא אחד מלטמא משכב ומושב ואחד מלטמא במגע ע''כ. וכפי זה אמר **וכבס** וגו' לומר שפסקה טומאת משכב ומושב. והנה עיקר הכרח דרשת תורת כהנים אינה אלא מכח קושיתנו, ולא הוצרכו לפרשה לצד פשיטותה, כי זולת קושיתנו אין הכרח אומרו מה בא ללמד הכרח, כי מי אמר לנו שבא ללמד דלמא בא לעצמו שצריך לכבס בגדיו יום שנטהר מהצרעת ויום גמר ספירת ז' ימים כמו שמצינו שצוה ה' לגלח כל שערו ולרחוץ כל בשרו ביום שנטהר וסוף ימי הספירה כמו כן צוה ה' על הכיבוס. אלא ודאי עיקר קושיתו היא שלא יכבם אם עדיין מטמא בגדים, ולזה בהכרח אתה אומר שלא בא אלא ללמד דבר ולזה אמר מה בא ללמד אם ללמד וכו' קל וחומר הוא ותירץ וכו':
@374 **וראיתי** לרבינו הלל שכתב למחוק גרסת לטמא משכב ומושב מכח ההוא שאמרו באלו דברים (פסחים סז:) דזב חמור ממצורע שמטמא משכב ומושב, וגורם לטמא בביאה. ולדבריו צריך למחוק כמה ברייתות גם כן הבאים שם בתורת כהנים דקתני שהמצורע מטמא משכב ומושב. וכבר דחה דבריו הרב בעל קרבן אהרן בדחיה שאין אחריה סמיכה. ומה שאמרו באלו דברים שהזב חמור ממצורע, כן הוא כפי האמת שבימי ספרו של זב מטמא משכב ומושב וימי ספרו של מצורע אינו מטמא משכב ומושב, והוא הדבר שלמדנו מאומרו וכבם המטהר ב' פעמים וכן פסקו רמב''ם וכל הפוסקים, ורבינו הלל לא כוון בזה אל הנכון:
@374 **ורחץ במים וגו'**. בתורת כהנים אמרו וזה לשונם במים אפילו במי מקוה, והלא דין הוא זב שאינו טוען הזיית מים חיים טעון ביאת מים חיים מצורע שטעון וכו'. תלמוד לומר ורחץ במים אפילו וכו' ע''כ. פשט דבריהם הוא שדורשים יתור תיבת במים שלא היה צריך לומר אלא ורחץ, וכן פירש בעל קרבן אהרן. וקשה והלא כבר מיעט הכתוב ביאת מים חיים במצורע בפרשת זב, כדתניא שם (טו יג) בתורת כהנים ורחץ בשרו במים חיים הזב טעון מים חיים ואין המצורע טעון מים חיים, והלא דין הוא ומה אם הזב וכו' תלמוד לומר בשרו במים חיים הזב טעון וכו' ואין המצורע טעון וכו' ע''כ, משמע כי מיתור תיבת בשרו דורש כן, וכן פירש הרב בעל קרבן אהרן, אם כן למה הוצרך לומר במים. ואפשר לומר כי עיקר דרשת התנא הוא מיתור תיבת במים ממנה דורש לרבות מי מקוה, ותיבת בשרו אצטריך למעט בגדיו, כמו שדרש שם גם כן בתורת כהנים, ומה שסמך גם כן לה מיעוט מים חיים במצורע, באגב, וסמך על יתור תיבת במים, ובזה לא קשיא למה דורש מתיבת בשרו, ב' דרשות. ובעל קרבן אהרן פירש כי דורש ממה שלא אמר ורחץ הזב ואמר בשרו, ולדברינו אין אנו צריכין לזה. ומה שדרשו בתורת כהנים בפרשת צו בפסוק (ו כא) ומורק ושוטף במים האמור בכלי שנתבשלה בו חטאת וזה לשונם ושוטף יכול במ' סאה תלמוד לומר במים כל שהן, במים ולא ביין ולא במזוג ע''כ. אין לדמות יתור במים האמור בחטאת ליתור במים האמור כאן, כי שם אם לא אמר במים לא הייתי מצריכו אלא מ' סאה מי מקוה שאין לנו צד לומר שצריך מים חיים לומר שבא הכתוב למעטו ומוכרח לומר שבא למעט גופן של מ' סאה, מה שאין כן במים האמור כאן כיון שיש צד לומר שצריכין מים חיים ובא יתור במים שדינן ליה למעט מים חיים, והבא לומר שממעט מ' סאה עליו להביא ראיה מנין. ומה שהוסיף שם לדרוש במים ולא ביין וכו', אין זה אלא מהמשמעות ולא מהיתור, ועיין פסוק שאחר זה ישוב הענין באופן אחר:
@375 **ורחץ** את בשרו במים. צריך לדעת למה אמר בשרו, לפי מה שמצינו שדרשו ז''ל במה שכתוב בזב (טו יג) ורחץ בשרו למה אמר בשרו ודרשו למעט מצורע ולמעט בגדיו, ב' דרשות הללו לא יוצדקו ביתור בשרו האמור כאן. גם למה אמר במים יתירה וכאן לא יוצדק מה שדרשו בפסוק ראשון, משום כי בטהרה ראשונה היה לנו לטעות להצריכו מים חיים ממה שיש בהזאתו מים חיים ובטהרה ב' אין לנו מקום לדון בה מים חיים. ואם באת לומר שכל טהרת המצורע ענין אחד הוא, אם כן הרי כבר מיעט מים חיים אפילו בטהרה שיש בה להדיא מים חיים. ויש לומר משום שהיה מקום לבעל הדין לחלק ולומר לא מיעט הכתוב ביאת מים חיים מהמצורע אלא לטהרה ראשונה שאין עולה בה מטומאתו כזב שנטהר לחלוטין מטומאתו אבל טהרה שנייה שעולה בה מטומאתו לחלוטין כטהרת זב עדיין אני דן במקומו שלא יגרע מהזב וצריך ביאת מים חיים, והגם שבטהרה זו אין בה הזאת מים חיים שהוא כח הקל וחומר, אף על פי כן טהרת המצורע ענין אחד הוא כולה תלמוד לומר **במים** פעם ב' לומר שאפילו בטהרה המעלהו מכל טומאה אין צריך ביאת מים חייב כזב, ודקדק לומר **בשרו** שעליו בא המשפט בזב שצריך ביאת מים חיים, וזולת זכרון בשרו כאן הייתי אומר שלא מיעט מים חיים אלא לכליו אבל בשרו עודנו נידון בקל וחומר מהזב, והגם שכליו אינם באים בקל וחומר מהזב שיצרך הכתוב למעטם וכשנבא לדון קל וחומר מהזב נאמר דיו לבא מן הדין להיות כנדון מה הנדון גופו ולא כליו וכו', אף על פי כן עדיין יש מקום לחוש להבא לסבור ולומר כיון שמצינו שהצריך בהזאתו מים חיים, גם כליו צריכין מים חיים תלמוד לומר **ורחץ בשרו במים במים**, יתירה לומר שעולה במי מקוה אפילו בשרו:
@375 **ואם** תאמר יאמר הכתוב ורחץ בשרו במים ולא יצרך לומר במים בפסוק אחר. משום שהייתי אומר לא מיעט הכתוב ביאת מים חיים אלא בטהרה ב' שאין בה משפט הזאת מים חיים מה שאין כן טבילה ראשונה שמצינו שהצריך הי' הזאת מים חיים עדיין אני דן קל וחומר מזב תלמוד לומר במים. ואין להקשות על זה כי אין אנו יכולין לומר שלא בא המיעוט אלא בטהרה ב' משום שאין בה הזאת מים חיים שהרי אין אתה מצריך המיעוט למעט בה מים חיים אלא משום קל וחומר והקל וחומר אינו חל אלא אם תאמר כל טהרת המצורע אחת היא ומשפט מים חיים שאמר הכתוב במצורע בטהרה א' יסובב לדון קל וחומר אפילו על טהרה ב' ואם כן כשבא המיעוט בטהרה ב' כאלו בא גם בטהרה א' ולא הי' צריך זו אינה קושיא, שהייתי אומר כי ממה שלא מיעט הכתוב אלא בטהרה ב' ולא בטהרה א' בזה עקר לי סברא שהייתי אומר שכל טהרת המצורע אחת היא והייתי מצריך במצורע ביאת מים חיים בב' טבילות תלמוד לומר בשרו במים בטבילה ב' למעט ביאת מים חיים והניח הקל וחומר מיוחד לטבילה ראשונה דוקא, תלמוד לומר במים בטבילה ראשונה שאפילו טבילה ראשונה שיש בה הזאת מים חיים אין צריכה ביאת מים חיים. אלא עדיין יש לנו לומר שבטבילה ב' הוא שממעט בשרו אבל טבילה ראשונה לא מיעט להדיא בשרו וכמו שפירשתי אם לא היה אומר בשרו בפסוק ב', וידים מוכיחות על הדבר ממה שדקדק הכתוב לומר בשרו בטהרה ב' ולא בטהרה ראשונה הרי זה מראה באצבע כי בטהרה א' צריך ביאת מים חיים לבשרו. ומעתה באנו למה שהוצרכו לדרוש מבשרו שאמר הכתוב בזב שבא למעט בשרו של מצורע והקשינו למה הוצרך והלא כבר נתמעט מתיבת במים, מעתה אין קושיא כי צריך מיעוט זה גם כן למעט גם טבילת גופו, ומה שקבע התנא המיעוט של גופו מתיבת במים, עיקר דרשתו הוא מבשרו האמורה בזה וקבע התנא עיקר הדין במקומו והבן:
@375 **ובדרך** רמז תרמוז הפ' על גלות ישראל ע''ד או' בס' הזוהר כי או''ה לישראל הם בחינת הצרעת וישלטו בהם לצד הטעם עצמו שיסובב הצרעת ותמצא ג''כ שאמרו ז''ל שלא נגאלו ישראל ממצרים אלא לצד שלא היה בהם בעלי לשון הרע דכתיב ושאלה אשה וגו' ודבר זה היה בידם י''ב חודש וכו' גם אין לך דבר שמרחיק האדם מן קונו כלשון הרע ולזה אמרה התורה **זאת תהיה תורת המצורע** שהוא עם בני ישראל שנצטרע בנגעי בני אדם הטמאים **ביום טהרתו** שיטהר לשונו ודרכיו **והובא אל הכהן** כי ה' ב''ה יתכנה בשם כהן כאמור בספר הזהר בפסוק והובא אל הכהן ואמר והובא לצד שנתרחק עכשיו יתקרב ובא אל הכהן ותכף ומיד כי מי גדול וגו' אלהם קרובים אליו ואמר והובא פי' מעצמו יתקרב כי מעשיו יקרבוהו ויקרא קרוב דכתיב שלום וגו' ולקרוב ואז ויצא ה' ונלחם וגו' והוא אומרו **ויצא הכהן אל מחוץ**.
@375 **למחנה** שהיא חוץ למחנה שכינתו לחוצה לארץ מקום טמא ששם בעונותינו הם גולים בנ''י **וראה והנה נרפא הנגע** שבעדו בא הצרעת שחזרו בתשובה ונטהרו וצוה הכהן ולקח למטהר **שתי צפרים חיות טהורות** הם ב' משיחים ונקרא צפור כי כן יתכנו נשמות העליונות כידוע ועוד מצינו שיתכנה הגואל לצפור וזה לך ל' הזוהר בפ' בלק ומההו מערת' יסגא חד עופא רברב' עלא' דישלוט בעלמא וליה יתיהיב מלכות' וכו' ע''כ ומצינו שאמרו ז''ל ששני משיחי ישראל הם משיח בן אפרים ומשיח בן דוד ובתחילה יתגלה משיח בן אפרים וימות ואח''כ יתגלה משיח בן דוד וכנגד ב' אלו אמר ולקח למטהר ב' צפרים חיות טהורות כל אלו הכינויים הם מעלות הקדושה כידוע ליודעי דעת ואומרו **ועץ ארז ושני תולעת ואז** וב רמז לזכות ג' אבות עץ ארז הוא אברהם שהוא האדם הגדול בענקים ושני תולעת יעקב ע''ד אומרו אל תיראי תולעת יעקב ואזוב הוא יצחק שהוא בחינת הגבורה שצריך צירוף זכות שלשתן ואמר **ושחט** כאן רמז להריגת משיח בן אפרים כמאמרו ית' **אל כלי חרס על מים חיים** פי' בשביל כפרת העם פדיון נפשם וכינה אותם כלי חרס ע''ד וייצר ה' את האדם עפר מן האדמה שהוא כלי חרס והכונה בזה לצד שנשארו ככלי חרם שעומד לשבירה לצד גרעון התורה המתיחסת למים חיים על סבת מים חיים שאין בישראל תורה ועל זה תשחט הצפור האחת גם באמצעות דבר זה ילבוש ה' בגדי נקם הפך מדותיו הרחמים ויעשה כלה לגוים המריעים וממוצא דבר אתה יודע שאסורה ועל זה תשחט הצפור האחת גם באמצעות דבר זה ילבוש ה' בגדי נגם הפך מדותיו הרחמים ויעשה כלה לגוים המריעים וממוצא דבר אתה יודע שאם יהיה בהם תורה לא ימות הצדיק ותמצא שכתב האר''י ז''ל שצריך לכוין בתפל' הקבוע להתפלל על זה הצדיק שלא ימות פי' כי באמצעות התפלה יתרבה זכותו ויעמוד חי ותבוטל גזירת מות ממנו ואמר **את הצפור החי'** שהוא משיח בן דוד יקח אותה הקב''ה ויצרף עמו זכו' האבות ויצרף נקמת הצדיק שנהרג והוא אומרו יקח אותה ואת עץ וגו' וטבל אותם בדם הצפור השחוטה ויתגברו הרחמים מזכות האבות וממשיח הנהרג ויתכפרו כל הדרגות הטומאות ומניעות דביקו' ישראל והוא מה שרמז הכתוב כאן באומרו **והזה על המטהר** פי' ענין כפר' כי למען זכות האבות ולמען אשכול הנהרג הוא כופר ויכפר על בנ''י ואמר שבעה כנגד שבע' הדרג' הטומא' אשר יטמאו בהם בית ישראל כי הם שבעה כידוע והן הנה הרמוזים בטומאת מת וטומאת נדה דכתיב כטומא' הנדה וגו' ובזה וטהרו ואז **ושלח את הצפור החיה** כאו' בספר הזוהר בפ' בלק וז''ל ומההיא מערתא יסגא חד עופא רברבא עלאה דישלוט בכל עלמא וליה יתיהב מלכותא וכו', והוא אומרו **על פני השדה** שהוא עולם הזה שתהיה שולטת בכל העולם, ואז **וכבס המטהר** שהם ישראל **את בגדיו** הם בגדים הצואים שהיו מלובשים בנשמתו כדרך אומרו (זכרי' ג) הסירו הבגדים הצואים, **וגילח את כל שערו** שהם בחינת צמחי החומר העכור, ורחץ במים הוא התורה בה יטהר מחשבותיו, ואחר יבא אל המחנה זה מחנה שכינה ירושלים היורדת בנויה מלמעלה, ואמר **וישב מחוץ לאהלו** כי לא יקרבו להזדווג לשכינה עד שישבו שבעה נקיים לחשש טומאה, וביום השביעי יהיו ראויים לקבלת הארת הקדושה, כיוצא בזה תמצא שאמר ביחזקאל שבעת ימים יכפרו את המזבח וטהרו אותו נמצאת אומר ב' טהרות טהרה הראשונה הרחקת הטומאה והב' היא הקרבת הקדושה:
@377 **והעמיד הכהן**. יתבאר על דרך מה שאמרו בתחילת מסכת כלים (פ''א מ''ח) שמחוסר כיפורים אסור ליכנס לעזרת ישראל ע''כ. והנה כאן צוה ה' שהמטהר יעמוד בפתח העזרה שהוא שער ניקנור כאומרם בפרק קמא דסוטה (ז) דכתיב לפני ה', ואמר הכתוב שעל הכהן שמירתו להעמידו שלא יפרוץ לצד שהוא בפתח העזרה ומכנים ידו לפנים לסמוך על קרבנו כאומרם בתורת כהנים ומכניס ראשו ליתן על תנוך וגו' יש לחוש שמא ימשך ויכנס לפנים לזה הטיל הכתוב הדבר על הכהן להעמידו:
@377 **הכהן המטהר**. הוצרך לומר **הכהן המטהר** ולא הספיק באחד מהם, אם היה אומר הכהן ולא היה אומר המטהר לא הייתי יודע שהמצוה בכהן המטהר שטהרו מן הצרעת לזה אמר **המטהר** כי מצותו בכהן המטהר מן הצרעת, ואם היה אומר המטהר ולא אמר הכהן לצד שיש בטהרת המצורע דברים הנעשים על ידי ישראל תבא הסברא לומר שגם הזר יקרא המטהר שהרי עושה גם כן טהרותיו תלמוד לומר הכהן:
@377 **האיש המטהר וגו'**. הוצרך לומר **האיש המטהר** ולא הספיק לומר האיש לבד, לצד שלא תטעה לומר שבא למעט הקטן שאינו בכלל דינים אלו הגם שישנו בטומאת צרעת לזה אמר המטהר, ולא הספיק לומר המטהר ולא יאמר האיש, משום לצד שיש במשפט זה גם הקטנים כנזכר תבא הסברא לומר שלא צוה ה' לכהן להעמיד המצורע לפני ה' שהוא חוץ לעזרת ישראל אלא מי שהוא קטן שמן הסתם אינו יודע שאין ליכנס לעזרת ישראל קודם הקרבת טהרתו אבל גדול נאמר אין חובה על הכהן להעמידו לצד שיודע הוא תלמוד לומר והעמיד האיש הגם שהוא איש על הכהן המצוה להעמידו חוץ לעזרה. ובתורת כהנים דרשו טעם אומרו האיש מלה יתירה למעט חטאת ועולה מתנופה, ואחר כך אמר הכתוב מיעוט אחר דכתיב אותו לאשם למעט גם את האיש שאינו טעון תנופה אלא אשם ולוג השמן לבד. ואם תאמר אם האיש הוא ממועט מתנופה מאומרו אותו לאשם והניף ולא האיש איך יבא למעט אחרים בדבר שאין בו. זה אינו קושיא כי יבא המיעוט בהם באם אינו ענין. ולזה תמצא שדקדק התנא בברייתא (בתו''כ כאן) וזה לשונם תלמוד לומר האיש לא חטאת ולא עולה ולא אמר זכרון התנופה, נתכוין בזה לומר שתיבת האיש באה למעט חטאת ועולה מדין אחד, והגם שאין הדבר שנתמעט ממנו באיש, הדבר מסור לחכמים לידע מהו. ובזה תשכיל משמעות ברייתא זו בתורת כהנים שהיא קשה ההבנה. ודברי בעל קרבן אהרן דחוקים בעיני:
@387 **ואם דל הוא ואין ידו משגת**. צריך לדעת למה כפל. ואולי שנתכוין על דרך מה שאמרו בפרק בתרא דכריתות (כז:) וזה לשון המשנה הפריש לכשבה או לשעירה העני יביא עוף וכו' ע''כ. ובגמרא (שם) למדו הדבר ממה שאמר הכתוב בקרבן עולה ויורד מחטאתו אשר חטא משמע ממקצת הדבר שהפריש לחטאתו ע''כ. והנה דרשה זו ישנה בעולה ויורד שישנו בדלי דלות כי שם הזכיר הכתוב מחטאתו שממנה דרשו, אבל מצורע יש לבעל הדין לחלוק ולומר כשם שלא מצינו בו שיוכל להביא קרבן דלי דלות והחמיר בו הכתוב גם נחמיר בו אם הפריש כבש וכשבה לחטאתו ועולתו והוצרך להם שלא יביא מקצת הדבר שהפריש לחטאתו להביא במקומן שתי תורים או שני בני יונה, תלמוד לומר **ואיז ידו משגת** שהגם שלא היה דל והפריש מעושר אם אין ידו משגת יכול הוא להוציא המעות המופרשים לחולין ויביא כפרת השגת יד. ותמצא שלא חלקו רז''ל בין עולה ויורד של מצורע לעולה ויורד של טומאת מקדש וכו' ושבועת ביטוי וכו':
@387 **או** ירצה על דרך מה שאמרו בסוף כריתות באותה שהבאתי בסמוך וזה לשונם הפריש לעשירית האיפה והעשיר יביא עוף העשיר יביא כשבה ע''כ, ואמרו שם שדרשו כן מדכתיב על חטאתו, וכאן רמז הדבר באומרו **דל הוא ואין ידו** וגו' פירוש ועודנו אין ידו משגת, אבל אם השיגה ידו הגם שהפריש בהיותו דל יביא קרבן עשיר, וב' דרכים אלו יסבלו יחד במשמעות הכתוב על זה הדרך ועודנו אין ידו משגת בין לחומרא בין לקולא כנזכר. ובתורת כהנים אמרו וזה לשונם דל הוא שומע אני דל ממה שהיה בן מאה מנה ונעשה בן נ' תלמוד לומר ואין ידו וגו', או ואין ידו וגו' יש לו ואין מוצא ליקח תלמוד לומר דל ע''כ. וצריך לדעת כוונת ואין מוצא, אם אין מוצא כל עיקר כמו שהיו בימים שהיתה ירושלים במצור, ודאי שמביא קרבן עני והרי הוא כחסרי ממון כי מה לי אין לו ממון או יש לו ואינו שוה כלום בערך הקרבן כיון שאינו משיגו בממון, אלא ודאי שכוונת התנא היא שאינה מצוי בקנין הרגיל וצריך הוא להפליג קנייתה בממון רב:
@387 **ונראה** שלא יתחייב אלא אם בשיעור שלא יהיה הוא חסר למה שצריך לעצמו, שהרי אפילו ירד אנו אומרים שיביא קרבן עני ויחיה מהנשאר. ופירוש זה של דברי רז''ל אינו סותר דברינו, ואלו ואלו דברי אלהים חיים. ותדע שאם לא היתה כוונת התורה בכפל הדבר אלא לומר דברי רז''ל היה לו לכתוב ואם לא תגיע ידו די שה וכשבה והביא וגו' כמו שאמר בקרבן טומאת מקדש והשבועות, אלא נתכוון גם כן למה שפירשנו:
@387 **ומה** שדרשו עוד בתורת כהנים בפרשה זו (לקמן ל' ל''א) בג' מקראות המיותרים בהשגת יד, והם **אשר תשיג ידו**, **מאשר תשיג ידו**, **את אשר תשיג ידו**, ודרשום על זה הדרך אשר תשיג בא להיה עשיר קודם ובעת הבאת הקרבן העני שיביא גם כן קרבן עני, **ומאשר תשיג ידו** בא למי שהיה עשיר והתחיל גם כן להביא אשמו והוא עדיין עשיר והעני שיביא גם כן קרבן עני. **ואת אשר תשיג ידו** בא להתחיל להביא קרבנו שהוא האשם בזמן שהיה עני והעשיר שצריך להביא בעושר, אבל אם הביא חטאת בעוני לא יביא עולה בעושר אם העשיר ולמדו שם דבר זה ממה שאמר הכתוב **אחד לחטאת ואחד לעולה** שצריך שיהיו שניהם מין אחד, מכל אלו הדרשות אין ללמוד מה שדרשנו מכפל אומרו דל ואין ידו וגו', שאפילו אחר כל דרשות שדרשו עדיין צריכין אנו לב' הדרשות שדרשנו שאחר שהפריש קרבן עשיר יביא קרבן עני ואחר שהפריש קרבן עני יביא קרבן עשיר כי לא באו ב' דברים אלו בדרשות הנזכרות:
@398 **זאת תורת וגו' אשר לא וגו'**. כל הכתוב מיותר, ורז''ל דרשו (בתו''כ) זאת תורת שריבה הבאת קרבן עשיר לעני אם ירצה. ואם תאמר למה צריך קרא והלא הסברא נותנת כן שלא בא הכתוכ אלא להקל מעליו ואם ירצה תבא עליו ברכת טוב ונראה כי לצד שרצה הכתוב למעט עשיר אם הביא קרבן עני שלא יצא וכמו שדרשוה מאומרו זאת מיעוט, חש הכתוב לומר שהקפיד על הכל במה שמיעט ואמר זאת עני בעניו ועשיר בעושרו תלמוד לומר **תורת**. ועדיין אין ידוע למה אמר הכתוב **אשר לא תשיג ידו** וגו'. ואולי שחש הכתוב שיבא החכם וילמוד משפט השג יד האמור במצורע מדין השג יד האמור בטומאת מקדש וקדשיו ושבועת האלה וכו' שישנם גם כן בקרבן דלי דלות ובמקום ב' תורים אחד עולה ואחד חטאת מביאים עשירית האיפה וילמד האמור במצורע שגם הוא אם לא השיגה ידו לעופות יביא עשירית האיפה תלמוד לומר זאת תורת אשר וגו' אשר לא תשיג ידו בטהרתו פירוש הגם שלא השיגה ידו בטהרתו הרשומה שהם בני יונה וכו' אף על פי כן יתפלש בעפר וימות ויביא ב' תורים או ב' בני יונה דוקא ובדרך רמז אפשר שרמז הכתוב למה שאמרו בזוהר הקדוש (תיקונים כב) כי העניות נקראת צרעת, ולזה שניהם נקראים מתים (נדרים סד), והוא מה שרמז באומרו **אשר בו נגע צרעת** פירוש עודנו הנגע בו, ומה הוא הנגע פירש ואמר **אשר לא תשיג ידו בטהרתו** פירוש שלא מצאה ידו לצד עניו להביא קרבן הצריך לטהרתו מצרעתו עד שהוצרך להביא עופות:
@400 **כי תבואו וגו' ונתתי וגו'**. וכי בשורה היא זו, ולא היה לו לומר אלא כי יהיה נגע בקירות בית אחוזתכם וגו' כדרך שהזכיר בנגעי בני אדם. ורז''ל הרגישו מזה ואמרו (ויק''ר פי''ז) כי לפי ששמעו הכנענים שישראל באים לארצם והטמינו כל וכו' ע''כ, וזה דרך דרש. ועל פי מה שאמרו במדרש (שם) וזה לשונם אמר ר' לוי אין בעל הרחמים נוגע בנפשות תחלה וכו' בתחלה הנגעים באים על ביתו וכו' ע''כ יתבאר על נכון. והוא לצד שהקדים לומר נגעי בני אדם, והוא הפך האמור בבעל הרחמים, לזה אמר מה שהקדמתי נגעי בני אדם הוא לצד שעדיין לא באתם אל הארץ ואין בתים לנגוע בהם, אבל כי תבואו אל הארץ אז לא אתן הנגע באדם תחלה אלא ונתתי נגע בבית ארץ וגו' תחלה. וטעם שלא סדר הכתוב נגע הבית קודם, לצד שנגעי אדם ישנם תיכף ומיד מהדיבור ואילך נוהגים ונגעי הבית הוא כי יבואו, לזה הקדים הצריך תיכף ומיד. ואם תאמר אם כן היה לו להקדים נגעי בגדים לנגעי אדם ששניהם ישנם מיד ולהם ראוי להקדים כסדר מדת בעל הרחמים:
@400 **ונראה** כי בחר ה' לסדר נגעי בגדים בין נגעי אדם ונגעי בתים לצד שיש בהם דברים שהם שוים בהם לנגעי אדם ויש דברים ששוים לנגעי בתים, כי בשיעור הצרעת שוים לדין נגעי אדם בגריס ולא כצרעת הבתים שהוא בב' גריסין. ובגוונים שוים לנגעי בתים ירקרק או אדמדם ולא בגוון לבן כנגע אדם:
@400 **עוד** נראה בהעיר למה סדר הכתוב דיני נגעי הבגד קודם שהשלים כל דיני נגעי בני אדם טומאתו וטהרתו, שהיה לו להמתין עד שיגמור כל משפט צרעת אדם ואחר כך יסדר משפט הבגדים, ואין לומר שנתכוין הכתוב לסדר דיני הטומאה בפני עצמן ודיני טהרתם בפני עצמם, שאם כן למה לא שפט כן גם בצרעת הבית שהיה לו גם כן להקדים טומאת נגע הבית קודם משפט טהרת נגעי אדם ובגדיו. אלא ודאי שהראה הכתוב בזה שהקדים נגע הבגד קודם לנגע אדם וקודם אומרו זאת תהיה תורת המצורע שבו רמז סימן עון הצרעת כי פיו ענה בו כמו שפירשנו בתחלת הפרשה כתב נגעי בגדים וכוונתו הוא לומר שהבגדים לוקים תחלה, ומה שהתחיל בדין הבאת הנגע באדם ולא התחיל בבגדים, בזה נתחכם הכתוב לחזק הדברים שנגעי הבגדים גם כן באים בחטא האדם כמו נגעי אדם, ולזה התחיל בנגעי אדם וסמוך להם אמר נגעי בגדים ואמר אחר שניהם זאת תהיה תורת המצורע תורתו של מוציא שם רע הראת לדעת כי גם על נגעי בגדים חוזרים הדברים מה שלא היה מובן כן אם היה מסדר נגעי בגדים והבן:
@400 **עוד** נראה שחש הכתוב להקדים נגע הבגד ואחר כך נגעי אדם, שאז הייתי אומר כי נגע הבגד בא על עון קל ונגע אדם בא על עון חמור ולא על עון עצמו שיתחייב לבא נגע על האדם בא על הבגדים לצד הרחמים, ולזה הקדים הכתוב ואמר נגעי אדם לומר כי גם צרעת הצריכה לבא לאדם בעל הרחמים מביאה בבגדים אולי ישוב ורפא לו מבוא עליו. ועדיין אני אומר דלמא על עון חמור באים נגעי אדם ועל עון קל באים נגעי בגדים והתורה סידרה החמור תחלה שהם נגעי אדם ואחר כך הקל שהם נגעי בגדים, אם כן היה לו לסדר משפט הבגדים אחר משפט אדם וטהרתם וכמו שכתבתי למעלה והבן:
@401 **והגיד לכהן לאמר**. תיבת **לאמר** מיותרת. ורז''ל בתורת כהנים דרשו יאמר לו הכהן דברי כיבושין ע''כ. וזה דרך דרש, כי הכתוב מדבר דברי אשר לו הבית. והם ז''ל דרשוה באם אינו ענין לדברי בעל הבית תנהו ענין לדברי כהן. ובעל קרבן אהרן פירש על זה הדרך והגיד לכהן והתכלית לאמר לו הכהן רצה לומר דברי כיבושין. ולפי זה היה לו לומר תיבת לאמר אחר כנגע נראה לי בבית, אלא ודאי שהתנא דרש התיבה באם אינו ענין, וקשה למה לא אמר הכתוב תיבת לאמר בדברי הכהן ותדרש הדרשה ביושר ומקום הניחו לנו לפרש, והוא על פי דבריהם ז''ל עצמם שכתבו שם בתורת כהנים וזה לשונם נגע מה תלמוד לומר כנגע אפילו תלמיד חכם ויודע שהוא נגע בודאי לא יגזור וכו' אלא יאמר כנגע ע''כ. ויש לדעת מי הכריחם ז''ל לפרש כן, דלמא טעם אומרו כנגע ולא אמר נגע כי חש הכתוב לומר נגע שתבין שלא חייבתו תורה לבא אצל הכהן ולהגיד אלא אם תלמיד חכם הוא וידע שהוא ודאי נגע, אבל אם נסתפק בו אם הוא נגע או לא לא יבא לכהן, לזה אמר כנגע שיבא על הספק כודאי:
@401 **אכן** דרשת התנא היא שלא היה לו לומר אלא והגיד לכהן, והדבר מובן שההגדה היא הנגע המוזכר בסמוך, ולזה דרש כי הייתור בא על הדקדוק כנגע ולא נגע שאפילו תלמיד חכם וכו' לא יאמר נגע אלא כנגע, וכל זה לדעת התנא. ומקום הניחו לנו גם כן בזה לחקור בדבריהם ז''ל, הלא לפי מה שדרשו עוד שם בתורת כהנים וז''ל נראה לי ולא לנרי, בבית להביא את העליה וכו' וכמה דרשות, מעתה צריך הכתוב לומר כנגע כדי שיאמר נראה לי בבית ללמוד המשפטים ההמה, ומנין לנו לדרוש שאפילו ידע ודאי שהוא נגע יאמר כנגע, והגם שדרך רז''ל לדרוש הכתובים בסדר זה, אף על פי כן כל עוד שנוכל ליישב הדרשה בסדר הכרחי הוא יותר נכון, ובזה הרווחנו את שלנו פירוש תיבת לאמר שנתכוין לומר על זה הדרך **לאמר כנגע** פירוש הגם שכפי האמת ידע שהוא נגע ואינו כנגע אלא במאמרו אף על פי כן יאמר כן. ושיעור תיבת לאמר הוא על זה הדרך האמירה תהיה כנגע, וממוצא דבר אתה מבין שאינו כנגע אלא במאמרו ולא בצדק הדבר. ובזה גם כן הרווחנו דרשת התנא שדרש בתיבת כנגע שרצה לומר שאפילו תלמיד חכם וכו'. עוד יכוין לומר שהתורה מתרת לאמר כנגע, וממילא אתה מבין שאינו כנגע שהוצרך להתיר. וכבר כתבתי כמה פעמים כי רשות נתונה לנו לדרוש הפסוקים בכמה פנים משונים מדבריהם ז''ל כל שמתישבים הפסוקים על נכון כל שאין הפכיות דברי רז''ל בהלכות:
@402 **בטרם יבא הכהן**. טעם שהוצרך לומר **הכהן** משום שזולתה היה נשמע כי בטרם יבא יצוה, וכפי זה אין חיוב לכהן להתעכב עד שידע שפינו ודאי את כל אשר בבית, ומאומרו הכהן, הראה כי תיבת בטרם אין לה קשר עם זכרון הכהן שאצל וצוה וקשורה היא עם ופינו והבן:
@402 **כל אשר בבית**. פירוש כל אשר בבית לא יטמא אלא יצילו הכל ואפילו פכים קטנים, כי חם ה' אפילו על ממון הבזוי של ישראל, ובזה נתן טעם הכתוב למה צוה ה' לפנות קודם הלא אפילו אחר ביאת הכהן ורואה הנגע אין הבית טמא אלא אחר שיצא הכהן ויסגירנו, ומעתה אין צורך להקדים לפנות קודם בא הכהן ויכולין לפנות אחר שבא הכהן קודם שיסגיר, לזה אמר **ולא יטמא כל אשר** וגו' פירוש כי לצד שכשיראה הכהן הנגע שצריך להסגיר אין רשות להתעכב מלהסגיר כל עיקר ומצד זה ימהרו לפנות ולצד המהירות ישכחו ממון הבזוי, לזה הקפיד ה' לפנות קודם שבזה לא יטמא מכל אשר בבית. ורז''ל אמרו (נגעים פי''ב מ''ה, ובתו''כ) שלא חס הקב''ה אלא על כלי חרם כי שאר כלים ובגדים יש להם תקנה במקוה. ולדרכנו הוספנו לפרש שחס הקב''ה אפילו על כלי חרס הקטנים שאין אדם מחשיב אותם:
@403 **וראה וגו' בקירות הבית וגו'**. פרשה זו רמזה מפעלות ה' בהנהגתו עם הרשעים אשר יבחרו במטעמי יצר הרע שהוא יקרא נגעי בני אדם. ואמרו בזוהר (ח''א קפ''ז) כי הקב''ה נותן הנפש בגוף האדם מצלחת מה טוב ואם לאו הוא עוקרו משם וחוזר ושותלה במקום אחר. והוא מה שרמז כאן בנגעי הבית, כי הבית ירמוז אל גוף האדם שהוא בתי הנפש, והכהן הרמוז כאן הוא הבורא שמצינו לרז''ל בספר הזוהר שדרשו כן בפסוק והובא אל הכהן וגו', ואמר כי כשיראה הקב''ה כי הנגע בקירות הבית פירוש נשתקע בחינת הרע בתוכיות מהות הגוף, ונתעב הבית והוא מה שרמז באומרם שקערורות תיבה זו מורכבת מב' שקע רורות ואות הא' נבלעת במבטא וכאלו אמר שקע ארורות שנשקע בו בחינת היצר הרע שנקרא ארור, ולפי שיש הרבה בחינות ברשעו אמר ארורות ואומרו ירקרקות רמז לסימן העבירה על דרך אומרם ז''ל (שבת לג) סימן לעבירה הדרוקן, גם אמר אדמדמת רומז לשפיכת דמים המיוחס לבחינת הרע רחמנא ליצלן. יצו ה' לסגור הבית פי' שלא יושפע משפע האלהי, והוא סוד נידוי הרשעים לבל יחסו בצלא דמהימנותא, אם האדם הרגיש בדבר ושב מה טוב, ואם לא יצו ה' להביא עליו יסורין לרחוץ כתמיו ונגעיו והוא סוד חלוץ אבנים וכו', ואם עדיין מסריח מעשיו הרי הוא מת, והוא אומרו ונתץ את הבית את אבניו וגו':
@425 **דברו אל בני ישראל ואמרתם וגו** '. כל זה מיותר אחר שאמר וידבר וגו' לאמר. ואולי שיכוין לומר על פי דבריהם שאמרו (תו''כ) בני ישראל מטמאין בזיבה ואין עכו''ם מטמאין בזיבה. לזה אמר **דברו** פירוש לשון קושי שתמצא טומאה בהם יותר מהעכו''ם ישראל זב מטמא משכב ומושב ואין העכו''ם זב מטמא משכב ומושב, ואמר **ואמרתם** פירוש לשון מעלה על דרך אומרו (תבא כו יד) האמרת והאמירך, הכוונה בזה שהגם שהוא מזקיק בהם הטומאה יותר, זה הוא למעלה להם, שהם ישנם בטהרה, ואין עכו''ם בטהרה, והוא סוד אין שוטה נפגע (שבת יג:):
@425 **איש איש כי יהיה זב וגו'**. צריך לדעת למה כפל לומר **איש איש**. ואולי שיודיע מה שאמרו ז''ל במדרש (תדב''א פט''ו) ראה אדם קרי שחייב טבילה, ואמר מי רואה אותי אין בכך כלום, שוב ראה פעם ב', אמר מי רואה אותי, פעם ג', עבר על מה שכתוב פעמים שלש עם גבר, הוא נעשה זב וכו' ע''כ. זה הוא שרמז באומרו **איש איש** פירוש פעם ראשונה איש, על דרך אומרו (תצא כג יא) אשר כי לא יהיה טהור מקרה לילה, ואמר פעם ב', איש לרמוז על פעם ב' אם חזר בו מוטב אם לאו יהיה זב גמור ויטבול לטומאה חמורה:
@425 **זובו טמא הוא**. רז''ל דרשו בתורת כהנים על זה הדרך זובו הוא טמא, למד על הזוב שהוא טמא, והלא דין הוא הזב שהוא גרם לו טומאה טמא, הזוב שהוא גורם טומאה אינו דין וכו', שעיר המשתלח יוכיח וכו' שהוא טהור ומטמא תלמוד לומר זובו הוא טמא. ודרשו עוד על זה הדרך הוא טמא ואין דם היוצא מהאמה טמא, פירוש שהייתי דן קל וחומר מרוקו ומה רוק שהוא יוצא ממקום טהרה טמא דם שיוצא ממקום טומאה אין דין וכו' תלמוד לומר הוא וכדרך שדן התנא שם כשרצה להצריך ריבוי למי רגלים שמטמאים ודן קל וחומר מרוקו וסתר לה מדם היוצא תלמוד לומר וזאת לרבות מי רגלים. ובפרשת דם נדה (נדה נו.) הקשו ומה ראית לרבות מי רגלים ולמעט דם היוצא, ואמר ר' שמעון מרבה אני מי רגלים לטומאה דדומה לרוק שמתעגל ויוצא וחוזר ונבלע, מה שאין כן הדם ע''כ. וקשה אם כן לא לכתוב אלא ריבוי וזאת ואני יושב ודן ריבוי זה למה הלא בין מי רגלים בין דם היוצא באים בקל וחומר מרוקו, ומכח זה הייתי מכריח לומר שלא לדון קל וחומר ונאמר שבא הכתוב לסתור קל וחומר שתחייבך לרבות מי רגלים ודם היוצא ולא ריבה אלא אחד מהם, ולידע איזה מהם הוא המתרבה ידון בדומה לרוק שמתעגל וכו' כדברי ר' שמעון, ולא היה צריך לכתוב מיעוט הוא. ואין לדחות שאז הייתי אומר שבא ריבוי וזאת לדם היוצא הגם שאינו מתעגל וכו' אבל מי רגלים אתי בקל וחומר, זה טעות, כי כשאנו באים לדון בקל וחומר מהרוק שאינו יוצא ממקום טומאה אנו דנין מי רגלים ודם היוצא כאחד בקל וחומר שהרי הם שוים בצד החמור שיצאו ממקום טומאה, ולא צריך ריבוי לדם אם לא שתאמר דאתא קרא לסתור לקל וחומר, ותמצא שגם התנא שגמר מיעוט הדם ממיעוט הוא כשבא ללמוד מי רגלים מקל וחומר דרוקו דחה דם היוצא יוכיח שאינו נלמד בקל וחומר ולא דחה פירכא זו מה לדם היוצא שאינו מתעגל וכו'. ומעתה כשלא יהיה אלא ריבוי וזאת תתחייב מעצמך לומר שהתורה מנעתך מלדון קל וחומר זה כדי שלא תדון הכל, ואני יודע כי מה שבא לטהר הוא דם היוצא ומכח זה בניתי מקום לפרש שנתכוון הכתוב בייתור תיבת הוא לומר כי אין גופו של זב לבד הוא המטמא את בעליו אלא הוא סימן אשר יעשה ה' בטמא לצד מעשיו הרעים, והודיע ה' כי אדם שיהיה בו סימן זה הוא לו לסימן כי איש טמא הוא. ותיבת הוא שאמר הכתוב חוזרת אל האדם שטמא הוא. ולזה יצו ה' משפט האדם שהוא עצמו אב הטומאה לטמא אדם וכלים והגם דהתנא דרשה למיעוט דם, זה היה קודם דרשת וזאת ואחר דרשת וזאת נחזור לדון ולדרוש. והרבה פעמים דורש בתורת כהנים בדרך זה, וכאן הניח מקום לדורשי תורה:
@426 **טומאתו בזובו**. בתורת כהנים אמרו טומאתו בזובו למעט שאינו מטמא באודם ע''כ. פירוש וזולת מיעוט זה הגם שאמר קרא זובו טמא הוא ודרשו בתורת כהנים שבא למעט אודם היוצא שאינו מטמא, לא דרשו כן אלא לצד שאחר האמת מיעט הכתוב שאינו מטמא הזב באודם, אבל אם לא היה מיעט טומאת האודם אז היה נכלל גם האודם בכלל אומרו זובו טמא, כי שניהם נקראים זובו, ולא היינו יכולין למעט האודם, והיינו מוכרחין לפרש מיעוט הוא על טומאת הזב שאינו מטמא באודם, ולא היה לנו מקום למעט דם היוצא שאינו מטמא, והוה אתי בקל וחומר מרוקו כאמור שם. או היינו מתחכמים למעטו ממה שיוצרך לריבוי וזאת כמו שכתבנו למעלה:
@426 **טומאתו היא**. בתורת כהנים דרשו ומה הזב שאינו מטמא באודם מטמא בלובן זבה שמטמאה באודם אינו דין שמטמאה בלובן תלמוד לומר טומאתו היא. פירוש שלא היה צריך לומר טומאתו, אלא בא למעט זבה, טומאתו ולא טומאתה. ולא מתיבת היא ממעט הזבה כדברי בעל קרבן אהרן, כי כשנבא לדייק ממשמעות מיעוט המתדייק מתיבת היא יהיה המיעוט בטומאה ולא בנטמא והבן. ומה שיש לפרש בברייתא זו שהצריך למעט זבה שלא תטמא בלובן שלא תדון בקל וחומר מזב, ובראש ברייתא זו ממעט הזב שלא יטמא באודם שלא ידון בקל וחומר מזב, והם ב' קל וחומר הסותרים זה את זה, כבר הארכתי בפרשה זו בפסוק והזה על המטהר, ולדרך שכתבתי שם יתיישבו גם כן דבריהם ז''ל במקום זה, כי יש בנדה חומרא שדמה מטמא לח ויבש (נדה נד:) מה שאין כן זובו של זב שאינו מטמא אלא לח, גם מטמא משכב ומושב בראיה אחת מה שאין כן הזב, ולזה יש להגדיל טומאת הדם, ויש חומרא בזב שאינו צריך ימים אלא ראיות, וגם שסופר שבעה לב' ראיות מה שאין כן הזבה, ואם כן יש צדדים להגדיל טומאת הלובן, וחש הכתוב למי שיגדל בעיניו חומרא זו לדון קל וחומר בדרך זה, ולמי שיגדל בעיניו חומרא זו שידון בדרך זה והבן. וטעם אומרו תיבת היא, נראה שחש הכתוב שיאמר האומר לא מיעט הכתוב לובן בזבה אלא למעט שלא יטמא בחומרות האודם דהיינו לטמא משכב ומושב בראיה אחת שלא לומר דון מינה ואוקי באתרא אבל לטמא בטומאתו של זב עדיין אני אומר שכן הוא, תלמוד לומר מיעוט ב' היא פירוש שהמיעוט בא על מציאות עצמה של טומאת הזב שאינה אלא בו, ושיעור הדברים הם על זה הדרך טומאה זו כמשפט אשר בו הוא דהיינו שמטמאים בב' וג' ראיות אינה אלא בזב כמובן מאומרו טומאתו ולא של זבה:
@441 **ורחצו במים**. טעם זכרון רחיצתו, אז''ל (תו''כ) להשוות לה משפט רחיצתה לכל התנאים הרמוזים בדין רחיצתו. ואם תאמר אם לזה נתכוון הפסוק לא היה צריך והיינו לומדים כן מאומרו ואשה בתוספת ו' מוסיף על ענין ראשון להשוות משפט שניהם וליתן את האמור העליון בתחתון, כמו שדרשו בתורת כהנים בפרשת ויקרא כל אותם דינים שכתוב בהם וא''ו בתחלה, ולפי מה שדרשו רז''ל בתורת כהנים וא''ו ואשה לרבות קטנה בת ג' שנים ויום אחד, לפי זה אם לא אמר ורחצו היינו דורשים הוא''ו למשפטי הרחיצה ולא ידעי' טומאה קטנה בת ג' שנים ויום אחד. וזולת דבריהם היה נראה לומר לפי מה שאמרו (בתו''כ) בפסוק אשר תצא ממנו שכבת זרע עד שתצא טומאתו חוץ לבשרו אבל אם לא יצתה הגם שהרגיש אוחז באמה ובולע התרומה, מה שאין כן האשה שטמאה אפילו בנגעית שכבת זרע במסתריה, לזה אמר ורחצו לומר שאין משוה שניהם אלא ברחיצה לא במשפט הטומאה. ומעתה אנו מפרשים אומרו ואשה בוא''ו כי גם האשה לפעמים יש בה משפט שוה לאיש שאינה טמאה במסתריה לרבנן אם בא עליה שלא כדרכה ולרבי יהודה ביאה ראשונה של כלה (בתו''כ כאן, יבמות לד:), ודייקו לה מתיבת אותה, ומעתה אם לא אמר ורחצו והייתי בא לדון משפטי הרחיצה שבאיש לאשה מוא''ו ואשה הייתי דן נמי שמטמא באיש אפילו לא יצתה שכבת זרע חוץ ויגמור מהאשה והייתי מפרש אומרו תצא כי עקירתה ממקומו נקראת יציאה, או על זה הדרך כי תצא לעתיד פירוש כל שראויה לצאת הגם שלא יצאתה טמא וכמו שמצינו באשה, לזה אמר ורחצו לגלות לך שלא נתקו בוא''ו של ואשה ליתן האמור של זה בזה, ואם היה אומר ורחצו בלא וא''ו ואשה הגם דאיכא תיבת אותה שממנה דורשים מיעוט למר שלא כדרכה ולמר הכלה אז לא היינו דורשים תיבת אותה בדרך זה והיינו דורשים אותה לדרשה אחרת אחר שנתגלה לנו בפירוש בפסוק שמטמא בית סתירה מ''ל כלה מ''ל וכו', ואדרבה היה מקום לומר אותה לרבות כל סתריה, אבל מאומרו ואשה בוא''ו השוה אותם הכתוב לשאר טומאת סתרים דלא מטמאים. ולפי מה שדרשו בתורת כהנים ואשה לרבות בת ג' שנים ויום אחד, גילו דעתם שסוברים שתיבת אותה מיוחדת היא לדורשה למיעוט ולא לרבות, ולזה נשארת וא''ו ואשה מיותרת ודרשו לבת ג' שנים ויום אחד:
@451 **ואם טהרה מזובה וספרה וגו'**. צריך לדעת גזירת הכתוב באיזה מקום הוא, אם הספירה היה לו לומר תספור לה, ואם אחר תטהר לא היה לו לומר ואחר, ונראה על פי מה שאמרו בתורת כהנים וזה לשונם ואם טהרה מזובה כשתפסוק מזובה ע''כ. לפי זה תהיה גזירת הכתוכ תיבת **מזובה**, והכי קאמר **ואם טהרה** תדע מאיזה זמן תקרא טהרה מזובה מעת נפסקה זובה נקראת טהרה לספור ז' ימי, והוא שאמרו כשתפסוק מזובה והבן. ותמצא שפרש''י בפרק קמא דמגילה (ח) וזה לשונו כשתפסוק מזוב' לאלתר תספור שאינה צריכה לטבול קודם והוא מכוון למה שכתבתי:
@451 **עוד** נראה לפרש הכתוב על זה הדרך **ואם טהרה** פירוש נסתלק הזוב שכן הוא משמעות תיבת טהרה ולא תחשוב שבהסתלק הזוב נסתלקה טומאה ממנה, לא כן, שלא נסתלקה אלא טומאת הזוב עצמו, והוא אומרו מזובה אבל לא טומאה מגע זוב, ועודנה טמאה וצריך לספור ז' נקיים, והוא אומרו וספרה לה וגו' ואחר תטהר מכל:
@451 **חסלת פרשת מצורע**
@457 **וידבר ה' וגו'**. צריך לדעת מה נאמר לו בדיבור זה. ב' לאיזה ענין ישמיענו הכתוב היות דיבור זה אחרי מות, מה לי אחר מה לי קודם. ג' למה הוצרך למור **בקרבתם** וגו', אם להודיע שמתו בשביל שנתקרבו לפני ה', הלא כבר הודיע הדבר במקומו (לעיל י יא) ויקריבו אש זרה וגו', ושם הוא יותר מפורש הדבר ומה שכתוב כאן בקרבתם, שאין ידוע מה הוא העון שעשו בקריבה זו שעליה מתו. ד' אומרו וימותו מיותרת אחר שהתחיל לומר אחרי מות בקרבתם וגו'. ה' אומרו וימותו בתוספת וא''ו:
@457 **ונראה** שכוונת הכתוב הוא שבא הקב''ה להזהיר את משה שלא יחשוב בדעתו כי לצד שהוא יותר קרוב למלכות שמים ובכל ביתו של המקום נאמן הוא ויכול ליכנם אל הקודש פנימה, והגם שיצו ה' על אהרן לא יתחייב הדבר שגם משה בכלל, כי גדול משה דכתיב (במדבר יב) אם יהיה נביאכם ה' וגו' לא כן עבדי משה, אשר על כן דבר ה' אל משה, והוא אומרו **וידבר ה' אל משה** פירוש אליו בא המצוה, ואמר לו סמוך למיתת ב' בני אהרן דיבור זה **בקרבתם** לפני ה' וימותו, פירוש הגם היותם בני אהרן ובתוספת מרובה היותם קרובים לפני ה' כמו שדרשו ז''ל (ויק''ר הי''ב) בפסוק בקרובי אקדש אף על פי כן לא חמל עליהם **וימותו**, הא למדת שלא יועיל היות האדם כל כך קרוב לה' כדי שיפרוץ גדר ליכנס לקודש פנימה:
@457 **עוד** נראה לומר שנתכוון באומרו **בקרבתם** על זה הדרך בהיותם יותר קרובים לה' מכל, הא למדת שאין קרובים מהם, שאם היה משה קרוב מהם היה הדבר נעשה בו כמו שאמר לו ה' (לעיל ג') בקרובי אקדש. ואולי כי כאן ביאר הקב''ה דבריו אל משה, ועל פי הדברים האלה אמר משה לאהרן הוא אשר דבר ה' וגו', כי דיבור זה נאמר לו סמוך לקריבתם ומיתתם. והגם שכבר כתוב בתורה מיתת ב' בני אהרן, אין מוקדם ומאוחר בתורה. ובתורת כהנים אמרו בסלקא דעתין דתיבת אחיך בא למעט משה שאינו באזהרה ומותר לבא בכל עת, והעלו באמיתות הדרשא שתיבת אחיך באה לרבות הבנים שהם באזהרת ע''כ. וכפי זה לא נתמעט משה מאזהרה, ומעתה אין אני יודע מה דינו של משה אם הוא באזהרה או לא. והרב בעל קרבן אהרן כתב שפשיטא כי מי הכניסו עד שיצטרך להזהירו. ולפי מה שכתבתי הנה באה אזהרתו ביחוד בפסוק ראשון. ודברי בעל קרבן אהרן שאמר מי הכניסו אינם נראים. וכונת התנא היא שלא בא הכתוב למעט משה מהאזהרה, ואין לנו מקרא לא למעט ולא לרבות, ובחר התנא לדרוש ביתור תיבת אחיך לרבות הבנים מלדרוש בה למעט משה. וכל זה לסברת האומר (ב''ר מ''ד ה') אחרי סמוך אחר מופלג, וכמו שהעתקתי מחלוקתם במקומות אחרים. אבל לסברת האומר אחרי מופלג אחר סמוך יתבאר הכתוב על זה הדרך שבא להודיעו שמיתתם היתה על קרבתם לפנים בקודש, והגם שהתורה אמרה אש זרה, מודיעו ה' כי טעם מיתתם היתה על קרבתם לפנים הגם שלא היתה אש זרה, ואומרו **וימותו**, נתכוין להודיעו שלא יחשוב כי יצתה מחשבתם לפועל שנכנסו לפנים אלא שנדחפו ומתו, והכוונה בהודעה זו לשלול לבל יחשוב אדם לפרוץ ולהתקרב הגם שימות, וזה ימצא בהיות לאדם בחינת החשק לא יחוש על עצמו ויתן נפשו, ודבר זה ימצא בבחינת החושק שיתן נפשו על הדבר הגם שידע שימות, לזה אמר לו וימותו פירוש וכבר מתו ולא השיגו מחשבתם להתקרב והבן זה:
@457 **וזה** לדעת ר' יוסי הגלילי שאמר בתורת כהנים על הקריבה מתו וגם לסברת ראב''ע שאמר כדי קריבה לעצמה וכדי הקרבה לעצמה, אבל לדברי רבי עקיבא דאמר על ההקרבה מתו, הנה לסברת האומר אחרי מופלג יתבאר הכתוב באופן אחר, והוא בהקדים לחקור למה לא ציוה ה' על משפט יום הכפורים האמור בפרשה זו עד הן היום ולא צוה ביום צוותו בענין קדשי המשכן, וכאשר אמר לו (שמיני ט ז) קרב אל המזבח שם היה לו לומר לו לא יבא אל הקודש פנימה. האמת שמדוייק הוא האיסור מאומרו קרב אל המזבח ועשה את וגו', שלא היה לו לומר אלא עשה את חטאתך וגו' ולמה הוצרך לומר קרב וגו', ורז''ל (בתו''כ) דרשו דרשות, ולדרכנו נראה שאמר אליו קרב אל המזבח אין לך רשות ליקרב אלא למזבח ולא לפנים, אלא ששם היה לו לצוות באזהרה זו דאל יבא וגו' ולא ימות:
@457 **אכן** לצד מה שהודיענו הכתוב שבעון העגל מתו שני בני אהרן דכתיב (עקב ט כ) ובאהרן התאנף ה' להשמידו ואתפלל וגו' ופירשו רז''ל (ויק''ר פ''ז) להשמידו זה מיתת הבנים והועילה תפלתו של משה מחצה, הא למדת כי שני בני אהרן בעון העגל מתו ומזבח כפרה היו המה לאביהם, ולא תקשה והלא אמרו (תו''כ כאן) שמתו לצד עון הקריבה למאן דאמר ולמאן דאמר על ההקרבה. יש לומר שאם לא היה עון אביהם היה ה' שומר רגלי חסידיו. גם לא קשה על מה שאמרו (זבחים קטו) שמתו להתקדש שמו יתברך, כי אם לא היה עון העגל היה מתחייב מאלהי המשפט להתקדש הבית בזולתם, כי כבר הודעתיך שהגם שיחפוץ ה' המותה לחסידיו לסיבה נעלמת לידוע תעלומות נפלאים ורמות, צריך שיהיה לצדיק כל שהוא מהדברים אשר לא טוב עשות כדי שדרך שם ישלוט בהם הדין. וכבר הארכתי בענף זה, צא ולמד (אבדר''נ פל''ח) ממה שמצא רע''ק טעם להריגתו לצד ששמח לבו בדרשתו תוך ס' ריבוא כאמור בדבריהם, וקשה הלזה יתחייב אנוש מיתה משונה אם כן פקע כלילא דורדי מכל עושי טוב ולומדים, אלא דזה הוא דרך שממנו ישלוט בו הדין, ולעולם סיבת מיתתו יקר בעיני ה' המותה לעשרה הרוגי מלכות למגן וצינה לדורות בני ישראל. וטעם זה נותן טעם לשבח גם במה שלפנינו, כי עון העגל כבר נמחל בפרהסיא כשהקריב אהרן אל המזבח וירדה שכינה על ידו ונתבשר שנמחל לו עון העגל, אם כן בטל דינא דהשמדת הבנים שבהבטל הסיבה יבטל המסובב, אלא ודאי כי הגם שנמחל רישומו ניכר והוא כשיעור חוט השערה מהחטא שיספיק להשלטת מדה הפועלת דין באדם, וזה גרם שלא נשמרו רגלי חסידיו ושגגו בקריבה והקרבה, ונתקדש בהם הבית:
@457 **ועל** פי הדברים האלה נוכל לומר כי לא הוכשר אהרן להיות ראוי לבא אל בית חצר המלך פנימה אלא באמצעות מזבח כפרה של הבנים בניו ונמחה רושם חטא העגל, אבל זולת זה לא הוכשר אהרן למעלה עצומה לעמוד במקום מופלא ובזה יתישב הכתוב על נכון, **וידבר ה'**, ומודיע הכתוב כי הדיבור הנאמר בענין **בזאת יבא אהרן אל הקודש** לא נכשר אהרן למעלה זו אלא **אחרי מות שני בני אהרן** ונמחה חטאו ודקדק לומר **בני אהרן**. כאן רומז כפרת עון אביהם שבזה הושלם להיות ראוי להאמור בענין כמו שפירשתי. ובזה נתן הכתוב טעם למה לא צוה ה' את הדבר הזה עד הנה, כי מקודם לא היה מוכשר אהרן לזה, ואחר שנחת הכתוב להודיע סיבת מיתתם שהוא לצד היותם בני אהרן לכפרת עון אביהם הודיע כי לא זאת היא סיבתם מתחלה ועד סוף למיתתם, אלא זאת היתה סיבה ראשונה שהיא גרמה שלא נשמרו רגליהם כנזכר ושגגו בקריבה או בהקרבה למאן דאמר, והוא אומרו **בקרבתם לפני ה'** לומר כי מה גרם להם היותם בני אהרן שיש בידו עון מעשה העגל הוא קרבתם, ובהצטרפות מכשול זה מתו. ולצד שכפי האמת ב' סיבות הללו לא הספיקו למיתתם, רבתי הוא אשר דבר ה' (לעיל י ג) בקרובי אקדש, שמתו להתקדש הבית בשבילם, כאשר אבאר טעם הוצרך לטעם זה ולא הספיקו ב' הטעמים, לזה אמר וימותו בתוספת וא''ו לרמוז ענין צורך מיתתם להתקדש הבית לירא את ה' המקודש לירא מהמקדש כל הקרב לבל ימות גם הוא ולזה סמך דיבור אזהרת אהרן **ואל יבא** וגו' **אל הקודש**. נמצאת אומר ג' דברים גרמו מיתתם, עון העגל, וההקרבה, וקידוש הבית, ושלשתם הודיע ה' במאמר ראשון שאמר **אחרי מות שני בני אהרן** זה כנגד חטא אהרן, **בקרבתם** כמשמעו, **וימותו** בשביל לקדש הבית **לבל יבא** וגו' **אל הקודש** קטן וגדול, וכל ג' הטעמים צריכין, עון העגל שזולתו לצד שהיו צדיקים גמורים היה הדין מחייב שיהיו נשמרים לבל יכשלו בקריבה וזה סימן למכשול ועון הקריבה גם כן שזולתה לא יומתו על עון אביהם כי גדולים היו, וסיבת קידוש הבית שזולת זה לא היה ה' מערבב שמחתו ביום שמחת לבו, ויתחייב הדבר לשמירת רגליהם לבל יכשלו, או לא היה ה' ממיתם באותו יום והיה ממתין להם עד יום אחר, אלא לצד שרצה ה' לקדש הבית בו ביום עשה כן. וטעם זה לבד לא יספיק למיתתם, שיתקדש הבית בזולתם:
@457 **וכפי** זה אפשר לתת טעם למאמרם ז''ל שאמרו (תו''כ שמיני) שאמר משה על נדב ואביהוא שהם גדולים ממשה ואהרן כי ממה שראה משה שהוצרך טעם עון העגל למיתת בני אהרן אם כן לא מצא הקב''ה נדנוד עון להסתבך בו ענף הדין ולא נכשלו אלא לצד מה שקדם בעון אביהם, לזה אמר שהם גדולים ממשה ואהרן כי לא נמצא להם אפילו כחוט השערה מהחטא מה שאין כן משה ואהרן. ולדרכנו זה אפשר שלזה נתכוון הכתוב באומרו (משלי כב) הלא כתבתי לך שלישים במועצות ודעת, כי ג' דברים היו סיבה לדבר, במועצות ב', ודעת ג', והם ג' דברים האמורים בענין, כנגד מה שלא מחל ה' לאהרן לעון העגל לא בתפילה ולא בהרצאת אהרן בקרבנותיו ומעשיו, גם כנגד מה שלא שמר רגליהם מלהתקרב למקום מקודש אמר במועצות, כי נתיעץ ה' לתכלית דבר, ורמז לב' הדברים במה שאמר מועצות לשון רבים ב' עצות, וא' מסובבת מחברתה, שלא החליט מחילה לאהרן כדי שלא ישמרם שבזה תמצא מדה השולטת כנזכר, וכנגד תכלית הדבר שמתו לקדש שמו יתברך אמר ודעת פירוש להודיע לכל מה יקר מקום קדושתו שאפילו לאנשים צדיקים כאלו שאין כמותם היה מה שהיה ויתקדש הבית:
@457 **עוד** נתכוון באומרו **אחרי מות** להיות שיצוה ה' לבל יכנס אהרן לקדשי קדשים בבגדי זהב (ראש השנה כו) מטעם אין קטיגור נעשה סניגור חש הכתוב לבעל דין שיחלוק ויאמר כי לא הקפיד ה' על הכנסת אהרן בבגדי זהב אלא כל עוד שעדיין לא נמחה רישומו של עון העגל, מה שאין כן אחר שמתו בניו ואין רישומו של עגל ניכר לחלוטין נמחה קטיגורו של זהב ויכול ליכנס בבגדי זהב בכבוד ובתפארת, לזה אמר **אחרי מות** וגו' שגם אחרי מותם צוה ה' לבל יכנס בבגדי זהב לקודש הקדשים אלא **כתונת בד קודש** וגו'. והגם שאמרו ז''ל (ערכין טז.) שבגדי זהב מכפרים. אף על פי כן לא יעשה קטיגור סניגור ללבן עונם של ישראל כשלג. ועיין מה שכתבתי בימי חורפי בחפצי חפץ ה' במאמרם ז''ל (שבת ל.) שכשאמר שלמה זכרה לחסדי וגו'. ולדרך זה אומר **בקרבתם** בא להסיר חשש פגם מעל משה שהוא אמר (עקב ט כ) ואתפלל גם בעד אהרן ויאמר האומר שלא הועילה תפילתו של משה, ומשה עצמו יחשוב מחשבות שלא הועילה תפילתו, לזה אמר **בקרבתם** לפני ה' פירוש בהצטרפות סיבה זו מתו אבל זולת זה והלא היו מתים כי הועילה תפלתו של משה על אהרן לבל ישמידו, וכפי זה אין אנו צריכין לומר שהועילה מחצה ולדבריהם ז''ל (ויק''ר פ''י ה') שאמרו שהועילה מחצה, פירוש כיון דסוף סוף מתו לא יהיה תועלת מתפלתו של משה לאהרן אלא מחצה כי אינו חשוב תועלת אלא כפי תכלית. ואומרו וימותו, אולי שבא ה' לומר למשה כי האנשים האלה עשו עון הקריבה או הקרבה והם כבר היו חייבי מיתה מעת התרגז ה' על אהרן להשמידו ולזה לא נמנעו מיד מדת הדין, אבל אם לא היה מה שקדם שהיו בני מיתה כנזכר הגם שהיו נכנסים אפשר שהיה ה' מאריך אפו להם וכדומה לזה, ושיעור הכתוב על זה הכתוב **בקרבתם לפני ה'** ומקום זה צריך לעשות להם נם למלטם מיד מדת הדין והם וימותו כבר פירוש נתחייבו מיתה קודם אלא בתפלת משה נמלטו:
@457 **או** יאמר על זה הדרך **אחרי מות** וגו'. דבר ה' למשה דרך מיתתן שהיתה על זה הדרך **בקרבתם לפני ה'** פירוש שנתקרבו לפני אור העליון בחיבת הקודש ובזה מתו, והוא סוד הנשיקה שבה מתים הצדיקים, והנה הם שוים למיתת כל הצדיקים, אלא שההפרש הוא שהצדיקים הנשיקה מתקרבת להם ואלו הם נתקרבו לה, והוא אומרו **בקרבתם לפני ה'**, ואומרו **וימותו** בתוספות וא''ו, רמז הכתוב הפלאת חיבת הצדיקים, שהגם שהיו מרגישים במיתתם לא נמנעו מקרוב לדביקות נעימות עריבות ידידות חביבות חשיקות מתיקות עד כלות נפשותם מהם והבן ובחינה זו אין מכיר איכותה, והיא מושללת ההכרה, לא מפי מין האנושי, ולא מפי כתבו, ולא תושג בהשערות מושכל הגשם, ולמשיג חלק מהשגה זו תבדיל ממנו המונע אותו מהתקבל ותכירהו על ידי סימניה כי זה הפכה מנגדת שונאיה ותפעול בו פעולה רשומה לשלול ממנו כח המונעו והמקיימו, ולפעמים תמאסהו הנפש ותריבהו מריבה גדולה והוא סוד הוללות הנביאים (ש''א יט כד), ולכשתרבה בחינה זו בפנימיותו תגעל הנפש את הבשר ויצתה מעמה ושבה אל בית אביה. ואודיע למתבונן בפנימיות השכלת המושכל, שהשכלת ההשכל תשכיל ההשכלות, ובהשכל בהשכלתו, ישכיל, שמושכל מושלל ההשכל, וכשישכיל בהערת עצמו, ולא עצמו ישכיל, שהמושכל מושכל ממושכל, בלתי מושכל מהשכל, והשכילו למשכילים ביחוד, השכלתו בסוד נשמה לנשמתו. ואז מותריו יהיו עטרי מלכים וכסאם. וכי יש חיים לחיים שעליהם אמר משה (נצבים ל יט) ובחרת בחיים בית המודעות, ושוללת חיים הנשתוים בהרגש הכללי, ויברך ברוך אלהים חיים אשר סגל סגולה זו לסגולתו:
@457 **עוד** יתבאר על דרך אומרם ז''ל בתורת כהנים והובאה במסכת יומא (נג.) וזה לשונם תניא ר''א אומר ולא ימות עונש, כי בענן אראה אזהרה יכול קודם מיתת בני אהרן, תלמוד לומר אחרי מות, יכול שניהם אחר מיתת וכו', תלמוד לומר אראה וגו', הא כיצד אזהרה קודם, מיתה עכ''ל. ובמס' יומא פ''ה (שם) בעי מאי משמע, ואמר רבא דכתיב אראה ועדיין לא נראה, ואילו היה אחרי מות בני אהרן כבר נראה בו ביום שנאמר (ט כג) וירא כבוד ה' ע''כ. וכפי זה בני אהרן מתו קודם שהעניש הכתוב. וכפי זה יתבאר הכתוב על זה הדרך אומרו **אחרי מות** בא לבל תחשוב בראותך כי יצוה ה' מצות הקטורת ואמר ולא ימות נאמר כי הוא זה עונש שבו נענשו בני אהרן דכתיב (י יא) ויקחו בני אהרן וישימו עליה קטורת וגו', לזה אמר **אחרי מות** וגו' פירוש כי לא צוה בעונש אלא אחר שמתו בני אהרן וגו'. אם כן לפי זה חלה הקושיא למה מתו. לזה אמר כי לא מתו על קו המשפט שאחרים אם היו עושים דבר זה לא היו מתים כיון שעדיין לא נצטוו בעונש, אלא הטעם הוא **בקרבתם לפני ה'** להיותם סביביו של הקב''ה דקדק עמהם כחוט השערה, ודבר קטון יחשב לדבר גדול, והוא מה שרמז בתוספות הוא''ו של וימותו לומר הגם שלא היו מחוייבים מיתה מטעם שעדיין לא ענש אף על פי כן מתו:
@457 **ובתורת** כהנים אמרו וזה לשונם דבר אל אהרן וגו' אין אנו יודעים מה נאמר בדיבור ראשון, היה ראב''ע משלו משל למה הדבר דומה לחולה שנכנם אצלו הרופא אמר לו אל תאכל צונן ואל תשכב בטחב, בא אחר ואמר לו אל תאכל צונן וכו' שלא תמות כדרך שמת פלוני, זה זרזו יותר מן הראשון, צריך לדעת למה אמר בסדר זה היה רבי אלעזר בן עזריה שהיה לו לומר אמר רבי אלעזר בן עזריא וכו':
@457 **ונראה** כי רבי אלעזר בן עזריה לא לקושיא זו נתכוין אלא על קושיא אחרת בא לתרץ, והיא מה שהקשינו למה איחר ה' לצוות מצוה זו לאהרן עד עתה, והיה מושלו לרופא וכו' שהרופא המזרז הרבה הוא שאומר כדרך שמת פלוני, וכמו כן עשה רופא ישראל שהמתין עד שמתו בניו כדי לזרזו ביותר, ומביא התנא דברי רבי אלעזר בן עזריה לתרץ גם קושיות כפל הדיבורים ובכללי הגמרא אנו אומרים שלפעמים מזכיר בעל המאמר בתירוץ ולא בקושיא, אלא שהתנא מביא דבריו לתרץ גם מה שהוקשה לו מה נאמר לו בדיבור ראשון כי נאמר לו הבט וראה שהאנשים הנגשים אל ה' קדשו ותבער בם אש הקדושה כה תאמר לאהרן אחיך גם הוא אל יבא וגו'. אלא דקשה לפי זה היה לו לומר אחרי מות ב' בני אהרן אחר דבר וגו', או אחר אומרו וידבר:
@457 **וראיתי** בסוף הברייתא דרבי אלעזר בן עזריה שגמר אומר וזה לשונו וזה זרזו (יותר) מהראשון לכך נאמר ויאמר וגו' דבר אל אהרן שאמרתי לך (שמות ד יד) הלא אהרן אחיך הלוי וראך ושמח בלבו, ואל יבא וגו' ואם יבא הוא מת עכ''ל. צריך לדעת מנין מצא לומר שאמר לו ה' הלא וגו' וראך וגו'. והיה נראה שהוקשה לו יתור תיבת אחיך, ולזה דרש אחיך שאמרתי לך הלא אהרן אחיך הלוי, והכונה כי יפחידו שלא יארע לו כמו שאירע לבניו, והצד שממנו יתחייב אמר לו כל זה הוא לצד היותו אחיו אחוה נכונה ונאמנה, אלא שקשה כי בתורת כהנים דרש מאומרו אחיך לרבות בני אהרן וכמו שכתבתי למעלה, ואפשר דדרשינן שניהם ודוחק:
@457 **ונראה** שכונת המאמר הוא ממה שאנו רואים שה' אמר למשה מה שצריך שיאמר לאהרן שלא ימות כבניו, ומן הראוי היה לו לומר זה אחר ויאמר ה' דבר אל אהרן לא מקודם, לזה אמר כי להיותם ב' אחים הנעימים אוהבים זה את זה כאומרו הלא אהרן אחיך הלוי ורמז לו (זבחים קב) שיטול כהונה ולא הקפיד, גם אהרן בראותו אחיו הקטן יגדל ממנו ואף על פי כן שמח בלבו, אשר על כן הוא אומר למשה דבר הנוגע לאהרן, ונתכוין ה' בזה להיות כולם כאיש אחד, ואם נאמר שמה שדרשת דבר אל אהרן שאמרתי לך הלא אהרן וגו' הוא דרשה בפני עצמה ואינה גמר דרשה שלפניו נראה כי אומרו ואל יבוא בתוספות וא''ו. ולפי פשט הכתוב נראה לומר כי באומרו ואל יבא בתוספת הוא''ו ולא הספיק לו לומר אל יבא, לרמוז שלא יוסיף הוא לעבור עליו מה שעבר על בניו, וכפי זה כאילו ביאר הכתוב שלא ימות גם הוא כבניו:
@457 **וראיתי** להרא''ם ז''ל שפירש כי לדברי רבי אלעזר בן עזריה יש ג' מיני אזהרות, והאריך ליישב הכתובים לדברי רבי אלעזר בן עזריה ולפי דעתי לא נתכוין רבי אלעזר בן עזריה אלא לומר שבדיבור ראשון אמר ה' למשה שיאמר לאהרן שאם יעבור ימות כדרך שמתו בניו, והוקשה לו לאיזה ענין יצוה ה' ככה ולא הספיק באומרו ולא ימות, לזה המשיל הדבר לרופא שהרופא שאומר לחולה שלא ימות כדרך שמת פלוני הוא מזרזו ביותר על כן צוה ה' ככה לתוספות זירוז, ורבי אלעזר בן עזריה לא המשיל הדבר ברופא א' אלא בג' רופאים וכל רופא שיער זירוז א' ורופא המזרז ואומר שלא ימות כפלוני לא הוא שזרז פעם ראשונה ושניה, וכפי זה סדר שעשה ה' הוא כרופא המזרז יותר מכלן, ולפי דברי הרא''ם אינו דומה לא לרופא א' ולא לב' ולא לג', כי רופא א' וב' אינם אומרים כפלוני והג' הוא מזרזו בפעם אחת ואומר לו שלא ימות כפלוני, מה שאין כן הקב''ה שלא ציוהו כן עד פעם ג'. ולדברי הרא''ם צריך לדחוק ולפרש שהדמיון הוא נושא א' לג' נושאים יחד. ועדיין קשה לדבריו למה עשה רבי אלעזר בן עזריה הדמיון בג' נושאים ולא בנושא אחד כדי שישוה אליו הנדמה, אלא ודאי שלא צוה אלא פעם אחד ובאחת דבר אליו הזירוז שלא ימות כבניו. ופירוש הכתובים לדבר רבי אלעזר בן עזריה הם על זה הדרך, וידבר וגו'. אחרי מות דיבור אחד. דבר וגו' ואל יבא וגו' דיבור ב'. בדבור אחד נאמר לו אמור לאהרן שבניו מתו בשביל ההקרבה, ואמור דיבור ב' שאני מצוהו לבל יקרב גם הוא, וממוצא דבר מובן כי מזרזו לבל יארע לו כדרך שמתו בניו, והוא דמיון הרופא הג' שזרזו יותר מכולן:
@458 **ויאמר ה'**. טעם לשון אמירה, לצד שהאזהרה באה בתוקף שאם יבוא ימות כמו שדרש רבי אלעזר בן עזריה (תו''כ כאן). לזה הודיעו כי אין זה אלא חיבה יתירה כדרך הרופא שמשתדל לזרז החולה לבל ימות, וכדמיון רבי אלעזר בן עזריה והוא מה שרמז בלשון אמירה:
@458 **או** ירצה כי ה' גדל ורמם את משה שגם דיבור הנוגע לאהרן לבדו לא דבר ה' עם אהרן אלא עם משה, והוא אומרו **ויאמר ה' אל משה** על דרך וה' האמירך, ותמצא שאמרו ז''ל (מד''ר פ' נשא פי''ד כ''א ריש תו''כ) שאפילו במקום שאמר הכתוב וידבר ה' אל משה ואל אהרן הכוונה בו למשה שיאמר לאהרן, וזה לך האות שאפילו מצות אהרן לא נאמרה לאהרן, ואם היה ה' מדבר עם אהרן לא היה צריך לצוותו על ידי שליח:
@458 **ואל יבא** אמר וא''ו בתחילת דיבור, מלבד מה שכתבנו למעלה, נראה עוד לומר כי לצד שקדם משה ואמר לאהרן ביום א' למשיחתו (לעיל ט ז) קרב אל המזבח ועשה וגו' משמעות הדברים יגידו כי למזבח יקרב ולא לפנים מן המזבח, ואמרו מאורי עולם שהם רבותינו ז''ל (פסחים מא:) כי לאו הבא מכלל עשה עשה, ומעתה הרי קדם לו על הכניסה עשה, לזה הוסיף כאן לאו על הדבר ואמר **ואל יבא**:
@458 **בכל עת** אבל יש עת שיבא בה, והוא מה שאמר אחר כך בזאת יבא וגו' אחת בשנה. וטעם שהקדים **ואל יבא בכל עת** קודם מצות ביאתו אחת בשנה, לומר אם לא יבא בכל עת אז יזכה לבא בעת ההיא אשר אנכי מצוך ואם יבא בעת אחר לא יבא בכל עת אפילו בעת הרשיון. ודקדק לומר **בכל עת** דרשו רז''ל (בתו''כ) שבא לאסור אפילו ביום כיפור עצמו לא יכנום אלא לדברים הרשומים בכתב אמת להקטיר ולהזות, ולדרך זה הרווחנו דקדוק נכון אחר בתוספת וא''ו של **ואל**.
@458 **יבא**, לומר מלבד אזהרת ימות השנה עוד מוסיף לומר שאפילו ביום כיפור עצמו לא יבא, ואזהרה שאר ימים דרשו ז''ל (בתו''כ) מהפסוק עצמו שאמר אל הקדש ולא הספיק לומר מבית לפרוכת ומובן המקום אשר יצוה עליו. ואל יקשה בעיניך הקדמת הוא''ו, כי כן דרך הכתוב, ובמקומות אחרים הארכתי בהוכחת הדברים:
@458 **כי בענן אראה**. פירוש לצד שקדם הכתוב ואמר (ט כג) וירא כבוד ה' הודיע כי לא בחינה זו לבד היא הנמצאת בפנים אלא בחינה גדולה אור עליון כי גבוה מעל גבוה שומר, והוא אומרו **אראה על הכפורת**:
@459 **בזאת יבא אהרן**. טעם שהזכיר אהרן ולא סמך על זכרונו בתחלת הענין, לצד שמה שקדם במצוה לא היה אלא לאהרן לבדו שלא יכנס ולא ימות, ואין מצוה זו נוגעת לזולתו, ומכאן ואילך לא לאהרן לבד באה המצוה אלא גם לכל ישראל כי הוא צורך ישראל לכנס לבית קדשי קדשים לכפר עליהם אחת בשנה, ויצו האל לעמו לעשות החוקים האמורים שיכניסו אהרן בפר וגו' כתנת בד קודש וגו' ודרשו ז''ל (תו''כ כאן) משל קודש שהיא תרומת הלשכה, וכפי זה יתחייב הכתוב להזכיר שם המצוה בכינוי להם:
@460 **כתנת בד קודש**. עם אומרו קודש בכתונת ולא הספיק במה שגמר אומר בגדי קודש הם. אולי שחש הכתוב שידון אדם בדעתו שלא צוה ה' לעשות משל קודש אלא ג' הבגדים חוץ מן הכתונת, כי הכתונת הוא מלבוש המתחייב לכל אדם ללבוש ויהיה משלו ועל הג' הוא שאמר בגדי קודש שהם בגדים שיכולים להיות לצד כבוד משרתי עליון, לזה אמר **כתונת בד** וגו' שגם היא קודש. וכדי שלא תחשוב כי דוקא כתנת חקק ה' שתהיה של קודש לזה חזר ואמר **בגדי קודש הם** כולם יחד. עוד נראה לומר כי מתכוון לומר ב' דברים, הא' שהבד שיעשו ממנו הכתונת יהיה של קודש, והוא הדין לשאר בגדים, והודיע הכתוב המשפט במזדמן ראשון, וענין ב' הוא שגם מעשה הבגדים יהיה של קודש, והוא מה שגמר אומר **בגדי קודש הם**:
@460 **עוד** נראה כי מתכוון באומרו **בגדי קודש הם**, לבל יראה הדבר שהוא חוץ מהמוס' כי עבד מלך שהוא הכהן אשר פארו ה' וכבדו במלבושי כבוד דכתיב (תצוה כח ב) לכבוד ולתפארת ובעת אשר יתעלה לשירות גדול כזה יאמר אליו הורד עדיך מעליך, לזה אמר **בגדי קודש הם** פירוש בגדים הראוים לקודש הם ולא אחרים, והטעם כי הבגדים המפוארים ההם יש בהם דברים בגו כמאמרם ז''ל (ויק''ר פכ''א ר''ה כו) אין קטיגור נעשה סניגור. או ירמוז טעם (משלי כה) אל תתהדר לפני מלך אדונינו ב''ה קדוש ונורא שמו, והוא אומרו **בגדי קודש הם** פירוש שבהם ראוי להשתמש בקודש קדשים אשר חונה שם האלהים. ורז''ל אמרו קודש ילבש שיהיו של קודש, פירוש כל הד' נלמדים מכתונת שיהיו של קודש וחזר לומר **בגדי קודש הם** דרשו ז''ל (תו''כ) שבא ללמד על כל בגדי כהונה שיהיו של קודש, ואלו ואלו דברי אלהים חיים:
@463 **ולקח את שני השעירים וגו'**. פרשה זו צריכה למודעי כי למה יצוה ה' דבר כזה, ואם היא מהמצות אשר לא עשה ה' בהם טעם היה לו לומר חוקה ומה גם תגדל הקושיא לדבריהם ז''ל (רע''מ אחרי סג. זהר ח''ג קא) כי עזאזל היא בחינת צד הרע הנה כמעט ח''ו שירמה הדבר לעכו''ם, ומה גם שמצוה ה' (יומא פו.) להשוות שעיר של שם לשעיר זה של דבר אחר הדברים מבהילים:
@463 **ונראה** לומר על פי הקדמות שהודיענו רז''ל וזה יצא ראשונה תנן במשנת חסידים (אבות פ''ד) העושה מצוה אחת קונה לו סניגור אחד והעובר עבירה אחת קונה לו קטיגור אחד ע''כ. ומפורשים הדברים באר היטב על פי דברי הזוהר הקדוש (ח''ב עו, ח''ג קכב והע''ז) ובהשכלה מושכל עליון על פי האריז''ל לבאי בהיכלי מלך כי מהעבירה עצמה יולד דבר רע שהוא עצמו העון שעשה ובידו נמסר עושהו כאומרו תיסרך רעתך (ירמי' ב) ותמוגנו ביד עונינו, (ישעי' סד) ולזה כמשמחל ה' לדוד הודיעו שאבד הכח הרע שנולד מהמעשה הבלתי הגון כאומרו (שמואל ב יב) גם ה' העביר חטאתך לא תמות, הכוונה בזה כיון שהחטא שעושה האדם נברא ממנו הנפרע מעושהו ממילא באבוד המשחית אין משחית, וזה שאמר לו ה' שאחר שהעביר חטאתו לא ימות כי אין ממית, מעתה כיון שעל ידי המעשים נוצרים דברים הרעים המזיקים והמצערים את האדם צוה ה' המעדיף טובו עלינו ואמר כי כל שעושה דבר בלתי הגון בלא ידיעה מחטאות האדם יביא קרבן, וצוה שיסמוך עליו בעל הקרבן, והטעם כי בזה יורקו החיצונים ההם שנתהוו ממעשיו הרעים על הקרבן ההוא, ופעולה זו הודיע ה' שתעשה בסגולת הבאת האדם קרבנו לבית אלהינו וסומך עליו שם יעשה הדבר בכח השלם של אלהי הרוחות לכל בשר, וזה הוא טעם שצוה ה' הסמיכה בחטאות, והנה כל המעשה אשר יעשה בחטאת זבח והקטרה יפעיל בבחינת ההיא הנמשכת מהאדם בקרבן ההוא על ידי סמיכתו כנזכר, ובזה היא נעקרת בחינת הרע. וכבר ידעת כי אין חטאת באה אלא על החטאות שהוא הדבר שעושה האדם בשוגג משום דלא נפיש זוהמיה מה שאין כן על עון שעושה האדם במזיד דנפיש זוהמיה אין מביאין קרבן, וזה אמר (משלי כא) זבח רשעים תועבה כי יתעבהו ה' ב''ה להקריב על מזבחו תיעוב כזה שאין לך מיאוס בעולם כמיאוס וזיהום העון רחמנא ליצלן:
@463 **ולפי** הקדמה זו יתבאר הענין על נכון, בהקדים מה שכתבו רז''ל בתורת כהנים וזה לשונם וכפר על הקדש מטומאת בני ישראל ומפשעיהם וגו' על זדון טומאת מקדש וקדשיו שעיר הנעשה בפנים ויום כיפור מכפר ועל שאר עבירות שבתורה הקלות והחמורות הזדונות והשגגות הודע ולא הודע עשה ולא תעשה כריתות ומיתות בית דין שעיר המשתלח מכפר עכ''ל. ובש''ס וזה לשונם ושעיר של עזאזל נושא עליו כל הזדונות קלות וחמורות ושגגות וכו', וגם הכהנים כפרתן בשעיר המשתלח כאמרם ז''ל במסכת זבחים פרק א' (מנחות צב. שבועות יג:) וזה לשונם ר' יהודה אומר גם הכהנים מתכפרין בשעיר המשתלח. ואחר שהודיענו ה' את כל זאת הנה שלך לפניך טעם מספיק כי הב' שעירים נושאים כל זוהמי תחלואי הנפש. השעיר שנושא עליו זדון טומאת מקדש וקדשיו קבלו ה' ולא תעבו, אבל שעיר הנושא זוהמות כל העבירות קלות וחמורות צוה ה' שיאבדם ויכלם חוץ ממקום הקודש, וצוה שיסמוך אהרן עליו את ידיו שהוא שלוחם של ישראל וכל אשר עושים שם הוא היה עושה ששלוחו של אדם כמותו, ואמר ונתן אותם על ראש השעיר החי ביאר הכתוב היטב הדבר שבסמיכתו הוא נותן כל הטומאות המזוהמות ההם על ראשו. ואמר ונשא השעיר, מודיע כי ימצא בו בחינת המקבל לישא את הרע ההוא אל ארץ וגו':
@463 **ולהבין** הענין משל למלך שבקר בגדי בניו וראה בהם בגדים נקיים וכתם בו משפשפו בידו ונותנו לבנו, וכשראה בגד מלוכלך הרבה נותנו לעבד אחד מעבדיו אשר לא ימאס הדבר המאוס, כן הדבר הזה המלך הוא מלכנו יתרומם שמו כשמביא לפניו קרבן אם הוא בפרט וטהרת כתם כל שהוא שהם כתמי השגגה או פרט אחד של טומאת מקדש וקדשיו כנזכר לא יתועב הקרבן אליו, אבל כל הזוהמה של כל העבירות שעשו ישראל קלות וחמורות הוא מיאוס גדול ואמר שיוליכוהו לעבד אחד מהרחוקים מהמלוכה לצד היותו מהפחותים וקלי הערך והוא ישבר ויאבד וימחק אותם ואין זה אלא כנותן לו שירות מבוזה לעשות ואף על פי כן למעלה הוא לו שחשבו האדון לעשות לו דבר ממה שהיה לפני אל בבית המקדש, ונעשה השעיר ההוא בהשואה עם השעיר המתקרב לפני אל. וטעם שצוה ה' עשות ככה ולא אמר שיקחו שעיר מהשוק וישלחוהו לעזאזל אחר שהתודה עליו, הוא לצד כי מן הנמנע שיתקבצו כל הטומאות שעשו ישראל במעשיהם הרעים ויבואו על ראש השעיר כי אם בהביאו השעיר לפני ה' ואחר שהובא לפני ה', מאז מוכח כי הוא זה השעיר שישא כל התיעוב וילך לו אל ארץ גזרה, לזה צוה להגריל והוא הבוחר יבחר את השעיר אשר יבחר בתבונתו יתברך בבעלי חיים, ומה גם למה שאמרו המקובלים כי כמה נפשות וניצוצות בבעלי חיים בלתי מדבר ומי ידע בלתי יתברך שמו. גם יש סוד בגורל (זהר ג' ק''א) והבן:
@466 **יעמד חי**. צריך לדעת הכוונה ורז''ל (יומא מ תו''כ) דרשו הרבה דרושים. ולדרכנו יתפרש על נכון שנתכוון באומרו יעמד חי שלא יתודה עליו תיכף ומיד כשיעלה עליו הגורל אלא יניחהו חי, פירוש לצד כי בחינת הרע נקראת מת ועל שמה יקרא הגוף בלא נשמה מת להיות ששולטת בו בחינת הטומאה הנקראת מת, והשעיר של עזאזל כשמתודה הכהן עליו ונותן עליו כל העונות והפשעים וכו' הנה הוא מת כלול מכל מיני מיתות, וצוה האדון שלא יעשהו מת אלא יעמד חי, ולזה תמצא שאומר עוד אחר כך וסמך אהרן וגו' **על ראש השעיר החי והתודה** וגו' **ונשא השעיר עליו**, כי מתחלה קודם שהתודה קראו חי ואחר כך אמר השעיר ולא הזכיר החי לומר שאחר שהתודה עליו אינו חי שכבר כחות של מיתה ירדו עליו, ותמצא שצוה ה' שהמשלחו טמא ויכבס בגדיו ורחץ בשרו במים כדין טמא מת:
@482 **והמשלח וגו' לעזאזל**. צריך לדעת מה הוא עזאזל ורז''ל (יומא סז:) פירשו עז וקשה. ויש בזה הרבה דרשות על כל פנים אין הדעת מתישבת. ויאורו עיני בדברי אנשי אמת שונין בש''ע נהורים של תורה שאמרו (זוהר ח''ב קנז.) כי המדבר החרוב הוא מקום ס''מ הרשע, וכפי זה בחינת זו תקרא מדבר, ותקרא עזאזל, ותקרא עוזא ועזאל, שאמרו ז''ל שלהם ירמוז שם זה, ואולי כי התיבה תגיד זה על זה הדרך עז אזל פירוש מקום של אותם שאזל ואסף עז פארם. או על זה הדרך עזא ז''ל פירוש מקום של כח הזל ההוא לשון זילות ופחיתו' כי ס''מ הוא למטה במדרגה מכל משרתי עליון:
@485 **והיתה לכם וגו'**. טעם אומרו **לכם**, לצד שבתחילת הדבור אמר אליו ה' דבר אל אהרן ועכשיו בא לצוות את ישראל כמו שגמר אומר האזרח והגר לזה הוצרך לומר **לכם**, לבל תטעה לומר כי מצות הכהנים ביום כיפור הוא דיבור ראשון שצוה ה' בתחילת הפרשה לבד, ומצות ישראל היא העינוי שכן רשם בדת ה', גם השכל יסכים לזה שהכהנים פטורים מהעינוי. או הכהן הגדול מיהא במקום עינויו היא עבודתו, וגם משה תבא הסברא לדון עליו כי אינו צריך עינוי, ומה גם לאשר קדם לנו כי נזדכך גופו ודמי לבר אלהין מלאך ד' אין צורך בעינוי, אשר על כן צוה ה' ואמר **והיתה לכם** פירוש מדבר עם משה ואהרן שגם הם בכלל העינוי. וכדי שלא תחשוב דדוקא למשה ואהרן יצוה ה' ולא לכל ישראל תלמוד לומר **האז רח והגר**, ובסמוך יתבאר באופן אחר:
@485 **לחקת עולם**. טעם אומרו **עולם**, לצד שתבא הסברא שלא בא העינוי אלא לכפר עון ומעתה כל שאין רישומו של עון במציאות בישראל אין חיוב בעינוי לזה אמר **חקת עולם**, ופנימיות הדבר הוא חוקה של עולם הבא, והוא סוד נכמם:
@485 **תענו את נפשותיכם**. פירוש עינוי הכולל לנפש בהשואה ואיזה זה מניעת המזון, ואם אתה אומר שיענה עצמו במלאכה ישתנה הדבר בב' דברים, הא' שמתענה ביותר החלק ממנו הטורח באותה מלאכה ואם כן אין עינוי הנפש בהשואה והתורה אמרה תענו את נפשותיכם, הב' כי בסדר זה יקרא עינוי הגוף כי הבשר החי מתיגע והתורה אמרה נפשותיכם ומעתה תם לריק כחם של הקראים:
@485 **האזרח והגר**. בתורת כהנים אמרו וזה לשונם האזרח, אזרח זה אזרח, האזרח לרבות נשי אזרח, גר זה הגר, הגר לרבות נשי הגר, בתוככם לרבות נשים ועבדים ע''כ. ועדיין צריכין אנו למודעי למה הוצרך לזכרון אזרח, ואם בשביל ריבוי ה''א המרבה נשים, זה טעות כי יש לאלוה מילין לדבר באופן שירבה הצריכין להתרבות מבלי תוספות אפילו אות אחת ללא צורך. ויתבאר הענין על פי מה שאמרו במסכת סוכה (כח:) וזה לשונם אמר מר האזרח לרבות הנשים לעינוי יום כיפור אמר רבא מדרבי יהודה אמר רב נפקא דאמר רבי יהודה אמר רב השוה הכתוב אשה לאיש לכל עונשין שבתורה ומתרץ לא נצרכה אלא לתוספת עינוי סלקא דעתך אמינא הואיל ומיעט רחמנא לתוספת עינוי מעונש ואזהרה לא יתחייבו נשים קמ''ל ע''כ, ועל פי הדברים האלה יש טעם בדבר שהוצרך הכתוב להזכיר אזרח, לצד שהרבוי ה''א על התוספת עינוי, לזה נתחכם ה' וזכר שניהם יחד המתרבה ורשימת דבר שבו מתרבה, והוא אומרו **האזרח** פירוש אזרח זה אזרח שחייב גם בתוספת עינוי כרשום במקום אחר ודומה לו הוא המתרבה בתיבת ה''א ואין חילוק ביניהם. ואחר שהוכרח לומר האזרח לטעם האמור חש שיטעה הטועה לומר שאומרו האזרח הוא למעט הגר שאינו בגדר זה של מצות יום כיפור תלמוד לומר **הגר**, ואם היה אומר גר לבד בלא ה''א היה לבעל הדין לחלק חילוק נכון כי נשי הגר לא שהרי הכתוב חלק בין ישראל לגר שבישראל ריבה הנשים ובגרים לא ריבה, לזה הוצרך לומר הגר לרבות נשי הגר. עוד נראה ליישב טעם הכתוב שהוצרך לפרט כל הפרטים לצד שהוצרך לפרט הכהנים כמו שפירשנו בתיבת לכם מעתה חל עליו לפרט גם האזרחים לבל יבא הטעות כי לכהנים לבדם יצו ה', ואחר שכן חל עליו לפרט כל הנרמזים בפרשה:
@490 **והיתה זאת לכם וגו'**. מקרא זה חוזר אל הכהנים לקיים לדורות מצוה האמורה בתחילת הפרשה שהיא עבודת כהן גדול, לבל יחשוב שלא נאמרה אלא לשעה תלמוד לומר **זאת לכם לחוקת עולם**, **לכפר על בני ישראל** כאן גילה ה' סודו כי על הכהנים ידבר כי הם המכפרים. עוד נתכוון בזה לבל יאמר אדם שלא צוה ה' לבל יכנם בבגדי זהב אלא בעת ההיא פעם ראשונה שעדיין לא נתכפר רושם עון עגל זהב אבל מפעם ראשונה ואילך כבר נמחה ונמחק רישומו ובא יבא אהרן בבגדי כבוד אל הקודש פנימה תלמוד לומר **והיתה זאת לכם לחוקת עולם** בלא שינוי, וגמר אומר **לכפר על בני ישראל**, אולי שנתכוון לתת טעם על הדבר לומר שהגם שבבחינת אהרן לא נשאר רושם מהעגל כיון שבערך ישראל לשמצה בקמיהם לא נמחק רושם העגל כל עיקר, ומעתה מתעגל הדבר גם על אהרן:
@490 **ויעש כאשר צוה ה' וגו'**. רז''ל אמרו (תו''כ) כי הכתוב יכוין להגיד שבחו של אהרן שלא עשה לגדולה ולהתנשא אלא עשה הכל לקיים מצות ה'. ונראה כי גם שבחו של משה יגיד שהרי ה' לא דבר עם אהרן אלא עם משה, והתורה מעידה שלא נשתנה הדבור לצד אמצעיות האמצעי, הא למדת שהדברים הנאמרים מפי משה לא נולד בהם השתנות אפי' בחלק מס' מחוט השערה, וזה בנין אב לתורתינו הקדושה שכולה היא מוצא פי ה' יחיה האדם חיי עולם בהגיגו בנועם עליון:
@493 **איש איש וגו' אשר ישחט**. טעם כפל איש איש. בזבחים (קח.) דרשו אליבא דרבי שמעון לרבות השוחט להדיוט שחייב וכאילו אמר איש לאיש, ולא דרשו לרבות שנים ששחטו משום שאמר הכתוב לאיש ההוא ונכרת האיש ההוא, ודרשו תיבת ההוא אחת למעוטי מוטעה ואנום ושוגג, ואחד למעט שנים ששחטו על זה הדרך ההוא ולא הם וקשה שבתורת כהנים דרשו למעט שנים ששחטו מדכתיב דם שפך ולא מתיבת ההוא. ויש לומר כי להיות שיש ב' מיעוטים ההוא ושפך ודרשו בתורת כהנים מיעוט אחד לשוגג ואנוס ומוטעה ומיעוט א' למעט שנים ששחטו אינו מקפיד הש''ס להמציא מיעוט שני' ששחטו מושפך או מההוא, ועיין בפסוק שאחר זה:
@493 **אשר ישחט**. בתורת כהנים אמרו וזה לשונם אין לי אלא וכו' מנין לשוחט עוף תלמוד לומר או אשר ישחט, והלא דין הוא ומה שחיטה וכו' מליקה וכו' אינו דין וכו' תלמוד לומר אשר ישחט על השחיטה הוא חייב ואינו חייב על המליקה ע''כ. משמע כי מתיבת או מרבה שחיטת עוף ומאשר ישחט ממעט המליקה שהיתה באה בקל וחומר. וקשה מברייתא שהביא במסכת זבחים (קז) מוכח כי רבי ישמעאל דורש מאשר ישחט לרבות שחיטה לעוף וממה שאמר הכתוב זה הדבר מיעט המליקה שהיתה בא בקל וחומר. וגם לרבי עקיבא שחולק שם עם רבי ישמעאל דורש ריבוי שחיטת העוף מדם יחשב ומיעוט המליקה מאשר ישחט כדמוכח מהש''ס שם, ואם כן ברייתא של תורת כהנים לא רבי עקיבא ולא רבי ישמעאל. והנה בהכרח לומר כי ברייתא של תורת כהנים אינה כר' ישמעאל ממה שדרש שם זה הדבר לגזירה שוה מה זה הדבר וכו' אל ראשי המטות וכו' אם כן בהכרח שלא כרבי ישמעאל, גם ממה שלא דרש בתורת כהנים יתור דם יחשב לדרשת רבי ישמעאל לרבות הזורק אם כן מוכח שדורשה כרבי עקיבא, גם ממה שדרשו בפ' י' או זבח לרבות הדם כדברי רבי עקיבא בברייתא שהביא בש''ם דזבחים, הרי זה מראה באצבע כי דרשת תנא דתורת כהנים הוא כדרכו של רבי עקיבא, ומעתה תהיה דרשת שחיטת עוף מדם יחשב ומיעוט מליקה מאשר ישחט ולמה דורש תנא דתורת כהנים ב' הדרשות מאו אשר ישחט, ועוד לתנא דתורת כהנים שדורש ב' הדרשות מאו אשר ישחט דם יחשב שאמר הכתוב למה לי:
@493 **וראיתי** להרמב''ם ז''ל שכתב בפרק י''ח מהלכות מעשה הקרבנות וזה לשונו שנים שאחזו בסכין ושחטו פטורים שנאמר אשר ישחט או אשר ישחט אחד ולא שנים ע''כ. וקשה להרמב''ם ז''ל למה עשה לימוד חדש ולא רשם הלימוד שהוזכר בברייתא ובתלמוד. ועוד קשה להרמב''ם ז''ל והרי פסוק אשר ישחט אשר ישחט דרשוה למשפט העוף בין לתנא דתורת כהנים בין לרבי ישמעאל בין לרבי עקיבא שהובא דבריהם בזבחים שכתבנו למעלה אשר ישחט אצטריך ללמד על העוף למר לרבות שחייב על שחיטתו ולמר למעט המליקה, ודין זה פסקו רמב''ם בסוף פרק י''ט מהלכות מעשה הקרבנות ועוד קשה למה שכתב הרמב''ם חיוב לשוחט לאיש מפסוק דם יחשב לאיש ההוא דם שפך, שכתב וזה לשונו אף על פי שלא נתכוון לשחוט קדשים אלו לה' הרי זה חייב שנאמר דם יחשב וגו' דם שפך אף על פי שזה הדם במחשבתו כדם הנשפך לא כקרבן הרי זה חייב ע''כ, והרי הש''ס דורש חיוב שוחט לאיש מאמרו איש איש ועוד דם שפך דרשו בתורת כהנים למעט ב' ששחטו או למעט אנוס שוגג מוטעה כמו שכתבנו למעלה ומה מקום לדרוש ממנה שוחט לאיש. והנה דרשה זו אמרוה בזבחים דף ק''ח ע''ב אליבא דרבי יוסי שחולק על רבי שמעון בדרשת איש איש, ולזה יש לומר שבחר הרמב''ם להביא הראיה מיתור דם שפך שהיא יותר חזקה מדרשת איש איש שאינה דרשה חזקה. והראיה ממה שאמרו במסכת מציעא (לא.) בפסוק העבט תעביטנו שסובר רבי שמעון דברה תורה כלשון בני אדם, וכתבו התוספת שם כי במקום שיש איזה הוכחה הפך דרשה הנשמעת מכפל הדברים אנו דורשים כפל התיבה ואין אנו אומרים דברה תורה כלשון בני אדם וכשיש התנגדות לדרשת הכפל אנו אומרים דברה תורה כלשון בני אדם, מעתה אין דרשת כפל איש איש חזקה כדרשת דם שפך שהביא הש''ס אליבא דרבי יוסי, והגם דהש''ם לא קאמר לה אלא אליבא דרבי יוסי, אף על פי כן ממנה נקח לרבי שמעון כי אין הכרח לעשות מחלוקת ביניהם בזה, והגם דהש''ס קאמר לסברת רבי שמעון שדורש שוחט לאיש מאיש איש, זה היה קודם שידע דרשת דם יחשב וגו' דם שפך מה שאין כן אחר דרשה זו הוא דבר השוה לכולם, ולזה כתב הרמב''ם מדרשת דם שפך, אבל קושיתינו הראשונה לדברי רמב''ם במקומה עומדת:
@493 **ונראה** לומר דסובר רמב''ם כיון שאנו רואים כל כך שינויים בין ברייתא של תורת כהנים וברייתא שהביא הש''ס בזבחים ובין דברי הש''ס גם כן כמו שכתבנו למעלה, אם כן מוכיחים הדברים שאין להקפיד על שינוי מקום דרשות אלו, ולזה למה שמוכיח רמב''ם מפסוק דם שפך שוחט לאיש דחייב אם כן אין לנו מנין לדרוש מיעוט שנים לזה חפש אחר דרשות יתור אשר ישחט שהיא מיותרת ואין אנו דורשים שחיטת עוף אלא מתיבת או, וכמו שדרשו בתורת כהנים שמרבה שחיטה לעוף מאומרו תיבת או לרבות ולפי זה דרשינן מיעוט מליקה בעוף מאומרו זה הדבר למעט מליקה בעוף וכדברי רבי ישמעאל שכתבנו למעלה שדורש מיעוט מליקת עוף מזה הדבר. ולא יקשה לך ממה דקיימא לן (ערובין מו:) הלכה כרבי עקיבא מחברו, כי אין בזה הפך רבי עקיבא בענין הלכה:
@495 **זבחי שלמים לה' וגו'**. היה צריך לומר וזבחו אותם זבחי וכו', ואולי שנתכוון האדון להראות חיבת הקודש אשר חבב עמו, ואמר **כי זבחי שלמים** הם קרבנות המשתתפים בשולחן אחד יחד בנים ואביהם, והוא אומרו **שלמים לה' אותם**, וחוזרת תיבת אותם לבני ישראל הזובחים האמורים בתחלת הכתוב לא לנזבחים.
@495 ועל דבר זה לבד תתנתק הנפש מנרתקה ותקום לעבודת האל במסירת נפש מבלי הרגש להפלגת עריבות הנרגש בבחינת אהבתו יתברך בנפש המרגשת בטעימת נועם חיבתו, וכל זה קטן הוא להמתחייב לנו עשות לערך המוקדם ממנו יתברך בבחינת שעשוע חיבובינו ורוממות אשר רומם עם קדושו:
@498 **ואליהם תאמר וגו'**. במסכת זבחים (קז.) תניא ר' ישמעאל אומר לעירוב פרשיות לומר שאף שחוטי חוץ שהעלה בחוץ הגם שאין ראויים לפנים כגון השוחט בפנים ומעלה בחוץ דתניא במשנה תחלת פרק י''ג דזבחים. וליתן כל האמור של זה בזה זולת דברים שריבה הכתוב באחד מהם ומיעט בחבירו. ועיין בדברי רש''י בזבחים:
@498 **איש איש וגו'**. עיין בפסוק שלפני זה:
@498 **מבית ישראל**. הוצרך לומר מבית ישראל ולא הספיק במאמר ואליהם שממנו מובן שחוזר להאמורים למעלה מהענין. לצד שאמר איש איש לומר שנים ששחטו כמו שכתבתי בסמוך, וחש הכתוב שיבא הדורש וידרוש לרבות הגוים כמו שדורשים (מנחות עג) באיש איש האמור בנדרים ונדבות (אמור כב יח) שהוא לרבות גוים, לזה הוצרך לומר מבית וגו' דוקא ישראל ולא אומות וממילא נתחייב לדרוש באיש איש כל מה שדרשו ז''ל. ואחר שהוצרך לומר מבית ישראל חש הכתוב לומר שמיעט הכתוב הגרים תלמוד לומר ומן הגר, והוצרך לרבות כל הריבוים דזולת זה יאמר האומר שלא ריבה אלא מה שהזכיר בכתוב. וגם לדעת ר' יוסי שסובר דברה תורה כלשון בני אדם. אולי שלא אמר כן אלא לצד שיש לו מניעת הדרשה בו לצד מיעוט ההוא. והגם שהקשה הש''ס לר''י דכיון שאינו דורש איש איש שבפרשה ב' גם איש איש שבפרשה א' לא ידרוש, אין הכי נמי אם לא היה הש''ס מוצא דרשות דם שפך היה אומר שדורשה מאיש איש, שכל שאין נגדיות לדרשה לא אמרינן דברה תורה וכו', ועיין בדברי התוספת במציעא דף ל''א ד''ה דברה תורה כלשון בני אדם שאין סברא לומר דלית לתנא כמה דרשות שנדרשו בכפל, והגם שהתוספת פרטו הקושיא לרבי שמעון על כל זה ישנה לכל. ועיקר מחלוקת התנאים היא בסברא בדבר המתנגד לדרשה שכפי הסברא מטה לומר דברה תורה כלשון בני אדם ותמצא שגם רבי שמעון מצינו שאמר (ב''מ לא:) דברה תורה כלשון בני אדם ומצינו לו שדורש הכפל:
@500 **ואיש איש וגו' אשר יאכל וגו'**. טעם כפל איש איש, בתורת כהנים דרשו וזה לשונם ישראל אלו ישראל, גר אלו גרים, הגר לרבות נשי הגרים, בתוכם לרבות נשים ועבדים, אם כן למה נאמר איש איש אמר רבי אלעזר ברבי שמעון להביא ולד ישראל מן הגר ומן העבד ע''כ. צריך לדעת למה הוצרך הכתוב לפרט כל הפרטים, וכדרך שהקשו במסכת סוכה (כח) באותה ברייתא שאמרה האזרח לרבות הנשים וזה לשונם מדר' יהודה אמר רב נפקא דאמר ר' יהודה אמר רב השוה הכתוב אשה לאיש לכל עונשים שבתורה ותירץ שם שאיצטרכא לתוספת עינוי וכו' ע''כ. אם כן גם במה שלפנינו יש להקשות כן למה הוצרך לרבות הנשים וכו' בין נשי ישראל בין נשי הגר. עוד יש לנו לעמוד על כוונת דברי התנא מה הוא הולד ישראל הבא מן הגר שהוצרך הכתוב לרבות מאיש איש, אם הוא המיר כבודו מגירות והלך לחרפות, הרי הוא גוי ולמי בא הכתוב להודיע האיסור. ועוד התנא אומר בפירוש ולד ישראל משמע שביהדותו עומד, אם כן פשיטא שלא גרע מגר שאמר קרא בפירוש ולמה איצטריך איש איש, והרב בעל קרבן אהרן כתב שגרסינן בברייתא מן הגוי ומן העבד, וירצה ולד בת ישראל הבא מן ע''ג או עבד שאף על גב שאביו עכו''ם או עבד שלא הוזהרו על הדם וכו' מחויב אם אכל דם דגריר אחר אמיא וכו' דגוי ועבד הבא על בת ישראל הולד כשר כדאמרינן ביבמות (כג.) בנך הבא וכו' קרוי בנך וכו' ע''כ. וקשה לי כיון שהכתוב קראו לזה בן ישראל אם כן ישראל גמור הוא, ואם מדבר הכתוב בבן שלא רצה לעמוד ביהודת אמו אם כן פקו פליליה ולמי בא הכתוב להודיע תורת ה'. ואם לכופו על הדבר ממה נפשך אם ביד ישראל לכופו פשיטא שכופין אותו כדין כל איש ישראל שעובר על התורה ואם אין בידינו לכופו הרי אין ברשותינו, ואם כן קרא למאי אתא:
@500 **ונראה** לומר בהקדם לדעת טעם איסור זה, כפי מה שהאירו חכמים את עינינו בפנימיות התורה, כי כל נפשות עם בני ישראל הם ממדריגה שאין למעלה ממנה בסוד (דברים לב ט) חלק ה' עמו. גם אמרו שהגם שהם בעולם התחתון ורחוקים ממקום גבוה אף על פי כן ישנם דבוקים בחוט של חסד עד מקום שורשה בסוד אומרו (שם) יעקב חבל נחלתו, ונפש הבהמה היא ממדריגה התחתונה אשר יתיחם מקומה אל קליפת נוגה והנה באכול אדם מדם בהמה שהנפש יוצאה בו שעליו בא עונש כרת קונה נפש הבהמיית מקומה בנפש אדם. והדיענו הכתוב כאן כי האוכל דם ומכניס נפש הפחותה בנפשו יגעל אותו שורש העליון לבל יהיה עוד נדבק בו. והוא מאמר **ונתתי פני בנפש האוכלת את הדם והכרתי אותה מקרב עמה** פירוש שיכרות החוט הקשור בשרשו שהוא מקור כללות נפשות עם ה', והוא אומר מק **רב עמה**. עוד ידוע הוא כי הגם שבכללות עם ישראל שורש אחד אף על פי כן הם במדריגות זו למעלה מזו בסוד (קהלת ה) כי גבוה מעל גבוה וגו'. וכיון שכן תבא הסברא לומר לצד שהנפש בהמה זו לא טמאה היא שהרי היא בהמה טהורה הנאכלת לזה לא תעשה נפש הלזו פגם ודופי אלא דוקא בהדרגה הגדולה שבישראל, ועונש שיחד ה' לעבירה זו אינו אלא להאזרחים זכרים ולא נקבות, וכשירבה הכתוב איזה ריבוי אין לנו בו אלא חידוש הדרגה אחת עד שירבה קצת המדרגות, גם כלך לדרך אחר יש לומר שאין הפעולה הלז עושה כל כך רושם להצטרך לכורתה אלא נפש שהיא קלת הערך אבל נפש רמה אפשר שהגם שתעשה בו רושם אף על פי כן לא תעשה כל כך פעולה בה כדי שתצטרך לכרת. אשר ע''כ נתחכם אל נורא עליל' וריבה כל הריבוים ואמר כי קטן וגדול ישנו בהכרת באוכלו דם הנפש, ואמר ריבויים לכל ההדרגות קטן וגדול:
@500 **והנה** לפניך ההדרגות זו למעלה מזו, ראשון שבקדושה זכרי ישראל ב' נשיהם לצד שהאשה אינה במדריגת האיש, ג' גר הבא מישראל וגיורת, ד' גר הבא מגר וישראלית, ה' גיורת כיוצא בשני ההדרגות, ו' גר הבא מגר וגיורת, ז' גיורת הבא מגר וגיורת, ח' גר עצמו, וכל אלו ההדרגות באו בכתוב, ראשון שבקדושה ישראל הזכירם בפירוש והוא מאמר תנא של תורת כהנים ישראל אלו ישראל. והזכיר הגרים ב' פעמים, וב' ריבויים עמהם הגר הגר. ותמצא שבמסכת סוכה (כח) דרשו ה' של האזרח לרבות נשיהם, נמצאת אומר כי ה''א של הגר הגר ריבויים הם, הרי לפניך ד' ריבויים בגרים והם כנגד ב' הדרגות שבגרים הא' הוא הגר שנולד מגר וגיורת והב' הגר עצמו שנתגייר, ושני הריבויים כנגד נשיהם שבהדרגתם, ואולי שלזה דקדק ואמר תנא דתורת כהנים הגר אלו הגרים ולא אמר זה גר שנתכוון לב' הדרגות דגרים כאמור, וא' הגר לרבות נשי הגרים פירוש מריבויי ה''א נתרבו נשיהם, ואמר **בתוכם** לרבות נשים ועבדים כמאמר התנא פירוש נשים אזרחיות ועבדים שדינם שוה לנשים, ולא תקשה למה הוצרך לרבות' והלא קל וחומר מגרים, ואין לומר שהייתי אומר כי לצד שהם גדולים מערך גר יצטרך לומר כי גם בהם יפעיל הכרת כמו שאמרנו בטעם זכרון ישראל, כי אחר שהוזכרו זכרי ישראל מכל שכן הנשים הנה אם לא היה ריבוי בתוכם שריבה בה קרא נשי ישראל לא היינו מרבים מה' של הגר ב' גיורים כמו שאמרנו, הרי לפניננו ו' ריבויים, ואמר **איש איש** ב' ריבויים אחרים ודרש אותם תנא בתורת כהנים ואמר להביא ולד ישראל הבא מן הגר ומן העבד פירוש ולד ישראל שיש בו זרע ישראל ובא גם כן מן הגר והוא אומרו מן הגר, והכונ' היא שאביו ישראל ואמו גיורת או אביו גר ואמו ישראלית, ושני הדרגות אלו נדרשים מכפל **איש איש**:
@500 **ולא** תקשה למה הוצרך הכתוב לרבות ההדגרות אלו אחרי שכבר ריבה גר גמור כמו שאמרנו, כי אם לא היה ריבוי איש היינו מפרשים דגרים האמורים בבאו מישראל וגיורת או מגר וישראלית. ומעתה הקדים הכתוב הדרגה החשובים שבגרים שיש בהן חלק ישראל ואחר כך אמר הגר הגר שכולן גרים, הרי לפניך ח' ריבויים. ואם תאמר גיורת הבאה מישראל וגר מנין, יש לומר שלאחר שנתרבה אפילו גר עצמו שנתגייר פשיטא שאין להפחית ממנו גיורת הבאה מישראל וגר הגם שהיא נקבה, ולדרך זה תתהלך בכל מקום שירבה ריבויים כאלו:
@500 **בנפש וגו'**. בתורת כהנים דרשו ולא בציבור ע''כ. הטעם כי אין כח בעון זה להכרית ציבור. ועיין במה שפירשתי למעלה:
@500 **מקרב עמה**. בתורת כהנים דרשו ועמה בשלם ע''כ, ואין ידוע הכוונה בזה, ממה נפשך אם חייבים מדין ערב למה יהיו פטורים כאן, ואם אינו מדבר במי שחייב מדין ערב כגון שלא ידעו או נאנסו אין צריך לומר. ונראה כי יכוון לומר כי כריתת הענף הרע מהאילן משביחו כידוע, ולזה אמר מקרב עמה פירוש כדי שלא יזיק ענף הרע לנצר מטעיו יתברך יכריתהו וישאר עמה בשלם:
@501 **כי נפש הבשר וגו'**. צריך לדעת נתינה טעם למה חוזר זה, ולפי מה שפירשתי למעלה הן הן הדברים שכתבנו שנותן הטעם למה תכרת נפש האוכלת, לצד שיש בדם הנפש והוא נותן בתוכו נפש הבהמית. אלא שעדיין יש לנו לחקור למה אמר נפש הבשר ולא אמר כי הנפש בדם. ונראה שנתחכם ה' להשיב לשואל למה לא אסר גם הבשר כי גם בו היה חיות הבהמה וכשאדם אוכלו יגרום הפגם בנפשו, לזה אמר וכי נפש הבהמי היתה בבשר, לא כן הוא, לא היתה אלא בדמו של בשר והדם הוא מחיה הבשר. ואין הנפש בבשר כל עיקר כאומרו **נפש הבשר בדם** היא הנפש ולא בבשר. ותכונה זו לא הכינה ה' בתכונת אדם כי האדם התפשטות חיונותו היא גם בבשר וגם בעצמות, ונקרא בדבריהם הבלה דגרמי שנשאר אחר כמה שנים בעצמות, ולזה אינם נרקבים הצדיקים, ויש רשעים שנמשלו כבהמות והן הנה שאינם עומדים בתחיית המתים לצד שיבשו עצמותם ונרקבו וכלתה הנפש והלכה לה כרוח הבהמה:
@501 **ואני נתתיו וגו'**. פירוש ותדע שהדם הוא הנפש שהרי אני נתתיו לכם וגו' לכפר על נפשותיכם נפש תחת נפש הרי כי הדם הוא הנפש. עוד יכוון הכתוב להזהיר על נפש הבהמה לבל המיתה, כי לא נתן ה' דם הבהמות לנו אלא לכפר על נפשותינו, והוא אומרו **נתתיו לכם על המזבח** לשלול זולת סיבה זו שאינו לנו במתנה לעשות כל אשר נחפוץ עשות בו. ותמצא (סנהדרין ב.) שדין הריגת בהמה צריך שיהיה על פי בית דין של כ''ג כמשפט אדם שהשוה הכתוב משפטם למשפט אדם, ולא הותרה בהמה לשחוט אלא לצרכי בשרה כי תאוה נפש אדם לאכול בשר שכן גמר קונה עולמו והקנה לנו דכתיב (ראה יב כ) כי תאוה נפשך לאכול בשר בכל אות וגו':
@503 **אשר יצוד ציד וגו'**. צריך לדעת לאיזה ענין הוצרך הכתוב לכתוב כל זה שלא היה לו לומר אלא איש אשר ישחט חיה או וגו' או אשר ישפוך דם וגו'. עוד אם גזירת הדברים היא מצות הכיסוי היה לו לומר יכסהו בעפר כי אומרו וכסהו משמע שקדמה מצוה אחרת. ונראה כי באמרו **אשר יצוד** נתכוון לאסור צידת מין טמא לכתחלה, הגם שהתירו הכתוב בהנאה, וכמו שהעליתי בספרי פר''ת סי' קי''ז כדעת רמב''ם (מ''א פ''ח) שאין התר' לצודם אלא אם מתכוון לצוד טהורים ונזדמנו עמהם טמאים, והוא מאמר הכתוב כאן **אשר יצוד** וגו' תנאי הוא הדבר שאין מתיר לו לצוד אלא **אשר יאכל** ולא אשר לא יאכל ואמר **וכסהו** לצד שקדם מצוה אחרת שלא לצוד שלא יאכל יוצדק לומר וכסהו בתוספת ו', ואמר **ושפך** וגו' פירוש שאסור לאכלו כדרך שאמר במקום אחר (דברים יב טז) לא תאכלנו על הארץ תשפכנו כמים, ולזה גמר אומר כאן ואמר **כי נפש כל בשר** וגומר **ואומר** וגו' הא למדת כי נתכוין במאמר **ושפך** לאסור אכילת דם חיה ועוף. נמצאת אומר ג' מצות נאמרו כאן, א' לא יצוד טמאים ליהנות מהם, ב' לא יאכל דם חיה ועוף, ג' מצות עשה לכסות דם חיה ועוף:
@503 **עוד** נראה שרמז באומרו **ושפך וכסהו** שאין צריך לכסות כל דמו אלא חלק בשפיכה וחלק בכיסוי (חולין פח.):
@504 **דמו בנפשו**. פירוש במקום נפשו. ובזה נתן טעם למה צריך לכסות דמו, כי לצד שדמו היא נפשו מהמוסר לנהוג בו כבוד זה כדרך שצוה ה' לקבור אדם מת משום כבודו, וטעם שלא אמר כדרך שאמר בבהמה נפשו בדמו. אולי שהבהמה יש לה נפש והיא נתונה בדם אבל חיה ועוף אין להם נפש כבהמה אלא הדם הוא במקום הנפש, ובזה אינם באים על המזבח לכפר כבהמה זולת תורים ובני יונה, וגם המה אין בדמם הזאה על המזבח אלא מיצוי כשמולק:
@504 **כי נפש כל בשר וגו'**. פירוש לא לצד שהדם מכפר על המזבח הוא שאסרתי הדם שאז תחלק בין דם בהמה לדם חיה ועוף אלא טעם האיסור הוא לצד כי נפש כל בשר וגו', ומעתה גם חיה ועוף בכלל:
@504 **כל אוכליו יכרת**. כבר כתבתי למעלה טעם הכרת. וטעם אומרו **אוכליו** לשון רבים ויכרת לשון יחיד, להעירך על פירושינו שהכרת הוא שיסתלק חיוני' המאיר בשורש נשמתו ונכרת השורש ההוא לזה אמר לשון יחיד. ואמר אוכליו לשון רבים, לצד שהנהנים מהאכילה רבים המה, כי חיוניות הנדבק בשורש עליון יש תחתיו הכנות כדי שיוכל עמוד ביחד עם הגוף, כי הגוף הוא חומר גשם וברא ה' בו כח המניע והוא הנפש שתכונתה היא נוטה על הגשם ויתאו למטעמותיו, ובראם ה' ב''ה בתכונה זו כדי שיתמזג עם הגוף והוא מוכן לבחינת הנשתוה לרוח, והרוח הוא מוכן לנשמה, והנשמה הוכנה להשרות שכינתו על הראויים, ומעתה כשאדם אוכל הדם הרי לפניך אוכלין מרובים, הגוף, הנפש, הרוח, הנשמה, ובבחינת העונש שהוא הכרת אין נכרת אלא חוט הנשמה הקשורה למעלה ובזה יבשו כל הענפים לזה אמר לשון רבים:
@504 **עוד** רצה על דרך מה שאז''ל (תו''כ לעיל ג') כי הציבור אינ' נכרתים בעון אכילת דם, לזה אמר **אוכליו** לשון רבים ויכרת לשון יחיד לומר שהגם שיאכלו רבים אין כרת אלא ליחיד ולא לציבור:
@504 **ונתתי** אל לבי לדעת מה טעם יצו ה' לכסות דם חיה ועוף ולא דם בהמה, בשלמא דם הנזרק על המזבח הוד ותפארת לו מדם חיה ועוף אבל דם שחיטת חולין אשר הוא נופל וגלוי עינים למה תגרע בהמה מחיה, ומה גם למה שמצינו שבחר לו יה קרבן מהבהמה ולא מחיה ועוף זולת תורים ובני יונה, והנה לפי מה שפירשנו שחיה דמה היא הנפש עצמה מה שאין כן הבהמה כי יש נפש מלבד הדם והיא מורכבת בדם ואין דמה עצמו נפשה, לזה לא צוה ה' לכסות הדם אלא הדם שהוא עצמו נפש מה שאין כן הבהמה שאין הדם עצמו נפש כמו של חיה ועוף, והגם שגם בדם בהמה יש נפש בו, על כל זה לא הדם עצמו נפש ואין כיסוי אלא למורגש ולא להיולי הגם שישנו והבן. וראיתי לתת לב משכיל מפני מה נשתנית בריית חיה מבהמה בבחינה זו:
@504 **ונראה** שהטעם הוא לפי מה שקדם לנו בהתבוננות מושכלות השפעות הקיום והעמדת כל יש, כי האל הבורא ב''ה הוא חיות הכל והכין ועשה פעולות כדי שכל הווה יגיענו ההסתפקות מן הצורך לקיומו, וחלק כל בריותיו לד' הדרגות והם אש רוח מים עפר, וכל אחת כלולה מהד'. וארבעה אלו תחלת הווייתה היא נעלמת מעיני כל בשר והיא רוחנית בתכלית הרוחניות והם ד' רגלי כסא כבודו יתברך ונשפעים מהם בכיוצא בהם ד' בריות אחרות נושאי הכסא פני אדם פני נשר פני אריה פני שור וכנגדם ד' מלאכים גבריאל רפאל מיכאל נוריאל אלו הכנה לאלו ומקבלין זה מזה ולעומתם יש למטה מקבלין בבעלי חיים אדם שור נשר אריה אדם מין אנושי שור מין בהמה אריה מין חיה נשר מין עוף וכנגדם בדוממים עפר מים אש רוח וכל א' כלול מארבעתם וגם בבחינת הנשמות שהם בריאה העליונה שבעליונות אשר ברא ה' מאורות עליונות חלק ה' ב''ה כמו כן ימצאון בחינות וחזר הדין שכל נושא ונושא כולל כל זה וכל מדרגה משפעת ונשפעת ממדריגת כסא הכבוד שהיא למעלה מחיות הקודש עד מדריגה הדומם. ומעתה אבוא לראות הנשפעים הנדמים מהד' בחינות הנגלים דוגמתם למעלה והנה יש לו בחינת שור בהמה טהורה הנשפעת מדמות פני שור אבל חיה ועוף לא מצינו בנדמים נשפעים למטה מהמושפעים מהקדושה כי אריה חיה טמאה נשר עוף טמא ויש לחקור זאת למה נמנע הנדמה מהתקבל בחינת הקדושה והטהרה כמו שקבל השור גם מנין נמשכה בחינת הטוהר לשאר חיות הטהורות אשר התירה תורה איל וצבי וגו' דע כי יש הדרגות שאין יכולת המקבל לקבל בתגבורת המשפיע בבחינת בסוד טעם עיני חכמי ישראל כידוע ליודעי דעת בהתבוננות הצודק בשכל ההבחן ולזה לצד כי אריה ונשר שלמטה באו בתגבורת לא יוכלו לסבול שיעור הנתכן והנשער אליהם בתכונת איכותם ולצד חסרון התקבל' השער' ההסתפקות מביחון הנרזב אשר בגן ה' כשיעור הצלחתם מהמקוה אליהם זו סיבה למרחקם אשר צוה ה' לאיש ישראל לבל יקרב אליהם כי איש ישראל הוצלח בנקוה אליו בסוד אומרו (דברים ד) הדבקים בה' ושיעור אשר הגיעו בבחינת אריה נשר כמוהו וכשיעורו נסתעף בקצת מהחיות והעופות ועשה בהם שיעור ההסתפקות והגם שלא בא איכותם אלא על ידי נשר כי הנשפע ראשון זה הוא סוד (איוב יד) מי יתן טהור מטמא וגו' וכל זה עשאו יתברך לסיבה הידועה סוד ה' ליראיו וכיון שכן אין תכונת הקדושה והטהרה המשתלשלת דבחינת הבהמה דומה לבחינת חיה ועוף כי בחינת שור יש דומה לו למעלה במקור הקדושה אשר ברא הבורא ותיכן בו הנפש מה שאין כן בחינת חיה ועוף לצד שנפסק דמות הנדמה למשפיע הנה הוא טמא לפנינו דכתיב (לעיל יא) את הנשר ואת וגו' תשקצו תש כחו ואין בו אלא החיוניות שהוא דם טוהר כאמרו דמו בנפשו וכמו שפירש דמו במקום נפשו זולת תורים ובני יונה שיודע אל עליון שגבר בהם החיונים וממוזגים הם בין הבהמה והעוף שמביאים מהם קרבן עולה וחטאת דוקא ויחיד דוקא ולא ציבור וצריך כיסוי כי עד גדר הבהמה לא בא כל זה כתבתי עם חפץ ד' והמשכיל ישכיל דבר אלהים חיים:
@505 **וכל נפש אשר תאכל נבילה**. אמר **וכל נפש**, לכלול כל המתרבים למעלה (פסוק י) ח' הדרגות כמו שפירשנו, והזכיר ב' הדרגות כלליות אזרח וגר, ודקדק לומר **באזרח ובגר**, פי' כל שנכלל באזרח וכל שנכלל בגר:
@508 **דבר ואמרת וגו' כמעשה וגו'**. צריך לדעת למה כפל לומר **דבר ואמרת** עוד מה חידש במאמר זה **אני ה' אלהיכם** וכי עד עתה לא ידעו זה. ועוד מה היא כוונתו במצות כמעשה וגו' אם אין ידוע מה המעשה שעליו תבא המצוה, וכמו כן מעשה ארץ כנען. ורז''ל אמרו (תו''כ) שהקיש מעשה מצרים למעשה כנען ולדבריהם ז''ל קשה למה כפל המצוה, ואם להשמיענו בא שמעשה ב' הרשעים שוה, מה צורך לתורה להודיענו דבר זה עוד צריך לדעת למה ציין ארץ מצרים באומרו **אשר ישבתם בה** וכי יש ארץ מצרים אחרת. עוד ציין **ארץ כנען** ואמר **אשר אני מביא** וגו' שנראה שיש אחרת ולא ידענו זולת זו, ולו יהיה שתהיה ארץ כנען אחרת כיון שאינה ידועה מנין יהיו מעשיה נודעים לצוות עליהם:
@508 **ונראה** כי לפי מה שהסמיך למצוה זו מצות העריות, גם ממה שאמר בסוף הפרשה (פסוק כד) אל תטמאו בכל אלה וגו' כי בכל אלה נטמאו הגוים הדברים מוכיחים ומגידים כי מעשה ארץ מצרים כמעשה ארץ כנען הוא מעשה עריות ובזה נבא לפרש הכתוב על נכון. הנה ידוע הוא כי כל מצות אשר צוה ה' לעם קדושו הם מצות שיכול האדם לעמוד בהם ויטה עצמו אל הרצון לעשותם, זולת מצות פרישת העריות הוא דבר שנפשו של אדם מחמדתן ואונסתו עליהם לעשותם, זולת בהתעצמות הרחקת ב' דברים מהאדם, והם מרחק הרגש ראות העין, ומרחק בחינת החושב, ואם ב' אלו לא יעשה אין אדם שליט ברוח זה לכלותה ממנו, כי כל שלא תהיה לו הרחקת הרגש הראות בדבר הגם שירחיק בחינת החושב לא ישלוט בעצמו לכלות ממנו הכרח החשק. וצא ולמד (קדושין פא.) ממעשה של ר''ע רבן של חסידים שהגם היותו מושלל מבחינת החושב נתנצח מבחינת הראות, גם ממעשה רבי מתיא ב''ח (ילקוט שמעוני פ' ויחי) שבחר לסמות עיניו למיחוש הכרחה אשר מהם תבא בדבר הרע הגם שהיה מושלל מבחינת החושב כאשר מעשיו מוכיחות. גם אם יושלל מבחינת הראות אם לא ירחיק בחינת החושב מחשבותיו יחייבו לבקש ולהתלהט אחר המעשה. וצא ולמד ממעשה שהובא בש''ס (ע''ז כב:) באותו גוי שקנה ירך בשר וחטט בו כדי וכו' ובעל וכו' ע''כ. וזהו יהיה תולדות החושב הכריחתו עשות מבלי בחינת הראות. נמצאת אומר שבא' מהב' תהיה מושללת מהאדם שליטה בעצמו בדבר זה ואין צריך לומר בהצמד ב' דברים ראות וחושב הן האדם חלוש כנגד תאותו, ואין צריך לומר אם ישלח ידו ואכל מעט מן הרע הזה הנה הוא מסור ביד תאותו. מעתה תחבולות האדם להעריך מלחמה נגד בחינה זו היא בשלילת ממנו ב' דברים ובזה תהיה נרכבת באדם תכונה לבל יתלהט אחר זה וישלוט הרצון בחפץ הטבעי והוא טעם אמרו ז''ל (ברכות לד:) במקום שבעלי תשובה עומדים אין צדיקים גמורין יכולין לעמוד, כי הצדיקים גמורים תכונת רצונם נוצחת החפץ מבלי צורך התעצמות מה שאין כן בעלי תשובה:
@508 **ובזה** נבא אל הביאור הנה האדון ה' צבאות נתחכם בצוותו מצוה זו ודבר נגד יצר הרע, שיאמר איך יכול אנוש טבעי למשול בתאותו אשר היא אנסתו דבר זה הוא מושלל מהדעת שיחייב ה' שמירתו לכל בהשואה אלא לאנשים אשר יכולין לעמוד ויש כח ברצונה לשלול החפץ בזה והם אותם שלא באו לידי מבחן הראות והחושב באלו וכדומה דבר הכתוב אבל במי שעברו בחינה הנזכר כפי הטבע אין אדם שליט ברוחו למנוע מעצמו חשק המכריחו, ועל זה נתכוון ה' בנועם דברי אלהים חיים ואמר **כמעשה ארץ מצרים אשר ישבתם** פירוש הגם שישבתם במקום שאנשיה בני זנונים ולא תמנע מכם בחינת החושב לצד ישיבתכ' ביניהם כל הזמן ההוא כאומר **אשר ישבתם בה** ואין ישיבה אלא עכבה וזה יסובב תגבור' החפץ בכם אף על פי כן אנכי מצוה אתכם שתתעצמו לנצח החשק לבל תעשו כמעשיהם, ואמר עוד **וכמעשה ארץ כנען** וגו' **אשר אני מביא אתכם שמה** וגו' פירוש אף על פי שאתם באים למקום אשר שם הרגיעה שידה של בחינת הרע הזה ונמצא בחינת החושב מתעוררת אף על פי כן מחייב אני אתכם לבלתי עשות כמעשיהם. ולצד שיאמר אדם כי אין מעצור ברוחו בדבר זה, לכן הקדים ה' בתחלה דברו הטוב ואמר **דבר אל בני ישראל ואמרת אליהם אני ה' אלהיכם**, כי הן אמת במין אנושי זולת ישראל ישנו בטענה זו כי לא ימצא בכחו למנוע עוצם חשקו ממנו מה שאין כן אתם בני ישראל לצד היותי ה' **אלהיכם** והיא השגה אלהות בכח האלהי ינוצח כח הטבעי גשמי, כי הצורה תשלוט בחומר כשיסכים איש ישראל להתדבק בה' אלהיו ישלוט בטבעו, והוא כמאמרם ז''ל (ב''ר פל''ד) שאמרו הצדיקים לבם מסור בידם והרשעים הם מסורים ביד לבם. הכוונה בזה כי החפץ והחשק ישנו בלב האדם והרצון הוא במוחו והם ב' מדריגות שנתן האדון בבני אדם וכשתזדמן לאדם דבר ערוה הלב חומדה ואין גמר בחימוד זה ויכול הרצון התלוי במוח למנוע החפץ ולא יעשנו הגם שיחמוד, הלא תמצא בבני אדם שמקבלים תענית הגם שהחפץ יתגבר בהם לאכול יבא הרצון וימנענו וכן עז''ה, וצדיקים תמיד מתנהגים כסדר זה ולבם מסור בידם שהגם שיתאוו תאוה בלבם יבחר השכל שהיא הנשמה ואם ישנו באזהרה מה' או מכללי התיעוב ישלול הרצון בו וימנע החפץ הגם שישנו, אבל הרשעים הם מסורים ביד לבם לכל אשר יבא החפץ בלב לא ימנעהו הרצון, ואולי כי אין להם נשמה או שכבר פגמוה ונכנעת היא לפני הרוח שבלב, ולכן אמר ה' **כי אני ה' אלהיכם** פירוש להיות שבחינת הנשמה בה ה' משרה אור שכינתו באדם בסוד (תהלים עח) אהל שכן באדם ומצד זה יש כח באדם לנצח החפץ לפני הרצון:
@508 **והוא** מה שנתכוון לומר דוד המלך עליו השלום במה שאמר (שם מ) לעשות רצונך אלהי חפצתי ותורתך בתוך מעי, הכוונה היא שמרוב דביקתו באדון האדונים יתברך שמו לעד עד שגם הלב נתהפך לעשות כמעשה הנשמה, שבא החפץ בו והתאוה לעשות רצונו יתברך, שאינו מהכת החפצים דברים המרוחקים מהקדושה וצריכים למונעם בשלילות הרצון, אלא שמעצמו חפץ ברצונו יתברך לשנוא דברים אשר הלב חפץ וחושק בהם. והוא מה שדקדק לומר חפצתי כי אפס חפץ המרגשת, וזה אמר במקום אחר (שם קט) ולבי חלל בקרבי, ואומרו ותורתך בתוך מעי פירוש לרוב חשק עבודת הקודש עד שמרגיש בלומדו תורת ה' כאלו אוכל וממלא בני מעיו ממזון טבעי:
@508 **עוד** אולי שנתכוון להודיע הקדמה תחת ששמעתיה משם הרב הקדוש מהר''י לוריא זצוק''ל (שער הגלגולים יט) והוא כי לפעמים יתהפך האדם וישתנה מטוב לרע בטבעו ומזגו ולא ידע מאיזה סיבה והוא עצמו יתמה איך נהפך בדעתו, ואמר כי זה יסובב לצד שלפעמים יאכל אדם מאכל שיש בו חלק מחלקי הרע או יש בו נפש רעה מהגלגולים לסיבת תחלואיהם וכאשר תכנס הנפש הרעה או ניצוץ הרע בקרבו תטהו מטוב לרע ותגבר בו בחינת הרע מעתה השומר עצמו ממאכלות הרעות יתגבר החפץ בו בדברים הנוגעים לנפש, והוא אומרו לעשות רצונך אלהי חפצתי וזה היה לי להיות תורתך בתוך מעי:
@508 **ולהשכילך** במשמעות אומרו ותורתך בתוך מעי. דע כי כל הצומח בין בדברים הכרחיים לחיות הנפש בין בדברים הסגוליים בעולם בין בדברים שהם תענוגי אדם שורש הכל והיוויו הוא מהתורה אשר היא אם הכל וכשם שבתורה פשט רמז דרש סוד כן מאכלים של עולם הזה, ועיין בפירוש שיר השירים (ראשון לציון פסוק הביאני אל בית היין) שחידשתי, וכשם שבעשבים יש דברים סגוליים וטבעיים כן יש בתורה מצות סגוליות וכו', והקדמה זו גדולה ויקרת הערך, וכתבתי ראשי פרקים להבינך אומרו ותורתך בתוך מעי כי כל האוכל אשר יאכל יסוד חיותו שבה נתהוה וגדל הוא מיניקת הקדושה שהיא התורה. ומעת פגם אדם הראשון ונתערב טוב ורע בכל אוכל תמצא חלק מהרע, ולזה צוה ה' על ערלת האילנות, ולזה גדל עם החטה מוץ ותבן וסובין הנזרקים, והבדילנו ה' מכמה דברים אשר שלט בהם חלק הרע לבל שקץ נפש הנבחרת, ולזה כשאדם אוכל דבר המותר כאילו נהנה מאור העליון ממאורי אור תורה אלא שנגשם לצד הצלחת יסודי ארץ שצריכים מזון כפי הכנתם והרכבתם, וזה אמר ותורתך בתוך מעי בזה גבר חפצו ותשוקתו לעשות רצונו יתברך כי אין רע בקרבו המסיר חפץ הערב לנפש:
@508 **נחזור** לענין שבאנו עליו כי בחינת החושב בדבר ערוה תגביר החפץ ותשליטנו ברצון ולא יושג הנצחון החפץ אלא דוקא באמצעות הרחקת הדבר מדעתו ומחשבתו לבל ראות הכיעור ולא יחשוב בו, אבל אם עיניו יביטו בדבר הנה הוא מסתכן, וכמעשה דוד המלך עליו השלום כשנסבב הדבר וראה מה שראה נתעורר לבו שהיה חלל ועשה מעשיו, ואפילו תחלת המחשבה בדבר זה תגרום תגבורת והולדת טבעיות החפץ ותגבורתו, ולזה נתכחם חכם החכמים שלמה המלך עליו השלום ואמר (משלי א) בני אם יפתוך חטאים פירוש בחינת החטא אל תאבה פירוש לא תכנם עם פתוייך בטוען ונטען, כי אריכות הרגשת החושב אפילו לבחינת השולל תפעיל הגברת החפץ ותהפך הרצון אליה. ומצות ה' ברה באה על הדבר בבחינת דיבור ואמירה, דיבור לומר גזירת מלך היא דבר מלך שלטון, אמירה לשון מענה רך ולשון רוממות לצד שהם ישגם במדריגה זו לאמר עליהם **אני ה' אלהיכם** ליחד שמו יתברך עליהם. גם מעלה גדולה היא לשומר בריתו, והיא ההדרגה שאין למעלה ממנה לזה אמר **ואמרת**:
@510 **את משפטי תעשו וגו'**. קשה אחר שאין מדבר אלא בפריצות העריות מה חוקים והמשפטים אשר צוה ה' אלהינו אותנו גם מה היא כוונתו באומרו **ללכת בהם**. גם צריך לדעת למה חזר פעם ב' לומר אני ה' אלהיכם:
@510 **ונראה** לפרש לפי מה שכתבתי בסמוך שהמחשבה בעריות תגדיל החפץ ותמעט מניעת הרצון, חש הכתוב שיאמר האדם להתרחק מכל וכל מפרט זה ויבטל מצות פריה ורביה ומצות היבום וכדומה ויהיה פרוש ממין זה לחלוטין שארז''ל (סוכה נב:) אבר קטן יש באדם משביעו רעב מרעיבו שבע, לזה צוה ה' ואמר **את משפטי תעשו** שהם ממין עצמו שאסרתי לך אני מחייבך לעשות, ואף על פי כן **את חקתי תשמרו** שהם העריות שאסר. או יאמר כי באמצעות שמירת העריות ימצאו הכנה בנפשותם לקיים מצות עשה כאומרו **משפטי תעשו** ושמירת כל הלאוין כאומרו **חקותי תשמר** ו, מה שאין כן אם יתעיב מעשיו בדרך ההוא תחלה נפשו בתחלואי הטומאה ולא יקיים אחת מהנה, כי טומאת חטא זה משרה טומאה על כל איברי האדם וכוחותיו, וכיון שכן כל הלאוין לא ימנע מהן כי בכל אבר טומאתו בו. וכן מצות עשה, והגם שיעשה לפעמים איזו מצוה אינה מצוה כי לא יתרצה בה הבורא יתברך שמו, על דרך אומרו (תהלים נ) ולרשע אמר אלהים מה לך לספר חוקי וגו', כי אין חפץ לה' בהם אלא במצוה הנעשית בקדושה. ואומרו **ללכת בהם** יכוין לומר לדרכנו כמין חומר, כי כאשר יהיה האדם טהור וקדוש מהתיעוב יוליד בטבעו לקיים המצות תמיד, על דרך אומרו (שם קיט) חשבתי דרכי ואשיבה רגלי אל עדותיך ודרז''ל (ויק''ר פל''ה) שרגליו של דוד מעצמם היו הולכות לבית המדרש לצד ההרגל והחפץ הנבחר, לזה אמר **ללכת בהם** פירוש שמעצמו ילך בהם בטבעו כעושה דברים שהטבע עושה לצד שעיקרו וגופו הכל עומד במקום טהור:
@510 **עוד** יכוין באומרו **ללכת בהם** על דרך מה שאמר הנביא (יחזקאל לג) צדקת הצדיק לא תזכר ביום שובו וגו', שאם יהיה צדיק כל ימיו וירשיע לבסוף הרי זה הפסיד זכותו ולא ילך עמו ביום לכתו לעולם העליון, לזה צוה ה' ואמר ללכת בהם פירוש שיתמיד במעשים הטובים ושמירות החוקים כדי שילך בהם ביום נסעו לדרך כל הארץ:
@510 **עוד** ירצה שלא יקוה האדם לשכר מצות בעולם הזה, על דרך אומרו היום לעשותם ולמחר לקבל שכרם (עירובין כב) שכל מה שיעשה לא יבחר לאכול עולמו בחייו אלא ילך לפניו צדקו לחזות בנועם ה':
@510 **עוד** ירצה על דרך אומרו כי נר מצוה ותורה אור, כי עולם העליון רחוק במהלך ובעלות נפש אדם מעולם זה לעולם העליון אם הוא רשע דרך רשעים באפילה, ובלכת אדם כשר מצות ותורה שבידו מאירים לו כאומרו (תהלים קיט) נר לרגלי דבריך ואור לנתיבתי, שהכוונה הוא להיות כי יש בנר מה שאין באור ויש באור מה שאין בנר, כי הנר יש בה בחינה גדולה מהאור כשיהיה קרוב ולזה אמרו רז''ל (פסחים ב) שבדיקת החמץ צריכה בלילה לאור הנר שהנר יפה לבדיקה להכניסה בחורין ובסדקין ומה שאין כן באור. ויש באור בחינה גדולה מהנר שרואה למרחוק מה שאין כן בנר, לזה אמר דוד כי מצות ה' יש באורם ב' בחינות הנזכרות, בחינת הנר בקרוב וזה אמר נר לרגלי שהוא בקרוב, ובחינת האור למרחוק והוא אומרו ואור לנתיבתי. וזה אמר כאן **ללכת בהם** פירוש באורם ילך שאם לא כן בחשיכה ילך ולא ידע במה יכשל רח''ל:
@510 **עוד** ירצה על דרך מה שאמר התנא האלהי רבי שמעון בר יוחאי ע''ה (זוהר ח''א קע:) כי רמ''ח אברי האדם ושס''ה גידיו הם כנגד מצות עשה ולא תעשה, ובעשות האדם מצוה באותו אבר שנעשית המצוה שורה בו שם הוי''ה יתברך, כי המצוה היא אותיות שם הויה חצים מגולה והוא סוד עלמא דאתגליא וחצים מכוסה סוד עלמא דאתכסיא כי אותיות מ''צ בא''ת ב''ש הם י''ה, ודבר ידוע הוא כי הקב''ה הוא שמו ושמו הוא בסוד אומרו (זכרי' יד) ה' אחד ושמו אחד. הראת לדעת כי בעשות המצוה נעשה האדם מרכבה לשכינה ומתהלך ה' בתוכו, וזה אמר **ללכת בהם**, וחזר ופירש מי הוא ההולך בהם ואמר **אני ה'** וכאלו אמר ללכת אני ה' בהם, והוא סוד (שמות כה ח) ושכנתי בתוכם. וכפי זה ירצה אומרו בהם כפשטה, כי בעשית המצוה נעשית ההכנה ללכת בה, וזהו סוד אומרו (כו יב) והתהלכתי בתוככם, (דברים ד ד) ואתם הדבקים בה' אלהיכם:
@511 **ושמרתם וגו'**. צריך לדעת למה כפל לומר דברים עצמם שאמר בסמוך, ויתבאר על פי דבריהם ז''ל (סנהדרין עד.) שאמרו וחי בהם ולא שימות בהם שאם אנסוהו לעבור על אחת ממצות ה' יעבור ולא יהרג. ואמרו עוד כי על ג' עבירות חייב אדם ליהרג ולא יעבור והם עבודה זרה גילוי עריות שפיכות דמים. מעתה אמר פסוק ראשון סמוך למצות עריות ולא התנה הכתוב אשר יעשה וגו' וחי בהם, ואמר פסוק ב' לצוות על שאר המצות ואמר **וחי בהם** לדייק ולומר שבמצות שנאמרו בפסוק שלפנינו שלא אמר וחי בהם יהרג ואל יעבור:
@511 **עוד** נראה בהעיר עוד למה שינה הכתוב בב' כתובים, בראשון אמר אני ה' אלהיכם, ובפסוק ב' אמר אני ה'. אכן כנגד ב' בנים דברה תורה אחד העושה מיראה ואחד העושה מאהבה, וכבר נתבארו הדברים במקומות אחרים (סוטה לא) כי העושה מיראה שכרו לאלף דור והעושה מאהבה שכרו כפול לאלפים. והנה מן הנמנע שישיג המשיג בחינת האהבה עד שתקדים לו בחינת היראה בסוד (תהלים קיח) זה השער לה', ואשר על כן אמר הכתוב כנגד בחינת היראה את משפטי וגו' **אני ה' אלהיכם**, דקדק להזכיר בחינת הדין שהוא רמוז בשם אלהים להעירך במי הכתוב מדבר, ואחר כך צוה לגדר ב' לעשות מאהבה, ולזה אמר **אני ה'** ולא הזכיר שם אלהות לומר שתהיה השמירה לצד אהבת הטוב והחפץ והרצון פעל בו לעשות מאמר קונו החביב מאהבתו אותו הגם שלא היה עונש לעובר. ואמר **וחי בהם** פירוש כי אדם שעושה מאהבה ישנו גם בטוב עולם הזה יתר על הגמול הקבוע לו בעולם הנצחי. ואולי כי לזה רמז באומרו וחי בתוספת וא''ו להעירך שזה נוסף על שכר אחר שהוא שכר הנעלם, מה שאין כן גדר הראשון שעושה מיראה שאין לו אלא לעולם העליון כאומרו ללכת בהם לעולם העליון, אבל גדר זה וחי בהם פירוש לא לעתיד לבד שאם כן היה לו לומר ויחיה אלא מעת טעמו טעם המצות בערך זה וחי בהם. ולדרך זה יתבאר גם כן מה שאמר בפרשת (עקב יא יד) והיה אם שמוע שאמר ונתתי מטר ארצכם וגו', פירוש לצד ששם נאמר לאהבה את ה' וגו' לזה הודיע כי מצוה זו יש לה שכר גם בעולם הזה וראוי הוא ליהנות בב' עולמות. והגם שאמרו ז''ל (קדושין לט:) שכר מצות בהאי עלמא ליכא, זה ישנו בהטבה זו, ורמז עולם העליון במה שאמר ונתתי בתוספ' וא''ו בתחילה יעוד השכר לו' אין זה אלא תוספת על הנעלם המושכל הנצחי:
@511 **האדם וגו'**. במסכת שבת וזה לשונם (ב''ק לח. ע''ז ג). אמר רבי יהודה מנין שאפילו גוי ועוסק בתורה שהוא ככהן גדול דכתיב אשר יעשה אותם האדם וחי וגו' כהנים לוים ישראלים לא נאמר אלא האדם ע''כ. פירוש לצד שהוקשה לרבי יהודה יתור האדם, עוד הוקשה לו למה דיבר הכתוב בלשון נסתר שהיה לו לומר אשר תעשו אותם כדרך שהתחיל לדבר ושמרתם וגו' לנוכח, ומכח זה דרש שנתכוון למי שלא היה שם באותו מצב שאינו לא כהן ולא לוי ולא ישראל ומי זה הוי אומר זה גוי. והתוספות ז''ל הקשו מברייתא (ב''מ קיד) שדרש ר''ש פסוק (יחזקאל לד) אדם אתם אתם קרויים אדם וכו'. ואמרו שיש לחלק בין אדם להאדם ע''כ. וכמו כן ראיתי בספר הזוהר (ח''א כה.) שחילוק זה אמיתי מצד עצמו, והוא דבר שב (ע) [מ] נין תלוי כידוע ליודעי חן שחשבון המעולה הוא של אדם ולא של האדם כי המוסיף גורע. ואולי כי כשעוסק הגוי בתורה גם עליו יהיה כתר זה ליקראות אדם, וכפי זה אות ה''א שבהאדם הוי ריבוי הגוי שגם הוא יקרא אדם כשעוסק בתורה, ואין אות הה''א כאן מעיקר השם והבן:
@530 **אל תטמאו בכל אלה**. אמרו ז''ל (תו''כ) בין בכולן בין במקצתן. פירוש אפילו במקצתו, וכאילו אמר אל תטמאו באחת מכל אלה. וצריך לדעת למה דיבר הכתוב בסדר זה שהיה לו לומר אל תטמאו באחת מכל אלה כדי שלא יהיה מקום לטעות. עוד קשה מה שגמר אומר כי בכל אלה נטמאו הגוים והגוים אין לנו מקום לומר שלא נטמאו אלא באחת שהשטוף בזמה ידו בכל. גם משמעות בכל אלה נטמאו, יגיד שבכולן נטמאו ומעתה מה טעם נשמע אל הדבר אשר יצוה עליו שהכונה היא אל תטמאו בכולן:
@530 **ונראה** לפרש בהשכיל על דבר אמת למה לא גילה ה' בתורה הדרגות המצות וסגולתם, ואדרבה בא שלמה המלך עליו השלום ואמר (משלי ה) אורח חיים פן תפלם וענו אחריו רז''ל (אבות פ''ב מ''א) שאין לנו לומר מצוה זו גדולה וזו קטנה שאין אתה יודע וכו', והוכיחו (דב''ר פ''ו ירושלמי פאה פ''א ה''א) ממה שקבע ה' שכר שוה לגדולה שבגדולות עם קטנה שבקטנות, ועל כולן אני דן שהסברא נותנת שיש מצות ודאי גדולות ביותר ולמה סתם ה' הדבר:
@530 **ונראה** כי לצד שיש צורך במצות הקטנות כבגדולות שכל מצוה ומצוה סגולתה בפני עצמה, ומה בכך אם שכרה מעט כיון ששכרה הוי דבר שאינו בנמצא כשכר הגדולה, וכל המצות צריכין לתיקוני הנפש, לזה צוה ה' קטן וגדול בהדרגה אחת כדי שיעשו ישראל כולם כאחד. והוא מאמר שלמה (קהלת ט) כל אשר תמצא ידך לעשות בכחך עשה:
@530 **עוד** נראה טעם אחר כי לצד שיש מצות שסגולתם להאריך ימים בעולם הזה, ויש שסגולתם עושר, ויש שסגולתם בנים, וכן על זה הדרך וחש ה' כשיתגלה הדבר כל אחד ילך וישתדל במה שחפץ ובמה שצריך ולא ישתדלו בשאר מצות כמצטרך, לזה סתם הדברים ובזה ישתדל האדם בכולן כדי שתבוא לידו גם מצוה שסגולתה דבר הצריך לו, ובזה יש טעם למה שאנו רואים כמה בני אדם רעים לשמים ולבריות ובתיהם שלום מפחד מלאים כל טוב, כי אפשר שבא לידם מצוה שסגולתה הצלחת עולם הזה, ואין העבירות שעושים מונעים סגולת המצוה והצלחתה, וכל זה בבחינת מצות עשה, ובמצות לא תעשה יהיה הדבר כן, יש עבירות שפורענותם לעולם הבא, ויש שפורענותם יסורין באריכות הזמן, ויש שפורענתם ברחמנות, ויש כ''כ אכזריות, והלא תמצא כמה רשעים שעברו על הכריתות ולא נכרתו הגם שעמדו בתוקף הרשע עד שעברו זמן הכריתה, אלא ודאי שיש שמשתלם עליה בעולם הזה ויש שמשתלם עליה לעולם הבא. ודבר ידוע הוא שיותר יפעיל הפחד בלב בני אדם מוסר המשתלם בעולם הזה להיותו נגלה מעונש הנסתר:
@530 **וכבר** קדם לנו כי ה' ב''ה יקפיד אפילו על ברואיו הקרובים אליו לבל ידברו דבר שאינו על קו הצדק, ואפילו דברים שנראם כשקר, וצא ולמד מאמר רבי עקיבא לחבריו (חגיגה יד:) כשתגיעו לאבני שיש טהור אל תאמרו מים מים, ומכאן נקיש לכסף נבחר לשון צדיק הוא ה' אלהינו מקור האמת כי יקפיד לבל יכתוב בתורה אלא דברים המובהקים במדת אמת:
@530 **ובזה** נבא אל הביאור, והוא כי לצד שעונש זה של הקאת הארץ יושביה אינו אלא על פרט אחד מהתועבות האמורים בפרשה כאשר אבאר בסמוך אבל שאר התועבות יש להם עונש אחר כאשר שפט אל חי תמים דעים כפי בחינת התיעוב, ולזה כשבא לצוות את עמו רצה להודיעם כי יש בתועבות אשר הזהירם עליהם תיעוב אחד אשר יסובב שתקיא אותם הארץ, ולא רצה ה' לגלותו כדי שלפחדו ישמרו עצמם מכולם יחד כמו שכתבתי שיותר ירעיד עונש הנגלה מעונש הנסתר, וזה שיעור הדברים **אל תטמאו בכל אלה**. פירוש, באחד מכל אלה.
@530 **כי בכל אלה נטמאו הגוים אשר אני משלח מפניכם ותטמא הארץ ואפקוד עונה**. פירוש, אחד הוא הגורם ואותו פקדתי על העיר ותקיא את יושביה הא למדת שעל עון אחד קאה הארץ אותם, אם כן תתחייב לומר כי מאמר **אל תטמאו בכל אלה** הוא באחד מכל אלה כיון שעל אחד היה העונש ואין אתה יודע מי הוא. ואמר עוד **ושמרתם** וגו' **ולא תעשו מכל התועבות** וגו' כי את כל וגו' עשו, נתכוון הכתוב בזה להודיעם שכל התועבות עשו אנשי הארץ ואין אחת בכל התועבות שלא עשו אותם, והמכוון בזה כדי שיכנסו כולן בגדר המיחוש, כי כל שלא עשו אותה אנשי הארץ אין בה פחד ההקאה מן הארץ, לזה הוצרך לומר כי כל וגו'. ודבר זה דומה לכלי מים שהקיא בו נחש כל הכלים שיכנסו בגדר ספק כלי זה אדם נרעד מגשת אליו, וכמו כן הדבר הזה. והגם שהעון הגורם הקאה הוא אחד ותועבות אשר יצוה רבים הם. דבר זה דין קבוע יש לו שאדם הוא פושט עצמו להתעיב, ודין לוקח יש לו ולא דין פורש, וכמו שהארכתי בזה בחיבורי על יורה דעה (פ''ת סי' קי) וכיון שכן כל הקבוע כמחצה ומחצה. ואחר שהפחידם בעונש נגלה חזר ואמר **כי כל אשר יעשה** וגו' פירוש שגם על כל שאר התועבות יש עונש חמור להכרתת הנפש אלא שאחת מהם גורמת עונש הנגלה:
@531 **ותטמא הארץ וגו'**. הכוונה הוא על דרך מה שאז''ל (זוהר ח''ג נג:) כי במעשה ישראל יתהו' הרוחניות אם לטוב אם לרע, והוא אומרם (אבות פ''ד מי''א) העושה מצוה אחת וכו' והעובר עבירה אחת, וזהו שרמז כאן באומרו **ואפקוד עונה עליה**, על דרך אומרו (ירמיה ב) תיסרך רעתך, כי מפעולת הרע יתהוה הקטיגור אשר ישלם לאיש כמעשהו. ואז''ל (תומר דבורה פ''א) כי תשלום הדין הוא כל מלאך מחבל שנברא מכל עבירה בא ומשתלם מעושהו עד שכלה באמצעות פעולת היסורין כי הוא מתמעט והולך וכשכלה כח פועל הרע הוא נאבד, ושפט ה' דבר זה בצדק כדי שישתלם כל אחד כפי מעשיו בכיוון מופלא, כי כפי כח הנעשה במעשה הרע יהיה בנברא, והוא מאמר הכתוב כאן באומר **ואפקוד עונה** פירוש לשון מינוי שממנה העון עצמו על עושהו. ואומרו לשון יחיד כבר פירשתי למעלה. עוד נראה לומר כפי דרכנו שאפשר שאין הקטיגורים משתלמים יחד אלא בזה אחר זה, לזה אמר לשון יחיד, וזה דרך דרש:
@532 **ושמרתם אתם**. טעם אומרו תיבת **אתם** ולא הספיק במה שדיבר להם לנוכח ושמרתם נראה כי מצוה זו באה להזהיר על החוקים והמשפטים שלא יהיו מתבטלים מכל המצטוים עליהם, והכוונה שלא יאמר אדם שאין לו להקפיד אלא שלא יתבטלו המצות על ידו אבל אם יתבטלו מהזולת אין לו לחוש, לזה אמר **ושמרתם את חוקותי** וגו' פירוש שלא יתבטלו מכל המצטוים עליהם. ולצד כי מצוה זו אינה אלא על הגדולים לזה אמר אתם דבר לנכח עם משה ובית דינו, כי על בתי דיני ישראל לפקוח עין לבל תתבטל מצוה אחת ממצות התורה מבני ברית. ובתורת כהנים אמרו ז''ל ושמרתם אתם אתם נאים שומרים אותם שאתם פתחתם אותם, וכן הוא (שה''ש) אומר גן נעול אחותי כלה גל נעול מעין חתום ע''כ פירוש כאן קרב ה' אזהרת העריות אל טבע הרגיל, ואמר להם כי מצוה זו של שמירת העריות אינו דבר חדש וזר בערך ישראל שהרי הם מצד עצמם קודם שנצטוו היו פרושים מן העריות דכתיב גן נעול אחותי כלה, והוא מה שרמז באומרו **אתם** פירוש מה שאתם שמרתם כבר מעצמיכם:
@532 **האזרח והגר**. רז''ל דרשו (תו''כ) אזרח זה אזרח האזרח לרבות נשי אזרחים, גר זה הגר, הגר לרבות נשי הגרים וכו' ע''כ, טעם שהוצרך הכתוב לפרט כל פרטים אלו, לבל תטעו מתיבת אתם ותאמר שבא למעט איזה פרט מהפרטים הרשומים תלמוד לומר וכו':
@532 **עוד** נראה כי נתכוין הכתוב להודיע שאם ישראל והגרים ישמרו כל החוקים והמשפטים אין כח במעשה הגוים הגם שיתעבו מעשיהם להקיא הארץ יושביה, ודוקא קודם שנכנסו ישראל לארץ הוא שקאה הארץ הגוים על מעשה התיעוב אבל אחר כניסת ישראל לארץ אין הדבר תלוי אלא בישראל והגר, ולזה פרט אותם שמעשיהם יסובבו למעט הגוים:
@532 **ותמצא** שאמר הכתוב (שמות כג לג) לא ישבו בארצך פן יחטיאו אותך לי, וכתב רמב''ם וסמ''ק שגוי שלא קבל עליו ז' מצות אסור לדור בארץ ישראל מטעם פן יחטיאו וגו', הא למדת שאם לא היה טעם פן יחטיאו הגם שלא יקבל עליו ז' מצות ויתעב מעשיו אין לחוש להקאת הארץ בשבילם:
@534 **ולא תקיא וגו' כאשר קאה וגו** '. לא הספיק מה שאמר למעלה ותקיא הארץ, לזרז ביותר על דרך מה שדרש רבי אליעזר בן עזריה בפרשת אחרי מות (בתו''כ) משל לחולה שנכנס אצלו הרופא וכו' אל תאכל צונן וכו' שלא תמות כדרך שמת פלוני זה זרזו יותר וכו' עד כאן, כמו כן במה שלפנינו נתכוין ה' לזרז ישראל ביותר:
@536 **ושמרתם את משמרתי**. יצו ה' על הגדרים השומרים לבלתי יבא להכשל בתיעוב, והוא אומרו **ושמרתם את משמרתי** פירוש משמרת הגדר, והטעם לבלתי עשות וגו' אפילו בשוגג, והגם שלא תתחייב על התיעוב בשוגג ואף על פי כן אתם מתטמאים במעשה התיעוב, והוא אומרו **ולא תטמאו בהם**, ולחשש זה. תשמרו משמרתי. ואומרו **אני ה' אלהיכם**, נתכוון לומר כי בהטמאם אפילו בשוגג הם נגרעים מערך זה שיתייחד שמו יתברך עליהם, כי התיעוב בכל מציאות שיהיה יפעיל פירוד בין ישראל ובין השכינה, שאין שכינה שורה אלא על המושלל מהכיעור ההוא וקדוש יאמר לו כל הכתוב לחיים:
@536 **חסלת פרשת אחרי**
@538 **אל כל עדת וגו'**. טעם אומרו אל כל. אמרו ז''ל בתורת כהנים לפי שפרשה זו רוב גופי התורה תלוים בה נאמרה בהקהל. והגם שכל מצוה ומצוה ממצות התורה היה משה אומרה לכל ישראל כאמור בברייתא הובאה בעירובין (נד:), תירץ הרא''ם שהיו נכנסים כת אחר כת מה שאין כן בפרשה זו שנכנסו יחד ע''כ. וקשה לדבריו אם כוונתו באומרו שהיו נכנסים כת אחר כת על ישראל שהיו באים אחר הזקנים, אם כן משה הי' אומר יותר מחמשה וששה פעמים, ולפי חשבון הפעמים שמנה התנא שם שיש ביד כל אחד ד' אינו משמע כן, שכתבו וזה לשונם נכנסו כל העם וכו' נמצאו ביד אהרן ד'. ואם כוונת הרב באומרו כת אחר כת הוא על כת של אהרן, ונדב ואביהוא, וכת של הזקנים, וכו' שבשאר הציוויים היו נכנסים זה אחר זה וכאן נכנסו יחד אהרן נדב ואביהוא והזקנים והישראלים. הנה במה שנעמוד על עקרן של דברים למה משה נהג בכל המצות בסדר זה, ולא היה שונה לכולם יחד ד' פעמים, ונמצאו לכל אחד מישראל ד' פעמים מפי משה, שהוא יותר טוב מלשמוע הד' פעמים פעם ממשה וב' וג' פעמים מזולתו, אלא הטעם הוא לא' מב' דברים, או לעשות כבוד להדרגת ישראל כבוד לאהרן כבוד לבניו כבוד לזקנים ואחר כך לישראל, או לצד שכל אחד למד בפני עצמו מפי משה כשיחזור אהרן לבניו וכשיחזרו בניו לזקנים והזקנים לישראל מאמצעות זה יהיה ניכר ונרגש אם יש השתנות בנשמע בין הכתות כשיחזרו הדברים זה לזה, מה שלא היה הרגש זה אם היו כלם שומעים מפי משה הד' פעמים, ודבר זה יושכל בלב שומע. אם כן לב' הדרכים יותר נכון לעשות בסדר זה גם במצוה זו, בין לטעם לעשות כבוד לאהרן כו' למה יגרע כבוד אהרן וכו' כאן, בין לטעם שיכון הדברים לשומעים אדרבה כאן יצטרך להיות הדבר יותר לצד שהם גופי התורה. ואם לצד שיאמר משה המצוה בדרך כללי לכל ישראל, הלא גם בסדר הראשונות ישנה לבחינה זו שישנו לדיבורו של משה כללי לכל ישראל כשנכנסין כל ישראל ושונה להם משה במעמד גם אהרן ובניו והזקנים, ואם כן מה כיעור בסדר הרגיל שצוה ה' לשנות שאין זה אלא גרעון:
@538 **אכן** הנכון בעיני הוא, כי בסדר הראשון לא היה מדבר משה אלא לאנשים, וכאן צוה ה' שידבר לכל עדת ישראל אנשים ונשים וטף כסדר שהיו מקובצים במתן תורה. ובסמוך יתבאר הכתוב באופן אחר:
@538 **ואמרת אליהם**. טעם שכפל לומר ואמרת לדבריהם ז''ל (ויק''ר פכ''ד תו''כ) שאמרו כי לצד שרוב גופי התורה וכו' לזה עשה בה גם כן כסדר נתינת התורה שדבר בה רכות וקשות (יתרו יט ג) כה תאמר וגו' ותגד, ואמר דבר לשון קושי **ואמרת** אמירה רכה, ובסמוך יתבאר הכתוב באופן אחר:
@538 **קדושים תהיו**. צריך לדעת מה הוא המכוון של מצוה זו. ונראה שבא הכתוב לתת עשה על העריות, שציוה עליהם בפרשה הקודמת בלאו, הוסיף עשה עליהם לעבור עליהם גם בעשה. עוד ירצה על דרך אומרם ז''ל (קידושין לט:) ישב אדם ולא עבר עבירה נותנים לו שכר כעושה מצוה, והוא מאמר הכתוב קדושים תהיו במצות עשה בבא עבירה לידו שיתרחק מעשות', ובזה קיים מצות עשה שנצטוו במאמר **קדושים תהיו**, והוציא זכרון מצוה זו בלשון זה של **קדושים**, לומר שכל המקיים מצוה זו נקרא קדוש, והוא מאמרם ז''ל (ויק''ר פכ''ד ירושלמי יבמות פ''ב ה''ד) ג''כ. ולטעם זה דקדק לומר **אל כל עדת בני ישראל**, לומר כי מצוה זו שמצוה קדושים תהיו היא מצוה שישנה בכל אדם, שכל איש ישראל בקיימו מצוה זו קדוש יאמר לו, ואין הדרגה בישראל שתהיה נמנעת מהשגה זו. גם בזה יתישב טעם כפל דבר ואמרת, כי יש כאן דיבור קשה בערך העובר שיוסיף עונש עשה, ויש כאן מעלה וכבוד למקיימו שיקרא קדוש. ואולי כי דוקא בנ''י הוא שישנם בבחינה זו מה שאין כן אומות העולם, לו יהיה שיפרוש אדם עצמו מבחינות העריות האסורות לו או אפילו שאינם אסורות, אף על פי כן מושלל הוא מבחינת הקדושה, ולזה אמר **אל** וגו' **בני ישראל**, ובסמוך יתבאר באופן אחר:
@538 **כי קדוש אני וגו'**. צריך לדעת מה נתינת טעם הוא זה, וכי יתחייב הדבר ליציר כפיו להדמות לקונו, והלא הרבה הדרגות ישנם באלהי ישראל ואינם מושגים בישראל, ואם כונתו לומר טעם הציווי שהוא חפץ בדבר לצד אלהינו קדוש חפץ שגם עובדיו יהיו כמו כן ולא טעם המתחייב, ועד עתה אין אני יודע למה יתחייב הכתוב לתת טעם. ורז''ל נראה שמקושיא זה הרגישו, ודרשו בתורת כהנים וזה לשונם אם אתם מקדשים עצמיכם מעלה אני עליכם כאילו קדשתם אותי ע''כ. וכפי זה תהיה כוונת **כי קדוש** וגו' הודעת תועלת הנמשך, והודעת הפכו כמו שסיים שם התנא ואם אין אתם מקדשים עצמכם מעלה אני עליכם כאלו לא קדשתם אותי ע''כ. ואולי כי גם לזה כוון בכפל דבר ואמרת, לקושי הנמשך אם לא יקדשו עצמם, ולרוממות הנסבב אם יקדשו עצמן:
@538 **עוד** נראה לפרש הכתוב על זה הדרך כי לצד שצוה ה' על בחינת תאוה הקבועה בטבע אנושי, והוא תאוה השולטת על הרצון, וכבר כתבתי בפרשה הקודמת בפסוק (יח ב) כמעשה ארץ מצרים וגו' כי בחינה זו אין יכולת באדם לשלוט עליה אלא בגדר הריחוק בבחינת החושב, ומעתה לצד שצוה ה' במקומו לקיים המין ולהדבק בצלע נכון לאיש יש מוצא רע מבחינה זו להתגבר בו בחינת חשק המתגבר ונוצח הרצון בהופכו, ואין אדם שולט בעצמו להשמר מן העריות שצוה ה' עליהם, ואם כן ממה נפשך יעשה מצוה דרך גבר בעלמא לקיים מינו הנה הוא מושלל משמירת העריות, ימנע עצמו ממין זה כל עיקר הנה הוא מבטל מצות פריה ורביה ומצות יבום, אשר על כן בא מאמר ה' כאן וצוה בנעימות אמרי קדוש **קדושים תהיו** פירוש שיקדשו עצמן במעשים אשר באה עליהם המצוה לעשותה, פירוש שלא יעשה הדבר לתאות הגשם ולהשלים החפץ השואלו עשות דבר אלא יעשה הדבר בקדושה ובטהרה, כמו שמתעטף בציצית ומכניס תפילין בזרועו, וימאס בדעתו חפץ הבא מעצמו, והוא מאמרם ז''ל (נדרים כ:) יהיה דומה כמו שכפאו שד, ולאיש כזה קדוש יאמר לו, ולצד שיאמר אדם איך נכחיש המורגש שהחפץ יכירנו ויטעה טעם הדבר, ואין כח בבחינת החושב למנוע ההרגש בזה כי הרגשתו גדולה ומעוררת כל החושים והרגשות וכובשת המחשבה לבא עמהם בטעימת הדבר, ואם כן חזרנו לחששא הראשונה, לזה אמר **כי קדוש אני ה' אלהיכם**, פירוש על דרך אומרם ז''ל (תיקונים ע) כי כל העושה מצוה אחת שמו יתברך הוי''ה שורה על אבר שבו עשה המצוה, כי תיבת המצוה בו רמוז שם, מ''צ בא''ת ב''ש י''ה, ואותיות ו''ה הרי הוי''ה, וכבר כתבתי במקומות אחרים (לעיל יח ד) טעם שחצי השם בא''ת ב''ש וחצי נגלה. ואם כן בעשות האדם הדבר לשם מצוה הנה שם הוי''ה שורה עליו שהוא קדוש, ובזה אין דבר רע משתלשל מהמעשה, והוא אומרו **כי קדוש אני ה' אלהיכם**, דקדק לומר **אלהיכם** לרמוז אל דביקות ה' במתקדש לעשות המעשה לשם מצוה, על דרך אומרו ואתם הדבקים בה' אלהיכם. ולזה אמר **אל כל עדת בני ישראל** לומר שכל איש ישראל ישנו בגדר מצוה זו, גם כפל ואמרת לרמז מעלה זו:
@538 **עוד** ירצה באומרו **כי קדוש אני** וגו' פירוש לצד שיש מאמרו יתברך בתורה שעם בני ישראל הם דבוקים בהקב''ה דכתיב (שם) ואתם הדבקים וגו', ועל ידי עבדיו הנביאים כתוב לאמר (ידמי' יג) כאשר ידבק האזור אל מתני איש כן הדבקתי אלי את כל בית ישראל, מעתה בא הקב''ה בטענה הנשמעת ואמר **קדושים תהיו**, והטעם כי קדוש אני, ואם תאמר ומה לתבן את הבר, לזה אמר ה' **אלהיכם**, כאן רמז השראת שכינה בדבקות לה' כאמור בפסוק ואתם הדבקים בה' אלהיכם:
@538 **עוד** ירצה שלא יאמר אדם שלא אסר הכתוב אלא מעשה העריות אבל לא בחינת החושב והסתכלות ושאר דקדוקי התיעוב אשר רבו וכבר רמזו מהם רז''ל (ברכות סא.) כגון המרצה מעות מידו ליד אשה וכו', כמו שדרשו בפסוק יד ליד וגו', וכאן צוה ה' על הדברים ההמה וכיוצא בהם שצריך להרחיק עצמו מהכיעור ומהדומה לדומה לו כדי שלא יבא להכשל אפילו בדקדוקים ההם, וכמאמר הזוהר בפסוק אל תפנו אל האלילים, והוא מה שצוה במאמר קדושים תהיו לבל יבא לידי החושב ותהיה נשללת מהם בחינת הקדושה כמאמר הכתוב (תצא כג יא) לא יהיה טהור מקרה לילה, ולצד שיאמר אדם הלא דבר זה אינו ברשותי שהגם שאשמור עצמי ביום אף על פי כן בלילה אין הדבר תלוי בידי, לזה אמר **כי קדוש אני ה' אלהיכם** וכיון שאני קדוש ואני עמכם אני אמנע בחינת הטומאה מגשת לאיש הישראלי, זולת אם אדם יחשוב בבחינת הרע אז שולל ממנו השראת שכינה ושורה עליו בחינת הרע והוא ההדרוקן המכסה פני איש רע, ואז יבא לידי קרי בלילה:
@538 **עוד** ירצה על זה הדרך **קדושים תהיו** לשון עתיד פירוש אין הפסק למצוה זו, כי כל שער מהקדושה אשר יכנס עדיין ישנו בגדר הכנסה שער אחר למעלה ממנו, כי אין שיעור להדרגות הקדושה המזומנת לכל הרוצה ליטול את השם. וצא ולמד ממדרגות הנביאים זו למעלה מזו, ומשה עולה על גביהן, ואולי שיכול להיות הדרגה גדולה ממשה, והוא מדרגות מלכנו משיחנו המעוטר בעטרי עטרות, כמובן מפסוק (ישעי' יא) ונחה עליו רוח ה' וגו', ולדברי רז''ל (במד''ר פי''ט דב''ר פ''ב) כי משה שהיה הוא הגואל העתיד, וכמו שהארכנו בפירושן של דברים במקומן, אם כן אין שיעור וגבול להדרגות הקדושה. לזה אמר **תהיו** כי מצוה זו אין לה הפסק ותמיד ישנה בגדר מצוה זו להיות קדושים. ונתן טעם לדבריו **כי קדוש אני ה' אלהיכם** שאין שיעור אל קדושתו יתברך, וחפץ ה' בבניו ידידיו להדמות לקונם בהפלגת הקדושה, ומעתה דון בדעתך ההדרגות אשר תבא בהם:
@538 **עוד** ירצה בנתינת הטעם **כי קדוש** וגו' פירוש ולפי ערך גדולת קדושתו יתברך צריכין להתקדש כי לצד שאנו מכינים עצמינו להשראת שכינה על ראשינו צריכין לשער גודל קדושתו יתברך כדי לעשות המוכן לדבר, כי אינו דומה המאכסן בביתו הדיוט, למאכסן שר וגדול וקל וחומר מלך, וקל וחומר בנו של קל וחומר מלך המלכים, וקל וחומר וכו' מלך העולם אשר לו המלוכה, שכל מה שיעשה עדיין ישנו בקום עשה כי אין שיעור די להצריך עשות, ולזה אמר **כי קדוש אני ה' אלהיכם** פירוש ולערך קדושתי אני מצוה שתכינו עצמכם בכל יכולת המושג:
@538 **ותמצא** שאמרו ז''ל (שבת קיב:) אם הראשונים כמלאכים וכו' ואם הראשונים אנשים וכו', הראת לדעת כמה צריך אדם עשות בהתקדשותו. וצא ולמד כמה היו משתדלים בעבודת ה' הראשונים, ממעשה רבי אלעזר בן עזריה (שם נד) שיצתה פרת שכנתו ברצועה שבין קרניה שלא ברצון חכמים הגם כי כפי דעתו היה מותר, ואמרו בירושלמי (שבת פ''ה) שהושחרו שיניו בתעניות על הדבר ההוא ולזה כיון באומרו **דבר** לשון קושי לצד הפלגת הציווי. ולצד בחינת המושג אמר **ואמרת** ואמר **אל כל עדת בני ישראל** לבל יאמר אדם שאין מצוה זו הגדולה לכל איש ישראל ולא דבר הכתוב אלא ליחידי סגולה, לזה אמר **אל כל עדת** וגו' שכלם ישנם בגדר מצוה זו, והוא מאמרם ז''ל (תדב''א רמב''ם הל' תשובה) יכול אדם לעשות עצמו כמשה רבינו:
@538 **עוד** ירצה **קדושים תהיו** כמלאכים הנקראים קדושים, ככתוב (דניאל ח) ויאמר אחד קדוש, והוא על דרך אומרו (תהלים פב) אני אמרתי אלהים אתם ובני עליון כלכם, ולצד שהקב''ה השרה שכינתו בתוך בני ישראל ועשאם בני פלטין שלו במקום המלאכים, וצא ולמד מה שאמרו בספר הזוהר (ח''ב קמ:) על זמן שהשרה הקב''ה שכינתו בתחתונים כמה היתה הרגשת בני עליון על שבחר ה' באוכלסי ישראל יותר מאוכלוסי המלאכים, ולזה צוה ה' את אוכלוסיו המובחרים שהן הנה מלאכיו ולהם יקרא קדושים וכשנכנסת' בגדר זה להיות אוכלוסי במקום המלאכים צריכין להיות קדושים. ורמז פרט זה שנכנסו במקום אוכלוסת המלאכים באומרו ה' **אלהיכם**:
@539 **איש אמו וגו'**. טעם סמיכות מצוה זו למצות קדושים. נתכוון לרמוז גם כן גדר לעריות, והוא על דרך מאמרם ז''ל (סוטה לו:) שדרשו בפסוק ויפוזו זרועי ידיו מידי אביר יעקב וגו' כי כשתקפתו אשת פוטיפר ליוסף ותקפו יצרו נזדמנה לו דיוקן אביו ואמר לו וכו' מיד ויפוזו זרועי וגו'. ושמעתי משם אנשי אמת (קב היש פ''ב) כי דיוקן האב תגביר כח הקדושה בבן ותמנעהו מבוא אל התיעוב והוא אומרו סמוך למצות העריות **אביו ואמו תיראו**, ולזה מי שתקפו יצרו יצייר בין עיניו יולדיו ויהיה לו למשיב נפש:
@539 **גם** ירמוז כי בעשותו המזימתה יבזה כבוד אביו, ולזה יצו האל סמוך למצות העריות מצות מוראו של אב ואם, הא למדת שאם גילה עריות בטל מצות מורא אב ואם שגרם להם זלזול שיאמרו ארור שזו ילד וכו', ולדרך זה הקדים האם לאב לצד שהיא נוטלת החרפה ביותר, על דרך אומרו (משלי י) ובן כסיל תוגת אמו. ולדרך זה הרווחנו טעם נכון גם בסמיכות **ואת שבתותי תשמרו**, והוא על דרך אומרו ז''ל בזוהר (ח''ב רעז ח''ג ש''א) כי ז' צדיקים יתכנו להם ז' ימי השבוע, ואמרו בזוהר חדש (ריש פ' תולדות) כי יום שבת הוא כנגד יוסף הצדיק, והוא סוד השלום ולזה אנו אומרים שבת שלום ואנו מברכין הפורם סכת שלום, והיא בחינת יסוד הכל ויוסף לצד צדקתו אשר שמר אות ברית קודש מגשת אל הטומאה ירש בחינה זו. והוא מה שאמר כאן **ואת שבתותי** ב' שבתות א' שמירת עצמו מלטמא אות ברית קודש, וא' שמירת שבת ושניהם בחינה אחת, ולזה נקראים שניהם אותות, בשבת אמר (תשא לא יג) אות היא ביני וגו'. ובמילה אמר (לד יז יא) והיה לאות. ותדע כי ב' הבחינות בערך המעשי הם ב' אבל בערך המסובב מהם הוא בחינה אחת והשומר אחד מהם יסובב התיקון והתקשרות נפשו בב' המצות, ולזה אמר **ואת שבתותי**:
@539 **ואביו תיראו**. בתורת כהנים אמרו שבמקום אחד הקדים הכתוב אב לאם דכתיב (יתרו) כבד את אביך ואת אמך וגו', ובמקום אחר הקדים אמו וכו' לומר ששניהם שקולים אבל אמרו חכמים האב קודם לאם. גם הברייתא הובא בקידושין דף ל''א דרש רבי וזה לשונם גלוי וידוע לפני מי שאמר והיה וגו' שבן מכבד לאמו וכו' לפיכך הקדים כבוד אב וכו' וגלוי וידוע וכו' שהבן מתירא מאביו וכו' לפיכך הקדים ה' מורא האם וכו' ע''כ. וקשה לי לב' הדרשות, כי כשנשכיל בענין בב' הכתובים החשיב הכתוב האב יותר מהאם בפסוק כבד וגו' הסמיך האב לכבוד באומרו כבד את אביך, גם בפסוק זה הסמיך האב למורא באומרו ואביו תיראו, ובדרך הזה מצינו לרז''ל שדרשו בכמה מקומות. והן אמת אם לא היה דין יוצא מדרך זה הייתי יכול לפרש הכתוב כדברינו שכבר הרשות נתונה לנו לפרש הכתוב הגם שיהיה בסדר אחר משונה מדברי הראשונים כל שאין הדין משתנה, אבל במה שלפנינו ישתנה הדין, אם נתגרשה האם, כי לפי מה שפרשנו שהתורה הקדימה בב' המקראות האב לאם אם יאמר אביו השקינו מים ואמו אומרת השקיני מים אם להקדים אביו לאם, ולדברי רבותינו שאמרו שהם שוים אלא לצד שהוא ואמו חייבין בכבוד אביו אם נתגרשה שאין טעם זה רצה יקדים לאביו רצה יקדים לאמו. וכן אמרו שם בקידושין בשאלת בן אלמנה אחת את רבי אליעזר ורבי יהושע, וזה לשונם נתגרשה מהו אמר לו הטל להם מים בספל וכו' ע''כ. הרי לסברת ר''א שקולים הם ממש. ואולי כי לפי מה שדרשו ז''ל שם בתורת כהנים וזה לשונם איש אין לי אלא איש אשה מניין תלמוד לומר תיראו אם כן למה נאמר איש מפני שהאיש סיפק בידו אשה אין סיפק בידה לעשות ע''כ, הנה לדברי ברייתא זו נאמר איש למעט אשה בענין הכבוד אמור מעתה שלענין הכבוד נאמר איש אמו וגו', ובאם אינו ענין, וכפי זה ישנה להקדמת אם בבחינת הכבוד, וכל זה ליישב ברייתא דתורת כהנים. אבל לדרשת רבי שדרש שהקדים הכתוב אם לאב בבחינת המורא וכו' עדיין קשה. ואולי כיון שאין זה אלא דרך אגדה ואין יוצא מזה דין הדרשה תדרש, שהרי סוף סוף הקדים הכתוב אם לאב שהיה לו לומר איש יירא אמו ואביו, והגם שהוכרח הכתוב לדבר בסדר זה לומר איש למעט אשה מחיוב הכבוד ולומר תיראו לרבות בבחינת המורא, אף על פי כן סוף סוף הרי סדר האם קודם לאב והאגדה נתלית ברמז כל שהוא:
@539 **עוד** נראה לומר כי התנאים לא נראה להם לומר שלצד שהסמיך הכתוב זכרון המורא לאב יהיה גדול מהאם. מטעם שהכתוב הוכרח במעשיו לדבר בסדר זה איש וגו' תיראו כדי שנדרוש מיעוט ורבוי בנשים, וכיון שכן נאמר בפה מלא שהקודם בפסוק הוא הראשון, ואמר תיראו לבסוף לא להסמיך לה האב כדי שיהיה במעלה יותר מהאם אלא לדרוש ממנה רבוי חיוב האשה במורא הורים:
@539 **עוד** נראה לומר טעם שאמר לשון יחיד וגמר אומר לשון רבים, נתכוון לומר כי כשהבן יהיה ירא מאביו גורם גם כן שבנו יהיה ירא ממנו, איבעית אימא למה שקדם בדברינו במקומות אחרים (ויחי מט ג) כי שורשי הקדושה ונגדיהם הנמצאים במוליד יעשו כיוצא בהם בנולדים. ואיבעית אימא מדרך המוסר כי כשיראה הבן שאביו מזלזל בכבוד אביו יפקע כלילת מוראו גם כן ממנו, וכשאדם ירא מאביו וכו' הבן לוקח מוסר. גם ישרישו בנפש הבן בחינת מפעל הטוב, ונמצא מקיים ב' מוראים, והוא אומרו **איש** לשון יחיד **תיראו** לשון רבים, כי במורא א' יראים ב', וזה אומרם (אבות פ''ד) מצוה גוררת מצוה:
@539 **או** יאמר על דרך מה שפסק הטור סימן ר''מ וזה לשונו ונראה לי כיון שהוא רשע אינו חייב בכבודו כדאמרין (ב''ק צד:) גבי הניח להם פרה גזולה חייבין להחזיר משום כבוד אביהם, ופריך בש''ס והלא לאו עושה מעשה עמך ואין חייבין בכבודו, ומשני כשעשה תשובה, אלמא כל שלא עשה תשובה אין חייבין בכבודו עכ''ל. סובר הרב שאין להחזיקו בעשה תשובה אלא כשראינוהו שעשה דוקא. והוא מאמר הכתוב **איש אמו ואביו** פירוש איש שמתנהג עם אמו כמנהג אב ואם לזה תיראו אבל מי שמזלזל בכבוד אביו ואמו פטור ממורא. ותיבת אמו ואביו חוזרת לאיש המוליד ונמשכת גם כן לתיראו להגיד על מי באה מצות תיראו והבן. וגם לפי מה שכתבתי בחבורי פר''ת והעמדנו דברי רמב''ם שכתב שמן הסתם מוחזק בחזר בתשובה, והוכחתו מההיא שאמרו בש''ס (קידושין מט) באומר לאשה הרי את מקודשת לי על מנת שאני צדיק גמור וכו' שאנו אומרים עשה תשובה הגם שלא ראינוהו שעשה וכו', ודחינו ראית הטור שהביא מהניח להם אביהם פרה גזולה, כי שאני ההוא שמעשיו מוכיחים שלא חזר בתשובה שהרי עודנה לפרת חטאתו עומדת חיה אף כי אחרי מותו, אבל כל שאין הוכחה כזו מן הסתם יעמוד בחזקת שחזר, גם לפי זה יעמדו דברינו בזמן שאנו רואים ודאי שאינו מכבד ואין מקום לחוש לתשובה, וכדומה להניח פרה גזולה, איש כזה פקע כבודו ומוראו מבניו כאשר עשה:
@539 **עוד** ירצה על דרך אומרם ז''ל בההיא עובדא דההוא גברא וכו' ושמע ושמתיה משום לפני עור לא תתן מכשול, והוא מאמר הכתוב כאן תיראו לשון רבים הגם שלא צוה אלא לאחד דכתיב איש אף על פי כן המצוה מוטלת על הירא ועל המתירא לבל יגרום למצוה שלא ירא שלא יסובבהו ליכשל:
@539 **ואת שבתותי תשמרו וגו'**. רז''ל אמרו (ב''מ לב:) מנין שאם אמר לו אביו חלל שבת וכו' שלא ישמע לו דכתיב איש אמו וגו' ואת שבתותי וגו' אני ה' שאתה ואביך חייבין בכבודי ע''כ. הנה לטעם אתה ואביך וכו' שדרשו מאומרו אני ה' מובן כי כמשפט הזה יהיה בכל מצות התורה הגם שאינם חמורים כשבת כגון השבת אבידה וליטמא למתים, אם כן למה לא הסמיך אלא מצות שבת שהיא חמורה שהיה לו להסמיך מצוה אחרת קלה, גם בזה לא היה צריך לנתינת טעם אני ה' להביא ממנה שאר מצות קלו'. ויתבאר על פי מה שכתב רמב''ם בפרק ה' מהלכות ממרים וזה לשונו היו אביו ואמו רשעים גמורים וכו' אסור לו להכותם וכו' ע''כ. ודייקו כל האחרוני' כי דוקא להכותם אסור אבל כבודם ומוראם אינו חייב בו. והעליתי בחיבורי על יורה דעה בישוב דברי רמב''ם עם מה שכתב הפרק ז' מהלכות ממרים שחייב לכבדם, כי לא כ' כן אלא במי שעבר קצת עבירות לתיאבון באקראי, וכאן מדבר במי שהוחזק ברשע גמור, ולזה דקדק בלשונו רשעים גמורים ולא הספיק לומר רשעים. וסובר אני שרשעים גמורים הם עוברים על כל העבירות הבאות לידם אלו אינו חיוב על הבן לירא מהם ולכבדם. והוא מאמר הכתוב כאן **איש אמו ואביו תיראו** ותנאי הוא הדבר **ואת שבתותי תשמרו** כלכם אבות ובנים, ודוק מינה שאם האבות לא ישמרו שבתות ה' הרי פקע מצות מוראם כי שקול שבת כנגד כל התורה כולה (שמו''ר פכ''ה י''ב) ונקרא רשע גמור:
@539 **עוד** יתפרש כל הכתוב בדרך רמז בהעיר עוד למה אמר **שבתותי** לשון רבים ולא לשון יחיד כדרך הרגיל בכל התורה. ורז''ל אמרו (שבת סט:) שבא ליתן שמירה אחת לשבתות הרבה, והכוונה בזה שאם עשה מלאכות הרבה בשבתות הרבה בהעלם שבת אינו חייב אלא חטאת אחת. ונראה על דרך מה שאמרו בספר הזוהר (כ''א ה:) כי שבתותי ירמוז ללילה וליום, וזה לשונו דא שבתא ומעלי שבתא כי לילה כיום יתקדש, ולצד שבחינת לילה אינו שוה לקדושת יום כי הלילה הוא בחינת אור המתיחס אליו כלה והוא בחינת שמור, והיום הוא בחינת אור עליון המתיחס אליו בחינת חתן המשפיע באור הלילה כידוע ליודעי חן ולזה יתיחס אליו זכור, ולזה אמר בזוהר (ח''ב פ''ח) כי סעודת לילה היא סעודת חקל תפוחין קדישין וסעודת יום היא סעודא עתיקא קדישא אב הרחמים, ולזה יקרא קידוש היום בלשון חז''ל (פסחים קו.) קידושא רבא.
@539 ושמעתי גם ראיתי כתוב (בסוף שו''ע האריז''ל) מעשה שבימי ראב''ע עמד טועה אחד וכתב בראיות כי יום שבת יקדים בו היום ואחר כך הלילה ונתגלה הדבר להרב על ידי נס וסתר מועצותיו וכו' דרשו מעל ספרו (אגרת שבת), וכנגד דעת טועה זו דבר הכתוב ואמר **איש אמו ואביו תיראו** הקדים אם לאב והשוה למצוה זו מצות השבת ואמר **ואת שבתותי** שהם לילה ויום וכו' לומר שגם בהם יקדים בחינת האם שהיא לילה לבחינת האב שהוא היום, שכסדר הורים כן סדר שבתות מעלי שבתא ושבתא ולא כדעת הטועים הנזכרת:
@540 **אל תפנו**. אומרו לשון פניה, לאסור מחשבת עבודה זרה, שלא יהיה פונה בדעתו לחשוב בה. ולהשכילך על דבר אמת דע כי בחינת אלהים אחרים תתיחם לה בחינת אחוריים, וכשהאדם חושב בה הם פונים אותם לצד פנים, והמשכיל יבין:
@540 **האלילים**. אמר לשון רבים, לצד שבחינת הרע היא בחינת הפירוד ואין חלק בה שיהיה לאחד, ולזה כשיזכיר הכתוב אלהים אחרים יזכירם בכינוי רבים:
@540 **ואלהי מסכה וגו'**. קשה והלא צוה בדרך כלל על כל האלילים שלא לפנות להם, ומה צורך לחזור ולצוות על זה. עוד למה אמר **לכם**. ואולי שיכוין למה שאמרו ז''ל (תיקונים יח) כי בעשות האדם מעשה הגון תשרה עליו שכינה, ובעוברו פי ה' האבר שבו חטא שורה עליו רוח הטומאה, והוא מסך המבדיל בינו ובין אלהיו כדרך אומרו (ישעי' נט) עונותיכם מבדילים וגו', והוא מאמרו כאן **ואלהי מסכה** פירוש אלהים שהם מסכים מבדילים אתכם ממקור החיים לא תעשו אותם לכם, הא למדת שהפונה לעבודה זרה גורם מסך המבדיל בינו ובין קונו, ולזה גמר אומר **אני ה' אלהיכם** לומר ממי הוא נבדל מצד המסך הלז:
@540 **עוד** יכוין באומרו אני ה' אלהיכם כי במה שישמור עצמו מאיסור זה של עבודה זרה בזה ה' אלהיו על דרך אומרם (חולין ה.) כל הכופר בעבודה זרה כמודה בכל התורה כולה. ובדרך רמז יכוין על דרך אומרם ז''ל (מגילה כח.) בפסוק לולי פני יהושפט וגו' מכלל שאסור להסתכל בפני אדם רשע, והוא אומרו כאן **ואלהי מסכה לא תעשו לכם** פי' לא תעשו עצמיכם אלהי מסכה שאסור להסתכל בכם:
@544 **ונכרתה וגו'**. יש לתת טעם למה יהיה חמור עונש כהן אוכל קדשים חוץ לזמנם חיוב כרת יותר מאוכל נבילה וטרפה ושקצים. דע כי מן הטעם עצמו שאמרו (ב''מ קיד:) ישראל מטמא באוהל ואין עכו''ם מטמאין באוהל לצד שישראל הם בחינת הקדושה ולזה כשמסתלקת ממנו הקדושה כל הקליפות מתקבצים יחד ובאים עליו. והוא הטעם עצמו במה שלפנינו, כי לצד שהקדשים ישנם במעלה שאין למעלה ממנו, כשעבר זמן אשר צוה ה' בו מסתלקת הקדושה ושורה עליו טומאה גדולה אשר כורתת נפש אוכלתה, מה שאין כן בטומאת אכילת שאר איסורים כנבילות וטריפות שקצים וכו' שאין כח בטומאה ההיא להכרית הנפש, ומתטהרת במלקות. ואומרו **כי את קודש ה' חלל** שנראה שיקפיד על בשר הקודש ולדברינו יקפיד על נפש האוכל' דבר טומאה. אולי כי לצד שעל ידי אכילת הבשר הוא משלים מעשה השלמים, לזה כשאוכלים הבשר יש בזה חילול הקודש שגומר מה שכבר נעשה על ידי מעשה זה, והוא בשר טמא ומחלל את אשר כבר בא בקודש מהדם והחלבים, וזו גם כן סיבה להשראת טומאה גדולה על הבשר ההוא, כי בחינת הרע תקוה ותשאף למקום הסבוך וסרוך לקדושה:
@545 **ובקצרכם וגו'**. טעם שהתחיל לדבר בלשון רבים וגמר אומר בלשון יחיד **לא תכלה**, נתכוון לשלול דעת טועים אשר אומרים כי כשאין דבר מספיק לעניים אין לו ליתן, על דרך אומרו (מלכים ב ד) מה אתן זה לפני מאה וגו', לזה צוה ה' בלשון יחיד לומר שאפילו אחד לבד עליו חובת פאה, הגם כי פאה של אדם אחד מועטת היא לכל עניי ישראל, וכמו כן במצות לקט ופרט ועוללות אמר לשון יחיד מטעם הנזכר. וטעם סמיכות מצוה זו לעונש כרת. אולי שרמז שלא יאמר אדם אם הזיד ונתחייב כרת מעתה אין לשמור עצמו מכל אשר יזדמן לפניו במעשה הרע כי כבר נתחייב כרת, לזה אמר **ובקצרכם את קציר ארצכם** פירוש כשגרם עד שנקצר קציר ארצו שהוא כרת האמור בסמוך **לא תכלה פאת שדך לקצור** אותה במעשים רעים אחרים. והודיע בזה שלא תכרת כל הנפש אלא הענף שבו רמוז מצוה זו, ועדיין ישנה לראות אחרים דבוקים בשורשם, כי כל נפש ישראל יש לה שרשים למעלה כנגד כל מצות התורה ואמר **ולקט קצירך** וגו', פירוש אפילו בענף החטא עצמו לא יוסיף לחטוא, כי יש לך לדעת מאמר הרב האר''י ז''ל כי בטבע הקדושה להשאיר במקום שתהיה בו רושם. ואם כן הגם שנכרת עדיין יש השארות הקציר שם, והוא שצוה עליו **ולקט קצירך לא תלקט** ברוב פשעים, כי ה' חפץ שבאמצעות הלקט ההוא יתעורר וישוב בתשובה לפני ה' וירחמהו, כי הלא תמצא שאמרו ז''ל (יומא פו.) שאפילו עבר אדם על כריתות ומיתות בית דין תשובה וכו' מכפרין, וכמאמר הנביא (הושע יד) שובה וגו' עד ה' אלהיך ודרשו ז''ל (שם) גדולה תשובה שמגעת עד כסא הכבוד פירוש שהגם שנכרת החוט המחבר עד כסא הכבוד ולא נשאר אלא חלק קטן בקרבו התשובה מגיעתו עד כסא הכבוד:
@547 **לא תגנובו וגו'**. סמך מצות גניבה למצות פאת שדה. אולי שנתכוין על דרך מה שאמרו בתורת כהנים (כאן) וזה לשונם בן בג בג אומר לא תגנוב את שלך מהגנב שלא תראה כגונב ע''כ. וכאן נתכוין במה שסמך לא תגנובו לפאה, שבא עליה באזהרה לבל יגנוב אותה בחושבו כי שלו הוא לוקח. ופירוש ג' לאוין אלו הוא, **לא תגנובו** זה הלוקח ממון חבירו שלא מידיעתו.
@547 **לא תכחשו** זה הבא לידו ממון חבירו בהיתר ומכחיש כשתובעו ממנו.
@547 **לא תשקרו** זה הבא לידו ממון חבירו בעדים והוא מכחיש, הגם שלא תועיל לו הכחשתו לענין ממון, הרי זה עובר משום לא תשקרו:
@547 **עוד** ירמוז שאם אדם עבר על הראשונה וגנב, הקב''ה יזמין לו מכירין, על דרך אומרם ז''ל (חגיגה טז. במד''ר פ''ט) העובר עבירה בסתר הקב''ה מכריז עליו ומפרסם רשעתו, ואם כן אם גנב ה' יזמין מי שידע בגנבתו, ומצוה אותו ה' שלא יכחיש, והוא אומרו **לא תכחשו**, ומדבר הכתוב באופן שיכול להכחישו כגון שאין כאן אלא עד אחד, אם הודה מה טוב ואם הכחיש הרואה, הקב''ה יזמין לו עד שני שיעיד עליו שאינו יכול להכחיש, ואם יכחיש שקר בימינו ולא יועילו שקריו, והוא אומרו **לא תשקרו** שמלבד שלא הועילו מעשיו הנה הוא עובר גם על לאו זה. וטעם אומרו לשון רבים מה שלא אמר בסדר זה עד עתה גם במצות הסמוכות מלאחריו אמר לשון יחיד דכתיב לא תעשוק וגו'. ונראה שנתכוין להזהיר גם בזמן שיכיר אחד בחבירו שגנב או כחש וכו' שלא יאמר אעשה כן גם אני להציל את שלי, לזה אמר לשון רבים **לא תגנובו** פי' הגם שהוא גנב לא תוסיף אתה להרשיע כמוהו ותעשו שניכם גנבים. וכמו כן אם יכחיש חברך לא תוסיף גם אתה עשות כמוהו ותכחשו שניכם. וכמו כן אם שקר בך חברך וכו', ואמר **ולא תשבעו** ג''כ שלא יאמר אם הוא מכיר שחבירו נשבע לו לשקר הריני נשבע להציל ממוני ממנו, ונשבעין לאנסים, שהרי אתה מחלל שם וכו', ולזה גמר אומר לשון יחיד, לומר שמדבר עם מי שמציל ממון עצמו בשבועה, ואין צריך לומר הנשבע ראשון הרמוז בכלל לא תשבעו. עוד יכוין באומרו **לא תשבעו** להזהיר גם למשביע אם יודע שחברו נשבע לשקר שלא ישביעהו, ואינו בחילול אלא הנשבע לזה אמר **וחללת** לשון יחיד:
@549 **לא תעשוק וגו'**. הכונה, להיות שצוה ה' על נוטל ממון חבירו שלא בידיעתו, אל יאמר אדם שלא הקפיד אלא בדרך גניבה אבל גזילה ועושק אשר ידע האדם בהם אין אזהרה, לזה חזר לצוות גם על נוטל ממון חברו בידיעתו כאונם, ולא גזילת ממון בהחלט לבד אלא אפילו עכבת ממון שכיר אסור. וטעם אומרו **רעך**, נתכוון לשלול טענת היותו ריעו ובאמצעות זה יתן יד בממונו ויאמר כרע כאח לו בינו לבין עצמו ימחול לו ולא יחפוץ להענישו, ולצד שאין באזהרה זו אלא משום דברים שבין אדם לחברו, כשהוא מוחל אין עון, לזה אמר **לא תעשוק את רעך**:
@549 **ובדרך** רמז ירמוז על דרך מה שדרשו חז''ל (ברכות לה:) בפסוק גוזל אביו ואמו וגו' זה הנהנה מהעולם הזה בלא ברכה ע''כ, והוא מאמר ה' כאן **לא תעשוק את רעך** זה הקב''ה דכתיב (משלי כז) ריעך וריע אביך שלא יגזול ברכות שהוא חייב לברך על מה שנהנה בעולם הזה, ואומרו **ולא תגזול** רמז שגם בעושק זה יש גזילה לאחרים, שהוא מה שרמז בפסוק גוזל אביו ואמו ודרז''ל (שם) אביו זה הקב''ה אמו זו כנסת ישראל, כי כשהאדם ממעיט במצוה הצריך עשות גורם רעה גם לכללות ישראל ואמר **לא תלין** שצריך לתת חוק יום ביומו, על דרך אומרם ז''ל (ויק''ר פכ''ו) שהיו לוים ביום ופורעים בלילה, והוא מה שרמז כאן לא תלין פעולת שכיר **אתך** פירוש תיבת אתך חוזרת לשכיר שהוא רוח ה' אשר נתן באדם כשכיר כתושב, ושכרו הוא עשות מצות ה':
@549 **עוד** ירמוז על דרך אומרם ז''ל כי בני תורה אין להם פרנסתם בעולם הזה וכאומרם (ילקוט משלי רמז תתקל''דד) שאמרה תורה מפני מה בני עניים, והטעם הוא שמעתי טעם נכון משם האר''י ז''ל כי אין העולם יכול לסבול רוב הטובה אשר תנתן בשביל הצדיקים לזה אינו משפיע אלא לבינונים ודרך שם יהיו נזונים בני תורה, הא למדת שאין העשירים אלא מרזב אשר הוכן להסתפקות הצורך לצדיקים, וצוה ה' לבל יעשוק האדם את ריעו שהוא הצדיק דכתיב (תהלים קכב) למען אחי ורעי ולא יתן לו את חקו, וזה עושק מפורסם:
@549 **עוד** ירמוז שלא יעשוק תיבת את שאצל ריעך שהוא הקב''ה, כמו שדרש רבי עקיבא (פסחים כב:) את ה' אלהיך תירא לרבות תלמידי חכמים. והכונה בזה לירא מהחכמים הדנים בארץ, וכיון שכן הרי יש אלהים שופטים בארץ אשר ירא מהם לקיים דבר משפט, ובזה לא יגזול כי השופט יוציא גזילה ממנו:
@551 **לא תעשו עול במשפט**. אזהרה זו באה לבעלי דינים שלא יערימו לזכות כפי הדין, והוא עול ולזה אמר בלשון רבים לא תעשו וגו', ושיעור אומרו **עול במשפט** הוא על זה הדרך, במשפט אשר ישפטו הדיינים שלא יסובבו שיהיה בו עול, כי הדיין שופט על פי הטענות אשר יסדרו לפניו, ולזה סמך מצוה זו לאזהרת לפני עור וגו' כי זה מכשיל הדיין לשפוט משפט מעוול:
@551 **עוד** ירצה לומר שהגם שהמשפט זכהו, לא יסמוך לעשות עול כשיכיר בעצמו כי עול בימינו, ולזה אמר בלשון רבים כי ידבר לבעלי דינים, ובסמוך שכוונתו לצוות לשופט אמר לשון יחיד לא תשא לא תהדר וגומר:
@551 **עוד** יכוין באומרו **לא תעשו עול** אזהרה לדיין, שהגם שהמשפט יגיד לחייב את זה ולזכות את זה אם בעיניו נראה כי הוא עול לא יעשו עול זה בשביל מה שנתחייב במשפט, אלא אין לדיין אלא מה שעיניו רואות:
@551 **עוד** ירצה באומרו **במשפט** בה''א הידיעה, על דרך אומרם ז''ל (ביצה טז.) כי בראש השנה קוצב הקב''ה לכל איש ואיש הצריך לו על משפט צדק, ולזה אם יחייבו הזכאי ויזכו החייב הנה הוא יוצא עול במשפט עליון בסך קצוב וכשמחסרו אם כן נעשה העול במשפט שלא נטל זה מה שחייב בבית דין של מעלה, וכן להיפך:
@552 **לא תלך רכיל וגו'**. קדמו רז''ל בספר הזוהר הקדוש ודקדקו כפל הדברים, **תלך**, **רכיל**, כי אחת הנה, ואמרו דרך סוד יעיין שם דבריהם באדרא (פ' נשא קכח.) ולפי פשט הכתוב נראה שיכוין לומר שלא יגרום הוא הרכילות הנעשה מהזולת על ידו, הא כיצד שלא יגלה דברים אפילו למי שאין בהם רכילות במקום שיש לחוש שהשומעים יוליכו הדברים ונמצא הוא הוליך רכילות זו שרכלו האמצעים. ולדרך זה ידוייק אומרו **בעמך**, פירוש באמצעות עמך אתה מוליך רכיל שאומרים הדברים בפניהם ומתגלגלים מזה לזה ונשמעים הדברים, ואמר **אני ה'** פירוש אני בוחן הדברים ממי יצאו תחילה ופורע:
@552 **עוד** ירצה שלא יחזיק בידי מדברי לשון הרע שבזה הוא סובב שיוליכו הרכיל ומעלה עליו הכתוב כאלו הוא הוליך רכילות לזה להיותו סיבה:
@552 **לא תעמוד וגו'**. לצד שצוה על הרכילות התנה בו שלא יעמוד על דם רעך, שאם ראה כת אחת שרוצין לרצוח חייב להודיעו לבעל דבר כדי שיציל נפשו, ולא יאמר הרי זה רכילות, הא למדת שאם לא גילה אוזן חבירו והרגוהו בטל אזהרת לא תעמוד וגו'. וצא ולמד ממעשה גדליה בן אחיקם (ירמי' מ) שגילו לו וכשלא חש היה מה שהיה:
@553 **לא תשנא את אחיך וגו'**. פירוש אם נסבב מאחיך דבר הגורם לשנאתו לא תשנאהו בלבבך אלא בפיך דבר אליו תוכחות על אשר ככה סבב, והוא אומרו **הוכח** וגו'. ואומרו **ולא תשא עליו חטא**, פירוש לא תחליט בדעתך שמה שנסבב מאחיך ברשע עשאן ועודנו עומד בחטאו עמוס על שכמו אלא תהיה דן אותו לכף זכות, ותוכיחנו ועל ידי התוכחה יהיה אחד מב' דברים, או יתן אמתלא להנעשה ואין חטא, או יתחרט על הנעשה וישוב לבל עשות כדבר הזה, והרי הוא כריע כאח לך:
@553 **עוד** נראה לפרש בהעיר עוד בשיעור הנדבר שהיה צריך לומר לא תשנא בלבבך את אחיך, שיגמור מקום השנאה שהתחיל לדבר בה ואחר כך יזכור את מי ישנא. אכן יכוין להודיע שיעור השנאה אשר ה' מצוה עליה, שלא יאמר אדם שאינו קרוי שנאה אלא שנאה גמורה לבקש רעתו ולחפוץ בכליונו, אבל הרחקה בלב אינה קרויה שנאה, לזה נתחכם הכתוב לסמוך **לא תשנא** עם תיבת **אחיך** לומר כי השערת השנאה אשר יצוה ה' עליה היא הנרגשת בערך אח, ושיעור זה כל שירחיקהו מלבו קצת הנה הוא יורד ממדרגת אח, והרי הוא עובר משום לא תשנא:
@553 **עוד** ירצה בהעיר למה באזהרת לא תשנא דקדק לומר את אחיך ובאזהרת הוכח תוכיח אמר את עמיתך שנראה שמדבר בב' נושאים:
@553 **אכן** יתבאר על דרך אומרם ז''ל (תיקונים ה' תדבא''ר פ''ג) אם ראית תלמיד חכם שעבר עבירה ביום אל תהרהר אחריו בלילה כי ודאי עשה תשובה גם מצינו שאמרו ז''ל (פסחים קי''ג:) בפרשת כי תראה חמור שונאך וגו' שהכתוב מדבר במי שראה בחברו רבר מגונה שמצוה לשנאותו. וכאן צוה הכתוב שאם ראה דבר מגונה בתלמיד חכם אינו נכלל בגדר אותם שצוה ה' לשנאותם אלא צריך להחזיקו כי ודאי עשה תשובה, והוא אומרו **לא תשנא את אחיך** שהוא תלמיד חכם המתכנה בשם אח דכתיב (תהלים קיג:) למען אחי ורעי. או על דרך אומרם את ה' אלהיך תירא לרבות תלמידי חכמים, כמו כן כאן **את אחיך** פירוש המתרבה מאת אחיך, ותיבת אחיך חוזרת על הבורא ב''ה שנקרא אח לישראל (מי שוחר טוב כ''ג) כביכול. ואומרו **הוכח תוכיח** מדבר בנושא אחר שהם המון העם, ולזה אמר **את עמיתך** ולא אמר הוכח תוכיחנו וחוזר לאחיך שאמר בתחילה אלא לומר שאינו מדבר במה שהתחיל לדבר בו שהוא תלמיד חכם אלא כהמון העם שמצוה לשנאותו מצוהו ה' שיוכיחנו על פניו למה תעשה כה בנעימות לשון בחיבה וברכות לשון. ואומרו **ולא תשא עליו חטא**, פירוש שלא ימנע ממנו התוכחות שבזה ישאר במשא חטאו ולא ישוב אל ה', הא למדת שאם לא הוכיחו בטל עשה דהוכח ולא תעשה של ולא תשא:
@553 **עוד** ירצה על דרך אומרם ז''ל (כתובות קה:) האי צורבא מרבנן דסנו ליה בני מאתיה משום דמוכח להו במילי דשמיא. ומעתה יאמר החכם למה לי קנאה למה לי שנאה ותחרות עם זרע ישראל ואחדל מהוכיח ואהיה אהוב ונחמד לכולן, לזה נתחכם ה' וקודם שצוהו להוכיח צוה לבני ישראל שלא ישנאוהו ואחר כך צוהו להוכיח שהרי ישראל מוזהרים מה' לבל ישנאוהו. ואם תאמר ומי יערבנו לעם שלא ישנאוהו וישמרו מצות לא תשנא, לזה אמר **ולא תשא עליו חטא** פירוש שלא יחשדם בחטא זה אלא יחזיקם בכשרות. ואומר לשון יחיד לשלול החשד אפילו מיחיד שיחזיק כל איש ישראל שלא ישנאו בשער מוכיח, ובזה יוכיח ויחזור ויוכיח עד שיקבלו מוסרו:
@553 **עוד** ירצה על דרך אומרם ז''ל (שבת לג:) בעון הדור נתפסים גדולי עולם, וכן הוא אומר (שה''ש א) אשכול הכופר וגו', ולצד זה חש הכתוב שתכנס בלב קרובי ה' הרחקת הלב על מעשה ה' זה, כי יאמרו שאינם מובטחים בחייהם ובשלוותם הגם כי יפליאו להטיב מעשיהם, לזה בא דבר ה' כאן ואמר לצדיקיו לא תשנא את אחיך בלבבך, פירוש אחיך זה הקב''ה, ויש לך לדעת שלא לכל ישראל בהשוואה יקרא הקב''ה אח אלא להקרובים והדבקים בה' כרבי עקיבא וחביריו, וצוה להם שלא יתרחק לבם מה', שההרחקה היא ענף השנאה. ואם תאמר מה אשיב אל לבי לבטחון בחיי ובשלוותי, לזה אמר **הוכח תוכיח את עמיתך** ובזה לא תשא אתה עליו פירוש בשבילו חטא, כי כלום טעם תפיסת הצדיק הוא בשביל עון הדור אם יוכיחנו הרי הוא ניצול ממה נפשך, אם חזרו בתשובה הרי אין כאן עונות שיתפס עליהם, ואם לא חזרו הרי נפטרת מתפיסה, כמו שגילה סודו ביד עבדיו הנביאים דכתיב (יחזקאל לג) ואתה כי הזהרת רשע וגו' הוא רשע בעונו ימות ואתה את נפשך הצלת. ולדרך זה נתיישבו כל הדקדוקים שדקדקנו בפ ס וק:
@553 **שוב** בא לידי תנא דבי אליהו (רבה פי''ח) וזה לשונו וכי באחים מן האב והאם הכתוב מדבר אין הכתוב מדבר אלא כנגד הקב''ה שאין לו אחים לא בעולם הזה ולא בעולם הבא ולא לימות המשיח אלא צדיקי עולם שעושין רצונו בתורתו בכל יום שקרא אותם אחים וריעים עכ''ל, ותדע שמעלת אח יותר ממדרגת בנים, כמאמר ז''ל (שה''ש פ''ג) לא זז מחבבה עד שקראה בתי לא זז וכו' עד שקראה אחותי:
@554 **לא תקום וגו'**. רז''ל (תו''כ כאן יומא כג.) אמרו נקימה הוא שעושה לו כמעשהו הרע נטירה שלא יאמר לו לא אעשה לך כמעשיך. וכפ''ז נתן טעם הכתוב למצוה זו בסמיכות ואהבת לרעך כמוך, פירוש כי ה' חפץ שתהיה אוהב רעך כמוך ואם אתה אומר לו כן הרי גלית דעתך כי טמון היה בלבך מעשהו בלתי הגון לך, ונתן טעם לדבר אני ה', פירוש על דרך אומרם (זוהר ח''ג טז) שבאמצעות יחוד הלבבות מתייחד שמו יתברך להיות שכנסת ישראל הם ענפי שם הוי''ה ב''ה דכתיב (דברים לב) כי חלק ה' עמו, ונתחכם ה' לצוות בענין הנהגת ישראל זע''ז בהדרגה. מצוה א' לא תשנא. ב' לא תקום וגו'. ג' ואהבת, ודקדק לומר, אחיך, עמך, לומר שאין מצוה אלא על אנשים שעושים מעשה עמך, אבל שונאי ה' כגון המומרים והאפיקורסים אסור לאהוב אותם ואדרבה צריך לשנאותם, כאומר (תהלים קלט) הלא משנאיך ה' אשנא:
@555 **את חקותי וגו' בהמתך וגו'**. בתורת כהנים אמרו וזה לשונם אין לי אלא בהמתו, בהמת חבירו מנין, תלמוד לומר את חקותי ע''כ. וקשה אם כן למה הוצרך הכתוב לומר **בהמתך** היה לו לומר בהמה לא תרביע כלאים ואז לא היה צריך לרבות בהמת אחרים. וראיתי להרב בעל קרבן אהרן שכתב בזה שדבר הכתוב בהווה. ואין דבריו נראים לי, כי לא ידבר בהווה במקום שיש לטעות ויצטרך להוסיף דברים להסיר הטעות:
@555 **ונראה** בהעיר בסדר הכתובים למה סמך הכתוב מצות הרבעה למצות אהבת ריעים, ומי יודע לסדר סדר מתאים כה' אלהינו. אכן לצד שצוה ה' על אהבת החברים והתקשרות לבם יחד כי חפץ ה' התקשרות ענפי הקדושה, ומזה יאמר אדם כי לא יקפיד ה' על הרבעת טהורה עם טהורה, לזה בא הכתוב ואמר כי אין הרצון בזה לקשר בהמה עם בהמה ואפילו בב' ענפי הטהרה הגם ששניהם מין טהרה, ולזה דקדק לומר בהמתך פירוש בהמה הטהורה לך לאכילה, ותמצא שבתורת כהנים דרשו וזה לשונם אין לי אלא בהמה עם בהמה, טהורה עם טמאה, טמאה עם טהורה מנין, תלמוד לומר את חקותי תשמרו עד כאן, הנה שסובר התנא כי בהמתך היא בהמה טהורה ואם לא אמר הכתוב בהמתך לא הייתי יודע שהטהורה בכלל ואדרבה יוכשר המעשה לצד שהוא התקשרות מין טהרה, והגם שהיה ה' מרבה איזה ריבוי הייתי דורשו באחד משאר תערובת טמא וטהור:
@559 **וכי תבואו אל הארץ וגו'**. ג' מצות נאמרו כאן. א' ביאת הארץ על דרך אומרם (כתובות קי:) הכל מעלין לארץ ישראל וכו'. ב' לנטוע כל עץ מאכל לשבח הארץ. ג' לנהוג שני ערלה:
@559 **עוד** ירמוז באומרו **וכי תבאו אל הארץ** שלא תהיה הכוונה לתיאבון המורגשות אלא תהיה כוונת הביאה אל הארץ לחיבוב ולחשק הארץ הקדושה אשר בחר ה' בה הר ה' שמה, ואמר כי אין כוונת דיבור זה להחליט המניעה מהשתדל בישוב הארץ אלא ונטעתם וגו', הא למדת שמה שהתנה במאמר אל הארץ הוא בבחינת תכלית המחשבה שתהיה למעלת הארץ במושכלות לא להנאת הגוף ואולי שרומז באומרו **עץ מאכל** על בני תורה שגם הם נקראו נטעים, כמו שאמר ר' יוסי (שבת קיח:) ה' בעילות בעלתי וה' נטיעות נטעתי, ונקראים גם כן עץ דכתיב (ישעי' ס''ה) כימי העץ ימי עמי, וכמו כן דרשו בזוהר (ח''ג רב) בפסוק לא תשחית את עצה שמדבר באדם בן תורה, ויצו ה' שתהיה עיקר הכנסת הארץ לנטוע בה עץ מאכל שהם בני תורה כי אוירה של ארץ ישראל מחכים ומטהר הנפש (ב''ב קנח:), ונקרא בן תורה עץ מאכל כי ממנו מזון לנפש. וצא ולמד ממעשה של ר' עקיבא (מם' כלה רבתי פ''ב) שלמד תורה לאותו תינוק שהיה אביו מת ונתון בצרה גדולה ומיום שפתח פיו בדברי תורה נהנה אביו בעולם העליון:
@559 **ואמר** ג' שנים **יהיה לכם ערלים**, פירוש אטומים שלא יצא מהם צפצוף תורה שהוא פרי מאכל (תנחומא קדושים יד) שעד שלש שנים אין התינוק יכול לדבר, ובשנה הרביעית שהתחיל לדבר ילמדו לומר תורה צוה לנו, שמע ישראל, וזה יקרא קודש הילולים, ובשנה החמישית תאכלו את פריו כמאמרם ז''ל (אבות פ''ה) בן ה' שנים למקרא, ויתחיל להיות עץ מאכל. וסמך הכתוב לזה מצות **לא תאכלו על הדם**, רמז הכתוב שלא יהיה סיפוקו במאכלו על סיבת הדם שהוא גשם האדם ותכונתו אלא לתכלית המושכל הרמוז בעץ מאכל. וסמך לזה גם כן מצות **לא תנחשו**, כי תכלית אכילת הדם הוא חלק הנחש, בסוד (ישעי' סה) ונחש עפר לחמו, והוא אוכל כל גשם האדם עד כלותו, והוא אומרו **ולא תעוננו** על דרך אומרו (איוב ז) כלה ענן וילך כן יורד שאול לא יעלה, ופסוק זה מדבר בהולך אחר המורגש להרבות חלב ודם:
@562 **לא תאכלו על הדם** סמך הכתוב מצוה זו למצות ערלה, לרמוז מה שאמרו ז''ל (מדרש תלפיות) כי אדם הראשון חטא באכילת עץ הדעת קודם זמן התירו שהוא בחינת ערלה, שאם היה ממתין עד ליל שבת קודש היה מקדש על היין, וזה הוא סוד דבריהם ז''ל שאמרו (סנהדרין לח:) אדם מושך בערלתו היה זו היא ערלתו, והוא מה שאמר הכתוב סמוך לאזהרת וערלתם ערלתו **לא תאכלו** פירוש מפרי ערלה, **על הדם** פירוש על סיבת הדם, כי זו סיבה לכל שפיכות דמים דם אדם ודם זרעיותיו, ויש לך לדעת כי סבת הערלות ועקרם זה מקורם שזולת חטא אדם לא היתה ערלה בעולם לא של צומח ולא של בעלי חיים:
@563 **לא תקיפו וגו'**. בהקפת הראש אמר לשון רבים ובהשחתת הזקן אמר לשון יחיד. לומר שישנו באזהרת לא תקיף הגם שאינו באזהרת לא תשחית, כגון מי שעדיין אין לו חתימת זקן, שלא תאמר כיון שאינו בלא תשחית אינו בלא תקיף כדרך שדרשו (קידושין לה:) במשפט הנשים שאינן בלא תקיפו כיון שאינם בלא תשחית. ואם תאמר ומה ראית לרבות אלו ולמעט אלו, מרבה אני הזכרים שישנם בלא תשחית כשיגדלו, וממעט אני הנשים שאין במינם לא תשחית:
@564 **ושרט לנפש וגו'**. אומרו **לנפש**, לומר הגם שהשרט חיבול הגוף הוא על פרידת הנפש היקרה. ודקדק לומר **לא תתנו בבשרכם**, הודיע הכתוב כי לא יפגום פגם זה בנפש אלא בבשר שהוא נרתק הנפש, והטעם לצד שאדם בהול על מתו אין המעשה פוגם כל כך כעושה בשאט בנפש ובישוב הדעת, ולזה תמצא שאמר הכתוב אחרי זה **וכתובת קעקע לא תתנו בכם** ולא אמר בבשרכם לומר שלא בבשר לבד יגרום הפגם אלא גם בפנימיות האדם לצד שאינו עושה מצד צער וחום הכאב שנאמר בו (ב''ב טז:) אין אדם נתפס על צערו. ואמרו **אני ה'** יתבאר על פי מאמר האלהי הרשב''י (זוהר ח''ג רמז) כי תיבת אני תגיד על כסא כבודו יתברך אשר אנו קוראים שכינתו יתברך, ושם הוי''ה ב''ה הוא מלך יושב על כסא המלכות, ורמז בזה כי יקפיד ה' על כבוד שמו יתברך, ועל כבוד שכינתו, ולדרך זה יצו ה' להאדם לבל יפגום גופו ונשמתו בב' מעשים הרשומים שהם שרט לנפש וכתובת קעקע:
@565 **אל תחלל את בתך וגו'**. פירוש יצו האל למי שיש לו בת שלא ינהג בה מנהג חולין להראותה לפני כל ולהתנאות לפניהם אלא כבודה בת מלך פנימה. והגם שיתכוין בה להנאת זיווגה כדי שיודע כי בת יפה ונעימה היא ותנשא להראוי לה, על כל זה יצו האל כי חילול הוא לה והיוצא מזה הוא להזנותה לא להשיאה כי יבער בה אש הטבעי ותחלל כבודה, ולא זו בלבד אלא שתהיה סיבה להבעיר אש בלב רואה וחומד ותזנה הארץ ולבסוף ומלאה הארץ זימה, ונמצא עון כל הרשע תלוי בצוארו, וצא ולמד מה שפירשתי בפרשת אחרי מות בפסוק (יח ב) כמעשה ארץ מצרים שחוש הראות יגדיל החפץ בדבר ויבטל כח הרצון במניעה ויטהו אל חפץ המעשה רחמנא ליצלן:
@566 **את שבתותי תשמרו וגו** '. צריך לדעת למה חזר לומר פעם ב' מה שצוה בתחלת הפרשה, ורז''ל בתורת כהנים אמרו וזה לשונם יכול יהיה בנין בית המקדש דוחה את השבת תלמוד לומר את שבתותי תשמורו וגומר ע''כ, דבריהם ז''ל יוציאו אותנו מקושי הסמיכות, אבל קושי הכפל במקומו מונח שהיה לו לכתוב ומקדשי תיראו סמוך למאמר ואת שבתותי תשמרו האמור בתחלת הפרשה ולא היה צריך לומר פעם ב' ואת שבתותי וגו':
@566 **ונראה** כי מצוה זו קשורה עם מה שלפניה, כי לצד שצוה ה' לאב לבל יחלל בתו להזנותה לפעמים ימצא כי הבת מעצמה תחלל כבוד עצמה וכבוד אביה לזנות ואין יד האב באמצע לזה צוה ה' לאב שיעשה שמירה לבל תזנה הבת כי הכל תלוי במוליד, ולהיות שיש שלש סיבות אשר יפעילו הולדת טבע רע בנולדים, האחד אם בשעת הזיווג יכוין אל הנאת המשגל לא לסיבת מצות הבורא לקיים המין זה יוליד בנולד תגבות (רע) המין השני ממנה פירוש מצד שהאשה מעשיה לא טובים רחלא בתר תגבורת אזלא. ג' אם המולידים אב או אם חשבו בחינת הרע בהסח הדעת, וכמעשה חזקי' המלך עליו השלום (סנהדרין קד.) אשר מחשבתם סבבה הולדת בלתי הגון הגם היותם יסודי עולם. כנגד סיבה א' אמר **את שבתותי תשמורו** ע''ד אומרם בזוהר (ח''ב פט.) בפסוק לסריסים אשר ישמרו את שבתותי שהם הצדיקים המסרסים את עצמם ואינם נזקקים לנשותיהם אלא בליל שבת ומושכין לבניהם נשמות קדושים ע''כ, הרי שהרוצה להוליד בן בעל נפש טהורה צריך לסרס עצמו ולעצור כח התאב ולא יפעול אלא לתכלית המצוה בו מאת ה' ב''ה והוא מאמר ה' למנוע נפש זונה מביתו **את שבתותי תשמרו** להזדווג בהם ובזה תוליד נשמה קדושה המואסה בזנות, וכנגד סיבה ב' שהוא החשש מצד האם אמר **ומקדשי תיראו** אזהרה לירא מהמקדש ובזה תשמור עצמה האשה לבל יבאינה אל המקדש להשקותה מי המרים. וכנגד סיב' ג' סמך לזה אזהרת **אל תפנו אל האובות ואל הידעונים** הם בחינת הטומאה הרוצה ומתאוה להדבק באדם הטהור. ותיבת **אובות** לשון אבה על דרך אומרו (דברים כג) ולא אבה ה'. ורמז **ידעוני** הוא לומר שלא יחשוב יהיה ידוע אצלו, כי ידיעת הטמא מכרחת האדם להדבק בו כטבע השפל שחפץ להדבק בעליון וחושק:
@566 **ואמר אני ה' אלהיכם**, בא לתת טעם להמשך נפש רעה מסיבת החושב, כי לצד כי ה' אלהינו פירוש שוכן בתוך נפש ישראל בחשוב האדם בבחינת הרע מסתלק כח הקדושה ואין מזדמן לפניו להמשיך אלא חלק הרע, נמצא כי כל שאינו שומר עצמו מג' סיבות הוא מחלל בתו וכו':
@568 **מפני שיבה תקום וגו** ' רז''ל אמרו (קידושין לב:) מפני שיבה שהוא גדול בשנים תקום והדרת קימה שיש בה הידור, תקום והדרת פני זקן זה שקנה חכמה, קשה כפי זה היה לו לומר מפני שיבה ומפני זקן תקום והדרת. ואולי שנתכוין להמשיך ההידור לזקן זה שקנה חכמה והקימה לשיבה שהוא הבא בימים. והכוונה בזה שצריך הדרגה גדולה בכבוד החכם יותר מכבוד גדול בשנים. והגם שדרשו ז''ל קימה והידור לזה וקימה והידור לזה, על כל זה ממה שנתחכם הכתוב לדבר בסדר זה להמשיך הידור לזקן הודיענו כי גדול הידור לזקן מהידור גדול בשנים. ומעתה נמצינו אומרים שצריך לכבד החכם יותר מבעל שיבה:
@568 **עוד** ירמוז על דרך אומרם ז''ל בבראשית רבה (פס''ה) כי אברהם אבינו ביקש על השיבה כדי שיהיה ניכר האב מהבן וכו' דכתיב (בראשית כד א) ואברהם זקן, והוא אומרו **מפני שיבה תקום** ובזה אתה מהדר פני זקן שהוא אברהם דכתיב ואברהם זקן שעל ידו היה דבר זה:
@568 **עוד** ירמוז על דרך אומרם ז''ל (ב''ר פי''ב) כי הרשעים כפופי קומה, ויצו ה' לאדם שיתעורר לתקן מעשיו לשוב לה' וזו היא קומתו, והערו לתקן מעשיו מפני שיבה פירוש שיבתו כדי שלא תאבד ממנו, על דרך אומרם ז''ל (יבמות נ.) זכה משלימין לו לא זכה פוחתין לו ולא יגיע לימי שנותינו ע' שנה. גם רמז כדי שלא יבואו ימים רעים בעת שיבתו שהם יסורין הקשים לאדם מכל יסורין כאומרו ז''ל (קהלת רבה פי''ב) כי הם ימים שכוחות האדם והשתדלותיו אפסים והוא צריך להשגחה אלהות:
@568 **עוד** ירמוז **והדרת פני זקן** פירוש זקנת עצמו על דרך אומרם (סוכה נג.) אשרי ילדותינו שלא ביישה את זקנותנו. גם רמז למאמרם ז''ל (חגיגה יד:) שבשעה שהצדיק הולך מעולם הזה אומרים לאברהם אבינו אשריך אברהם אבינו שצדיק זה יצא מחלציך, וכשהולך הרשע לא די שאין אומרים כן לפניו אלא שהוא מצטער, לזה מעורר ה' להאדם ואומר לו **והדרת פני זקן** זה אברהם שמתהדר כשאומרים לפניו אשריך וכו' והוסיף להפחידו מענייני עולם הבא, ואמר **ויראת מאלהיך** זו יראת עונש יום הדין, **אני ה'** זו תשלום שכר טוב של עולם הבא. או ירצה להעיר היראה והאהבה, יראה ויראת וגו', אהבה אני ד' כי שם זה הוא מקור האהבה החשוקה בלב כל משכיל:
@569 **וכי יגור אתך וגו'**. אמר לשון יחיד **אתך** וחזר לומר לשון רבים בארצכם. לצד כי המשכת הגרים תהיה באמצעות הצדיק אברהם אבינו עליו השלום, גם לצד טוהר ארץ הקדושה תגרר נפשות השבויות, לזה אמר אתך לשון יחיד לרמוז אל הצדיק, כי לא כולן הם בגדר המשכת ענפי הקדושה, ואמר **בארצכם** לרמוז למעשה הארץ, שגם היא ישנה בגדר פעולה טובה זו:
@569 **עוד** ירמוז על השראת השכינה בעולם הזה אתנו, ויצו ה' כי יגור אתך גר ממקום גבוה דקדק לומר אתך על דרך (תהלים עח) אהל שכן באדם. ואמר **בארצכם** היא ארץ הקדושה כי שם מקום השכינה, ועזבה מקומה עליון ובאה לגור בארץ. לא תונו אותו, שאין לך אונאה כאונאת השכינה. ואומרו **כאזרח מכם** וגו' להזהיר על הגרים וכו' הבאים להתיהד:
@570 **כאזרח מכם וגו'**. כאן גילה ה' סודו שכל נפשות עם קדושו היו טבועים במצרים בתוך האומות, והוא מה שאמר כאזרח מכם וגו'. ואם תאמר איך ישוה זרע מריעים שאבותיו גוים לאזרח שאבותיו ידידי ה'. לזה אמר **כי גרים הייתם בארץ מצרים**, פירוש נפשותם היו מעורבים תוך קליפות מצרים, ועיין מה שפירשתי בפרשת יתרו (כ' ב') בפסוק אנכי ה' וגו' אשר הוצאתיך מארץ מצרים וגו', וכמו כן גר זה היתה נפשו תוך הקליפות ועכשיו זרחה בעולם וחזרה לשורשה, וכפי זה ישנו לנתינת טעם לשבח כי גרים וגו', שאם על גרות הגופות אין הטעם נכון כי ישתנה גר הבא מן האומות שלא יהיה נאהב לצד ההבדל שישנו בשינוי המשפחות, כי לא ככל משפחות הגוים בית ישראל:
@575 **ואל בני ישראל וגו'**. טעם אומרו **ואל בני ישראל** נתכוון להזהיר כללות ישראל להרוג הנותן מזרעו למולך, ואמר בתוספת וא''ו לומר שמלבד חיוב המעביר גם חיוב כל העם להענישו:
@576 **ואני אתן את פני וגו'** צריך לדעת מה מקום לעונש זה אחר שיש דין למטה וירגמו אותו אבן:
@576 **ונראה** כי יודיע הכתוב שמלבד עונש ההריגה עוד יהיה לו עונש לנפש, והוא אומרו **והכרתי אותו מקרב עמו** פירוש מענף נצר הקדושה. ונתן הכתוב טעם לב' עונשים אלו ואמר **כי מזרעו** וכו' **למען טמא** וגומר **ולחלל** וגו', הרי ב' פגמים וכנגדן ב' עונשין, כנגד טמא מקדש ירגמוהו באבן, וכנגד חילול שם קדשו גם הוא יתחלל ונכרת נפשו מעמה:
@577 **ואם העלם יעלימו** טעם הכפל, לומר שאם העלימו מן האחד שוב אינם יכולין שלא להעלים מהבאים אחריהם, ויעלימו ודאי מכולם, כי אם ירצו לעשות דין בהם יאמרו להם למה לא עשיתם דין באחד. או יאמר **העלם** לבל ימנעוהו מליתן למולך, **יעלימו** מלעשות בו משפט אחר אשר נתן כאמרו בתתו מזרעו וגומר:
@578 **ושמתי אני את פני וגומר**. משמעות הכתוב יגיד שאם לא יעשה משפט העם יעשה ה' משפט בו ובמשפחתו גם כן, מה שלא היה אם היו עושים דין עם הארץ, ואלו הם דברים רחוקים, ממה נפשך אם הם חייבין בין עשו דין כ''כ ברשע עצמו בין לא עשו:
@578 **ונראה** לפרש על זה הדרך **ואם העלם** וגו' פירוש במקום שאין דין למטה יהיה דין למעלה ושמתי אני וגו'. וכשיעשו דין למעלה יפתחו גם כן פנקסי בני משפחתו ויתעוררו הדינים על כל המשפחה, והוא אומרו **ובמשפחתו**. וחזר ופירש שימת פנים זו מה עושה, ואמר כנגד האיש עצמו והכרתי אותו, וכנגד משפחתו יפתחו ספרי דיניהם אם יש מהם זונים כמותו הרי הוא בכלל הכרת, והוא אומרו ואת כל הזונים אחריו ממשפחתו, אבל אותם שנפתחו ספריו ונמצא שלא זנו לא יכרתו, ואמר עוד **לזנות** ולא הספיק לומר הזונים וגו' אחרי המולך, נתכוין לומר שהגם שלא זנה עד עתה פירוש שלא העביר בנו למולך אלא שחשב לזנות מחשבת עבודה זרה נתפסים עליה כמעשה, ויכרית ה' את החושב כעושה כמו שאמר הכתוב (יחזקאל יד) למען תפוש את בית ישראל בלבם:
@578 **נמצאת** אומר שאם עם הארץ יעשו דין בעושה רע אין דין למעלה ולא ימות מישראל זולת העובד למולך, אבל אם לא יעשו דין נפתחים ספרי כל המשפחה ומתעורר הדין גם עליהם ונתפסים גם על המחשבה, והוא מאמרם ז''ל (דב''ר פ''ה) במקום שיש דין וכו' אין וכו' ע''כ. קשה פשיטא שכשיעשו דין למטה מה מקום לדין ליעשות למעלה, ולדרכנו ידוייק על נכון שכשעושין דין למטה נמנע דין למעלה פירוש דין השאר שאין ספריהם נפתחים. ותמצא שאמרו רז''ל (ר''ה טז:) שכשנפתחים ספרי הדינים אדם נכנם בסכנה וצריך זכות גדול ליפטר:
@580 **והתקדשתם והייתם קדושים**. יצו ה' שיהיו נוטים אל בחינת הקדושה, ובזה הוא מבטיחם שיהיו במדריגת מלאכים הנקראים קדושים, דכתיב (דניאל ח) ויאמר אחד קדוש, והוא אומרו **והייתם קדושים**, ותמצא שאמרו ז''ל (במד''ר פ''כ) בפסוק כעת יאמר ליעקב וגו' כי המלאכים יהיו עומדים בשורה החיצונה וישראל בפנים ושואלים מלאכי אלהים לעם קדושו מה פעל אל, נמצאת אומר כי קדושיו במקום המלאכים הם ישראל. וחזר הכתוב ופירש הדבר שבו יתקדשו ואמר **ושמרתם את חקותי**, פירוש תשמרו מצות לא תעשה, ותקיימו מצות עשה בזה אני מקדשכם, כי על ידי זה שם הוי''ה מתגלה עליו ובזה מתקדש, וכמו מה שכתוב בזוהר (תיקונים ע) כי האבר שבו עושה מצוה שורה עליו שם הוי''ה הרמוז בתיבת מצוה:
@582 **כי איש איש אשר יקלל**. קשה אומרו **כי** שנותן טעם למה שלפניו ולא אמר דבר קודש שיהיה זה טעמו. ואם על שמירת החוקים, וכי לא נכלל בפסוק זה אלא קללת אבות שהוצדק לומר כי. עוד למה כפל לומר איש איש. ובתורת כהנים אמרו איש אין לי אלא איש אשה מנין תלמוד לומר איש איש ע''כ. קשה מנין יעלה על דעת למעט אשה שהוצרך לריבוי והלא השווה הכתוב אשה לאיש לכל עונשים שבתורה בדרך כלל וכאומרם ז''ל (ב''ק טו.). ואם לצד שחש הכתוב לפרש איש שבא למעט אשה, לא היה לו לכתוב איש לטעות לומר שבא למעט אשה ויאמר אדם כי יקלל וגו':
@582 **עוד** למה כפל לומר אביו ואמו קלל. אכן כוונת הכתוב הוא לצד שצוה קודם לזה על העברת בנו ובתו למולך, והקפיד הכתוב על זרעו לבד אבל בן אחרים ואפילו קרוביו כגון אחיו ואחותו פטור, כדתניא בסנהדרין (סד:) וזה לשונם אינו חייב אלא על יוצאי יריכו וכו' ע''כ. וצריך לומר טעם חיובו על בנו ובתו ולא על בני הזולת שהוא לצד שבניו הם נידונין כנכסיו של אדם לזה מועילים מעשיו כשמקריבו לעבודה זרה במה שמעבירן למולך אבל חוץ מהם אין מעשיו עושין רושם, על דרך אומרם ז''ל (ערכין כח ב''מ ז.) אפילו לגבי קדשי שמים אין אדם מקדיש דבר שאינו שלו, ומעתה יאמר אדם והלא גם הבן אינו כולו של האב כאומרם ז''ל (נדה לא.) שהאב והאם הם שותפין באדם הלובן מהאב והאודם מהאם, וא''כ מזה הטעם עצמו לא יתחייב האב על הבן מצד חלק האם, לזה אמר הכתוב אחר אזהרה ועונש מעביר בניו למולך כי איש איש אשר יקלל וגו' מות יומת, ודקדק לומר את אביו ואת אמו פירוש זה בפני עצמו או זה בפני עצמו, כמו שדקדקו בתורת כהנים בפסוק זה עצמו חיוב על כל אחד משניהם, הרי שהבן מת לצד שנגע באביו או בכבוד אמו ואין אנו אומרים והרי אין כל הבן של האב או של האם להמיתו בשבילם, ואם תאמר גם על זה דן אנכי למה יהיה המשפט הזה, לזה גמר אומר **אביו ואמו קלל**, פירוש כי כשמקלל אביו מקלל גם אמו עמו וכן להפך, והטעם לצד שהאב והאם הם גוף אחד כמאמרם ז''ל (ברכות כד.) אשתו כגופו, וכפי זה בין הנעשה לאחד מהם או הנעשה מאחד מהם לבניהם יחשב לשניהם יחד. ולזה תמצא שיעניש ה' לאיש להמית אשתו דכתיב (משלי כב) למה יקח משכבך מתחתיך. וכפל לומר **איש איש** משום שמצינו שתלה הכתוב זכרים בנקבות ונקבות בזכרים, ואמרו ז''ל (נדה לא.) אשה מזרעת תחלה יולדת זכר, אם כן יש הפרש בלידת הזכר ללידת הנקבה ומצד זה ישתנה ההפרש בבחינת המולידים, ויש מקום לומר לצד שתלה הכתוב זכרים בנקבות לא יומתו אבות על העברת הבנים או האמהות על העברת הבנות לצד שתלאם הכתוב באבות תלמוד לומר איש איש אחד לגופו ואחד לאשה ששניהם ישנם בחיוב העברת בן ובת:
@582 **עוד** נראה כי לצד שאמר הכתוב אביו ואמו ודרשו רז''ל (ילקוט) שאביו בא למעט אבי אביו ואמו בא למעט אם אמו שלא יהרגו, לזה חש הכתוב לטעות ולומר שהמיעוט בא אביו ולא אביה אמו ולא אמה ואם כן הנשים פטורות מעונש זה, תלמוד לומר איש איש לרבות אשה:
@595 **ושמרתם את וגו'**. טעם שהוצרך לומר פעם אחרת פסוק זה הגם שכבר אמר כן בפרשת אחרי מות (יח כו), נתכוין לומר שצריכין לשמור המצות לבל יתבטלו בין מהם בין מזולתם ובזה לא תקיא הארץ הא למדת שאם לא יהיו נשמרים המצות תקיא הארץ, גם השומרים על שלא מיחו בשלא שמרו:
@597 **ואני אתננה וגו' ארץ זבת וגו'**. קשה אחר שאמר לרשת אותה מה צריך לומר ואני אתננה, עוד למה סמך שבח הארץ לזכרון הירושה. ונראה לי שהכונה היא שמלבד מה שיירשו עוד יתן להם שתהיה הארץ זבת חלב ודבש יותר מהשיעור מה שלפניה, גם שלל שלא בזמן ירושתם אחר כך שהוא זמן החורבן שלא תהיה זבת חלב ודבש, כמו שסיפרו מכיריה בזמן הזה בעונינו:
@599 **והייתם לי קדושים וגו'** טעם אומרו **לי**. יתבאר על דרך אומרם ז''ל (תו''כ כאן) אל יאמר אדם אי אפשי בבשר חזיר וכו' אלא אפשי ואפשי אלא אבי שבשמים וכו', והוא אומרו **והייתם לי קדושים** שתהיו פרושים לי לשם מצותי ולא לצד תיעוב הדבר הנאסר, ולזה סמך מאמר זה להבדלת בהמה וחיה לרמוז למה שכתבתי, ואומרו **כי קדוש אני ה'** וגו' נתן טעם למצוה זו של הבדלת בהמה טמאה כי קדוש וגו' **ואבדיל אתכם מז העמים להיות לי**. והענין עצמו של פרישות ישראל מן העכו''ם הוא הדבר עצמו של פרישתכם מן הבהמה טמאה. ברוך ה' אשר הבדילנו מן הטמאים מאדם עד בהמה עד עוף השמים:
@599 **חסלת פרשת קדושים**
@601 **ויאמר ה' וגו'**. צריך לדעת למה שינה מסדר הרגיל לומר בכל התורה דבר אל וגו'. עוד למה הקדים התואר למתואר שהיה צריך לומר בני אהרן הכהנים. ודרשות שדרשו חז''ל (תו''כ) במקומן עומדים הגם שידבר בסדר זה. ויתבאר על דרך מה שאמרו ז''ל (תנחומא כאן) וזה לשונם אמר הקב''ה למשה אין נאה ליוצא ונכנס לפני להסתכל במת וכו' ע''כ, והוא אומרו **אמור** לשון מעלה, אל הכהנים פירוש לצד שהם כהנים משרתי פני מלך, ומה היא המעלה שלא יטמאו לנפש אדם כמאמרם ז''ל שאין נאה ליוצא ונכנס וכו'. ומטעם זה הקדים התואר למתואר להסמיך המעלה לצד היותם כהנים מה שלא היה נשמע כן אם היה אומר אמור אל בני אהרן:
@601 **ואמרת אליהם לנפש וגו'**. צריך לדעת למה כפל לומר **ואמרת**. ורז''ל אמרו (תו''כ יבמות קיד:) כמה דרשות, ועוד יש לאלוה מילין והוא על דרך מה שכתב הרמב''ם פרק ב' מהלכות אבל וזה לשונו המטמא את הכהן אם היו שניהם מזידים הכהן לוקה וזה המטמא עובר משום ולפני עור וגו', ואם היה הכהן שוגג והמטמא מזיד הרי זה שמטמאו לוקה ע''כ. וקשה מנין לו להרמב''ם לחייב המטמא מלקות, והרב המגיד ומהרי''ק לא אמרו כאן דבר, כי אם הלחם משנה אשר הוא כתב וזה לשונו בהלכות כלאים כתב רבינו בזה שהמלביש כלאים לחברו אם היה הלובש שוגג המלביש לוקה, ותמה עליו הכסף משנה וכתב ששאל זה הרא''ש מהר''ש ולא זכינו לתשובה וכו', ואפשר לו דמשמע ליה לרבינו דמדאמרינן בפרק ג' מינים (נזיר מד.) דגלי קרא בנזיר שלא עשה המטמא כנטמא מדכתיב וטמא את ראש נזרו משמע דבעלמא עבדינן המטמא כנטמא ולכך כתב רבינו בפרק ה' מהלכות נזירות שאם היה הנזיר שוגג וזה שטמאו מזיד אינו לוקה ע''כ דברי הרב, ואינם נראים דקשה א' למה לא יהיה הנזיר בנין אב לכל התורה כולה דלא אמרינן המטמא כנטמא וכו' וכן על זה הדרך. ועוד ההוא דנזיר שהוצרך הכתוב למעט משום שהייתי דן קל וחומר מתגלחת שחייב דהא חומר בטומאה מבתגלחת תלמוד לומר וטמא את ראש וגו' ע''כ, אם כן זולת הקל וחומר לא היה צריך למעט, ואדרבא תגדל מדורת הקושיא לרמב''ם מההוא דפרק ג' מינים:
@601 **והנכון** בעיני שטעמו של רמב''ם הוא מאותה שאמרו במסכת נזיר דף מ''ד וזה לשונם ומה טומאה וכו' לא עשה בה מטמא כמיטמא תגלחת לא כל שכן שלא עשה מגלח כמתגלח אמר קרא תער לא יעבור קרי ביה לא יעבור הוא ולא יעביר לאחר עד כאן ופירש''י לא יעביר לו אחר ע''כ, פירוש אזהרה לאחר שלא יעביר תער על ראש הנזיר שאם לא כן תהיה הכוונה שלא יעביר הנזיר שער של אדם אחר ופשוט. וצריך לדעת כוונת הש''ם מנין דורש לא יעביר לו אחר, אם דורש המסורת הלא מסורת לא יעביר הוא ביו''ד בין בי''ת לרי''ש. ועוד לכשנאמר שאין חסרון היו''ד מעכבת אף על פי כן עדיין חסר תיבת לו שזולתה יהיה משמעות לא יעביר שהנזיר לא יעביר לאחרים:
@601 **אכן** כוונת הש''ם שמדייק מאמר הכתוב תער לא יעבור וגו' שהיל''ל לא יגלח את ראשו או לא יעביר על ראשו יו''ד בין בית לרי''ש ויחזור אל הנזיר האמור בסמוך ויתלה האיסור כמצווה עליו לא במעשה התער שלא בכינוי אל המתגלח כאומרו תער לא יעבור שמשמעות הדברים יגידו שאסר המעשה בין על יד המתגלח בין על יד אחרים, והוא מאמר הש''ס קרי ביה לא יעבור הוא ולא יעביר לו אחר פירוש משמעות התיבה תגיד לאסור הדבר בין על ידו בין על ידי אחר. ומאמר קרי ביה אינו מדויק אלא מלבישים המכוון בתיבה והבן. ומעתה כמו כן נאמר בדין כלאים שאמר (לעיל יט יט) ובגד כלאים שעטנז לא יעלה עליך ולא אמר לא תעלה עליך משמע שלא על המעלה עליו לחוד מצוה אלא על המעשה הוא מצוה שלא יהיה בין ממנו בין מהזולת, ולזה פסק הרמב''ם (הל' כלאים פ''י הל''א) שהמלביש כלאים לחבירו מזיד לוקה, וכמו כן נאמר במה שלפנינו בטומאה כהן ממה שאמר הכתוב לא יטמא אזהרה שלא בכינוי לנטמא לומר שמזהיר בין לכהן עצמו בין לאחרים על הטומאה. ושיעור המצוה היא שמצוה ה' ב''ה לבל יהיה הכהן טמא. ומעתה כל המטמאו בין הוא בין אחר הרי זה עבר על הלאו ולוקה. וכפי זה עלו פסקי רמב''ם על נכון:
@601 **ובזה** נבוא ליישב דקדוק הכתוב שכפל לומר אמור ואמרת, כי לצד שצוה ה' לכהנים גם לאחרים על טומאתם, כנגד הכהנים אמר אמור אל הכהנים, וכנגד אזהרת אחרים שלא יטמאו אמר **ואמרת** אליהם. ואולי שתיבת אליהם חוזרת לישראל המצטוים בכל המצוה, ותמצא שאמר בסוף ענין זה (פסוק כד) וידבר משה אל אהרן ואל בניו ואל כל בני ישראל הרי שהציווי נאמר מה' גם לישראל, וזה יצדיק לך פירושנו שהאזהרה בא כאן גם לישראל שלא יטמאו הכהנים. ובתורת כהנים (לקמן כד) אמרו וזה לשונם וידבר ה' הזהיר את אהרן על ידי הבנים ואת הבנים על ידי ישראל ואת הבנים זה על ידי זה, ואלו ואלו דברי אלהים חיים:
@601 **לנפש**. רז''ל דרשו (בתו''כ) לרבות רביעית דם וכו', וראיתי לרמב''ם ז''ל שכתב בפרק ג' מהלכות אבל וזה לשונו אחד המת ואחד שאר הטומאות הפורשות מן המת שנאמר לנפש עכ''ל, והקשו עליו מדתנא בתורת כהנים וזה לשונם אין לי אלא המת מנין לרבות הדם תלמוד לומר לנפש, מנין לרבות כל הטומאות הפורשות מן המת תלמוד לומר ואמרת אליהם לרבות וכו' ע''כ. ותירץ הכסף משנה שסובר רמב''ם שמתיבת לנפש גמרינן הכל ששקולים הם וקרא לא צריך אלא אסמכתא ע''כ. ואין דברי הכסף משנה נראים, כי מנין לו לרמב''ם לבנות בנין חדש שלא כדברי הברייתא:
@601 **אכן** הנכון הוא כי רמב''ם ז''ל ברייתא אחרת הוא שראה והנה היא כתובה בפסיקתא, וזה לשונם אמור ואמרת להזהיר גדולים על הקטנים, לנפש לא יטמא להביא רביעית דם שתצא מן המת שהוא בלא יטמא עכ''ל, והובאה ברייתא זו ביבמות (קיד.). ולפי ברייתא זו תתחייב לומר שגם שאר טומאות הפורשות מן המת מתרבות מן לנפש שהרי דורש כפל ואמרת להזהיר גדולים על הקטנים. והדבר פשוט אצלי שנעלמה ברייתא זו מעיני הכסף משנה והראיה שכתב הרב בפרק הנזכר דין י''ב וזה לשונו כהן קטן וכו' הגדולים וכו' כפירש''י אמור ואמרת וגו' עד כאן, הנה ממה שמוכיח דין זה מדברי רש''י ולא מדברי הברייתא אתה יודע שלא ידע הברייתא:
@601 **ונשאר** ליישב מנין להם לדרוש מתיבת לנפש רביעית דם וכו', ודלמא הוצרך לומר לנפש להודיע שאינו מזהיר אלא על טומאת מת ולא על שאר טומאות, ויש לומר שהיה לו לומר למת לא יטמא ומאומרו **לנפש** דרשו רביעית דם וכל שיש בו נפש. אבל טמאי מת אינם בכלל זה:
@601 **לא יטמא**. אמר לשון יחיד הגם שהתחיל לדבר בלשון רבים הכהנים, אליהם. לסברת תנא שדרש כפל ואמרת להזהיר גדולים על הקטנים מעתה אין לנו מקום אזהרה למטמא שלא יטמא לכהן לזה אמר לשון יחיד ואמירה לרבים לומר שאזהרת רבים על היחיד הא למדת אזהרה למטמא:
@601 **עוד** נראה שחש הכתוב לומר לא יטמאו שלא תבא הסברא לטעות שלא הקפיד הכתוב אלא על טומאת כללות הכהנים, כי דבר זה אינו אלא חוקה ואין לנו אלא מה שבא בפירוש, אבל כהן יחיד לא יקפיד עליו תלמוד לומר יטמא לשון יחיד. עוד לצד שצוה ה' לכהנים (לעיל י ט) איסור יין ושכר ושם גילה הכתוב שטעם האיסור הוא לבל יעבדו עבודת הקדוש שתויי יין, ואם כן שלא בזמן משמרתם או שלא בזמן עבודה יכולין לשתות יין ושכר, ואם כן תבא הסברא שילמוד סתום מהמפורש לדון בטעם איסור טומאה שהוא מהטעם עצמו שנאסרה שתיית יין ושכר נאסרה טומאה כדי שיהיה ראוי לעבודה לזה נתחכם ה' וידבר לשון יחיד לא יטמא לומר שאפילו אחד מהכהנים הוא עומד באיסור זה, וממוצא דבר אתה למד שלא מטעם ביטול עבודה כי אין עבודה בטילה מהעדר כהן אחד, אלא ודאי שאיסור טומאת כהן היא חובת גברא ואפילו מי שמשמרתו באה לזמן רחוק אף על פי כן הוא באיסור זה, ומטעם האמור בדבריהם ז''ל וכתבנוהו למעלה:
@602 **כי אם לשארו וגו'** תניא בתורת כהנים וזה לשונם שארו זו אשתו דכתיב שאר אביך, הקרוב למעט ארוסה פירוש לצד שעדיין לא נתקרבה. אליו למעט הגרושה פירוש קרוב שנתרחק. יאמר לאמו מה תלמוד לומר לאביו מה אמו שהיא מתחללת הרי הוא מטמא לה אביו שאינו מתחלל אינו דין שיטמא לו אלו כן הייתי אומר מה אמו בידוע אף אביו בידוע אביו חזקה מנין תלמוד לומר ולאביו ע''כ. הקשו חכמי לוניל לרי''ץ לעולם לא יאמר הכתוב לאביו ואנו למדין מקל וחומר מאמו מה תאמר הרי אביו זה אינו ידוע כאמו יטמא ממה נפשך אם זה אביו מטמא ואם אינו אביו אם כן הוא ממזר ואין לו כהונה עד כאן. ובעיני אינו קושיא כלל כי הכתוב כאן בא לב' דברים להתיר, ולהצריך, להתיר טומאה בקרובים הגם שאסר ברחוקים, ולהצריך. שאם לא רצה ליטמא מטמאין אותו בעל כרחו, כמו שאמר הכתוב לה יטמא ואמרו בתורת כהנים מצוה, שחייב כל כהן ליטמא למתים האמורים בענין. והגם שלא נאמר לה יטמא אלא באחותו, הרי אמרו בתורת כהנים וזה לשונם מעשה ביוסף הכהן שמתה אשתו בערב פסח ולא רצה ליטמא לה ודחפוהו חכמים וטמאוהו בע''כ עכ''ל, הרי שלך לפניך שעל כל הקרובים האמורים בענין הוא חייב ליטמא. וכפי זה אם הייתי דן טומאת אביו מדין ממה נפשך אין לי מקום לחייבו לטמא לו כי יאמר מי יאמר שהוא אביו, ומה גם אם ימות אביו בערב פסח אין לבטל מצות פסח א' במועדו מחמת ספק, ולא מבעיא למאן דאמר (רמב''ם ופר''ח) ספק דאורייתא מותר מדאורייתא פשיטא שלא יטמא לדחות מצות פסח במועדו אלא אפילו למאן דאמר ספק דאורייתא אסור מדאורייתא אף על פי כן אין לו לדחות מצות ודאי מפני מצות ספק, תלמוד לומר לאמו ולאביו שחייב ליטמא לכל אחד מהם דבר תורה. ועיין בפסוק שאחר זה:
@602 **ועוד** נראה לי כיון שיש מציאות שאביו אין לו אלא חזקה, והבן מוחזק בכהן, כגון שיש לפנינו ב' בני אדם מוחזקים בחזקת כהנים כל אחד בפני עצמו, גם מוחזקים שאחד מהם אב ואחד בנו, ומציאות זה יכול להיות שיורע חזקת האב שאינו כהן ולא יורע חזקת הבן להסירו ממדריגת כהן ונאמר שאין זה אביו ונשאר הבן בחזקתו. וכיון שכן אם לא אמר לאביו הייתי דן שלא יטמא לאביו חזקה באופן הנזכר מטעם שמא יורע חזקת אביו והבן ישאר כהן לעולם, ולזה אמר התנא אביו חזקה מנין תלמוד לומר לאביו. והנה בין לדרך זה ובין לדרך ראשון אביו חזקה חייב לטמא לו כי סוף כל סוף אביו אינו אלא חזקה והתורה חייבתו ליטמא:
@602 **ולבנו ולבתו ולאחיו וגו'**. תניא בתורת כהנים וזה לשונם יאמר לבנו ולבתו מה תלמוד לומר לאמו ולאביו. בנו ובתו שאינו חייב בכבודם הרי הוא מטמא להם אביו ואמו שהוא חייב בכבודם אינו דין שיטמא להם, אלו כן הייתי אומר לבנו ולבתו הנפלים, תלמוד לומר לאמו ולאביו מה אמו ואביו בני קיימא אף בנו ובתו בני קיימא ע''כ. קשה כפי זה לא היה צריך לומר אלא לאמו ולבנו וגו' ולא יאמר לאביו, ולטענת מה אמו בידוע, בנו ובתו יוכיחו שמן הסתם אינם בידוע אלא חזקה ומטמא להם. ואין לומר שגרוע אביו מבנו ובתו, שהרי מצינו שדן התנא קל וחומר מהם לאביו ולאמו, ואם כן למה הוצרך לומר לאביו. ואם לגלות על בנו ובתו שהם בני קיימא, למדינן מיתור לאמו שאין צריך שבאה מק''ו בנו ובתו, ואין לומר שצריך לאביו ולאמו שניהם יחד למעט בנו ובתו הנפלים, כי למה לא יספיק אחד. ועוד אם צריך שניהם מה מקום לתנא לעשות צריכיות בין לאביו ולאמו הלא צריכין שניהם למעט בנו ובתו נפלים, והדברים פשוטים:
@602 **ונראה** לומר שאם לא אמר לאביו הייתי דן על זה הדרך מה תלמוד לומר לאמו בנו ובתו שאינו חייב בכבודם מטמא להם אמו לא כל שכן, אילו כן הייתי דן גם אביו תלמוד לומר לאמו למעט אביו מטעם שאינו אלא חזקה, והיינו מתחייבין לפרש כי בנו ובתו שאמר הכתוב הם דומים לאמו בידוע, וכגון שלא היה מציאות שתתעבר אשתו אלא ממנו על ידי ידיעה ברורה במציאות שיכול להיות, מה שאין כן אחר שאמר הכתוב לאביו והקשינו למה הוצרך ויבא דינו מאמו והכרחנו לומר שבא לומר אפילו אינו אלא חזקה אם כן אמו למה לי שמע מינה למעט בנו ובתו נפלים. והגם שהתנא אמר לאביו ולאמו למעט הנפלים, לאו דוקא, וסמך על מה שהעירך בסמוך בדרשת לאביו שבא לומר אפילו אינו אלא חזקה:
@602 **אלא** שקשה למה שאמרו שם בתורת כהנים בסיפא דברייתא דלאמו ולאביו וזה לשונם אלו נאמר לאביו ולא נאמר לאמו וכו' הייתי אומר מה אביו שאינו מתחלל אף אמו שאינה מתחללת אמו שנתחללה מנין תלמוד לומר לאמו ע''כ. הרי שהוצרך לאמו לרבות אפילו נתחללה, ומנין לו למעט הנפלים, ואם תדרוש לנפלים נתחללה מנין, ועוד צריך לדעת כפי זה בתו שנתחללה אם חייב לטמא לה או לא, שיש פנים לומר דוקא אמו שחייב בכבודה הוא שנתרבית אפילו נתחללה, ויש פנים לומר כיון שגילה קרא שהחילול אינו פוגם הקורבה הוא הדין בתו:
@602 **אכן** בהעיר בדברי התנא מנין מצא לומר שיטמא לאמו שנתחללה, אם מיתור, דלמא אצטריך משום שהייתי אומר לאביו לצד שיש בו מעלה שאינו מתחלל מה שאין כן האם שגרועה מערך אב לצד שמתחללת. וכמו כן דקדק התנא בתחלת דבריו באמרו מה אביו שאינו מתחלל, משמע כי ההפרש יוצרך לעשות בו ההדרגה הגם שאינו בנמצא אלא כיון שראוי להיות, ואם כן נוכל לומר עד עתה שאמו שנתחללה פטור מלטמא, ובהכרח לומר שהתנא סובר כי אומרו לאמו משמעותה הוא בין כהנת בין חללה. האמת שאם לא היה אומר אלא לאביו היה לבעל דין לחלוק ולומר אמו גרועה מאביו גם בהיותה כהנת כיון שישנה בחילול, אבל אחר שאמר לאמו אפילו נתחללה במשמע. וכמו כן תדון כשאמר הכתוב ולבתו אפילו נתחללה במשמע. כי לא תלה הכתוב הדבר אלא בסיבת הקורבה, ואמו שנתחללה ובתו שנתחללה נקראים אמו ובתו, ומעתה כיון שבלא ריבוי אנו אומרים כי משמעות בתו הוא אפילו שנתחללה כל שנקראת בתו יטמא לה, אם כן נבא לדין למה אמר אמו והלא תבא בקל וחומר מבתו ומה בתו שנתחללה מטמא לה אמו אצטריך:
@602 **אכן** אם לא אמר הכתוב לאמו אז לא היינו אומרים כי לאביו בא למעט בנו ובתו הנפלים אלא למעט אמו, ומיעוט זה קרוב יותר בנשמע מלילך לחפש אחר הנפלים של בנו ובתו לומר שעליהם בא, והייתי ממעט אמו מטעם שמתחללה, וכשהיינו באים לדון מבתו שמתחללת ומטמא לה היינו מעמידין מיעוט האם כשנתחללה דוקא, אבל לא נתחללה היתה באה מקל וחומר מבתו, וכשנבוא לדון בבתו אפילו נתחללה ממשמעות התיבה כמו שאמרנו למעלה שאפילו נתחללה תקרא בתו, היינו חוזרים ודנים בתו שנתחללה מאמו שנתחללה ומה אמו שנתחללה אינו מטמא לה כמו שדרשנו מיתור לאביו בתו שנתחללה לא כל שכן והגם שמשמעות בתו יגיד אפילו נתחללה, זה מן הסתם, אבל כשיבא הלימוד במיעוט או בקל וחומר נחזור להעמידה בשלא נתחללה:
@602 **העולה** מכל הכתוב בעומק הכתוב הוא, שאם לא אמר הכתוב לאביו שממנו נבא לטעות שבא למעט אמו כמו שכתבתי לא היה צריך לומר לאמו והיתה באה מבנו ובתו כנזכר. ואם לא אמר לאמו שממנה היה בא הטעות לומר שבא למעט אביו לצד שאינו ידוע אלא חזקה לא היה צריך לומר לאביו. אם כן תקשה לא יאמר לא אביו ולא אמו לזה דרשו שבא למעט הנפלים שאינו מטמא להם, ומעתה אין מקום לנו לומר שיאמר או לאמו לבד או לאביו לבד, כי אחד מהם שיאמר יוליד הטעות ויסתור הבנין, ונתחכם ה' לדבר דברי אמת, ולזה נתחכם התנא וקדם להודיע הטעות היוצא מאם יאמר א' מהם, ואחר כך דרש יתור שניהם יחד והבן. ובזה עלה דברי התנא לאור עולם דברי אלהים חיים:
@608 **וקדשתו** ולא אמר וקדשתם כסדר הנדבר עד עתה בלשון רבים. לדבריהם ז''ל (יבמות פח:) שאזהרה זו באה שאם כהן לא רצה לגרש אשה זונה וחללה וגו' שמלקין אותו ומיסרין אותו עד שיגרש, ולפי הטעם שנתן הכתוב **כי את לחם אלהיך הוא מקריב**, תבא הסברא לומר כי כל עוד שיש כהנים שלמים וכן רבים המספיקים להקריב אין חיוב לכוף, לזה אמר לשון יחיד שאפילו על אחד מהם יקפיד לעשות כמשפט הזה:
@608 **קדוש יהיה לך**. פירוש כדי שיהיה קדוש יהיה לך הכהן פירוש הנה הוא שלך לכופו על הדבר. ואומרו **כי קדוש**, פירוש לצד שקדמה לנו הידיעה כי הקדושה היא בחינה הנקנית ברצון ובהשלמת החפץ והחשק בה ולא בכפייה. ואיך אומר הכתוב לכופו על הקדושה, לזה אמר **כי קדוש** פירוש לא להמשיך לו הקדושה מחדש שכבר הוא קדוש אלא שלא לאבד קדושתו. ואומרו **אני ה' מקדשכם**, נותן טעם לחיוב ישראל בדבר זה, כי באמצעות קדושת כהן ה' ב''ה משרה שכינתו בתוכינו ומקדש אותנו, ואם אין כהן אין עבודה ואין מקדש ואין שוכן:
@617 **דבר אל אהרן לאמר**. אמר לאמר, לצד שהמצוה באה לאהרן כאומרו דבר אל אהרן שהטיל עליו להפריש בעלי מומין מהכהנים להיות שהוא כהן גדול, לזה אמר **לאמר** שיזהיר גם כן כל הכהנים שיאמר להם המצוה, ונמצאו מוזהרים הכהנים על עצמן וכהן גדול גם כן מוטל עליו לבל [יגש] (יזיד) איש בעל מום:
@617 **איש מזרעך וגומר**. לא אמר כסדר שאמר בתחלת הפרשה, ולא כסדר שאמר בפרשה שאחריה דבר אל אהרן ואל בניו וינזרו, ולא כסדר יין ושכר שאמר אתה ובניך. ואולי כי נתכוין ה' במתק לשונו לומר שאהרן ובניו מובטחים מכל המומין האמורים בפרשה לזה לא הזכיר לא הוא ולא בניו אלא זרעך. והגם שגם בניו יקראו זרעך, אף על פי כן ממה ששינה העירך כי על הבאים אחריהם הוא אומר, ודקדק גם כן לומר מזרעך, הבטיחך שלא יפול המום בכולם אלא במקצתם, ועיין בפירוש פסוק והוא צרוע (לקמן כב ד):
@621 **כל איש וגו' מזרע אהרן וגומר**. כפל האזהרה הוא לישראל שלא יניחו להקריב בעל מום, ולזה לא עשה הציווי לנוכח והבן:
@627 **אמור אליהם**. בתורת כהנים אמרו וזה לשונם אליהם אלו העומדים לפני הר סיני ע''כ. הוקשה להם יתור אמור אליהם אם על האמורים בסמוך שהם הכהנים, לא היה צריך לומר, שעליהם התחיל לדבר וזה גמר המצוה שהתחיל לדבר בה. ואם על ישראל הלא לא הוזכרו בסמוך לזה אמר על העומדים בהר סיני, כי שם נזדווגה אומה לאלהיה וכשידבר סתם הדבר מובן שעליהם הוא אומר, וכפי זה הרי עונש זה הוא גם לישראל, ואם תאמר אם כן למה בכל התורה מזכיר בני ישראל בכל פרט ופרט ולא הספיק לומר דבר אליהם, כבר אמרו ז''ל (ויק''ר פ''ב) משל למי שהיה לו בן חביב ותמיד זכרונו בפיו אכל בני שתה בני, כמו כן הקב''ה לאהבת ישראל ערב עליו זכרונם בפיו. ובמקום שיש לדרוש דרשינן:
@628 **מזרע אהרן**. הוצרך להזכירם פעם ב', לומר שהם דוקא הוא שישנם בהערב שמש, אבל קדשים שאוכלים ישראל שהם (השלמים) [מע''ש] אין צריכים הערב שמש כך דרשו בתורת כהנים. ואומרו **והוא צרוע**, דרשו בתורת כהנים וזה לשונם אין לי אלא זרעו עצמו מנין תלמוד לומר והוא וגומר עד כאן. הנה בדין זה אי אפשר לומר מה שפירשנו בפסוק (כא ז) איש מזרעך כי ה' ישמרנו, לצד שיש כאן גם כן אשר תצא ממנו שכבת זרע, ואהרן מצינו שלא פירש מאשתו, ואם לא היה אומר והוא היה מקום לומר שאהרן יאכל הקדשים בטומאה תלמוד לומר והוא, וכיון שנתרבה אהרן נתרבו גם כן בניו, ומעתה פסוק ראשון שאמר איש מזרעך אשר יהיה בו מום ולא נתרבה אהרן אמור מעתה שאינו בכלל, והוא מטעם שהוא מובטח שישמרהו ה' לו ולבניו שלא יפול בהם מום, וכמ''ש:
@636 **ובת כהן וגו' היא וגו'**. בתורת כהנים דרשו מיעוט היא לאמה שאמה אוכלת מצדה הגם שהיא אינה אוכלת ואפילו נתאלמנה אמה. וראיתי להעיר לבות בני אדם ברמז גדול אשר רמזה פרשה זו. דע כי אמדו ז''ל (סנהדרין צג.) שעם בני ישראל הדרגתם למעלה מהדרגת המלאכים. ואמרו עוד (זוהר ח''ב קנה.) כי ה' ברא ד' עולמות זה למעלה מזה, ורשומים המה בפסוק (ישעי' מג) כל הנקרא בשמי ולכבודי בראתיו יצרתיו אף עשיתיו. לכבודי עולם עליון הנקרא אצילות, בראתיו הנקרא עולם הבריאה, יצרתיו יצירה, עשיתיו עשיה, עוד יש לך לדעת כי כבודו יתברך מלא כל עולם ועולם ועד מתחת עולם דכתיב (דברים לב ט) ומתחת זרועות עולם, ואורו יתברך מאיר בד' עולמות, הוא בסוד ד' אותיות שם הוי''ה ב''ה, יו''ד בעולם האצילות, ה''א ראשונה בעולם הבריאה וכו', ואמרו ז''ל (זוהר ח''ג ריח:) שחיונית המתנועע בבני אל חי הוא מאורו יתברך דכתיב (דברים לג כז) כי חלק ה' עמו. גם קראם ה' בניו:
@636 **עוד** אמרו ז''ל (זוהר ח''א פ: צד:) כי בחינות החיוני שבאדם יתייחס אליו ד' כינויים, יש שיקרא נפש, ויש שיקרא רוח, ויש שיקרא נשמה, ויש שיקרא חיה, בסוד כי רוח החיה באופנים, ותקרא נשמה לנשמה. ואמרו אנשי אמת כי בחינה הבאה מאור עולם העשיה לצד היותו מועט ואין בו אלא כל שהוא מהחיונית המנענע, והוא הוא שמרגיש במורגשות עולם הזה, ועשה ה' ככה לסיבת העולם להיותו גס, וזו תקרא נפש, והבא מאור עולם היצירה לצד היותו עליון מעולם העשיה הארתה גדולה ותקרא רוח, והבאה מאור עולם הבריאה תקרא נשמה לצד הדרגתה, והבאה מאור עולם האצילות תקרא נשמה לנשמה:
@636 **והנה** האדון ה' צבאות עשה התקשרות כל העולמות רוחני וגשמי באדם ישר קשר כל הגשמיות וכל הרוחניות יחד, הגשמיות בנה ד' יסודות ושם שם לו חק הרוחניות מכל העולמות. ויש לך לדעת כי הגשמיות יתנגד לחיבור הרוחני יותר מהתנגדות אש ומים, לזה נתחכם ה' ב''ה וברא באדם מכון הראשון שהוא הנפש שאין בה אלא חלק מועט מהרוחניות והשרה בתוכה בחינה עליונה ממנה שהיא בחינת הרוח, ונמצאת הנפש ממוצעת בין הגוף ובין הרוח, כי אין הרוח עומד בגשם בלא אמצעיות הנפש, וכמו כן הרוח ממציע בין הנפש והנשמה, כי הנפש בערך הנשמה שאורה רב כגוף לערך הרוח, וכן נשמה ממצעת בין הרוח ובין נשמה לנשמה נמצאת אומר כי הנפש יכולה עמוד לבדה, והרוח בב', והנשמה בג', ונשמה לנשמה בד':
@636 **עוד** אמרו יודעי דעת קדוש (זוהר ח''ב צד:) כי התעצמות השלמים באמצעות לקח טוב אשר נתן לנו הבורא הוא לעלות מדרגה התחתונה למדרגה שלמעלה ממנה, על זה הדרך נפש יעלה למדרגת רוח, ורוח למדרגית נשמה, ונשמה למדרגת נשמה לנשמה, וזו היא תכלית סיבת בריאת האדם תן לחכם ויחכם:
@636 **עוד** אמרו ז''ל כי ההשגה בהעלאה זו תסובב שישלח אדם ידו ויהנה כאדם העושה בשלו, והוא סוד (תהלים קכח) יגיע כפיך כי תאכל אשריך וטוב לך, פירוש האושר שלך והטוב שלך, והוא מאמר חז''ל שהנפש קודם ביאתה לעולם הזה אוכלת כבת בוגרת, ובחזרתה כבת נשואה. עוד יש לך לדעת כי כל אשר יצר וברא ועשה ה' הכל עומד למזון ולמחיה מעולם העליון שאליו יקרא עולם האצילות, והוא אור היו''ד שבשמו יתברך, והמזון ההוא יקרא קודש, והוא מקור החיות והאושר והטוב, והגם כי כל הנבראים יורד להם החיות, כי זולת החיות אין נברא, והוא סוד אומרו (נחמיה ט) ואתה מחיה את כולם, על כל זה ישתנה השפע בהתרחקותו, כאשר ישתנה הצומח מן הארץ כשמתרחק מהיניקה, ועשה ה' ככה לתת לכל אחד כפי בחינתו וכפי אשר ישיג בטהרתו, גם לארץ הגשמית יתן לה ה' מים וזהו שפעה וחיותה והולידה והצמיחה. ועל דרך זה גם כן הוא שפע החיוניות של הנפשות והרוחות והנשמות ונשמות לנשמות כפי בחינתה, כי לא כל הנפשות בהדרגה א', ולא כל וכו' שוות וכו', ואין לך נברא בין בגשמיים בין ברוחניים בין במלאכים העליונים בין בנפשות רוחות (כוחות) נשמות נשמות לנשמות שאינם צריכין לשפע הקדוש, אלא כל א' כפי שורשו הקדוש:
@636 **עוד** יש לך לדעת כי להיות שיש אדם שזוכה לכל המדרגות הקדושות, ויש שזוכה לג', ויש לב', ויש לאחד, ומי שלא זכה אלא בנפש בעולם הזה ולא לרוח אין מעשיו מועילים כלום, כי אין כח בידו להשיבה למעלה, כי אין מחזיק בידו להטותה אלא באמצעות הרוח אם יזכה לרוח באמצעות מעשיו הטובים יעלה הנפש למדרגת הרוח. ודע כי כאשר יעלנה למדרגת הרוח הנה הוא קנאה במעשיו ונקרא הוא בעלה, והוא סוד אומרו (משלי כג) אם בעל נפש אתה פירוש קנאה והוא שלו באמצעות היגיעה, והמושג מהיגיעה נעשה הרוח בעל נפש כי עולה היא עמו ושוים הם בהדרגה ומקום תחנותו תחנותה מפתו תאכל ומכוסו תשתה ובחיקו תשכב, וכן הרוח בערך הנשמה, והנשמה בערך נשמתה, וקניית מדרגת בחינת הקדושות הלא הוא באחד מב' סיבות, או מצד המזריע כי האב יפעיל כח עליון בבן כמו שפירשתי בפרשת ויחי (מט ג) בפסוק ראובן בכורי. או לצד התעצמות באמצעות עסק התורה, וכמו שכתב בזוהר הקדוש (ח''ג צא:) בפרשת שור או כשב או עז כי יולד כי האדם יכול להשיג מה כפי התעצמותו בתורה וכו' אפילו יהיה במדרגה שאין למטה ממנה אם יטריח ישיג הדרגות עליונות כפי שיעור היגיעה יעיין שם דבריו:
@636 **עוד** יש לך לדעת כי המסובב מחטא האדם גם כן ישתנה כפי מה שהיא בחינת האדם, כי אינו דומה פגם אשר יסובב לנפש כפגם הרוח ושאר הדרגות, כי פגם הנפש יסובב כליונו בסוד (יחןקאל יח) הנפש החוטאת היא תמות, ופגם הרוח אפילו לא יסובב אלא כתמים ונגעים יחשב פגם גדול, ולזה יצוה ה' עליו והרוח תשוב אל האלהים אשר נתנה ודרשו רז''ל (שבת קנב:) תנה לו כמו שנתנה לך, שזולת זה נדבקים בה סרכי הטומאה ויסבוה לגיוני הסטרא אחרא וימנעוה משוב אל מקומה הראשון. ופגם הנשמה הגם שלא יגיעה כשיעור הנזכר אלא יפחת אורה ממה שהיה תכסהו כלימה, כי הכל כפי המבייש והמתבייש. ופגם נשמה לנשמה הגם שלא יגיע עליה מהפגם ולא הפחתה אורה אלא שיסוכב שתצא ממנו שלא כרצונה, כמו שאמרו בתיקונים (תיקון ע') בסוד פסוק לא יאונה לצדיק כל און שמדבר הכתוב במי שיש לו נשמה לנשמה וכשבא אדם לידי חטא מסתלקת הנשמה הקדושה שלא יאונה לה און, וסילוקה זה תקפיד עליו כפי ערך מעלתה, הא למה הדבר דומה למאכסן מלך בביתו וחוזר בו ומגרשו:
@636 **ואחרי** הודיע ה' אותנו כל האמור נוכל לומר כי הן הנה הדברים האמורים בכתובים. והתחיל לומר **וכל זר לא יאכל קודש** מדבר בב' עניני קודש, בקודש הקרבנות, ובקודש הנעלם שהוא שפע הרוחני מזון לבני אלהים. ואמר **תושב כהן ושכיר** לרמוז אל הרוח ואל הנפש, כי הרוח הוא תושב כהן פירוש כי בו מושב הנשמה הנקראת כהן שהיא מדרגה העליונה, ושכיר גם כן הוא הנפש כי הוא הפועל כל מלאכות האדם, ב' בחינות אלו הודיע הכתוב שאינם ראויים לאכול מהמזון הנקרא קודש לצד היותו מדרגה גדולה, וצא ולמד מה שכתב הרשב''י (זוהר ח''ב קכא) בהפרש שבין קודש לקודש. ואמר **וכהן כי יקנה נפש** וגו' פירוש כהן היא נשמה העליונה תקרא כהן. והזכירה בלשון זכר לומר כי כיון שהגיעה לגדר זה תקרא במדרגת זכר, כי יקנה נפש כי באמצעות כשרון מעשיה קנתה גם הנפש והעלתה אותה למדרגתה ותקרא בעל נפש.
@636 **הוא יאכל בו** פירוש כי יזכה ליהנות גם הנפש מקודש מה שלא היה זה קודם עלייתה, ואמר הנפש ומכל שכן הרוח שהוא עליון מנפש. ואומר **ויליד ביתו** יכוין אל נפשות הקדושה אשר נפלו מזמן קדמון והם מתבררים באמצעות כשרון מעשה הצדיקים, שהמעשה הטוב הוא כאבן השואבת להוציא ניצוץ הטוב, ויתיחסו בשם ילידי הנשמה המבררתם, ואמר הכתוב שגם הם יעלו עמה ליהנות מקודש:
@636 **ואומרו** ובת כהן מדבר הכתוב בנשמה שנפגמה ונטמאה במעשיה שתפסיד הנאת הקודש והוא אומרו **ובת כהן** שהיא הנשמה, **כי תהיה לאיש זר** שהוא ס''מ שחמדה מטעמותיו ותזנה אחריו, היא בתרומת הקדשים לא תאכל, דקדק לומר בתרומת, לומר שאפילו תרומת הקדשים לא תאכל תרי ממאה, ואין צריך לומר הקודש עצמו. ודקדק לומר היא לשלול אחרת הבא משפטה בסמוך, דכתיב ובת, וזה הוא עינוי הנפש כשיחסר מזונה היא נשפלת ונחשך אורה וירד הדרה רחמנא ליצלן:
@637 **ואומרו ובת כהן כי תהיה אלמנה וגו'**. מדבר הכתוב בבחינת נשמה לנשמה שאין מגיעה דביקות הרע כל עיקר אלא שהיא בורחת והולכת לה כמו שאמרנו, והוא מה שנתן טעם בבת כהן תנשא, לומר כי בחינה זו מעולה ביותר, ולזה אין זר אתה כמו שאמרנו שעליה נאמר לא יאונה לצדיק וגו'. וקורותיה הם שתהיה אלמנה וגרושה אמר אלמנה כאשה שאין לה בעל הזן ומפרנסה כמו כן בעלה לא זן ולא מפרנסה במצוות ובמעשים טובים **וגר** ושה כי לצד שפשט ידו האדם לעבור פי ה' גרשה ממנו כמו שכתבנו, **וזרע אין לה** שלא עשה פירות בעולם הזה, אף על פי כן **ושבה אל בית אביה** וחזרתה היא לאכול משלחן אביה כימי נעוריה שהיתה אוכלת בבושה מלחם אביה תאכל, מה שאין כן נשמה שהשיגה עשות תורה ומצות שאוכלת יגיעה כאדם האוכל משלו. ואומרו **וכל זר לא יאכל קודש** נתן טעם למה אין ה' מרחם גם לנשמה להאכילה קודש בתורת חן וחסד, לזה אמר הטעם הוא וכל זר וגו', ולזה נשמה שנדבק בה בחינת הרע הנקרא זר לא תאכל לבל יאכל הזר ההוא הנדבק בה:
@638 **ונתן לכהן את הקודש**. רז''ל נחלקו בפרק ו' דתרומות רבי אליעזר אומר כל שראוי להיות קודש, ור''ע אומר הקודש שאכל ע''כ, ואולי שיכוין לומר שעל ידי הנתינה זו מעלה עליו הכתוב כאילו נותן הקודש עצמו, וכאילו לא אכל הקודש:
@640 **והשיאו אותם** וגומר. פירוש כשלא יפרעו קרן וחומש יגדילו גדר האשם שעשו בשוגג ליקרא מזיד שהוא עון כיון שיש בידם נתקן ואינם מתקנין, והוא אומרו **והשיאו** פירוש ינשאו אותם פירוש הם שיהיה הדבר עון את שאינה אלא אשמה. ואו **מרו באכלם את קדשיהם** פירוש שיחשב להם מזיד אכילת הקדשים שאכלו לא הזדת מניעת הפרעון, ועיין מה שפירשתי בפסוק שלפני זה:
@659 **מועדי ה' וגו'**. גזירת הדיבור. רז''ל אמרו (תו''כ) כי הוא אשר תקראו אותם, פירוש כי מועדי ה' הם בזמן שיקראו אותם ישראל. וצריך לדעת למה חזר לומר אלה הם מועדי. עוד צריך לדעת למה חזר לצוות על השבת. ועוד רואה אני שחזר לומר פעם שני אחר מצוות השבת אלה מועדי ה'. ונראה כי שיעור הכתובים הוא שמתחלה צוה ה' כי עיקר המועדות תלוי בזמנים אשר יקראו אותם, וחש הכתוב שיטעו לומר שבכלל זה גם כן קדושת יום השבת אם יסכימו לדחותו מיומו ליום אחר יתקדש על פיהם, לזה חזר ופירש **אלה הם מועדי ששת ימים** וגו' פירוש אלה שהם שבתות הם מועדי מועדים שקבע הבורא ואינם בגדר השתנות. וחזר לומר **אלה מועדי ה' מקראי קודש** אשר הרשיתי אתכם שתקראו אותם אתם בחודש הראשון וגו' פסח שבועות ראש השנה יום כיפור סוכות אלו אין קדושתם אלא על פי ישראל:
@659 **עוד** נראה לומר טעם שכפל לומר **אשר תקראו אותם** ב' פעמים, על דרך מה שכתב רמב''ם בפרק ד' מהלכות קידוש החודש וזה לשונו על שלשה סיבות מעברין השנה על התקופה ועל האביב ועל פירות האילן. ויש שם דברים אחרים שבית דין מעברין בשבילן מפני הדרכים וכו' ומפני הגשרים וכו' ומפני תנורי פסחים וכו' ומפני גליות ישראל שנעקרו ממקומן ועדיין לא הגיעו לירושלים וכו' ע''כ. הרי כי לב' סיבות כוללות מעברין ומאחרין המועד, הא' לצד תנאי הזמן שיהיה באביב, והב' לצד כשרון העם, לזה אמר הכתוב ב' פעמים אשר תקראו אותם, ושלא תאמר שלצד תנאי הזמן שהתנה הכתוב חודש האביב לבד מעברין אבל לכשרון העם יעשה המועד בזמנים הנמצאים מוכשרים, תלמוד לומר ב' פעמים **אשר תקראו אותם**:
@662 **בין הערבים פסח לה'** פירוש חלק הנוגע לה' מקרבן פסח שהוא מתן דמים והקטרת חלבים יהיה בין הערבים, אבל חלק הנוגע לישראל שהוא אכילת הבשר יהיה בליל ט''ו על מצות ומרורים. עוד ירצה באומרו **פסח לה'** לצד שפסח מצרים שהוא פסח ראשון עשוהו לאהבת הערב והמועיל, הערב שאמרו ז''ל (שמו''ר פי''ט) שנתבשם פסחו של משה מרוחות (מריח) גן עדן, ועיין מה שפירשתי בפרשת בא (יב מג), והמועיל לפסוח המשחית על בתיהם, וכאן אמר כי פסח דורות יעשוהו לשם ה' הגם שאין בו אחד משתיהן:
@672 **וספרתם לכם וגו'**. אומרו **לכם** לצד שיצו ה' לספור שבע שבתות, ואמרו ז''ל (זוהר ח''ג צד.) כי לצד שהיו בטומאת מצרים ורצה ה' להזדווג לאומה זו דן בה כמשפט נדה שדינה לספור ז' נקיים, וצוה שיספרו ז' שבועות ואז יהיו מוכשרים להכניסתם כלה לחופה, והגם כי שם ז' ימים וכאן ז' שבועות, לצד הפלגת הטומאה וגם היותם בכללות ישראל שיער התמים דעים כי כן משפטם, ועיין מה שפרשתי בפסוק (יתרו יט א) בחודש השלישי לצאת וגו', והוא מאמר הכתוב כאן **וספרתם לכם** פירוש סיבת ספירה זו היא לסיבתכם לטהרתכם שזולת זה תיכף היה ה' נותן להם התורה. ולדרך זה ידוייק על נכון טעם **ממחרת השבת** ולא מיום השבת עצמו, כי כן משפט הספירה שיהיו כל הימים שלימים, ולצד שיום ט''ו בניסן שהוא יום השבת האמור כאן מקצת היום היו עדיין בארץ מצרים לזה יצו ה' לספור ממחרת, והגם כי זה היה בפסח מצרים, כמשפט הזה יעשה באותו פרק עצמו מדי שנה בשנה, כי כמו כן יעשה בסוד ה' כידוע ליודעי חן. וכפי הפשט לזכרון העובר ביום השבת לזכרון כי ששת ימים וגו' והמשכיל יבין. ועיין מה שפרשתי בפרשת בראשית בפסוק ויכל אלהים ביום השביעי, ובדרך רמז רמז באומרו **וספרתם** על דרך אומרם ז''ל כי נשמות עם בני ישראל הם בבחינת הלוחות, ובאמצעות תחלואי הנפש וטומאת התיעוב יתלכלכו ויחשיך אורם, וארז''ל (ויק''ר פל''ב) כי הלוחות של סנפרינון היו. לזה אמר **וספרתם לכם** פירוש באמצעות מנין זה אתם מאירים כסנפרינון את עצמיכם:
@672 **ממחרת השבת מיום וגו'**. פירוש מעכשיו קודם שתכנסו לארץ ממחרת השבת, וכנגד אחר ביאתם לארץ אמר **מיום הביאכם** וגו', ולזה הקדים ממחרת השבת להיותה מצוה שישנה אז מה שאין כן מיום הביאכם שהוא אחר ביאה לארץ:
@672 **ובקצרכם את קציר וגו'**. מה ענין זה לכאן. ואולי שבא לחייב גם שדה שהובא ממנו העומר שחייב בלקט ופאה, שתבא הסברא לומר כיון שתחלתו נקצר לקרבן יהיה פטור מפאה וכו' תלמוד לומר. ולזה תמצא שלא הזכיר אלא לקט ופאה שהם חובת שדה בלא סובב אמצעי ולא הוזכר שכחה שהיא באה מצד בעל השדה, ות''ל בתורת כהנים אמרו שרמז ה' בזה שכל מי שנותן לקט שכחה ופאה מעלה עליו כאלו בית המקדש קיים והוא מקריב קרבנותיו לתוכו וכו' ע''כ. מה שאמר שכחה תגם שלא הוזכר בפסוק, לצד שהיא מצוה שחייב בה כלקט ופאה כללה. והכ' שלא כתב להעירך שנתכוין גם כן לדרך שכתבתי:
@684 **יוה'** ' **כ וגו' מקרא קודש וגו'** פירוש בלא אמצעות קריאתם אותו קודש ובלא עינוי שמתענים בו הוא יום כיפור מצד עצמו, ומעתה יש שכר למצות קריאת קודש ועינוי בו מלבד ריוח הכפרה:
@685 **וכל מלאכה וגו' כי יום כיפורים וגו'**. נתינת טעם זה הוא על דרך מה שאמרו בסוטה דף מ' שאין אומרים פסוקים כשהכהנים מברכין את העם והטעם אמרו וז''ל כלום יש עבד שמברכין אותו ואינו מאזין ע''כ, ולדרך זה אמר וכל מלאכה לא תעשו, והטעם כי יום כיפורים הוא פירוש כי עיצומו של יום מכפר ויש לך אדם שהזמן מכפר עליו והוא עסוק במלאכתו, והמשכיל על דבר עיצומו של יום לבבו יבין המכפר כי הוא אדון המאיר היום לסגל סגל דבר זה:
@691 **הזה חג הסוכות**. בתורת כהנים דרשו יתור הזה, ופירשתי הברייתא בפרשת מצורע (י''ד ז') (לז) **מועדי ה'**. אמר רבי עקיבא (תורת כהנים פסוק ל''ה) אלו ימי מועד שאסורין במלאכה ע''כ, ונראה כי לזה גמר אומר **ומלבד מתנותיכם** וגו' **כל נדריכם** וגו' **כל נדבותיכם** אשר תתנו לה' שמשמע אפילו עולות ואין עולות באין ביום טוב כאומרם (ביצה י''ט.) לכם ולא לגבוה אלא ודאי שאין הכתוב מדבר אלא בחולו של מועד:
@703 **צו את בני ישראל וגו** '. צריך לדעת מה ענין מצות שמן והדלקתו במקום זה, גם מצות מערכת השלחן מה ענינו לכאן, ומה גם שכבר נאמרו הדברים ככתבן במקומן במצות המשכן ומצותיו, ורש''י ז''ל פירש מה שפירש, ואין בדבריו דבר מספיק, ורמב''ן ז''ל כתב שכלה השמן וכו', ואין ראיה לדבריו, ואולי כי לצד שצוה מצות שבעיות פסח ז' ימים, חג הסוכות ז' ימים, שמחת המינים ז' ימים, גם ראש השנה ויום הכיפורים ישנם בבחינת השבע להיותם בחודש השביעי, לזה סמך לזה גם כן מצות המנורה שהיא בחינת שבע נרות, גם השלחן ישנו בסוד שבע דכתיב שש המערכת וגו' והשלחן הסדורות עליו שהוא סוד המתקבץ בו שש מעלות והיא משלמת שבע, ותמצא שצוה גם כן בפרשה זו מצות העומר שהוא שבע שבתות, גם מצות השבת, נמצאת אומר שכלל כל מצות השביעיות יחד לומר כי סודם ועיקרם אחד:
@703 **עוד** אפשר שנתכוין בסמיכות פרשת מנורה לפרשת סוכה על דרך מה שאמרו ז''ל (תורת כהנים) בפסוק מחוץ לפרוכת העדות וז''ל וכי לאורה היה צריך והלא כל המ' שנה שהיו במדבר לא הלכו אלא לאורו, ופירשו התוספות (שבת כ''ב:) שלא היו הולכים לאור החמה אלא לאור השכינה שהיו רואים מה שבתוך התפוח וכו' אלא עדות לבאי עולם וכו' ע''כ, והוא מה שנתחכם ה' בסמיכות זה של מצות המנורה למצות סוכה כי בסוכות וגו' לומר כי ישראל לצד ענני כבוד לא היה להם אור השמש והליכתם היתה לאורו יתברך, אם כן מצות מנורה אינה אלא לפרוכת העדות עדות לבאי עולם וכו':
@711 **ויצא בן אשה וגו'**. אמר **ויצא** על דרך אומרם ז''ל (תנחומא) בפסוק ויצא העגל הזה שיצא בלא כוונת הפועל, כמו כן כאן לא שנתכוונה האשה ישראלית למעשה הכיעור אלא בלא מתכוין לדבר איסור יצא הנגע, כאומרם ז''ל (שמו''ד פ''א) שהעמיד המצרי הבעל לעבודתו וחזר לבית ועשה מעשה והאשה חשבה כי בעלה היה ויצא נגע זה, ולזה תמצא שהכתוב משוה זכרון האשה לזכרון האיש הישראלי דכתיב **האשה הישראלית ואיש הישראלי** כי נקיה האשה מעון ושוה לאיש הישראלי המוזכר לפנינו שאין בו דופי, ואומרו **בתוך בני ישראל** לומר שלא היה בתוכם ממזר כיוצא בו:
@711 **עוד** ירצה שלא נתנו לו מושב בתוכם שבמקום שהיה רוצה לטעת אהלו היה אומר לו אינך משלנו, ורז''ל (תורת כהנים) אמרו שבא לומר הכתוב שנתגייר ואלו ואלו דברי אלהים חיים:
@711 **ואיש הישראלי**. טעם שלא הוזכר שמו, אולי שלא רצה להזכירו משום שעל ידו היה הדבר שנקב בן הישראלית את השם ומגלגלין וכו', ואין הקדוש ברוך הוא חפץ לגנות אדם, ומה גם בתורה שנשאר הרושם לעולם ועד:
@711 **עוד** נתכוין הכתוב לומר שמריבה אשר נצו עליה היא על הפרש הנרשם שזה הוא בן ישראלית וזה בן ישראלי וכאן כלל כל מה שאמרו ז''ל (ויק''ר פל''ב) למ''ד על דבר יוחסין ולמ''ד וכו', ולא חש הכתוב להאריך לשון ולומר גם כן שמו כי אין צורך בדבר:
@712 **ושם אמו**. צריך לדעת למה לא הזכיר שמה בתחלה כשהזכירו עד הבאתו אל משה, ויש לומר בב' דרכים, האחד לשבח על זה הדרך **ויביאו אותו אל משה ושם אמו** וגו', פירוש גם היא מכלל המביאים והאחד לגנאי ויביאו אותו אל משה ועל ידי הבאה זו נתחייבה שהכתוב יפרסם אותה שאמו היא שלומית, וממוצא דבר אתה יודע כי נכמרו רחמיה על בנה וכתיב (משלי י''ב) ורחמי רשעים אכזרי, לזה גילה אותה הכתוב כי זאת האשה וזה בנה, גם הזכיר שבטה להטעם עצמו שכתבתי כי מן הסתם השבט ירחם ויעמוד לעזר הקרובים, ולזה אמרו במדרש (ויק''ר פל''ב) גנאי לו גנאי לשבטו וכו':
@723 **כגר כאזרח**. ולא אמר הגר כאזרח, שאז יהיה נשמע כי מדרגת גר למטה ממדרגת אזרח שהקטן נתלה בגדול, לזה אמר **כגר כאזרח** פירוש האזרח כגר והגר כאזרח ששקולים הם במשפט:
@724 **ובני ישראל עשו וגו'**. קשה מה מקום ובני ישראל עשו וגו' אחר שאמר ויוציאו את המקלל וגו' וירגמו אותו אבן הריני רואה שעשו את אשר צוה ה', וי''ל לצד שהיה הדבר על ידי מריבה ומחלוקת שהיתה בין הישראלי ובין בן הישראלית יש מקום לומר שעשו בו משפט כתוב לאמצעות גם כן טינא שבלב, לזה אמר **עשו כאשר צוה ה'** פירוש לצד מצות ה' הוא שעשו:
@724 **או** נתכוין הכתוב להעלות המצוה שעשאוה כל ישראל הגם שלא היתה בו יד כולם:
@724 **או** ירצה שעל ידי מעשה זה שקנאו קנאת כבודו יתברך העלה עליהם הכתוב גם כן כאלו עשו כל התורה, והוא אומרו כאשר צוה ה' את משה בדרך כלל:
@724 **או** יאמר על זה הדרך לצד שבמצות ה' למשה אמר **הוצא את המקלל** שחוזר אל משה כי הוא יוציא אותו והרגימה תהיה על ידי ישראל דכתיב **ורגמו אותו כל העדה**, וכאן אמר ויוציאו המקלל שחוזר אל ישראל המוזכרים בסמוך, ובא הכתוב לשבח לישראל ואמר **ובני ישראל עשו כאשר צוה ה' למשה**, פירוש לעשות הוא קדמו הם בדברו אליהם ועשו אותו קודם שיעשהו משה לצד הזריזות והמהירות לקיים מצות ה', ולדרכים הראשונים נפרש הוצא, או הוא או שלוחו:
@724 **חסלת פרשת אמור**
@725 **בהר סיני וגו'**. צריך לדעת למה הזכיר הר סיני במצוה זו, והגם שרבותינו ז''ל אמרו (תורת כהנים) כי ללמד בא שכל המצות נאמרו כללותיהן ופרטותיהן בסיני, עדיין יש מקום לשאלתינו למה לא לימד זה אלא במצוה זו בדיוק ולא במצוה ראשונה או אחרונה, ואולי כי לצד שהזכיר מתנת הארץ דכתיב **אשר אני נותן** דקדק לומר בהר סיני, לומר כי מחמת הר סיני פירוש מה שקיבלו בו היא שנגמרה המתנה, שעל מנת תורה נתן ה' את הארץ:
@725 **עוד** על פי מאמר הגמרא מסכת עבודה זרה (כ'.) ופסקו רמב''ם בפרק ג' מהלכות זכיה וזה לשונו אסור לתת לעכו''ם מתנת חנם ע''כ ואם כן ישראל קודם שקבלו התורה דינם כעכו''ם ואחר קבלת תורה יכול ליתן להם, לזה אמר **בהר סיני** שבזה יוכל לומר אשר אני נותן לכם, ובזה נתישב גם כן למה הוצרך לומר אשר אני נותן כי פשיטא כי הוא הנותן ואין אחר לטעות בו, ותמצא שבפרשת קדושים (לעיל י''ט כ''ג) אמר כי תבואו אל הארץ ונטעתם וגו' ולא הוצרך לומר בה סימן, אלא שנתכוון למה שכתבנו, ומעתה יתיישב למה בחר ה' ללמד בנין אב זה לכל התורה בפרשה זו ולא בפרשה אחרת:
@726 **דבר וגו' ואמרת וגו'**. טעם הכפל, לצד שיש במצוה זו ענין מניעת עבודת אדמה והפקרת הפירות העולים מהאילנות וצמח האדמה, כנגד מניעת עבודת האדמה והכנת הצלחתו אמר **דבר** לשון קושי, כי הוא דבר שאין רצון אדם חפצה בו לצד היותו מניעת הטוב, וכנגד הפקרת הצומח אמר **ואמרת**, כי הוא דבר שכל אחד ישמח בו שיאמר ידו בכל, גם לצד ההבטחות שצוה בענין (פסוק כ''א) ועשת את התבואה לשלש השנים אמר ואמרת אמירה המסעדת את הלב:
@726 **עוד** ירצה לצד שמצוה זו של שביתת הארץ יש בה ב' דברים, הא' דבר מלך שלטון שעל עבדיו חיוב לקיים כל דבר, והב' הגם שיהיה דבר זה בין אדם לחבירו יתחייב עשותו כפי הדין, כי הנותן מתנה לחברו ומתנה עמו בשעת המתנה תנאו קיים, וכמו כן האדון ב''ה בשעת המתנה מתנה תנאים כאומרו אשר אני נותן ולא אמר אשר נתתי, אשר על כן אמר כנגד דבר מלך שלטון אמר דבר, וכנגד היות הדבר מתחייב מהמשפט אמר ואמרת פירוש בלא טעם גזירת מלך יקבלו המאמר:
@726 **ושבתה הארץ וגו'**. צריך לדעת מה היא כוונת הכתוב במאמר זה, אם על שנת השמיטה הרי הוא אומר בסמוך ובשנה השביעית שבת שבתון:
@726 **אכן** נתכוון ה' לומר סמוך לזכרון הנתינה להם שיור לה' בארץ, והוא אומרו **אני נותן** ולא מתנה חלוטה אלא **ושבתה** וגו' **לה'**, וחזר ופירש שיעור שבת זה, אם חודש, אם שנה, בכמה שנים, ואמר **שש שנים ובשנה השביעית שבת** וגו', ומעתה אם לא היה אומר הכתוב ושבתה וגו' אלא מה שאמר אחר כך ובשנה השביעית לא הייתי יודע ששייר ה' לעצמו שנה זו אלא שנתן מתנה חלוטה לצמיתות ולא כן הוא:
@726 **והצצתי** וראיתי כי אלהים חשבה לטובה בסדר מעשה זה, כי אם היה ה' נותן הארץ על תנאי בהבטל התנאי תתבטל המתנה, ובמה שעשה השיור כשישלחו יד בשיור לא מפני זה תתבטל המתנה אלא עליהם לפרוע כל העולה בשיור, והעד הנאמן מה שאמר הכתוב (לקמן כ''ו ל''ד) אז תרצה הארץ את שבתותיה את אשר לא שבתה וגו', ומעתה אין ביטול למתנת הארץ עד עולם:
@726 **עוד** נראה טעם סמיכות ושבתה לאשר אני נותן, על פי דבריהם שאמרו (ב''מ כ''ג.) הן של תלמיד חכם במקום שבועה, והחכם אשר ממנו תוצאות חכמה הוא ה' אלהים, ולזה כשהוציא מפי עליון אני נותן אמירתו במקום שבועה. או גם כן לצד שמתנת ה' לישראל דין צדקה יש לה ואמירתה כדין נדר (ר''ה ו'.), ולזה תכף ומיד תוך כדי דיבור לאומרו אשר אני נותן אמר ושבתה הארץ וגו', וזולת זה מה שאמר אחר כך ובשנה השביעית וגו' אינו תוך כדי דיבור למאמר הנתינה שהרי הפסיק במאמר שש שנים וגו' ושש שנים וגו':
@727 **שש שנים וגו'**. נתכוון ליתן עשה על הזריעה וגו' ועל הזמירה של שנה שביעית, כי לאו הבא מכלל עשה עשה (פסחים מ''א:), והגם שכתב רמב''ם בהלכות שמיטה (פ''א) כי עשה נשמע מאומרו ושבתה הארץ שבת וגו', אף על פי כן אינו נשמע משם עשה דזריעה ועשה דזמירה, או אולי לחייבו בב' עשין, ועיין בפסוק ואספת:
@727 **ושש שנים תזמור**. כפל לומר ושש שנים ולא הספיק לומר שש שנים תזרע שדך ותזמור כרמך, יתבאר על דרך אומרם ז''ל בפרק ה' דשביעית וז''ל בנות שוח שביעית שלהם שנייה וכו', וכתבו הטעם משום שאנו הולכים בהם אחר חנטה וכיון שחנטו בשביעית דינם כפירות שביעית ואסורים בשנה שניה לשביעית, הרי שבאילנות אנו הולכים אחר חנטה ובדגן ובירקות אנו הולכים בהם אחר לקיטה כמו שאמרו בפרק קמא דראש השנה (י''ג:), ואשר על כן הבדיל ה' ואמר שש שנים של זרעוני שדה בפני עצמן ושש שנים של הכרם בפני עצמן לצד שאין משפטן שוה שזה אנו הולכים בו אחר לקיטה וזה אנו הולכים בו אחר חניטה:
@727 **ואספת וגו'**. צריך לדעת למה הוצרך לומר ואספת, ואולי שנתכוון לדייק **ואספת את תבואתה** ולא ספיחיה העולים בשביעית, והכוונה בזה ליתן עשה על אסיפת ספיחים כי לאו הבא מכלל עשה עשה, או ירצה להבטיח שהגם שזרעו הארץ שש שנים וכפי טבע הארץ כשזורעה שנה אחר שנה לא תתן כחה, וכמאמרם ז''ל (ב''ב כ''ט.) זורע שנה אחת ומובירה שנה אחת וכו', שבזה תתן כחה אבל שנה על שנה ובפרט שש שנים ודאי שתכחש הארץ, ויאמר האומר הנה טוב מאד שתשבות הארץ באופן אחד בסדר שתתן כחה בשנת הזריעה, ואין לדבר זה גבול שתהיה שנה השביעית בדיוק שנת שבתון, לזה אמר **שש שנים** ואף על פי כן **ואספת את תבואתה** בגדר הראוי לה בלא הכחשה משנה לשנה, ואין צורך להוביר אותה בשנה משני השש כי יצו ה' את הברכה בארץ הקדושה, ואולי כי לזה גם כן נתכוון באמרו **דבר ואמרת**, דבר כפשטה, ואמרת כי אדרבה מתנה טובה אני נותן להם שיזרעו השדה וכו' שש שנים זה אחר זה ולא תכחש הארץ מתת כחה בשוה מבלי שיצטרכו להוביר זולת שנה השביעית למצות מלך:
@727 **עוד** יתבאר על דרך מה שאמרו בסנהדרין דף כ''ו וז''ל מכריז ר' ינאי פוקו וזרעו בשביעית משום ארנונא, וכתבו התוספות ואם תאמר משום ארנונא התירו לחרוש בשביעית דאורייתא וי''ל וכו' אי נמי י''ל דפיקוח נפש הוא ששואל ממנו ואין לו וכו' ע''כ, והוא מאמר הכתוב **שש שנים** וגו' **ואספת** וגו' פירוש אימתי אין אני מתיר לך אלא שש ולא שבע ואספת כשאתה זורע לאסוף לעצמך אבל לארנונא לתת למושל זרעו אפילו בשביעית כדברי ר' ינאי:
@730 **והיתה שבת וגו'**. פירוש שלא תאמר שיהיה משפטו כשאר שולחן הגבוה שהכהנים זוכים בו אלא לכם לכולכם יחד כהנים לוים ישראלים וכו', וחזר ופרט לך וגו', ואם תאמר אם כן למה נאמר לכם שלא היה לו לומד אלא הארץ לאכלה לך וגו', ונראה כי חש לומר בדרך זה שהייתי אומר הקודם בפסוק קודם באכילה, כדרך שאמרו (ספרי) ענייך ועניי עירך וגו' ממה שאמר הכתוב (רבדים ט''ו ז') כי יהיה בך אביון וגו', לזה קדם הכתוב וכלל כולם יחד ואמר לכם שאין גדר לאחד יותר מחבירו בפירות שביע ית:
@738 **וכי תמכרו וגו'**. בתורת כהנים אמרו וז''ל מנין שאין אונאה לקרקעות תלמוד לומר או קנה מיד אל תונו המטלטלין יש להם אונאה ואין אונאה לקרקעות ע''כ, ובגמרא (ב''מ נ''ו.) הקשו מפסוק את כל ארצו מידו והעלו כל ידו ידו ממש ושאני התם דליכא למימר הכי ע''כ, קשה ונלמוד משם שכשיאמר ידו אין ידו ממש וי''ל שתיבת ידו משמעותו הוא ידו ממש אלא שגם יכול להיות נשמע גם כן רשותו אבל משמעות ידו הוא יותר קרוב בנשמע, ולזה כשיאמר הכתוב ידו הגם שב' הפירושים צודקים בה אין אני דן בה אלא הדרגה היותר קרובה שהוא ידו, ואם אין כוונת הכתוב לומר ידו ממש עליו שלא לומר תיבה שנוכל לפרש בה הבנה זרה, מה שאין כן במקום שאין לפרש בה אלא פירוש אחד לא יחוש הכתוב לדבר בלשון שיכול לישמע בו הענין. ונשאר לנו לחקור זאת לדבריהם ז''ל שדרשו שאזהרת אל תונו אינה אלא במטלטלין והלא עיקר הכתוב במכר קרקעות נאמר:
@738 **ונראה** כי הגם שרבותינו ז''ל דרשו כן הוא על פי ההלכות שהיה בידם מסיני סמכום בכתובים ועל כל פנים יתיישב הכתוב לפי פשוטו על זה הדרך כי לצד שצוה ה' על הארץ שלא תמכר לצמיתות צוה שלא יאנה המוכר ללוקח שאינו בקי במשפטי התורה כי הארץ תהיה לו ולזרעו עד עולם, ואחר כך יבוא בטענת דבר מלך להחזירה לו, ודבר זה כיוצא באונאה זו יוצדק גם בקרקעות המוכר קרקע על מנת שאין עליה מערערים ויצאו עליה מערערים שהוא ביטול מקח, וכאן אין לך מערערים כהוא עצמו שחוזר לערער על שדהו להחזירו בטענת זכות התורה, לזה צוה ה' ואמר במספר שנים וגו' ימכר לך, אלא במה שאמר הכתוב אל תונו סתם שכלל כל מין אונאה זה אינו אלא במטלטלין כמו שדקדק לומר קנו מיד כדברי רבותינו ז''ל:
@739 **במספר וגו** ' **אחר היובל**. צריך לדעת א' למה אמר אחר היובל ולא אמר עד היובל כי שנים הנקנים הם מזמן הקנייה עד היובל לא מה שעברו משנת היובל עד זמן הקנייה, ב' למה שינה הכתוב לשונו כשהזכיר מספר שנים אמר תקנה ותלה הדבר בלוקח וכשהזכיר מספר תבואות אמר ימכר לך יחס הדבר למוכר, ובמסכת ערכין פרק המוכר (כ''ט:) תנן המוכר שדהו בשעת היובל אינו מותר לגאול פחות מב' שנים שנאמר במספר שני תבואות, היתה שנת שדפון או שביעית אינה עולה מן המנין, ר''א אומר מכרה לו בראש השנה מלאה פירות הרי זה אוכל ג' תבואות ע''כ, ובגמרא אינו גואל לא קתני אלא אינו מותר אלמא קסבר איסורא נמי איכא, ולא מבעיא מוכר דקאי בעשה דכתיב ימכר לך אלא אפילו לוקח נמי קאי בעשה דכתיב תקנה ע''כ, עוד תניא שם וז''ל אכלה שנה אחת לפני היובל משלימין לו שנה אחרת אחר היובל ע''כ, נמצינו אומרים ד' הלכות הא' מצוה לשניהם שלא יהיה המכר פחות מגבול האמור בכתוב, ב' שאם היו ג' תבואות בב' שנים הם ללוקח, הג' אם לא היו תבואות בב' שנים כגון שנת שדפון וכו' אינה עולה לו מן המנין, הד' אם אירע יובל בתוך הב' שנים אינה יוצאה עד שישלימו ב' שנים, ופסק הרמב''ם לד' הלכות אלו בפרק י''א מהלכות שמיטה ויובל:
@739 **ועל** פי זה יתיישבו הדקדוקים על נכון אומרו **במספר שנים אחר היובל** פירוש מספר השנים שאומר הכתוב יתחייבו להיות הגם שישלמו אחר היובל כי אין היובל מפקיעם, ושינה הכתוב לשונו לומר פעם אחד תקנה ופעם אחד ימכר להטיל מצוה על הלוקח ועל המוכר שלא יהיה המכר פחות מהאמור, והזכיר השנים והתבואות לתת זכות השנים וזכות התבואות, ואמר **מספר תבואות** ולא אמר מספר תבואה לאם היו שנים שאין בהם תבואה או מחמת שדפון או שנת שמיטה ויובל אינם עולים לו מהמנין, ויש לדעת טעם נכון בדבר זה למה יאסור ה' ללוקח לבל יחזיר השדה פחות מב' שנים וכו' וכי אסור לו לאדם לתת או למחול ממונו או להפקירו ויהיה זה כאחד מהם, ואולי לצד כי רצונו יתברך הוא לבל ימכור אדם שדהו, וכמו שדרשו ז''ל (תודת כהנים בפסוק כ''ה) כי ימוך אחיך וגו' שאין אדם רשאי למכור שדהו ולהניח המעות וכו', לזה יכוון ה' בצוו ללוקח לבל ישיב הקנין למוכר כדי שבאמצעות הדבר יעמוד בין עיניו החלט החזרה תוך ב' שנים ולפעמים ימנע מחמת זה ולא ימכור:
@739 **עוד** נראה על פי מה שכתב רמב''ם שם בפרק י''א וז''ל המוכר שדהו לששים שנה אינה יוצאה ביובל שאינו חוזר ביובל אלא דבר הנמכר סתם או לצמיתות ע''כ, והכסף משנה לא רשם מנין הוציא הרב דין זה, ואולי כי דין זה הוא מה שרשם ה' במאמר זה על זה הדרך **במספר שנים אחר היובל** פירוש כשהוא מוכר במספר השנים למ' או ס' שנה ומעלה, ימכור פירוש יכול למכור וימשך המכר גם אחר היובל ואין היובל מפסיק להוציאה מידו כיון שמכר למספר שנים, ומה שגמר אומר **במספר שני תבואות** וגו' פירוש נותן טעם לדבר למה מכר לשנים ימשך אחר היובל, ואמר במספר שני תבואות ימכר לך מכר זה, פירוש כיון שמוכר לשנים הרי זה אינו מוכר אלא שני תבואות לא גוף הקרקע, שעל מכירתו הוא שמקפיד הכתוב:
@741 **ולא תונו וגו'**. רבותינו ז''ל דרשו (ב''מ נ''ח:) שהכתוב מדבר באונאת דברים, ולפי פשט הכתוב ירצה כי הגם שאמר למעלה אל תונו ודקדק לומר מיד להודיע כי באונאת מטלטלים הכתוב מדבר ולא באונאת קרקע, חש הכתוב שיטעה הטועה כי בקרקעות מותר לאונות, לזה אמר לא תונו וגו', ואמר **ויראת מאלהיך** פירוש הגם שאין דין אונאה בהם, הוא דוקא לענין משפט יושבי תבל, אבל לעולם איסור אונאה יש בדבר, וטעם שאמרתי שאין בו אונאה הוא מטעם שהנחתי משפט זה לדון אותו אני, והוא אומרו **כי אני ה' אלהיכם** פירוש שופט אתכם בדבר הזה לא לצד שמותר לאונות בקרקע, והרבה דינים מצינו בתורה שה' סלק משפטם לבית דין של מעלה, ועיין מה שכתבתי בפרשת משפטים (כ''א י''ב) ומה לפנינו יש טעם בדבר לצד שימצא אדם מוכר שוה מאה בחמשים או להפך אין בית דין יכול לעמוד על הדבר לדעת הקנין שהוא לצד הרצון ואת שהוא לצד האונאה וסלק ה' דינו לבוחן לבות ויודע מחשבות אדם ותחבולותיו:
@741 **וכבר** כתבתי למעלה כי מקח טעות ישנו אפילו בקרקעות, וכן כתב הרמב''ם בפרק ט''ו מהלכות מכירה וכן המוכר לחבירו קרקע וכו' ונמצא במקח מום שלא ידע בו הלוקח מחזירו אפילו לאחר כמה שנים ע''כ, ופירושנו זה כללוהו חז''ל במאמרם שאמרו אל תונו באונאת דברים שבזה נכלל כל מין אונאה כי גם המאנה חברו לרמותו בדברי שקר הוא מאנהו והרי הוא בכלל אונאת דברים:
@743 **ונתנה הארץ פריה**. פירוש פרי הקצוב בכחה לעשות, שהגם שנראה פרי הארץ לא נשער כי זה הוא כח הארץ ולא יותר, שהלא תמצא (כתובות קי''ב.) שגער החכם בארץ ועצרה כחה ולא נתנה פירותיה אחר כך כסדר הראשון, והרואה פירותיה אחר גערתו לא קודם יחשוב כי הוא זה כחה:
@743 **ואכלתם לשובע**. אולי כי לצד שאמר ונתנה הארץ פריה שהוא בגבול האחרון בשומן הפירות, וטעם הפירות, לצד זה אין אדם יכול לאכול מהם כדי שביעה, וזה הוא מדברים הנרגשים כפי הטבע, לזה הבטיחם ה' כי יהיו הפירות באופן שיאכלו מהם לשובע:
@743 **וישבתם לבטח וגו'**. והגם שכבר אמר בפסוק שלפני זה וישבתם על הארץ לבטח חזר לומר כן, להבטיח שלא יסובב הפלגת שבח הפירות לבא עליהם שודד, ולזה דקדק לומר בפסוק ראשון וישבתם על הארץ לומר שהבטחה זו היא על חימוד הארץ, והבטחה שניה על חימוד פירותיה, ובזה נמצאו בטוחים על הארץ ועל פירותיה:
@744 **וכי תאמרו וגו'**. פשט הכתוב הוא על זה הדרך וכי תאמרו מה נאכל, ולצד שיש במשמעות מאמר זה ב' דרכים, הא' הוא טעם שלילות הרצון בדבר זה שלא יזרעו וכו' שאם כן מה נאכל ובהכרח לזרוע לחיותנו על האדמה, ודרך ב' הוא שאלה על הנסבב מקיום מצוה זו מה נאכל כיון שלא נזרע, לזה בא הכתוב ופירש הכוונה במאמר מה נאכל במה שגמר אומר **הן לא נזרע** וגו' פירוש לא שאנו אומרים מה נאכל לתת טעם לשלילות קיום מצוה זו אלא הן אנו מקבלים לא נזרע וגו' אלא כבן שאומר לפני אביו מה נאכל אז וצויתי וגו', אבל אם תהיה כוונתם במאמר מה נאכל לדרך הראשון אז לא יצו ה' אתם את הברכה:
@745 **וצויתי את ברכתי וגו'**. ברכה זו אינה בצומח שכבר הבטיח ונתנה הארץ פריה שהוא גבול שגבל ה' בכחה, אלא שמבטיח ברכת התבואה ככד קמח הצרפית (מלכים א' י''ז) וכשמן אשת עובדיה (מ''ב ד'), והוא שדקדק לומר **ועשת את התבואה** פירוש הברכה שיצו ה' תעשה ריבוי בתבואה כדי שתספיק לג' שנים הגם שהארץ תוציא צמחה כמדי שנה בשנה, צא ולמד מקב חטים שבעליה (תענית כ''ד.), ועיין מה שפירשתי בפסוק וכי יש לי כל (בראשית ל''ג י''א):
@745 **לשלש השנים**. פשט הכתוב הוא לשנה עצמה שהיא ששית ושנת שביעית ושנה שמינית, על זה הדרך מחודש סיון של שנה ו' עד חודש סיון של ז' ושל ח' הרי ב' שנים ומחודש סיון של ח' עד סיון של תשיעית הרי ג' שנים, והוא מאמר הכתוב **עד השנה התשיעית** ולא עד תחלתה של ט' אלא עד בא תבואתה הרי ג' שנים מיום ליום, והוצרך הכתוב לפרש לבל תחשוב שמקצת שנה חשוב שנה:
@746 **וזרעתם את השנה וגו'**. הוצרך לומר כן, מצד שאמר ועשת את התבואה לג' שנים חש שיאמר האומר אם שנה שמינית בת זריעה היא למה יעשה נס כדי שתהיה תבואת שנה ו' עושה לשמינית, לזה גמר אומר וזרעתם את השנה השמינית, ונתן טעם לברכת תבואת שנה ו' צורכי שנה שמינית שהוא מטעם ואכלתם מן התבואה ישן כדי שתאכלו שנה שמינית תבואה ישן ולא חדש כי הישן משובח לבריות יותר מן החדש (ב''ב צ''א:) כידוע, וכרחם אב על בנים ירחם ה' על עמו:
@749 **כי ימוך אחיך וגו'**. פרשה זו תרמוז ענין גדול והערה ליושבי תבל, כי ימוך על דרך אומרו (קהלת י' י''ח) בעצלתים ימך המקרה, ואמרו ז''ל (תענית ז':) עשיתם לאותו שנאמר בו (תהלים ק''ד) המקרה במים עליותיו מך, כי כשהתחתונים מטין מדרך הטוב מסתלקים ההשפעות ומתמסכן עמוד הקדושה, כי העיקר תלוי בהתחתונים, ואמר **ומכר מאחוזתו** ירצה על המשכן משכן העדות אשר הוא אחוזתו ית' שבו השרה שכינתו ובעונותינו נמכר הבית ביד האומות, וכמאמרם ז''ל (מדרש תהלים ע''ט) בפירוש פסוק מזמור לאסף באו גוים וגו', והודיע הכתוב כי גאולתו היא ביד הצדיק אשר יהיה קרוב לה' על דרך אומרו (לעיל י' ג') בקרובי אקדש הוא יגאל ממכר אחיו, כי האדון ב''ה יקרא לצדיקים אח כביכול דכתיב (תהלים קכ''ב) למען אחי ורעי, והגאולה תהיה בהעיר לבות בני אדם ויאמר להם הטוב לכם כי תשבו חוץ גולים מעל שלחן אביכם ומה יערב לכם החיים בעולם זולת החברה העליונה אשר הייתם סמוכים סביב לשלחן אביכם הוא אלהי עולם ב''ה לעד, וימאיס בעיניו תאוות הנדמים ויעירם בחשק הרוחני גם נרגש לבעל נפש כל חי עד אשר יטיבו מעשיהם, ובזה יגאל ה' ממכרו, ועל זה עתידין ליתן את הדין כל אדוני הארץ גדולי ישראל ומהם יבקש ה' עלבון הבית העלוב:
@750 ואומרו **ואיש כי לא יהיה לו גואל**. על דרך אומרם ז''ל (סנהדרין צ''ג.) אין איש אלא הקדוש ברוך הוא דכתיב (שמות ט''ו ג') ה' איש מלחמה, כשלא יהיה לו גואל כי אין איש שם על לב אין מנהל ואין מחזיק ביד אומה ישראלית להשיבה אל אביה, אל תאמר כי ח''ו אבדה תקוה, אלא והשיגה ידו ומצא כדי גאולתו, אמרו ז''ל (סנהדרין צ''ח) כי היסורין והגלות הם תקון האומה להכשירה, והוא מה שרמז **והשיגה ידו** על דרך אומרו (דברים ב' ט''ו) יד ה' היתה בם שהיא מדת הגבורה החובטת באומה בגלות המר, ובאמצעות זה ישיג למצוא כדי גאולת הבית:
@751 ואומרו **וחשב וגו'**. הנה לצד שהמכר הוא בעונותינו כאומרו (ישעי' נ' א') הן בעונותיכם נמכרתם והעון הוא חוב על האדם, בשעת קריעת השטר צריך לעשות חשבון החוב שעליו ולפרוע הנשאר, והוא אומרו **וחשב את שני ממכרו** השנים שנשאר הבית מכור ויתנכה לפי שיעור השנים מעונות ישראל, והעודף ישיב על דרך אומרם ז''ל (יומא פ''ו:) במשפטי התשובה ותיקוניה תשובת המשקל אם אדם נהנה מהעון יסגף עמו כשיעור מה שנהנה מהחטא ובזה יפרע חובו, וכמו כן יעשה אדון העולם כשיתקרב זמן הגאולה, והוא מאמרם ז''ל (סנהדרין צ''ח) שיהיו חבלי משיח, ובזה **ושב לאחוזתו** פירוש חוזר אל הקדוש ברוך הוא, גם על ישראל על דרך אומרו (דברים ל' ג') ושב ה' את שבותך ואמרו ז''ל (מגילה כ''ט.) ישיב לא נאמר אלא ושב וגו':
@752 **ואומרו ואם לא מצאה ידו די השיב**. פירוש אם יראה האדון כי אין כח בעם לסבול חבלים עוד ורבו חובותיהם למעלה ראש ואפם בהם כח הסבל, **והיה ממכרו עד שנת היובל** שהוא זמן המוגבל לגאולה בעתה, ואז **ויצא ביובל ושב לאחוזתו** כי קץ הגלות ישנו אפילו יהיו ישראל רשעים גמורים ח''ו:
@753 **ואיש כי ימכור**. אחר שאמר ענין מכר הבית חזר הכתוב לתת טעם לדבר איך יהיה הדבר הזה שימכור ה' אחוזתו בית הבחירה, והוא אומרו ואיש זה הקדוש ברוך הוא, **כי ימכור בית מושב** פירוש בית שבו מושב אלהים זה בית המקדש, עיר חומה זו ירושלים דכתיב (תהלים קכ''ה) ירושלים הרים סביב לה, אמר הטעם הוא **והיתה גאולתו** שבאמצעות זה אדרבה נגאל, על דרך אומרם ז''ל (מדרש תהלים ע''ט) בפסוק מזמור לאסף וגו' שהשליך ה' חמתו על עצים ואבנים שזולת זה לא היה נשאר מישראל שריד ופליט ואם אין ישראל אין בית המקדש ולא ירושלים, לזה והיתה גאולתו של עם וגאולת הבית כי יש תקוה ושבו בנים לגבולם:
@759 **וכי ימוך אחיך וגו'**. פרשה זו תעיר האדם על רוח ה' אחינו אשר שכן בתוכנו, ואמר כי ימוך אחיך שהוא רוח החיים אשר נטע בתוכנו לחיותנו, אם ראה האדם כי לא האיר בתורה ולא במצות כי אין עני כי אם מן התורה והמצות, **ומטה ידו** והחשיך אורו והודו, **עמך** פירוש לצד היותו עמך הוא שנתמוטט שזולתך היה אורו מאיר מסוף העולם ועד סופו, ותמצא שיבקש ה' להחזיר לו הרוח כאשר נתנה כאומרו (קהלת י''ב ז') והרוח תשוב וגו' ואמרו ז''ל (שבת קנ''ב:) תנה לו כמן שנתנה לך, ויצו ה' **והחזקת בו** פירוש שיתחזק לשוב בתשובה להשיבו למכונו, כי אין לך דבר המעמיד לרוח החיוני במקום גבוה כתשובה:
@759 **ואמר גר ותושב**. דע כי אמרו יודעי נסתרות לה' (קב הישר פל''ב) כי יש בחינת נפשות שה' מביאם באדם בסוד העיבור לסיבות ידועות, יש שבאים להתגורר עם האדם בעשותו איזה מצוה כדי להשתתף במעשה וזוכה בזה, ויש שבאה ומתישבת לסיבות מופלאות אשר הפליא ה' בתיקון הנפשות, וכנגד שניהם אמר **גר ותושב וחי עמך** כנגד ב' הנפשות הבאים שלא מדעתו כשהוא מתחזק לשוב בתשובה, ויזהר עוד שלא יחשיך אור רוחו והגרים אתו, והוא אומרו **אל תקח מאתו** מת שיש בו ובמה בנשך ובמרבית כאשר אבאר בסמוך, **ויראת מאלהיך** פירוש כי מאורו חלק הנפשות הטהורות השיב לו פקדונו, ומבקש עוד **וחי אחיך עמך** שיחזיר הנפש בתוספות חיות באמצעות עבודת הקודש אשר ציוהו ה', והגם שאמרו תנה לו כמו שנתנה לך, זה צד ההסתפקות, או לפי מה שפירשתי בספרי חפץ ה' (שבת קנ''ב) כי כשיתנה לה' כמו שנתנה לו בזה היא מתעלית ומוסיפה חיים ואור עליון ועיין שם:
@761 ואמר **את כספך וגו'**. כאן פירש מה הוא הנשך והתרבית אשר מחשיכים אורו, **את כספך** הם הדברים שהאדם כוסף בעולם הזה לדברים הנדמים, **לא תתן לו בנשך** כי כשאדם משלים תאות נפשו הבהמית ומטעים רוחו מכסופיו הוא נשוך בזה ומטיל בו ארס החטא, ואמר **ובמרבית לא תתן אכלך** פירוש אפילו אכלך שהוא דבר שהורשית לאכול לא תרבה בו, כי כשאדם הולך אחר גרונו ויטה גבול התאוה שבו למותרות בזה יחשיך אור הנפש כי כשזה קם זה נופל כשמתרבה תאבון המורגש מתמעט תאבון הרוחני, והוא מאמר הכתוב (משלי י''ג כ''ה) צדיק אוכל לשובע נפשו, לא להנאת ההרגש, ואומרו **אני ה'** וגו' פירוש והגם שאני אומר לכם להוציא אתכם מארץ מצרים לתת לכם את ארץ כנען לא לאכול מטובה ולשבוע מפריה הוא התכלית אלא להיות לכם לאלהים הוא עיקר הארץ, ואמרו ז''ל בתורת כהנים וז''ל כל היושב בארץ ישראל מקבל עליו עול מלכות שמים:
@763 **וכי ימוך אחיך וגו'**. פרשה זו תרמוז למה שאמרו ז''ל בספר הזוהר (תיקונים י') כי ה' צוה לשר אדום שהוא ס''מ שלא יתנהג באכזריות עם ישראל, והוא אומרו **כי ימוך אחיך** על דרך אומרו (מלאכי א') הלא אח עשו ליעקב, עמך פירוש נמיכותו ועניותו הוא לצד היותו עמך שנתלוה לדרכיך הרעים, **ונמכר לך** על דרך (ישעי' נ''ב ג') חנם נמכרתם ודרשו בספר הזוהר (ח''ב קכ''ח.) כי בחינת ס''מ תקרא חנם, שגלות החל הזה הוא לאדום זכור ה' לבני אדום, ויצו ה' **לא תעבוד בו עבודת עבד** על דרך אומרו (ירמי' ב' י''ד) העבד ישראל וגו', אלא **כשכיר כתושב יהיה** וגו', לצד שיש בישראל ב' בחינות, המון העם ויושבי בשבת תחכמוני (ש''ב כ''ג), ותמצא שהגם שישראל מעלין מסים וארנוניות אין לומדי התורה בכלל דכתיב (דברים ל''ג ג') והם תוכו לרגליך ואמרו ז''ל (ב''ב ח'.) וכו', וכתיב (עזרא ז') מנדה בלו והלך לא שליט וגו', כנגד ההמון עם אמר כשכיר שהם מכורים בעד עונותיהם, וכנגד הצדיקים אמר כתושב שאינם אלא יושבים בין האומות בגלות אבל אין עליהם משא מלך:
@763 **ואומרו** עד שנת היובל הוא גבול הגאולה כידוע יעבוד עמך, ומודיע ה' כי סוף סוף יצא מעמו דכתיב **ויצא מעמך**, **הוא ובניו** פירוש הניצוצים המתבררים באמצעות היותם עמו והוא סוד הגלות, שאם לא כן למה לא ייסרם ה' בשבט מוסר שם בארצם ובנחלתם אלא אחד מהטעמים הוא כדי שיבררו הניצוצות של הקדושה מבין הארצות כי כל מקום ומקום שימצאון שם ישראל באמצעות היסורין והתורה והמצות הניצוצות מתבררים מעצמם, והוא סוד אומרו (קהלת ח') עת אשר שלטה האדם באדם לרע לו. ואם תאמר אם כן אם לא היו ישראל חוטאים וגולים מי היה מברר המתבררים עתה בתפוצת ישראל, דע כי אם לא היו ישראל חוטאים היה להם כח לברר ניצוצות הקדושות במקום שהם מכל המקומות אשר באו שם, מה שאין כן אחר חטאם דחלש כחם ולואי שתשיג ידם במקום עצמו אשר שם הניצוצות, ואמר **ושב אל משפחתו** כי בבא הגואל יטע ה' בתוכנו אורו יתברך אשר שם הוא משפחת עם בני ישראל, גם יקומו שוכני עפר וישובו כל אחד אל אחוזת אבותיו הוא אור עולם בית המקדש כוננו ידיו יתברך לא תרדה בו בפרך ויראת מאלהיך, ומצד דבר זה יתחייב מיתה ס''מ לעתיד לבא כמאמרם ז''ל (סוכה נ''ב.) שהרי הוא מותרה ועבר מצות ה':
@779 **כי לי בני ישראל עבדים וגו'**. צל''ד למה כפל לומר עבדים עבדי הם, ונראה כי יכוין לומר על זה הדרך כי לי בני ישראל עבדים מעיקרם קדושים מבטן ומהריון בשורש נפשותם הגם שלא היה מוציאם ממצרים, וכל זה למה שממנו ואליו, אבל מה שמהם לחייבם להחזיק את עצמן לעבדים עבדי הם אשר הוצאתי אותם מארץ מצרים שהוא טעם מוכרת להם ומחייב להתייחס להם שם עבדות:
@779 **אני ה' אלהיכם**. טעם שהתחיל הכתוב לדבר דרך נסתר כי לי וגו' עבדי הם וגמר אומר לנוכח אני ה' אלהיכם, אולי כי לצד שמצוה לקונה עבד עברי שישלחנו בשנת היובל, לזה נתן לו הטעם לצד שהוא עבד ה' כאומרו עבדי הם, ולצד שיאמר הקונה כי טעם זה יוצדק לגבי העבד שלא יפקיע עבודתו וימכור עצמו לצמיתות אבל הקונה אין עליו חיוב, ומה גם אם הוא מוכר עצמו לגר תושב או לעקר הוא העובר על מצות ה', לזה גמר אומר **אני ה' אלהיכם** מדבר עם הקונה שעמו התחיל לדבר בתחלת הפרשה כי תקנה ועם אותם שצוה אותם לנוכח לא ירדנו בפרך לעיניך, כי דבר מלך שלטון עליהם לקיים כל הכתוב:
@781 **את שבתותי תשמורו וגו'**. צריך לדעת למה חזר הכתוב וצוה כאן על השבת, ונראה שנתכוין להסמיך מצות שבת למצוה שלפניה דכתיב לא תעשו לכם אלילים וגו' לומר כשם שע''ז שקולה ככל התורה גם מצות שבת שקולה ככל התורה כולה, גם עוד יכוין לומר על השמיטות שהם נקראים שבתות דכתיב (לעיל כ''ה ב') שבת לה' שמזהיר עליהם לשומרם, וסמך לאזהרה זו אומרו **ומקדשי תיראו** על דרך אומרם ז''ל (אבות פ''ה) לא נחרב הבית אלא בשביל שלא שמרו מצות שביעית, וכן אמר הכתוב (לקמן כ''ו ל''ד) אז תרצה הארץ את שבתותיה, והוא עצמו אומרו **את שבתותי תשמרו ומקדשי תיראו** שלא תסבבו להחריבו כשלא תקיימו מצות השבתות, ויש לך לדעת כי הגם שה' משליך חמתו על ביתו ונחלתו לחללה לכפרת עון כאומרם ז''ל (מדרש תהלים ע''ט) בפסוק מזמור לאסף עם כל זה על הכל יביא ה' במשפט כל המסבב בחטאו את הדבר הרע הזה ביום המשפט הנורא כשיעמוד בעל הבית המקודש ויתבע האיש המגרש, ומה גם למה שאמר הנביא (הושע י''א) לא אבא בעיר ודרשו ז''ל (זוהר ח''א א':) נשבע הקדוש ברוך הוא כו' אנה יוליך את חרפתו ומה מענה בלשונו ומה גמול יעריכנו, והוא מה שרמז הכתוכ כאן באומרו ומקדשי תיראו כי עונשו גדול, וישער מזה עונש השמיטה, לשומרה:
@781 **חסלת פרשת בהר סיני**
@782 **אם בחקתי תלכו וגו'**. בתורת כהנים אמרו ז''ל יכול אלו המצות כשהוא אומר ואת מצותי וגו' הרי המצות אמורות מה אני מקיים אם בחקתי להיות עמלים בתורה ע''כ, וטעם שקרא הכתוב עמל התורה חוקה, לצד שיש בה מצוה אפילו ללמוד דברים שלמדם פעמים וג' והם נטועים אצלו, כי חפץ ה' בעסק התורה חוקה חקק ותמצא שאמרו ז''ל (קהלת רבה פ''ג) כי לטעם שילמוד האדם תורה בחשק תמיד גזרה חכמתו יתברך שיהיה האדם לומד ושוכח, וטעם אומרו **חקתי** לשון רבים, ירמוז לב' תורות תורה שבכתב ותורה שבעל פה, ומסורת התיבה לשון יחיד שאין וא''ו בין קו''ף לתי''ו, לומר כי תורה שבעל פה היא כלולה בתורה שבכתב ושם בנינה. עוד רמז באומרו **חקתי** לשון רבים על דרך אומרו (יהושע א' ח') והגית בו יומם ולילה, שצריך לקבוע עתים בתורה ביום ובלילה, והמסורת לשון יחיד כי ב' העתים הם ביום אחד:
@782 **עוד** ירצה כי צריך האדם בקיום מצות התורה ב' דברים, הא' ללמוד לעצמו, והב' ללמד לאחרים דכתיב (דברים י''א) ולמדתם אותם את בניכם ושננתם וגו', לזה אמר **חקתי** לשון רבים ללמוד וללמד, לשמור ולעשות כאומרו ואת מצותי תשמרו ועשיתם אותם:
@782 **וטעם** אומרו לשון הליכה לומר שצריך לעסוק בתורה אפילו בהליכתו על דרך אומרו (דברים ו') ובלכתך בדרך באהבתה ישגה תמיד וגו':
@782 **ב)** עוד ירצה על דרך מה שאמרו ז''ל (ויק''ר פל''ה) בפסוק חשבתי דרכי וגו' שהיה דוד חושב לעשות ענינים ורגליו מוליכים אותו מעצמם אל בית המדרש לרוב החפץ והרצון והרגילות בדבר, והוא אומרו **אם בחקתי תלכו** פירוש הליכתכם מעצמה תהיה אחריה כמאמר דוד לרוב החשק והרגילות:
@782 **ג)** עוד ירצה על פי מאמרם ז''ל (זוהר ח''ג ר''ב.) כי התורה יש בה ד' דרכים והם פשט רמז דרוש סוד ומאלו נפרדו ע' פנים וכל אופן לכמה אורחין ושבילין ונתיבות, והוא מה שאמר **חקתי** לשון רבים, **תלכו** פירוש בכל אורחין ושבילין ילך בהם בפירוש הכתובים ולא יאמר שאין בתורה אלא פשט המובן לכל:
@782 **ד)** עוד ירצה באומרו **תלכו** על דרך אומרו (משלי ג') בכל דרכיך דעהו וגו', וכתב רמב''ם בפרק ג' מהלכות יסודי התורה (הלכות דעות) וז''ל ישים אל לבו כדי שיהיה גופו שלם וחזק כדי שתהיה וכו' לדעת את ה', שאי אפשר שיבין ויסתכל בחכמות וכו', נמצא המהלך בדרך זה כל ימיו עובד ה' ע''כ, והוא מאמר הכתוב כאן **אם בחקתי תלכו** בשביל עסק התורה תלכו בכל דרככם באכילה וכו' במשתה בדיבור וכו' בכל מעשה המסובב מהטבעיות:
@782 **ה)** עוד יתבאר על דרך אומרם ז''ל (סנהדרין ל''ד) שהרשות נתונה ללומדי תורה לפרש בה ולדרוש בכמה אורחין ושבילין ותלמיד ותיק יחדש בדרשת הכתובים כאשר יוכל הכתוב שאת ככל אשר תשיג ידו בתורתו, ויצו ה' כאן באומרו **אם בחקתי** שהיא התורה **תלכו** בפרדסה תנאי הוא הדבר ואת מצותי וגו', פירוש שלא יהיה מגלה פנים בתורה שלא כהלכה, שלא לטהר את הטמא ועשיתם אותם שלא לטמא את הטהור, והוא מאמרם ז''ל (אבות פ''ג) המגלה פנים בתורה שלא כהלכה אין לו חלק לעולם הבא:
@782 **ו)** עוד יתבאר על דרך אומרם (אבות פ''ב) ולא עם הארץ חסיד פירוש שאסור לעם הארץ להתנהג בחסידות שיעשה חומרות וגדרים כמנהג החסידים, כי לפעמים יעשה חומרא בדבר שהוא אדרבה עבריין, כי ימצא חסיד שירצה לגדור עצמו לקיים מצות עונה בימים המקודשים ותהיה בעיניו מצוה גדולה לשמש מטתו בליל כיפור, כמו ששמענו שהיה מעשה כן וכדומה, לזה ציוו חז''ל שאין לעם הארץ להתנהג במדת חסידות, והוא מאמר ה' כאן **אם בחקתי תלכו** שהוא עסק התורה, אז **ואת מצותי תשמרו** פירוש תעשו לכם משמרת כדי לקיימם גדרים ושמירות ולא זולת זה:
@782 **ז)** עוד ירצה על דרך אומרם ז''ל (אבות פ''ד) הוי גולה למקום תורה, שצריך לכתת רגליו ממקום למקום ללמוד תורה, וצא ולמד דבריהם ז''ל בגמרא (חגיגה ה':) כי כולן היו גולין ללמוד ויש שהיה הולך ששה חדשים וחוזר כמו כן לעסוק ביום א', והוא אומרו **אם בחקתי** שהיא עסק התורה צריכים שתלכו ממקומכם אחריה, גם כדי שתהיו פנויים אין נכון ללמוד והוא בביתו כי יטרדוהו בצורכי הבית, לכן יעזוב איש את אביו ואת אמו ויסע ממקומו ללכת אחריה:
@782 **ואומרו** ואת מצותי תשמרו. יתבאר על דרך מה שאמרו במסכת שבת (ל''א:) מכריז ר' ינאי חבל על מאן דלית ליה דרתא ותרעא לדרתא עביד, שעיקר עסק התורה צריך שיהיה לשמור ולעשות, והוא אומרו **אם בחקתי** וגו' שהוא עסק התורה תנאי הוא הדבר ואת מצותי תשמרו ועשיתם אותם, ואמר **ואת מצותי** יתבאר על דרך אומרם בגמרא (ברכות י''ז:) הלומד שלא לשמה נוח לו שלא נברא, והקשו בתוספות עם אותה שאמרו לעולם יעסוק אדם בתורה אפילו שלא לשמה שמתוך שלא לשמה בא לשמה ותרצו כי הם ב' אופנים שלא לשמה, א' לקנטר, וא' להתכבד, לקנטר נוח לו שלא נברא, להתכבד יעסוק שמתוך וכו', והוא מאמר ה' **אם בחקתי תלכו** ותנאי הוא הדבר ואת מצותי שבה ב' מצות הצריכין בלימודה שלא ילמדו לא לקנטר ולא להתכבד, אז **תשמרו ועשיתם אותם** מבטיח הכתוב שהגם שתבא עבירה לידו יהיה ניצול ממנה, וכאומרם (סוטה כ''א.) תורה מגינא ומצלא מיצר הרע, וכמו שאמרו במסכת עבודה זרה (י''ז.) באותה מעשה של ר' חנינא ור' יונתן שחלפו אפיתחא דזונות וכו' דכתיב (משלי ב') מזימה תשמור עליך וגו', ודקדק לומר **ועשיתם** על דרך אומרם ז''ל (קידושין ל''ט:) ישב אדם ולא עבר עבירה נותנין לו שכר כעושה מצוה, והעמידוה כשבאה עבירה לידו וניצול ממנה, הגם שאינה אלא שמירה מעלה עליו הכתוב כאילו עשה מעשה מצות:
@782 **והגם** שדרש רבא (פסחים נ':) בפסוק כי גדול עד שמים חסדך זה הלומד שלא לשמה אלא להתכבד, הטעם לא שיש רצון הבורא בלימוד זה אלא לתכלית היוצא ממנו שיבא ללמוד לשמה, ותורה זו אין בסגולתה להציל מיצר הרע בבא עבירה לידו, ובזה יש לתרץ מה שהקשו שם בסוטה לרבי יוסף שאמר תורה בין בעידנא דעסיק בה בין בעידנא דלא עסיק בה מגנא ומצלא אלא מעתה דואג ואחיתופל מי לא עסקו בתורה אמאי לא אגינא עלייהו ע''כ, לדברינו אין קושיא שהם היו לומדים מתחלתם שלא לשמה ואין כח בתורה כזו להגין עליו מיצר הרע:
@782 **ח)** או יאמר על זה הדרך להיות שיש שני סברות (ע''ז י''ז) אחת של ר' חנינא ואחת של ר' יונתן א' אמר נחלף אפתחא דע''ז דנכים יצריה, וא' אמר נחלף אפתחא דזונות כי היכי דנכפייה ליצרן ונקבל אגרא, ובא הכתוב כאן והכריע עם האומר נחלף אפתחא דזונות, והוא אומרו **אם בחקתי תל**.
@782 **כו** פירוש יכולין אתם לילך ואני מבטיחכם שאת מצותי תשמורו שיהיו כופין יצרם, ואם תאמר ולמה יכניס עצמו בספק זה, לזה אמר **ועשיתם אותם** כדי שתטלו שכר כעושה מצוה כיון שבא לידכם העון, והוא מאמרם שם ונכפייה ליצרין כי היכי דנקבל אגרא:
@782 **ט)** או ירצה על דרך אומרם ז''ל במשנת חסידים (אבות פ''ו) התורה נקנית במ''ח דברים, כי לא כל הרוצה לקנות תורה ישיג קניינה אלא באמצעות המ''ח דברים, והוא מה שאמר כאן **אם בחקתי תלכו** אם אתם חפצים להשיג התורה תנאי הוא הדבר ואת מצותי תשמורו ועשיתם אותם שהם אותם המ''ח דברים, כי יש בהם בחי' המניעות וכנגדם אמר תשמרו, ויש בהם בחינת המעשה וכנגדם אמר ועשיתם וגו':
@782 **י)** עוד ירצה להודיע מעלת עסק התורה שיש בו מה שאין בעסק המצות, כי עסק המצות יכול להיות שיהיה אדם פועל ועושה ויגרום החטא וימיר כבודו לבסוף ולא תזכרנה צדקתו ביום פשעו, אבל מצות עסק התורה מבטיחו כי כל העוסק בתורה צדקתו עומדת לעד, וילך עמו צדקו על דרך אומרם (סוטה כ''א.) כי עבירה מכבה מצוה ואין עבירה מכבה תורה לבטל זכותה של תורה ויזכה ללכת בה בלכתו לעולם העליון, ועיין מה שפירשתי בפרשת אחרי מות (י''ח ד') את חקתי תשמרו ללכת בהם:
@782 **יא)** עוד ירצה על דרך אומרם ז''ל (שבת סג.) בפסוק אורך ימים בימינה וגו' שהמיימינים בה שכרם לעולם העליון, והמשמאילים בה שכרם בעולם הזה, הוא מה שאמר כאן **אם בחקתי** שהיא עסק התורה, תהיה כוונתכם בעסק זה לא לתכלית עולם הזה והוא כת המשמאילין בה, אלא תלכו תהיה כוונתכם לתשלומין כשתלכו לעולם העליון, והוא כת המיימינים:
@782 **יב)** עוד יתבאר על פי דבריהם ז''ל במשנת חסידים (אבות פ''ג) כל שחכמתו מרובה ממעשיו וכו' וכל שמעשיו מרובים וכו', והוא מה שרמז הכתוב באומרו **אם בחקתי תלכו** שהוא עסק התורה ולפי ערך זה תהיה שמירת המצות וקיומן כדי שלא תהיה חכמתו מרובה ממעשיו, והוא אומרו סמוך למצות עסק התורה ואת מצותי תשמרו ועשיתם אותם:
@782 **יג)** עוד יתבאר על דרך אומרם ז''ל (פאה פ''א) אלו דברים וכו' ותלמוד תורה כנגד כולם, והוא אומרו **אם בחקתי תלכו** שהוא עסק התורה מעלה אני עליכם גם כן ששמרתם מצותי ועשיתם אותם:
@782 **יד)** או ירצה על דרך אומרו (לעיל ז' ל''ז) זאת התורה לעולה ולמנחה, ודרשו ז''ל (מנחות ק''י.) אדם עוסק בפרשת עולה מעלה עליו כאלו הקריב עולה וכו', על דרך אומרו (הושע י''ד) ונשלמה פרים שפתינו, ולא זה בלבד אלא כל מצוה ומצוה שאינה בפרק השג יד כשאדם לומד מצותה בתורה כאלו עשאה, והוא מאמר הכתוב **אם בחקתי תלכו ואת מצותי** וגו' אותם שאין מציאות לעשותם תשמרו פירוש תהיו מחכים אותם מתי יבואו לידכם לעשותם, מעלה אני עליכם כאלו עשיתם אותם גם כן, והוא אומרו **ועשיתם אותם** לומר לא שכר מחשבה לבד אני נותן, והגם שכתבנו בסמוך ותלמוד תורה כנגד כולם, יש מצות שמבטלין תלמוד תורה בשבילן כגון מעשה הקרבנות וכדומה, ולבחינה זו צריך שילמוד מצותה ויקו לעשותם:
@782 **טו)** או יאמר על זה הדרך שלא יאמר אדם כיון שתלמוד תורה ימלא מקום המצות אם כן הרי הוא פטור ממעשה המצות אשר תזדמן לפניו, תלמוד לומר **אם בחקתי תלכו** שהוא עסק התורה, **ואת מצותי** שהם לא תעשה תשמרו, לא מפני זה תהיו פטורין מקיום מצות אלא ועשיתם אותם, ומה שפירשתי שהוא שקול הוא פרט למזדמן שאינו יכול להתקיים על ידי הזולת:
@782 **טז)** עוד ירצה על דרך אומרם ז''ל (ברכות י''ד.) שאסור לאדם לשום לדרך פעמיו עד שיקדים דברי תורה דכתיב (תהלים פ''ה) צדק לפניו יהלך וישם לדרך וגו', וצא ולמד מה שאמרו בזוהר (ח''א ס''ט) על ההולכים בדרך ואין ביניהם דברי תורה שמתחייבים בנפשם, והוא מאמר ה' **אם בחקתי תלכו** פירוש כשיש לימוד תורה, תלכו אז תלך לבטח, כי כשיש עסק התורה כוחותיה מלוין את האדם:
@782 **יז)** עוד נתכוין לומר מה שאמרו ז''ל (שבת ס''ג.) חשב אדם לעשות מצוה ונאנס ולא עשאה מעלה עליו כאלו עשאה, והוא מאמרו **אם בחקתי תלכו** לשון עתיד פירוש תחשבו ללכת וגו', תשמרו גם כן תחשבו לעשות שמירה ועשיתם אותם פירוש מעלה אני עליכם כאלו כבר עשיתם אותם:
@782 **יח)** עוד ירצה על דרך אומרם ז''ל (סוכה מ''ה:) כי ג' הדרגות בבני עליה הא' המסתכלים באספקלריא דלא נהרא, ב' המסתכלים באספקלריא דנהרא, הג' דעיילי בלא בר, ופירשתי על דרך זה פסוק (איוב ג') קטון וגדול שם הוא ועבד חפשי מאדוניו, קטון הוא המסתכל באספקלריא דלא נהרא בסוד (בראשית א' ט''ז) המאור הקטן, גדול הוא המסתכל באספקלריא דנהרא בסוד (שם) המאור הגדול, ועבד חפשי מאדוניו זה שעולה בלא רשות, שה' אדוניו נתן לו חפשיות ללכת בכל אשר יחפוץ, ואין אני יודע במה יושג הכבוד הגדול הזה, לזה בא מאמרו יתברך ואמר **אם בחקתי** פירוש באמצעות השתדלות התורה כמצטרך בזה אין אתם צריכין לרשיון להוליך אתכם אלא אתם מעצמכם תלכו בלא בר:
@782 **יט)** עוד ירצה על דרך אומרם ז''ל (סנהדרין ק''ב.) שאמר הקדוש ברוך הוא לירבעם חזור בך ואני ואתה ובן ישי נטייל בגן עדן וכו' ע''כ, ואמרו המקובלים כי טיול זה היא הדרגת שעשוע שאין למעלה ממנו, אשרי אנוש יזכה לו, ויאמר אדם במה יזכה ילוד אשה להדרגה זו, לזה בא המאמר כאן ואמר אם בחקתי באמצעות עסק התורה תלכו היא הליכה נעלמה מעיני כל חי שהוא הטיול, באמצעות התורה תטיילו במקומות הנעלמים:
@782 **כ)** עוד ירצה על דרך אומרם ז''ל (ילקוט תהלים תתל''א) כי כשברא ה' אדם הראשון בעולם הזה לא בראו לשבת בעולם הזה לעולמי עד כשלא יחטא, שאם כן אדרבה ירידה היא לו ושפלות, כי תכלית המקווה היא בעולם העליון ששמה יקצור אשר זרע, אלא היתה הכוונה כי עלה יעלה לשמים ולאוצרות החיים בעת אשר יחפוץ, ויהיה כמי שדר בבית ועליה על גבה, וכשירצה לעלות ולהשתעשע יעלה, כמו שמצינו (מ''ב ב') שעלה אליהו בסערה השמימה, ועל ידי החטא הוצרך להפשיט עורו מעליו ויניח הגוף בעולם הזה, והודיע הכתוב כאן כי בהתעצמות האדם בעסק התורה יכול להשיג באמצעותה שלא ירגיש במות אלא כאדם ההולך ממקום למקום ותמצא (זוהר ח''ב קע''ד.) שהצדיקים אינם מרגישים בצער הפרידה על דרך אומרו (קהלת ה') מתוקה שנת העובד, כי מי שהוא עובד ה' שינתו שהיא המיתה מתוקה ועריבה עליו, ואם יתעצם יותר הנה לך אליהו שעל ידי התעצמות תורתו לא מת:
@782 **כא)** עוד ירצה על דרך מה שאמרו במשנת חסידים (אבות פ''ד) ועל כרחך אתה מת ועל כרחך אתה חי, שאין אדם מת ברצונו אם יחפוץ למות, ואמרו במסכת נדה דף ל''ו (ע''ב) וז''ל כי קא נח נפשיה דרב א''ל לרב אסי זיל צנעיה ואי לא ציית גרייה הוא סבר גדייה א''ל בתר דנח נפשיה דרב א''ל הדר בך דהדר ביה רב וכו' גדייה וכו' נח נפשיה דרב אסי אזל שילא א''ל לדביתהו צבית לי זוודתא וכו' צביתה ליה זוודתא ונח נפשיה דשילא ע''כ, הרי שבערך בעלי התורה יכולין ללכת לעולם העליון כשהם חפצים ורוצים ללכת הגם שעדיין לא הגיע זמנם ולא שלח המלך אחריהם, והוא מאמר **אם בחקתי** בסיבת חקתי שאתם עמלים בהם אתם ברשות עצמיכם אם תרצו ללכת תלכו:
@782 **כב)** עוד נתכוון ה' להודיע הפלגת תועלת התורה, כי העוסק בתורה יתאו תמיד ללכת לעולם העליון, כי יראה רב ערך תועלת המסובב ממנה וכי הוא למעלה וישאף הלוך לפני ה' בארצות החיים, ולדרך זה פירשתי אומרו (תהלים מ''ט) אך אלהים יפדה נפשי מיד שאול כי יקחני סלה פירוש כשיהיה האדם בטוח שלא יראה שאול ויתעדן בעדן ה' בזה ישאף לקחתו סלה, וכאלו אמר סלה כי יקחני, ועין מדרש רבות (ילקוט פ' מסעי) במאמר אהרן למשה כשעלה להר ההר למות שם שאמר לו שאלו כן היה יודע היה מקוה שילך קודם, והוא מאמר הכתוב **אם בחקתי** פירוש שתעמלו בתורה באמצעות זה אתם מעצמכם תחפצו ללכת לטעום טעם שאין ערוך אליו:
@782 **כג)** עוד ירצה על דרך אומרם בספר הזוהר (ח''ג צ''א:) בפירוש פסוק שור או כשב וגו' כי מין הבהמי אינו משתנה מגדר שבו נולד מה שאין כן בני אדם ישתנו לצד מעשיהם והולכים מגדר לגדר עליון, כאומרם (שם ח''ב צ''ד:) זכה יתיר יהבין ליה וכו' זכה יתיר וכו' הולך וגדל, ואין אני יודע מי הוא הסובב מהלכים אלו, ובא הכתוב כאן וגילה ואמר **אם בחקתי** באמצעות עסק התורה תהיה ההשגה הלז הולך ואור ממדרגה שפלה למדרגה עליונה ומן העליונה לשלמעלה ממנה:
@782 **כד)** עוד יתבאר על דרך אומרם ז''ל (זוהר ח''א קע''ה:) בפסוק (משלי ו') בהתהלכך תנחה אותך כי הדרכים אשר תעלה בהם הנשמה בצאתה מן העולם הם חשך וצלמות המלאים גערת ה' ומי שיש בידו תורה היא מאירה לפניו כאומרו (תהלים קי''ט) נר לרגלי דבריך ואור לנתיבתי, והוא אומרו **אם בחקתי תלכו** פירוש בתורה תלכו כי היא אור לנתיבתכם אבל זולתה עליהם נאמר (משלי ד') דרך רשעים כאפילה וגו', גם נקראה תורה כי היא תוריהו דרך אשר ילך בה:
@782 **כה)** עוד יתבאר הכתוב חוץ מדרכם ז''ל על זה הדרך **אם בחקתי** הכתוב מדבר במצוה שנקרא חקה שהיא מצות תפילין שנאמר (שמות י''ג י') ושמרת את החקה וגו', ואמר תלכו על דרך אומרם ז''ל מנהג הראשונים מניחין תפילין בזרועם ובראשם כל היום הולך מביתו לבית המדרש תפילין בראשו וכו' מבית המדרש לביתו תפילין וכו', ואמרו (סוכה כ''ח.) על רבי יוחנן בן זכאי ועל רבי שלא הלכו ד' אמות בלא תפילין, והוא מאמר ה' בחקתי תלכו, ואומרו **ואת מצותי תשמרו** הן מצות השייכים ללבישתם שצריכין גוף נקי, ולמ''ד (שבת מ''ט.) שלא יפיח בהם, ולמ''ד שלא ישן בהם, ושלא יסיח דעתו מהם, שזולת זה אסור להניחם, ואומרו **ועשיתם אותם** כאלו אמר ועשיתם אתם שבזה אתם מתקנים עצמיכם להשרות שכינתו יתברך עליכם, כאומרו (דברים כ''ח י') וראו כל עמי הארץ כי שם ה' נקרא עליך וגו' ואמרו ז''ל (ברכות ו'.) כו':
@782 **כו)** עוד יתבאר על דרך אומרם (ב''ר פמ''ד) בפסוק הבט נא השמימה, שהעלה ה' לאברהם ודרך על המזלות, והוא אומרו **אם בחקתי תלכו** פי' חקותי על דרך אומרו (ירמי' ל''ג) חקות שמים וגו', אם בהם תלכו כמו (בראשית י''ג י''ז) קום התהלך בארץ, תנאי הוא הדבר ואת מצותי תשמרו, כי באמצעות קיום המצות הוא שולט ודורך על המזלות, והן הנה שבהם זכה אברהם לבחינה זו, ואומרו **ועשיתם אותם**, צדק יקראהו לרגלו (ישעי' מ''א) ואמרו ז''ל (שבת קנ''ו.) שאמר לו הקדוש ברוך הוא מאי דעתך דקאי צדק וכו' ע''כ, הרי שמעריך המזלות בסדר הנאות לו ויוליך מזל ממקום למקום, והוא אומרו **ועשיתם אותם** פירוש לחקתי תתקנו אותם בסדר הנאות לכם, והוא מאמרם ז''ל (שם) אין מזל לישראל פירוש הם שולטים בו. או יאמר ועשיתם אותם על דרך אומרו (ישעי' ס''ו) כי כאשר השמים החדשים וגו' אשר אני עושה עשיתי לא נאמר אלא עושה מלמד שעל ידי עסק התורה והמצות נבראים שמים חדשים (זוהד ח''א ה'.), והוא או **מרו ועשיתם אותם**:
@782 **כז)** עוד יתבאר על דרך מה שאמרו במסכת שבת דף קנ''ו מאן דאתיליד בנוגה יהי זנאי, עוד שם אמרו כלדאי לאימיה של רב נחמן בר יצחק שבנה יהיה גנב וכו' יע''ש, הרי שהמזל יפעיל באדם פועל עשות הרע, וחש ה' כי יאמר אדם כי כשיש המזל מגיד על רשע הנולד בו אין בידו לתקן ואנוס הוא ופטור מהעונש, לזה אמר **אם בחקתי** שהם המזלות תלכו פירוש יסובבו אתכם הלוך בדרך לא טוב אינכם פטורים בטענה זו, אלא **ואת מצותי תשמרו** על כל פנים אתם חייבים, ויש תיקון למזל, וכמעשה שעשתה לו אמו של רב נחמן, והוא אומרו ועשיתם אותם:
@782 **כח)** או יאמר על דרך אומרם במסכת שבת (שם) האי מאן דאתיליד במזל מאדים אושיד דמא אמר רבי אשי או אומנא או גנבא או טבחא או מוהלא ע''כ, והוא אומרו **אם בחקותי תלכו** שהם חקות השמים שהם המזלות, ואת מצותי תשמרו שהם שחיטה מילה בזה אתם עושים מה שמראה במזלות בדבר מצוה, והוא אומרו **ועשיתם אותם**:
@782 **כט)** עוד יתבאר על דרך אומרם ז''ל (ספרי פ' האזינו) שצריך האדם ללמוד מוסר מחקות השמים שאין משנים את תפקידם וששים ושמחים לעשות רצון הבורא, והוא אומרו **אם** בדרך חקתי שהם חקות שמים וארץ המתמידים לעשות רצון קונם בשמחה בלא שינוי **תלכו**, בזה גם אתם **מצותי תשמרו** שלא תעברו עליהם ותעשו את שישנם בעשה, כי תאמרו ומה אלו שאין להם שכר ועונש כן, אנו על אחת כמה וכמה:
@782 **ל)** עוד ירצה **אם בחקתי** על דרך אומרם (אבות ג') אם אין קמח אין תורה וכו' ופרשתיהו במקומו שירצה לומר אם אין קמח אם אתה רואה שעצר ה' (השמים) ואין קמח הטעם הוא משום אין תורה, כאומרו (דברים ל''ב ב') יערוף כמטר לקחי פירוש כשיעור המוכן הבא מן הגשמים יהיה לקחי, וכשאין לקח יעצור ה' השמים, ואומרם אם אין תורה אין קמח פירוש כשאין תורה בודאי שלא יהיה קמח כי יעצור ה' שמיו, והוא אומרו **אם בחקתי** פירוש בשיעור חקתי שהם חק המזונות, **תלכו** פירוש אם אתם רוצים לתת לכם חקכם שהם המזונות צריכין אתם כמו כן לקיים המצות, והוא אומרו **ואת מצותי תשמרו** על דרך אומרו יערוף כמטר לקחי כשיעור המטר שהוא המזון צריך שתהיה העבודה, ואומרו **ועשיתם אותם** פירוש יעשו כדי שיתמיד ה' המעשה לתת חקם:
@782 **לא)** עוד ירצה על דרך אומרו (תהלים ע''ב) ייראוך עם שמש ואמרו ז''ל (ברכות כ''ט:) כי כל הנבראים זמן עבודתם הוא בזמן שהשמש עולה בבקר זמן תפלת שחרית, ובזמן שהשמש יורדת וכו', והוא אומרו **אם בחקתי תלכו** על דרך אומרו (תהלים נ''ה) בבית אלהים נהלך ברגש, ואומרו **ואת מצותי תשמרו** ירמוז לאומרם ז''ל (ברכות ל''ב:) חסידים הראשונים היו שוהים שעה אחת וכו' ואחר תפלה שעה וכו', וכנגדן אמר ואת מצותי וגו', ואומרו **ועשיתם אותם** פירוש בזה יתקנו המאורות, כי על ידי מעשה התחתונים כשהולכין בדרך לא טוב המאורות לוקין (סוכה כ''ט.):
@782 **לב)** עוד יש לפרש הכתוב בקרבנות שמצינו שנקראו חקה דכתיב בהם (לעיל ו' י''א) חק עולם וגו', וכתיב (לעיל ז' ל''ו) חקת עולם וגו' ואמר **אם בחקתי תלכו** להביא קרבנותיכם תנאי הוא הדבר **ואת מצותי תשמרו** על דרך אומרם במסכת סוכה (כ''ט.) אמר ר''י אמר רשב''י גזול דומיא דפסח וכו' אף גזול לית ליה תקנתא בין לפני יאוש בין לאחר יאוש וכו' לאחר יאוש משום מצוה הבאה בעבירה, והוא מאמר ה' כאן **ואת מצותי תשמרו** שלא יביאו לא גזול לפני יאוש ולא גזול שלאחר יאוש, ומסורת התיבה אחת יורה לצד שב' המצות הם ענין אחד של גזל, ואומרו **ועשיתם אותם** יתבאר על דרך אומרם שם בפרק לולב הגזול וז''ל אמר רבי יוחנן מאי דכתיב אני ה' אוהב משפט שונא גזל בעולה, משל למלך שעבר על בית המכם אמר לעבדיו תנו מכס וכו' אמר להם ממני ילמדו עוברי דרכים שלא להבריח מן המכם אף הקדוש ברוך הוא שונא גזל בעולה כדי שילמדו כו', ואמרו ז''ל (קידושין ל''ט:) כי מי שבאה עבירה לידו וניצל הימנה נותנין לו שכר כעושה מצוה, והוא אומרו טעם למצוה האמורה שלא יביאו מן הגזל ועשיתם אותם פירוש כדי שילמדו עצמן גם כן לברוח מן הגזל, וזה יקרא מעשה הגם שאינו אלא הרחקת הרשע כיון שהוא בשעת מעשה כמדייק ממאמר לברוח וכו':
@782 **לג)** עוד יתבאר הפסוק על כללות המצות על זה הדרך לצד שיחשוב אדם כי עיקר המצות ותועליותם אינו אלא למי שיודע עקרן וטעמן אבל עשית מצוה בלא ידיעת טעם הרי הוא עושה מעשה שאין בו ממש כגוף בלא נשמה ותמצא שכן כתבו בשם הרב האר''י ז''ל (ליקוטי תורה פ' עקב) כי מעשה בלא כונת הדבר הוא ככלי ריק שהעיקר הוא המחשבה, ולזה בא מאמר ה' כאן **אם בחקתי תלכו** פירוש אם האדם יעשה המצוה בכונה זו לצד אשר חקק ה' ב''ה תועיל להם כוונה זו כאלו קיימו המצות כמו שנתכוון ה' עשות, והוא אומרו **ואת מצותי תשמרו** בכינוי אל המצוה שהוא בכל כוונותיהם וסודותיהם, ולצד שיאמר אדם אם כן כיון שהקדוש ברוך הוא יקבל דבר זה לצד הרצון שבאדם הגם שלא נתכוון אם כן גם כן לא יעשה דבר ויתרצה בדעתו עשות ויועיל הרצון גם בהעדר המעשה, תלמוד לומר ועשיתם אותם תנאי הוא הדבר שיעשה מה שיש בידו וה' יגמור בעדו:
@782 **לד)** עוד יתבאר על דרך מה שפסק מרן בהלכות תפילין סימן ל''ב סי''ח וז''ל אם נדבקה אות לאות וכו' פסול, ובהלכות ספר תורה כתב הרא''ש דבקות פוסל בספר תורה ואם גרר הדבקות וכו' כשר, נמצינו אומרים שיש היתר לחקוק דבק שבין אות לאות בספר תורה ולא בתפילין, והוא מה שרמז הכתוב כאן **אם בחקתי** פירוש חקיקות האותיות **תלכו** כמשפטיהן לחוק אות' לא לכל תמחקו אלא **ואת מצותי** שהם תפילין תשמרו לבל תחקו אפילו דבק שבין אות לאות, ואומרו **ועשיתם אותם** יתבאר על דרך מה שפסק הרא''ש בתשובה ט''ז כלל ג' וז''ל מ''ם פתוחה שנדבק פתיחתה ימחוק כולה ויכתוב אחרת במקומה אבל גרירת הסתימה אינו עושה אותה אות דהוה ליה חק תוכות ואמרינן (גיטין כ'.) וכתב ולא חקק וכו' ע''כ, והוא אומרו ועשיתם אותם פירוש שאין לחוק תוכה אלא לגוררה ולעשות אחרת במקומה:
@782 **לה)** עוד ירמוז על פי מה שהעלו האחרונים (מ''א סי' קמ''ג) כי ספר תורה שנמצא בו דבק מותר לקרות בו ואין צריך להוציא אחר מטעם שיכול לגוררה וכל שראוי לבילה וכו' (מנחות ק''ג:) וחדשו עוד האחרונים (טו''ז או''ח סי' ל''ב) שאפילו הוא יום שבת שאין יכול לגוררה מטעם שהמניעה אינה מצד הספר תורה אלא לצד שמירת שבת, והוא אומרו **אם בחקתי** דבר שהוא עומד לחוק שהוא דבק האות, **תלכו** פירוש יש לכם רשות להורות כי הוא דרך שילכו בו ולא יצטרכו להוציא אחר, ואפילו יהיה בזמן שאינם יכולין לתקן שהוא יום שבת קודש שמצותי עליכם לאסור, והוא אומרו ואת מצותי תשמרו, ונתן הטעם **ועשיתם אותם** כיון שיש בידכם לעשות ויכול לתקן הרי זה כשר שאין התיקון מעכב כטעם שנתנו האחרונים:
@782 **לו)** עוד יתבאר על פי מה שפסק מהרי''ק ביורה דעה סימן רע''ו סעיף י''א וז''ל דבקה אות לחברתה באותיות שם ב''ה, יש לגררה וכתב המרדכי במנחות וז''ל שאף על פי שאזהרה למוחק ה' מלא תעשון כן וגו' הא תיקון הוא ע''כ, הוא מה שאמר **אם בחקתי תלכו** פירוש הגם שאסרתי למחוק אם הוא דבר שצריך לחוק הדבר אתם רשאין לעשות כן, והוא מה שאמר **תלכו** על דרך (שמות י''ח) והודעת להם את הדרך אשר ילכו בה, ואומרו **ואת מצותי** וגו' פירוש תנאי הוא הדבר לאמן ידיו שלא יגע אלא בחלק הדבק ולא בגוף האותיות שנצטווה עליהם לבל ימחוק, ואמר לשון רבים שיצו ה' על ב' אותיות הדבוקות שלא יגע בשניהם, ואולי שיש לסמוך גם כן דבריהם ז''ל שאמרו (שבועות ל''ה.) שאסור למחוק גם אות הנטפל לה' מאחוריו, והוא מה שרמז באומרו **מצותי** לשון רבים השם והנטפל לו שישמור לבל ימחוק בגרירתו הדבק, ואומרו **ועשיתם אותם** נתן טעם להתיר למחוק הדבק כדברי המרדכי שאין זה אלא תיקון, וגם ירמוז במאמר ועשיתם אותם על פי מה שאמרו בברייתא (מס' סופרים פ''ה) וז''ל המוחק אות אחת וכו' ואם נשפך דיו על השם מותר למוחקו שלא היתה כונתו אלא לתקן, וכתב הבית יוסף בשם הר''י אסכנדרנ''י שאפילו נפסדה האות מהאותיות שיוכל למוחקו לכל האות ע''כ, והוא אומרו ועשיתם אותם פירוש אפילו אותם עצמן שהם האותיות אם הוכרח לתקן יכול למחוק האות עצמה, ומה שהתנה ואת מצותי תשמרו לבל יגע באותיות הוא כשאין אלא דבק והאותיות שלמים אבל אם נפסדה האות עמה יכול למוחקה ולתקנה:
@782 **לז)** עוד יתבאר על דרך מה שאמרו בפרק א' של ראש השנה (כ''א.) וז''ל שלח ליה ר''ה בר אבין לרבא כי חזית דמשכה תקופת טבת עד שיתסר בניסן עבריה לההיא שתא ולא תיחוש דכתיב (דברים ט''ז א') שמור את חודש האביב, שמור אביב של תקופה שיהיה בחודש ניסן ע''כ, והוא אומרו **אם בחקתי תלכו** פירוש לפי חשבון העיבור לפי חקות השמים שהם חמה ולבנה בהודעת הזמן תלכו, תנאי הוא הדבר **ואת מצותי תשמרו** כדי שיבא זמן האביב בפסח, ואם כפי החוקות שאתם הולכים בהם לא יהיה כן **ועשיתם אותם** פירוש תעברו השנה כדי שתעשו אותם המצות כמו ששלח ר''ה בר אבין לרבא:
@782 **לח)** עוד יתבאר על דרך מה שאמרו במסכת שבת (קנ''ו:) וז''ל שמואל ואבלט הוו יתבי והוו קאזלי הנהו אינשי לאגמא וכו', הרי שהגם שהראה המזל עליו בהליכתו שימות על ידי ששמר האיש מכלימה ועשה עמו חסד תקן המזל לטובה, והוא אומרו **אם בחקתי תלכו** פירוש הגם שהוא בזמן שבו הראה עליו המזל לרעה שילך ולא ישוב אם את מצותי תשמרו יש כח בכם להפך המזלות ולתקן אותם, והוא אומרו ועשיתם אותם:
@782 **לט)** עוד יתבאר על דרך אומרם (פסחים נ''ו.) כתת נחש הנחושת וכו' ואמרו בגמרא שם לצד שהיו תועים אחריו, והנה ענין נחש הנחושת הוא חוקה אשר חקק ה' והביט אל נחש וגו' וחי (במדבר כ''א ט') והרשה אותם עשות כן, והוא מאמר **אם בחקתי** שהוא להביט אל נחש הנחושת תלכו, תנאי הוא הדבר **ואת מצותי** תשמרו אבל אם לא, אין כאן חוקה ויכול חזקיה לכתתו ובזה ועשיתם אותם לבל יטעו אחריו:
@782 **מ)** עוד יתבאר על זה הדרך שהכא מיירי במצות טבל שמצינו שיצו ה' לאוכל טבל ואפילו כהן שחייב מיתה, ויש לך לתמוה בדבר כלום מה הוא דבר שיש בתבואה זו שאוסרה הוא הפרשת תרומה ואם התרומה עצמה היא נאכלת לכהן מכל שכן תערובת, אלא אין זה אלא חקה, והוא מאמר **אם בחקתי תלכו** שלא לאכול טבל עד עשות מצות ה' להפריש תרומות וכו', והוא אומרו **ואת מצותי תשמרו** ואז ועשיתם אותם שבזה יתקנו המופרש ליאכל לבעליו והשאר לכל אדם:
@782 **מא)** עוד ירמוז על דרך אומרם ז''ל (אבות פ''ב) שוב יום אחד לפני מיתתך, שבזה יהיה כל ימיו בתשובה, והוא מאמר **אם בחקתי** שהיא גזירת המיתה שחקק ה' שאין מידו מציל אם תלכו בהם שכל יום יאמר למחר ימות בזה ודאי ואת מצותי תשמרו ועשיתם אותם:
@782 **מב)** עוד יתבאר על דרך מה שאמרו בפרק השוכר את הפועלים דף פ''ה במעשה ההוא מרבנן שאמר לו אליהו סימן להכיר כסאו של רבי חייא בהליכתו מגן עדן של מטה לישיבה של מעלה שהיה עולה מעצמו ולא היה צריך למלאכים להעלותו כשאר הצדיקים, וזה השגתו היתה באמצעות השתדלותו נמרץ בעסק התורה לעצמו ולאחרים כאמור שם, והוא מאמר **אם בחקתי תלכו** פירוש באמצעות השתדלות בתורה ללמוד וללמד כרמוז בתיבת בחקתי, תלכו פירוש מעצמכם כרבי חייא ולא תצטרכו למלאכים להוליך אתכם:
@783 **ונתתי** גשמיכם. צריך לדעת אומרו ונתתי בוא''ו המוסיף ולא קדם לזה יעוד אחר, ולמה שכתבתי בפירוש אם בחקתי שיש גזירה בתיבת תלכו יוצדק לומר ונתתי בתוספת וא''ו, גם יתישב מה שיש להעיר עוד, כי מפשט הכתוב משמע ששכר עסק התורה והמצות עשה ולא תעשה הוא ונתתי גשמיכם, אם כן שכר מצוה בעולם הזה הוא ויצא אדם נקי משכר עבודתו, ובמה שדקדק לומר **ונתתי** בתוספת וא''ו העיר אותנו שקדמו יעודים אחרים לעולם הבא, והם מה שרמזתי בפסוק אם בחקותי תלכו:
@783 **או** יאמר לצד ששכר עולם העליון רוחני ואין יעודיו נתפסים בנרשם ולא בדיבור, לזה רמזו במה שהוסיף וא''ו בתחילת ענין לומר כי יש שכר אחר, ומוסיף עוד ליתן גשמיכם, ודקדק לומר **גשמיכם** כאילו הם שלכם, לא בעד שכר מצות ומעשים טובים, אלא לצד שהם מעמידי עולם בעסק התורה וכו' זוכים בשלהם, ואולי כי לטעם זה ראה ויתר גוים התיר ממונם לישראל (ב''ק ל''ח.) כי ישראל קנו העולם וכל אשר בו והן הגוים כנכסי בני ישראל:
@783 **עוד** נתכוון לומר שהגם שהוא נותן בתורת גשמיכם מתנה אינו מחשב הדבר שהוא שלו אלא כאילו הדבר שלכם:
@783 **ודקדק** לומר **ונתתי** שהוא האדון צריך לעשות הדבר, כדי שיוריד טיפות גשמיכם בזמנם וכפי השיעור הצריך, כי הוא יודע הזמן והשיעור אשר תשתה הארץ ושיועילו לה מה שאין כן כל זולתו יתברך, וכן תמצא שאמרו ז''ל (ויק''ר פכ''ח) וז''ל אדם שוכב על מטתו והקדוש ברוך הוא מעלה עננים:
@783 **עוד** נתכוון באומרו **גשמיכם** על כללות המזון, בין הצריך לעולם, בין הצריך לאדמה, בין הצריך לנפשות, כי כולם עומדים ליזון, ויש טללים וגשמים גשמיים, ויש טללים וגשמים רוחניים כידוע ליודעי חן, ועל כולם אמר ונתתי גשמיכם, ועיין מה שכתבתי בפרשת בהר סיני:
@783 **ונתנה** הארץ וגו' פירשתי בפרשת בהר סיני:
@784 **והשיג לכם דיש וגו'**. זו ברכת התבואה אחר שנתלשה, כדרך אומרם ז''ל (ב''מ מ''ב.) הבא למוד גרנו יאמר יהי רצון וכו', הרי כי יש ברכת ה' אפילו אחר שעשוי גורן, והוא אומרו והשיג לכם דיש שיתרבה הצומח עד גבול זה, ועיין מה שפירשתי בפרשת בהר בפסוק ועשת את התבואה (כ''ה כ''א):
@784 **ואכלתם וגו' לשובע**. זו ברכת המזון בבטן כאומרם ז''ל (תורת כהנים) אוכל קימעא ומתברכת במעיו:
@784 **עוד** ירצה לומר שלא ימשך לכם דבר הרגיל להיות בבני אדם כי ירבה טובם ומזונותיהם שמתמלאת תאותם בזה ולא יעצרו כח למיכל לשובע, אלא ואכלתם לחם לשובע אכילה מרובה כדי שביעה:
@784 **עוד** ירצה על דרך אומרם ז''ל (מגילה ז':) רווחא לבסומי שכיחא, והוא אומרו ואכלתם וגו' **לשובע** שיהיה לחמכם ערב כל כך שאפילו יהיו שבעים יאכלוהו:
@784 **עוד** דקדק לומר **לחמכם** שאינם צריכין לפתן ללפת בו את הפת אלא הלחם לבדו ערב לנפש לאכול ממנו כדי שביעה:
@784 **עוד** ירצה על פי דבריהם ז''ל (גיטין ע') אכילה גסה הוא סם המות לגוף, והבטיח ה' שיאכלו לחמם לשובע אפילו יהיו שבעים יאכלו ולא יזיקום:
@784 **עוד** ירצה לצד שיש בפירות שיש בהם שומן כאומרם במשנה (ס. טה מ''ח.) טעם הפירות ושומן הפירות, והנה כל האוכל שיש בו שומן אדם אוכל ממנו ומרגיש בכדי שביעה מה שאין כן כל אוכל שאין שומן הגם שיאכל אדם וממלא בטנו אין הרגש השובע במעיו, ואלו הם דברים הנרגשים לכל מרגיש כידוע, והודיע הכתוב כאן במאמר **ואכלתם לחמכם לשובע** פירוש אפילו לחם לבד היוצא מן הארץ ירגישו באכילתו השובע, כי יש בו שומן הסועד לבב אנוש:
@784 **וישבתם לבטח בארצכם**. ירצה כי לצד שכל הברכות האמורות בענין יכולין להתקיים ואין טובתם טובה, וכגון אם היו טרודין במלחמות ושנה חורשים וזורעים ושנה אין חריש וקציר ומשלמת שנה לשנה, אם כן אין היכר לברכה, תלמוד לומר וישבתם לבטח בארצכם אין מטריד אתכם וכל שנה ושנה תהיה לכם הברכה האמורה, ואומרו **בארצכם** פירוש שכל העולם יכירו וידעו כי היא ארצכם ואין לזרים אתכם בה ובזה לא יהיה לכם אפילו מיחוש ותשבו בטח:
@784 **עוד** ירצה באומרו **וישבתם לבטח** פירוש שלא תטרחו אתם בקציר ובבציר אלא זרים יעבודו ואתם יושבים בקתדרא, ואומרו לבטח שאין מיחוש על הקנין היותו ביד עובדים:
@785 **ונתתי שלום בארץ**. צריך לדעת למה הוצרך לומר זה אחר שכבר אמר וישבתם לבטח, ואולי שיכוין על עם בני ישראל עצמם שלא יהיה להם פירוד הלבבות שיטע ה' ביניהם שלום וריעות. או אפשר שיכוין על כללות העולם, ותדע שכשמדבר על ארץ ישראל מזכירה בכינוי כאומרו בסמוך בארצכם, וכאן אמר **בארץ** שמבטיחם כי יהיה שלום בכל העולם, ותמצא שחפץ ה' בדבר, וצא ולמד מפרי החג ע' כנגד ע' אומות, ומאמרי רבותינו ז''ל (סוכה נ''ה:) בענין זה, גם כפי הטבע כשיש מלחמות בעולם יחרדו גם היושבים בטח לקול ענות מלחמה, ולזה גמר אומר **ושכבתם ואין מחריד**:
@785 **והשבתי חיה רעה**. פירוש לצד שהבטיחם ה' שיהיו יושבים בטח איש תחת גפנו ותאנתו מזה יסובב שהדרכים הרחוקים קצת מן הישוב תתמעט בהם רגל דורכת, וכיון שכן ימצאון שם חיות המדבריות ויתקרבו לבא אל הישוב, לזה אמר **והשבתי חיה רעה מן הארץ** פירוש ארץ אשר בא בה המיחוש שתהיה בו חיה רעה שהוא מקום הקרוב לישוב, ולזה לא אמר בארצכם כמו שהתחיל לומר בסמוך מלפניה ומלאחריה:
@786 **ורדפתם את אויביכם**. קשה אחר שהבטיח בשלום ובבטחה מה מקום לומר כן, אכן ירצה כי מה שהבטיח הוא ממה שמהאומות להם שלא ירעו ולא ישחיתו אבל לא ממה שמישראל לאומות, וזו היא עיקר נס ההבטחה שלא יאמרו כי השלום והבטח' הוא שגם הם לא ירעו ולא ישחיתו לאומות ונמצאו כגומלין, תלמוד לומר **ורדפתם** וגו' כי אתם תרדפו אותם ותאבדום, ואף על פי כן תשבו לבטח ובשלום ולא תעבור חרב בארצכם, ומה שקרא אותם הכתוב אויבים, לא לצד שהם באים לצור על עיר הקודש שאם כן אין בטח ואין שלום ליושביה, אלא קרא אותם אויבים לצד אויבי ה' רשעי הגוים נקראים אויבי ה' ואויבינו, גם לצד שיודע ה' כי כל האומות שונא ישראל בטבע המתקנא והיא שנאה יסודית ואין לה תמורה:
@786 **ונפלו וגו'**. אומרו **לחרב** פירוש תהיה נפילת האויבים לפני עם ה' כשיעור הנפילה אשר תהיה מהחרב, ובדרך רמז ירצה על דרך אומרם במעשה נם בני חשמונאי (יוסיפון כ''ב) שראה מלאך שולף חרב נגד האויב, והוא מה שרמז באומרו **ונפלו** וגו' לחרב פירוש הנשלף מהמלאך:
@787 **ורדפו מכם חמשה וגו'**. קשה אחר שאמר הכתוב שיפלו האויבים לפנינו וכו' בדרך כלל שמשמע אפילו ריבוא לפני ב' אם כן מה מקום לומר ורדפו ה' מאה אין זה אלא ממעט מברכה א', אכן יתבארו הכתובים על פי מה שאמרו ז''ל במסכת סוטה דף י''א וז''ל לעולם מדה טובה מרובה ממדת פורעניות, והקשו התוספות שם בד''ה לעולם וז''ל וא''ת הרי מצינו מדת פורענות גדולה ממדה טובה דכתיב (דכרים ל''כ ל') איכה ירדוף אחד אלף ושנים יניסו רבבה גבי מדת פורעניות וגבי מדה טובה כתיב ורדפו מכם חמשה מאה וי''ל דגבי מדת פורענות מיירי רדיפה ולא הריגה אבל הכא כתיב ורדפו מכם חמשה מאה וסיפא דקרא ונפלו אויביכם לפניכם לחרב עכ''ל, וקשה לי על דבריהם ז''ל ממה שאמרו במסכת מועד קטן פרק אלו מגלחין (ט''ז:) וז''ל ואלה שמות הגבורים וגו' על שמנה מאות חלל בפעם אחת שהיה זורק חץ ומפיל שמנה מאות חלל בפעם אחת והיה מתאנח על מאתים דכתיב איכה ירדוף אחד אלף יצתה בת קול ואמרה לו רק בדבר אוריה החתי ע''כ, ולדברי התוספות דמה שאמר הכתוב איכה ירדוף אחד אלף מדבר ברדיפה בלא הריגה למה היה מתאנח דוד על שלא היה הורג אלף דכתיב איכה ירדוף אחד אלף הלא פסוק זה אינו מדבר בהריגה:
@787 **אשר** על כן נראה דבין פסוק ורדפו מכם חמשה מאה בין פסוק איכה ירדוף אחד אלף אינו מדבר אלא בהריגה ומה שהוקשו ז''ל נראה לתרץ על פי מה שאמרו בתורת כהנים וז''ל מכם מן החלשים שבכם ולא מן הגבורים שבכם ע''כ. ויש לדקדק למה כפל לומר ולא מן הגבורים אלא הכונה היא שבא לשלול שלא לפרש בדבריו שר''ל אפילו מן החלשים לזה פירש לא מן הגבורים ועל פי הדברים הללו לא קשה כי בפסוק זה לא הזכיר אלא ברכת החלשים שבישראל שירדפו ה' מאה וגו' וחלשים כיוצא בהם באומות העולם אינם אפילו עורכי מלחמה ומ''ש הפסוק איכה ירדוף אחד אלף מדבר בגבורים ואומרו אחד נתכוון לומר המיוחד שהוא הגבור ולא הוצרך לומר הדרגה זו בישראל כי ילמד ממדת פורענות שהרי מדה טובה מרובה:
@787 **ומעתה** ב' דברים צוה ה' לטוב לעמו ישראל הא' לא הגביל בה שיעור והם גבורי ישראל ועליהם הוא אומר בפסוק אחד ורדפתם את אויביכם ונפלו וגו' לחרב ואם נפשך עגמה עליך לדעת שיעור צא ולמד ממדת פורענות שנאמר איכה ירדוף אחד אלף וכלל גדול הוא כי מדה טובה גדולה ממדת פורענות ולפחות בהשוא' כמו שהוכיחו התוס' (סוטה י''א) ז''ל מההיא שאמרו כל העוסק בתורה יום אחד בשנה מעלה עליו הכתוב כאילו עסק כל השנה והוכיחו מהאמור בפרשת מרגלים וגו' (י''ד ל''ד) אשר תרתם את הארץ יום לשנה וגו' הרי שאין הכרח להיות גדולה אלא שלא תמצא פחותה ממנה בענין בהכרח תתחייב לומר שאחד מישראל יהרוג אלף לפחות ולזה היה דוד מתאנח על תשלום האלף כדי שלא תהיה מדת פורענות מרובה כי דוד היה אחד המיוחד:
@787 **ותמצא** בדברי הימים א' סימן י''ב שאמר הכתוב אלה מבני גד ראשי הצבא אחד למאה הקטן והגדול לאלף הנה לפניך כי מה שאמר הכתוב ה' מאה ומאה רבבה הם החלשים ובזה גילה כי מה שאמר הכתוב איכה ירדוף אחד אלף ירצה לומר אחד המיוחד לא מהפחותים ומעתה הרווחנו קושית יתור פסוק ראשון שאמר ורדפתם את אויביכם שמדבר בגבורים ולא אמר שיעור כי אין שיעור להם שאפשר שאחד לחמש מאות אלף ולפחות אחד לאלף כאמור בקללה איכה ירדוף אחד אלף והניח ה' הדבר סתום שאין כל הגבורים שוים ואין כל הזכיות שוות ואין כל הזמנים שוות יכול להיות שאחד ירדוף ריבוא אלא לפחות אחד אלף:
@787 **ונפלו אויביכם וגו'**. כפל לומר דבר זה פ''ב רז''ל דרשו (תו''כ) שהכוונה היא שיפלו איש בחרב רעהו ונראה עוד לומר לפי שעשה הפרש בין רדיפת ה' לרדיפת מאה הוסיף עוד לומר שהוא הדין אם יהיה אלף מישראל תגדל הנפילה באויביהם כשיעור ההפרש שבין ה' למאה יהיה כמו כן בין מאה לאלף והוא אומרו לחרב פירוש לשיעור מנין חרב נוקמת:
@788 **ופניתי אליכם וגו'**. אומרו **ופניתי** על דרך אומרם ז''ל (תענית ב') ג' מפתחות ביד הקדוש ברוך הוא וא' מהם הוא של לידה לזה כשרצה לומר והפריתי אתכם אמר ופניתי שהוא יפנה עצמו כביכול לעשות דבר זה ולא על ידי שליח ואולי שיכוון ג''כ במאמר **והרביתי** על מפתח הפרנסה כי בפרנסה קומתם גדלה ואמרו בתורת כהנים והרביתי אתכם בקומה זקופה ובמאמר **והקימותי את בריתי** על דרך אומרם ז''ל (סנהדרין צ') שברית כרותה לשוכני עפר להחיותם והוא מפתח הג' שביד הקדוש ברוך הוא וכנגד שלשתם אמר ופניתי וגו':
@788 **עוד** יתבאר על דרך אומרם ז''ל (שבת קנו) אין מזל לישראל ועל דרך אומרו (ישעי' מא) צדק יקראהו לרגלו שעקר ה' מזל זה ממקום אחד ונתנו במקום אחר והוא מאמר ה' ופניתי אליכם והפריתי וגו' כנגד בני חיי ומזוני הגם ששלשתם הם תלויים במזל ולא בזכות (מו''ק כח) אני אפנה המזל ממקום למקום המורה אליכם לפרות זה כנגד הבנים **והרביתי אתכם** כנגד חיי על דרך אומרו (דבדים יא) למען ירבו ימיכם וגו' **והקימותי את בריתי** כנגד מזוני ויחס לה שם ברית על דרך אומרו (נח ח') ויאמר ה' אל לבו לא אוסיף וגו' עוד כל ימי הארץ זרע וקציר וגו' ואמרו ז''ל (שבועות לו) כי מה שאמר לא אוסיף הוא שבועה וכתיב שם (ט' י''ב) זאת אות הברית וכל הנאמר שם הוא נכלל בכלל השבועה ודקדק במאמרו כאן שיקיים אותה הברית של זרע וקציר עמם והוא אומרו **והקימותי את בריתי אתכם** כי לא היתה השבועה בדרך כלל על כל הארץ כי הלא יש כמה שנים שאין זרע וקציר בחלק מן הארץ כי ה' לא אמר שם בברית נח ימי כל הארץ ועיין מה שפירשתי בפסוק (דברים ו') ואהבת את ה' אלהיך:
@788 **עוד** יתבאר אומרו **ופניתי אליכם** על דרך מה שאמר הנביא (ש''ב ו') ולא אבה דוד להסיר אליו ארון ה' וגו' ויטהו דוד בית עובד וגו' ויברך ה' את עובד וגו' ואמרו ז''ל (ברכות סג) אשתו וח' כלותי' ילדו ששה בכרס אחד דכתיב (דה''א כ''ו) פעולתי השמיני ששים ושנים ע''כ והוא מאמר ה' **ופניתי אליכם והרביתי אתכם** שבאמצעות פניית ה' אליהם ישתלשל הדבר מעצמו להרבות אותם כמו שנשתלשל לבית עובד כשהטה אליו ארון ה'. ואומרו **והרביתי אתכם** לשון מעלה ורבנות והכונה בזה שהגם שיהיו מרובים כל כך ומדרכים הרגילים בנמצאים בעולם כל המתרבה ימעט ערכו כאשר הרחבנו ביאור פרט בחינה זו במקומות אחרים (שמות א' ט' שלח י''ג י''ח) אף על פי כן והרביתי אתכם ואומרו **והקימותי את בריתי אתכם** הבטיחם מה שהבטיח הנביא דכתיב (ישעי' נ''ט) ואני זאת בריתי אותם אמר ה' וגו' לא ימושו מפיך וגו' שלא תפסק תורה מזרעם. עוד נתכוין לומר בדרך כלל ברית ההטבה שיחדש הברית עמהם מלבד ברית האבות והוא אומרו והקימותי את בריתי שכבר נשבעתי לאבותיכם אקיים אותה אתכם מחדש:
@789 **ואכלתם ישן נושן**. פירוש שלא תתעפש התבואה ולא תהיה נרקבת או תפסד מאכילת הפוליטיקין אלא אדרבה תבחרו לאכול היותר ישן והוא מה שכפל לומר ישן נושן ואומרו **וישן מפני חדש תוציאו** פירוש לא תוציאו אותו לצד שנתישן ונפסד אלא מפני חדש תוציאו אותו וטעם שכתב דבר זה כאן ולא במקומו למעלה כשהזכיר ברכת התבואה וברכת הארץ נתכוין הכתוב בזה להגדלת הטובה שהגם שיפרה וירבה אותם אף על פי כן תהיה להם הפלגת הטוב שיאכלו ישן וגו' מה שאינו כל כך כשהאוכלים מועטים שאז אפילו מהמיעוט יאכלו ישן נושן:
@790 **ונתתי משכני בתוככם**. פירוש על דרך אומרו (תהילים ע''ח) אהל שכן באדם שעיקר משכנו יתברך הוא תוך נשמות עם קדושו ואומרו **ולא תגעל נפשי** ולא הספיק אומרו ונתתי משכני לצד שחש ה' כי יאמר נא ישראל שדבר זה שמבטיח ה' הוא דבר רחוק מהשכל שידור דירת קבע רוחני בלתי בעל תכלית הרוחניות תוך בני אדם בעלי צורה וחומר והגם כי יבטיח ה' עשות כן זה יהיה לצד עוצם האהבה יהפך הצורה על דרך מה שפירש הרשב''י (זוהר ח''ג רמ''א) בפסוק באתי לגני וגו' אכלתי יערי וגו' שתיתי ייני וגו' משל לחתן וכו' יעויין שם דבריו והוא דבר הפך תכונת ההשתוות ודבר כזה לא יתמיד כמעשה ניסים ואין מבטח להתמדת הדבר ותגעל הרוחניות לגשמיות לזה אמר **ולא תגעל נפשי אתכם** כי יכונן ה' תכונת נפשם בסדר אשר ישכון ה' בתוכם כדרך המתקבל בתכונת הנשתוו' והוסיף לומר **והתהלכתי בתוככם** לומר שמלבד שלא יגעל גם יהיה לו נחת רוח בהשראת שכינתו בתוך תוכם והיא בחינת הנשמה שהיא תוך תוכם ופירוש והתהלכתי הוא טיול הערב גם נתכוין על דרך מה שאמרו ז''ל כי נשמות עם בני ישראל חצובות מאורו יתברך והרחקת שכינתם בעולם הזה לא יסובב פרידתה ממקורה והרי היא דבוקה בחבל הכסף עד מקום מחצבה ודרך שם יורד אור החיים ממקור עליון ומחבר נפש קדושה עם מקורה וזה יסובב כי תכיר הנפש בוראה ותתאו לעבודתו וללכת בדרכיו ועל ידי חטא האדם נרתק חבל הכסף ולא יאיר אור הבא מלמעלה תוך הנפש והוא סוד אומרו (ישעי' נ''ט) עונותיכם היו מבדילין בינכם ובין אלהיכם וזה יסובב שיקו האדם מטעמי התיאוב ויאבד חשקו במושכלות הנעימים והערבים והוא מאמר ה' באומרו **והתהלכתי בתוככם** זו חבל הכסף המתהלך מאורו יתברך תוך נפש אדם ובזה **והייתי לכם לאלהים** כי איש כזה יבחר בקבלת עול אלהותו יתברך ותמצא שכל נפש החוטאת בעולם אינה פועלת הרע בתחלתה עד שתקדים בחטא קל מקלי הקלות ובחטוא האדם אפילו כחוט השערה ימנע ממנו בחינה זו של התקשרותו במדרגה עליונה וצא ולמד ממעשה נבות (מ''א כ''ב) שעל ידי שאמר דבר שקר הגם שהיה לתכלית רצונו יתברך אף על פי כן ה' אמר אליו צא ממחיצתי (שבת קמ''ט) וכשמשתדל היצר עם האדם בדקדוק קל עד שיבדיל בינו ובין ה' אז הוא שיכול לשלוט בו לחטוא חטאים גדולים רח''ל מה שלא היה יכול עשות קודם בעת דביקות האדם באור עליון:
@790 **עוד** נראה לפרש הפרשה על זה הדרך שהכתוב מדבר בהכנות עולם הזה גם בשכר עולם הבא והתחיל בברכת הלחם ואמר **ונתתי גשמיכם בעתם** שהוא הכנת המזון והפרנסה והבטח בארץ כאומרו וישבתם לבטח עליה עד כאן כלל כל הכנת עולם הזה ואומרו **ונתתי שלום** וגו' מכאן מתחיל גמול הנסתר והוא מעת הפרידה מעולם הזה שהוא יום המיתה שהוא המדוה הגדול אשר בלב כל חי הכוס המר ההוא הגם שיהיה האדם שלם בכל שלימות העולם הזה בזוכרו יום המיתה וערבה כל שמחה ומה גם שאין לו גבול רחוק שאין אדם יודע יום קיצו אשר על כן בא המבטיח טובות לעמו וסמך לבם גם בדבר זה ואמר כי ביום הנסיעה לא יחרד האיש ולא ירגז כדרך המתים אלא יעשה ה' דבר שתהיה הנסיעה כאדם ששוכב וערבה לו שנתו:
@790 **והוא** אומרו **ונתתי שלום** על דרך אומרם ז''ל (שבת י') כי שמו של הקדוש ברוך הוא שלום ובעת פטירת הצדיק יקרב אורו יתברך לפני האדם והוא סוד מיתת נשיקה ובזה יהיה כשוכב והוא אומרו **ושכבתם** כמו שנאמר באבות שכיבה וסוד הדבר כי הנפש כשמרגשת בקריבת אור הנערב אצלה תכסוף ותנתק ממקומה להדבק בשכינה ולעוצם התאוה יתרבה העריבות על הרגשת הפרידה ולא תרגיש בו ולא ישאר ההרגש אלא מהערב ועיין מה שכתבתי בתחלת אחרי מות וכל השגה זו תסובב עסק התורה והמצות והוא מאמר הכתוב (קהלת ה') מתוקה שנת העובד השינה היא יציאת הנשמה מן הגוף שהעובד את ה' ועוסק בתורה ובמצות מתוקה לו יציאת הנשמה על אופן האמור ואומרו **ואין מחריד** הוא מלאך המות המחריד האדם בראייתו לבד ולצד שיש צדיקים שיזכו להדבק נפשם בשכינה אבל יקדים להם מלאך המות לסיבת תחלואי הנפש לזככה באמצעות צער החרדה לזה הבטיח כי כל עיקר לא יראו מחריד:
@790 **עוד** ירצה אומרו **ונתתי שלום**. שיתקיים הגוף שהוא בחינת הארץ ולא יתפרדו היסודות וצא ולמד ממעשה רב אחאי בר יאשיה (שבת קנ''ב) שגששיה רב נחמן אחר כמה שנים שמת וראהו כי איש קיים היה כי ה' יצו ליסודות להתקיים יחד ולא יתפרדו וזה יושג מאמצעות התורה כמאמר (משלי ו') בשכבך תשמור עליך ואומרו **ושכבתם ואין מחריד** על דרך אומרם (ישעי' נז) ינוחו על משכבותם שלא תשלוט רימה בגופם להחרידם בקבר ותמצא שהצדיקים אין רימה בגופן וצא ולמד ממעשה רבי אלעזר בן רשב''י (ב''מ פ''ד) וכאלה רבות ודבר זה הוא יעוד גדול שינוח הגוף בקבר שאמרו ז''ל (שבת י''ג) קשה רימה בבשר המת כמחט בבשר החי ויש לך לדעת כי כל נברא ירגיש כפי שיעור תכונתו אשר כוננו יוצרו ואומרו **והשבתי חיה רעה מן הארץ** הוא רוח הטומאה הנקראת חיה רעה שהיא חיוניות רע בחינת הטומאה השורה על הגוף אחר מיתה שלזה ציוה ה' שהנוגע במת או הנכנס לאוהל יטמא ז' ימים הבטיח ה' כי תסגיל התורה והמצות להשבית רוח הטומאה מן הגוף ותמצא שאמרו ז''ל (כתובות ק''ג) יום שמת רבי בטלה טומאה:
@790 **ואומרו וחרב לא תעבור בארצכם**. נתן הכתוב טעם להשבתת הטומאה הוא כי טומאה זו עיקרה הוא לצד שנשחט האדם בחרבו של מלאך המות הפגומה שבזה נעשה נבילה והנבילה מטמאה ונשלכת לכלב דכתיב (שמות כ''ב) לכלב תשליכון והטומאה היא בחינת הכלב אבל ההולכים בתורת ה' כמצטרך חרב לא תעבור בארצכם שהוא גופו הנבנה מהארץ ממוצא דבר אתה יודע שלא יגע חרבו של מלאך המות בגופו של צדיק עד כאן יעודי הפטירה ומנוחת הגוף:
@790 **ואומרו ורדפתם**. מכאן מתחיל פועל הרוחניות הנעלם המושג מעסק התורה דע כי התעצמות עסק התורה ומעשה המצות הוא לברר ניצוצי הקדושה וליחד ענפיה אחד אל אחד אשר לסיבת אחיזת הקליפות ימנע הדבר בסוד אומרו (ישעי' נ''ט) עונותיכם היו מבדילים בינכם וגו' ועיין מה שפירשתי בפרשת יתרו בפסוק (י''ט ה') והייתם לי סגולה ויתייחסו הקליפות בשם שונאים ואויבים ועיין מה שפירשתי במאמרם ז''ל בפסוק (תהלים צ''ב) כי הנה אויביך ה' ויערבו לך דברי אלהים חיים וכאן הודיע הכתוב כי באמצעות עסק התורה והמצוות ירדפו את אויביהם ונפלו וגו' ותאבד הטומאה כמאמר (זכרי' י''ב) ואת רוח הטומאה אעביר וגו' ואומרו **לחרב** על דרך אומרו (שה''ש ו') איש חרבו על ירכו ואמרו ז''ל (תקונים ז') שהשומר בריתו לבל נוגע במה שלא הורשה זה יש כח בו להמית ולאבד אויבי ה' ברוח שפתיו ולזה לא אמר בחרב אלא לחרב ואומרו **ורדפו מכם ה' מאה** פירוש ממה שיצא מכם ירדפו ה' שהם חמשה חומשי תורה ירדפו מאה הדרגת הקליפות והוא על דרך אומרו (משלי ט''ז) נפש עמל עמלה לו ואמרו ז''ל (סנהדרין צ''ט) אדם במקום זה ותורתו עמלה לו במקום אחר שעושה כליון לאויבי ה':
@790 **ואומרו ומאה מכם**. פירוש על דרך אומרם (מנחות מ''ג ב') מה ה' אלהיך שואל מעמך וגו' אל תקרי מה אלא מאה שהם מאה ברכות והוא אומרו **ומאה מכם** פירוש שנעשים מכם שהם מאה ברכות בכל יום **רבבה ירדופו** וחזר לומר **ונפלו אויביכם** וגו' לחרב נתכוין למאמר חז''ל שאמרו (ברכות ה.) כל הקורא קריאת שמע וכו' כאלו אוחז חרב פיפיות וכו' דכתיב רוממות אל בגרונם וחרב פיפיות בידם והנה פסוק ראשון רמז בו יעוד המסובב מהמעשה ופסוק ב' יעוד המסובב מהדיבור המקודש ואומרו **ופניתי אליכם** פירש הכתוב תכלית ההצלחה הבאה מכליון האויבים ואמר ופניתי אליכם פירוש כשזה נופל יפלו כל ניצוצי הקדושה אל שורשם שהם כללות ישראל המקבצים אותם וכינה ניצוצי הקדושה אליו יתברך לצד שהם חלק ה' ובזה יפרו וירבו ועיין מה שפירשתי בפסוק (סוף ויגש) ויאחזו בה ויפרו וירבו מאוד ומה שפירש המגיד למהרי''ק בפסוק וימת יוסף וגו' ובני ישראל פרו וגו':
@790 **עוד** ירצה באומרו **ופניתי** וגו' כי בהבטל האויב שהוא מסך המבדיל כמאמר (ישעי' נ''ט) כי אם עונותיכם היו מבדילים וגו' בהסרת המסך אז יפנה וידבק ה' בנו:
@790 **עוד** ירצה כי כשישראל ישתדלו בדבר האמור הגם שישנו למפסיק בחלק א' האדון יפנה לנו מחלק המופנה ויגדיל וירבה כחינו נגד האויב עד כלות המסך ואז והקימותי וגו':
@790 **עוד** ירצה **ופניתי אליכם** על פי דבריהם ז''ל בזוהר (בזוהר ח''ג ש''ג) כי שעשוע הצדיקים שאין למעלה ממנו הוא בחצי לילה השני שהקדוש ברוך יושב על כסאו בין הצדיקים שבגן עדן ומסיר פרגוד אחד ומגלה להם אור פנימי הנערב ולרוב ההשתוקקות ועוצם הפלגת הרגש העריבות לנשמות עד שמתעלפים ונושרים מהם אורות והם נפשות שיורדות לעולם התחתון להאיר יעויין שם דבדיו בזוהר חדש (פר' בלק) והוא מה שדמז במאמר ופניתי אליכם שהוא על שעשוע הגדול ומופלא הנזכר. ואמר לשון פנייה לצד שהאדון ברוך הוא אינו משתנה דכתיב (מלאכי ג') אני ה' לא שניתי אלא שמגלה מאורו את אשר יחפוץ ויסתיר כפי מה שאינם ראוים להשיג לזה אמר ופניתי אליכם להאיר למולכם אור הפנימי הנסתר יראו עיניכם וישמח לבכם. ואומרו **והפריתי אתכם** רמז לניצוצות הנושרות מהם לצד ההתעלפות כאמור ואומרו **והרביתי אתכם** פירוש שלא תחשוב כי לצד נשירת הנשמות מהם ימעט אורם ח''ו לזה אמר והרביתי אתכם שיתרבה אדרבה אורכם כאור פני מלך וסוד הנשירה אולי שיהיה בא' מב' הדרכים או כי ירבה אורם עד שיהיה והותר או כי אור הקודם ידחה מפני אור חדש וישן מפני חדש תוציאו כסדר האמור בדברי המקובלים כי המוחין דגדלות ידחו מוחין דקטנות ונמצא הנושר מהם הוא לצד ההתרבות והוא אומרו והרביתי אתכם:
@790 **עוד** ירצה באומרו **והרביתי אתכם** לשון רבנות והוא על דרך אומרו תהיו לי ממלכת כהנים וגוי קדוש ופירשנוהו שם שהגדילם על המלאכים כהני עליון שיהיו הם קרובי המלך וגדולי העליונים ואומרו והקימותי כאן הבטיח על התחיה שברית כרותה לשוכני עפר שיעלה ה' אותם מקברותיהם ואמר ה' כי דוקא ללומדי תורה על דרך אומרם ז''ל (כתובות קי''א) כל העוסק בטל תורה טל תורה מחייהו ואולי כי הן הן הדברים שרמז באומרו **והקימותי את בריתי** שהוא התורה אתכם כי בטל אשר יצו ה' אתם התורה הם חיים:
@790 **עוד** נתכוון על דרך אומרם (סנהדרין צ') בפסוק אשר נשבעתי לתת לאבותיכם שהאבות עצמם יעמדו לרשת את הארץ והוא מאמרו כאן שאותה ברית שנשבע ה' לקיים הארץ לעולם ועד בידם כל המקיים תנאי הכתוב יחייהו ה' עם האבות לקיים בידו ברית הארץ לעולם ועד:
@790 **עוד** רמז גניזת הנשמות בצרור החיים את ה' וידוע כי בחינה המתיחס לה ברית יתיחס גם כן לה שלום והוא אומרו **והקימותי את בריתי** שהוא יסוד עולם הנשמות אתכם גם בזה כלל זיווג חי העולמים בכנסת ישראל שהיא כללות הנשמות והמשכיל יבין כי הוא זה תכלית מנוחת הנשמות:
@790 **ואומרו ואכלתם ישן נושן**. כאן רמז לסעודת עולם הבא שיטעימם ה' מיין המשומר בענביו מו' ימי בראשית גם מבשרו של לויתן ואין לך ישן נושן כזה שלא קדמו דבר בעולם קודם לבריאת האדם:
@790 **ואומרו וישן מפני חדש תוציאו**. מלבד מה שפירשתי בו למעלה ירמוז עוד על דרך מה שאמרו ז''ל (חגיגה י''ב) בפסוק וימנע מרשעים אורם כי אור שבו ברא הקדוש ברוך הוא מעשה בראשית גנזו הקדוש ברוך הוא לצדיקים לפי שראה הרשעים שאינם ראוים להשתמש בו וכו', והוא אומרו וישן שהוא אור שקדם לאור זה החדש שנתחדש אחריו והוא אומרו מפני חדש תוציאו פירוש תוציאו מבית גנזיו להשתמש בו:
@790 **ואומרו ונתתי משכני וגו'**. ירצה על דרך מאמרם ז''ל (ב''ב ע''ה) שעתיד הקדוש ברוך הוא להוריד משכן מן השמים ויש מרבותינו ז''ל שאמרו שהוא משוהם ויש מרבותינו ז''ל שאמרו מישפה, וכאומרו (שמות ט''ו) פעלת ה' מקדש ה' כוננו ידיך והוא אומרו **ונתתי משכני בתוככם** פירוש משכן שכוננו ידי אורידהו ואתנהו בתוככם ומאז עד עולם יעמוד הדבר כאומרו ולא תגעל נפשי אתכם כי יעביר רוח הטומאה מן הארץ:
@790 **עוד** ירצה על דרך אומרם ז''ל (במדבר כ') בפסוק כעת יאמר ליעקב וגו' שהמלאכים מבחוץ והצדיקים מבפנים והמלאכים שואלים את הצדיקים מה פעל אל והוא אומרו **ונתתי משכני בתוככם** שלא יהיה מחנה המלאכים מפסיק ביניכם וביני:
@791 **ואומרו והתהלכתי בתוככם**. על דרך אומרו (יואל ג') ונבאו בניכם ובנותיכם שיהיה אורו יתברך מתהלך בתוכם והוא רוח המנבא על דרך אומרו (במדבר י''א) עם ה' נביאים כי יתן ה' את רוחו עליהם:
@791 **עוד** ירצה על דרך אומרם ז''ל (תענית ל''א) עתיד הקדוש ברוך הוא לעשות מחול לצדיקים וישב ה' בתוכם וכל אחד יראה באצבעו ויאמר זה אלי ואנוהו והוא אומרו **והתהלכתי בתוככם** ואמר לשון הליכה לצד שיתהלך אורו יתברך לזון נשמות היושבים סביביו יקרא הליכה ואומרו **והייתי לכם לאלהים** הוא מאמרם זה אלי ואנוהו ואולי שרמז לשון נוה שהצדיקים עצמן הם נוה של הקדוש ברוך הוא שהוא דר ביניהם ואומרו **ואתם תהיו לי לעם** שיהיו הם קרובים יותר מכל צבא השמים:
@791 **עוד** ירצה באומרו **והייתי לכם לאלהים** לצד כי בזמן הזה אמונת אלהותו הוא מפי הנביאים לזה אמר כי הנה ימים באים שכל עם ה' יוכר להם אלהותו יתברך וידעו כי ה' הוא האלהים והוא מאמר והייתי לכם לאלהים שיכירו אלהותו מצד עצמם ולצד שהכרה זו ישנה לכל הנבראים דכתיב (זכריה י''ד) ביום ההוא יהיה ה' אחד לזה אמר **ואתם תהיו לי לעם** הגם שההכרה שוה בכל לא יהיו לו לעם אלא עם בני ישראל:
@792 **ואומרו אני ה' וגו'**. יתבאר על דרך מאמר חז''ל (ברכות י''ב) בפסוק ולא יאמר עוד חי ה' אשר העלה את ישראל ממצרים וגו' שהכוונה היא שיאמרו חי ה' אשר העלה ישראל מארץ מצרים ומכל הארצות והוא אומרו אני ה' וגו' אשר הוצאתי אתכם מארץ מצרים זה כנגד יציאת מצרים וכנגד אשר העלה אתכם מכל הארצות אמר ואשבור מוטות עולכם וגו' ולפי מה שפירשתי בפסוק (שמות כ') אנכי ה' אלהיך אשר הוצאתיך מארץ מצרים מבית עבדים יתבאר הכתוב גם כן על האופן עצמו יעויין שם:
@793 **ואם לא תשמעו וגו'**. צריך לדעת היכן נצטוו בתנאי על השמיעה בתחלת הפרשה שיוצדק לומר בכפל התנאי ואם לא תשמעו ולא היה צריך להתחיל אלא מואם בחקתי תמאסו, ונראה כי כאן נתכוון הכתוב להעירך כי מה שאמר בתחילת הדברים אם בחקתי שכוונתו היא על עסקי התורה ולזה רשם בהפכיותה שלילת השמיעה ואיזו מצוה שתלויה בשמע אוזן הוי אומר עסק התורה על דרך אומרו (ישעי' נ''ה) שמעו ותחי נפשכם ישמע חכם ויוסיף לקח (משלי א') ולצד שנתכוון ה' במאמר בחקתי לכל מה שפירשנו בה בכפל התנאי תלה כל המשך הרע מסיבת העדר התורה:
@793 **עוד** לצד שרצה ה' לומר שלילת שמירת המצות ומיאון עשות רצונו יתברך לזה הקדים הסיבה ואמר שסיבת הדבר היא לצד שלא למדו תורה על דרך אומרם ז''ל (קדושין מ') אמר הקב''ה בראתי לכם יצר הרע בראתי לו תורה תבלין הרי כי אין תקוה לינצל מהיצר על ידי עסק זולת התורה וכשיושלל מהתורה יטה אזנו ליצרו הרע:
@793 **עוד** נתכוון להעיר לב נרדם כי כל שהולך בדרך לא טוב ודאי שהושלל ממנו ידיעת הבורא ב''ה וטובותיו והנמשך מעבודתו כי בודאי אם ישיג אדם חלק א' מערבות ידידות נעימות מתיקות ענף מענפי אור עליון יבז בלבו היות בעולם הזה מלך המלכים בערך קיום מצוה אחת והוא מה שהעיר ה' באומרו **ואם לא תשמעו לי** פירוש לשון הבנה אז הוא שאני חושש לכם שלא תעשו וגו' אבל אם תבינו ותדעו אותי אין לחוש והוא מאמר הנביא (ישעי' ה') לכן גלה עמי מבלי דעת:
@793 **עוד** ירצה בהעיר עוד אומרו **ולא תעשו את כל** לפי מה שפירשתי בפסוק אם בחקתי תלכו וגו' באחד מן הדרכים שיכוון לומר שעל ידי עסק התורה יהיה בטוח מיצרו כי התורה מגנא ומצלא (סוטה כ''א) לזה אמר בכפל התנאי ואם לא תשמעו לי פירוש לי לשמי שהגם שילמדו התורה אם לא יהיה הלימוד לשמו יתברך ולא יעשו את כל המצות האלה פירוש אין מציל מיד יצר הרע ויבואו לידכם עבירות שאין מציל מהיצר אלא תורה לשמה:
@793 **עוד** ירצה שאם לא ישמעו לתורה הגם שיסכימו לעשות כל המצות הוא מן האי האפשרות כי לא יוכל השיג דעת דקדוקי המצות ופרטיהם ולא ימנע מהכשל גם על דרך אומרם ז''ל (מנחות ק''י) זאת התורה לעולה וגו' כי העוסק בתורה אפילו בזמן חורבן הבית יכול לקיים כל המצות מה שאין כן אם לא יעסקו בתורה בודאי שלא יעשו את כל המצות:
@793 **עוד** נתכוין באומרו תיבת **לי** להעיר כי אטימת אוזן מדברי תורה הוא כמי שבא לדבר עמו האדון מלך העולם וימאן לשמוע אליו והוא אומרו **ואם לא תשמעו לי** פירוש לי אין אתם רוצים לשמוע:
@793 **עוד** יתבאר הכתוב על דרך אומרם ז''ל (אלשיד איכה א') בפסוק ואותי עזבו ותורתי וגו' משל לתופש כנור וכו' ע''כ הרי שהגם שיהיו ישראל ב''מ עובדי עבודה זרה ועושים כל העבירות ויהיו עוסקים בתורה לא היה נחרב הבית והוא מה שנתחכם ה' להקדים ולומר **ואם לא תשמעו לי** אז הוא שאם לא תעשו את כל המצות ימשך לכם פורענות האמור בענין אבל אם תשמעו הגם שלא תעשו את כל וגו' יהיה דינם כתופש כנור וכו' האמור בדבריהם:
@793 **עוד** ירצה על זה הדרך לצד שיודע ה' מחשבות לב האדם ותחבולות יצר הרע וסדר כניסתו עם האדם לזה דברה תורה כנגד יצר הרע והתחיל כנגד תחילת הפיתוי והנה כבר כתבתי לך פעמים רבות כי לצד שאיש ישראל קרובים לה' לא תיכון עצתו של יצר הרע לדבר אליו עשות הרע עד שירחיקהו מעט מעט כגונב את הקטן מבית אביו שבתחילה מושכו מעט מעט כמו כן בתחילה יתחיל היצר לדבר אליו כי נכון הדבר הבא מאת ה' כל הכתוב בתורה מי כמוך יחוש לדברי ה' אבל מה שהוסיפו חכמים כמה גדרים ושמירות וענפי האיסור מי יאמר כי כן צוה הבורא, וכשיטה אזנו להרהר אחריהם יוסיף להכותו כי יאמר אליו רבים המצות האלה ממך רמ''ח מצות עשה וענפיהם ולצד היות האדם מרוחק מעט מה' יוכל יכה בו:
@793 **וכנגד** ב' פיתויים אלו אמר **ואם לא תשמעו לי** כאן מדבר על קבלת דברי חכמים והוא על דרך אומרו (דברים י''ז) והאיש אשר יעשה בזדון לבלתי שמוע וגו' ומת האיש ההוא ודקדק לומר לי על דרך כל המהרהר אחר רבו כאלו מהרהר אחר השכינה לזה אמר (סנהדרין ק''י) ואם לא תשמעו, תדע שהדבר לי הוא נוגע ועוד כי החכמים היכל ה' המה:
@793 **וכנגד** פיתוי הב' שמרבה בעיניו עול מ''ע כי רבים הם אמר **ולא תעשו את כל המצות האלה** גם נתכוון לומר שכל שאינו מאמין בדברי רבותינו בוודאי שלא יעשה אחת מכל המצות כי סדר המצות ואמיתותה הוא אשר גבלו ראשונים והמסרב לשמוע להם אין בידו אפילו אחת מכל מצות ה' ולזה לא אמר ואם לא תעשו כסדר שאמר בפסוק שאחר זה לצד שזה נמשך מאם לא תשמע ו:
@794 **ואם בחקתי וגו'**. צריך לדעת למה אמר ואם ולא סמך על ואם שאמר בתחילת הענין, עוד אומרו **בחקתי** שהיה צריך לומר ואם חקותי תמאסו כי על שלילתם לא תיכון הבי''ת כמאמר ואם את משפטי הסמוכה לה. עוד למה חזר פעם ב' לומר ואם, עוד למה לא כלל הכתוב יחד חקים ומשפטים ויאמר ואם חקתי ומשפטי תמאם או תגעל וגו', עוד למה ייחד הכתוב המאיסה לחקות וגעילת נפש למשפטים, עוד אחר שהזכיר מאיסה וגעילה מה צורך לומר לבלתי עשות ומה גם שכתב למעלה ולא תעשו את כל המצות והגם שפירשנו בו באחד מהדרכים שהוא המשך ממה שקדם אליו עם כל זה יתחייב ישוב משמעות הכתוב. עוד מה הוא כוונת אומרו להפרכם וגו':
@794 **אכן** כוונת הכתוב הוא כנגד פיתוי יצר הרע המפתה לבטל מצות לא תעשה ויתחכם להתחיל להרחיק מדעת אדם מצות שהם חוקה בלא טעם באחד מב' דרכים או יאמר אליו כי לא יאמנו הדברים שיאמר אותם אלהי עולם או יאמר לו יהיה שנאמין שאמרם אין הדברים כפשטן, ולא יכוון אל הנשמע מהם וכשיטה אדם אזנו לדברי המסית אז יוסיף לדבר אליו גם במצות שיש להם טעם במצות ה' ויהיה הנקל עוברו פי ה' בכל שהוא מטעמים פגומים שיראה לו כיון שנתרחק מהקדושה ובעבירה אשר היצר לא ימצא לה טעם יחזור להוכיח מאותם העבירות שכבר הושרש זה האדם לעבור עליהם ויאמר אליו אמור נא לי מה רע ועונש הגיעך על אשר עברת על כמה עבירות שאסרה תורה ולא יזכירהו סיבת תחילת עוברו עליהם שהיתה בטענה הנשמעת לו בהוראות היצר אליו ויתאמץ עמו בעזר תאוה הגוברת עליו ויעבור פי ה' ואחר שעבר פי ה' פעם וב' הנה יבא עוד בטענה ההוגנת לו כי יותר יקל מעליו העונש אם יהיה מומר ויכפור בכל שאז לא יענישהו למעלה אם יבא לכלל העונש אלא על עון אחד שהמיר והפר ברית שנשבע בהר סיני מה שאין כן זולת זה יהיה נענש על כל פרט ופרט:
@794 **וכנגד** הדרגות המסית בא הכתוב ואמר על ראשון ראשון שהתחיל לפתות במצות שהם חוקה **ואם בחקתי** שהם מצות שאין בהם טעם כמאמר חז''ל (במ''ר י''ט) שהשטן ואומות העולם אומרים מה מצוה זו ומה טעם יש בה לזה דקדק לומר **בחקתי** בי''ת הסיבה לומר כי לצד שהם חקות תמאסו אותן ותקבלו דברי היצר ואמר ואם לומר שהיא הדרגה אחרת שהוא ביטול גם מצות לא תעשה גם לומר שכל אחת כדאי לעצמו להביא עונש האמור בענין:
@794 **וכנגד** פיתוי ב' של היצר אמר **ואם את משפטי** שהם מצות שיש בהם טעם תגעל נפשכם וטעם ששינה מהאמור בחוקים לדרכנו יש טעם נכון כי החקים העדר הטעם הוא אשר סבב המאיסה בהם מה שאין כן משפטים ישרי טעם סיבתם היא לצד שנפשם חמדה עשות רע לא לצד שאין טעם במצוה לזה אמר תגעל נפשכם ולזה לא אמר גם כן במשפטי כמאמר בחקתי:
@794 **עוד** ירצה באומרו **תגעל** על פי מאמר החסידים בהבחנת האדם את נפשו לדעת מה היא אם עומדת בגדר טוב או נפש טמאה כי יוכר הדבר כפי תאות הנפש אשר תטה עשות יעויין דבריו בספר הישר לר''ת (שער ט') הוא מאמר תגעל נפשכם כי הנפש הרשעה תגעל קיום המצות ותבחר עשות רע לצד חלאים שבה שהוא בחינת רע כמאמר רז''ל (ברכות ס''א) רשעים יצר הרע שופטן והוא מה שגמר אומר **לבלתי עשות את כל מצותי** כי הנפש הלזו תגעל כל ענפי הקדושה ואומרו **להפרכם** כנגד פיתוי האחרון של יצר הרע שאומר אליו הפר ברית והמר כבודך להקל העונש ובא הכתוב וייעד עונש שלם בשוה גם לזה ובטל טענת המסית בפרט זה וכמאמר הנביא (יחזקאל כ''ה) הנה ככל הגוים בית יהודה וגו' והיתה התשובה לזה (שם כ ל''ג) אם לא ובחימה שפוכה אמלוך עליכם:
@794 **עוד** יתבארו הכתובים על פי דבריהם ז''ל (זוהר ח''א ק'.) ששלימות עבודת ה' הוא באמצעות ג' דברים מחשבה דיבור מעשה, לזה כשכפל ה' התנאי אמר זכרון שלשתם, כנגד הדיבור אמר **ואם לא תשמעו** כנגד עסק. התורה שהוא ההגיון, וכנגד המעשה אמר **ולא תעשו** וגו', וכנגד המחשבה אמר **ואם בחקותי** תמאסו ודבר זה ישנו במחשבה, ולצד שהמחשבה ישנה במוח ובלב לזה אמר כנגד המוח תמאסו, וכנגד הלב אמר תגעל נפשם כי הנפש הוא בלב כידוע:
@794 **עוד** אפשר שהכתוב ידבר כנגד הדרגות שיהיו בכללות עם בני ישראל והם ג' כתות, האחד הם גדולי ישראל העומדים על התורה ועל העבודה, וכנגד כת זו אמר ואם לא **תשמעו לי** וגו', כי הכת הצדיקים צריכין לדקדק במצות ה' ולקיים כל התורה, ואם יזלזלו אפילו בענף קטן הרי זה מתחייב בנפשו, וכמאמרם ז''ל (יומא פ''ו.) וז''ל היכי דמי חילול ה' כגון אנא דמסגינא ד' אמות בלא ציצית ותפילין ובלא תורה, וכנגדם אמר הכתוב **ואם לא תשמעו לי** פירוש להשתדל בעסק התורה לשמה, ולא **תעשו את כל המצות** כללותיהם ופרטותים ודקדוקיהם שחסרון מעט יחשב לזדון גדול, ויש כת אחרת שאינם בני תורה אבל הם מושכלים ויודעים הכרת הטוב והישר, כנגדם אמר **ואם בחקתי תמאסו** כי לאלו יעניש הכתוב אפילו על ביטול מצות שאין בהם טעם ויחשב להם לזדונות, אבל על ביטול הדקדוקים שנענשים עליהם גדולי ישראל לא ישיגם כמו כן העונש, ויש כת אחרת שהם הסכלים שבעם ישראל שלא תשיג ידיעתם להכריח קיום החוקים שבתורה, וכנגדם אמר **ואם את משפטי תגעל נפשכם**, כי אלו לא יענשו עונש גדול האמור בענין אלא על ביטול המשפטים שהם מוסברים לשכל אנוש, אבל על החוקים ואין צריך לומר הדקדוקים שיענשו עליהם גדולי ישראל נידונים בהם כשוגגים וכשוטים האנוסים שעונשם קל עד מאד:
@794 **לבלתי עשות**. כאן רשם ה' תנאי שלא יביא כל העונש האמור אלא אם עודם מסכימים בדעתם ללכת בדרכי הרע לבלתי עשות וגו', אבל אם דעתם לחזור, או הגם שאין דעתם לחזור אלא שהאדון ב''ה יודע שיחזרו בתשובה יאריך ה' אפו להם עד שובם אליו, ולא יביא עליהם את הרעה הכתובה:
@794 **להפרכם את בריתי**. נתכוון להתנות עוד שלא יביא כל העונש אלא לעובר להכעיס כאומרו להפרכם את בריתי, אבל לעובר לתיאבון לא יבא לכלל העונשים. ורז''ל אמרו (תורת כהנים) ואם לא תשמעו וגו' יש אדם שאינו לומד אבל עושה ת''ל ולא תעשו, יש אדם שאינו לומד ולא עושה אבל אינו מואם באחרים ת''ל בחקתי תמאסו וגו', כל שאינו לומד אינו עושה, ומואס באחרים העושים, ושונא תלמיד חכמים דכתיב תגעל נפשכם, ולבסוף אינו מניח אחרים לעשות דכתיב לבלתי עשות, ולבסוף כופר בעיקר דכתיב להפרכם וגו' ע''כ, הנה לדבריהם ז''ל לא יבא עונש האמור אלא עד שיגיעו לגדר האחרון שכופר בעיקר, וטעם שלא אמר הכתוב גדר האחרון לבד, בא להודיע סיבת הסיבות שתסובב לאדם לבא למדה זו האחרונה, וממשמעות הדברים תשכיל כי בהכשל בראשונה יתגלגל וירד מטה מטה עד מדה האחרונה ומעתה יובן מאמר הנביא (ידמי' ט') על מה אבדה הארץ על עזבם את תורתי שהיא סיבה הראשונה שממנה יצאו כל פרטים הרעים רח''ל:
@795 **אף אני וגו'**. פירוש גם מדת הרחמים תסכים על הקללות עם מדת הדין:
@795 **והפקדתי וגו' השחפת וגו'**. בחר ה' במין קללות אלו כנגד מדתם של הרשעים, ולצד שעיקר עונם היא מניעת עסק התורה מדד להם במדה עצמה, והנה התורה נמשלה לאש דכתיב (ירמי' כ''ג) הלא כה דברי כאש, ודע כי התורה תסגל ג' מעלות טובות בנפש אדם, הא' מבאמצעות עסקה להיותה אש מצרפת הנפש ומטהרת אותה לבל תצטרך לרדת שאול לצרפה, ולזה אין אור של גיהנם שולט בהם (חגיגה כ''ז.) כי אשה גדול מכח אש גיהנם ואין תחלואי הנפש שבהם שולט אור של גיהנם, ולזה גיהנם צועק בהרע אין לי חפץ בצדיקים וכו' (שמו''ר ז') שהם מתישים כחה ומכבים אשה, והמעלה הב' שמאירה העינים, כי יש לך לדעת כי צריך אור גדול לעיני כל ישראל כדי שיוכלו ליהנות מזיו השכינה למעלה, והאדון באהבתו אותנו נתן לנו התורה שנקראת אור דכתיב (משלי ו') ותורה אור, כדי שבאמצעותה יגדל כוח אור עינינו, כי כפי גודל אור שבעינים כפי המושג בהביט אל האלהים, ולכל שלא האירו בתורה יקרא להם נביא ה' (ישעי' מ''ב) והעורים הביטו לראות, והמעלה הג' כי דברי תורה משמחי לב דכתיב (תהלים י''ט) פקודי ה' ישרים משמחי לב, וכתיב (שם צ''ז) ולישרי לב שמחה, וכנגד ג' מעלות אלו אמר ה' עונש מכוון לעוזבי ה', כנגד מה שמאנו לעסוק בתורה שהיא אש הקדושה יפקיד ה' עליהם שחפת וקדחת, גם הזכיר **בהלה** שהוא הפך המושג מעסק התורה שהוא ישוב השכל והתכוננות הדעת, וכנגד מאור עינים אמר **מכלות עינים**, וכנגד שמחת הלב אמר **ודאבון גפש**, ואמר **וזרעתם לריק** כנגד הצלחת העולם הזה:
@795 **גם** ירמוז להצלחת עולם העליון על דרך אומרם ז''ל (עוקצין פ''ג) עתיד הקדוש ברוך הוא להנחיל לכל צדיק וצדיק שלש מאות ועשר עולמות, ודבר ידוע הוא שכל הדרגות יעודי שכר הטוב לצדיקים יש כנגדם עונשי הרשעים כאומרו (קהלת ז') גם זה לעומת זה עשה האלהים, וכשם שיש הדרגות השלש מאות ועשר יעודי הכשרים כנגדם שלש מאות ועשר טינופי היסורין לעושי רשעה ויקראו קרי ריק שעולה בהם שלש מאות ועשר, והוא מאמר **וזרעתם לריק** במקום להנחיל אוהבי י''ש יהיה לבחינת הרע ריק שהם כנגד מספר בקליפה, ואמר לשון זריעה כי יתייחס גם למפעלות לשון זה, על דרך אומרו (הושע י') זרעו לכם לצדקה וגו' ואומרו **ואכלוהו אויביכם** כי הקליפות נהנים ממעשה הרשעים, ויודיע הכתוב שהקליפות הם אויבי איש:
@796 **ונתתי פני וגו'**, הם פני זעם, וטעם קריאת הדין פנים, לצד שתמיד עומדים לפני ה' כת המשמאילים שהם כת המשחיתים לזה יקראו פני ה', ועליהם אמר ונתתי פני ובזה ונגפתם לפני אויביכם הם האומות שהם ענפי כוחות הקליפה, גם נתכוין במאמר **פני** לומר שלא יסתיר פניו מהם כשימסרם ביד אויביהם שאם כן הם ח''ו מכלים את הכרם, והוא גילה רצונו יתברך בסוף הענין ואף גם זאת וגו' לא מאסתים לכלותם וגו', ואמר בכם למעט בית המקדש שלא תשלוט בו מדת הדין תחלה:
@797 **לא תשמעו לי**. תלה הדבר בשמיעה שהיא התורה, כי הנמנע שיחזרו בתשובה זולת על ידי התורה:
@797 **שבע על חטאתיכם**. פירוש לשיעור חטאתם שהם שבע מדה כנגד מדה, ואלו הם ז' עבירות, א' לא שמעו, ב' לא עשו, ג' בחקותי מאסו, ד' משפטי השם געלו, ה' מונעים אחרים בלתי עשות, ו' הפרו ברית ואחר שיסרם ה' בלתי עשות ו' הפרו ברית, ואחר שיסרם ה' ולא שמעו לו וסגרו שערי התשובה הרי ז', ולטעם זה אנו מישבים מאמרם ז''ל שאמרו (ר''ה ט''ז:) ג' ספרים נפתחים בראש השנה כו' בינונים תלויים וכו' עד יום הכפורים וכו' ע''כ, פירוש לצד שתלה ה' להם לעשות תשובה ולא עשו הוכרע משקלם כרשעים:
@798 **ושברתי את גאון עזכם**. אמרו ז''ל (תורת כהנים) זה בית המקדש שנקרא כן, והכונה בזה כיון שלא חזרו בתשובה זה יורה שחושבים בדעתם כי ה' חפץ בהם עדיין ממה שעודו שוכן בתוכם ובזה מתחזקים לזה אמר ושברתי וגו':
@799 **ותם לריק וגו'**. כאלו אמר ותם כחכם לריק פירוש שכחם בשלימות יהיה לריק, ולצד שלפעמים לא ישלוט המשחית אלא בחלק כאן הודיע (ה') כי ישלטו בכל ר ח '' ל:
@800 **ואם תלכו עמי קרי**. לצד שמכות אלו הם מכות המרגישות ומכירות השגחה כי ה' מיסר אותם, וכשאין חוזרים בתשובה אין מענה אלא לומר קרי הוא זו:
@800 **שבע כחטאתיכם**. הגם שלא הרשיעו בעבירות חדשות אף על פי כן כיון שלא חזרו אחר היסורין יחשב להם כעושים מחדש:
@801 **חית השדה**. כשם שהם עשו מעשה בהמות שלא הרגישו להערת מלכם תבא חית השדה ותעשה מעשיה בהם:
@803 **והלכתי וגו' בקרי**. פירוש שלא יביא עליהם יסורים מכוונים על חטאתם כמו שעשה מקודם שהיה מביא כחטאתם על דרך אומרו (תהלים ס''ב) תשלם לאיש כמעשהו, כי זה יעורר לב נרדם וישכילו להטיב מעשיו שכנגדם באה אליו הרעה, ואמר ה' כי אם ילכו עמו בקרי ולא ישכילו למעשה ה' אשר יעורר לבם בכיוון יסורין כנגד עונותיהם גם הוא ילך עמהם בקרי ויביא עליהם יסורין שאין להם דמיון למעשיהם הרעים והם חרב ומצור ודבר וסגירה ביד אויב ורעב שכולל ג' צרות הרי ז':
@808 **ואכלתם בשר בניכם וגו' תאכלו**. טעם שכפל לומר תאכלו פעם ב' לומר שאפילו אחר שכבר אכלו לא יכמרו רחמיהם כדרך הרגיל להנחם אחר מעשה ויכמרו רחמיהם ויבכו הוי בני הוי בתי אלא עוד יסכימו לאכול אם ימצאום מחדש:
@808 **או** ירצה כי יקדימו לאכול הבנים, והטעם לצד שנותנים עיניהם לאכול גם הבנות לזה יקדימו הבנים שיש בהם ספק שימאנו ויברחו בראות הבנות נאכלות מה שאין לחוש כמו כן בבנות כי אין כח בהם כזכרים, והוא אומרו **ואכלתם בשר בניכם** וטעם הקדמת הבנים ולא הבנות לא לצד שאין דעתכם לאכול הבנות אלא תוסיפו גם כן לאכול בשר בנותיכם ואתם מקדימין הבנים שיש לחוש לטעם מורגש:
@808 **או** יאמר על זה הדרך כי לצד שרחמי האב על הבנים יותר מהבנות (רש''י שבת ס''ו:) לזה הם מתחכמין לאכול הבנים תחלה כדי שבזה יהיה נקל להם לאכול הבנות, וזה שיעור הכתוב **ואכלתם בשר בניכם** וטעם הקדימה כדי **שבשר בנותיכם תאכלו** פירוש לא יכאב לבבכם כפי מה שקדם ויהיה לכם כמאכל הרגיל:
@809 **וגעלה נפשי וגו'**. צריך לדעת למה הוצרך לומר כי פשיטא שתגעל נפשו שהרי בזמן שהם צדיקים גמורים נתברכו שלא תגעל נפשו והדבר מובן שלא תהיה ברכה זו נוהגת בימי רשעם, ואם בא לומר הפכיות הברכות, היה לו לומר הפכיות כל השאר, אלא ודאי שלא אמר אלא העונשים שהם לבד העדר הברכות, ונראה שנתכוין לומר שאפילו בערך הצדיקים שיהיו בזמן ההוא תגעל נפשי מהם בסוד (הושע ד') וכשל גם נביא עמך, גם נתכוון שלא יתנבאו עוד בישראל נביאים כי לא יופיע ה' שכינתו המתיחס לה בחינת נפש בהם, וקללה זו אין קללה למעלה ממנו, ולזה קבעה אחר כמה קללות, הא למדת שהיא גדולה ממה שלפניה, והיא שנתקיימה בזמן הזה ולה כלו עינינו ודאבה מאוד נפשנו אוי נא לנו:
@810 **ונתתי את עריכם חרבה**. פירוש אפילו ישוב כשאר עיירות לגוים לא תהיה, וזה עגמת נפש גדול גם זה יגיד ב''מ כליון התקוה ציון מדבר היתה וגו' (ישעי' ס''ד) כל זמן שישראל לא יטיבו דרכיהם:
@810 **והשמותי וגו'**. פירוש השראת הטומאה ושימת שכונתה בבית המקדש, כי הקליפה תקרא שממון, וכבר הודיעו המקובלים כי שם הרגיעה שידה ורגל ס''מ דורכת על בית ה', אשר על זה יקרעו לבם ותערג נפש כל חי למול בעל הבירה:
@810 **ולא אריח וגו'**. פירוש שלא יתרצה במעשיהם הטובים שגם להם יתיחס ריח ניחוח, וכמו כן אמר ירמיה (איכה ג') שתם תפלתי:
@811 **והשמותי אני**. אמר אני פירוש מדה זו ה' בכבודו יעשנה, והטעם כי היא מדה טובה כמאמר רז''ל (תורת כהנים) שלא ימצאו אויבים נחת רוח:
@812 **ואתכם אזרה וגו'**. יתבאר הכתוב על דרך אומרם ז''ל במסכת כתובות (קי''א.) שהשביע ה' את ישראל ג' שבועות, א' שלא יעלו בחומה פירוש ביד חזקה, ואחד שלא ימרדו באומות העולם וכו' ע''כ, והוא מאמר **ואתכם אזרה בגוים** כאן רמז לב' דברים, אומרו **אזרה** שלא יעלו בחומה, בגוים שלא ימרדו בגוים, ואומרו **והריקותי אחריכם חרב** יתבאר על דרך שגמר שם וז''ל אמר להם הקדוש ברוך הוא לישראל אם אתם מקיימין השבועה מוטב ואם לאו אני מתיר את בשרכם כצבאות וכאילות השדה ע''כ, והוא אומרו **והריקותי אחריכם חרב** שתהיה חרב מרוטה לפניכם אם לא תקיימו גזירת זרוי בגוים כנזכר יהיה בשרכם וגו', ואומרו עוד **והיתה ארצכם** וגו' חרבה הוא נתינת טעם על הדבר למה יחפוץ ה' בזרוי בגוים כדי שתהיה ארץ שממה וערים חרבות כדי שאז תרצה הארץ וגו', לזה צריך שתהיו אתם בארץ אויביכם, והוא אומרו ואתם וגו':
@815 **והנשארים בכם וגו'**. פירוש אותם שישארו אחר כל זה ברשעם ולא חזרו בתשובה, כדרך שאמר למעלה ואם תלכו עמי קרי וגו' כמו כן אמר והנשארים בכם פירוש בתכונה הראשונה אוסיף בהביא להם מורך וגו' **ונפלו** וגו', **והנשארים** וגו' פירוש שלא חזרו כו' אחר כל זה ימקו וגו', וממוצא דבר אתה יודע שהגם שתבא להם כליון אחר כליון לא תכלה האומה כמאמרו לבסוף לא מאסתים לכלותם:
@819 **והתודו את עונם וגו'**. ראשונים לא האירו עינינו בכתובים הללו כי כולן רחוקים משמוע, אחד למה חייבם הכתוב להתודות עון אבותם הלא בהתודות עונם אין אני קורא עליהם אוחזים מעשה אבותיהם בידיהם (כרכות ז'.) ב' אומרו אף אני אלך עמם וגו' מה ענין עונש זה אחר הוידוי, ג' אומרו והבאתי אותם וגו' עונש זה כבר אמור למעלה, ד' אומרו **או אז יכנע** ספק זה למה. ורמב''ן ז''ל פירש שהספק הוא על הגאולה או תבא על ידי כניעה או עד שיקבלו עונשם, והוא פירוש דחוק, וכמו כן מה שפירש אדונינו רש''י ז''ל הוא דחוק לעין רואה ולב משכיל:
@819 **ונראה** לפרש הכתובים על זה הדרך כי לצד שטעות מתמידי העבירות תבא להם מעין טועה בראותם מה שלפניהם התעיבו עול שנה אחר שנה ודרכם צלחה ושלותם רב לאין חקר אף כי חטאתם כבדה מזה לא יפחד עשות רשע וימאן לקחת מוסר, כי יגדל ביחון הראות מהודעת המוכיח מיעודי התורה, ודבר זה כילה אמונת עם בני ישראל בעונש הרשע ושכר הצדק, וכמו כן הנה עם בני ישראל לא הביא ה' עליהם מוסר עד אשר עונות ראשונים גברו ועלו למעלה ראש ושלוותם וטובתם רבה ועצמה כמובן מדברי נביאים, ולזה כשפעל ה' ועשה בהם נקמת עונותם לא האמינו כי על פועל הרע שילם להם ויוכיחו מהראשונים, לזה אמר ה' בעת שובם ויבואו להתודות צריכין להתודות גם כן כי אבותיהם חטאו:
@819 **והוא** אומרו והתודו עונם וגו' ואת עון אבותם כדי להסיר טעות שהיו בו שאין זה מעשה רעה ממה שעשאוהו ראשונים ולא נענשו, ויאמרו בפיהם אבותינו חטאו והרשיעו ואנחנו עונותיהם סבלנו לצד שאחזו מעשה אבותיהם בידיהם, ואומרו **ואף אשר** וגו' פירוש כי מחשבת טעות זה שהעונשים היו באים בקרי יחשבהו ה' עון שצריך וידוי עליו כשאר עבירות:
@820 **ואומרו אף אני וגו'**. פירוש גם זה יאמרו בכלל הוידוי כי צדיק ה' על כל הבא עליהם, וכן ראוי למשפט צדק לילך עמם בקרי ולא יעול האל משפט:
@820 **ואומרו והבאתי אותם וגו'**. פירוש גם זה יאמרו בכלל הוידוי, והנה ממה שמצריכם ה' להתודות עליו אתה יודע שהם היו מרשיעים בפרט זה, והרשע הוא כי יאמרו למה ה' יוציאם מארצם ויגלם בין האומות, אם לפירעון עונם ייסרם תוך ארצותם ולא יגלם בין האומות, כי אדרבה זה יסובב הפך תיקון המבוקש שאם המבוקש הוא להטיב מעשיהם והנה כשיזרה אותם בארצות יגמרו לעשות רע ויתערבו בגוים וילמדו מעשיהם, וזה יחזק מחשבת קרי, לזה כשאמר ה' והתודו זכר שיאמרו גם כן בוידוים כי צדיק ה' במה שהלך עמהם קרי, ולאותו הטעם ולאותו המבחן הביאם בארץ אוביהם כדרך מעשה המקרה בלא כיון אל הצריך:
@820 **ואומרו או אז**. פירוש שיתלו טעם הבאתם בארץ אויביהם לצד הליכה, או לטעם כדי שיכנע לבבם הערל לזה הביאם בארץ אוביהם מה שלא היה נכנע באופן אחר זולת זה, שבזה יהיה להם הרווחה נכונה, שעל ידי הכנעה לבד ירצו את עונם ולא יצטרכו למירוק אחר על דרך אומרו (מ''א כ''א) הראית כי נכנע אחאב, ואמרו ז''ל (ברכות ז'.) טובה מרדות אחת בלבו של אדם ממאה מלקיות, והוא אומרו אז יכנע וגו' ואז ירצו את עונם:
@821 **ואומרו וזכרתי וגו'**. פירוש כי הוידוי יועיל להקל מעליהם הגזירות הרעות אבל להשיבם לכנם צריך זכות אבות, והוא אומרו וזכרתי:
@821 **עוד** ירצה לומר שזה תוספת טעם לגלות בארץ אויביהם, כי על ידי כן יעלה זכרון ברית אבות ויזכור אותם לרחמים מה שלא היה כן זולת זה, גם תהיה להם זכירת הרחמים כשישתתף עמהם זכרון הארץ, וזולת הגלותם בארץ העמים אין צורך לזכרון הארץ לזוכרה עמה והוא אומרו **וזכרתי** וגו' והארץ אזכור, והוסיף עוד לומר **והארץ תעזב מהם**, טעם אחר לגלות, כי בזה גם כן תרץ הארץ שבתותיה מה שלא היה כן בלא גלות:
@821 **בריתי יעקוב ואף את וגו'**. פירוש אם תספיק זכות יעקב מה טוב ואם לאו אוסיף מה שלמעלה ממנה שהיא ברית יצחק ואם לא תספיק אצרף מה שלפניו ברית אברהם:
@822 **והארץ תעזב וגו' יען וביען וגו'**. אומרו יען וביען על דרך אומרו (ירמי' ט') על מה אבדה הארץ על עזבם את תורתי ואמרו ז''ל (ב''מ פ''ה:) דבר זה נשאלה וכו' עד שבא הקדוש ברוך הוא ופירשה ויאמר ה' על עזבם את תורתי, פירוש השאלה היא שאם ישראל חטאו ארץ מה חטאה שאבדה שהיה לו לבעל הדין ליפרע מהם ולא תחרב הארץ וחורבתה היא ביציאת בניה מתוכה ויבואו בה ערל וטמא שהוא אבדן הארץ, ויאמר ה' על עזבם את תורתי, הרי שיציאת ישראל מארץ ישראל היא לסיבת מניעת התורה, כי לצד שאין תורה אין חשק לארץ בישיבתם בה, ומצינו עוד שאמר הכתוב למעלה מזה אז תרצה וגו' ותרץ את שבתותיה, הרי כי לסיבת עון השמיטה תאבד הארץ מהם, מעתה הם ב' טעמים ליציאת ישראל מארץ הקדושה:
@822 **לזה** אמר יען וביען, וחזר ופירש מה הם הב' סיבות ואמר **במשפטי מאסו** הם השמיטות, **וחקתי געלה נפשם** היא עסק התורה, כמו שאמר בתחלת הפרשה אם בחקתי ופירשוה על עסק התורה, וממוצא דבר אתה יודע כי צריכין ב' הסיבות, שאם היו עוסקים בתורה היו מתיסרים באופן אחר ותתרצה הארץ בביטול השמיטה לצד תועלת התורה הנשמעת בה, ואם היו מקיימין מצות השמיטה הגם שלא היו עוסקין בתורה היה ה' מיסרם באופן אחר ולא היו גולין, ובהצטרף ב' יצא הדין להביא אותם בארץ אויביהם שאמר בתחילת הענין:
@823 **ואף גם זאת בהיותם וגו'**. צריך לדעת איך יוצדק ואף גם זאת שהוא ענין הטבה עם מה שקדם לו בענין היסורין והצרות, ואולי שחוזר לתחלת הענין שהזכיר עונותם והליכתם במקרה עם ה' אף על פי כן לא מאסתים וכו':
@823 **עוד** יתבאר על דרך מה שפירשתי במה שקדם כי ה' נותן טעם להקפדת כל חכם לב למה יגלה ישראל מארצו ולא שם לו שם בארץ עצמה משפט תט אשורם מני אורח, עוד הוסיף לומר **אף גם** טעם זה, והוא באמצעות הבאתם **בארץ אויביהם** ותעזב הארץ מהם **לא מאסתים** וגו' **לכלותם**, על דרך אומרם ז''ל (מדרש תהלים ע''ט) כי ה' השליך חמתו על עצים ועל אבנים למלט עם בני ישראל כמזמור לאסף באו גוים וגו' שמו את ירושלים לעיים וגו' שהיה מזמר על הדבר, גם יסובב רחמיו ותכבש מדת הדין בראות עם עליון בני מלכים שפלים ביד אויביהם, וזה יסובב שפלם שלא תכלה אותם מדת הדין, והוא אומרו **ואף גם זאת** סיבה להבאתם **בארץ אויביהם** שבהיותם בארץ אויביהם **לא מאסתים** וגו' **לכלותם**, ולצד זה בחרתי בעונש כזה:
@823 **להפר** בריתי אתם. ברית זו היא שלא יחליפם באומה אחרת שקיים ה' כן במאמרו ליוצאי מצרים, והוא מה שגמר אומר **כי אני ה' אלהיהם** פירוש זאת אות הברית אלהיהם ולא אלהים לאומה אחרת, גם מאמרו בשעת מתן תורה שיהיו עם סגולה מכל העמים וממלכת כהנים ומאמר ה' הוא במקום ברית:
@823 **עוד** נראה שכוונת הכתוב היא על זה הדרך **לא מאסתים** וגו' **לכלותם** והטעם הוא לצד בריתי אתם, וחזר ופירש מה הוא הברית **כי אני ה' אלהיהם** זה הוא הברית שהופר אם אכלה אותם כי אין מקיים ברית ה' שיהיה להם לאלוה אשר נתחייבו הם לקיימו:
@823 **גם** ירצה על התורה שנקראת ברית שאם אין ישראל התורה שנתן ה' להם והיא אתם עמם הופרה:
@824 **ואומרו וזכרתי להם ברית וגו'**. רבותינו ז''ל אמרו (תורת כהנים) וז''ל מנין שברית כרותה לשבטים דכתיב וזכרתי וגו' ברית וגו' אשר הוצאתי וגו', ואפשר לומר שנתכוון על דרך אומרו (ירמי' ב') זכרתי לך חסד נעוריך אהבת וגו', וכמו כן אמר כאן וזכרתי וגו' פירוש שיזכור ה' לדור האחרון זכות דור ראשון שנכנס בברית עם ה' באהבה רבה, ופירש מי הם הראשונים בעל ברית ואמר אותם שהוצאתי אותם וגו' ונתקדש באמצעותם אלהים חיים:
@824 **חסלת פרשת בחוקתי**, **סליק ספר ויקרא**
